--
-- Name: applicationnumber(character varying, character varying, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.applicationnumber(_bookname character varying, _finalregistrationno character varying, _presentyear text) RETURNS TABLE(application_number character varying)
    LANGUAGE plpgsql
    AS $$
begin 
	return query
	select d.applicationnumber as Application_Number  from kaverimrg.documentmaster d 
	left join kaverimrg.booktypemaster b on d.bookid = b.bookid 
	left join kaverimrg.scannedfileuploaddetails s on d.documentid = s.documentid 
	where b.booknameenglish=_bookname and d.finalregistrationnumber=_finalregistrationno and extract(year from d.presentdatetime)::varchar=_presentyear;
	
end;
$$;


ALTER FUNCTION kaverimrg.applicationnumber(_bookname character varying, _finalregistrationno character varying, _presentyear text) OWNER TO postgres;

--
-- Name: dashboardinfoinsert(); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.dashboardinfoinsert()
    LANGUAGE plpgsql
    AS $$

begin
	
	truncate table kaverimrg.feedashboarddetails;
	
	insert into kaverimrg.feedashboarddetails(feesname,feerulecode,feesamount,lastrefreshdate)
	 select feesname, feerulecode, feesamount, CURRENT_TIMESTAMP from kaverimrg.vw_fees_landingpage;
	
	truncate table kaverimrg.applicantdashboarddetails;
	
	insert into kaverimrg.applicantdashboarddetails(applicationtypeid, applicationtypename, bookid, bookname, cnt_totalapplication, lastrefreshdate)
	Select applicationtypeid, applicationtypename, bookid, bookname, cnt_totalapplication, CURRENT_TIMESTAMP from kaverimrg.vw_cnt_totalapplication; 

	 update kaverimrg.citizenloginloginfo set isactive=false,ismultilogin=false where isactive=true and ismultilogin=true and logindatetime::time> interval '0 hours 30 minutes';--'00:30:00'--limit 10
	update kaverimrg.citizenmaster set forgotpasswordcount = 0 where forgotpasswordcount >=1;
	update kaverimrg.departmentloginloginfo set isactive=false,ismultilogin=false where isactive=true and ismultilogin=true and logindatetime::time> interval '0 hours 30 minutes';--'00:30:00'--limit 10
	update kaverimrg.citizeotpdetails set otp =0, otpcount=0 where otpcount>=5;
	
end;
$$;


