CREATE FUNCTION kaverimrg.f_citizen_master(_loginname text, _firstname text, _middlename text, _lastname text, _gender integer, _email text, _phone bigint, _password text, _secquestion integer, _secanswer text, _isloggedin character, _lstupdusr text, _lstupddt timestamp without time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
id_val bigint;
x bigint;
y bigint;
_citizenid bigint;
z bigint = -1;
begin
select count(1) into x from kaverimrg.citizenmaster where lower(loginname) = _loginname;
select count(1) into y from kaverimrg.citizenmaster where lower(email) = _email and phone=_phone;
if (x = 1 ) then
_citizenid=0;
return _citizenid;
elseif (y = 1 ) then
_citizenid=0;
return _citizenid;
else
INSERT INTO kaverimrg.citizenmaster(loginname,firstname,middlename,lastname,gender,email,phone,password,secquestion,secanswer,isloggedin,
                                  lstupdusr,lstupddt)
   VALUES
 	(_loginname,_firstname,_middlename,_lastname,_gender,_email,_phone,_password,_secquestion,_secanswer,_isloggedin,
             _lstupdusr,_lstupddt);
    select citizenid into _citizenid from kaverimrg.citizenmaster where loginname = _loginname;
	return _citizenid;
	end if;
exception
 WHEN unique_violation then
 raise notice 'duplicate user';
   end
$$;


