--
-- Name: fetch_certificationpath(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fetch_certificationpath(_applicationnumber character varying) RETURNS TABLE(firmdigsignpath character varying)
    LANGUAGE plpgsql
    AS $$


declare
BEGIN
return query
	 select f.firmdigsignpath  from kaverimrg.firmmaster f where f.applicationnumber=_applicationnumber
	 union
	select f2.firmdigsignpath   from kaverimrg.firmamendment f2 where f2.applicationnumber=_applicationnumber
	
	union 
	
  select f2.firmdigsignpath   from kaverimrg.firmreconstitution  f2 where f2.applicationnumber=_applicationnumber
union 
  select f3.firmdigsignpath   from kaverimrg.firm_dissolution  f3 where f3.applicationnumber=_applicationnumber;

	
	 
END;
$$;


ALTER FUNCTION kaverimrg.fetch_certificationpath(_applicationnumber character varying) OWNER TO postgres;

