--
-- Name: fn_accept_anywhere_reg(bigint, integer, bigint, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_accept_anywhere_reg(_srocode bigint, _bookid integer, _propertyid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
regDetail record;
prty record;
prpty record;
v_documentid bigint;
BEGIN	
	--Insert to DocumentMaster
	for regDetail in (select * from kaverimrg.documentmaster d where d.applicationnumber = _oldApplicationNumber) loop
		insert into kaverimrg.documentmaster (
			documentid,
			srocode, 
	 		bookid,
			regarticlecode,
	 		presentdatetime, 
			executiondatetime, 
			applicationnumber, 
			verified, 
			issroapproved
		) values (
			nextval('kaverimrg.document_seq'),
			_srocode, 
			5,
			regDetail.regarticlecode,
			current_timestamp, 
			regDetail.executiondatetime, 
			_newApplicationNumber, 
			true, 
			'E'
		 ) returning documentid into v_documentid;
	end loop;
	
	--Insert To PartyInfo
	for prty in (select * from kaverimrg.partyinfo p where p.applicationnumber=_oldApplicationNumber) loop
		insert into kaverimrg.partyinfo(			
			srocode,
			documentid,
			partytypeid,
			firstname,
			middlename,
			lastname,
			address,
			age,
			sex,
			isexecutor,
			ispresenter,
			relationship,
			relativename,
			epic,
			pan,
			phonenumber,
			availableextacre,
			availableextgunta,
			availableextfgunta,
			bincom,
			category,
			dateofdeath,
			fingerid,
			fingerverificationstatusid,
			landcode,
			mainownerno,
			ownerno,
			partypoa,
			photopath,
			poapresentation,
			profession,
			section88exemption,
			thumbpath,
			totalextacre,
			totalextgunta,
			totalextfgunta,
			transactextacre,
			transactextgunta,
			transactextfgunta,
			salutationid,
			isorganization,
			organizationid,
			applicationnumber,
			verified,
			issroapproved,
			districtcode,
			talukcode,
			hoblicode,
			villagecode, 
			tanno,
			housenumber,
			propertyid, 
			propertynumber, 
			idprooftypeid,
			isconsentwitness,
			isprivateattendance 
		) values (
			_srocode,
			v_documentid,
			prty.partytypeid,
			prty.firstname,
			prty.middlename,
			prty.lastname,
			prty.address,
			prty.age,
			prty.sex,
			prty.isexecutor,
			prty.ispresenter,
			prty.relationship,
			prty.relativename,
			prty.epic,
			prty.pan,
			prty.phonenumber,
			prty.availableextacre,
			prty.availableextgunta,
			prty.availableextfgunta,
			prty.bincom,
			prty.category,
			prty.dateofdeath,
			prty.fingerid,
			prty.fingerverificationstatusid,
			prty.landcode,
			prty.mainownerno,
			prty.ownerno,
			prty.partypoa,
			prty.photopath,
			prty.poapresentation,
			prty.profession,
			prty.section88exemption,
			prty.thumbpath,
			prty.totalextacre,
			prty.totalextgunta,
			prty.totalextfgunta,
			prty.transactextacre,
			prty.transactextgunta,
			prty.transactextfgunta,
			prty.salutationid,
			prty.isorganization,
			prty.organizationid,
			_newApplicationNumber,
			prty.verified,
			prty.issroapproved,
			prty.districtcode,
			prty.talukcode,
			prty.hoblicode,
			prty.villagecode, 
			prty.tanno,
			prty.housenumber,
			prty.propertyid, 
			prty.propertynumber, 
			prty.idprooftypeid,
			prty.isconsentwitness,
			prty.isprivateattendance 
		);
	end loop;
	
	--Insert To PropertyMaster
	for prpty in (select * from kaverimrg.propertymaster p where p.applicationnumber = _oldApplicationNumber) loop 
		insert into kaverimrg.propertymaster (
			propertyid, 
			documentid, 
			villagecode,
			regsrocode,
			srocode,
			totalarea,
			unitid,
			northboundary,
			southboundary,
			eastboundary,
			westboundary,
			landmark,
			marketvalue,
			assessment,
			stampduty,
			consideration,
			additionalduty, 
			cessduty,
			govtduty,
			isexempted,
			exemptiondescription,
			ismovableproperty,
			applicationnumber,
			verified,
			issroapproved,
			stamparticlecode,
			stampruleid,
			regarticlecode,
			propertytypeid,
			noofscanpages,
			roadcode,
			sfdastamparticlecode,
			sfdastampruleid,
			sfdanoofscanpages,
			srostamparticlecode,
			srostampruleid,
			sronoofscanpages,
			sfdamarketvalue,
			sromarketvalue,
			ownedarea,
			sfdanatureofdocument,
			sronatureofdocument,
			transferliabilities
		) values (
			nextval('kaverimrg.propertymaster_seq'),
			v_documentid, 
			prpty.villagecode,
			_srocode,
			_srocode,
			prpty.totalarea,
			prpty.unitid,
			prpty.northboundary,
			prpty.southboundary,
			prpty.eastboundary,
			prpty.westboundary,
			prpty.landmark,
			prpty.marketvalue,
			prpty.assessment,
			prpty.stampduty,
			prpty.consideration,
			prpty.additionalduty, 
			prpty.cessduty,
			prpty.govtduty,
			prpty.isexempted,
			prpty.exemptiondescription,
			prpty.ismovableproperty,
			_newApplicationNumber,
			prpty.verified,
			prpty.issroapproved,
			prpty.stamparticlecode,
			prpty.stampruleid,
			prpty.regarticlecode,
			prpty.propertytypeid,
			prpty.noofscanpages,
			prpty.roadcode,
			prpty.sfdastamparticlecode,
			prpty.sfdastampruleid,
			prpty.sfdanoofscanpages,
			prpty.srostamparticlecode,
			prpty.srostampruleid,
			prpty.sronoofscanpages,
			prpty.sfdamarketvalue,
			prpty.sromarketvalue,
			prpty.ownedarea,
			prpty.sfdanatureofdocument,
			prpty.sronatureofdocument,
			prpty.transferliabilities
		); 
	end loop;
	
	update kaverimrg.anywhere_reg_log set 
		isjurisdictionsroaccepted = true, memoaccepteddatetime = current_timestamp, newapplicationnumber = _newapplicationnumber
	where propertyid=_propertyid;
	
return v_documentid;
END;
$$;


ALTER FUNCTION kaverimrg.fn_accept_anywhere_reg(_srocode bigint, _bookid integer, _propertyid bigint, _oldapplicationnumber character varying, _newapplicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_add_dept_user(integer, text, integer, integer, integer, integer, text, text, text, bigint, integer, text, text, text, text, text, text, boolean, integer, text, text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_add_dept_user(_employeetypeid integer, _officialemailid text, _officeid integer, _districtcode integer, _srocode integer, _rollid integer, _firstname text, _middlename text, _lastname text, _phoneno bigint, _identityprooftype integer, _idproofnumber text, _idproofpath text, _panno text, _leftthumbpath text, _rightthumbpath text, _photopath text, _isactive boolean, _createdby integer, _password text DEFAULT NULL::text, _kgid text DEFAULT NULL::text, _doj timestamp without time zone DEFAULT NULL::timestamp without time zone, _serviceexpdate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$




DECLARE
v_userid bigint;
v_count integer;
v_srocode integer;
v_officetypeid integer;
BEGIN 

	 select officetypeid into v_officetypeid from kaverimrg.mas_officemaster mo where officeid=_officeid;
	if v_officetypeid<3 then 
	select srocode into _srocode from (select srocode from kaverimrg.sromaster where districtcode=_districtcode limit 1)temp;
	
	end if;
	select count(*) into v_count from kaverimrg.departmentusers where emailid=_officialemailid or  mobileno=_phoneno;
if v_count=0 then 
   insert into kaverimrg.departmentusers(userid,employeetypeid,emailid,officeid,districtcode,srocode,designationid,firstname,
   middlename,lastname,mobileno,serviceflag,passwd,kgid,doj,serviceexpdate,loginname,createdby,status)
   values(nextval('kaverimrg.deptuserid_seq'::regclass),_employeetypeid,_officialemailid,_officeid,_districtcode,
   _srocode,_rollid,_firstname,_middlename,_lastname,
   _phoneno,_isactive,_password,_kgid,_doj,_serviceexpdate,_officialemailid,_createdby,1)
   returning userid into v_userid;
   
   insert into kaverimrg.departmentusers_biometrics(userid,uploadphoto,pan,status,uploadthumbleft,uploadthumbright,identityprooftype,idproofnumber,idproofpath,createdby)
   values (v_userid,_photopath,_panno,_isactive,_leftthumbpath,_rightthumbpath,_identityprooftype,_idproofnumber,_idproofpath,_createdby);
 
 end if;
   
   													

 
return v_userid;
END;

$$;


ALTER FUNCTION kaverimrg.fn_add_dept_user(_employeetypeid integer, _officialemailid text, _officeid integer, _districtcode integer, _srocode integer, _rollid integer, _firstname text, _middlename text, _lastname text, _phoneno bigint, _identityprooftype integer, _idproofnumber text, _idproofpath text, _panno text, _leftthumbpath text, _rightthumbpath text, _photopath text, _isactive boolean, _createdby integer, _password text, _kgid text, _doj timestamp without time zone, _serviceexpdate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_add_designation_role(integer, character varying, text, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_add_designation_role(_createdby integer, _designame character varying, _desigdescription text, _isactive boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_designationid integer;
v_count integer;

BEGIN 

select count(*) into v_count from  kaverimrg.desigmaster where designame=_desigdescription;
	
	if v_count>0 then 
	  
		v_designationid=0;
	ELSE
	
	 insert into kaverimrg.desigmaster(designationid,designame,desigdescription,isactive,createdby)
	 values(nextval('kaverimrg.designationid_seq'::regclass),_designame,_desigdescription,_isactive,_createdby)
	 returning designationid into v_designationid;
	 
	 end if;
	 
	 return v_designationid;

END;

$$;


ALTER FUNCTION kaverimrg.fn_add_designation_role(_createdby integer, _designame character varying, _desigdescription text, _isactive boolean) OWNER TO postgres;

