--
-- Name: fn_add_office(integer, integer, text, text, text, text, integer, integer, text, text, integer, text, character varying, integer, boolean, integer, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_add_office(_createdby integer, _officetypeid integer, _officename text, _officenamer text, _shortname text, _shortnamer text, _districtid integer, _kaverimrgcode integer, _officeaddress text, _landline text, _pincode integer, _govt_order_filepath text, _ddocode character varying, _parentofficeid integer DEFAULT NULL::integer, _isactive boolean DEFAULT true, _anywhereregenabled integer DEFAULT 0, _bhoomicensuscode integer DEFAULT NULL::integer, _onlinebookingenabled integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_officeid integer;
v_kaverimrgcode integer;
v_count integer;
v_anywhereregenabled  boolean;

BEGIN 

	if _anywhereregenabled=0 then 
	v_anywhereregenabled=false;
	else 
	v_anywhereregenabled=true;
end if;
	
	  
select nextval('kaverimrg.officeid_seq'::regclass) into v_officeid;

 if  _officetypeid=1 then
    select count(*) into v_count from kaverimrg.mas_officemaster where officetypeid=1;
     if v_count>0 then 
     
       return 0;
     end if;
    _parentofficeid=v_officeid;
    _kaverimrgcode=1;
end if;

if  _officetypeid=2 then
	select count(*) into v_count from kaverimrg.mas_officemaster where officetypeid=2 and districtid=_districtid;
     if v_count>0 then 
     
       return 0;
     end if;
    _parentofficeid=1;
    _kaverimrgcode=_districtid;
end if;

if _officetypeid=3 then 

	select count(*) into v_count from kaverimrg.mas_officemaster where officetypeid=3 and officename =_officename;
     if v_count>0 then 
     
       return 0;
     end if;
    
    if v_count=0 then 
    INSERT INTO kaverimrg.sromaster
	(districtcode, sronamek, sronamee, shortnamek, shortnamee, enableanywherereg, getbhoomidata,islive)
	VALUES(_districtid,_officenamer,_officename,_shortnamer,_shortname,v_anywhereregenabled, false,true)
	returning srocode into _kaverimrgcode;
   end if;

    
 end if;




 
 insert into kaverimrg.mas_officemaster(createdby,officeid,officetypeid,officename,officenamer,shortname,shortnamer,districtid,parentofficeid,kaverimrgcode,bhoomicensuscode,anywhereregenabled,officeaddress,landline,onlinebookingenabled,pincode,govt_order_filepath,ddocode,isactive)
VALUES
(_createdby,v_officeid,_officetypeid,_officename,_officenamer,_shortname,_shortnamer,_districtid,_parentofficeid,_kaverimrgcode,_bhoomicensuscode,_anywhereregenabled,_officeaddress,_landline,_onlinebookingenabled,_pincode,_govt_order_filepath,_ddocode,_isactive);
 
	-- if Any sro under DR is anywhere enabled then ,All sr under that dr will be anywhere enabled	 
if(_officetypeid=3 and _anywhereregenabled=1 ) then
   update kaverimrg.mas_officemaster set anywhereregenabled=1 where parentofficeid=_parentofficeid;
end if;
	

return v_officeid;

END;

$$;


