--
-- Name: fn_add_role_module_function_mapping(integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_add_role_module_function_mapping(_rollid integer, _functionid integer, _moduleid integer, _submoduleid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_success  integer;
v_count integer;

BEGIN 

select count(*)  into  v_count  from kaverimrg.role_module_function_mapping   where
rollid=_rollid  and moduleid=_moduleid and submoduleid=_submoduleid and functionid=_functionid;
if(v_count=0) THEN
 insert into kaverimrg.role_module_function_mapping(rollid,functionid,moduleid,submoduleid)
  values (_rollid,_functionid,_moduleid,_submoduleid)
  returning 1 into v_success;
 ELSE
 v_success=0;
 end if;
 
 

return v_success;

END;

$$;


