--
-- Name: fn_add_usergroup(text, text, boolean, integer, integer[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_add_usergroup(_groupname text, _groupdesc text, _isactive boolean, _createdby integer, _rollarray integer[] DEFAULT NULL::integer[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$



DECLARE
v_groupid integer;
v_count integer;
v_roleid integer;
BEGIN 
	v_groupid:=0;
       select count(*) into v_count from kaverimrg.deptmentusergroup where groupname=_groupname;
	   if v_count=0 then 
	   
		INSERT into kaverimrg.deptmentusergroup(groupname,groupdesc,isactive,createdby)
		values(_groupname,_groupdesc,_isactive,_createdby) 
		returning groupid into v_groupid;
		
		if(_rollarray is not null and array_length(_rollarray,1)>0 ) then
			for v_roleid in (select * from unnest(_rollarray)a) 
		 LOOP
		 
			insert into kaverimrg.group_roll_mapping(groupid,rollid) values(v_groupid,v_roleid);
		 end loop;
		 end if;
	end if;
		
		
		return v_groupid;
		 
END;

$$;


ALTER FUNCTION kaverimrg.fn_add_usergroup(_groupname text, _groupdesc text, _isactive boolean, _createdby integer, _rollarray integer[]) OWNER TO postgres;

--
-- Name: fn_amendmentfetch_firm_details(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_amendmentfetch_firm_details(_finalregistrationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$


declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
	    from ( select c.districtnamee,c.districtnamee as droffice,
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,d.finalregistrationnumber,d.durationoffirm
			from kaverimrg.firmmaster d 
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.finalregistrationnumber =_finalregistrationnumber
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,d.finalregistrationnumber,d.durationoffirm)Firmdetails) as Firmdetails,
			  
			  	   
( select array_to_json(array_agg(row_to_json(Branchdetails)))
  from ( select
			bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
		stlgd.statenamee||'-'||bg.branchpincode as Address, bg.branchphone
		from kaverimrg.firmmaster d 
		inner join kaverimrg.firmbranches bg on d.applicationnumber =bg.applicationnumber
		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode 			                       
        where d.applicationnumber=bg.applicationnumber  and
		d.finalregistrationnumber = _finalregistrationnumber )Branchdetails) as Branchdetails,
		  
		  
( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,

( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,6)
	 order by firmpersonid)partnerdetails
) as partnerdetails,	  
							
( select array_to_json(array_agg(row_to_json(firmwitness)))
  from (select coalesce(fe.firstname,null) as firstname,coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID
					from kaverimrg.firmmaster d 	
 inner join kaverimrg.frm_witnessdetails fe  on d.applicationnumber=fe.applicationnumber
			where d.finalregistrationnumber =_finalregistrationnumber)firmwitness) as firmwitness
	   
from kaverimrg.firmmaster d 	
    inner join 	kaverimrg.firmparty a on d.applicationnumber=a.applicationnumber
inner join kaverimrg.districtmaster c on a.predistrictcode = c.districtcode
where d.finalregistrationnumber =_finalregistrationnumber
   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_amendmentfetch_firm_details(_finalregistrationnumber character varying) OWNER TO postgres;

--
-- Name: fn_amendmentfetch_firm_details(character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_amendmentfetch_firm_details(_finalregistrationnumber character varying, _firmname character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
v_finalregistrationnumber  character varying;
v_count integer;

BEGIN

if _firmname is not null  then 
  
  select  finalregistrationnumber,count(*) into v_finalregistrationnumber,v_count
  from kaverimrg.firmmaster where trim(firmname)=trim(_firmname)
  group by finalregistrationnumber limit 1;
  if v_count=1 then 
  _finalregistrationnumber:=v_finalregistrationnumber;
  end if;
end if;

select row_to_json(data_json) into v_data_json 
	    from ( select c.districtnamee,c.districtnamee as droffice,
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(distinct fp.firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,d.finalregistrationnumber,d.durationoffirm
			from kaverimrg.firmmaster d 
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.finalregistrationnumber =_finalregistrationnumber and presentertypeid in (1,6)
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,d.finalregistrationnumber,d.durationoffirm)Firmdetails) as Firmdetails,
			  
			  	   
( select array_to_json(array_agg(row_to_json(Branchdetails)))
  from ( select
			bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
		stlgd.statenamee||'-'||bg.branchpincode as Address, bg.branchphone
		from kaverimrg.firmmaster d 
		inner join kaverimrg.firmbranches bg on d.applicationnumber =bg.applicationnumber
		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode 			                       
        where d.applicationnumber=bg.applicationnumber  and
		d.finalregistrationnumber = _finalregistrationnumber order by branchid desc )Branchdetails) as Branchdetails,
		  
		  
( select row_to_json(presenter_detils)
from (select br.salutation,br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,

( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select br.salutation,br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID,
	  CASE
WHEN r.presentertypeid=8 THEN  r.firstname
else
	  NULL 
END as G_firstname,

CASE
WHEN r.presentertypeid=8 THEN r.middlename
else
	  NULL 
END as G_midname,					  
CASE
WHEN r.presentertypeid=8 THEN  r.lastname
else
	  NULL 
END as G_lastname,				  
	CASE
WHEN r.presentertypeid=8 THEN  'Guardian'--pt.description 
else
	  NULL 
END as G_designation,
CASE
WHEN r.presentertypeid=8 THEN r.phoneno 
else
	  NULL 
END as G_phonenumber,
CASE
WHEN r.presentertypeid=8 THEN  r.mailaddress 
else
	  NULL 
END as G_EmailID,
	  
CASE
WHEN r.presentertypeid=8 THEN  r.firmpersonid
else
	  NULL 
END as G_firmpersonid,

CASE
WHEN r.presentertypeid=8 THEN  r.presentertypeid
else
	  NULL 
END as G_presentertypeid
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
	  left JOIN kaverimrg.firmparty r on br.linkfirmpersonid=r.firmpersonid
	  left JOIN kaverimrg.firmparty rs on rs.linkfirmpersonid=r.firmpersonid
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid!=8 and br.presentertypeid in (1,6)
	 order by br.firmpersonid desc)partnerdetails 
) as partnerdetails,	  
							
( select array_to_json(array_agg(row_to_json(firmwitness)))
  from (select fe.salutation,coalesce(fe.firstname,null) as firstname,coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID
					from kaverimrg.firmmaster d 	
 inner join kaverimrg.frm_witnessdetails fe  on d.applicationnumber=fe.applicationnumber
			where d.finalregistrationnumber =_finalregistrationnumber)firmwitness) as firmwitness
	   
from kaverimrg.firmmaster d 	
    inner join 	kaverimrg.firmparty a on d.applicationnumber=a.applicationnumber
inner join kaverimrg.districtmaster c on d.districtcode = c.districtcode
where d.finalregistrationnumber =_finalregistrationnumber
   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_amendmentfetch_firm_details(_finalregistrationnumber character varying, _firmname character varying) OWNER TO postgres;

--
-- Name: fn_application_upd_delete(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_application_upd_delete(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
declare
v_cnt integer;
--y integer;
v_appno varchar;
BEGIN	 
select count(*) into v_cnt from kaverimrg.applicantapplicationdetails 
where applicationnumber =_applicationnumber;

if (v_cnt>0)
then
update kaverimrg.applicantapplicationdetails set isdeleted =true 
where applicationnumber =_applicationnumber;
v_appno:=_applicationnumber;
else 
v_appno:='application does not exists';

end if;

return v_appno;
END;
$$;


ALTER FUNCTION kaverimrg.fn_application_upd_delete(_applicationnumber character varying) OWNER TO postgres;

