--

CREATE FUNCTION kaverimrg.fn_autofile_fruits_doc(_applicationnumber character varying, _docpath character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_referenceno varchar;
BEGIN  

update kaverimrg.fruits_data_recv_details 
	set applicationstatus = 1, isformiiisrsigned = true, formiiipath = _docpath
where applicationnumber = _applicationnumber returning referenceno into v_referenceno;
	
update kaverimrg.documentmaster 
	set uploaddocdeedpath = _docpath
where applicationnumber = _applicationnumber;
return v_referenceno;
END;
$$;


