--

CREATE FUNCTION kaverimrg.fn_challan_exit(_challan character varying) RETURNS boolean
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
declare
x integer;
y integer;
z integer;
BEGIN	 
select count(*) into x from kaverimrg.ams_reg_epaymenttransdetails where 
deptreferencecode = _challan;
select count(*) into y from kaverimrg.otherreceiptdetails where ddchallannumber=_challan;
select count(*) into z from kaverimrg.AMS_BankInstrumentNumberDetails where instrumentnumber=_challan;
if (x > 0) or (y > 0) or (z > 0) then
return true;
else
return false;
end if;
END;
$$;


