--
-- Name: fn_changerole_dept_user(integer, integer, integer, bigint, boolean, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_changerole_dept_user(_updatedby integer, _userid integer, _newdesignationid integer, _phonenumber bigint, _isactive boolean DEFAULT true, _newservice_start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _newservice_end_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$




DECLARE

v_count integer;
v_success integer;
v_temp_record record;
BEGIN 

  select count(*) into v_count from kaverimrg.departmentusers where userid=_userid;
  if v_count=1 then 
	select * into v_temp_record from kaverimrg.departmentusers where userid=_userid;
	--insert previous service history
	--office1
	if (v_temp_record.designationid <> _newdesignationid) then
	insert into kaverimrg.departmentusers_service_history(userid,srocode,designationid,updatedby,officeid,servicestartdate,serviceexpdate,isgovtemployee)
	values(_userid,v_temp_record.srocode,v_temp_record.designationid,_updatedby,v_temp_record.officeid,v_temp_record.doj,current_date,v_temp_record.isgovtemployee);
	end if;
   update kaverimrg.departmentusers
   set designationid=_newdesignationid,createdby=_updatedby,mobileno=_phonenumber,serviceflag=_isactive
   where userid=_userid; 
   if _newservice_start_date is not null then
		update kaverimrg.departmentusers
		set doj=_newservice_start_date where userid=_userid; 
		
	end if;
	
	 if _newservice_end_date is not null then
		update kaverimrg.departmentusers
		set serviceexpdate=_newservice_end_date where userid=_userid; 
		
	end if;
	
	
	
   v_success=1;
   
   ELSE
   
   
   v_success=0;
   
   end if;
    
   
 
return v_success;
END;

$$;


ALTER FUNCTION kaverimrg.fn_changerole_dept_user(_updatedby integer, _userid integer, _newdesignationid integer, _phonenumber bigint, _isactive boolean, _newservice_start_date timestamp without time zone, _newservice_end_date timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_create_office_type(integer, text, text, text, text, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_create_office_type(_createdby integer, _officetype text, _officetypedesc text, _officetypedescr text, _shortname text DEFAULT NULL::text, _shortnamer text DEFAULT NULL::text) RETURNS smallint
    LANGUAGE plpgsql
    AS $$

DECLARE

v_officetypeid int2;
v_count  int2;

BEGIN 
  
 select count(officetype) into v_count   from kaverimrg.mas_officetypes mo   where officetype=upper(_officetype);
 if v_count=0 then 
    
   INSERT INTO kaverimrg.mas_officetypes(
	officetype,officetypedesc, officetypedescr, shortname, shortnamer,createdby)
	VALUES (upper(_officetype), _officetypedesc,_officetypedescr,_shortname,_shortnamer,_createdby)
	returning officetypeid into v_officetypeid;
 else
    v_officetypeid=0;
 end if;
	
	
	return v_officetypeid;

END;

$$;


ALTER FUNCTION kaverimrg.fn_create_office_type(_createdby integer, _officetype text, _officetypedesc text, _officetypedescr text, _shortname text, _shortnamer text) OWNER TO postgres;

