CREATE FUNCTION kaverimrg.fn_delete_branchdetails(p_partnerdetails kaverimrg.type_branchdelete[] DEFAULT NULL::kaverimrg.type_branchdelete[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare

v_branchid bigint;
v_row kaverimrg.type_branchdelete[];
v_arry record;
v_amendmentid integer;

begin

/*select  amendmentbranchid  into v_amendmentid  from kaverimrg.firmamendment f where f.applicationnumber
in (select a._applicationnumber from unnest(p_partnerdetails)a );*/

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partnerdetails))

loop

for v_arry in (select a._branchid,a._applicationnumber  from  unnest(v_row) a)

loop

 delete from kaverimrg.amendmentfirmbranches fp 
 where  fp.branchid=v_arry._branchid and fp.applicationnumber=v_arry._applicationnumber--fp.amendmentbranchid=v_amendmentid
 returning branchid into v_branchid;

  end loop;

 end loop;

 return 1000;

end;
$$;


