--
-- Name: fn_delete_citizenotpdetails(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_delete_citizenotpdetails(_citizenid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
v_citizenid bigint;

begin
delete from kaverimrg.citizeotpdetails 
where citizenid = _citizenid returning citizenid into v_citizenid;
return v_citizenid;
exception
WHEN unique_violation then
raise notice 'duplicate user';
  end;
$$;


