	delete from kaverimrg.partyinfo p1 where applicationnumber =_applicationnumber;

	delete from kaverimrg.k1pendingregistrationdata where applicationnumber =_applicationnumber;
	
	delete from kaverimrg.documentmaster d where applicationnumber=_applicationnumber;

	delete from kaverimrg.propertynumberdetails p3 where propertyid in (select propertyid from kaverimrg.propertymaster where applicationnumber=_applicationnumber);

	delete from kaverimrg.propertymaster p where applicationnumber=_applicationnumber;

	
