--
-- Name: fn_delete_departmentuser_from_group(integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_delete_departmentuser_from_group(_userid integer, _groupid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

 DECLARE
 v_count integer;
 v_success integer;

 
 BEGIN
    
		v_success:=0;
	 select count(*) into v_count from kaverimrg.departmentusers d where 	userid=_userid and groupid=_groupid;
	 if v_count=1 then 
	 
	  update kaverimrg.departmentusers set groupid=NULL where userid=_userid  and groupid=_groupid
	  returning 1 into v_success;
	  
	 end if;
	 
	 return v_count;

	  
 
 END;
 
$$;


ALTER FUNCTION kaverimrg.fn_delete_departmentuser_from_group(_userid integer, _groupid integer) OWNER TO postgres;

--
-- Name: fn_delete_officetype(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_delete_officetype(_officetypeid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$




DECLARE
v_success integer;
v_count integer;
BEGIN 
	v_success=0;
		select count(*) into v_count from kaverimrg.departmentusers where officeid in 
		(select officeid  from kaverimrg.mas_officemaster mo where mo.officetypeid=_officetypeid);
		if v_count=0 then
		
		 select count(*)  into v_count from kaverimrg.mas_officemaster mo where mo.officetypeid=_officetypeid;
		
		 if v_count=0 then 
		
		  delete from kaverimrg.mas_officetypes mo  where officetypeid=_officetypeid;
		  v_success=1;
		ELSE
		
		  v_success=0;
		end if;
	   end if;
	    
		
		return v_success;

END;

$$;


ALTER FUNCTION kaverimrg.fn_delete_officetype(_officetypeid integer) OWNER TO postgres;

--
-- Name: fn_delete_partner_witness(character varying, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_delete_partner_witness(_applicationnumber character varying, _firmpersonid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationnumber text;
v_firmwitnessid integer;
v_firmpersonid integer;

begin

--select firmwitnessid into v_firmwitnessid from kaverimrg.frm_witnessdetails where firmpersonid=_firmpersonid
select count(*)  into v_cnt 
from kaverimrg.frm_partnerwitnessrelations fp 
where fp.firmpersonid=_firmpersonid ;

if v_cnt<>0 then 
select fp.firmwitnessid  into v_firmwitnessid 
from kaverimrg.frm_partnerwitnessrelations fp 
where fp.firmpersonid=_firmpersonid ;
 delete from kaverimrg.frm_partnerwitnessrelations fp 
 where  fp.firmpersonid=_firmpersonid;
end if;

select count(*)  into v_cnt  from kaverimrg.frm_partnerwitnessrelations fp 
where fp.firmwitnessid =v_firmwitnessid;

if v_cnt=0 then 

delete from kaverimrg.frm_witnessdetails where firmwitnessid=v_firmwitnessid;

end if;
 
delete from kaverimrg.firmparty where firmpersonid=_firmpersonid and applicationnumber = _applicationnumber
 
 returning firmpersonid into v_firmpersonid;
 

if(v_firmpersonid is not null)
then 
return _applicationnumber;

else 
return null;
end if;

end;
$$;


ALTER FUNCTION kaverimrg.fn_delete_partner_witness(_applicationnumber character varying, _firmpersonid bigint) OWNER TO postgres;

