--
-- Name: fn_delete_partnerdetailsamendmentfinal(kaverimrg.type_partnerdelete[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_delete_partnerdetailsamendmentfinal(p_partnerdetails kaverimrg.type_partnerdelete[] DEFAULT NULL::kaverimrg.type_partnerdelete[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare

v_firmpersonid bigint;
v_row kaverimrg.type_partnerdelete[];
v_arry record;
v_amendmentpersonid integer[];
v_amendmenttypeid integer;
v_amendmentid integer;

begin

select  amendmentid  into v_amendmentid  from kaverimrg.firmamendment f where f.applicationnumber
in (select a._applicationnumber from unnest(p_partnerdetails)a );

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partnerdetails))

loop

for v_arry in (select a._firmpersonid from  unnest(v_row) a)

loop

 delete from kaverimrg.amendmentfirmparty fp 
 where  fp.firmpersonid=v_arry._firmpersonid and fp.amendmentid=v_amendmentid
 returning firmpersonid into v_firmpersonid;

  end loop;

 end loop;

 return 1;

end;
$$;


