-- Name: fn_fetch_address_taluk_lgd(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_address_taluk_lgd(_talukcode bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
v_address text;
BEGIN		

select t.taluknamee||', '||d.districtnamee||', '|| s.statenamee
into v_address 
from
kaverimrg.lgd_statemaster s
inner join kaverimrg.lgd_districtmaster d on (s.statecode = d.lgdstatecode)  
INNER JOIN kaverimrg.lgd_talukmaster T ON (t.lgd_districtcode = d.districtcode) 
where t.talukcode =  _talukcode;

return v_address;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_address_taluk_lgd(_talukcode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_address_village(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_address_village(_villagecode bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
v_address text;
BEGIN		

select v.taluknamee||', '||T.districtnamee||', '||d.statenamee
into v_address from kaverimrg.lgd_talukmaster v 
INNER JOIN kaverimrg.lgd_districtmaster T ON (v.lgd_districtcode = t.districtcode)
inner join kaverimrg.lgd_statemaster d on (t.lgdstatecode = d.statecode) 
where v.talukcode = _villagecode;

return v_address;

END;
$$;


