--
-- Name: fn_fetch_allocate_applications_sro(integer, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_allocate_applications_sro(p_srocode integer, p_status text) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, deoid integer, deoname text)
    LANGUAGE plpgsql
    AS $$
BEGIN
IF(p_status = 'CD108') THEN
   RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,0,null
from kaverimrg.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from kaverimrg.ApplicationAudit au
	where au.wrkflowstatusid = p_status and activityorder = (select max(activityorder) 
				from kaverimrg.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
left outer join kaverimrg.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join kaverimrg.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.currentstatus in (p_status)
order by aa.crtdt;
ELSIF(P_STATUS = 'CD109') then
RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,du.userid as deoid, du.firstname||' '||du.lastname
from kaverimrg.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from kaverimrg.ApplicationAudit au
	where au.wrkflowstatusid = p_status and activityorder = (select max(activityorder) 
				from kaverimrg.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
						   inner join kaverimrg.departmentusers du 
						   on (ad.assignedto=du.userid::text)
						   inner join kaverimrg.desigmaster dm on (dm.designationid =4 and dm.designationid=du.designationid)
left outer join kaverimrg.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join kaverimrg.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.currentstatus in (p_status) AND ad.deoid is not null
order by aa.crtdt;
END IF;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_allocate_applications_sro(p_srocode integer, p_status text) OWNER TO postgres;

