	--select row_to_json(app_json) into v_data_json from(
	select array_to_json(array_agg(row_to_json(app_json))) into v_data_json from
	(select amendmentbranchid,
			applicationnumber,
			amendhousebuildingname,
			amendstreetaddress,
			amendstatecode,
