select row_to_json(data_json) into v_data_json 
  --from (select row_to_json(app_json) 
 --from ( select array_to_json(array_agg(row_to_json(Firmdetails)))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone,d.registrationid,d.firmnumber,d.finalregistrationnumber,
