-- Name: fn_fetch_anywhere_reg(bigint, character varying, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_anywhere_reg(_srocode bigint, _sr character varying, pagenumber integer, pagesize integer) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, regsrocode integer, regsroname character varying, srocode integer, sroname character varying, propertyid bigint, propertydescription character varying, northboundary character varying, eastboundary character varying, westboundary character varying, southboundary character varying, executiondatetime date, presentdatetime date, registrationdatetime date, pagecount integer, executants text, claimants text, docpath text)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if(_sr = 'rsr') then
	return query 
	select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		pm.regsrocode::integer, 
		(select sronamee from kaverimrg.sromaster s where s.srocode=arl.regsrocode),
		pm.srocode::integer,
		(select sronamee from kaverimrg.sromaster s where s.srocode=arl.srocode),
		pm.propertyid,
		ps.description,
		pm.northboundary,
		pm.eastboundary,
		pm.westboundary,
		pm.southboundary,
		dm.executiondatetime::date,
		dm.presentdatetime::date,
		dm.registrationdatetime::date,
		dm.pagecount,
		prt_ex.executants,
		prt_cl.claimants,
		dm.uploaddocdeedpath
	from kaverimrg.anywhere_reg_log arl
	 join kaverimrg.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	 join kaverimrg.propertymaster pm on arl.propertyid = pm.propertyid  
	 join kaverimrg.propertyschedules ps on pm.propertyid = ps.propertyid 
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as claimants
			FROM kaverimrg.partyinfo vw
			WHERE vw.partytypeid = 1 and vw.srocode=_srocode
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as executants
			FROM kaverimrg.partyinfo vw
			WHERE vw.partytypeid = 2 and vw.srocode=_srocode
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
	where arl.regsrocode=_srocode and arl.ismemosent = false and pm.srocode<>0
	OFFSET PageOffset
	FETCH NEXT pagesize ROWS ONLY;
elsif (_sr = 'jsr') then
	return query 
	select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		pm.regsrocode::integer,
		(select sronamee from kaverimrg.sromaster s where s.srocode=arl.regsrocode),
		pm.srocode::integer,
		(select sronamee from kaverimrg.sromaster s where s.srocode=arl.srocode),
		pm.propertyid,
		ps.description,
		pm.northboundary,
		pm.eastboundary,
		pm.westboundary,
		pm.southboundary,
		dm.executiondatetime::date,
		dm.presentdatetime::date,
		dm.registrationdatetime::date,
		dm.pagecount,
		prt_ex.executants,
		prt_cl.claimants,
		dm.uploaddocdeedpath
	from kaverimrg.anywhere_reg_log arl
	 join kaverimrg.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	 join kaverimrg.propertymaster pm on arl.propertyid = pm.propertyid  
	 join kaverimrg.propertyschedules ps on pm.propertyid = ps.propertyid 
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as claimants
			FROM kaverimrg.partyinfo vw
			join kaverimrg.propertymaster pm2 on vw.applicationnumber=pm2.applicationnumber 
			WHERE vw.partytypeid = 1 and pm2.srocode=_srocode
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	 JOIN ( SELECT vw.applicationnumber,
			string_agg((coalesce (vw.firstname,'')::text||' '::text||coalesce (vw.middlename,'')::text||' '::text||coalesce (vw.lastname,'')::text|| ' '::text) || coalesce (vw.address,'')::text ,', '::text) as executants
			FROM kaverimrg.partyinfo vw
			join kaverimrg.propertymaster pm2 on vw.applicationnumber=pm2.applicationnumber 
			WHERE vw.partytypeid = 2 and pm2.srocode=_srocode
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
	where arl.srocode=_srocode and arl.isjurisdictionsroaccepted = false and pm.regsrocode<>0
	OFFSET PageOffset
	FETCH NEXT pagesize ROWS ONLY;
end if;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_anywhere_reg(_srocode bigint, _sr character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applicaion_finalized(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_applicaion_finalized(p_srocode integer) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee
from kaverimrg.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from kaverimrg.ApplicationAudit au
	where au.wrkflowstatusid in ('CD103','CD110') and activityorder = (select max(activityorder) 
				from kaverimrg.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
left outer join kaverimrg.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join kaverimrg.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and ad.sfdaid is not null and 
ad.currentstatus in ('CD105','CD110')
order by aa.crtdt;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_applicaion_finalized(p_srocode integer) OWNER TO postgres;

--
-- Name: fn_fetch_applicaion_pending(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_applicaion_pending(p_srocode integer) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select ad.applicationnumber applicationnum,aa.crtdt::date as applicationdate,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee
from kaverimrg.ApplicantApplicationdetails ad
inner join (select au.applicationnumber,crtdt,au.wrkflowstatusid from kaverimrg.ApplicationAudit au
	where au.wrkflowstatusid = 'CD102' and activityorder = (select max(activityorder) 
				from kaverimrg.ApplicationAudit aau 
						   where aau.applicationnumber = au.applicationnumber 
						   and aau.wrkflowstatusid = au.wrkflowstatusid)) aa 
						   on aa.applicationnumber= ad.applicationnumber
				
left outer join kaverimrg.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join kaverimrg.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.srocode = p_srocode and 
ad.sfdaid is null and 
ad.currentstatus in ('CD102')
order by aa.crtdt;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_applicaion_pending(p_srocode integer) OWNER TO postgres;

--
-- Name: fn_fetch_application_count_deo(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_application_count_deo(p_deoid text) RETURNS TABLE(totalcount bigint, totalreviewedcount bigint, totalweeklycount bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select  count(tot_cnt.applicationnumber) as TotalCount,
count(tot_review.applicationnumber) TotalReviewedCount,100::bigint as TotalweeklyCount
  from kaverimrg.ApplicantApplicationdetails ad 
 left JOIN (select distinct applicationnumber from kaverimrg.ApplicationAudit 
		   where wrkflowstatusid = 'CD109') tot_cnt 
 on (ad.applicationnumber = tot_cnt.applicationnumber) 
 left JOIN (select distinct applicationnumber from kaverimrg.ApplicationAudit 
		   where wrkflowstatusid = 'CD112') tot_review
 on (ad.applicationnumber = tot_review.applicationnumber) 
 where ad.assignedto = p_deoid;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_application_count_deo(p_deoid text) OWNER TO postgres;

--
-- Name: fn_fetch_application_count_sro(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_application_count_sro(p_srocode integer) RETURNS TABLE(totalcount bigint, totalallocatedcount bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select count(tot_cnt.applicationnumber) as TotalCount,
count(tot_alloc.applicationnumber) TotalAllocatedCount
 from kaverimrg.slottxn slot 
 inner join kaverimrg.ApplicantApplicationdetails ad on 
 (slot.applicationnumber = ad.applicationnumber and currentstatus in ('CD108','CD109'))
 left JOIN (select distinct applicationnumber from kaverimrg.ApplicationAudit 
		   where wrkflowstatusid = 'CD108') tot_cnt 
 on (ad.applicationnumber = tot_cnt.applicationnumber) 
 left JOIN (select distinct applicationnumber from kaverimrg.ApplicationAudit 
		   where wrkflowstatusid = 'CD109') tot_alloc
 on (ad.applicationnumber = tot_alloc.applicationnumber)
 where slot.sltbookedon::date = current_date::date 
 and ad.srocode = p_srocode;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_application_count_sro(p_srocode integer) OWNER TO postgres;

--
-- Name: fn_fetch_application_deo(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_application_deo(p_deoid text) RETURNS TABLE(applicationnum character varying, applicationdate date, applicationtime text, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, isverified boolean, isuploaddocuments boolean, presentdate date, executedate date, pendingdocumentnumber character varying, finalregistrationnumber character varying, documentid bigint, isprintsummary boolean, isprintendorsement boolean, isdigitalsigned boolean, isregistrationcompleted boolean, sakalanumber character varying, uploadsummarydocpath text, remarks text, isundervaluation boolean, articlenamee character varying, isphotothumbtransmitted boolean, ispaymentdone boolean)
    LANGUAGE plpgsql
    AS $_$


BEGIN
   RETURN QUERY
  select   ad.applicationnumber applicationnum,slot.slotbookdate as applicationdate,
  slot.slotbooktime as applicationtime,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,coalesce(dm.ispaymentdetails,'false') as isverified,
coalesce(dm.isuploaddocuments,'false') isuploaddocuments,dm.presentdatetime::date presentdate,
dm.executiondatetime::date as executedate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1')::character varying, 
dm.finalregistrationnumber,dm.documentid,
dm.isprintsummary,dm.isprintendorsement,
	dm.isdigitalsigned,dm.isregistrationcompleted,dm.gscno as sakalanumber,dm.uploadsummarydocpath,ad.remarks,dm.isundervaluation,rg.articlenamee,dm.isphotothumbtransmitted
	,CASE
            WHEN ad.applicationnumber::text = fk.applicationnumber::text THEN true
            ELSE false
        END AS ispaymentdone
from kaverimrg.ApplicantApplicationdetails ad 
inner join kaverimrg.documentmaster dm on (dm.applicationnumber = ad.applicationnumber)
LEFT join (SELECT distinct sl.applicationnumber,
            sl.appointmentdate sltbookedon,
            sl.appointmentdate::date AS slotbookdate,
            sl.starttime||'-'||sl.endtime::text AS slotbooktime
           FROM kaverimrg.appointmentmaster sl
          WHERE sl.status in ('1','Pending') --AND
		  -- sl.appointmentdate::date = (current_timestamp AT TIME ZONE 'Asia/Calcutta')::date 
		  ) slot 
						   on slot.applicationnumber= ad.applicationnumber
left outer join kaverimrg.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus
left join kaverimrg.registrationarticles rg on ad.regarticlecode=rg.regarticlecode 
left join kaverimrg.servicesmaster sm on ad.applicationtypeid = sm.serviceid
left join kaverimrg.feesrequired_paymentchk fk on ad.applicationnumber=fk.applicationnumber
where ad.deoid::text = p_deoid and 
(ad.currentstatus in ('CD110','CD111','CD112','CD113','CD114','CD115','CD116','CD117','CD120','CD119','CD134','CD136'))

order by slot.sltbookedon  ;

END;
$_$;


