--
-- Name: fn_fetch_application_json_data(text, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_application_json_data(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
		
select row_to_json(app_json) into v_data_json
from (
  select ad.applicationnumber,dm.executiondatetime::date executedate,
dm.pendingdocumentnumber, dm.pagecount ,sa.articlenamee as stamparticlename,
ra.articlenamee as regarticalename, 
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,
 	pm.propertyid,
    pm.documentid,
    d.villagenamee,
	pm.propertytypeid,
	ptm.propertytypename as propertytype,
    c.sronamee sroname,
    pm.northboundary,
    pm.southboundary,
    pm.eastboundary,
    pm.westboundary,
    pm.landmark,
	pm.consideration,
    pm.marketvalue,
	pm.cessduty,
    pm.govtduty,
	pm.additionalduty,
	pm.stampduty,
    pm.valuationreport,
	( select array_to_json(array_agg(row_to_json(schd)))
      from (select ps.scheduletype,ps.totalarea,ps.description as scheduledescription,
			ps.partyids as scheduleparties from kaverimrg.propertyschedules ps 
		   where ps.propertyid = pm.propertyid)schd ) as propertyschedules,
	  ( select array_to_json(array_agg(row_to_json(prptyno)))
      from (select pnd.propertyid,pnd.currentpropertytypeid,
			pntm.typenameenglish as propertynumbertype,
			pnd.currentnumber,pnd.hissa_no,pnd.survey_no 
			from kaverimrg.propertynumberdetails pnd 
		   left join kaverimrg.propertynotypemaster pntm			
			on (pntm.propertytypeid = pnd.currentpropertytypeid) 
		   where pnd.propertyid = pm.propertyid )prptyno ) 
			as propertynumberdetails
   FROM kaverimrg.propertymaster pm 
   left join kaverimrg.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
   left join  kaverimrg.sromaster c on (pm.srocode = c.srocode)
   left join kaverimrg.villagemaster d on (pm.villagecode = d.villagecode)
   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (select applicationnumber,partyid,name as partyname,age, address ,profession,
phonenumber,epic,partytypeid,partytypename,isexecutor,ispresenter,admissiondate,
section88exemption,fingerid,thumbpath,photopath
from kaverimrg.vw_fetch_party vw_party 
			where vw_party.applicationnumber = ad.applicationnumber) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select name,address,age,profession from kaverimrg.witnessinfo wi
where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo
  from kaverimrg.applicantapplicationdetails ad
inner join kaverimrg.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaverimrg.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaverimrg.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode
) app_json ;

return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_application_json_data(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_application_status_track(bigint, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_application_status_track(_srocode bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
PageOffset INTEGER := 0;
begin
	
if(pagenumber<>-1 and pagesize<>-1) then
	PageOffset := ((pagenumber - 1) * pagesize);
	select row_to_json(data_json) into v_data_json 
	from (select dsm.districtnamee ,s.sronamee,
		(select array_to_json(array_agg((row_to_json(application_data))))
	  	from(select a.applicationnumber,a.currentstatus  from kaverimrg.applicantapplicationdetails a 
		   join kaverimrg.documentmaster d on a.applicationnumber=d.applicationnumber 
		   where d.srocode=_srocode and a.currentstatus in ('CD108','CD109','CD110','CD111',
	'CD112','CD115','CD116') order by a.inserteddatetime OFFSET PageOffset
	FETCH NEXT pagesize ROWS ONLY)application_data) as application_data
	from kaverimrg.districtmaster dsm 
	join kaverimrg.sromaster s on dsm.districtcode=s.districtcode and s.srocode=_srocode)data_json;

elsif (pagenumber=-1 or  pagesize=-1) then
	PageOffset := ((pagenumber - 1) * pagesize);
	select row_to_json(data_json) into v_data_json 
	from (select dsm.districtnamee ,s.sronamee,
		(select array_to_json(array_agg((row_to_json(application_data))))
	  	from(select a.applicationnumber,a.currentstatus  from kaverimrg.applicantapplicationdetails a 
		   join kaverimrg.documentmaster d on a.applicationnumber=d.applicationnumber 
		   where d.srocode=_srocode and a.currentstatus in ('CD108','CD109','CD110','CD111',
	'CD112','CD115','CD116') order by a.inserteddatetime)application_data) as application_data
	from kaverimrg.districtmaster dsm 
	join kaverimrg.sromaster s on dsm.districtcode=s.districtcode and s.srocode=_srocode)data_json;
end if;

return v_data_json;

END;
$$;


