CREATE FUNCTION kaverimrg.fn_fetch_applicationdetails(_applicationnumber character varying) RETURNS TABLE(appointmenttypeid integer, appointmenttype character varying, serviceid integer, servicename character varying, srocode integer, sroname character varying, firstname character varying)
    LANGUAGE plpgsql
    AS $$


declare
v_typeid int;

BEGIN 
	
select applicationtypeid into v_typeid from kaverimrg.applicantapplicationdetails a
where applicationnumber =_applicationnumber;

if(v_typeid=1)
then
return query
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,p.srocode
,s.sronamee  sroname
, p.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaverimrg.partyinfo p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =p.applicationnumber 
join kaverimrg.sromaster s on p.srocode =s.srocode 
where a.applicationnumber=_applicationnumber and p.ispresenter=true;

elsif(v_typeid=4)
then
return query
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,a.srocode
,s.sronamee  sroname
, c.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.citizenmaster c on a.citizenid=c.citizenid
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
--join kaverimrg.partyinfo p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =a.applicationnumber 
join kaverimrg.sromaster s on a.srocode =s.srocode 
where a.applicationnumber=_applicationnumber;

elsif v_typeid in (6) then 
return query 
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,dsm.districtcode
,dsm.districtnamee  as sroname
, c.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaverimrg.citizenmaster c on a.citizenid=c.citizenid
--join kaverimrg.firmparty p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =p.applicationnumber 
join kaverimrg.firmmaster  s on a.applicationnumber  =s.applicationnumber 
join kaverimrg.districtmaster  dsm on s.districtcode =dsm.districtcode
where a.applicationnumber=_applicationnumber 
--and p.presentertypeid in (1,2)
;

elseif(v_typeid = 46) then
return query
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,a.srocode
,s.sronamee as sroname
,c.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.citizenmaster c on a.citizenid=c.citizenid
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid 
join kaverimrg.sromaster s on a.srocode =s.srocode 
where a.applicationnumber= _applicationnumber;


elsif v_typeid in (47) then 
return query 
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,dsm.districtcode
,dsm.districtnamee  as sroname
, c.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaverimrg.citizenmaster c on a.citizenid=c.citizenid
--join kaverimrg.firmparty p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =p.applicationnumber 
join kaverimrg.firmamendment  s on a.applicationnumber  =s.applicationnumber 
join kaverimrg.districtmaster  dsm on s.drcode =dsm.districtcode
where a.applicationnumber=_applicationnumber 
--and p.presentertypeid in (1,2)
;

elsif v_typeid in (48,49,50) then 
return query 
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,dsm.districtcode
,dsm.districtnamee  as sroname
, c.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaverimrg.citizenmaster c on a.citizenid=c.citizenid
--join kaverimrg.firmparty p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =p.applicationnumber
join kaverimrg.firm_dissolution s on a.applicationnumber=s.applicationnumber
--join kaverimrg.sromaster s on a.srocode =s.srocode 
join kaverimrg.districtmaster  dsm on s.drcode=dsm.districtcode
where a.applicationnumber=_applicationnumber 
--and p.presentertypeid in (1,2)
;

/*elsif (v_typeid=47) then 
return query 
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,dsm.districtcode
,dsm.districtnamee  as sroname
, p.firstname::varchar
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaverimrg.firmparty p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =p.applicationnumber 
join kaverimrg.sromaster s on a.srocode =s.srocode 
join kaverimrg.districtmaster  dsm on s.districtcode=dsm.districtcode
where a.applicationnumber=_applicationnumber  and p.presentertypeid in (1,2);*/



end if;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_applicationdetails(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_applicationdetails_backup(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_applicationdetails_backup(_applicationnumber character varying) RETURNS TABLE(appointmenttypeid integer, appointmenttype character varying, serviceid integer, servicename character varying, srocode integer, sroname character varying, firstname character varying, iswillpvtattendance boolean)
    LANGUAGE plpgsql
    AS $$


declare
v_typeid int;

BEGIN 
	
select applicationtypeid into v_typeid from kaverimrg.applicantapplicationdetails a where applicationnumber =_applicationnumber;

if(v_typeid=1)
then
return query
with party as (select count(partyid) as countofparty,isprivateattendance,partyid,applicationnumber from kaverimrg.partyinfo group by isprivateattendance,partyid,applicationnumber )
select distinct
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,p.srocode
,s.sronamee  sroname
, p.firstname::varchar
,case when party.countofparty = 1 and party.isprivateattendance = true then true else false END as iswillpvtattendance
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
join kaverimrg.partyinfo p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster c on c.applicationnumber =p.applicationnumber 
join kaverimrg.sromaster s on p.srocode =s.srocode 
join party on party.applicationnumber = a.applicationnumber
where a.applicationnumber=_applicationnumber and p.ispresenter = case 
when party.countofparty=1 and party.isprivateattendance = true then  false 
else  true end;

elsif(v_typeid=4)
then
return query
select
1 as appointmenttypeid,
'Regular'::varchar as appointmenttype,
e.serviceid
,e.servicename
,a.srocode
,s.sronamee  sroname
, c.firstname::varchar,
false as iswillpvtattendance
from kaverimrg.applicantapplicationdetails a 
join kaverimrg.citizenmaster c on a.citizenid=c.citizenid
join kaverimrg.servicesmaster e on a.applicationtypeid  =e.serviceid
--join kaverimrg.partyinfo p on a.applicationnumber =p.applicationnumber 
--join kaverimrg.documentmaster d on d.applicationnumber =a.applicationnumber 
join kaverimrg.sromaster s on a.srocode =s.srocode 
where a.applicationnumber=_applicationnumber;
end if;


end;
$$;


