--
-- Name: fn_fetch_applications_citizen_dashboard(bigint, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_applications_citizen_dashboard(_citizenid bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber text, applicationstartdate timestamp without time zone, applicationtype text, ispendingdocument boolean, wrkflowstatusnamee text, wrkflowstatusid text, remarks text, sroname text, sronamek text, isduecorrection boolean, deptreferencecode text, reasonid integer)
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;
BEGIN	
		PageOffset := ((pagenumber - 1) * pagesize);
			

				return query 
				select 
				app.applicationnumber::text, 
				app.applicationstartdate, 
				ser.servicename::text as applicationtype,
				a.ispendingdocument,
				wrk.wrkflowstatusnamee as wrkflowstatusnamee,
				app.currentstatus::text as wrkflowstatusid,
				app.remarks,
				sr.sronamee::text as sroname,
				sr.sronamek::text,
				app.isduecorrection,
					( SELECT ams_reg_epaymenttransdetails.deptreferencecode::text
					FROM kaverimrg.ams_reg_epaymenttransdetails
					WHERE ams_reg_epaymenttransdetails.applicationnumber::text = app.applicationnumber::text AND 
					ams_reg_epaymenttransdetails.isdelete IS NULL
					ORDER BY ams_reg_epaymenttransdetails.inserteddatetime DESC
					LIMIT 1) AS deptreferencecode,
				a.reasonid
		--kaverimrg.vw_citizen_dashbaord vw 
  FROM kaverimrg.applicantapplicationdetails app
     JOIN kaverimrg.servicesmaster ser ON app.applicationtypeid = ser.serviceid
     JOIN kaverimrg.wrkflowmaster wrk ON app.currentstatus::text = wrk.wrkflowstatusid::text
     LEFT JOIN kaverimrg.sromaster sr ON sr.srocode = COALESCE(app.regsrocode, app.srocode)
	 left join kaverimrg.minutebook_data a on a.applicationnumber = app.applicationnumber
				where  app.citizenid = _citizenid
			order by app.applicationstartdate desc
			
	/* select 
				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid
				from kaverimrg.vw_citizen_dashbaord vw 
				left join kaverimrg.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc
				*/
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_applications_citizen_dashboard(_citizenid bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applications_citizen_dashboard_bkup_020523(bigint, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_applications_citizen_dashboard_bkup_020523(_citizenid bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber text, applicationstartdate timestamp without time zone, applicationtype text, ispendingdocument boolean, wrkflowstatusnamee text, wrkflowstatusid text, remarks text, sroname text, sronamek text, isduecorrection boolean, deptreferencecode text, reasonid integer)
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;
BEGIN	
		PageOffset := ((pagenumber - 1) * pagesize);
			

				return query 
				select 

				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid
				from kaverimrg.vw_citizen_dashbaord vw 
				left join kaverimrg.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc
				
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		


END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_applications_citizen_dashboard_bkup_020523(_citizenid bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_applications_citizen_dashboard_json(bigint, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_applications_citizen_dashboard_json(_citizenid bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;
v_count integer;
v_data_json json;
BEGIN	

		select count(*) into v_count from  kaverimrg.vw_citizen_dashbaord vw 
		left join kaverimrg.minutebook_data a on a.applicationnumber = vw.applicationnumber
		where  vw.citizenid = _citizenid;
		PageOffset := ((pagenumber - 1) * pagesize);
			

				select row_to_json(app_data) into v_data_json from (select array_to_json(array_agg(row_to_json(temp))) as applications,v_count as Total from (select 

				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid,
				a.isbefore2003,
				vw.applicationtypeid
				from kaverimrg.vw_citizen_dashbaord vw 
				left join kaverimrg.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc
				
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY	)temp)app_data;
		
		
return  v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_applications_citizen_dashboard_json(_citizenid bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

