  FROM kaverimrg.applicantapplicationdetails app
     JOIN kaverimrg.servicesmaster ser ON app.applicationtypeid = ser.serviceid
     JOIN kaverimrg.wrkflowmaster wrk ON app.currentstatus::text = wrk.wrkflowstatusid::text
     LEFT JOIN kaverimrg.sromaster sr ON sr.srocode = COALESCE(app.regsrocode, app.srocode)
	 left join kaverimrg.minutebook_data a on a.applicationnumber = app.applicationnumber
				where  app.citizenid = _citizenid
			order by app.applicationstartdate desc
			
	/* select 
				vw.applicationnumber::text, 
				vw.applicationstartdate, 
				vw.servicename::text as applicationtype,
				a.ispendingdocument,
				vw.currentstatusname as wrkflowstatusnamee,
				vw.currentstatus::text as wrkflowstatusid,
				vw.remarks,
				vw.sroname::text,
				vw.sronamek::text,vw.isduecorrection,vw.deptreferencecode::text,a.reasonid
				from kaverimrg.vw_citizen_dashbaord vw 
				left join kaverimrg.minutebook_data a on a.applicationnumber = vw.applicationnumber
				where  vw.citizenid = _citizenid
				order by vw.applicationstartdate desc
				*/
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

END;
$$;


