--
-- Name: fn_fetch_cc_details_json_check(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_cc_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$

/* 22-08-22 - Added phone column (Drupad)   */
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
select b.ccid,
b.applicationnumber,
aad.currentstatus , 
c.documenttypedesc as applicationtype,
a.firstname,
a.middlename,
a.lastname,
a.pan as Adhaarnumber,
a.phone,
--b.ccnumber,
--b.ccdate,
--b.userid,
--b.documenttype,
b.documenttype as documenttypeid,
b.marriagetypeid,
g.documenttypedesc as documenttype,
--c.documenttypedesc as documenttype,
b.kaverimrgdrocode ,
e.districtcode,
e.districtnamee as district,
b.kaverimrgsrocode,
d.sronamee as subregistraroffice,
b.documentnumber,
b.booktype as booktypeid,
f.booknameenglish as booktype,
b.yearofregistration,
a.citizenid,
/*b.pagecount,
b.totalamount,
b.isappliedforsignedcopy,
b.documentstatusid,
b.submittedby,
b.submitteddatetime,
b.preparedby,
b.prepareddatetime,
b.signedby,
b.signeddatetime,
b.appliedsignedcopy,
b.comparedby,
b.compareddatetime,
b.certificatenumber,
b.accepteddatetime,
b.marriagetypeid,
b.firmtypeid,*/
	( select array_to_json(array_agg(row_to_json(feesrequired)))
      from (
	   select c.serviceid,
c.ispaid,
c.requiredfeeid,
c.feeruleid,
c.payableamount,
c.feedescription from kaverimrg.cc_requiredfees c where c.ccid = b.ccid
	  )feesrequired) as feesrequired
	from kaverimrg.citizenmaster a  
    inner join kaverimrg.cc_applicationdetails b on  a.citizenid = b.userid
	inner join kaverimrg.documenttypemaster c on cast(b.documenttype as bigint) = c.documenttypeid
	inner join kaverimrg.sromaster d on b.kaverimrgsrocode = d.srocode
	inner join kaverimrg.districtmaster e on b.kaverimrgdrocode = e.districtcode
	inner join kaverimrg.booktypemaster f on cast(b.booktype as integer) = f.bookid
	inner join kaverimrg.documenttypemaster g on b.documenttype = g.documenttypeid
	inner join kaverimrg.applicantapplicationdetails aad on aad.applicationnumber  = b.applicationnumber
	
	--right JOIN kaverimrg.partyinfo p on p.applicationnumber::text = a.applicationnumber::text
where b.applicationnumber = _applicationnumber
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_cc_details_json_check(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_cc_receiptnumber_details_json(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_cc_receiptnumber_details_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
begin
	select row_to_json(data_json) into v_data_json 
      from (
	         select  b.ccid,b.ccdate::date,b.applicationnumber,sum(f.payableamount) as Fees,c.firstname as name,c.permanentaddress as address,
        b.certificatenumber,s.sronamee as place,r.receiptnumber 
      from kaverimrg.citizenmaster c 
         inner join kaverimrg.cc_applicationdetails b  on b.userid=c.citizenid
         inner join kaverimrg.cc_requiredfees f on f.ccid =b.ccid 
        left join kaverimrg.receiptmaster r on r.applicationnumber =b.applicationnumber 
        inner join kaverimrg.sromaster s on s.srocode =b.kaverimrgsrocode
         where b.applicationnumber =_applicationnumber
         --'CCA-07032023-21664'
        group by b.ccid,b.ccdate,c.firstname,c.permanentaddress,b.certificatenumber,r.receiptnumber,s.sronamee
) data_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_cc_receiptnumber_details_json(_applicationnumber text) OWNER TO postgres;

