    AS $$



--declare
--partyids record;
begin
return query
with recursive q as(
SELECT  *
from kaverimrg.partyinfo p  
where p.partyid =_partyid -- this condition defines the ultimate ancestors in your chain, change it as appropriate
UNION ALL
SELECT  p2.*
from kaverimrg.partyinfo p2
join q ON p2.linkpartyid = q.partyid) select q.partyid  ,q.srocode  ,q.documentid  
,q.partytypeid ,q.firstname ,q.middlename
,q.lastname,q.address,q.age  ,q.sex
,q.isexecutor ,q.ispresenter,q.isorganization,
