--,q.poaadmission,q.poapresentation ,q.primaryseller
--,q.profession,q.restriction
--,q.restrictiondescription ,q.restrictiontype ,q.section88exemption
--,q.thumbmatchfailedreasonid  ,q.thumbminutiae ,q.thumbpath
--,q.totalextacre  ,q.totalextgunta  ,q.totalextfgunta  ,q.transactextacre  ,q.transactextgunta  ,q.transactextfgunta  
--,q.volumename ,q.hasgpa ,q.isaua  
--,q.importedpartyparentid ,q.salutationid ,q.isorganization ,q.organizationid  
--,q.applicationnumber ,q.verified ,q.issroapproved
--,q.districtcode  ,q.talukcode  
--,q.hoblicode ,q.villagecode ,q.tanno ,q.yearofincorp ,q.orgpoaauthsignfname
--,q.orgpoaauthsignmname ,q.orgpoaauthsignlname ,q.linkpartyid ,q.housenumber ,q.pin
--,q.propertyid ,q.propertynumber ,q.idprooftypeid ,q.isconsentwitness ,q.isprivateattendance
