--
-- Name: fn_fetch_citizen_dashboard(integer, timestamp without time zone, timestamp without time zone, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_citizen_dashboard(_applicationtypeid integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _propertytypeid integer DEFAULT NULL::integer) RETURNS TABLE(applicationsreceived bigint, applicationsapproved bigint, averagetime text, mediantime text, mintime text, maxtime text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$


DECLARE

BEGIN	

if _applicationtypeid=1 THEN --All document registration
	return query
	select 
	count(distinct a.applicationnumber) as ApplicationsReceived,
	count(distinct case when a.currentstatus='CD120'  then a.applicationnumber end ) as ApplicationsApproved,
	CASE
  WHEN EXTRACT(month FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((AVG(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as AverageTime,
CASE
  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) > 0 THEN
    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.registrationdatetime - d.presentdatetime))) || ' Minute(s) ' as MedianTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((MIN(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as MinTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((MAX(d.registrationdatetime - d.presentdatetime))::interval)) || ' Minute(s) ' as max_duration
	FROM kaverimrg.applicantapplicationdetails a
	join kaverimrg.propertymaster p on p.applicationnumber = a.applicationnumber
	join kaverimrg.documentmaster d on d.applicationnumber = a.applicationnumber
	where p.propertytypeid =_propertytypeid and d.presentdatetime::date >=_fromdate 
	and d.registrationdatetime::date <=_todate and a.applicationtypeid=_applicationtypeid
 and  d.registrationdatetime is not null;
       
elsif _applicationtypeid=12 then --All CC registration
	return query
