    EXTRACT(month FROM justify_interval((AVG(a.registrationenddate - ap.appointmentdate))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((AVG(a.registrationenddate - ap.appointmentdate))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((AVG(a.registrationenddate - ap.appointmentdate))::interval)) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval((AVG(a.registrationenddate - ap.appointmentdate))::interval)) > 0 THEN
    EXTRACT(hour FROM justify_interval((AVG(a.registrationenddate - ap.appointmentdate))::interval)) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval((AVG(a.registrationenddate - ap.appointmentdate))::interval)) || ' Minute(s) ' as AverageTime,
CASE
  WHEN EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) > 0 THEN
    EXTRACT(month FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) > 0 THEN
    EXTRACT(day FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) || ' Day(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) > 0 THEN
    EXTRACT(hour FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) || ' Hour(s) '
  ELSE ''
END ||
EXTRACT(minute FROM justify_interval(percentile_cont(0.5) WITHIN GROUP (ORDER BY a.registrationenddate - ap.appointmentdate))) || ' Minute(s) ' as MedianTime,
CASE
  WHEN EXTRACT(month FROM justify_interval((MIN(a.registrationenddate - ap.appointmentdate))::interval)) > 0 THEN
    EXTRACT(month FROM justify_interval((MIN(a.registrationenddate - ap.appointmentdate))::interval)) || ' Month(s) '
  ELSE ''
END ||
CASE
  WHEN EXTRACT(day FROM justify_interval((MIN(a.registrationenddate - ap.appointmentdate))::interval)) > 0 THEN
    EXTRACT(day FROM justify_interval((MIN(a.registrationenddate - ap.appointmentdate))::interval)) || ' Day(s) '
  ELSE ''
