ALTER FUNCTION kaverimrg.fn_fetch_citizen_dashboard_test2(_applicationtypeid integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _propertytypeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_closing_remarks(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_closing_remarks(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$


declare
v_array character varying[];
v_stampduty numeric;
v_registrationfees numeric;
v_reasonid integer;
v_markrtvalue bigint;
v_drorderno character varying;
v_minutedate text;
v_deptreferencecode character varying;
v_transdate text;
v_endorsementtext character varying;
v_districtname character varying;
v_delaycondonefees numeric;
v_endorsementKtext character varying;
v_delaydays integer;
BEGIN	
--Get the deficit stamp duty--
select sum(b.amountpaid) into v_stampduty
from kaverimrg.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode in (35,99,100);

--SRO market value 
select sum(p.sromarketvalue) into v_markrtvalue from kaverimrg.propertymaster p where p.applicationnumber =_applicationnumber; 

--Get the deficit registration fees--
select b.amountpaid into v_registrationfees
from kaverimrg.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 31;

--Get the DR Order details
select a.reasonid, a.dr_order_number, to_char(a.minutedate,'dd-MM-yyyy') into v_reasonid, v_drorderno, v_minutedate 
from kaverimrg.minutebook_data a where a.applicationnumber = _applicationnumber;

--Get Challan Payment Details
select distinct b.deptreferencecode, to_char(b.inserteddatetime,'dd-MM-yyyy') transdate 
into v_deptreferencecode, v_transdate
from kaverimrg.ams_reg_epaymentamtpaiddetails b right outer join kaverimrg.feesrequired c 
on b.applicationnumber=c.applicationnumber where b.applicationnumber = _applicationnumber 
and c.feerulecode in (35,99,100,31) and b.amountpaid=c.amountpaid;

--Get the district registrar office name--
select districtnamee into v_districtname from kaverimrg.sromaster sm left outer join kaverimrg.districtmaster dm on
sm.districtcode=dm.districtcode left outer join kaverimrg.documentmaster docm on docm.srocode=sm.srocode
where docm.applicationnumber=_applicationnumber;



--Now create text based on reason id

if (v_reasonid=1) then --If Under Valuation
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the market value of rs.',v_markrtvalue,' ','the property is decided. For the difference in market value the stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration on',' ',to_char(now(),'YYYY-MM-DD'));
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ಸ್ವತ್ತಿಗೆ',' ',v_markrtvalue,' ','ರೂಗಳ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯವನ್ನು ನಿಗದಿಪಡಿಸಿರುತ್ತಾರೆ. ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯಕ್ಕೆ ಕ್ರಮವಾಗಿ ರೂ',v_stampduty,'ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಮತ್ತು  ರೂ',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,' ರಂತೆ ದಿನಾಂಕ',v_transdate,'  ರಂದು ಪಾವತಿಸಿ',' ',to_char(now(),'YYYY-MM-DD'),'ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=2) then --If Impound
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the difference of stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration.');
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ  ದಸ್ತಾವೇಜನ್ನು ಪರಿಬದ್ದಗೊಳಿಸಿ ಆದೇಶಿಸಲಾಗಿದೆ .ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ರೂ',v_stampduty,',',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,'ರಂತೆ ದಿನಾಂಕ',v_transdate,'ರಂದು ಪಾವತಿಸಿ',to_char(now(),'YYYY-MM-DD'),'. ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=3) then --If Delay Condonation
--Get the delay condonation fees--
select b.amountpaid into v_delaycondonefees
from kaverimrg.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 28;

--Get the delayed days--
select date_part('day', presentdatetime - executiondatetime) - 122 into v_delaydays from kaverimrg.documentmaster where applicationnumber = _applicationnumber;

v_endorsementtext:=concat('Acceptance for registration/admission to registration was directed by the District Registrar of ',v_districtname,' in his order No. ',v_drorderno,' dated ',v_minutedate,' on payment of the fine Rs. ',v_delaycondonefees,' for a delay of ',v_delaydays,' days under Section 25/ Section 34 of the Registration Act 1908. ');
v_endorsementKtext:=concat('ನೋಂದಣಿ ಸ್ವೀಕಾರ / ಅಂಗೀಕಾರ ನೋಂದಣಿ ಕಾಯ್ದೆ 1908ರ ಪ್ರಕರಣ 25 / ಪ್ರಕರಣ 34ರ ಕೆಳಗೆ',v_delaydays,'ವಿಳಂಬಕ್ಕೆ ಶುಲ್ಕ ಮತ್ತು ದಂಡ ಒಟ್ಟು ರೂ.',v_delaycondonefees,'ಪಾವತಿಯಾದ ನಂತರ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು',v_districtname,' ರವರ ಆದೇಶ ಸಂಖ್ಯೆ',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ನೋಂದಣಿಗೆ ಸ್ವೀಕರಿಸಿದೆ /ಒಪ್ಪಿದೆ.');
elsif (v_reasonid=4) then --If Party Appearance
v_endorsementtext:='On completion of all the party appearance and admission of execution document is ordered for registration.';
v_endorsementKtext:='ಎಲ್ಲಾ ಪಕ್ಷಗಾರರು ಹಾಜರಾಗಿ ದಸ್ತಾವೇಜನ್ನು ಬರೆದು  ಕೊಟ್ಟಿದಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಾರೆ';
elsif (v_reasonid=5) then --If Private Attendance
v_endorsementtext:='After private appearance, the document is ordered for registration.';
v_endorsementKtext:='ಖಾಸಗಿ ಹಾಜರಾತಿಯ ನಂತರ, ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ';
end if;
v_array:=array[v_endorsementtext,v_endorsementKtext];
return array_to_json(v_array);
END;
$$;


