--Now create text based on reason id

if (v_reasonid=1) then --If Under Valuation
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the market value of rs.',' ','the property is decided. For the difference in market value the stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration on',' ',to_char(now(),'YYYY-MM-DD'));
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ಸ್ವತ್ತಿಗೆ','---','ರೂಗಳ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯವನ್ನು ನಿಗದಿಪಡಿಸಿರುತ್ತಾರೆ. ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ಮಾರುಕಟ್ಟೆ ಮೌಲ್ಯಕ್ಕೆ ಕ್ರಮವಾಗಿ ರೂ',v_stampduty,'ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಮತ್ತು  ರೂ',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,' ರಂತೆ ದಿನಾಂಕ',v_transdate,'  ರಂದು ಪಾವತಿಸಿ',' ',to_char(now(),'YYYY-MM-DD'),'ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=2) then --If Impound
v_endorsementtext:=concat('As per the district registrar order No. ',v_drorderno,' dated ',v_minutedate,' the difference of stamp duty of Rs. ',v_stampduty,' and Reg fee of Rs. ',v_registrationfees,' Is paid vide challan No. ',v_deptreferencecode,' Date ',v_transdate,'. Hence the document is ordered for registration.');
v_endorsementKtext:=concat('ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳ ಆದೇಶ ಸಂಖ್ಯೆಯೆ.',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ  ದಸ್ತಾವೇಜನ್ನು ಪರಿಬದ್ದಗೊಳಿಸಿ ಆದೇಶಿಸಲಾಗಿದೆ .ಮಾನ್ಯ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು  ಆದೇಶದಂತೆ ವೆತ್ಯಾಸದ ರೂ',v_stampduty,',',v_registrationfees,'ಗಳ ನೋಂದಣಿ ಶುಲ್ಕವನ್ನು ಚಲನ್ ಸಂಖ್ಯೆ',v_deptreferencecode,'ರಂತೆ ದಿನಾಂಕ',v_transdate,'ರಂದು ಪಾವತಿಸಿ',to_char(now(),'YYYY-MM-DD'),'. ದಿನಾಂಕದಂದು ಉಪ ನೋಂದಣಿ ಕಛೇರಿಗೆ ಹಾಜರುಪಡಿಸಲಾಗಿದ್ದು ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ.');
elsif (v_reasonid=3) then --If Delay Condonation
--Get the delay condonation fees--
select b.amountpaid into v_delaycondonefees
from kaverimrg.feesrequired b where applicationnumber=_applicationnumber and b.feerulecode = 28;

--Get the delayed days--
select date_part('day', presentdatetime - executiondatetime) - 122 into v_delaydays from kaverimrg.documentmaster where applicationnumber = _applicationnumber;

v_endorsementtext:=concat('Acceptance for registration/admission to registration was directed by the District Registrar of ',v_districtname,' in his order No. ',v_drorderno,' dated ',v_minutedate,' on payment of the fine Rs. ',v_delaycondonefees,' for a delay of ',v_delaydays,' days under Section 25/ Section 34 of the Registration Act 1908. ');
v_endorsementKtext:=concat('ನೋಂದಣಿ ಸ್ವೀಕಾರ / ಅಂಗೀಕಾರ ನೋಂದಣಿ ಕಾಯ್ದೆ 1908ರ ಪ್ರಕರಣ 25 / ಪ್ರಕರಣ 34ರ ಕೆಳಗೆ',v_delaydays,'ವಿಳಂಬಕ್ಕೆ ಶುಲ್ಕ ಮತ್ತು ದಂಡ ಒಟ್ಟು ರೂ.',v_delaycondonefees,'ಪಾವತಿಯಾದ ನಂತರ ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಗಳು',v_districtname,' ರವರ ಆದೇಶ ಸಂಖ್ಯೆ',v_drorderno,'ದಿನಾಂಕ',v_minutedate,'ರಂತೆ ನೋಂದಣಿಗೆ ಸ್ವೀಕರಿಸಿದೆ /ಒಪ್ಪಿದೆ.');
elsif (v_reasonid=4) then --If Party Appearance
v_endorsementtext:='On completion of all the party appearance and admission of execution document is ordered for registration.';
v_endorsementKtext:='ಎಲ್ಲಾ ಪಕ್ಷಗಾರರು ಹಾಜರಾಗಿ ದಸ್ತಾವೇಜನ್ನು ಬರೆದು  ಕೊಟ್ಟಿದಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಾರೆ';
elsif (v_reasonid=5) then --If Private Attendance
v_endorsementtext:='After private appearance, the document is ordered for registration.';
v_endorsementKtext:='ಖಾಸಗಿ ಹಾಜರಾತಿಯ ನಂತರ, ದಸ್ತಾವೇಜನ್ನು ನೋಂದಣಿಗೆ ಆದೇಶಿಸಿದೆ';
end if;
v_array:=array[v_endorsementtext,v_endorsementKtext];
return array_to_json(v_array);
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_closing_remarks_040523(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_courtorder_details(integer, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_courtorder_details(_srocode integer, _villagecode integer, _propertytypeid integer, _propertytynumber character varying, _surveyno integer DEFAULT NULL::integer, _hissano character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
--v_surveyhisno json;

--v_courtdetalsh json ;

begin
--	select row_to_json(app_json_d) into v_surveyhisno from (
--	select e.survey_no,e.hissa_no from kaverimrg.bannedpropertynumbers e 
--	join kaverimrg.bannedproperties b on e.propertyid=b.propertyid 
--	where e.survey_no =_surveyno and e.hissa_no=_hissano and b.villagecode=_villagecode
--	)app_json_d;

if(_surveyno is  null or _hissano is null or _propertytypeid<>1 )  then
	
--RETURN QUERY
select array_to_json(array_agg(row_to_json(courtorder)))
from (select c.ordernumber, c.issuingauthority, c.issueddate, c.description, c.casetype from kaverimrg.courtorders c join
kaverimrg.bannedpropertynumbers a on c.courtorderid=a.orderid and c.srocode=a.srocode
join
kaverimrg.bannedproperties b on a.orderid =b.orderid and b.srocode=a.srocode and b.courtpropertyid=a.propertyid
where a.srocode=_srocode and a.currentpropertytypeid=_propertytypeid and a.currentnumber=_propertytynumber 
and b.villagecode=_villagecode and c.isinforce=true and c.iscancelled=False) courtorder into v_data_json;
	  

elseif(_surveyno is not null or _hissano is not null or _surveyno=1) 
then

select array_to_json(array_agg(row_to_json(courtorder)))
from (select c.ordernumber, c.issuingauthority, c.issueddate, c.description, c.casetype from kaverimrg.courtorders c join
kaverimrg.bannedpropertynumbers a on c.courtorderid=a.orderid and c.srocode=a.srocode
join
kaverimrg.bannedproperties b on a.orderid =b.orderid and b.srocode=a.srocode and b.courtpropertyid=a.propertyid 
where a.srocode=_srocode and a.survey_no =_surveyno and a.hissa_no=_hissano 
and b.villagecode=_villagecode and c.isinforce=true and c.iscancelled=False) courtorder into v_data_json;

end if;

return v_data_json;
end
$$;


