--
-- Name: fn_fetch_courtorder_propertytype_json(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_courtorder_propertytype_json(p_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
v_propertytypeid integer;
v_applicationnumber text;
BEGIN
--select propertytypeid into v_propertytypeid from kaverimrg.propertytypemaster where propertytypeid = p_propertytypeid;
--if (v_propertytypeid = 20) and (v_applicationnumber = p_applicationnumber) then
select row_to_json(app_json) into v_data_json
from (
	   select array_to_json(array_agg(row_to_json(agri)))
      from (SELECT applicationnumber,
    propertyid,
    sro,
    court_order_number,
    injuction_or_stay_flag,
    survey_no,
    currentnumber,
    oldnumber,
    eastboundary,
    westboundary,
    northboundary,
    southboundary,
    area,
    description AS court_order_details,
    currentpropertytypeid,
    oldpropertytypeid,
    hissa_no,
    propertytypename, 
	--end if;
--if (v_propertytypeid = 28) and (v_applicationnumber = p_applicationnumber) then
	 ( select array_to_json(array_agg(row_to_json(Non_Agriculture)))
      from (select applicationnumber,
    propertyid,
    sro,
    court_order_number,
    injuction_or_stay_flag,
    survey_no,
    currentnumber,
    oldnumber,
    eastboundary,
    westboundary,
    northboundary,
    southboundary,
    area,
    description AS court_order_details,
    currentpropertytypeid,
    oldpropertytypeid,
    hissa_no--,
    --propertytypename 
			from kaverimrg.vw_court_order_non_agri where 
			currentpropertytypeid = 20 and applicationnumber = p_applicationnumber
) Non_Agriculture) as nonagri
from kaverimrg.vw_fetch_court_order_details
where currentpropertytypeid = 17 and applicationnumber = p_applicationnumber)agri
)app_json;
--end if;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_courtorder_propertytype_json(p_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_cvc_reports(character varying, bigint, bigint, bigint, bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_cvc_reports(_status character varying, _srocode bigint DEFAULT NULL::bigint, _roadcode bigint DEFAULT NULL::bigint, _villagecode bigint DEFAULT NULL::bigint, _hoblicode bigint DEFAULT NULL::bigint, _talukcode bigint DEFAULT NULL::bigint, _districtcode bigint DEFAULT NULL::bigint, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srocode integer, sronamee character varying, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying, roadcode bigint, roadnamee character varying, roadnamek character varying, propertytypeid integer, propertytypename character varying, agrilandtypenamee character varying, oldrate numeric, newrate numeric, measurementcode integer, measurementnamee character varying, effectivedate timestamp without time zone, circularyear integer, circularinfo text, roadaddedby text, roadrejby text, remarks text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	


	if (pagenumber<>-1 and pagesize<>-1) then
		PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select distinct 
		s.srocode,
		s.sronamee,
		d.districtcode,
		d.districtnamee,
		t.talukcode,
		t.taluknamee,
		h.hoblicode,
		h.hoblinamee,
		v.villagecode,
		v.villagenamee,
		mvd.roadcode,
		r.roadnamee,
		r.roadnamek,
		mvd.propertytypeid,
		p.propertytypename,
		a.agrilandtypenamee,
		case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,
        case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        m.measurementcode,
		m.measurementnamee,
		mv.effectivedate,
		mv.circularyear,
		mv.circularinfo,
		d1.firstname as roadaddedby,
		d2.firstname as roadapprorejby,
		mvd.remarks
		
	
from kaverimrg.mas_valratedetail mvd
left join kaverimrg.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaverimrg.measurementmaster m on m.measurementcode = mvd.unitid
left join kaverimrg.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode
left join kaverimrg.openbuiltratedetail o on mvd.roadcode = o.roadcode 
left join kaverimrg.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode
inner join kaverimrg.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaverimrg.roadmaster r on mvd.roadcode = r.roadcode
inner join kaverimrg.villagemaster v on r.villagecode = v.villagecode
left join kaverimrg.agrilandtypemaster a on a.agrilandtypeid = mvd.agrilandtypeid 
left join kaverimrg.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaverimrg.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaverimrg.talukmaster t on t.talukcode = v.talukcode 
left join kaverimrg.districtmaster d on t.districtcode = d.districtcode
left join kaverimrg.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaverimrg.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where

( CASE  when _from_date is not null and _to_date is not null then 
     mv.effectivedate between _from_date and  (_to_date + interval '1 day')
 else true end)

and 

( CASE  WHEN _status is not null THEN  mvd.isapproved = _status::boolean   
		ELSE mvd.isapproved is null  END )
 and 
 (CASE  WHEN _srocode is not null THEN  mvd.srocode = _srocode   ELSE true   END )
 and 
 (CASE WHEN _roadcode is not null THEN  mvd.roadcode = _roadcode  ELSE true  END )
  and 
  (CASE WHEN _roadcode is not null THEN  mvd.roadcode = _roadcode  ELSE true  END )
  and 
  ( CASE WHEN _villagecode is not null THEN  r.villagecode = _villagecode  ELSE true  END )
  
  and 
  
  ( case WHEN _hoblicode is not null THEN  h.hoblicode = _hoblicode   ELSE true   END )
  and 
  
  ( case  WHEN _talukcode is not null THEN  t.talukcode = _talukcode  ELSE true   END)
  
   and 
  
  ( CASE   WHEN _districtcode is not null THEN  d.districtcode = _districtcode  ELSE true  END )
  
   and 
  
  ( case  WHEN _districtcode is not null THEN  d.districtcode = _districtcode   ELSE true  END )
  
    

 ),cte_count as (select count(*) as total_rows from cte)
   select * from cte
   right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber=-1 or  pagesize=-1) then 

return query
with cte as (select distinct 
		s.srocode,
		s.sronamee,
		d.districtcode,
		d.districtnamee,
		t.talukcode,
		t.taluknamee,
		h.hoblicode,
		h.hoblinamee,
		v.villagecode,
		v.villagenamee,
		mvd.roadcode,
		r.roadnamee,
		r.roadnamek,
		mvd.propertytypeid,
		p.propertytypename,
		a.agrilandtypenamee,
		case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,
        case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        m.measurementcode,
		m.measurementnamee,
		mv.effectivedate,
		mv.circularyear,
		mv.circularinfo,
		d1.firstname as roadaddedby,
		d2.firstname as roadapprorejby,
		mvd.remarks
from kaverimrg.mas_valratedetail mvd
left join kaverimrg.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaverimrg.measurementmaster m on m.measurementcode = mvd.unitid
left join kaverimrg.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode
left join kaverimrg.openbuiltratedetail o on mvd.roadcode = o.roadcode 
left join kaverimrg.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode
inner join kaverimrg.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaverimrg.roadmaster r on mvd.roadcode = r.roadcode
inner join kaverimrg.villagemaster v on r.villagecode = v.villagecode
left join kaverimrg.agrilandtypemaster a on a.agrilandtypeid = mvd.agrilandtypeid 
left join kaverimrg.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaverimrg.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaverimrg.talukmaster t on t.talukcode = v.talukcode 
left join kaverimrg.districtmaster d on t.districtcode = d.districtcode
left join kaverimrg.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaverimrg.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where

( CASE  when _from_date is not null and _to_date is not null then 
     mv.effectivedate between _from_date and  (_to_date + interval '1 day')
 else true end)

and 

( CASE  WHEN _status is not null THEN  mvd.isapproved = _status::boolean   
		ELSE  true
		
		END )
 and 
 (CASE  WHEN _srocode is not null THEN  mvd.srocode = _srocode   ELSE true   END )
 and 
 (CASE WHEN _roadcode is not null THEN  mvd.roadcode = _roadcode  ELSE true  END )
  and 
  (CASE WHEN _roadcode is not null THEN  mvd.roadcode = _roadcode  ELSE true  END )
  and 
  ( CASE WHEN _villagecode is not null THEN  r.villagecode = _villagecode  ELSE true  END )
  
  and 
  
  ( case WHEN _hoblicode is not null THEN  h.hoblicode = _hoblicode   ELSE true   END )
  and 
  
  ( case  WHEN _talukcode is not null THEN  t.talukcode = _talukcode  ELSE true   END)
  
   and 
  
  ( CASE   WHEN _districtcode is not null THEN  d.districtcode = _districtcode  ELSE true  END )
  
   and 
  
  ( case  WHEN _districtcode is not null THEN  d.districtcode = _districtcode   ELSE true  END )
  
    

 )
   select cte.*,null::bigint as totalcount from cte	;


end if;

end;
$$;


