ALTER FUNCTION kaverimrg.fn_fetch_cvc_reports_1(_status character varying, _srocode bigint, _roadcode bigint, _villagecode bigint, _hoblicode bigint, _talukcode bigint, _districtcode bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_cvc_reports_18102023(character varying, bigint, bigint, bigint, bigint, bigint, bigint, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_cvc_reports_18102023(_status character varying, _srocode bigint DEFAULT NULL::bigint, _roadcode bigint DEFAULT NULL::bigint, _villagecode bigint DEFAULT NULL::bigint, _hoblicode bigint DEFAULT NULL::bigint, _talukcode bigint DEFAULT NULL::bigint, _districtcode bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying, srocode integer, sronamee character varying, villagecode bigint, villagenamee character varying, hoblicode integer, hoblinamee character varying, talukcode integer, taluknamee character varying, districtcode integer, districtnamee character varying, roadaddedby text, roadrejby text, remarks text, newrate numeric, oldrate numeric, propertytypeid integer, propertytypename character varying, effectivedate timestamp without time zone, circularinfo text, circularyear integer, measurementcode integer, measurementnamee character varying, regionname character varying, agrilandtypenamee character varying, newroad_yn character varying, updateddate timestamp without time zone, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

	if( _status = 'true' and _srocode is not null) then
return query
with cte as (select distinct mvd.roadcode,
        r.roadnamee,
        r.roadnamek,
        s.srocode,
        s.sronamee,
        v.villagecode,
        v.villagenamee,
        h.hoblicode,
        h.hoblinamee,
        t.talukcode,
        t.taluknamee,
        d.districtcode,
        d.districtnamee,
        d1.firstname as roadaddedby,
        d2.firstname as roadapprorejby,
        mvd.remarks,
        case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then mvd.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvd.rate   
        end as newrate,
        case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,     
        mvd.propertytypeid,
        p.propertytypename,
        mv.effectivedate,
        mv.circularinfo,
        mv.circularyear,
        m.measurementcode,
        m.measurementnamee,
        r3.regionname,
        a.agrilandtypenamee,
        case when r.roadcode in (select r5.roadcode from kaverimrg.rateagriculturaldetail r5 union 
        						 select o5.roadcode from kaverimrg.openbuiltratedetail o5 union 
        						 select mvf5.roadid from kaverimrg.mas_val_flatrates mvf5) then 'Yes'::character varying
        else 'No'::character varying end as Newroad_YN,
        mvd.updateddate
from kaverimrg.mas_valratedetail mvd
left join kaverimrg.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaverimrg.measurementmaster m on m.measurementcode = mvd.unitid
left join kaverimrg.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode and mvd.agrilandtypeid = r2.agrilandtypeid 
left join kaverimrg.openbuiltratedetail o on mvd.roadcode = o.roadcode and mvd.propertytypeid = o.propertytypeid 
left join kaverimrg.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode and mvd.propertytypeid = mvf.propertytypeid 
left join kaverimrg.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaverimrg.agrilandtypemaster a on a.agrilandtypeid = r2.agrilandtypeid
left join kaverimrg.roadmaster r on mvd.roadcode = r.roadcode
left join kaverimrg.regionmaster r3 on r3.regionid = r.regionid 
left join kaverimrg.villagemaster v on r.villagecode = v.villagecode
left join kaverimrg.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaverimrg.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaverimrg.talukmaster t on t.talukcode = v.talukcode 
left join kaverimrg.districtmaster d on t.districtcode = d.districtcode
left join kaverimrg.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaverimrg.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where mvd.isapproved = _status::boolean
