        r.roadnamee,
        r.roadnamek,
        s.srocode,
        s.sronamee,
        v.villagecode,
        v.villagenamee,
        h.hoblicode,
        h.hoblinamee,
        t.talukcode,
        t.taluknamee,
        d.districtcode,
        d.districtnamee,
        d1.firstname as roadaddedby,
        d2.firstname as roadapprorejby,
        mvd.remarks,
--        mvd.rate as newrate,
        case when mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate 
             when mvd.propertytypeid = o.propertytypeid then mvd.rate
             when mvd.propertytypeid = mvf.propertytypeid then mvd.rate
             end as newrate,
        case when mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate 
             when mvd.propertytypeid = o.propertytypeid then o.rate
             when mvd.propertytypeid = mvf.propertytypeid then mvf.rate
             end as oldrate,
        mvd.propertytypeid,
        p.propertytypename,
        mv.effectivedate,
        mv.circularinfo,
        mv.circularyear,
        m.measurementcode,
        m.measurementnamee
from kaverimrg.mas_valratedetail mvd
left join kaverimrg.mas_valrateheader mv on mv.valrateheaderid = mvd.valrateheaderid 
inner join kaverimrg.measurementmaster m on m.measurementcode = mvd.unitid
left join kaverimrg.rateagriculturaldetail r2 on mvd.roadcode = r2.roadcode
left join kaverimrg.openbuiltratedetail o on mvd.roadcode = o.roadcode 
left join kaverimrg.mas_val_flatrates mvf on mvf.roadid = mvd.roadcode
inner join kaverimrg.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaverimrg.roadmaster r on mvd.roadcode = r.roadcode
inner join kaverimrg.villagemaster v on r.villagecode = v.villagecode
left join kaverimrg.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaverimrg.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaverimrg.talukmaster t on t.talukcode = v.talukcode 
left join kaverimrg.districtmaster d on t.districtcode = d.districtcode
left join kaverimrg.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaverimrg.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where mvd.isapproved = _status::boolean
and mvd.srocode = _srocode
--and mvd.roadcode = _roadcode;
--and v.villagecode = _villagecode; 
