inner join kaverimrg.propertytypemaster p on p.propertytypeid = mvd.propertytypeid
left join kaverimrg.roadmaster r on mvd.roadcode = r.roadcode
inner join kaverimrg.villagemaster v on r.villagecode = v.villagecode
left join kaverimrg.sromaster s on s.srocode = v.srocode and mvd.srocode = s.srocode
left join kaverimrg.hoblimaster h on h.hoblicode = v.hoblicode 
left join kaverimrg.talukmaster t on t.talukcode = v.talukcode 
left join kaverimrg.districtmaster d on t.districtcode = d.districtcode
left join kaverimrg.departmentusers d1 on d1.userid = mvd.sfdaid
left join kaverimrg.departmentusers d2 on mvd.updatedby::bigint = d2.userid
where mvd.isapproved is null
--and mvd.srocode = _srocode;
--and mvd.roadcode = _roadcode;
--and v.villagecode = _villagecode;
--and h.hoblicode = _hoblicode; 
--and t.talukcode = _talukcode;
and d.districtcode = _districtcode
OFFSET PageOffset   
FETCH NEXT pagesize ROWS ONLY;

end if;
end;
$$;


