--
-- Name: fn_fetch_cvc_reports_30102023(character varying, bigint, bigint, bigint, bigint, bigint, bigint, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_cvc_reports_30102023(_status character varying, _srocode bigint DEFAULT NULL::bigint, _roadcode bigint DEFAULT NULL::bigint, _villagecode bigint DEFAULT NULL::bigint, _hoblicode bigint DEFAULT NULL::bigint, _talukcode bigint DEFAULT NULL::bigint, _districtcode bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying, srocode integer, sronamee character varying, villagecode bigint, villagenamee character varying, hoblicode integer, hoblinamee character varying, talukcode integer, taluknamee character varying, districtcode integer, districtnamee character varying, roadaddedby text, roadrejby text, remarks text, newrate numeric, oldrate numeric, propertytypeid integer, propertytypename character varying, effectivedate timestamp without time zone, circularinfo text, circularyear integer, measurementcode integer, measurementnamee character varying, regionname character varying, agrilandtypenamee character varying, newroad_yn character varying, updateddate timestamp without time zone, totalcount bigint)
