ALTER FUNCTION kaverimrg.fn_fetch_cvc_reports_backup_24_sept_23(_status character varying, _srocode bigint, _roadcode bigint, _villagecode bigint, _hoblicode bigint, _talukcode bigint, _districtcode bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_cvc_reports_bck(character varying, bigint, bigint, bigint, bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_cvc_reports_bck(_status character varying, _srocode bigint DEFAULT NULL::bigint, _roadcode bigint DEFAULT NULL::bigint, _villagecode bigint DEFAULT NULL::bigint, _hoblicode bigint DEFAULT NULL::bigint, _talukcode bigint DEFAULT NULL::bigint, _districtcode bigint DEFAULT NULL::bigint, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srocode integer, sronamee character varying, districtcode integer, districtnamee character varying, talukcode integer, taluknamee character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, villagenamee character varying, roadcode bigint, roadnamee character varying, roadnamek character varying, propertytypeid integer, propertytypename character varying, agrilandtypenamee character varying, oldrate numeric, newrate numeric, measurementcode integer, measurementnamee character varying, effectivedate timestamp without time zone, circularyear integer, circularinfo text, roadaddedby text, roadrejby text, remarks text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	


	if (pagenumber<>-1 and pagesize<>-1) then
		PageOffset := ((pagenumber - 1) * pagesize);
return query
with cte as (select distinct 
		s.srocode,
		s.sronamee,
		d.districtcode,
		d.districtnamee,
		t.talukcode,
		t.taluknamee,
		h.hoblicode,
		h.hoblinamee,
		v.villagecode,
		v.villagenamee,
		mvd.roadcode,
		r.roadnamee,
		r.roadnamek,
		mvd.propertytypeid,
		p.propertytypename,
		a.agrilandtypenamee,
		case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
        	 when mvd.roadcode in (select mvf2.roadid from kaverimrg.mas_val_flatrates mvf2) and mvd.propertytypeid = mvf.propertytypeid then mvf.rate
        end as oldrate,
        case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then mvd.rate
