	    when (_status = 'false' and _talukcode is not null) then mvd.isapproved = _status::boolean and t.talukcode = _talukcode 
	    when (_status is null and _talukcode is not null) then mvd.isapproved is null and t.talukcode = _talukcode 
	    when (_status = 'true' and _districtcode is not null) then mvd.isapproved = _status::boolean and d.districtcode = _districtcode 
	    when (_status = 'false' and _districtcode is not null) then mvd.isapproved = _status::boolean and d.districtcode = _districtcode 
	    when (_status is null and _districtcode is not null) then mvd.isapproved is null and d.districtcode = _districtcode 
	    when (_from_date is not null and _to_date is not null) then mv.effectivedate between _from_date and  (_to_date + interval '1 day')end)
	   ,cte_count as (select count(*) as total_rows from cte)
select * from cte
right join (select total_rows from cte_count) total_row on true 
