		case when mvd.roadcode in (select r3.roadcode from kaverimrg.rateagriculturaldetail r3) and mvd.agrilandtypeid = r2.agrilandtypeid then r2.rate
        	 when mvd.roadcode in (select o.roadcode from kaverimrg.openbuiltratedetail o) and mvd.propertytypeid = o.propertytypeid then o.rate
