--
-- Name: fn_fetch_district_taluk_hob_village_name(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_district_taluk_hob_village_name(_villagecode bigint) RETURNS TABLE(kaverimrgdistrictnamee character varying, kaverimrgtaluknamee character varying, kaverimrghobliname character varying, kaverimrgvillagename character varying, bhoomidistrictnamee character varying, bhoomitaluknamee character varying, bhoomihobliname character varying, bhoomivillagename character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
 
 return query
 

select 
dsm.districtnamee as kaverimrgdistrictname,
tm.taluknamee as kaverimrgtalukname,
hm.hoblinamee as kaverimrghobliname,
v.villagenamee as kaverimrgvillagename,
b.districtnamee as bhoomidistrictname,
b.bhoomitalukname as bhoomitalukname,
b.bhoomihobiname,
b.bhoomivillagename 
from 
kaverimrg.villagemaster v 
join kaverimrg.talukmaster tm on tm.talukcode = v.talukcode
join kaverimrg.hoblimaster hm on hm.hoblicode = v.hoblicode
join kaverimrg.districtmaster dsm on dsm.districtcode = tm.districtcode
join kaverimrg.bhoomimappingdetails b on  b.kaverimrgvillagecode=v.villagecode 

where villagecode=_villagecode;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_district_taluk_hob_village_name(_villagecode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_district_taluk_hob_village_name(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_district_taluk_hob_village_name(_districtcode bigint, _talukcode bigint, _hoblicode bigint, _villagecode bigint) RETURNS TABLE(kaverimrgdistrictnamee character varying, kaverimrgtaluknamee character varying, kaverimrghobliname character varying, kaverimrgvillagename character varying, bhoomidistrictnamee character varying, bhoomitaluknamee character varying, bhoomihobliname character varying, bhoomivillagename character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN	
 return query
 
 select 
dsm.districtnamee as kaverimrgdistrictname,
tm.taluknamee as kaverimrgtalukname,
hm.hoblinamee as kaverimrghobliname,
v.villagenamee as kaverimrgvillagename,
b.districtnamee as bhoomidistrictname,
btk.talukaname as bhoomitalukname,
btm.villagename as bhoomivillagename,
btm.hobliname as bhoomihobliname
from 
kaverimrg.villagemaster v 
join kaverimrg.talukmaster tm on tm.talukcode = v.talukcode
join kaverimrg.hoblimaster hm on hm.hoblicode = v.hoblicode
join kaverimrg.districtmaster dsm on dsm.districtcode = tm.districtcode
join kaverimrg.bhoomimappingdetails b on  b.kaverimrgvillagecode=v.villagecode
join kaverimrg.bhoomitalukamapping btm on  btm.villagecode = v.villagecode
join kaverimrg.bhoomitaluk btk on btk.talukacode=btm.talukacode
where  b.bhoomidistrictcode = _districtcode
and b.bhoomitalukcode = _talukcode
and b.bhoomihobicode = _hoblicode
and b.bhoomivillagecode = _villagecode;


end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_district_taluk_hob_village_name(_districtcode bigint, _talukcode bigint, _hoblicode bigint, _villagecode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_doc_data_doc_summary(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_doc_data_doc_summary(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $_$
declare 
v_data_json1 json;
begin
	select row_to_json(app_json) into v_data_json1
from (

 select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno, 
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, wi.address,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaverimrg.witnessinfo wi
			/*left join kaverimrg.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaverimrg.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaverimrg.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fs.valuatiotypeid=1 then true else false end) as isimpound,
	(case when fs.valuatiotypeid=3 then true else false end) as isundervalue
	from kaverimrg.applicantapplicationdetails ad
join kaverimrg.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaverimrg.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
join kaverimrg.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
join kaverimrg.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaverimrg.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
join kaverimrg.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaverimrg.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber) 
left join kaverimrg.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
join kaverimrg.sromaster ss on ss.srocode=ad.srocode 
left join kaverimrg.feesrequired fs on ad.applicationnumber=fs.applicationnumber
  where ad.applicationnumber = _applicationnumber  --and ad.currentstatus ='CD110'
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,
	ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks
	,dm.pendingdocumentnumber,md.ispendingdocument,fs.valuatiotypeid
	) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaverimrg.fn_fetch_doc_data_doc_summary(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_document_party_details(text, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_document_party_details(_applicationnumber text, _srocode bigint) RETURNS TABLE(applicationtypeid integer, finalregistrationnumber character varying, executiondatetime timestamp without time zone, pendingdocumentnumber character varying, book character varying, registrationdatetime timestamp without time zone, noofscanpages integer, applicationtype character varying, sroname character varying, partyinfo json)
    LANGUAGE plpgsql
    AS $$

declare 

BEGIN
return query
select ad.applicationtypeid,dm.finalregistrationnumber,
dm.executiondatetime executiondatetime,
dm.pendingdocumentnumber,bm.printablename as book,
dm.registrationdatetime registrationdatetime,
pm.sronoofscanpages as noofscnpages,svm.servicename as applicationtype,
sm.sronamee as sroname,
(
      select array_to_json(array_agg(row_to_json(prty)))
      from (

select 
applicationnumber,partyid,name as partyname,age, address ,profession,
phonenumber,epic,partytypeid,partytypename,isexecutor,ispresenter,admissiondate,
section88exemption,fingerid,thumbpath,photopath,idprooftypedesc,idproofnumber,
relationship,relativename,
isEndorsePrinted,gender as sex,
isprivateattendance,
vw_party.coveringletterno,thumbremarks 
from kaverimrg.vw_fetch_party vw_party 
			where vw_party.applicationnumber = ad.applicationnumber and
			vw_party.partytypeid in (1,2) order by partytypeid) prty
    ) as partyinfo

from kaverimrg.documentmaster dm 
inner join kaverimrg.sromaster sm on sm.srocode = dm.srocode 
inner join kaverimrg.applicantapplicationdetails ad ON ad.srocode = sm.srocode
inner join kaverimrg.partyinfo pi on pi.srocode = sm.srocode
inner join kaverimrg.propertymaster pm on pm.propertyid = pi.propertyid
inner join kaverimrg.servicesmaster svm on svm.serviceid = ad.applicationtypeid
left join kaverimrg.booktypemaster bm on (bm.bookid=dm.bookid) 
where  ad.applicationnumber = _applicationnumber and ad.srocode=_srocode;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_document_party_details(_applicationnumber text, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_documentsummary(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,ad.refuseremarks, 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,md.isbefore2003,  
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			z.zonenamee ,
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaverimrg.propertyschedules ps 
					left join kaverimrg.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername
					, pnam.firstname as name
					, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaverimrg.propertyschedules ps 
				  left join kaverimrg.vw_fetch_party pi on pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') AS firstname from kaverimrg.partyschedules ps1
					left join (select name,partyid from kaverimrg.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 on pi2.partyid = ps1.partyid 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaverimrg.propertynumberdetails pnd 
					 left join kaverimrg.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaverimrg.propertymaster pm 
		   left join kaverimrg.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid)
		   left join kaverimrg.zonemaster z on z.zoneid = pm.zoneid 
			left join kaverimrg.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaverimrg.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaverimrg.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaverimrg.sromaster c on (pm.srocode = c.srocode)
		   left join kaverimrg.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaverimrg.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaverimrg.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,
		sl.descriptione,vw_party.islateapperance		
		from kaverimrg.vw_fetch_party vw_party 
		left join kaverimrg.partywitness pw on vw_party.partyid=pw.partyid 
		left join  kaverimrg.salutationmaster sl on vw_party.salutationid=sl.salutationid
		left join kaverimrg.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber and
			vw_party.partytypeid in (1,2)
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
		,vw_party.aliasname,sl.descriptione,vw_party.islateapperance
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno, concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address,
			wi.age,wi.applicationnumber,wi.name,r.relatione as relation,wi.relativename,
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaverimrg.witnessinfo wi
			left join kaverimrg.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaverimrg.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaverimrg.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaverimrg.lgd_talukmaster g ON g.talukcode = wi.talukcode
			/*left join kaverimrg.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaverimrg.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaverimrg.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument,
	(case when fds.valuatiotypeid=1 then true else false end) as isundervaluation,
	(case when fds.valuatiotypeid=3 then true else false end) as isimpound,
	(case when dm.executiondatetime::date<(now()- interval '4 months')::date then true else false end) as isdelaycondonation 
  from kaverimrg.applicantapplicationdetails ad
inner join kaverimrg.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaverimrg.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join (select distinct applicationnumber,valuatiotypeid from kaverimrg.feesrequired fd where fd.applicationnumber=_applicationnumber) as fds on fds.applicationnumber=ad.applicationnumber 
 join kaverimrg.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
 join kaverimrg.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaverimrg.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaverimrg.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaverimrg.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaverimrg.sromaster ss on ss.srocode=ad.srocode
  where ad.applicationnumber = _applicationnumber 
  group by ad.applicationnumber,dm.executiondatetime,
  dm.presentdatetime ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,fds.valuatiotypeid,dm.executiondatetime,
	ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument,md.isbefore2003
) app_json ;

return v_data_json1;

END;
$_$;


ALTER FUNCTION kaverimrg.fn_fetch_documentsummary(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_documentsummary_json(text, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_documentsummary_json(_applicationnumber text, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $_$



declare 
v_data_json1 json;
BEGIN

select row_to_json(app_json) into v_data_json1
from (

  select ad.applicationnumber,dm.executiondatetime::date executedate,
  dm.presentdatetime as presentdate,
regexp_replace(dm.pendingdocumentnumber, '^([^-]*-[^-]*)-.*$', '\1') as pendingdocumentnumber ,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee as stamparticlename,ad.annexurepath,dm.uploaddocannexurepath,
	dm.partypaymentdetails,
ra.articlenamee as Naturedeed, bm.printablename as book,sm.servicename as applicationtype,
	ad.remarks,
	ad.remarksk,
	ss.sronamee as sroname ,--- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid,md.private_remark,
	ad.refuseremarks,
	md.isbefore2003,
	(select case when f.applicationnumber=_applicationnumber then true else false end as isfruits 
	 from kaverimrg.applicantapplicationdetails a join kaverimrg.fruits_data_recv_details f on a.applicationnumber=f.applicationnumber where a.applicationnumber=_applicationnumber) as isfruits , 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,
	md.ispendingdocument ,
	md.pendingregistrationnumber ,
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattendancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd,
			zn.zonenamee, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (
			/*  select ps.propertyid as propertyschedulespropertyid,ps.scheduletype,ps.totalarea,
			  ps.description as scheduledescription,
					case when pm.propertytypeid=17 then
					string_agg(pi.name,',') else null end as bhoomisellerparty ,

					pi.name, pi.ispresenter, pi.isexecutor			

					from kaverimrg.propertyschedules ps 
					left join kaverimrg.vw_fetch_party pi on (pi.propertyid = ps.propertyid 
					and pi.applicationnumber=ps.applicationnumber
						)
				   where ps.propertyid = pm.propertyid 
					group by ps.propertyid ,ps.scheduletype,ps.totalarea,ps.description,			
				  pi.name, pi.ispresenter, pi.isexecutor	*/

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaverimrg.propertyschedules ps 
				  left join kaverimrg.vw_fetch_party pi on pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') 
								AS firstname from kaverimrg.partyschedules ps1
			left join 
						(select name,partyid from kaverimrg.vw_fetch_party vf where vf.applicationnumber = _applicationnumber ) as pi2 
							 on pi2.partyid = ps1.partyid 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaverimrg.propertynumberdetails pnd 
					 left join kaverimrg.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaverimrg.propertymaster pm 
		   left join kaverimrg.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
		   left join kaverimrg.zonemaster zn on (pm.zoneid=zn.zoneid)
			left join kaverimrg.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			left join kaverimrg.stamprules sr on pm.stampruleid = sr.stampruleid
			left join kaverimrg.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		   left join  kaverimrg.sromaster c on (pm.srocode = c.srocode)
		   left join kaverimrg.villagemaster d on (pm.villagecode = d.villagecode)
			left join kaverimrg.hoblimaster h on d.hoblicode = h.hoblicode
		   left join kaverimrg.vw_fee_calculation_details_chk calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=ad.applicationnumber 	   
		   
		   ) prpty
    ) as propertyinfo,	
	 (
      select array_to_json(array_agg(row_to_json(prty)))
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,vw_party.name as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		/*isorganization, tanno, organizationid, yearofincorp, linkpartyid, auname, auaddress,
		 aualiasname, 
		auage, ausex, auidprooftypeid, auidprooftypedesc, auidproofnumber, auprofession,
		 poaisorganization,
		poaname, poaaddress, poaage, poasex, poaidproofnumber, poatan, poaprofession,
		 poarelationship, 
		poarelativename,poaidprooftypedesc, poapartytypename, poayearofincorp, 
		orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname, minorguardianname,
		 minorguardianage,
		minorguardianrelationship, minorguardianrelativename,*/
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused 
		from kaverimrg.vw_fetch_party vw_party 
		left join kaverimrg.partywitness pw on vw_party.partyid=pw.partyid 
		left join kaverimrg.witnessinfo wi on pw.witnessid = wi.witnessid 
			where vw_party.applicationnumber = ad.applicationnumber and
			vw_party.partytypeid in (1,2)
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused
			order by partytypeid) prty
    ) as partyinfo,
	(  select array_to_json(array_agg(row_to_json(witness)))
      from (select wi.witnessid, wi.name, wi.houseno,concat(wi.address,' ',d.districtnamee,' ',g.taluknamee,' ',s.statenamee) as address 
      ,wi.age,wi.applicationnumber,wi.name,r.relatione as relation,wi.relativename,  
			/* added a columns houseno, address, pincode and necessary joins for the same, on 07/11/2022 */
			/* Removed above changes, on 07/11/2022 */
			/*(wi.address::text || ', '::text) || (tal.taluknamee::text || ', '::text) || (dis.districtnamee::text || ', '::text) || (st.statenamee::text) || ' '::text AS address,*/
			wi.pincode, wi.age, wi.profession, wi.isEndorsePrinted, wi.sex 
			from kaverimrg.witnessinfo wi
			left join kaverimrg.relationshipmasters r on wi.relation::int =r.id 
			JOIN kaverimrg.lgd_districtmaster d ON d.districtcode = wi.districtcode
    		 JOIN kaverimrg.lgd_statemaster s ON d.lgdstatecode = s.statecode
     		JOIN kaverimrg.lgd_talukmaster g ON g.talukcode = wi.talukcode

			/*left join kaverimrg.lgd_districtmaster dis ON dis.districtcode = wi.districtcode
			left join kaverimrg.lgd_statemaster st ON st.statecode  = wi.statecode
			left join kaverimrg.lgd_talukmaster tal ON tal.talukcode = wi.talukcode*/
			where wi.applicationnumber = ad.applicationnumber) witness
	) as witnessinfo,
	md.ispendingdocument  as ispendingdocument
  from kaverimrg.applicantapplicationdetails ad
inner join kaverimrg.documentmaster dm on (ad.applicationnumber=dm.applicationnumber)
left join kaverimrg.minutebook_data md on (md.applicationnumber=ad.applicationnumber)
left join kaverimrg.servicesmaster sm on (sm.serviceid = ad.applicationtypeid)
left join kaverimrg.booktypemaster bm on (bm.bookid=dm.bookid)
left join kaverimrg.stamparticles sa on (sa.stamparticlecode=dm.stamparticlecode)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode=dm.regarticlecode)
left join kaverimrg.bhoomifileuploaddetails bh on (dm.finalregistrationnumber = bh.finalregistrationnumber)
left join kaverimrg.easthi_eswathu_fileuploaddetails ee on (dm.finalregistrationnumber =ee.finalregistrationnumber )
inner join kaverimrg.sromaster ss on ss.srocode=ad.srocode
  where ad.applicationnumber = _applicationnumber and ad.srocode=_srocode and ad.applicationnumber is not null and ad.srocode is not null
  group by ad.applicationnumber,dm.executiondatetime,md.pendingregistrationnumber,
  dm.presentdatetime ,md.isbefore2003,
	dm.finalregistrationnumber,dm.registrationdatetime,dm.isPrintEndorsement,
	dm.pagecount ,sa.articlenamee ,ad.annexurepath,dm.uploaddocannexurepath,dm.partypaymentdetails,
ra.articlenamee , bm.printablename ,sm.servicename ,
	ad.remarks,
		ad.remarksk,ss.sronamee, --- To fetch the Kannada text added on 28-11-2022
	ad.currentstatus,dm.isscancompleted,ad.applicationtypeid,md.remark_comment,md.reasonid ,md.private_remark,ad.refuseremarks,dm.pendingdocumentnumber,md.ispendingdocument
) app_json ;

return v_data_json1;

END;
$_$;


