	(select case when f.applicationnumber=_applicationnumber then true else false end as isfruits from kaverimrg.applicantapplicationdetails a join kaverimrg.fruits_data_recv_details f on a.applicationnumber=f.applicationnumber where a.applicationnumber=_applicationnumber) as isfruits , 
	string_agg(bh.acknowledgeno,',') as Ysavednumber,
	string_agg(ee.acknowledgeno,',') as acknowledgeno,
	md.ispendingdocument ,
	md.pendingregistrationnumber ,
     (
      select array_to_json(array_agg(row_to_json(prpty)))
      from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
