					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaverimrg.propertynumberdetails pnd 
					 left join kaverimrg.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
