from kaverimrg.ec_applicationdetails where applicationnumber = _applicationnumber;
--like 'TMPEC-00027'

if v_isappliedbydept = true
then

		if v_ispropertysearch = true 
		then
		
		select row_to_json(app_json) into v_data_json
