			a.ecid,
		    a.kaverimrgvillagecode,
		    b.villagenamee,
		    a.kaverimrghoblicode,
		    c.hoblinamee,
		    e.districtcode,
		    d.districtnamee,
		    c.talukcode,
		    f.taluknamee,
		    a.eastboundary AS east,
		    a.westboundary AS west,
		    a.northboundary AS north,
		    a.southboundary AS south,
		    a.easttowest,
		    a.northtosouth,
		    a.measurementunitid,
		   --  g.descriptionenglish AS units,
		    null AS units,
		    a.propertydescription AS descriptionofproperty,
		    a.searchfromdate AS fromdate,
		    a.searchtodate AS todate,
			a.ispropertysearch, -- 
			a.isnamesearch,  -- 
			--l.firstname,
		    --l.middlename,
		    --l.lastname,
			--l.phone,
			--l.email,
			a.applicationnumber,
			--l.permanentaddress as  address,
			a.kaverimrgsrocode,
			e.sronamee,
			a.area,
			a.hectare,
			a.acre,
			a.gunta,
			a.cents,
