		    a.searchtodate AS todate,
			a.ispropertysearch, -- 
			a.isnamesearch,  -- 
			l.firstname,
		    l.middlename,
		    l.lastname,
			l.phone,
			l.email,
			a.applicationnumber,
			l.permanentaddress as  address,
			a.kaverimrgsrocode,
			e.sronamee,
			a.area,
			a.hectare,
			a.acre,
			a.gunta,
			a.cents,
			a.easttowestmeasurement,
		    a.northtosouthmeasurement,
			a.propertytypeid,
			p.propertytypename as propertytype,
			--l.pin as pincode ,
			a.partyname ,
			a.isappliedbydept,
			a.reason,
			
			( select array_to_json(array_agg(row_to_json(propertynodetails)))
		      from (
			  select  i.propertynotypeid,
		    h.typenameenglish AS propertynumbertype,
			i.newpropertynumber AS propdetails,
			presentpropertydetails
				  from kaverimrg.ec_propertynumberdetails i
				  inner join kaverimrg.propertynotypemaster h on i.ecid = a.ecid and
				  h.propertytypeid = i.propertynotypeid  
			  )propertynodetails) as propnumberdetails,
			  
			
			( select array_to_json(array_agg(row_to_json(feesinfo)))
		      from (select  k.requiredfeeid,
		    k.feeruleid,
		    k.payableamount,
		    k.ispaid,
		    k.serviceid,
		    k.feedescription from
				kaverimrg.ec_requiredfees k 
		     JOIN kaverimrg.feesrulemaster m ON k.ecid = a.ecid and m.feerulecode = k.feeruleid
				   )feesinfo ) as feesdetails
				   
			FROM kaverimrg.ec_applicationdetails a
		     JOIN kaverimrg.villagemaster b ON a.kaverimrgvillagecode = b.villagecode
		     JOIN kaverimrg.hoblimaster c ON b.hoblicode = c.hoblicode
		     JOIN kaverimrg.talukmaster f ON f.talukcode = c.talukcode
		     JOIN kaverimrg.sromaster e ON e.srocode = a.kaverimrgsrocode
		     JOIN kaverimrg.districtmaster d ON d.districtcode = e.districtcode
		     JOIN kaverimrg.measunitmaster g ON g.unitid = a.measurementunitid::integer
			JOIN kaverimrg.citizenmaster l ON l.citizenid = a.userid
			JOIN kaverimrg.propertytypemaster p on p.propertytypeid = a.propertytypeid
			--JOIN kaverimrg.partyinfo pi on pi.applicationnumber::text = a.applicationnumber::text
		and a.applicationnumber = _applicationnumber
		) app_json ;
		
		
		else 
		
		select row_to_json(app_json) into v_data_json
