ALTER FUNCTION kaverimrg.fn_fetch_ec_details_json_check_temp(_applicationnumber text) OWNER TO postgres;

--
-- Name: ec_srch_property; Type: TABLE; Schema: kaverimrg; Owner: postgres
--

CREATE TABLE kaverimrg.ec_srch_property (
    _currentproperttypeid bigint,
    _currentnumber character varying
);


ALTER TABLE kaverimrg.ec_srch_property OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check(integer, kaverimrg.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_check(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
	
	
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.sroconsideration as consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber
-- pn.currentnumber AS aptno_new,
-- pn.oldnumber AS oldno
from  kaverimrg.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
-- Left Join is required at partyschedules and partyinfo to fetch propertyschedules where partyid is null
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null 
 then
 case when  ps.description is not null and  ps.description<>'' then  
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '))
 else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre') end 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps 
join kaverimrg.propertynumberdetails p on ps.propertyid=p.propertyid 
join kaverimrg.propertymaster pp on ps.propertyid=pp.propertyid 
left join kaverimrg.partyschedules pas on ps.propertyid=pas.propertyid 
left join kaverimrg.partyinfo pin on pas.partyid=pin.partyid 
join kaverimrg.villagemaster v2 on pp.villagecode=v2.villagecode 
join kaverimrg.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 
join kaverimrg.districtmaster d on tm.districtcode =d.districtcode 
where ps.propertyid = pm.propertyid and (p.currentpropertytypeid, p.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,p.hissa_no,ps.northboundary
		   ,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct p.partyid,
-- (
--        CASE
--            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS claimant,
          CASE
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	        END AS partyname,
        p.partytypeid ,
-- (
--        CASE
--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS executant,
        --# left join is necessary because in partyschedules table we are not capturing claimaint details
		     p.address from kaverimrg.partyinfo p
			left JOIN kaverimrg.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
			left JOIN kaverimrg.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
			left JOIN kaverimrg.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaverimrg.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaverimrg.salutationmaster s2 ON p2.salutationid = s2.salutationid
		--	left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
			where p.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		 join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from kaverimrg.propertymaster pm inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
--inner join kaverimrg.propertynumberdetails pn_src  on pm.propertyid = pn_src.propertyid and (pn_src.currentpropertytypeid, pn_src.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )  --and pn_src.srocode = v.srocode
join (select distinct propertyid from kaverimrg.propertynumberdetails p where(p.currentpropertytypeid, p.currentnumber) 
in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) ) as pn_src on pn_src.propertyid=pm.propertyid
inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
where  v.villagecode = _villagecode and dm.bookid not in (3, 4) and pm.ismovableproperty = false
and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate 
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_check(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_bb(integer, kaverimrg.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_check_bb(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
	
	
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.sroconsideration as consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber
-- pn.currentnumber AS aptno_new,
-- pn.oldnumber AS oldno
from  kaverimrg.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
-- Left Join is required at partyschedules and partyinfo to fetch propertyschedules where partyid is null
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null 
 then
 case when  ps.description is not null and  ps.description<>'' then  
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '))
 else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre') end 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps 
join kaverimrg.propertynumberdetails p on ps.propertyid=p.propertyid 
join kaverimrg.propertymaster pp on ps.propertyid=pp.propertyid 
left join kaverimrg.partyschedules pas on ps.propertyid=pas.propertyid 
left join kaverimrg.partyinfo pin on pas.partyid=pin.partyid 
join kaverimrg.villagemaster v2 on pp.villagecode=v2.villagecode 
join kaverimrg.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 
join kaverimrg.districtmaster d on tm.districtcode =d.districtcode 
where ps.propertyid = pm.propertyid and (p.currentpropertytypeid, p.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,p.hissa_no,ps.northboundary
		   ,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct pi.partyid,
-- (
--        CASE
--            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS claimant,
        concat(pi.firstname, pi.middlename, pi.lastname) as partyname,
        pi.partytypeid ,
-- (
--        CASE
--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS executant,
        --# left join is necessary because in partyschedules table we are not capturing claimaint details
		     pi.address from kaverimrg.partyinfo pi 
			left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
			where pi.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		 join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from kaverimrg.propertymaster pm inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
--inner join kaverimrg.propertynumberdetails pn_src  on pm.propertyid = pn_src.propertyid and (pn_src.currentpropertytypeid, pn_src.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )  --and pn_src.srocode = v.srocode
join (select distinct propertyid from kaverimrg.propertynumberdetails p where(p.currentpropertytypeid, p.currentnumber) 
in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) ) as pn_src on pn_src.propertyid=pm.propertyid
inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
where  v.villagecode = _villagecode and dm.bookid not in (3, 4) and pm.ismovableproperty = false
and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate 
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_check_bb(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_multi(integer, kaverimrg.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_check_multi(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json[]
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
  v.villagenamee,
 v.hoblicode,
 h.hoblinamee,
r.referencetext,
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber,
 pn.currentnumber AS aptno_new,
 pn.oldnumber AS oldno
from  kaverimrg.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid 	 
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( select 
ps.easttowest,
 ps.northtosouth,
ps.description 
from kaverimrg.propertyschedules ps where ps.srocode = pm.regsrocode and ps.propertyid = pm.propertyid)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select  pi.partyid,
 string_agg(
        CASE
            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END, ', '::text) AS claimant,
 string_agg(
        CASE
            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END, ', '::text) AS executant,
		     pi.address from kaverimrg.partyinfo pi where pi.srocode = dm.srocode AND pi.documentid = dm.documentid
group by pi.partyid,pi.address
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.stamp5datetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails
from kaverimrg.propertymaster pm inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
	 inner join kaverimrg.propertynumberdetails pn_src on pm.propertyid = pn_src.propertyid --AND pn_src.srocode = pm.regsrocode
inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid
left JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left  JOIN kaverimrg.referencemaster r on r.documentid = dm.documentid 
 where  v.villagecode = _villagecode and
	  (pn_src.currentpropertytypeid, pn_src.currentnumber) 
	  in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) --and
--dm.stamp5datetime between _fromdate  and _todate
) app_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_check_multi(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_test(integer, kaverimrg.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_check_test(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
	
	
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.sroconsideration as consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber
-- pn.currentnumber AS aptno_new,
-- pn.oldnumber AS oldno
from  kaverimrg.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
-- Left Join is required at partyschedules and partyinfo to fetch propertyschedules where partyid is null
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null 
 then
 case when  ps.description is not null and  ps.description<>'' then  
 concat(ps.description, 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ', ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '),' ',zn.zonenamee,' zonename')
 else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre',zn.zonenamee,' zonename') end 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps 
join kaverimrg.propertynumberdetails p on ps.propertyid=p.propertyid 
join kaverimrg.propertymaster pp on ps.propertyid=pp.propertyid 
left join kaverimrg.zonemaster zn on zn.zoneid=pp.zoneid
left join kaverimrg.partyschedules pas on ps.propertyid=pas.propertyid 
left join kaverimrg.partyinfo pin on pas.partyid=pin.partyid 
join kaverimrg.villagemaster v2 on pp.villagecode=v2.villagecode 
join kaverimrg.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 
join kaverimrg.districtmaster d on tm.districtcode =d.districtcode 
where ps.propertyid = pm.propertyid and (p.currentpropertytypeid, p.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,p.hissa_no,ps.northboundary
		   ,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea,zn.zonenamee
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct p.partyid,
-- (
--        CASE
--            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS claimant,
          CASE
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	        END AS partyname,
        p.partytypeid ,
-- (
--        CASE
--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS executant,
        --# left join is necessary because in partyschedules table we are not capturing claimaint details
		     p.address from kaverimrg.partyinfo p
			left JOIN kaverimrg.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
			left JOIN kaverimrg.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
			left JOIN kaverimrg.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaverimrg.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaverimrg.salutationmaster s2 ON p2.salutationid = s2.salutationid
		--	left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
			where p.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		 join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from kaverimrg.propertymaster pm inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
--inner join kaverimrg.propertynumberdetails pn_src  on pm.propertyid = pn_src.propertyid and (pn_src.currentpropertytypeid, pn_src.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )  --and pn_src.srocode = v.srocode
join (select distinct propertyid from kaverimrg.propertynumberdetails p where(p.currentpropertytypeid, p.currentnumber) 
in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) ) as pn_src on pn_src.propertyid=pm.propertyid
inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
where  v.villagecode = _villagecode and dm.bookid not in (3, 4) and pm.ismovableproperty = false
and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate 
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_check_test(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_check_test_20112023(integer, kaverimrg.ec_srch_property[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_check_test_20112023(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
	
	
select row_to_json(data_json)::json into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.sroconsideration as consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber
-- pn.currentnumber AS aptno_new,
-- pn.oldnumber AS oldno
from  kaverimrg.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn.currentpropertytypeid, pn.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
-- Left Join is required at partyschedules and partyinfo to fetch propertyschedules where partyid is null
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null 
 then
 case when  ps.description is not null and  ps.description<>'' then  
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '),' ',zn.zonenamee,' zonename')
 else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v2.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre',zn.zonenamee,' zonename') end 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps 
join kaverimrg.propertynumberdetails p on ps.propertyid=p.propertyid 
join kaverimrg.propertymaster pp on ps.propertyid=pp.propertyid 
left join kaverimrg.zonemaster zn on zn.zoneid=pp.zoneid
left join kaverimrg.partyschedules pas on ps.propertyid=pas.propertyid 
left join kaverimrg.partyinfo pin on pas.partyid=pin.partyid 
join kaverimrg.villagemaster v2 on pp.villagecode=v2.villagecode 
join kaverimrg.talukmaster tm on v2.talukcode =tm.talukcode --, p.currentnumber) 
join kaverimrg.districtmaster d on tm.districtcode =d.districtcode 
where ps.propertyid = pm.propertyid and (p.currentpropertytypeid, p.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,d.districtnamee,tm.taluknamee,v2.villagenamee,p.survey_no,p.hissa_no,ps.northboundary
		   ,ps.eastboundary,ps.westboundary,ps.southboundary,ps.totalarea,zn.zonenamee
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct p.partyid,
-- (
--        CASE
--            WHEN pi.partytypeid = 1 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS claimant,
		(case when pmm.regarticlecode=91 then 
          (CASE
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	         end) END) AS partyname,
			
        p.partytypeid ,

-- (
--        CASE
--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS executant,
        --# left join is necessary because in partyschedules table we are not capturing claimaint details
		     p.address from kaverimrg.partyinfo p
			left JOIN kaverimrg.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
			left JOIN kaverimrg.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
			 join kaverimrg.partyschedules psp on p.partyid=psp.partyid
			 join kaverimrg.propertymaster pmm on psp.propertyid=pmm.propertyid
			left JOIN kaverimrg.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaverimrg.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaverimrg.salutationmaster s2 ON p2.salutationid = s2.salutationid
		--	left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
			where p.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
	(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	',Liability Note: ', ld.liabilitynote, '<br>2.  Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		 join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from kaverimrg.propertymaster pm inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
--inner join kaverimrg.propertynumberdetails pn_src  on pm.propertyid = pn_src.propertyid and (pn_src.currentpropertytypeid, pn_src.currentnumber) in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a )  --and pn_src.srocode = v.srocode
join (select distinct propertyid from kaverimrg.propertynumberdetails p where(p.currentpropertytypeid, p.currentnumber) 
in (select a._currentproperttypeid,a._currentnumber from unnest (p_srch_property) a ) ) as pn_src on pn_src.propertyid=pm.propertyid
inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid  and dm.finalregistrationnumber is not null and Isregistrationcompleted=true
JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
where  v.villagecode = _villagecode and dm.bookid not in (3, 4) and pm.ismovableproperty = false
and dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate 
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_check_test_20112023(_villagecode integer, p_srch_property kaverimrg.ec_srch_property[], _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_firm(integer, integer, text, text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_firm(_districtcode integer, _talukcode integer, _firmname text, _finalregdno text, _from_date timestamp without time zone, _to_date timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
v_finalregdno text;
  
BEGIN

	if _finalregdno is not null then
	
	  v_finalregdno=_finalregdno ;
	 
	else 
	
	  select f.finalregistrationnumber  into v_finalregdno 
	 from kaverimrg.firmmaster f where f.firmname=_firmname;
	
 end if;

raise notice 'finalregno%',v_finalregdno;
raise notice 'finalregno%',_finalregdno;


	
 select (row_to_json(data_json)) into v_data_json
  from (select d.firmname,d.applicationnumber,d.finalregistrationnumber,
   s.servicename,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Pincipal_place_of_business,	
		d.finalregistrationnumber ,  (select array_to_json(array_agg(row_to_json(partnerdetails))) as PartnerDetails
  from(select   br.firmpersonid, br.firstname||' '||br.middlename||' '||br.lastname as partner_name

from kaverimrg.firmparty br where br.applicationnumber=d.applicationnumber) partnerdetails  ),

(select array_to_json(array_agg(row_to_json(amendmentdetails))) as Amendmentdetails
  from (select  f.applicationnumber,f.finalregistrationnumber,'Firm Amendment'|| ' ' ||
mfa.description  as servicename,f.inserteddatetime
from kaverimrg.firmamendment f 
join kaverimrg.mas_frm_amendmenttypes mfa  on f.amendmenttypeid=mfa.amendmenttypeid 
join kaverimrg.applicantapplicationdetails a2 on a2.applicationnumber=f.applicationnumber 
  where f.finalregistrationnumber=v_finalregdno
 and f.inserteddatetime between  _from_date  and _to_date 
-- and 
--a2.currentstatus in ('FA122')
)amendmentdetails),

(select array_to_json(array_agg(row_to_json(reconstituriondetails))) as Reconstituriondetails
  from (select f.applicationnumber,f.firmfinalregnumber,s.servicename,f.inserteddatetime
from kaverimrg.firmreconstitution f 
join kaverimrg.applicantapplicationdetails a2 on a2.applicationnumber=f.applicationnumber
join kaverimrg.servicesmaster s 	on a2.applicationtypeid=s.serviceid  
  where f.firmfinalregnumber=v_finalregdno
 and   f.inserteddatetime between  _from_date  and _to_date 
-- and 
-- a2.currentstatus in ('FC119')
 )reconstituriondetails),
 (select array_to_json(array_agg(row_to_json(desolutiondetails))) as Desolutiondetails
  from (select fd.applicationnumber,fd.finalregistrationnumber,s.servicename,
 fd.inserteddatetime from kaverimrg.firm_dissolution fd 
 join kaverimrg.applicantapplicationdetails a2 on fd.applicationnumber=a.applicationnumber 
 join kaverimrg.servicesmaster s 	on a2.applicationtypeid=s.serviceid
 where fd.finalregistrationnumber=v_finalregdno
 and   fd.inserteddatetime between  _from_date  and _to_date 
 --and 
 --a2.currentstatus in ('FD120')
  )desolutiondetails),
  (select array_to_json(array_agg(row_to_json(protestentrydetails))) as Protestentrydetails
  from (select f2.applicationnumber,f2.finalregistrationnumber,
  s.servicename,f2.inserteddatetime   from kaverimrg.firmprotestentry f2 
  join kaverimrg.applicantapplicationdetails a2 on f2.applicationnumber=a2.applicationnumber 
  join kaverimrg.servicesmaster s 	on a2.applicationtypeid=s.serviceid
 where f2.finalregistrationnumber=v_finalregdno
 and   f2.inserteddatetime between  _from_date  and _to_date
 )protestentrydetails)
 --and 
 --a2.currentstatus in ('FD120')


			from kaverimrg.firmmaster d 
		inner join kaverimrg.applicantapplicationdetails a on d.applicationnumber =a.applicationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
		left join kaverimrg.servicesmaster s on a.applicationtypeid =s.serviceid 
			where 
			d.districtcode =_districtcode  and d.talukacode=_talukcode 
and  d.finalregistrationnumber=v_finalregdno 
and  
--a.currentstatus like 'FR%' and a.currentstatus>='FR118' and 
(a.applicationstartdate  between _from_date  and _to_date  )
			
	   	)data_json;
	   	

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_firm(_districtcode integer, _talukcode integer, _firmname text, _finalregdno text, _from_date timestamp without time zone, _to_date timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_party_details_check(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json from (
select array_to_json(array_agg(row_to_json(app_json)))
--select row_to_json(data_json) into v_data_json from (
--select array_to_json(array_agg(row_to_json(data_json)))
--into v_data_json 
from (
 select 
pm.propertyid,
pm.marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from ( 
	--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null then
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & ')) 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps left outer join kaverimrg.partyschedules pas
on ps.propertyid=pas.propertyid left outer join kaverimrg.partyinfo pin on 
pas.partyid=pin.partyid where ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid
--Code Ends for Property Schedules	 
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(prty)))
from ( select distinct p.partyid,
 --(
 --       CASE
 --           WHEN pi.partytypeid = 1 or (ps.propertyid = pm.propertyid) THEN concat(pi.firstname, pi.middlename, pi.lastname)
 --           ELSE NULL::text
 --       END::text) AS claimant,
 --(
 --       CASE
 --           WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
 --           ELSE NULL::text
 --       END::text) AS executant,
 CASE
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	        END AS partyname,
        p.partytypeid ,
 
		     p.address from kaverimrg.partyinfo p
			left JOIN kaverimrg.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
			left JOIN kaverimrg.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
			left JOIN kaverimrg.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaverimrg.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaverimrg.salutationmaster s2 ON p2.salutationid = s2.salutationid
		--	left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
			where p.documentid = dm.documentid
		    --order by pi.partytypeid,pi.partyid	 	  	
)prty ) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
from (select dm.documentid,
dm.registrationdatetime AS executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails,
(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		left join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from  kaverimrg.propertymaster pm
left join  kaverimrg.propertyschedules ps on  ps.propertyid = pm.propertyid
left JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid
left join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
left JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
left JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left join kaverimrg.sromaster s on s.srocode = v.srocode
--left join  kaverimrg.partyinfo pi  on (pi.documentid = pm.documentid )
where pm.villagecode = _villagecode and  dm.bookid not in (3, 4) and pm.ismovableproperty = false and
	exists  (select 1 from kaverimrg.partyinfo p where p.documentid=pm.documentid
							and  p.applicationnumber is not null and
			lower(firstname) ~ lower(_firstname) = true
			and lower(coalesce(middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(lastname,'')) ~ lower(_lastname) = true
		   )
	--pi.applicationnumber in (
	--select applicationnumber from kaverimrg.partyinfo where
--firstname = _firstname and 
--coalesce(middlename,'') = _middlename and
--coalesce(lastname,'') = _lastname )
 and 
	dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate

--)  data_json ;
) app_json )  data_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_party_details_check(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check_bbck(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_party_details_check_bbck(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json from (
select array_to_json(array_agg(row_to_json(app_json)))
--select row_to_json(data_json) into v_data_json from (
--select array_to_json(array_agg(row_to_json(data_json)))
--into v_data_json 
from (
 select 
pm.propertyid,
pm.marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from ( 
	--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null then
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & ')) 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps left outer join kaverimrg.partyschedules pas
on ps.propertyid=pas.propertyid left outer join kaverimrg.partyinfo pin on 
pas.partyid=pin.partyid where  ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid
--Code Ends for Property Schedules	 
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(prty)))
from ( select distinct pi.partyid,
 (
        CASE
            WHEN pi.partytypeid = 1 or (ps.propertyid = pm.propertyid) THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END::text) AS claimant,
 (
        CASE
            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END::text) AS executant,
		     pi.address from kaverimrg.partyinfo pi 
			left outer join kaverimrg.partyschedules ps on pi.partyid=ps.partyid
			where pi.documentid = dm.documentid
		    --order by pi.partytypeid,pi.partyid	 	  	
)prty ) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
from (select dm.documentid,
dm.registrationdatetime AS executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails,
(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		left join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from  kaverimrg.propertymaster pm
left join  kaverimrg.propertyschedules ps on  ps.propertyid = pm.propertyid
left JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid
left join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
left JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
left JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left join kaverimrg.sromaster s on s.srocode = v.srocode
--left join  kaverimrg.partyinfo pi  on (pi.documentid = pm.documentid )
where pm.villagecode = _villagecode and  dm.bookid not in (3, 4) and pm.ismovableproperty = false and
	exists  (select 1 from kaverimrg.partyinfo p where p.documentid=pm.documentid
							and  p.applicationnumber is not null and
			lower(firstname) ~ lower(_firstname) = true
			and lower(coalesce(middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(lastname,'')) ~ lower(_lastname) = true
		   )
	--pi.applicationnumber in (
	--select applicationnumber from kaverimrg.partyinfo where
--firstname = _firstname and 
--coalesce(middlename,'') = _middlename and
--coalesce(lastname,'') = _lastname )
 and 
	dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate

--)  data_json ;
) app_json )  data_json ;
return v_data_json;
END;
$$;


