ALTER FUNCTION kaverimrg.fn_fetch_ec_json_party_details_check_bck_28082023(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_ec_json_party_details_check_test(integer, character varying, character varying, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ec_json_party_details_check_test(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json from (
select array_to_json(array_agg(row_to_json(app_json)))
--select row_to_json(data_json) into v_data_json from (
--select array_to_json(array_agg(row_to_json(data_json)))
--into v_data_json 
from (
 select 
pm.propertyid,
pm.marketvalue,
pm.consideration,
ra.articlenamee,
pm.eastboundary AS east,
pm.westboundary AS west,
pm.northboundary AS north,
pm.southboundary AS south,
pm.totalarea AS area,
pm.villagecode,
v.villagenamee,
v.hoblicode,
h.hoblinamee,
(select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
v.srocode,
s.sronamee,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from ( 
	--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null 
 then
 case when  ps.description is not null and  ps.description<>'' then 
 concat(ps.description,'Village: ',v.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no, ', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ', ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & '),' ',zn.zonenamee) 
   else concat('District: ', d.districtnamee,', ' , 'Taluk: ', tm.taluknamee,', ' , 'Village: ',v.villagenamee,', ', '', 'Survey No: ',p.survey_no,', ', 'Hissa No: ', p.hissa_no,', ', 'BoundaryDetails: [North: ',ps.northboundary,', '
 , 'East: ',ps.eastboundary,', '
 , 'West: ', ps.westboundary,', ', 'South: ', ps.southboundary,', ','] measuring ',ps.totalarea,' acre',zn.zonenamee,' zonename') end 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps 
left join kaverimrg.propertynumberdetails p on ps.propertyid=p.propertyid
left outer join kaverimrg.partyschedules pas on ps.propertyid=pas.propertyid 
left outer join kaverimrg.partyinfo pin on pas.partyid=pin.partyid 
where ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid,zn.zonenamee
		   ,p.survey_no,p.hissa_no,ps.northboundary,ps.eastboundary,ps.westboundary,ps.southboundary,d.districtnamee,tm.taluknamee
		   ,v.villagenamee,ps.totalarea
--Code Ends for Property Schedules	 
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(prty)))
from ( select distinct p.partyid,
-- (
--        CASE
--            WHEN pi.partytypeid = 1 or (ps.propertyid = pm.propertyid) THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS claimant,
-- (
--        CASE
--            WHEN pi.partytypeid = 2 THEN concat(pi.firstname, pi.middlename, pi.lastname)
--            ELSE NULL::text
--        END::text) AS executant,
 CASE
	            when p1.partytypeid = 4 AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 4 AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = true THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
	            WHEN p1.partytypeid = 5 AND p.isorganization = false THEN concat(s1.descriptione, p1.firstname, ' is POA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid = 9 AND p.isorganization = true AND p2.firstname IS NOT NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ', whose POA is ', s2.descriptione, p2.firstname, ' ', p2.middlename, ' ', p2.lastname)
	            WHEN p1.partytypeid = 9  AND p.isorganization = true AND p2.firstname IS NULL THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 1 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            WHEN p1.partytypeid IS NULL AND p.partytypeid = 2 THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
	            ELSE NULL::text
	        END AS partyname,
        p.partytypeid ,
 		p.address from kaverimrg.partyinfo p
			left JOIN kaverimrg.partyinfo p1 ON p.partyid = p1.linkpartyid AND (p1.partytypeid = ANY (ARRAY[9, 4, 5]))
			left JOIN kaverimrg.partyinfo p2 ON p2.linkpartyid = p1.partyid AND (p2.partytypeid = ANY (ARRAY[5]))
			left JOIN kaverimrg.salutationmaster s ON p.salutationid = s.salutationid
			left JOIN kaverimrg.salutationmaster s1 ON p1.salutationid = s1.salutationid
			left JOIN kaverimrg.salutationmaster s2 ON p2.salutationid = s2.salutationid
		--	left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
			where p.documentid = dm.documentid
		--	left  join kaverimrg.partyschedules ps on pi.partyid=ps.partyid 
--			where p.documentid = dm.documentid
		    --order by pi.partytypeid,pi.partyid	 	  	
)prty ) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
from (select dm.documentid,
dm.registrationdatetime AS executiondate,
dm.cdnumber,
dm.pagecount,
dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails,
(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote,
(select string_agg(concat('1. Liability Details: Order Number: ', ld.ordernumber, ', Issue Date: ', TO_CHAR(ld.issuedate ::date, 'dd/mm/yyyy'), 
	 	', Liability Note: ', ld.liabilitynote, '<br>2. Additional Note: ', ld.liabilityadditionalnote),';<br> ') 
		from kaverimrg.liabilityonpropertydetails lop
		left join kaverimrg.liabilitydetails ld on lop.liabilityid = ld.liabilityid 
		--left join kaverimrg.liabilitynoteadditionaldetails lnad on lnad.liabilityid=ld.liabilityid 
	 where lop.propertyid = pm.propertyid) as liabilitynote
from  kaverimrg.propertymaster pm
left join  kaverimrg.propertyschedules ps on  ps.propertyid = pm.propertyid
left JOIN kaverimrg.documentmaster dm ON pm.documentid = dm.documentid
left join kaverimrg.villagemaster v on pm.villagecode = v.villagecode
left JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode
left join kaverimrg.talukmaster tm on v.talukcode=tm.talukcode
left join kaverimrg.districtmaster d on tm.districtcode=d.districtcode
left JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
left join kaverimrg.sromaster s on s.srocode = v.srocode
left join kaverimrg.zonemaster zn on zn.zoneid =pm.zoneid
--left join  kaverimrg.partyinfo pi  on (pi.documentid = pm.documentid )
where pm.villagecode = _villagecode and  dm.bookid not in (3, 4) and pm.ismovableproperty = false and
	exists  (select 1 from kaverimrg.partyinfo p where p.documentid=pm.documentid
							and  p.applicationnumber is not null and
			lower(firstname) ~ lower(_firstname) = true
			and lower(coalesce(middlename,'')) ~ lower(_middlename) = true
			and lower(coalesce(lastname,'')) ~ lower(_lastname) = true
		   )
	--pi.applicationnumber in (
	--select applicationnumber from kaverimrg.partyinfo where
--firstname = _firstname and 
--coalesce(middlename,'') = _middlename and
--coalesce(lastname,'') = _lastname )
 and 
	dm.registrationdatetime::date >= _fromdate and dm.registrationdatetime::date <= _todate

--)  data_json ;
) app_json )  data_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ec_json_party_details_check_test(_villagecode integer, _firstname character varying, _middlename character varying, _lastname character varying, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_employee(integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_employee(_officetype integer, _officeid integer) RETURNS TABLE(userid bigint, employeename text, employeepost text, useremail text)
    LANGUAGE plpgsql
    AS $$



DECLARE

BEGIN 

	if _officetype=0 then 
	    
		  if _officeid=0 then --All office of All type

			  return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaverimrg.departmentusers du 
				join  kaverimrg.mas_officemaster mo on du.officeid=mo.officeid 
				--and mo.officeid=_officeid
				join kaverimrg.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				--and mo2.officetypeid=_officetype
				join kaverimrg.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
			
			ELSE  --perticular office of any type
			
				return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaverimrg.departmentusers du 
				join  kaverimrg.mas_officemaster mo on du.officeid=mo.officeid 
				and mo.officeid=_officeid
				join kaverimrg.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				--and mo2.officetypeid=_officetype
				join kaverimrg.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
		end if;
		
	 ELSE
			if _officeid=0 then  --All office of perticular type
			return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaverimrg.departmentusers du 
				join  kaverimrg.mas_officemaster mo on du.officeid=mo.officeid 
				--and mo.officeid=_officeid
				join kaverimrg.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				and mo2.officetypeid=_officetype
				join kaverimrg.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
				
			ELSE  --perticular office of a perticular type
			
				return query
				select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
				concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
				du.emailid as username
				from kaverimrg.departmentusers du 
				join  kaverimrg.mas_officemaster mo on du.officeid=mo.officeid   and mo.officeid=_officeid
				join kaverimrg.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
				and mo2.officetypeid=_officetype
				join kaverimrg.desigmaster d on d.designationid=du.designationid 
				where du.serviceflag is true;
			end if;
			
				
	end if; 
			

 

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_employee(_officetype integer, _officeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_employee_by_officeid(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_employee_by_officeid(_officeid integer) RETURNS TABLE(userid bigint, employeename text, employeepost text, useremail text)
    LANGUAGE plpgsql
    AS $$


DECLARE



BEGIN 

  return query
	select  du.userid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS EmployeeName,
	concat_ws(' '::text, mo2.officetypedesc,mo.officename ,d.designame) as post,
	du.emailid as username
	from kaverimrg.departmentusers du 
	join  kaverimrg.mas_officemaster mo on du.officeid=mo.officeid 
	join kaverimrg.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
	join kaverimrg.desigmaster d on d.designationid=du.designationid  where du.officeid=_officeid;

 

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_employee_by_officeid(_officeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_employee_by_userid(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_employee_by_userid(_userid integer) RETURNS TABLE(userid bigint, kgid text, employeename text, roll text, usertype text, officeid text, officename text, jurisdictionid text, post text, joiningdate text, officialemailid text, mobileno bigint, isactive boolean, roleinfo json)
    LANGUAGE plpgsql
    AS $$


DECLARE

BEGIN 

  return query
	
select  du.userid,
	du.kgid,concat_ws(' '::text, du.firstname,du.middlename, du.lastname) AS empname,
	d.designame::text as role,
	e.employeetypedesc  as usertype,
	mo2.officetypedesc||mo.officeid as officeid,
	mo2.officetypedesc||' '||mo.officename as officename,
	mo2.officetypedesc||' '||joff.officeid as jurisdictionid,
	concat_ws(' '::text,trim(d.designame),mo2.officetypedesc,mo.officename ) as post,
	to_char(du.doj,'dd/mm/yyyy') as joiningdate,
	du.emailid as officialemailid,du.mobileno,du.serviceflag,
	(select  fn_fetch_roleinfo_byuseid  from kaverimrg.fn_fetch_roleinfo_ByUseId(_userid))as rolesinfo
	from kaverimrg.departmentusers du 
	join  kaverimrg.mas_officemaster mo on du.officeid=mo.officeid 
	join kaverimrg.mas_officetypes mo2 on mo2.officetypeid=mo.officetypeid 
	join kaverimrg.desigmaster d on d.designationid=du.designationid 
	join kaverimrg.mas_officemaster joff on mo.parentofficeid=joff.officeid
	join kaverimrg.mas_officetypes mo3 on mo3.officetypeid=joff.officetypeid 
	join kaverimrg.employeetypemaster e on e.employeetypeid=du.employeetypeid 
	where du.userid=_userid;

 

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_employee_by_userid(_userid integer) OWNER TO postgres;

--
-- Name: fn_fetch_endorsement_summary_rule_17(text, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_endorsement_summary_rule_17(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;



begin
		
		select count(*) into v_countrecord from kaverimrg.propertymaster p where applicationnumber=_applicationnumber;
		select count(*) into v_cntproperty from kaverimrg.propertynumberdetails ps where propertyid in (select propertyid from kaverimrg.propertymaster where applicationnumber=_applicationnumber);
	
pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select rr.srocode,
    rr.sronamee,
    rr.bookid,
    rr.documentnumber,
    rr.finalregistrationnumber,
    rr.presentdatetime,
    (rr.executiondatetime::timestamp at time zone 'utc') as executiondatetime,
    rr.dateofstamp,
    rr.pagecount,
    rr.index2shera,
    rr.isvisited,
    rr.isfiling,
    rr.ispending,
    rr.isscanned,
    rr.isrefused,
    rr.ispaymentofmoney,
    rr.isadjudicated,
    rr.iswithdrawn,
    rr.refusaldate,
    rr.correctionreference,
    rr.pendingdocumentnumber,
    rr.istransmitted,
    rr.isphotothumbtransmitted,
    rr.inserteddatetime,
    rr.initialtransmitted,
    rr.considerationamount,
    rr.requiredstampduty,
    rr.paidstampduty,
    rr.documentstatus,
    rr.applicationnumber,
    rr.verified,
    rr.issroapproved,
    rr.deedattachpath,
    rr.uploaddocdeedpath,
    rr.uploaddocannexurepath,
    rr.uploadsummarydocpath,
    rr.annexurepath,
    rr.remarks,
    rr.remarkscomment,
    rr.documentid,
    rr.booknamekannada,
    rr.booknameenglish,
    rr.printablename,
    rr.articlenamee,
    rr.articlenamek,
    rr.regarticlecode,
    rr.regarticlename,

(select array_to_json(array_agg(row_to_json(app_json)))
from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
 
vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,
 
sm.districtcode,di.districtnamee as District,
 
pm.stamparticlecode,
 
sp.articlenamee as stamparticle,
 
pm.stampruleid,
 
sr.descriptione as stampsubarticle,
 
pm.regarticlecode,
 
ra.articlenamee as registrationfeearticle,
 
sr.bookid,
 
bt.booknameenglish as bookname,
pm.srocode,
 
se.sronamee as sroname,
 
pm.propertytypeid,
 
pt.propertytypename,
 
pm.noofscanpages,
 
pm.ismovableproperty,
 
pm.movablepropertydesc,
 
w.wardid,
 
pm.totalarea,
 
me.descriptionenglish as unit,
 
w.wardnumber,
 
pm.landmark,
 
pm.zoneid,
 
zone.departmentname as zonename,
 
subpropertytypeid,
 pm.valuationreport,
( select array_to_json(array_agg(row_to_json(partypndetails)))
from (
select distinct a.partyid ,
COALESCE(coalesce(a.firstname,' ')||' '||coalesce(a.middlename,' ')||' '||coalesce(a.lastname,' '), NULL::text)  AS name,
a.partytypeid ,a.address, a.isexecutor, a.ispresenter, a.salutationid, a.age from
kaverimrg.partyinfo a
where a.applicationnumber = _applicationnumber
group by a.address, a.isexecutor, a.ispresenter,a.partytypeid,a.firstname,a.middlename,  a.lastname,a.partyid, a.salutationid, a.age
 
)partypndetails) as partyinfopropnumberdetails,

 
( select array_to_json(array_agg(row_to_json(prptyno)))
 
from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
 
pntm.typenameenglish as propertynumbertype,
 
pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription
 
from kaverimrg.propertynumberdetails pnd
 
 left join kaverimrg.propertynotypemaster pntm
 
on (pntm.propertytypeid = pnd.currentpropertytypeid)
 
 where pnd.propertyid = pm.propertyid and
 
pm.applicationnumber = _applicationnumber
 
 )prptyno )
 
as propertynumberdetails,
 
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from
(select scheduleid,
ps.propertyid,
ps.srocode,
ps.partyid,
ps.scheduletype,
pm.totalarea,
ps.unitid,
ps.description,
ps.partyids,
ps.aileniatedauthorityid,
ps.alieniatedorder,
ps.bhoomisellerpartyids,
ps.govtrestricorder,
ps.govtrestrictionid,
ps.landcode,propertygroup,
ps.giftshare,
ps.giftsharedetails,
ps.easttowest,
ps.northtosouth,
ps.blockchainpropertyid,
ps.assignedblockchainpid,
ps.applicationnumber,
ps.verified,
ps.issroapproved,
ps.eastboundary,
ps.westboundary,
ps.northboundary,
ps.southboundary,
mm.measurementnamee
from kaverimrg.propertyschedules ps
 join kaverimrg.propertymaster pmm on ps.propertyid=pmm.propertyid 
left join kaverimrg.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
left join kaverimrg.measurementmaster mm on ps.unitid= mm.measurementcode
where ps.applicationnumber=_applicationnumber and ps.propertyid= pm.propertyid
order by ps.scheduleid
) propertyschedules) as propertyschedulesdata,

pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaverimrg.propertymaster pm 
left join kaverimrg.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaverimrg.sromaster sm on (vi.srocode=sm.srocode)
left join kaverimrg.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaverimrg.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaverimrg.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaverimrg.bhoomidistrictmasterdi on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish
,pm.srocode,se.sronamee,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname,
subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri, pm.valuationreport 
offset pageoffset
fetch next pagesize rows only
 
)app_json) 

from kaverimrg.vw_document_for_approval_rule17 rr where rr.applicationnumber = _applicationnumber

) data_json;


return v_data_json;
	END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_endorsement_summary_rule_17(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_endorsementdetails(character varying, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_endorsementdetails(_applicationnumber character varying, srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_array json;
v_pid json;
v_presenter boolean;
v_privateattendence boolean;
V_linkparty bigint;
V_section88exemption boolean;
--v_rearray bigint[];
begin
	
for v_presenter,v_privateattendence,V_linkparty,V_section88exemption   in (select p.ispresenter,p.isprivateattendance,p.linkpartyid,p.section88exemption  
	from kaverimrg.partyinfo p where applicationnumber = _applicationnumber)
	loop
	
	
		
		
	if(v_presenter=true)
	then 
		
		
	-----At private attandance------
	
		if(v_privateattendence=true)
		then 
		

		 select array_to_json(array_agg(row_to_json(party)))
      	from (
		select Distinct e.endorsementdescriptione,e.endorsmentsubname from kaverimrg.partyinfo p 
		 join kaverimrg.EndorsementFlowMaster e on e.endorsmentname  = case when p.ispresenter='true' then 'Presentation' else null end
		 where e.endorsmentsubname='At private attandance' and p.isprivateattendance = true) as  party into v_array ;
		
	------With Power of attorney----
		
		elseif(V_linkparty is not null)
		then 
		select array_to_json(array_agg(row_to_json(party)))
		from (
			select Distinct e.endorsementdescriptione,e.endorsmentsubname  from kaverimrg.partyinfo p 
			join kaverimrg.partyinfo p2 on p.partyid = p2.linkpartyid 
			join kaverimrg.partyinfo p3 on p.partyid = p3.linkpartyid 
			join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
			where p.ispresenter=true and p2.linkpartyid is not null and p2.partytypeid = 5 and p3.partytypeid=5 and   e.endorsmentsubname = 'With Power of attorney')as  party into v_array;
			--group by  p.partyid ,p2.linkpartyid 
		
	-------With Covering Letter---------		
		elseif(V_section88exemption=true)		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
			select distinct e.endorsementdescriptione,e.endorsmentsubname  from kaverimrg.partyinfo p 
				join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.section88exemption =true and  e.endorsmentsubname = 'With Covering Letter')as  party into v_array;
			
	----- Normal At Work-------		
		
		elseif(v_privateattendence=false and V_linkparty is null  and V_section88exemption=false )		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
				select Distinct e.endorsementdescriptione,e.endorsmentsubname  from kaverimrg.partyinfo p 
				join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.ispresenter=true and p.isprivateattendance = false and p.linkpartyid is null and p.section88exemption = false
				and e.endorsmentsubname='Normal at Office' )as  party into v_array;
			
			
			
	
		end if;
	
	
	end if;
 end loop;
return (v_array);

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_endorsementdetails(_applicationnumber character varying, srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_endorsementdetails_bak(character varying, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_endorsementdetails_bak(_applicationnumber character varying, _srocode bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_array json;
v_pid json;
v_presenter boolean;
v_privateattendence boolean;
V_linkparty bigint;
V_section88exemption boolean;
--v_rearray bigint[];
v_executor boolean;
v_fingerid bigint;

begin
	
for v_presenter,v_privateattendence,V_linkparty,V_section88exemption,v_executor,v_fingerid in (select distinct p.ispresenter,p.isprivateattendance,p.linkpartyid,p.section88exemption,p.isexecutor,p.fingerid  
	from kaverimrg.partyinfo p where p.applicationnumber = _applicationnumber and p.srocode=_srocode)
	loop
	
	
		
		
	if(v_presenter=true)
	then 
		
		
	-----At private attandance------
	
		if(v_privateattendence=true)
		then 
		

		 select array_to_json(array_agg(row_to_json(party)))
      	from (
		select Distinct e.endorsementdescriptione,e.endorsementdescriptionk from kaverimrg.partyinfo p 
		 join kaverimrg.EndorsementFlowMaster e on e.endorsmentname  = case when p.ispresenter='true' then 'Presentation' else null end
		 where e.endorsmentsubname='At private attandance' and p.isprivateattendance = true and p.applicationnumber=_applicationnumber
		 and p.srocode=_srocode) as  party into v_array ;
		
	------With Power of attorney----
		
		elseif(V_linkparty is not null)
		then 
		select array_to_json(array_agg(row_to_json(party)))
		from (
			select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.partyinfo p 
			join kaverimrg.partyinfo p2 on p.partyid = p2.linkpartyid 
			join kaverimrg.partyinfo p3 on p.partyid = p3.linkpartyid 
			join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
			where p.ispresenter=true and p2.linkpartyid is not null and p2.partytypeid = 5 and p3.partytypeid=5 and 
			e.endorsmentsubname = 'With Power of attorney' and p.applicationnumber=_applicationnumber
		 	and p.srocode=_srocode)as  party into v_array;
			--group by  p.partyid ,p2.linkpartyid 
		
	-------With Covering Letter---------		
		elseif(V_section88exemption=true)		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
			select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.partyinfo p 
				join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.section88exemption =true and  e.endorsmentsubname = 'With Covering Letter' and p.applicationnumber=_applicationnumber
				 and p.srocode=_srocode)as  party into v_array;
			
	----- Normal At Work-------		
		
		elseif(v_privateattendence=false and V_linkparty is null  and V_section88exemption=false )		
		then
			select array_to_json(array_agg(row_to_json(party)))
		from (	
				select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.partyinfo p 
				join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.ispresenter='true' then 'Presentation' else null end
				where p.ispresenter=true and p.isprivateattendance = false and p.linkpartyid is null and p.section88exemption = false
				and e.endorsmentsubname='Normal at Office' and p.applicationnumber=_applicationnumber
				 and p.srocode=_srocode)as  party into v_array;
			
			
			
	
		end if;
	
	elseif (v_executor=true)
	then 
	
	-----Normal Finger :- It mean Left Thumb-----
		if(v_fingerid=1)
		then
		select array_to_json(array_agg(row_to_json(party)))
		from 
		(select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.partyinfo p 
		join kaverimrg.fingertypemaster f on p.fingerid = f.fingerid 
		join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.isexecutor ='true' then 'Executant acceptance' else null end
		where p.fingerid=1 and p.isexecutor = true and e.endorsmentsubname='Normal ' and p.applicationnumber=_applicationnumber
		 and p.srocode=_srocode)as  party into v_array;
	
	----With Right thumb or any other fingers---
	
		elseif(v_fingerid in (6,2,3,4,5,7,8,9,10))
		then
		select array_to_json(array_agg(row_to_json(party)))
		from(select Distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.partyinfo p 
			join kaverimrg.fingertypemaster f on p.fingerid = f.fingerid 
			join kaverimrg.EndorsementFlowMaster e  on e.endorsmentname = case when p.isexecutor ='true' then 'Executant acceptance' else null end
			where p.fingerid in(6,2,3,4,5,7,8,9,10)  and p.isexecutor = true and e.endorsmentsubname = 'With Right thumb or any other fingers' 
			and p.applicationnumber=_applicationnumber and p.srocode=_srocode) as  party into v_array;
	
		elseif(v_fingerid=0)
		then
		select array_to_json(array_agg(row_to_json(party)))
		from(select e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.partyinfo p 
			join kaverimrg.fingertypemaster f on p.fingerid = f.fingerid 
			join kaverimrg.EndorsementFlowMaster e on e.endorsmentname = case when p.isexecutor ='true' then 'Executant acceptance' else null end
			where p.fingerid=0 and e.endorsmentsubname ='Party with out finger' and p.applicationnumber=_applicationnumber and p.srocode=_srocode) as  party into v_array;
		
		elseif(v_executor=true)
			then
			select array_to_json(array_agg(row_to_json(party)))
		from(
				select distinct e.endorsementdescriptione,e.endorsementdescriptionk  from kaverimrg.witnessinfo w 
				join kaverimrg.partyinfo p on w.documentid =p.documentid 
				join kaverimrg.EndorsementFlowMaster e on e.endorsmentname = case when w.isexicutent  ='true' then 'Witness identifying executants' else null end
				where w.isexicutent = true and e.endorsmentsubname ='Witness identifying executants' and p.applicationnumber=_applicationnumber and p.srocode=_srocode)as  party into v_array;

		end if;
	
		
	
	end if;
 end loop;
return (v_array);

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_endorsementdetails_bak(_applicationnumber character varying, _srocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_fda_pending(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_fda_pending(_sfdaid bigint DEFAULT NULL::bigint) RETURNS TABLE(v_doc bigint, v_assigntoday bigint, v_pendingec bigint, v_pendingcc bigint)
    LANGUAGE plpgsql
    AS $$
declare 
v_doc bigint;
v_assigntoday bigint;
v_pendingEC bigint;
v_pendingCC bigint;

begin
	--ALl document registration 	
select count(distinct a.applicationnumber) as Doc_Rg into v_doc  from kaverimrg.applicantapplicationdetails a 
where applicationtypeid=1 and currentstatus='CD103' and a.sfdaid =_sfdaid;
--Assign Today

select count(distinct a.applicationnumber) as assigntoday into v_assigntoday  from kaverimrg.applicantapplicationdetails a
join kaverimrg.applicationaudit a2 on a.applicationnumber=a2.applicationnumber 
where a.applicationtypeid=1 and a2.wrkflowstatusid='CD103' and a.sfdaid =_sfdaid and to_char(a2.crtdt,'YYYY-MM-DD')=to_char(current_date,'YYYY-MM-DD');
--pending EC

select count(distinct ad.applicationnumber) as pendingEC into v_pendingEC from kaverimrg.applicantapplicationdetails ad
join kaverimrg.ec_applicationdetails ea on ad.applicationnumber::text=ea.applicationnumber::text 
where ad.applicationtypeid =13 and ad.currentstatus in ('CE139','CE105') and ad.sfdaid=_sfdaid;
--Pending CC

select count(distinct ad.applicationnumber) as PendingCC into v_pendingCC from kaverimrg.applicantapplicationdetails ad 
join kaverimrg.cc_applicationdetails  ea on ad.applicationnumber::text=ea.applicationnumber::text 
where ad.applicationtypeid =12 and ad.currentstatus ='CC105' and ad.sfdaid=_sfdaid;



return query
select v_doc,v_assigntoday,v_pendingEC,v_pendingCC;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_fda_pending(_sfdaid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_feesrequired_firm(character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_feesrequired_firm(_applicationnumber character varying, _firmregistrationtypeid integer) RETURNS TABLE(feerulecode integer, description text, value numeric)
    LANGUAGE plpgsql
    AS $$



declare
v_date_of_constitution  timestamp without time zone;
v_penalty  numeric;
v_underoneyearstampdutypaid boolean;
v_underoneyearstampdutynotpaid boolean;
v_morethanoneyearstampdutypaid  boolean;
v_morethanoneyearstampdutynotpaid boolean;
v_no_of_year integer;
v_is_stamp_paid integer;
v_amendmenttypeid integer;

begin
	
	
 
	if _firmregistrationtypeid=6  THEN  --Firm Registration Filling
	  
	    select  dateofconstitutionofthefirm,
	    underoneyearstampdutypaid,
	    underoneyearstampdutynotpaid,
	    morethanoneyearstampdutypaid,morethanoneyearstampdutynotpaid into 
	    v_date_of_constitution,v_underoneyearstampdutypaid,v_underoneyearstampdutynotpaid,
	    v_morethanoneyearstampdutypaid,v_morethanoneyearstampdutynotpaid from kaverimrg.firmmaster   fm
	    where fm.applicationnumber=_applicationnumber;
	  select
	  case when (current_date  - dateofconstitutionofthefirm::date)<=60 then 0
	  else 
		ceil((current_date  - dateofconstitutionofthefirm::date)/365.25)  end 
		into v_no_of_year  from  kaverimrg.firmmaster fm
		where fm.applicationnumber=_applicationnumber;
	    
	    if v_underoneyearstampdutypaid or v_morethanoneyearstampdutypaid then 
	        v_is_stamp_paid=0;
	        v_penalty=0;
	    elsif (v_underoneyearstampdutynotpaid ) or 
	    (v_morethanoneyearstampdutynotpaid) then 
	    	v_penalty=v_no_of_year*5;
	    	 v_is_stamp_paid=1;
	    
	    end if;
	       
	    
	    
	
		return query
		select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
		where f.feerulecode in (33,127)
		union 
		select f.feerulecode,f.descriptione::text,(f.value*v_is_stamp_paid+v_penalty)::numeric 
		from kaverimrg.feesrulemaster f 
		where f.feerulecode in (60)
		union 
		select f.feerulecode,f.descriptione::text,(f.value*5)::numeric 
		from kaverimrg.feesrulemaster f 
		where f.feerulecode in (2);
		
	
	elsif _firmregistrationtypeid=47  THEN --Firm Amendment Filling
	
	 
		select amendmenttypeid
		into v_amendmenttypeid 
		from kaverimrg.firmamendment
		where applicationnumber =_applicationnumber; 
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
	 where 
	 case 
			when v_amendmenttypeid in (1) then f.feerulecode in (61,126,128) --amendement1
			when v_amendmenttypeid in (2) then f.feerulecode in (61,129,114) --amendment2
			when v_amendmenttypeid in (3) then f.feerulecode in (61,115,116) --amendment3
			when v_amendmenttypeid in (4) then f.feerulecode in (61,117,118) --amendment4
	  	 
	 end
	union 
		select f.feerulecode,f.descriptione::text,(f.value*5)::numeric 
		from kaverimrg.feesrulemaster f 
		where f.feerulecode in (2);
	 
	
	
	
	elsif _firmregistrationtypeid=49  THEN   --Firm Dissolution Filling
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
	where f.feerulecode in (62,122,123)
	union 
		select f.feerulecode,f.descriptione::text,(f.value*5)::numeric 
		from kaverimrg.feesrulemaster f 
		where f.feerulecode in (2);
	 
	 elsif _firmregistrationtypeid=48  THEN   --Firm Reconstitution Filling
	 
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
	where f.feerulecode in (119,120,121)
	union 
		select f.feerulecode,f.descriptione::text,(f.value*5)::numeric 
		from kaverimrg.feesrulemaster f 
		where f.feerulecode in (2);
	 
	 
	 elsif _firmregistrationtypeid=50   THEN   --Protest Entry Filling
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
	where f.feerulecode in (18)
	union 
		select f.feerulecode,f.descriptione::text,(f.value*5)::numeric 
		from kaverimrg.feesrulemaster f 
		where f.feerulecode in (2);
	 
	 elsif _firmregistrationtypeid=51 then
	 select ceiling ((f.searchtodate - f.searchfromdate) / 365.25) into 
	 v_no_of_year from kaverimrg.ec_applicationdetails_firm f
		where f.applicationnumber =_applicationnumber;
	 return query
	 select f.feerulecode,f.descriptione::text,(f.value+f.value*(v_no_of_year-1)*0.5)::numeric
	 from kaverimrg.feesrulemaster f 
	where f.feerulecode in (124);

	elsif _firmregistrationtypeid=52 then
	
	return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric
	 from kaverimrg.feesrulemaster f 
	where f.feerulecode in (125);
	
	  
	 
	   
	 
	 end if;

END;
$$;


