    LANGUAGE plpgsql
    AS $$


DECLARE
BEGIN
		if _marriagetype=1 and _marriagemode=1 THEN  --Hindu Marriage online
	
		return query
		select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
		where f.feerulecode in (66,67);
	elsif _marriagetype=1 and _marriagemode=2 THEN  --Hindu Marriage OFFLINE
	
		return query
		select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
		where f.feerulecode in (66,67,68,85);
	
	elsif _marriagetype=2 and _marriagemode=1 THEN -- Special Marriage online - followed same pattern as backup query
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f where f.feerulecode in (45, 37, 49, 77);
	
	
	elsif _marriagetype=2 and _marriagemode=2 THEN     --  Special Marriage offline
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
	 where f.feerulecode in (45, 37, 49, 77);
	
	elsif _marriagetype=3 and _marriagemode=1 THEN   -- Special Marriage others online
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f where f.feerulecode in (11, 37, 83);
	
	elsif _marriagetype=3 and _marriagemode=2 THEN    --  Special Marriage others offline
	
	 return query
	 select f.feerulecode,f.descriptione::text,f.value::numeric from kaverimrg.feesrulemaster f 
	 where f.feerulecode in (11, 37, 83);
	 
	 end if;
END;
$$;


