--
-- Name: fn_fetch_final_regnumber(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_final_regnumber(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
	DECLARE
		v_regnumber text;
		v_serialnumber bigint;
		v_BOOKID bigint;
		v_regdocnumber text default null;
		v_shortname character varying(50);
		V_FINYEAR character varying(50);
		v_pname varchar;
	BEGIN
	
	V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
				to_CHAR(current_date + interval '-12 month', 'YYYY') || 
	'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
				||'-' || to_char(current_date + interval '12 month', 'YY') end );
	
	select  dm.finalregistrationnumber, b.printablename,  dm.bookid,
	sro.shortnamee--,sm.servicename 
	into v_regdocnumber, v_pname, v_BOOKID,
	v_shortname--,applicationtype
	from kaverimrg.documentmaster dm 
	inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
	--INNER join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	--left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	--left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
	join kaverimrg.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
	where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
	
	v_serialnumber:=0;
		
	update kaverimrg.sroserialmaster set finalserial = (coalesce(finalserial,0)+1)::bigint
	where srocode= _srocode and bookid=v_BOOKID and finyear=V_FINYEAR 
	returning finalserial into v_serialnumber;	
	
	if(v_serialnumber=0)
	 then 
	
	 	raise EXCEPTION  'Serial Number could not be generated(%)',v_BOOKID; --EXCEPTION 'Courtorder --> %', v_ordernumber
							--USING HINT = 'Please check property data';
	 	
	end if;
		
	
	
	--select  coalesce(srl.finalserial,0)+1 into v_serialnumber 
	--from kaverimrg.sroserialmaster srl where srocode=_srocode and bookid=v_BOOKID and finyear=V_FINYEAR  for update;
	
	--select v_serialnumber from (select coalesce(srl.finalserial,0)+1
	--into v_serialnumber
	--from kaverimrg.documentmaster dm 
	--inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
	--INNER join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	--left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	--left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
	--join kaverimrg.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
	--where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1) for update;
	
	-- v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
	v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
	
	/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
	 from  kaverimrg.sromaster sro where srocode = _srocode;
	SELECT BOOKID INTO v_BOOKID FROM kaverimrg.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
	select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaverimrg.documentmaster dm 
	left join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/
	
	if (v_regdocnumber is null) then
	update kaverimrg.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
	registrationdatetime = CURRENT_TIMEstamp, isregistrationcompleted = true
	where applicationnumber = _applicationnumber and srocode= _srocode
	and finalregistrationnumber is null;
	fn_fetch_final_regnumber:=v_regnumber;
	
	else 
	fn_fetch_final_regnumber:=v_regdocnumber;
	end if;
	
	END;
	$$;


ALTER FUNCTION kaverimrg.fn_fetch_final_regnumber(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) OWNER TO postgres;

--
-- Name: fn_fetch_final_regnumber_bck(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_final_regnumber_bck(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_regnumber text;
	v_serialnumber bigint;
	v_BOOKID bigint;
	v_regdocnumber text default null;
	v_shortname character varying(50);
	V_FINYEAR character varying(50);
	v_pname varchar;
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select  dm.finalregistrationnumber, b.printablename,  dm.bookid,
sro.shortnamee,sm.servicename 
into v_regdocnumber, v_pname, v_BOOKID,
v_shortname,applicationtype
from kaverimrg.documentmaster dm 
inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
INNER join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
--left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
join kaverimrg.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
	

select  coalesce(srl.finalserial,0)+1 into v_serialnumber 
from kaverimrg.sroserialmaster srl where srocode=_srocode and bookid=v_BOOKID and finyear=V_FINYEAR  for update;

--select v_serialnumber from (select coalesce(srl.finalserial,0)+1
--into v_serialnumber
--from kaverimrg.documentmaster dm 
--inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
--INNER join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
--left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
--left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
--join kaverimrg.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
--where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1) for update;

-- v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
 from  kaverimrg.sromaster sro where srocode = _srocode;
SELECT BOOKID INTO v_BOOKID FROM kaverimrg.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaverimrg.documentmaster dm 
left join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/

if (v_regdocnumber is null) then
update kaverimrg.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
registrationdatetime = CURRENT_TIMEstamp, isregistrationcompleted = true
where applicationnumber = _applicationnumber and srocode= _srocode
and finalregistrationnumber is null;
fn_fetch_final_regnumber:=v_regnumber;

update kaverimrg.sroserialmaster set finalserial = v_serialnumber
where srocode= _srocode and bookid=v_BOOKID and finyear=V_FINYEAR ;

else 
fn_fetch_final_regnumber:=v_regdocnumber;
end if;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_final_regnumber_bck(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) OWNER TO postgres;

--
-- Name: fn_fetch_final_regnumber_fruits(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_final_regnumber_fruits(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber_fruits text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_regnumber text;
	v_serialnumber bigint;
	v_BOOKID bigint;
	v_regdocnumber text default null;
	v_cnt bigint;
	v_shortname character varying(50);
	V_FINYEAR character varying(50);
	v_pname varchar;
	v_consideration_amt bigint;
BEGIN

select sum(consideration) into v_consideration_amt from kaverimrg.propertymaster p 
where p.applicationnumber = _applicationnumber 
group by p.applicationnumber;

select bookid into v_BOOKID FROM kaverimrg.documentmaster d where applicationnumber = _applicationnumber;

if(v_consideration_amt <= 300000) then --and _formiiidata != '' ) then
	update kaverimrg.fruits_data_recv_details set applicationstatus = 1
	where applicationnumber = _applicationnumber;
/*else 
	update kaverimrg.fruits_data_recv_details f set f.applicationstatus = 2
	where applicationnumber = _applicationnumber;*/
end if;
	
select --COALESCE(sro.registrationdocserial,0)+1,
	COALESCE(srl.finalserial,0)+1,
	shortnamee into v_serialnumber,v_shortname
from kaverimrg.sromaster s
join kaverimrg.sroserialmaster srl on srl.srocode = s.srocode 
where s.srocode = _srocode and srl.bookid = v_BOOKID;

--SELECT BOOKID INTO v_BOOKID FROM kaverimrg.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
select b.printablename into v_pname from kaverimrg.booktypemaster b where bookid = v_BOOKID;
-- (select bookid FROM kaverimrg.documentmaster d where applicationnumber = _applicationnumber limit 1);


V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );
			
--v_regnumber:= v_shortname||'-'||v_BOOKID||'-Part-IV-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaverimrg.documentmaster dm 
left join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber;-- and dm.srocode= _srocode;

if (v_regdocnumber is null) then
	update kaverimrg.documentmaster set finalregistrationnumber= v_regnumber,
	documentnumber=v_serialnumber, registrationdatetime = CURRENT_TIMEstamp,
	isregistrationcompleted = true
	where applicationnumber = _applicationnumber --and srocode= _srocode
	and finalregistrationnumber is null;
	fn_fetch_final_regnumber_fruits:=v_regnumber;

	/*update kaverimrg.sroserialmaster set finalserial = v_serialnumber
	where s.srocode = _srocode and srl.bookid = v_BOOKID;*/

	update kaverimrg.applicantapplicationdetails set currentstatus = 'CD120'
	where applicationnumber = _applicationnumber;
else 
	fn_fetch_final_regnumber_fruits:=v_regdocnumber;
end if;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_final_regnumber_fruits(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber_fruits text, OUT applicationtype text) OWNER TO postgres;

--
-- Name: fn_fetch_final_regnumber_rule_17_3(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_final_regnumber_rule_17_3(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) RETURNS record
    LANGUAGE plpgsql
    AS $$
	DECLARE
		v_regnumber text;
		v_serialnumber bigint;
		v_BOOKID bigint;
		v_regdocnumber text default null;
		v_shortname character varying(50);
		V_FINYEAR character varying(50);
		v_pname varchar;
	BEGIN
	
	V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
				to_CHAR(current_date + interval '-12 month', 'YYYY') || 
	'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
				||'-' || to_char(current_date + interval '12 month', 'YY') end );
	
	select  dm.finalregistrationnumber, b.printablename,  dm.bookid,
	sro.shortnamee--,sm.servicename 
	into v_regdocnumber, v_pname, v_BOOKID,
	v_shortname--,applicationtype
	from kaverimrg.documentmaster dm 
	inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
	--INNER join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	--left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	--left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
	join kaverimrg.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
	where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
	
	v_serialnumber:=0;
		
	update kaverimrg.sroserialmaster set finalserial = (coalesce(finalserial,0)+1)::bigint
	where srocode= _srocode and bookid=v_BOOKID and finyear=V_FINYEAR 
	returning finalserial into v_serialnumber;	
	
	if(v_serialnumber=0)
	 then 
	
	 	raise EXCEPTION  'Serial Number could not be generated(%)',v_BOOKID; --EXCEPTION 'Courtorder --> %', v_ordernumber
							--USING HINT = 'Please check property data';
	 	
	end if;
		
	
	
	--select  coalesce(srl.finalserial,0)+1 into v_serialnumber 
	--from kaverimrg.sroserialmaster srl where srocode=_srocode and bookid=v_BOOKID and finyear=V_FINYEAR  for update;
	
	--select v_serialnumber from (select coalesce(srl.finalserial,0)+1
	--into v_serialnumber
	--from kaverimrg.documentmaster dm 
	--inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
	--INNER join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	--left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	--left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
	--join kaverimrg.booktypemaster b on dm.bookid = b.bookid -- Added on Decemeber 16, 2022, to fetch the printable name of the sro
	--where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1) for update;
	
	-- v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
	v_regnumber:= v_shortname||'-'||v_pname||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;
	
	/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
	 from  kaverimrg.sromaster sro where srocode = _srocode;
	SELECT BOOKID INTO v_BOOKID FROM kaverimrg.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
	select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaverimrg.documentmaster dm 
	left join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
	left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
	where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/
	
	if (v_regdocnumber is null) then
	update kaverimrg.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
	registrationdatetime = CURRENT_TIMEstamp, isregistrationcompleted = true
	where applicationnumber = _applicationnumber and srocode= _srocode
	and finalregistrationnumber is null;
	fn_fetch_final_regnumber:=v_regnumber;
	
	else 
	fn_fetch_final_regnumber:=v_regdocnumber;
	end if;
	
	END;
	$$;


ALTER FUNCTION kaverimrg.fn_fetch_final_regnumber_rule_17_3(_srocode integer, _applicationnumber character varying, OUT fn_fetch_final_regnumber text, OUT applicationtype text) OWNER TO postgres;

--
-- Name: fn_fetch_firm_wrkflowcount(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_firm_wrkflowcount(_drocode bigint) RETURNS TABLE(receivedfromcitizen bigint, allocatedtofda_sda bigint, receivedfromfda_sda_sda bigint, senttocitizenforconfirmations bigint, receivedfromcitizenafterconfirmation bigint, receivedfromfdascanandupload bigint, generatecertificateandreadyfordigisign bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
v_AllocatedtoFDA_SDA bigint;
v_ReceivedfromFDA_SDA_SDA bigint;
--v_array bigint[];
begin 

select Count(*) as ReceivedFromCitizen into ReceivedFromCitizen  from(
select distinct * from kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode
	and currentstatus in ('FR106','FA111','FD106','FC106')) receivedfromcit;
	
select Count(*) as AllocatedtoFDA_SDA  into AllocatedtoFDA_SDA from(
select distinct * from kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode 
and currentstatus in('FR107','FA112','FC107','FD107'))allocatedtofda_sda;

select Count(*) as ReceivedfromFDA_SDA_SDA into ReceivedfromFDA_SDA_SDA     from(
select distinct * from kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode
and currentstatus in ('FR109','FA114','FC109','FD109')) sda ;

select Count(*) as SenttocitizenforConfirmations into SenttocitizenforConfirmations  from(
select distinct * from kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode 
and currentstatus in ('FR110','FA115','FC110','FD110'))SenttocitizenforConfirmation;

select Count(*) as Receivedfromcitizenafterconfirmation into Receivedfromcitizenafterconfirmation  from(
SELECT distinct * FROM kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode
and currentstatus in ('FR114','FA119','FC114','FD114'))Receivedfromcitizenafterconfirmation;

select Count(*) as ReceivedfromFDAscanandupload into ReceivedfromFDAscanandupload  from(
SELECT distinct * FROM kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode and
currentstatus  in  ('FR116','FA120','FC116'))ReceivedfromFDAscanandupload;

select Count(*) as Generatecertificateandreadyfordigisign into Generatecertificateandreadyfordigisign  from(
SELECT distinct * FROM kaverimrg.vw_fetch_firm_dr_dashboard where drcode= _drocode 
and currentstatus  in  ('FR117','FA121','FC117','FD117'))Generatecertificateandreadyfordigisign;

return query 
select ReceivedFromCitizen,AllocatedtoFDA_SDA,ReceivedfromFDA_SDA_SDA,SenttocitizenforConfirmations,Receivedfromcitizenafterconfirmation,ReceivedfromFDAscanandupload,Generatecertificateandreadyfordigisign;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_firm_wrkflowcount(_drocode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_firm_wrkflowcount_sda(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_firm_wrkflowcount_sda(_sfdaid bigint) RETURNS TABLE(allocatedtofda_sda bigint, allocatedforscanandupload bigint, readyforissue bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
v_AllocatedtoFDA_SDA bigint;
v_ReceivedfromFDA_SDA_SDA bigint;
--v_array bigint[];
begin 

select Count(*) as AllocatedToFDA_SDA into AllocatedToFDA_SDA  from(
select distinct * from kaverimrg.vw_fetch_pending_sfda_appnum_firm where sfdaid= _sfdaid
and currentstatus in ('FR107','FA112','FC107','FD107')) AllocatedToFDA_SDA;
	
select Count(*) as AllocatedforScanandUpload  into AllocatedforScanandUpload from(
select distinct * from kaverimrg.vw_fetch_pending_sfda_appnum_firm where sfdaid= _sfdaid
and currentstatus in('FR115','FA120','FC116','FD115'))AllocatedforScanandUpload;

select Count(*) as ReadyForissue into ReadyForissue from(
select distinct * from kaverimrg.vw_fetch_pending_sfda_appnum_firm where sfdaid= _sfdaid
and currentstatus in ('FR119','FA122','FD119')) ReadyForissue ;

return query 
select AllocatedToFDA_SDA,AllocatedforScanandUpload,ReadyForissue;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_firm_wrkflowcount_sda(_sfdaid bigint) OWNER TO postgres;

