-- Name: fn_fetch_firmbranches(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_firmbranches(_applicationnumber character varying) RETURNS TABLE(branchid integer, taluknamee character varying, address text, isdeletemarked boolean, dateofdiscont character varying)
    LANGUAGE plpgsql
    AS $$

begin
return query
--	select bg.branchid ,tal.taluknamee,
--	bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
--		stlgd.statenamee||'-'||bg.branchpincode as Address, 
----		case when afb.isremoved = true and f2.applicationnumber not in 
----		(select applicationnumber from kaverimrg.amendmentfirmbranches f) then true else false end isdeletemarked,
--		case when afb.isremoved = true then true else false end isdeletemarked,
----		case when afb.isremoved = true and f2.applicationnumber not in
----		(select applicationnumber from kaverimrg.amendmentfirmbranches f) then
----		to_char(afb.dateofcommencement_discontinuation,'yyyy-MM-dd')::character varying else null end as dateofdiscont
--		to_char(afb.dateofcommencement_discontinuation,'yyyy-MM-dd')::character varying as dateofdiscont
--		from kaverimrg.firmmaster d 
--		inner join kaverimrg.firmbranches bg on d.applicationnumber =bg.applicationnumber
--		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
--		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
--		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode
--		left join kaverimrg.amendmentfirmbranches afb on bg.branchid=afb.branchid
--		--left join kaverimrg.firmamendment f2 on f2.amendmentid = afb.amendmentid
--        where d.applicationnumber=bg.applicationnumber and
--		d.finalregistrationnumber = _finalregistrationnumber
--		order by bg.branchid;

select bg.branchid ,tal.taluknamee,
	bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
		stlgd.statenamee||'-'||bg.branchpincode as Address, 
		case when afb.isremoved = true and f2.applicationnumber in 
		(select applicationnumber from kaverimrg.amendmentfirmbranches f) then true else false end isdeletemarked,
		case when afb.isremoved = true and f2.applicationnumber in
		(select applicationnumber from kaverimrg.amendmentfirmbranches f) then
		to_char(afb.dateofcommencement_discontinuation,'yyyy-MM-dd')::character varying else null end as dateofdiscont
		from kaverimrg.firmmaster d 
		inner join kaverimrg.firmbranches bg on d.applicationnumber =bg.applicationnumber
		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode
		left join kaverimrg.amendmentfirmbranches afb on bg.branchid=afb.branchid and afb.applicationnumber = _applicationnumber
		left join kaverimrg.firmamendment f2 on f2.finalregistrationnumber  = d.finalregistrationnumber
        where d.applicationnumber=bg.applicationnumber and
		f2.applicationnumber = _applicationnumber
		order by bg.branchid;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_firmbranches(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_gscno(); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_gscno() RETURNS TABLE(applicationnumber character varying, gscno character varying, srocode integer)
    LANGUAGE plpgsql
    AS $$
begin
return query
select d.applicationnumber,d.gscno,d.srocode
from kaverimrg.documentmaster d where d.isregistrationcompleted =true and d.gscno is not null 
union all 
select ca.applicationnumber,ca.gscno,ca.kaverimrgsrocode from kaverimrg.cc_applicationdetails ca 
inner join kaverimrg.applicantapplicationdetails a 
on a.applicationnumber = ca.applicationnumber where ca.gscno is not null 
and a.currentstatus='CC109' and ca.gscno is not null 
union all 
select ea.applicationnumber,ea.gscno,ea.kaverimrgsrocode  from kaverimrg.ec_applicationdetails ea 
inner join kaverimrg.applicantapplicationdetails aa on aa.applicationnumber=ea.applicationnumber 
where ea.gscno is not null and aa.currentstatus='CE109' and ea.gscno is not null;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_gscno() OWNER TO postgres;

--
-- Name: fn_fetch_gscno_finalregistrationnumber(integer, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_gscno_finalregistrationnumber(_choice integer, _pagenumber integer DEFAULT NULL::integer, _pagesize integer DEFAULT NULL::integer) RETURNS TABLE(gscno character varying, currentstatus character varying, applicationnumber character varying, finalregistrationnumber character varying, srocode integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((_pagenumber - 1) * _pagesize);

if(_choice = 1) then
return query
select d.gscno,a.currentstatus,a.applicationnumber,d.finalregistrationnumber,a.srocode
from kaverimrg.applicantapplicationdetails a join kaverimrg.documentmaster d on  a.applicationnumber = d.applicationnumber 
where a.currentstatus='CD120'
OFFSET PageOffset   
FETCH NEXT _pagesize ROWS ONLY;

elseif(_choice = 2)then
return query
select d.gscno,a.currentstatus,a.applicationnumber,d.certificatenumber as finalregistrationnumber,a.srocode 
from kaverimrg.applicantapplicationdetails a join kaverimrg.ec_applicationdetails d on  a.applicationnumber = d.applicationnumber 
where a.currentstatus='CE110'
OFFSET PageOffset   
FETCH NEXT _pagesize ROWS ONLY;

else --(_choice = 3)then
return query
select d.gscno,a.currentstatus,a.applicationnumber,d.certificatenumber as finalregistrationnumber,a.srocode
from kaverimrg.applicantapplicationdetails a join kaverimrg.cc_applicationdetails d on  a.applicationnumber = d.applicationnumber 
where a.currentstatus='CC109'
OFFSET PageOffset   
FETCH NEXT _pagesize ROWS ONLY;
end if;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_gscno_finalregistrationnumber(_choice integer, _pagenumber integer, _pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_igrdashboard(timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_igrdashboard(_fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
PageOffset := ((pagenumber - 1) * pagesize);
v_fromdate :=_fromdate;
v_todate :=_todate;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (select distinct to_char(current_date,'DD-MM-YYYY') as current_date, 
concat(to_char(v_fromdate,'DD-MM-YYYY'),' - ',to_char(v_todate,'DD-MM-YYYY'))as date_range, d.districtcode,d.districtnamee,  

count(distinct case when a.currentstatus in ('CD102') then a.applicationnumber else null end) as Received_from_Citizen,  

count(distinct case when a.currentstatus in ('CD103') then a.applicationnumber else null end) as Allocated_to_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD104') then a.applicationnumber else null end) as Received_from_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD106') then a.applicationnumber else null end) as Sent_to_citizen_for_confirmation,  

count(distinct case when a.currentstatus in ('CD108') then a.applicationnumber else null end) as Received_from_citizen_after_confirmation,  

count(distinct case when a.currentstatus in ('CD110') then a.applicationnumber else null end) as Allocated_to_DEO_for_Biometric,  

count(distinct case when a.currentstatus in ('CD111') then a.applicationnumber else null end) as Received_from_DEO_after_Biometric_with_Summary,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,	  

count(distinct case when a.currentstatus in ('CD115') then a.applicationnumber else null end) as Receivedfordigisign,  

count(distinct case when a.currentstatus in ('CD116') then a.applicationnumber else null end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaverimrg.applicantapplicationdetails a  

join kaverimrg.sromaster s on s.srocode = a.srocode  

join kaverimrg.districtmaster d on d.districtcode = s.districtcode  

where a.applicationtypeid in (1,2) 

and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate

group by  d.districtcode,d.districtnamee
order by d.districtnamee asc)as dashboard
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaverimrg.fn_fetch_igrdashboard(_fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_igrdashboard_12072023(integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_igrdashboard_12072023(pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json; 

BEGIN	 
