count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,	  

count(distinct case when a.currentstatus in ('CD115') then a.applicationnumber else null end) as Receivedfordigisign,  

count(distinct case when a.currentstatus in ('CD116') then a.applicationnumber else null end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaverimrg.applicantapplicationdetails a  

join kaverimrg.sromaster s on s.srocode = a.srocode  

join kaverimrg.districtmaster d on d.districtcode = s.districtcode  

where a.applicationtypeid in (1,2) 
	  
	  --and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate

group by  d.districtcode,d.districtnamee
order by d.districtnamee asc)as dashboard
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaverimrg.fn_fetch_igrdashboard_12072023(pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_igrdashboard_sro(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_igrdashboard_sro(_districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;

BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	select array_to_json(array_agg(row_to_json(dashboard)))  into v_data_json

from (select distinct to_char(current_date,'DD-MM-YYYY')as current_date , s.sronamee,  

sum(case when a.currentstatus in ('CD102') then 1 else 0 end) as Received_from_Citizen,  

sum(case when a.currentstatus in ('CD103') then 1 else 0 end) as Allocated_to_SDA_FDA,  

sum(case when a.currentstatus in ('CD104') then 1 else 0 end) as Received_from_SDA_FDA,  

sum(case when a.currentstatus in ('CD106') then 1 else 0 end) as Sent_to_citizen_for_confirmation,  

sum(case when a.currentstatus in ('CD108') then 1 else 0 end) as Received_from_citizen_after_confirmation,  

sum(case when a.currentstatus in ('CD110') then 1 else 0 end) as Allocated_to_DEO_for_Biometric,  

sum(case when a.currentstatus in ('CD111') then 1 else 0 end) as Received_from_DEO_after_Biometric_with_Summary,  

sum(case when a.currentstatus in ('CD112') then 1 else 0 end) as Allocated_to_DEO_for_Printing_with_scanning,  

sum(case when a.currentstatus in ('CD112') then 1 else 0 end) as Allocated_to_DEO_for_Printing_with_scanning,	  

sum(case when a.currentstatus in ('CD115') then 1 else 0 end) as Receivedfordigisign,  

sum(case when a.currentstatus in ('CD116') then 1 else 0 end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaverimrg.applicantapplicationdetails a  
join kaverimrg.sromaster s on s.srocode = a.srocode  and s.districtcode =_districtcode
join kaverimrg.districtmaster d on d.districtcode = s.districtcode  
where a.applicationtypeid in (1,2) 
	  
	  and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate 

group by s.sronamee
order by s.sronamee)as dashboard 
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;
/*update kaverimrg.marriageregistration set   numberofcopy=_numberofcopy,
 declarationdate=current_timestamp,
 declarationplace=_declarationplace where applicationnumber = _applicationnumber;*/
return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_igrdashboard_sro(_districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_igrdashboard_sro_12072023(integer, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_igrdashboard_sro_12072023(_districtcode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;

BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	select array_to_json(array_agg(row_to_json(dashboard)))  into v_data_json

from (select distinct to_char(current_date,'DD-MM-YYYY')as current_date , s.sronamee,  

sum(case when a.currentstatus in ('CD102') then 1 else 0 end) as Received_from_Citizen,  

sum(case when a.currentstatus in ('CD103') then 1 else 0 end) as Allocated_to_SDA_FDA,  

sum(case when a.currentstatus in ('CD104') then 1 else 0 end) as Received_from_SDA_FDA,  

sum(case when a.currentstatus in ('CD106') then 1 else 0 end) as Sent_to_citizen_for_confirmation,  

sum(case when a.currentstatus in ('CD108') then 1 else 0 end) as Received_from_citizen_after_confirmation,  

sum(case when a.currentstatus in ('CD110') then 1 else 0 end) as Allocated_to_DEO_for_Biometric,  

sum(case when a.currentstatus in ('CD111') then 1 else 0 end) as Received_from_DEO_after_Biometric_with_Summary,  

sum(case when a.currentstatus in ('CD112') then 1 else 0 end) as Allocated_to_DEO_for_Printing_with_scanning,  

sum(case when a.currentstatus in ('CD112') then 1 else 0 end) as Allocated_to_DEO_for_Printing_with_scanning,	  

sum(case when a.currentstatus in ('CD115') then 1 else 0 end) as Receivedfordigisign,  

sum(case when a.currentstatus in ('CD116') then 1 else 0 end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaverimrg.applicantapplicationdetails a  
join kaverimrg.sromaster s on s.srocode = a.srocode  and s.districtcode =_districtcode
join kaverimrg.districtmaster d on d.districtcode = s.districtcode  
where a.applicationtypeid in (1,2) 
	  
	  --and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate 

group by s.sronamee
order by s.sronamee)as dashboard 
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;
/*update kaverimrg.marriageregistration set   numberofcopy=_numberofcopy,
 declarationdate=current_timestamp,
 declarationplace=_declarationplace where applicationnumber = _applicationnumber;*/
return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_igrdashboard_sro_12072023(_districtcode integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_igrdashboard_temp(timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_igrdashboard_temp(_fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
PageOffset := ((pagenumber - 1) * pagesize);
v_fromdate :=_fromdate;
v_todate := _todate;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (select distinct to_char(current_date,'DD-MM-YYYY') as current_date,v_fromdate,v_todate, d.districtcode,d.districtnamee,  

count(distinct case when a.currentstatus in ('CD102') then a.applicationnumber else null end) as Received_from_Citizen,  

count(distinct case when a.currentstatus in ('CD103') then a.applicationnumber else null end) as Allocated_to_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD104') then a.applicationnumber else null end) as Received_from_SDA_FDA,  

count(distinct case when a.currentstatus in ('CD106') then a.applicationnumber else null end) as Sent_to_citizen_for_confirmation,  

count(distinct case when a.currentstatus in ('CD108') then a.applicationnumber else null end) as Received_from_citizen_after_confirmation,  

count(distinct case when a.currentstatus in ('CD110') then a.applicationnumber else null end) as Allocated_to_DEO_for_Biometric,  

count(distinct case when a.currentstatus in ('CD111') then a.applicationnumber else null end) as Received_from_DEO_after_Biometric_with_Summary,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,  

count(distinct case when a.currentstatus in ('CD112') then a.applicationnumber else null end) as Allocated_to_DEO_for_Printing_with_scanning,	  

count(distinct case when a.currentstatus in ('CD115') then a.applicationnumber else null end) as Receivedfordigisign,  

count(distinct case when a.currentstatus in ('CD116') then a.applicationnumber else null end) as Sent_to_FDA_SDA_for_Acknowledgement  

from kaverimrg.applicantapplicationdetails a  

join kaverimrg.sromaster s on s.srocode = a.srocode  

join kaverimrg.districtmaster d on d.districtcode = s.districtcode  

where a.applicationtypeid in (1,2) 

and a.applicationstartdate::date >=_fromdate and a.applicationstartdate::date <=_todate

group by  d.districtcode,d.districtnamee
order by d.districtnamee asc)as dashboard
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

return v_data_json; 

END; 

$$;


ALTER FUNCTION kaverimrg.fn_fetch_igrdashboard_temp(_fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_index_search_json_firm(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_index_search_json_firm(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
v_finalregdno text;
_districtcode integer;
_talukcode integer;
_firmname text;
 _finalregdno text;
 _from_date timestamp without time zone;
 _to_date timestamp without time zone;
  
BEGIN

	select ecfm.kaverimrgdrocode,ecfm.kaverimrgtalukcode,ecfm.searchfromdate,
	ecfm.searchtodate,ef.firmname,ef.finalregistrationnumber 
	into _districtcode,_talukcode,_from_date,_to_date,_firmname,_finalregdno
	from kaverimrg.ec_applicationdetails_firm ecfm 
	join kaverimrg.ec_firmregistrationdetails ef on ecfm.ecid=ef.ecid 
	where ecfm.applicationnumber=_applicationnumber;

	if _finalregdno is not null then
	
	  v_finalregdno=_finalregdno ;
	 
	else 
	
	  select f.finalregistrationnumber  into v_finalregdno 
	 from kaverimrg.firmmaster f where f.firmname=_firmname;
	
 end if;

raise notice 'finalregno%',v_finalregdno;
raise notice 'finalregno%',_finalregdno;


	
 select (row_to_json(data_json)) into v_data_json
  from (select d.firmname,d.applicationnumber,d.finalregistrationnumber,
   s.servicename,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Pincipal_place_of_business,	
		d.finalregistrationnumber ,  (select array_to_json(array_agg(row_to_json(partnerdetails))) as PartnerDetails
  from(select   br.firmpersonid, br.firstname,br.middlename,br.lastname 

from kaverimrg.firmparty br where br.applicationnumber=d.applicationnumber) partnerdetails  ),

(select array_to_json(array_agg(row_to_json(amendmentdetails))) as Amendmentdetails
  from (select  f.applicationnumber,f.finalregistrationnumber,'Firm Amendment'|| ' ' ||
mfa.description  as servicename,f.inserteddatetime
from kaverimrg.firmamendment f 
join kaverimrg.mas_frm_amendmenttypes mfa  on f.amendmenttypeid=mfa.amendmenttypeid 
join kaverimrg.applicantapplicationdetails a2 on a2.applicationnumber=f.applicationnumber 
  where f.finalregistrationnumber=v_finalregdno
 and f.inserteddatetime between  _from_date  and _to_date 
-- and 
--a2.currentstatus in ('FA122')
)amendmentdetails),

(select array_to_json(array_agg(row_to_json(reconstituriondetails))) as Reconstituriondetails
  from (select f.applicationnumber,f.firmfinalregnumber,s.servicename,f.inserteddatetime
from kaverimrg.firmreconstitution f 
join kaverimrg.applicantapplicationdetails a2 on a2.applicationnumber=f.applicationnumber
join kaverimrg.servicesmaster s 	on a2.applicationtypeid=s.serviceid  
  where f.firmfinalregnumber=v_finalregdno
 and   f.inserteddatetime between  _from_date  and _to_date 
-- and 
-- a2.currentstatus in ('FC119')
 )reconstituriondetails),
 (select array_to_json(array_agg(row_to_json(desolutiondetails))) as Desolutiondetails
  from (select fd.applicationnumber,fd.finalregistrationnumber,s.servicename,
 fd.inserteddatetime from kaverimrg.firm_dissolution fd 
 join kaverimrg.applicantapplicationdetails a2 on fd.applicationnumber=a.applicationnumber 
 join kaverimrg.servicesmaster s 	on a2.applicationtypeid=s.serviceid
 where fd.finalregistrationnumber=v_finalregdno
 and   fd.inserteddatetime between  _from_date  and _to_date 
 --and 
 --a2.currentstatus in ('FD120')
  )desolutiondetails),
  (select array_to_json(array_agg(row_to_json(protestentrydetails))) as Protestentrydetails
  from (select f2.applicationnumber,f2.finalregistrationnumber,
  s.servicename,f2.inserteddatetime   from kaverimrg.firmprotestentry f2 
  join kaverimrg.applicantapplicationdetails a2 on f2.applicationnumber=a2.applicationnumber 
  join kaverimrg.servicesmaster s 	on a2.applicationtypeid=s.serviceid
 where f2.finalregistrationnumber=v_finalregdno
 and   f2.inserteddatetime between  _from_date  and _to_date
 )protestentrydetails)
 --and 
 --a2.currentstatus in ('FD120')


			from kaverimrg.firmmaster d 
		inner join kaverimrg.applicantapplicationdetails a on d.applicationnumber =a.applicationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
		left join kaverimrg.servicesmaster s on a.applicationtypeid =s.serviceid 
			where 
			d.districtcode =_districtcode  and d.talukacode=_talukcode 
and  d.finalregistrationnumber=v_finalregdno 
and  
--a.currentstatus like 'FR%' and a.currentstatus>='FR118' and 
(a.applicationstartdate  between _from_date  and _to_date  )
			
	   	)data_json;
	   	

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_index_search_json_firm(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_indexii_final_registration(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_indexii_final_registration(_finalregistrationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	
--select row_to_json(app_json) into v_data_json
from ( select 
 pm.applicationnumber,
 pm.propertyid,
 pm.marketvalue,
 pm.consideration,
 ra.articlenamee,
 pm.eastboundary AS east,
 pm.westboundary AS west,
 pm.northboundary AS north,
 pm.southboundary AS south,
 pm.totalarea AS area,
 pm.villagecode,
 v.villagenamee,
 v.hoblicode,
 --h.hoblinamee,
 --r.referencetext,
 (select referencetext from kaverimrg.referencemaster where documentid=dm.documentid order by lstupddate desc limit 1),
( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from ( select 
pn.currentpropertytypeid,
 pn.currentnumber,
 pn.currentnumber AS aptno_new,
 pn.oldnumber AS oldno
from  kaverimrg.propertynumberdetails pn WHERE
			pm.propertyid = pn.propertyid  
			and (pn_src.srocode,pn_src.currentpropertytypeid, pn_src.currentnumber) = 
			(pn.srocode,pn.currentpropertytypeid, pn.currentnumber)
  )propertynodetails) as propnumberdetails,
( select array_to_json(array_agg(row_to_json(propertyschedules)))
      from ( 
--Code Begins for Property Schedules
select 
ps.easttowest,
 ps.northtosouth,
 case when pas.propertyid is not null then
 concat(ps.description, ' Allotted to: ', string_agg(pin.firstname || pin.middlename || pin.lastname,' & ')) 
else
ps.description end as
 description
from kaverimrg.propertyschedules ps
join kaverimrg.partyschedules pas on ps.propertyid=pas.propertyid 
join kaverimrg.partyinfo pin on pas.partyid=pin.partyid 
where ps.propertyid = pm.propertyid
		   group by ps.easttowest, ps.northtosouth,ps.description,pas.propertyid
--Code Ends for Property Schedules	  
)propertyschedules)as propertyschedules,
( select array_to_json(array_agg(row_to_json(partydetails)))
      from ( select distinct pi.partyid,
 (
        CASE
            WHEN pi.partytypeid = 1 THEN concat(pi.firstname,', ',pi.middlename,', ',pi.lastname)
            ELSE NULL::text
        END::text) AS claimant,
 (
        CASE
            WHEN pi.partytypeid = 2 THEN concat(pi.firstname,', ',pi.middlename,', ',pi.lastname)
            ELSE NULL::text
        END::text) AS executant,
		     pi.address from kaverimrg.partyinfo pi 
			join kaverimrg.partyschedules ps on pi.partyid=ps.partyid
			where pi.documentid = dm.documentid
--group by pi.partyid,pi.address,ps.propertyid
)partydetails) as partydetails,
( select array_to_json(array_agg(row_to_json(documentdetails)))
   from (select dm.documentid,
    dm.srocode,
    dm.registrationdatetime AS executiondate,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference)documentdetails)as documentdetails, 
	(select note_enteredpart from kaverimrg.dec_drpndnote where propertyid=pm.propertyid order by insertdatetime desc limit 1) as correctionnote
     from 
	  kaverimrg.documentmaster dm left outer join
	  kaverimrg.propertymaster pm ON pm.documentid = dm.documentid and Isregistrationcompleted=true
	  inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode --reverting to revenue village code instead of v.bhoomivillagecode 
	  inner join kaverimrg.propertynumberdetails pn_src on pm.propertyid = pn_src.propertyid AND pn_src.srocode = v.srocode
      --inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode --Commenting hoblimaster join as FRUITS is using dummy data
       JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
      where  dm.finalregistrationnumber =_finalregistrationnumber
--) app_json;
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_indexii_final_registration(_finalregistrationnumber character varying) OWNER TO postgres;

