	  inner join kaverimrg.villagemaster v on pm.villagecode = v.villagecode 
	  inner join kaverimrg.propertynumberdetails pn_src on pm.propertyid = pn_src.propertyid AND pn_src.srocode = v.srocode
      --inner JOIN kaverimrg.hoblimaster h ON v.hoblicode = h.hoblicode --Commenting hoblimaster join as FRUITS is using dummy data
      left JOIN kaverimrg.registrationarticles ra ON ra.regarticlecode = dm.regarticlecode
      where  dm.finalregistrationnumber =_finalregistrationnumber
--) app_json;
)  app_json ) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_indexii_final_registration_for_correctionnote(_finalregistrationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_insert_documentmaster_pending_regis(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_insert_documentmaster_pending_regis(_applicationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber varchar;
v_regarticlecode int;
v_stamp5datetime timestamp without time zone;
v_bookid int;
v_remarks varchar;
v_minutedate timestamp without time zone;
v_pendingdocumentnumber varchar;
v_sronoofscanpages int;
v_docid bigint;
v_cnt bigint;
v_srocode int;

begin 
	v_applicationnumber := _applicationnumber;

	select count(*) into v_cnt from kaverimrg.documentmaster where applicationnumber = _applicationnumber;

	if v_cnt = 0 then

	select p.applicationnumber,
		p.srocode ,
		p.regarticlecode,
		LOCALTIMESTAMP as stamp5datetime,
		r.bookid,
		md.remarks,
		md.minutedate,
		md.pendingregistrationnumber,
		p.sronoofscanpages into v_applicationnumber,v_srocode,v_regarticlecode,v_stamp5datetime,
		v_bookid,v_remarks,v_minutedate,v_pendingdocumentnumber,v_sronoofscanpages
	from kaverimrg.propertymaster p
	join kaverimrg.minutebook_data md on md.applicationnumber = p.applicationnumber 
	join kaverimrg.registrationarticles r on p.regarticlecode = r.regarticlecode 
	where p.applicationnumber  =_applicationnumber limit 1;


	select * into v_docid from kaverimrg.fn_insert_documentmaster_pending_regis(v_applicationnumber,null,v_srocode,v_regarticlecode,v_stamp5datetime,v_bookid,v_remarks,v_minutedate,v_pendingdocumentnumber,v_sronoofscanpages);
	
	else
	
	select documentid into v_docid from kaverimrg.documentmaster d where applicationnumber = _applicationnumber;

end if;
return v_docid;
end
$$;


