--
-- Name: fn_fetch_liability_details_json_check(bigint, bigint, text, bigint, bigint, character varying, bigint, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_liability_details_json_check(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint DEFAULT NULL::bigint, _propertyid bigint DEFAULT NULL::bigint, _propertynumber character varying DEFAULT NULL::character varying, _survey_no bigint DEFAULT NULL::bigint, _hissa_no character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$


declare 
v_data_json json;
BEGIN
select  row_to_json(app_json) into v_data_json
from 
(
SELECT  A.SROCODE,
B.SRONAMEE AS SRONAMEE,
A.Bookid,
C.BOOKNAMEENGLISH AS BOOKNAME,
case when cast(to_char(A.EXECUTIONDATETIME,'MM') as bigint)>3 then cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(A.EXECUTIONDATETIME  + interval '1 year','YY')
else cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(A.EXECUTIONDATETIME,'YY') end AS FINANCIAL_YEAR,
A.DOCUMENTNUMBER,
	--*****************Add Property Number details***********************--
	( select array_to_json(array_agg(row_to_json(propertynodetails)))
      from (
	  select  'NOTE :'||' '||ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
      pn.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
	  string_agg(distinct case when pi.partytypeid = 1 
	 --or ps.propertyid is not null -- Commented by Shubham on 06-01-2023.
	 then pi.firstname||''||pi.middlename||''||pi.lastname end,',') as claimant,
	  string_agg(distinct case when pi.partytypeid = 2 then pi.firstname||''||pi.middlename||''||pi.lastname end,',') as executant,
        'Order number :'||' '||lop.ORDERNUMBER||'<br/><br/>'||lop.liabilitynote||' Issue Date :'||' '||to_char(lop.issuedate,'dd-MM-yyyy') as liabilitydetails,
	  pn.propertyid
	  from kaverimrg.partyinfo pi left outer join kaverimrg.propertyschedules ps
	  on pi.applicationnumber=ps.applicationnumber left outer join kaverimrg.propertynumberdetails pn on
	  pn.propertyid=ps.propertyid left outer join kaverimrg.LIABILITYONPROPERTYDETAILS lp
	  on pn.propertyid=lp.propertyid --and lp.orderissuedate is not null
	  left join kaverimrg.liabilitydetails lop on lp.liabilityid=lop.liabilityid
	  where pi.applicationnumber=A.applicationnumber and pn.srocode=a.srocode 
	  group by pn.CURRENTNUMBER, ps.DESCRIPTION, ps.SCHEDULETYPE, lop.ORDERNUMBER,lop.issuedate,lop.liabilitynote,pn.propertyid
	  )propertynodetails) as propnumberdetails,
	  --*****************Exact Property Number details***********************--
      (select array_to_json(array_agg(row_to_json(exactpropertydetails)))
      from (select distinct dm.FINALREGISTRATIONNUMBER,
      dm.EXECUTIONDATETIME AS EXECUTIONDATE,
      sm.ARTICLENAMEE AS ARTICLENAME,
      pm1.LANDMARK,
      pnd.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
      'NOTE :'||' '||psd.SCHEDULETYPE ||' '||psd.DESCRIPTION AS PROPERTYDESCRIPTION, pm1.propertyid
	  from kaverimrg.propertynumberdetails pnd 
	  left join kaverimrg.propertymaster pm1 on pnd.propertyid=pm1.propertyid 
	  left join kaverimrg.documentmaster dm on pm1.applicationnumber=dm.applicationnumber
	  left join kaverimrg.stamparticles sm on pm1.stamparticlecode=sm.stamparticlecode
	  left join kaverimrg.propertyschedules psd on pm1.propertyid=psd.propertyid
	  where pnd.currentnumber=PR.currentnumber and finalregistrationnumber is not null and pnd.srocode=a.srocode
	  )exactpropertydetails ) 
	  as exactpropdetails,
	  --*****************Similar Property Number details***********************--
      (select array_to_json(array_agg(row_to_json(similarpropertydetails)))
      from (select distinct dm1.FINALREGISTRATIONNUMBER,
      dm1.EXECUTIONDATETIME AS EXECUTIONDATE,
      sm1.ARTICLENAMEE AS ARTICLENAME,
      pm2.LANDMARK,
      pnd1.CURRENTNUMBER AS PROPERTYNUMBERDETAILS,
      'NOTE :'||' '||psd1.SCHEDULETYPE ||' '||psd1.DESCRIPTION AS PROPERTYDESCRIPTION, pm2.propertyid 
	  from kaverimrg.propertynumberdetails pnd1 
	  left join kaverimrg.propertymaster pm2 on pnd1.propertyid=pm2.propertyid 
	  left join kaverimrg.documentmaster dm1 on pm2.applicationnumber=dm1.applicationnumber
	  left join kaverimrg.stamparticles sm1 on pm2.stamparticlecode=sm1.stamparticlecode
	  left join kaverimrg.propertyschedules psd1 on pm2.propertyid=psd1.propertyid
	  where pnd1.currentnumber like '%'||PR.currentnumber||'%' and finalregistrationnumber is not null
	  and pnd1.srocode=a.srocode
	  )similarpropertydetails ) 
	  as similarpropdetails
	
FROM kaverimrg.DOCUMENTMASTER A LEFT OUTER JOIN kaverimrg.SROMASTER B
ON A.SROCODE = B.SROCODE AND EXECUTIONDATETIME IS NOT NULL and a.srocode > 0
LEFT OUTER JOIN kaverimrg.BOOKTYPEMASTER C ON C.BOOKID = A.BOOKID
LEFT OUTER JOIN kaverimrg.PROPERTYMASTER D ON D.DOCUMENTID = A.DOCUMENTID 
LEFT OUTER join kaverimrg.PROPERTYNUMBERDETAILS PR ON D.PROPERTYID = PR.PROPERTYID
LEFT OUTER join kaverimrg.STAMPARTICLES S ON S.STAMPARTICLECODE = D.STAMPARTICLECODE
where a.srocode = _srocode and a.bookid = _bookid and (a.documentnumber=_documentnumber or (PR.currentpropertytypeid=_propertyid and (pr.currentnumber=_propertynumber or
(pr.survey_no=_survey_no and pr.hissa_no=_hissa_no)))) and
case when cast(to_char(A.EXECUTIONDATETIME,'MM') as bigint)>3 then cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(A.EXECUTIONDATETIME  + interval '1 year','YY')
else cast(to_char(A.EXECUTIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(A.EXECUTIONDATETIME,'YY') end=_finyear
and A.FINALREGISTRATIONNUMBER IS NOT NULL
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_liability_details_json_check(_srocode bigint, _bookid bigint, _finyear text, _documentnumber bigint, _propertyid bigint, _propertynumber character varying, _survey_no bigint, _hissa_no character varying) OWNER TO postgres;

--
-- Name: fn_fetch_liability_report_json_check(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_liability_report_json_check(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select array_to_json(array_agg(row_to_json(app_json))) into v_data_json
from (
select  a.liabilityid, a.srocode,
	s.sronamee as sroname,
	a.issuedate as liabilitydate,
	d.finalregistrationnumber,
	c.documentid,
	d.documentnumber,
	a.liabilitynote,
	a.ordernumber,
	c.propertyid,
	'Schedule '||ps.scheduletype || ' - ' || ps.description as Schedule,
	string_agg(g.currentnumber,', ') propertynumberdetails,
	f.villagenamee,
	a.liabilityfromdate,
a.liabilityadditionalnote,
a.amount,
a.issuedby
    /*( select array_to_json(array_agg(row_to_json(liability_report)))
      from (select  --'report generated from'||' '||_fromdate||' '||_todate,
			c.ordernumber,
			a.liabilitynote,
			a.issuedate as liabilitydate,
			'' as liabilityadditionalnote,
            d.finalregistrationnumber,
			g.currentnumber||','||g.survey_no as propertyschedule,
			g.currentnumber as propertynumberdetails
            --e.villagecode,
			--f.villagenamee 
		   )liability_report ) 
			as liabilityreport*/
	from
kaverimrg.liabilitydetails a 
left join kaverimrg.sromaster s on s.srocode = a.srocode
left join kaverimrg.liabilityonpropertydetails c on c.liabilityid = a.liabilityid
left join kaverimrg.propertyschedules ps on c.propertyid=ps.propertyid
left join kaverimrg.documentmaster d on d.documentnumber = c.documentid and d.srocode=a.srocode
left join kaverimrg.propertymaster e on e.documentid = d.documentid and e.propertyid=c.propertyid
left join kaverimrg.villagemaster f on f.villagecode = e.villagecode
left join kaverimrg.propertynumberdetails g on g.propertyid = e.propertyid 
where a.srocode = _srocode and a.isdeleted=false
and a.issuedate between _fromdate and _todate
	group by a.liabilityid, a.srocode, s.sronamee, a.issuedate, d.finalregistrationnumber, c.documentid,
	d.documentnumber, a.liabilitynote, c.propertyid, ps.scheduletype, ps.description, f.villagenamee
--and g.currentnumber||','||g.survey_no is not null and g.currentnumber||','||g.survey_no not like 'string%'
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_liability_report_json_check(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_fetch_marriage_mas_idprooftypes(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_marriage_mas_idprooftypes(_prooftypeid integer) RETURNS TABLE(prooftype character varying, idprooftypeid smallint, description character varying)
    LANGUAGE plpgsql
    AS $$
begin
	
return query
select mp.prooftype ,mi.idprooftypeid ,mi.description 
from kaverimrg.mas_idprooftypes mi
join kaverimrg.mas_prooftypes_idproof_mapping mm on mm.idprooftypeid  = mi.idprooftypeid
join kaverimrg.mas_prooftypes mp on mp.prooftypeid = mm.prooftypeid 
where mm.prooftypeid = _prooftypeid;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_marriage_mas_idprooftypes(_prooftypeid integer) OWNER TO postgres;

--
-- Name: fn_fetch_masval_pendingapproval_sro(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer) RETURNS TABLE(valrateheaderid bigint, circularinfo text, circularpath text, effectivedate timestamp without time zone, roadcode bigint, roadname character varying, roadnamek character varying, srocode bigint, villagecode bigint, villagename character varying, villagenamek character varying, hoblicode integer, hobliname character varying, sfdaid bigint, masval json)
    LANGUAGE plpgsql
    AS $$

BEGIN
   RETURN QUERY
   SELECT mh.valrateheaderid,
    mh.circularinfo,
    mh.circularpath,
    mh.effectivedate,
    mval.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    mval.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    mh.sfdaid,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM kaverimrg.mas_valratedetail m
                             JOIN kaverimrg.mas_val_agrilandtypes agri_ty ON m.agrilandtypeid = agri_ty.agrilandtypeid
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaverimrg.rateagriculturaldetail ad) r ON r.roadcode = m.roadcode AND m.agrilandtypeid = r.agrilandtypeid AND m.propertytypeid = 17 AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.propertytypeid = 17) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM kaverimrg.mas_valratedetail m
                             JOIN kaverimrg.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaverimrg.openbuiltratedetail br) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.agrilandtypeid IS NULL AND m.amenitiesid IS NULL) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.namewithamenities AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            amn.namewithamenities,
                            m.rate AS rate_val
                           FROM kaverimrg.mas_valratedetail m
                             JOIN kaverimrg.mas_val_apartmentsamenities amn ON amn.amenitiesid = m.amenitiesid
                             JOIN kaverimrg.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaverimrg.mas_val_flatrates op
                                  WHERE op.amenitiesid IS NOT NULL) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND m.amenitiesid = r.amenitiesid AND m.floorid = r.floorid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.amenitiesid IS NOT NULL AND m.agrilandtypeid IS NULL) ra
                  WHERE ra.roadcode = mval.roadcode) val) AS masval
   FROM kaverimrg.mas_valrateheader mh
     JOIN ( SELECT DISTINCT mas_valratedetail.sfdaid,
            mas_valratedetail.srocode,
            mas_valratedetail.roadcode,
            mas_valratedetail.valrateheaderid
           FROM kaverimrg.mas_valratedetail
          WHERE mas_valratedetail.valrateheaderid IS NOT null and mas_valratedetail.valrateheaderid=_valrateheaderid) mval ON mh.valrateheaderid = mval.valrateheaderid
     JOIN kaverimrg.roadmaster rm ON rm.roadcode = mval.roadcode
     JOIN kaverimrg.villagemaster_bck_12062023 vm ON vm.villagecode = rm.villagecode
     JOIN kaverimrg.hoblimaster_bck_12062023 h ON vm.hoblicode = h.hoblicode
     where mh.valrateheaderid =_valrateheaderid;
	 
	 END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer) OWNER TO postgres;

--
-- Name: fn_fetch_masval_pendingapproval_sro(integer, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(requestno bigint, circularinfo text, circularpath text, effectivedate timestamp without time zone, roadcode bigint, roadname character varying, roadnamek character varying, srocode bigint, villagecode bigint, villagename character varying, villagenamek character varying, hoblicode integer, hobliname character varying, sfdaid bigint, masval json)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
   RETURN QUERY
   SELECT mh.valrateheaderid as requestNo,
    mh.circularinfo,
    mh.circularpath,
    mh.effectivedate,
    mval.roadcode,
    rm.roadnamee AS roadname,
    rm.roadnamek,
    mval.srocode,
    vm.villagecode,
    vm.villagenamee AS villagename,
    vm.villagenamek,
    h.hoblicode,
    h.hoblinamee AS hobliname,
    mh.sfdaid,
    ( SELECT array_to_json(array_agg(row_to_json(val.*))) AS array_to_json
           FROM ( SELECT 'Agriculture'::text AS propertytype,
                    ra.rate,
                    ra.agrilandtypedesc AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.agrilandtypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            agri_ty.description AS agrilandtypedesc,
                            m.rate AS rate_val
                           FROM kaverimrg.mas_valratedetail m
                             JOIN kaverimrg.mas_val_agrilandtypes agri_ty ON m.agrilandtypeid = agri_ty.agrilandtypeid
                             LEFT JOIN ( SELECT ad.roadcode,
                                    ad.agrilandtypeid,
                                    ad.villagecode,
                                    ad.measurementcode,
                                    ad.rate,
                                    ad.effectivedate,
                                    COALESCE(lead(ad.effectivedate, 1) OVER (PARTITION BY ad.roadcode, ad.agrilandtypeid ORDER BY ad.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaverimrg.rateagriculturaldetail ad) r ON r.roadcode = m.roadcode AND m.agrilandtypeid = r.agrilandtypeid AND m.propertytypeid = 17 AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.propertytypeid = 17) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Vacant Land/Building'::text AS propertytype,
                    ra.rate,
                    ra.propertytypename AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.rate AS rate_val
                           FROM kaverimrg.mas_valratedetail m
                             JOIN kaverimrg.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT br.roadcode,
                                    br.propertytypeid,
                                    br.rate,
                                    br.measurementcode,
                                    br.effectivedate,
                                    COALESCE(lead(br.effectivedate, 1) OVER (PARTITION BY br.roadcode, br.propertytypeid ORDER BY br.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaverimrg.openbuiltratedetail br) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.agrilandtypeid IS NULL AND m.amenitiesid IS NULL) ra
                  WHERE mval.roadcode = ra.roadcode
                UNION ALL
                 SELECT 'Apartment/Flat'::text AS propertytype,
                    ra.rate,
                    ra.namewithamenities AS typedesc,
                    ra.rate_val
                   FROM ( SELECT m.roadcode,
                            r.propertytypeid,
                            r.measurementcode,
                            r.rate,
                            r.effectivedate,
                            ptm.propertytypename,
                            m.amenitiesid,
                            m.floorid,
                            amn.namewithamenities,
                            m.rate AS rate_val
                           FROM kaverimrg.mas_valratedetail m
                             JOIN kaverimrg.mas_val_apartmentsamenities amn ON amn.amenitiesid = m.amenitiesid
                             JOIN kaverimrg.propertytypemaster ptm ON ptm.propertytypeid = m.propertytypeid
                             LEFT JOIN ( SELECT op.roadid AS roadcode,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid,
                                    op.unitid AS measurementcode,
                                    op.rate,
                                    op.effectivedate,
                                    COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
                                   FROM kaverimrg.mas_val_flatrates op
                                  WHERE op.amenitiesid IS NOT NULL) r ON r.roadcode = m.roadcode AND m.propertytypeid <> 17 AND m.agrilandtypeid IS NULL AND m.propertytypeid = r.propertytypeid AND m.amenitiesid = r.amenitiesid AND m.floorid = r.floorid AND CURRENT_DATE >= r.effectivedate AND CURRENT_DATE <= r.effectivetodate
                          WHERE  m.valrateheaderid=_valrateheaderid AND mval.roadcode = m.roadcode AND mval.sfdaid = m.sfdaid AND m.amenitiesid IS NOT NULL AND m.agrilandtypeid IS NULL) ra
                  WHERE ra.roadcode = mval.roadcode) val) AS masval
   FROM kaverimrg.mas_valrateheader mh
     JOIN ( SELECT DISTINCT mas_valratedetail.sfdaid,
            mas_valratedetail.srocode,
            mas_valratedetail.roadcode,
            mas_valratedetail.valrateheaderid
           FROM kaverimrg.mas_valratedetail
          WHERE mas_valratedetail.valrateheaderid IS NOT null and mas_valratedetail.valrateheaderid=_valrateheaderid
		  and (mas_valratedetail.isapproved is null )) mval ON mh.valrateheaderid = mval.valrateheaderid
     JOIN kaverimrg.roadmaster rm ON rm.roadcode = mval.roadcode
     JOIN kaverimrg.villagemaster vm ON vm.villagecode = rm.villagecode
     JOIN kaverimrg.hoblimaster h ON vm.hoblicode = h.hoblicode
     where mh.valrateheaderid =_valrateheaderid 
    OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	 
	 END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_masval_pendingapproval_sro(_valrateheaderid integer, pagenumber integer, pagesize integer) OWNER TO postgres;

