CREATE FUNCTION kaverimrg.fn_fetch_masval_pendingapproval_sro_test(_valrateheaderid integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
 

SELECT array_to_json(array_agg(row_to_json(arr))) into  v_data_json
from  (
select array_to_json(array_agg(row_to_json(temp))) as data,count(*) as Total from (


SELECT mh.valrateheaderid as requestNo,
    mh.circularinfo,
    mh.circularpath,
    mval.roadcode,
    mh.effectivedate,
    rm.roadnamee AS roadname,
    mval.srocode,
    vm.villagenamee AS villagename,
