ALTER FUNCTION kaverimrg.fn_fetch_masval_pendingapproval_sro_test_1(_valrateheaderid integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_minutebook_deo(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_minutebook_deo(p_deoid text) RETURNS TABLE(applicationnum character varying, applicationdate date, applicationtime time without time zone, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, ispropertydetails boolean, ispartydetails boolean, ispropertyschedule boolean, isvaluationfees boolean, ispaymentdetails boolean, presentdate date, executedate date, pendingdocumentnumber character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  select ad.applicationnumber applicationnum,slot.slotbookdate as applicationdate,
  slot.slotbooktime as applicationtime,ad.srocode,ad.applicationtypeid,sm.servicename,
ad.currentstatus,wm.wrkflowstatusnamee,coalesce(dm.ispropertydetails,'false') as ispropertydetails,
coalesce(dm.ispartydetails,'false') as ispartydetails,
coalesce(dm.ispropertyschedule,'false') as ispropertyschedule,
coalesce(dm.isvaluationfees,'false') as isvaluationfees,
coalesce(dm.ispaymentdetails,'false') as ispaymentdetails,
dm.presentdatetime::date presentdate,
dm.executiondatetime::date as executedate,dm.pendingdocumentnumber
from kaverimrg.ApplicantApplicationdetails ad 
inner join kaverimrg.documentmaster dm on (dm.applicationnumber = ad.applicationnumber)
inner join (select sl.applicationnumber,sl.sltbookedon, sl.sltbookedon::date as slotbookdate,
			sl.sltbookedon::time as slotbooktime
			from kaverimrg.slottxn sl
	where sltservicestatus= 1
			and sltbookedon = 
			(select max(sltbookedon) from kaverimrg.slottxn slt
			 where slt.applicationnumber = sl.applicationnumber)) slot 
						   on slot.applicationnumber= ad.applicationnumber
left outer join kaverimrg.Wrkflowmaster wm on wm.wrkflowstatusid = ad.currentstatus 
left join kaverimrg.servicesmaster sm on ad.applicationtypeid = sm.serviceid 
where ad.assignedto = p_deoid and 
ad.currentstatus in ('CD121')
order by slot.sltbookedon ;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_minutebook_deo(p_deoid text) OWNER TO postgres;

--
-- Name: fn_fetch_module_info(); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_module_info() RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
v_data_json json;
BEGIN
  select json_agg(mdl) as modules into v_data_json from  (select m.moduleid,m.modulename,(select json_agg(sbm) as submodules from
 (select s.submoduleid,s.submodulename,(select json_agg(fbm)as functions from (select f.functionid,f.functionname  from kaverimrg.functionmaster f 
 where f.moduleid=s.moduleid and f.submoduleid=s.submoduleid ) as fbm)
 from kaverimrg.submodulemaster s where moduleid=m.moduleid  ) as sbm) 
 
 from kaverimrg.modulemaster as  m ) as mdl;
 
 return v_data_json;
 
END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_module_info() OWNER TO postgres;

--
-- Name: fn_fetch_movable_property_details_json_check(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_movable_property_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
select
	a.propertytypeid,
    k.applicationnumber,
    (l.propertytypename::text || ' '::text) || a.movablepropertydesc as propertydescription,
    a.propertyid,
    a.stamparticlecode,
    b.articlenamee AS stamparticleselected,
    a.stampruleid,
    c.descriptione AS stampsubarticleselected,
    a.regarticlecode,
    d.articlenamee AS registrationfeearticleselected,
    d.bookid,
    e.booknameenglish AS booknumber,
	j.deedattachpath AS uploaddeeddocument,
    j.executiondatetime AS dateofexecution,
	( select array_to_json(array_agg(row_to_json(feecalculation)))
      from (select 
	a.consideration AS totalconsiderationamount,
    a.govtduty,
    a.noofscanpages::numeric * 2.5 AS scanningfees,
    0 AS denotationofstampduty
	  )feecalculation) as feedetails,
( select array_to_json(array_agg(row_to_json(partyinfodetails)))
      from (select   string_agg(
        CASE
            WHEN f.ispresenter = true THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS presenter,
    string_agg(
        CASE
            WHEN f.isexecutor = false THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS claimant,
    string_agg(
        CASE
            WHEN f.isorganization = true AND f.isexecutor = true THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS executant,
    f.age,
    f.sex,
    f.address,
    f.pan,
    f.profession from
		kaverimrg.partyinfo f where f.propertyid = a.propertyid
						group by  f.age,
    f.sex,
    f.address,
    f.pan,
    f.profession
		   )partyinfodetails ) 
			as partydetails,
	( select array_to_json(array_agg(row_to_json(witnessdetails)))
      from ( select
	 h.name,
    h.age AS witnessage,
    h.sex AS witnesssex,
    h.address AS witnessaddress  
		  from kaverimrg.witnessinfo h 
     JOIN  kaverimrg.partywitness g ON 
			g.witnessid = h.witnessid
			join kaverimrg.partyinfo p on
			p.partyid = g.partyid
	  )witnessdetails) as witnessinformation,
	( select array_to_json(array_agg(row_to_json(srodetails)))
      from ( select
	 a.srocode,
    i.sronamee  
		  from kaverimrg.sromaster i where i.srocode = a.srocode
	  )srodetails) as srodetail
	FROM kaverimrg.propertymaster a
     JOIN kaverimrg.stamparticles b ON a.stamparticlecode = b.stamparticlecode AND b.stamparticlecode = 5
     JOIN kaverimrg.stamprules c ON c.stamparticlecode = b.stamparticlecode AND c.stampruleid = 19 AND c.stamparticlecode = 5
     JOIN kaverimrg.registrationarticles d ON d.regarticlecode = a.regarticlecode AND d.regarticlecode = 72
     JOIN kaverimrg.booktypemaster e ON e.bookid = d.bookid
     JOIN kaverimrg.documentmaster j ON j.documentid in (select documentid from kaverimrg.documentmaster)
     JOIN kaverimrg.applicantapplicationdetails k ON k.applicationnumber::text = a.applicationnumber::text
     JOIN kaverimrg.propertytypemaster l ON l.propertytypeid = a.propertytypeid
  --GROUP BY a.propertyid, a.movablepropertydesc, a.stamparticlecode, b.articlenamee, a.stampruleid, c.descriptione, a.regarticlecode, d.articlenamee, d.bookid, e.booknameenglish, a.consideration, a.govtduty, a.noofscanpages, f.age, f.sex, f.address, f.pan, f.profession, f.partyid, h.name, h.age, h.sex, h.address, h.profession, a.srocode, i.sronamee, a.applicationnumber, j.deedattachpath, j.executiondatetime, k.applicationnumber, a.propertytypeid, l.propertytypename;
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_movable_property_details_json_check(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_mr_sro_dashboard(bigint, text[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_mr_sro_dashboard(_srocode bigint, _currentstatus text[]) RETURNS TABLE(applicationnum character varying, applicationdate date, srocode integer, applicationtypeid integer, servicename character varying, currentstatus character varying, wrkflowstatusnamee text, sfdaid bigint, username text, marriagemode character varying, marriagetype character varying, scannedform1path character varying, marriagemodeid integer, marriagetypeid integer, objectioncount bigint, noticenumber bigint, noticeissuedate timestamp without time zone, noticeenddate timestamp without time zone, bridebroom_sro integer, bridebroom_sro_pre integer, bride_sro integer, bride_sro_pre integer)
    LANGUAGE plpgsql
    AS $_$
	begin
		
		return query
		
		SELECT ad.applicationnumber AS applicationnum,
		    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
		    COALESCE(m.regsrocode, m.regsrocode) AS srocode,
		    ad.applicationtypeid,
		    sm.servicename,
		    ad.currentstatus,
		    wm.wrkflowstatusnamee,
		    ad.sfdaid,
		    usr.username,
		    mm.marriagemode,
		    mt.marriagetype,
		    m.scannedform1path,
		    mm.marriagemodeid,
		    mt.marriagetypeid,
		    ( SELECT count(*) AS count
		           FROM kaverimrg.marriageobjectiondetails mo
		          WHERE mo.objectionstatus IS NULL AND mo.applicationnumber::text = ad.applicationnumber::text) AS objectioncount,
		    mn.noticenumber,
		    mn.noticeissuedate,
		    mn.noticeenddate,
		    0 as bridebroom_sro,
		    0 as bridebroom_sro_pre,
		    0 as bride_sro,
		    0 as bride_sro_pre
		   FROM kaverimrg.applicantapplicationdetails ad
		     JOIN kaverimrg.marriageregistration m ON m.applicationnumber::text = ad.applicationnumber::text
		     LEFT JOIN kaverimrg.marriagenoticedetails mn ON ad.applicationnumber::text = mn.applicationnumber::text
		     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
		     LEFT JOIN kaverimrg.wrkflowmaster wm ON wm.wrkflowstatusid::text = ad.currentstatus::text
		     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
		     LEFT JOIN kaverimrg.mas_marriagemode mm ON mm.marriagemodeid = m.marriagemodeid
		     LEFT JOIN kaverimrg.mas_marriagetype mt ON mt.marriagetypeid = m.marriagetypeid
		  WHERE ad.applicationtypeid = 4 AND (ad.currentstatus::text <> ALL (ARRAY['MR101'::text, 'MR111'::text, 'MR115'::text, 'MR102'::text, 'MR103'::text, 'MR104'::text, 'MR105'::text, 'MR125'::text, 'MR117'::text, 'MR118'::text, 'MR121'::text]))
		  and m.regsrocode = _srocode 
		  and ad.currentstatus = ANY($2)
 
  	union all
  
  	select ab.* from 
		  (SELECT ad.applicationnumber AS applicationnum,
		    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
		    COALESCE(m.regsrocode, m.regsrocode) AS srocode,
		    ad.applicationtypeid,
		    sm.servicename,
		    ad.currentstatus,
		    wm.wrkflowstatusnamee,
		    ad.sfdaid,
		    usr.username,
		    mm.marriagemode,
		    mt.marriagetype,
		    m.scannedform1path,
		    mm.marriagemodeid,
		    mt.marriagetypeid,
		    ( SELECT count(*) AS count
		           FROM kaverimrg.marriageobjectiondetails mo
		          WHERE mo.objectionstatus IS NULL AND mo.applicationnumber::text = ad.applicationnumber::text) AS objectioncount,
		    mn.noticenumber,
		    mn.noticeissuedate,
		    mn.noticeenddate,
		    (SELECT  sm.srocode
		           FROM kaverimrg.persondetails pd
		             JOIN kaverimrg.villagemaster v ON v.villagecode = pd.percityvillagecode
		             JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
		             JOIN kaverimrg.districtmaster d ON d.districtcode = sm.districtcode
		          WHERE pd.sex::text ~~ 'M%'::text and pd.applicationnumber = ad.applicationnumber) as bridebroom_sro,
		    (SELECT 
		            sm.srocode
		           FROM kaverimrg.persondetails pd
		             JOIN kaverimrg.villagemaster v ON v.villagecode = pd.precityvillagecode
		             JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
		             JOIN kaverimrg.districtmaster d ON d.districtcode = sm.districtcode
		          WHERE pd.sex::text ~~ 'M%'::text and pd.applicationnumber = ad.applicationnumber) as bridebroom_sro_pre,
		    
		    (SELECT sm.srocode FROM kaverimrg.persondetails pd
		             JOIN kaverimrg.villagemaster v ON v.villagecode = pd.percityvillagecode
		             JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
		             JOIN kaverimrg.districtmaster d ON d.districtcode = sm.districtcode
		          WHERE pd.sex::text ~~ 'F%'::text and pd.applicationnumber = ad.applicationnumber) as bride_sro,
		     (SELECT  sm.srocode
		           FROM kaverimrg.persondetails pd
		             JOIN kaverimrg.villagemaster v ON v.villagecode = pd.precityvillagecode
		             JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
		             JOIN kaverimrg.districtmaster d ON d.districtcode = sm.districtcode
		          WHERE pd.sex::text ~~ 'F%'::text and pd.applicationnumber = ad.applicationnumber ) as bride_sro_pre
		   FROM kaverimrg.applicantapplicationdetails ad
		     JOIN kaverimrg.marriageregistration m ON m.applicationnumber::text = ad.applicationnumber::text
		     LEFT JOIN kaverimrg.marriagenoticedetails mn ON ad.applicationnumber::text = mn.applicationnumber::text
		     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
		     LEFT JOIN kaverimrg.wrkflowmaster wm ON wm.wrkflowstatusid::text = ad.currentstatus::text
		     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
		     LEFT JOIN kaverimrg.mas_marriagemode mm ON mm.marriagemodeid = m.marriagemodeid
		     LEFT JOIN kaverimrg.mas_marriagetype mt ON mt.marriagetypeid = m.marriagetypeid
		  WHERE ad.applicationtypeid = 4 AND (ad.currentstatus::text <> ALL (ARRAY['MR101'::text, 'MR111'::text, 'MR115'::text, 'MR102'::text, 'MR103'::text, 'MR104'::text, 'MR105'::text, 'MR125'::text, 'MR117'::text, 'MR118'::text, 'MR121'::text]))
		  
		  and m.regsrocode <> _srocode 
		  and ad.currentstatus = ANY($2)) ab
		  where (ab.bridebroom_sro = _srocode or ab.bridebroom_sro_pre = _srocode or ab.bride_sro = _srocode or ab.bride_sro_pre = _srocode);

	END;
$_$;


ALTER FUNCTION kaverimrg.fn_fetch_mr_sro_dashboard(_srocode bigint, _currentstatus text[]) OWNER TO postgres;

--
-- Name: fn_fetch_newfirm_witness_details(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_newfirm_witness_details(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN	
	select 
	array_to_json(array_agg(
	row_to_json(witnessdetails)
	))
	into v_data_json
	from (select salutation, firstname, middlename, lastname, dateofbirth,
	age, genderid, profession, phonenumber, mailaddress, dateofjoin,
	withousebuildname, witstreetname, witstatecode, witdistrictcode,
	wittalukacode, withoblicode, witcityvillagecode, witpincode, date,
	finalregistrationnumber, applicationnumber, firmwitnessid, witnessfathername,
	(select 
	array_to_json(array_agg(
	row_to_json(firmpersonids))) from (select fp.firmpersonid,fp.firstname,fp.middlename,fp.lastname
	from kaverimrg.firmparty fp
	join kaverimrg.frm_partnerwitnessrelations fp2 on fp.firmpersonid=fp2.firmpersonid 
	where fp.applicationnumber=_applicationnumber  and fp2.firmwitnessid =vw1.firmwitnessid)  firmpersonids ) as  firmpersonids
	from kaverimrg.vw_fetch_GetFirmWitnessDetails  vw1
	where applicationnumber =_applicationnumber 
	group by salutation, firstname, middlename, lastname, dateofbirth,
	age, genderid, profession, phonenumber, mailaddress, dateofjoin,
	withousebuildname, witstreetname, witstatecode, witdistrictcode,
	wittalukacode, withoblicode, witcityvillagecode, witpincode, date,
	finalregistrationnumber, applicationnumber, firmwitnessid, witnessfathername)witnessdetails;
	 

return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_newfirm_witness_details(_applicationnumber character varying) OWNER TO postgres;

