--
-- Name: fn_fetch_party_data_doc_summary(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_party_data_doc_summary(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json1 json;
BEGIN

select array_to_json(array_agg(row_to_json(prty))) into v_data_json1
      from (
		select 
		vw_party.applicationnumber,vw_party.partyid,case when (vw_party.aliasname='' or vw_party.aliasname is null)  then  vw_party.name else CONCAT(vw_party.name,', alias:',vw_party.aliasname) end  as partyname,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,string_agg(wi.name||' '||wi.middlename||' '||wi.lastname,',') as witness_name ,
		vw_party.isEndorsePrinted,vw_party.gender as sex, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks
		,vw_party.ispartyrefused,vw_party.islateapperance,sl.descriptione as salutation
		from kaverimrg.vw_fetch_party vw_party 
		left join kaverimrg.partywitness pw on vw_party.partyid=pw.partyid 
		left join kaverimrg.witnessinfo wi on pw.witnessid = wi.witnessid 
		left join kaverimrg.salutationmaster sl on sl.salutationid=vw_party.salutationid
			where vw_party.applicationnumber = _applicationnumber and
			vw_party.partytypeid in (1,2)
			group by vw_party.applicationnumber,vw_party.applicationnumber,vw_party.partyid,vw_party.name ,vw_party.age, vw_party.address ,vw_party.profession,
		vw_party.phonenumber,vw_party.epic,vw_party.partytypeid,vw_party.partytypename,vw_party.isexecutor,vw_party.ispresenter,vw_party.admissiondate,
		vw_party.section88exemption,vw_party.fingerid,vw_party.thumbpath,vw_party.photopath,vw_party.idprooftypedesc,vw_party.idproofnumber,
		vw_party.relationship,vw_party.relativename,vw_party.isEndorsePrinted,vw_party.gender, vw_party.isorganization, vw_party.tanno, vw_party.minorguardianname, vw_party.poaname,
		vw_party.auname, vw_party.auaddress, vw_party.isprivateattendance, vw_party.coveringletterno, vw_party.thumbremarks,vw_party.ispartyrefused,vw_party.aliasname
		,vw_party.islateapperance,sl.descriptione
			order by partytypeid) prty;
    
return v_data_json1;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_party_data_doc_summary(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_party_details_rule_17_3_json(text, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_party_details_rule_17_3_json(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;

begin
		
select count(*) into v_countrecord from kaverimrg.partyinfo p where applicationnumber=_applicationnumber;

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(party_json) into v_data_json  from (
	select array_to_json(array_agg(row_to_json(partypndetails)))
from (
select distinct a.partyid ,
COALESCE(coalesce(a.firstname,' ')||' '||coalesce(a.middlename,' ')||' '||coalesce(a.lastname,' '), NULL::text)  AS name,
a.partytypeid ,a.address, a.isexecutor, a.ispresenter,v_countrecord, a.salutationid, a.age from
kaverimrg.partyinfo a
where a.applicationnumber = _applicationnumber
group by a.address, a.isexecutor, a.ispresenter,a.partytypeid,a.firstname,a.middlename,  a.lastname,a.partyid, a.salutationid, a.age

offset pageoffset
fetch next pagesize rows only
 
)partypndetails) party_json;

return v_data_json;

	END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_party_details_rule_17_3_json(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

