-- Name: fn_fetch_party_witness_json(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_party_witness_json(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 

--p_witnessdetails kaverimrg.witnessinfo1_input[] DEFAULT NULL::kaverimrg.witnessinfo1_input[]

v_data_json json;
BEGIN


 select row_to_json(app_json) as fn_fetch_party_witness_json   into v_data_json

from ( 
select array_to_json(array_agg(row_to_json(data_json)))

from (
SELECT 
   -- a.partyid,
   -- (((e.firstname::text || ' '::text) || e.middlename::text) || ' '::text) || e.lastname::text AS partyname,
    --b.name,
	
	( select array_to_json(array_agg(row_to_json(NameAndParty)))
	from (
	 select x.partyid,
     (((y.firstname::text || ' '::text) || y.middlename::text) || ' '::text) || y.lastname::text AS name
	FROM 
	-- kaverimrg.witnessinfo b LEFT JOIN 
     kaverimrg.partywitness x   -- ON    b.witnessid = a.witnessid
     Inner JOIN kaverimrg.partyinfo y ON y.partyid = x.partyid  and b.witnessid = x.witnessid
	where 	y.applicationnumber = b.applicationnumber  and 
			y.applicationnumber =	_applicationnumber and 
						a.partyid =  x.partyid
	) NameAndParty ) as PartyIdAndName ,
	
    --b.middlename,
   -- b.lastname,
    b.age,
    b.address,
    b.sex,
    b.profession,
    b.witnessid,
    b.registrationid,
    b.dateofbirth,
    b.status,
    b.phoneno,
    b.relation,
    b.mothername,
    b.fathersname,
    b.srocode,
    b.applicationnumber,
    b.verified,
