    b.villagecode,
    b.relativename,
    b.pincode,
    b.houseno,
    b.iscliment,
    b.isexicutent
   FROM kaverimrg.witnessinfo b
     LEFT JOIN kaverimrg.partywitness a ON b.witnessid = a.witnessid
