--
-- Name: fn_fetch_pending_regnumber(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_pending_regnumber(_srocode integer, _applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
   v_regnumber text;
   v_serialnumber bigint;
   v_pendingnumber text default null;
    v_shortname character varying(50);  
   V_FINYEAR character varying(50);
    v_BOOKID bigint;  
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select dm.pendingdocumentnumber,dm.bookid,sro.shortnamee,coalesce(srl.pendingserial,0)+1
into v_pendingnumber,v_BOOKID,v_shortname,v_serialnumber
from kaverimrg.documentmaster dm 
inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
left join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
/*
select dm.pendingdocumentnumber,presentdatetime::date,sm.servicename into 
pendingregnumber,presentdate,applicationtype
from kaverimrg.documentmaster dm 
inner join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode; */

if (v_pendingnumber is null) then	
v_regnumber:= 'P-'||to_char(v_serialnumber,'fm00000')||'-'||v_shortname||'-'||V_FINYEAR;
	v_pendingnumber := v_regnumber;
	update kaverimrg.documentmaster set pendingdocumentnumber= v_regnumber,
	presentdatetime = Current_timestamp
	where applicationnumber = _applicationnumber and srocode= _srocode
	and pendingdocumentnumber is null;
	update kaverimrg.applicantapplicationdetails set registrationstartdate= Current_timestamp
	where applicationnumber = _applicationnumber and srocode= _srocode;
end if;
v_pendingnumber = regexp_replace(v_pendingnumber, '^([^-]*-[^-]*)-.*$', '\1') ;

return _applicationnumber;

END;
$_$;


ALTER FUNCTION kaverimrg.fn_fetch_pending_regnumber(_srocode integer, _applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_pendingdocument_chk(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_pendingdocument_chk(_srocode integer, _pendingdocumentnumber character varying) RETURNS TABLE(note text)
    LANGUAGE plpgsql
    AS $$
declare 
v_cnt int;
--v_note varchar(100);

begin 
	
	select count(*) into v_cnt from kaverimrg.k1pendingregistrationdata 
	where srocode = _srocode and pendingdocumentnumber =_pendingdocumentnumber;
	
	if(v_cnt = 1)then
	return query
	
	select 'His document has been already been retrived in'||' '||coalesce(c.email,'')||' '||'account, Kindly connect with the'||' '||coalesce(c.firstname,'')||' '||coalesce(c.middlename,'')||' '||coalesce(c.lastname,'') as note
	from kaverimrg.k1pendingregistrationdata k
	join kaverimrg.applicantapplicationdetails a on a.applicationnumber = k.applicationnumber 
	join kaverimrg.citizenmaster c on c.citizenid = a.citizenid
	where k.srocode = _srocode and k.pendingdocumentnumber =_pendingdocumentnumber;
--	returning note into v_note;
	
	else
	raise notice 'No data';
end if;
end;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_pendingdocument_chk(_srocode integer, _pendingdocumentnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_pendingdocument_chk(integer, character varying, date); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_pendingdocument_chk(_srocode integer, _pendingdocumentnumber character varying, _pendingdocumentdate date) RETURNS TABLE(note text)
    LANGUAGE plpgsql
    AS $$
declare 
v_cnt int;
--v_note varchar(100);

begin 
	
	select count(*) into v_cnt from kaverimrg.k1pendingregistrationdata 
	where srocode = _srocode and pendingdocumentnumber =_pendingdocumentnumber and pendingdocumentdate =_pendingdocumentdate;
	
	if(v_cnt = 1)then
	return query
	
	select 'His document has been already been retrived in'||' '||coalesce(c.email,'')||' '||'account, Kindly connect with the'||' '||coalesce(c.firstname,'')||' '||coalesce(c.middlename,'')||' '||coalesce(c.lastname,'') as note
	from kaverimrg.k1pendingregistrationdata k
	join kaverimrg.applicantapplicationdetails a on a.applicationnumber = k.applicationnumber 
	join kaverimrg.citizenmaster c on c.citizenid = a.citizenid
	where k.srocode = _srocode and k.pendingdocumentnumber =_pendingdocumentnumber and k.pendingdocumentdate =_pendingdocumentdate;
--	returning note into v_note;
	
	else
	raise notice 'No data';
end if;
end;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_pendingdocument_chk(_srocode integer, _pendingdocumentnumber character varying, _pendingdocumentdate date) OWNER TO postgres;

--
-- Name: fn_fetch_permission_by_role(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_permission_by_role(_rollid integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE

v_data_json  json;

BEGIN 

select array_to_json(array_agg(row_to_json(tmp))) INTO
v_data_json from 
(select rmfm.rollid,rmfm.moduleid,m.modulename,rmfm.submoduleid,s.submodulename,rmfm.functionid,f.functionname  
from kaverimrg.role_module_function_mapping  rmfm
join kaverimrg.modulemaster m on rmfm.moduleid=m.moduleid 
left join kaverimrg.submodulemaster s on rmfm.submoduleid=s.submoduleid and rmfm.moduleid=s.moduleid 
left join kaverimrg.functionmaster f on rmfm.functionid=f.functionid  and rmfm.moduleid=f.moduleid and rmfm.submoduleid=f.submoduleid 
where rmfm.rollid=_rollid  ) as tmp;

	
 
 

return v_data_json;

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_permission_by_role(_rollid integer) OWNER TO postgres;

--
-- Name: fn_fetch_print_dissolution(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_print_dissolution(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json /*( select
  array_to_json(array_agg(row_to_json(app_json)))*/
  from (select row_to_json(app_json) 
 from ( select  c.districtnamee,c.districtnamee as droffice,	
	   
 (select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,
		count(distinct firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		am.inserteddatetime::date as DateOfRegistration
			from kaverimrg.firmmaster d 
		inner join kaverimrg.firm_dissolution am on am.finalregistrationnumber=d.finalregistrationnumber
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber and fp.presentertypeid in (1,6)
		inner join kaverimrg.applicantapplicationdetails a on am.applicationnumber  =a.applicationnumber
		inner join kaverimrg.wrkflowmaster wf on a.currentstatus =wf.wrkflowstatusid 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where am.applicationnumber =_applicationnumber
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		am.inserteddatetime)Firmdetails) as Firmdetails,
	   
	 (select array_to_json(array_agg(row_to_json(dateofdissolution)))
  from (select fd.dateofdissolutionofdate::date,fd.dissolutionid
		from kaverimrg.firm_dissolution fd 
			where fd.applicationnumber =_applicationnumber)dateofdissolution) as dateofdissolution,
	   
	 	   	   ( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname,br.dissolutionpersonid,br.presentertypeid,br.firmpersonid,br.phoneno,br.email
from kaverimrg.dissolutionfirmparty  br
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where br.applicationnumber =_applicationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,  
	   
	    ( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid
   FROM kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.firm_dissolution f ON f.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 49
and ad.applicationnumber =_applicationnumber ) fdasdafetch) as fdasdafetch,
	   
	    ( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT fr.feeruleid,fr.feedescription,fr.payableamount
   FROM kaverimrg.firm_requiredfees fr 
     JOIN kaverimrg.firm_dissolution f ON f.applicationnumber::text = fr.applicationnumber::text
   WHERE fr.applicationnumber =_applicationnumber ) feesrequiredbyappl) as feesrequiredbyappl,
	   
	   ( select array_to_json(array_agg(row_to_json(dissolutionremarks)))  from 
 ( SELECT ar.firmdetailsremarks_fda_sda, 
ar.presenterdetailsremarks_fda_sda, 
ar.partnerdetailsremarks_fda_sda,
ar.witnessdetailsremarks_fda_sda,
ar.stampdutyandfeedetailsremarks_fda_sda,
ar.uploaddocumentremarks_fda_sda,
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.witnessdetailsremarks_dr,
ar.stampdutyandfeedetailsremarks_dr,
ar.canprocesstopaymentremarks_dr,
ar.uploaddocumentremarks_dr
   FROM kaverimrg.firmapplicationremarks ar 
     JOIN kaverimrg.firm_dissolution f ON f.applicationnumber::text = ar.applicationnumber::text
  WHERE ar.applicationnumber =_applicationnumber) dissolutionremarks) as dissolutionremarks
	   
 from kaverimrg.firmmaster a 
inner join kaverimrg.firm_dissolution am on  am.finalregistrationnumber=a.finalregistrationnumber
inner join kaverimrg.sromaster b on a.districtcode = b.districtcode 
inner join kaverimrg.districtmaster c on a.districtcode = c.districtcode
where  am.applicationnumber =_applicationnumber	   
)  app_json 
	   
	   ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_print_dissolution(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_print_form_firm(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_print_form_firm(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
 -- from (select row_to_json(app_json) 
	    from (
	    select c.districtnamee,c.districtnamee as droffice,
			  
			 
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(distinct fp.firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		d.inserteddatetime::date as DateOfRegistration,a.citizenid    
			from kaverimrg.firmmaster d 
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		left join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber and fp.presentertypeid in (1,6) 
		inner join kaverimrg.applicantapplicationdetails a on d.applicationnumber =a.applicationnumber
		inner join kaverimrg.wrkflowmaster wf on a.currentstatus =wf.wrkflowstatusid 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.applicationnumber =_applicationnumber
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,d.inserteddatetime,a.citizenid)Firmdetails) as Firmdetails,
			  
			  	   
( select array_to_json(array_agg(row_to_json(Branchdetails)))
  from ( select
		bg.branchid, bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||tal.taluknamee||' '||dis.districtnamee||' '||
		s.statenamee ||' '|| bg.branchpincode as Address --bg.branchphone
		from kaverimrg.firmbranches bg 
		left join kaverimrg.lgd_statemaster s on bg.branchstatecode  = s.statecode 
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode 
			                       left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode
			                       --left join kaverimrg.hoblimaster hob on bg.branchhoblicode = hob.hoblicode 
			                       --left join kaverimrg.villagemaster vil on bg.branchcityvillagecode = vil.villagecode
             where bg.applicationnumber = a.applicationnumber  and
		  bg.applicationnumber = _applicationnumber order by branchid desc)Branchdetails) as Branchdetails,
		  
		  
( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID, br.firmpersonid,
br.presentertypeid,br.dateofjoin::date
from kaverimrg.firmparty br
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where br.applicationnumber = _applicationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,
			  
			  
 ( select array_to_json(array_agg(row_to_json(partnerdetails)))
  from(
  select  br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID, br.dateofjoin::date,
br.perhousebuildname||' '||br.perstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||
	  hob.hoblinamee||' '||vil.villagenamee||'-'||br.perpincode as Address, br.firmpersonid, br.presentertypeid,
	  br.dob::date,br.relationship,mr.relationname,br.relativename,
CASE
WHEN r.presentertypeid=8 THEN  r.firstname
else
	  NULL 
END as G_firstname,

CASE
WHEN r.presentertypeid=8 THEN r.middlename
else
	  NULL 
END as G_midname,					  
CASE
WHEN r.presentertypeid=8 THEN  r.lastname
else
	  NULL 
END as G_lastname,				  
	CASE
WHEN r.presentertypeid=8 THEN  'Guardian'--pt.description 
else
	  NULL 
END as G_designation,
CASE
WHEN r.presentertypeid=8 THEN r.phoneno 
else
	  NULL 
END as G_phonenumber,
CASE
WHEN r.presentertypeid=8 THEN  r.mailaddress 
else
	  NULL 
END as G_EmailID,

CASE
WHEN r.presentertypeid=8 THEN  r.dateofjoin::date

else
	  NULL 
END as G_dateofjoin,	

CASE
WHEN r.presentertypeid=8 THEN  
r.perhousebuildname||' '||r.perstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||r.perpincode
else
	  NULL 
END as G_Address,
CASE
WHEN r.presentertypeid=8 THEN  r.firmpersonid
else
	  NULL 
END as G_firmpersonid,

CASE
WHEN r.presentertypeid=8 THEN  r.presentertypeid
else
	  NULL 
END as G_presentertypeid,

CASE
WHEN r.presentertypeid=8 THEN  r.dob::date
else
	  NULL 
END as G_dob,
CASE
WHEN r.presentertypeid=8 THEN  r.relationship
else
	  NULL 
END as G_relationship,
CASE
WHEN r.presentertypeid=8 THEN  mr.relationname
else
	  NULL 
END as G_relationname,	  	  
CASE
WHEN r.presentertypeid=8 THEN  r.relativename
else
	  NULL 
END as G_relativename  
from kaverimrg.firmparty br
	   left JOIN kaverimrg.firmparty r on br.linkfirmpersonid=r.firmpersonid
	  left JOIN kaverimrg.firmparty rs on rs.linkfirmpersonid=r.firmpersonid
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
inner join kaverimrg.mas_frm_presentertypes ps on br.presentertypeid=ps.presentertypeid	  
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode
--inner join kaverimrg.relationshipmasters rt on rt.id=br.relationship
inner join kaverimrg.MarriageWitnessRelationMaster mr on mr.relationid=br.relationship  
where br.applicationnumber = _applicationnumber and br.presentertypeid!=8 and br.presentertypeid in (1,6)
order by br.firmpersonid desc
  )partnerdetails) as partnerdetails,
			  
(select array_to_json(array_agg(row_to_json(firmwitness)))
	from (select   fe.firmwitnessid,coalesce(fe.firstname,null) as firstname,
	coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID, fe.genderid,
		fe.witnessfathername,fe.age,
	(select array_to_json(array_agg(row_to_json(firmpersonids))) 
	 from (select fp.firmpersonid,fp.firstname||' '||fp.middlename||' '||fp.lastname as partnername
	from kaverimrg.firmparty fp
	join kaverimrg.frm_partnerwitnessrelations fp2 on fp.firmpersonid=fp2.firmpersonid 
	where fp.applicationnumber=_applicationnumber  and fp2.firmwitnessid =fe.firmwitnessid) firmpersonids ) as  firmpersonids
	from kaverimrg.frm_witnessdetails fe  
	where fe.applicationnumber =_applicationnumber)firmwitness) as firmwitness,
			  
			   ( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid
   FROM kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.firmmaster f ON f.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 6 
and ad.applicationnumber =_applicationnumber ) fdasdafetch) as fdasdafetch,

 ( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT fr.feeruleid,fr.feedescription,fr.payableamount
   FROM kaverimrg.firm_requiredfees fr 
     JOIN kaverimrg.firmmaster f ON f.applicationnumber::text = fr.applicationnumber::text
   WHERE fr.applicationnumber =_applicationnumber ) feesrequiredbyappl) as feesrequiredbyappl,

 ( select array_to_json(array_agg(row_to_json(remarks2)))  from 
 ( SELECT ar.firmdetailsremarks_fda_sda, 
ar.presenterdetailsremarks_fda_sda, 
ar.partnerdetailsremarks_fda_sda,
ar.witnessdetailsremarks_fda_sda,
ar.stampdutyandfeedetailsremarks_fda_sda,
ar.uploaddocumentremarks_fda_sda,
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.witnessdetailsremarks_dr,
ar.stampdutyandfeedetailsremarks_dr,
ar.canprocesstopaymentremarks_dr,
ar.uploaddocumentremarks_dr
   FROM kaverimrg.firmapplicationremarks ar 
     JOIN kaverimrg.firmmaster f ON f.applicationnumber::text = ar.applicationnumber::text
  WHERE ar.applicationnumber =_applicationnumber) remarks2) as remarks2
	   
 from kaverimrg.firmmaster a 
inner join kaverimrg.sromaster b on a.districtcode  = b.districtcode 
inner join kaverimrg.districtmaster c on b.districtcode = c.districtcode
where a.applicationnumber = _applicationnumber	   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_print_form_firm(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_print_protestentry(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_print_protestentry(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
	    from ( select c.districtnamee,c.districtnamee as droffice,
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,d.finalregistrationnumber,d.durationoffirm
			from kaverimrg.firmmaster d 
		join kaverimrg.applicantapplicationdetails a on d.applicationnumber =a.applicationnumber
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber and fp.presentertypeid in (1,6)
		inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where pe.applicationnumber =_applicationnumber
	   	group  by 	a.currentstatus,  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,d.finalregistrationnumber,d.durationoffirm)Firmdetails) as Firmdetails,
			  		  
( select row_to_json(presenterdetils)
from (select pe.firstname||' '||pe.middlename||' '||pe.lastname as Presentername, pt.description as designation, pe.phoneno as phonenumber,
	  pe.email as EmailID,
	  pe.perhousebuildingname||' '||pe.perstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||
  pe.perpincode as presenteraddress,
	  pe.presentertypeid,pe.protestentrypersonid
	from kaverimrg.protestentryfirmparty pe
inner join kaverimrg.mas_frm_presentertypes pt on pe.presentertypeid=pt.presentertypeid
	  left join kaverimrg.districtmaster dis on pe.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on pe.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on pe.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on pe.percityvillagecode  = vil.villagecode
where pe.applicationnumber =_applicationnumber and pe.presentertypeid in (1,2,9))presenterdetils) as presenterdetils,
	  
							
( select array_to_json(array_agg(row_to_json(firmwitness)))
  from (select coalesce(fe.firstname,null) as firstname,coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID
		from kaverimrg.firmmaster d 
inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
 inner join kaverimrg.frm_witnessdetails fe  on d.applicationnumber=fe.applicationnumber
			where pe.applicationnumber =_applicationnumber)firmwitness) as firmwitness,
			  
( select array_to_json(array_agg(row_to_json(remark))) from 
 ( SELECT
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.protestentrynotedremarks_dr,
ar.protestentryisnotvalidremarks_dr,
ar.uploaddocumentremarks_dr
   FROM  kaverimrg.firmapplicationremarks ar  
 WHERE ar.applicationnumber =_applicationnumber)remark)as remarks,
			  
( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid
   FROM kaverimrg.applicantapplicationdetails ad
   LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
   LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 50
and ad.applicationnumber =_applicationnumber) fdasdafetch) as fdasdafetch
   
from kaverimrg.firmmaster d 	
inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
inner join kaverimrg.districtmaster c on d.districtcode = c.districtcode
where pe.applicationnumber =_applicationnumber
   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_print_protestentry(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_json_chk(text, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_property_details_json_chk(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;
begin
	
	select count(*) into v_countrecord  from kaverimrg.propertymaster p where applicationnumber=_applicationnumber;
	
	select count(*) into v_cntproperty from kaverimrg.propertynumberdetails ps where propertyid in (select propertyid from kaverimrg.propertymaster where applicationnumber=_applicationnumber) 
	and ps.currentpropertytypeid in (1,60,65);

	select isownertobeclaimant into v_partytypeid from kaverimrg.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaverimrg.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaverimrg.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaverimrg.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                --  string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  
				(select coalesce(r.relatione,a.relationship) from kaverimrg.partyinfo a1 
							where a1.ownerno in (select min(ownerno) from kaverimrg.partyinfo p where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid and a1.partytypeid= (case when v_partytypeid=true then 1 else 2 end ))   as relationship,a.relativename,                

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaverimrg.partyinfo a inner join kaverimrg.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaverimrg.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
									group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.relativename
                                   ,a.transactextacre,a.transactextgunta,a.transactextfgunta,a.propertyid,r.id,a.ownerno
                                   order by a.ownerno limit 1
                                 
									--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaverimrg.propertynumberdetails pnd

                                   left join kaverimrg.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaverimrg.vw_fetch_court_order_details co  where  co.propertyid = pm.propertyid and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaverimrg.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaverimrg.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaverimrg.vw_fetch_court_order_details na where na.propertyid = pm.propertyid and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaverimrg.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,

a.userid,

a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaverimrg.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaverimrg.propertymaster pm1 left outer join kaverimrg.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaverimrg.propertyschedules ps
                 join (select * from kaverimrg.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid=pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p
				on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
				 join kaverimrg.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaverimrg.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
				where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)

                order by ps.scheduleid 


                
) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaverimrg.propertymaster pm 
join kaverimrg.bhoomimappingdetails bh on (pm.villagecode=bh.kaverimrgvillagecode)
left join kaverimrg.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaverimrg.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaverimrg.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaverimrg.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on  w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri



union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

sm.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaverimrg.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.departmentname as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,(select string_agg(firstname,', ')  from kaverimrg.partyinfo pp where pp.propertyid =a.propertyid and pp.partytypeid= (case when v_partytypeid=true then 1 else 2 end)) as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

--                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,
                  (select coalesce(r.relatione,a.relationship) from kaverimrg.partyinfo a1
							where a1.ownerno in (select min(ownerno) from kaverimrg.partyinfo p 
															where propertyid=a.propertyid) 
									and r.id::text=a1.relationship::text
							and a1.propertyid=a.propertyid)   as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaverimrg.partyinfo a inner join kaverimrg.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaverimrg.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)
								group by b.survey_no,b.hissa_no,r.relatione,a.relationship,a.availableextacre ,a.availableextgunta,a.availableextfgunta,a.relativename
								,a.propertyid,r.id,a.ownerno
								order by a.ownerno limit 1
								--group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaverimrg.propertynumberdetails pnd

                                   left join kaverimrg.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaverimrg.vw_fetch_court_order_details co  where  co.propertyid = pm.propertyid and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaverimrg.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaverimrg.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaverimrg.vw_fetch_court_order_details na where na.propertyid = pm.propertyid and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaverimrg.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,
a.userid,
a.drocode,
a.mappingid,
a.documentid,
a.propertyid,
false
FROM kaverimrg.vw_liability_search a
where a.srocode = pm.srocode and a.currentnumber
in
(select pnd.currentnumber from kaverimrg.propertymaster pm1 left outer join kaverimrg.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid
where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaverimrg.propertyschedules ps
                 join (select * from kaverimrg.partyinfo p where partytypeid = 2 and (case when v_cntproperty>0 then
				 propertyid  = pm.propertyid else p.applicationnumber=_applicationnumber end) order by ownerno limit 1)as p 
				 on (case when v_cntproperty>0 then ps.propertyid=p.propertyid else p.applicationnumber=ps.applicationnumber end)
                 join kaverimrg.propertymaster pmm on ps.propertyid=pmm.propertyid               
				left join kaverimrg.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid and  p.partytypeid =(case when sf.isownertobeclaimant=true then 1 else 2 end)
                order by ps.scheduleid limit 1
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaverimrg.propertymaster pm 
left join kaverimrg.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaverimrg.sromaster sm on (vi.srocode=sm.srocode)
left join kaverimrg.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaverimrg.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaverimrg.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaverimrg.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on  w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri  
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_property_details_json_chk(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_json_chk_2(text, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_property_details_json_chk_2(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$



declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
begin
	
	select count(*) into v_countrecord  from kaverimrg.propertymaster p where applicationnumber=_applicationnumber;

	select isownertobeclaimant into v_partytypeid from kaverimrg.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaverimrg.propertymaster p where p.applicationnumber =_applicationnumber limit 1);

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

