     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaverimrg.propertynumberdetails pnd

