a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaverimrg.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaverimrg.propertymaster pm1 left outer join kaverimrg.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

