v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaverimrg.propertymaster pm 
join kaverimrg.bhoomimappingdetails bh on (pm.villagecode=bh.kaverimrgvillagecode)
left join kaverimrg.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaverimrg.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaverimrg.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaverimrg.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on  w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

