                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,a.firstname as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaverimrg.partyinfo a inner join kaverimrg.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaverimrg.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end)

                                   --group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

