                pm.landmark,
                pm.zoneid,
                zone.departmentname,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_property_details_json_chk_backup_31052023(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_json_chk_new(text, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_property_details_json_chk_new(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$


declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
begin
	
	select count(*) into v_countrecord  from kaverimrg.propertymaster p where applicationnumber=_applicationnumber;

	select isownertobeclaimant into v_partytypeid from kaverimrg.stamprulesflag sf where sf.stampruleid in (Select stampruleid from kaverimrg.propertymaster p where p.applicationnumber =_applicationnumber limit 1);
--v_partytypeid:=2;

pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))

from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

ho.hoblicode,ho.hoblinamee as Hobli,ta.talukcode,ta.taluknamee as Taluk,

ta.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaverimrg.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.zonenamee as zonename,

                subpropertytypeid,
            
                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (    

                  select b.survey_no,b.hissa_no, a.firstname as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,

a.transactextacre as transactextacre,a.transactextgunta as transactextgunta ,a.transactextfgunta as transactextfgunta from

kaverimrg.partyinfo a inner join kaverimrg.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaverimrg.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid  and a.partytypeid= (case when v_partytypeid=true then 1 else 2 end) 
					)partypndetails 
                 
                  ) as partyinfopropnumberdetails ,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaverimrg.propertynumberdetails pnd

                                   left join kaverimrg.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaverimrg.vw_fetch_court_order_details co  where  co.propertyid = pm.propertyid and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaverimrg.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaverimrg.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

                ( select array_to_json(array_agg(row_to_json(courtordernonagri)))

                from (

                                select * from kaverimrg.vw_fetch_court_order_details na where na.propertyid = pm.propertyid and

                applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) and na.villagecode in (select p6.villagecode from kaverimrg.propertymaster p6 where applicationnumber=_applicationnumber)

                                )courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,

a.userid,

a.drocode,

a.mappingid,

a.documentid,

a.propertyid,

false

FROM kaverimrg.vw_liability_search a

where a.srocode = pm.srocode and a.currentnumber

in

(select pnd.currentnumber from kaverimrg.propertymaster pm1 left outer join kaverimrg.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid

where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,

                ( select array_to_json(array_agg(row_to_json(propertyschedules)))

                from

(select scheduleid,

                ps.propertyid,

                ps.srocode,

                ps.partyid,

                ps.scheduletype,

                pm.totalarea,

                ps.unitid,

                ps.description,

                ps.partyids,

                ps.aileniatedauthorityid,

                ps.alieniatedorder,

                ps.bhoomisellerpartyids,

                ps.govtrestricorder,

                ps.govtrestrictionid,

                ps.landcode,propertygroup,

                ps.giftshare,

                ps.giftsharedetails,

                ps.easttowest,

                ps.northtosouth,

                ps.blockchainpropertyid,

                ps.assignedblockchainpid,

                ps.applicationnumber,

                ps.verified,

                ps.issroapproved,

                ps.eastboundary,

                ps.westboundary,

                ps.northboundary,

                ps.southboundary,

                p.transactextacre,

                p.transactextgunta,

                p.transactextfgunta

                from kaverimrg.propertyschedules ps

                left join kaverimrg.partyinfo p on ps.propertyid=p.propertyid

                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid

                order by ps.scheduleid

) propertyschedules) as propertyschedulesdata,

v_countrecord as countofrecord,

pm.roadcode as roadcode,

rd.roadnamee as roadnamee,

ta.unit as unittype,

pt.isagri as isagriculture


from kaverimrg.propertymaster pm 
join kaverimrg.bhoomimappingdetails bh on (pm.villagecode=bh.kaverimrgvillagecode)
left join kaverimrg.bhoomivillagemaster vi on (bh.bhoomivillagecode  = vi.villagecode and bh.bhoomitalukcode=vi.talukcode and bh.bhoomidistrictcode=vi.districtcode and bh.bhoomihobicode=vi.hoblicode)
left join kaverimrg.bhoomihoblimaster ho on (ho.hoblicode =bh.bhoomihobicode and ho.talukcode=bh.bhoomitalukcode  and ho.districtcode=bh.bhoomidistrictcode)
join kaverimrg.bhoomitalukmaster ta on (bh.bhoomitalukcode=ta.talukcode and bh.bhoomidistrictcode=ta.districtcode)
left join kaverimrg.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on  w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.zonemaster zone on pm.zoneid = zone.zoneid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=true

group by pm.propertyid,pm.villagecode,vi.villagenamee,ho.hoblicode,ho.hoblinamee,ta.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              

,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish  

,pm.srocode,se.sronamee,

pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.zonenamee,

                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri
                
union ALL


select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,

vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,

ta.districtcode,di.districtnamee as District,

                pm.stamparticlecode,

                sp.articlenamee as stamparticle,

                pm.stampruleid,

                sr.descriptione as stampsubarticle,

                pm.regarticlecode,

                ra.articlenamee as registrationfeearticle,

--             sr.bookid,

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end ) as bookid,

                --bt.booknameenglish as bookname,
	
                (select booknameenglish from kaverimrg.booktypemaster where bookid =

                (case when pm.stamparticlecode = 14 then

                 (select bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber limit 1)

                      else sr.bookid end )) as bookname,
                pm.srocode,

                se.sronamee as sroname,

                pm.propertytypeid,

                pt.propertytypename,

                pm.noofscanpages,

                pm.ismovableproperty,

                pm.movablepropertydesc,

                w.wardid,

                pm.totalarea,

                me.descriptionenglish as unit,

                w.wardnumber,

                pm.landmark,

                pm.zoneid,

                zone.zonenamee as zonename,

                subpropertytypeid,

                ( select array_to_json(array_agg(row_to_json(partypndetails)))

      from (

                  select b.survey_no,b.hissa_no,a.firstname as ownername,

                                  /* COMMENTED ON 01-10-2022 as ownername is only single owner*/

                                  --string_agg(a.firstname,',') as ownername,

                                  coalesce(r.relatione,a.relationship) as relationship,a.relativename,

a.availableextacre as transactextacre,a.availableextgunta as transactextgunta ,a.availableextfgunta as transactextfgunta from

kaverimrg.partyinfo a inner join kaverimrg.propertynumberdetails b on a.propertyid = b.propertyid

                                 -- and a.partytypeid = 2 /* commented on 30-07-2022 - in discharge deed, owner will be marked as claimant */

                                  left join kaverimrg.relationshipmasters r on r.id::text = a.relationship::text 

                                  --a.relationship in ('3','4','5','6','7','8')

                                  where a.applicationnumber = pm.applicationnumber and pm.propertyid= b.propertyid

                                   --group by b.survey_no , b.hissa_no,r.relatione,a.relativename,a.relationship,

     --  a.transactextacre,a.transactextgunta,

                                --   a.transactextfgunta

                  )partypndetails) as partyinfopropnumberdetails,

( select array_to_json(array_agg(row_to_json(prptyno)))

      from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,

                                                pntm.typenameenglish as propertynumbertype,

                                                pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription

                                                from kaverimrg.propertynumberdetails pnd

                                   left join kaverimrg.propertynotypemaster pntm                                    

                                                on (pntm.propertytypeid = pnd.currentpropertytypeid)

                                   where pnd.propertyid = pm.propertyid and

                                                pm.applicationnumber = _applicationnumber

                                   )prptyno )

                                                as propertynumberdetails,

                ( select array_to_json(array_agg(row_to_json(courtorderagri)))

                from (

               

                select * from kaverimrg.vw_fetch_court_order_details co  where  co.propertyid = pm.propertyid and

                applicationnumber = _applicationnumber and (co.currentpropertytypeid <> 1 or co.currentpropertytypeid=1) and co.villagecode in (select p7.villagecode from kaverimrg.propertymaster p7 where applicationnumber=_applicationnumber) 

                ) courtorderagri) as Courtdataagri,

                ( select array_to_json(array_agg(row_to_json(partynonagri

)))

                from (

                select pm.assessment as pid,

                pa.firstname as ownername,

                pm.landmark as propertydescription ,

                pm.ownedarea as totalarea

     from kaverimrg.partyinfo pa where pa.propertyid = pm.propertyid

                )partynonagri)partyinfononagri,

 ( select array_to_json(array_agg(row_to_json(courtordernonagri)))
                from (
select * from kaverimrg.vw_fetch_court_order_details na where na.propertyid = pm.propertyid and
 applicationnumber = _applicationnumber and (na.currentpropertytypeid <>1 or na.currentpropertytypeid=1) 
 and na.villagecode in (select p6.villagecode from kaverimrg.propertymaster p6 where applicationnumber=_applicationnumber)
)courtordernonagri)as courtdatanonagri,

                ( select array_to_json(array_agg(row_to_json(propertyliability)))

                from (SELECT

a.liabilityid,

a.entrydate,

a.issuedate,

a.issuedby,

a.amount,

a.ordernumber,

a.liabilitynote,

a.srocode,

a.sronamee,
a.userid,
a.drocode,
a.mappingid,
a.documentid,
a.propertyid,
false
FROM kaverimrg.vw_liability_search a
where a.srocode = pm.srocode and a.currentnumber
in
(select pnd.currentnumber from kaverimrg.propertymaster pm1 left outer join kaverimrg.propertynumberdetails pnd on pm1.propertyid=pnd.propertyid
where pm1.propertyid=pm.propertyid)) propertyliability ) as liabilitydata,
                ( select array_to_json(array_agg(row_to_json(propertyschedules)))
                from
(select scheduleid,
                ps.propertyid,
                ps.srocode,
                ps.partyid,
                ps.scheduletype,
                pm.totalarea,
                ps.unitid,
                ps.description,
                ps.partyids,
                ps.aileniatedauthorityid,
                ps.alieniatedorder,
                ps.bhoomisellerpartyids,
                ps.govtrestricorder,
                ps.govtrestrictionid,
                ps.landcode,propertygroup,
                ps.giftshare,
                ps.giftsharedetails,
                ps.easttowest,
                ps.northtosouth,
                ps.blockchainpropertyid,
                ps.assignedblockchainpid,
                ps.applicationnumber,
                ps.verified,
                ps.issroapproved,
                ps.eastboundary,
                ps.westboundary,
                ps.northboundary,
                ps.southboundary,
                p.transactextacre,
                p.transactextgunta,
                p.transactextfgunta
                from kaverimrg.propertyschedules ps
                left join kaverimrg.partyinfo p on ps.propertyid=p.propertyid
                where ps.applicationnumber=_applicationnumber and ps.propertyid  = pm.propertyid
                order by ps.scheduleid
) propertyschedules) as propertyschedulesdata,
v_countrecord as countofrecord,
pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaverimrg.propertymaster pm 
left join kaverimrg.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaverimrg.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaverimrg.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaverimrg.districtmaster di on (di.districtcode = ta.districtcode)
--left join kaverimrg.bhoomidistrictmaster  di on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on  w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.zonemaster zone on pm.zoneid = zone.zoneid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber and pt.isagri=false
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,ta.districtcode,di.districtnamee              
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish  
,pm.srocode,se.sronamee,
pm.propertytypeid,
                pt.propertytypename,
                pm.noofscanpages,
                pm.ismovableproperty,
                pm.movablepropertydesc,
                w.wardid,
                pm.totalarea,
                me.descriptionenglish,
                w.wardnumber,
                pm.landmark,
                pm.zoneid,
                zone.zonenamee,
                subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri
			
offset pageoffset

fetch next pagesize rows only

)  app_json ) data_json;

return v_data_json;

END;

$$;


ALTER FUNCTION kaverimrg.fn_fetch_property_details_json_chk_new(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_details_rule_17_3_json(text, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_property_details_rule_17_3_json(_applicationnumber text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
pageoffset integer:=0;
v_countrecord int;
v_partytypeid bool;
v_cntproperty int;

begin
		
		select count(*) into v_countrecord from kaverimrg.propertymaster p where applicationnumber=_applicationnumber;
		select count(*) into v_cntproperty from kaverimrg.propertynumberdetails ps where propertyid in (select propertyid from kaverimrg.propertymaster where applicationnumber=_applicationnumber);
	
pageoffset:=((pagenumber-1) * pagesize);

select row_to_json(data_json) into v_data_json from (

select array_to_json(array_agg(row_to_json(app_json)))
from (

select pm.propertyid as PIDNO,pm.villagecode,vi.villagenamee as Village,
 
vi.hoblicode,ho.hoblinamee as Hobli,vi.talukcode,ta.taluknamee as Taluk,
 
sm.districtcode,di.districtnamee as District,
 
pm.stamparticlecode,
 
sp.articlenamee as stamparticle,
 
pm.stampruleid,
 
sr.descriptione as stampsubarticle,
 
pm.regarticlecode,
 
ra.articlenamee as registrationfeearticle,
 
sr.bookid,
 
bt.booknameenglish as bookname,
pm.srocode,
 
se.sronamee as sroname,
 
pm.propertytypeid,
 
pt.propertytypename,
 
pm.noofscanpages,
 
pm.ismovableproperty,
 
pm.movablepropertydesc,
 
w.wardid,
 
pm.totalarea,
 
me.descriptionenglish as unit,
 
w.wardnumber,
 
pm.landmark,
 
pm.zoneid,
 
zone.departmentname as zonename,
 
subpropertytypeid,
pm.valuationreport,
 
( select array_to_json(array_agg(row_to_json(partypndetails)))
from (
select distinct a.partyid ,ptm.descriptioninenglish,
COALESCE(coalesce(a.firstname,' ')||' '||coalesce(a.middlename,' ')||' '||coalesce(a.lastname,' '), NULL::text)  AS name,
a.firstname,
a.middlename,
a.lastname,
a.partytypeid ,a.address, a.isexecutor, a.ispresenter, a.salutationid, a.age, s.descriptione from
kaverimrg.partyinfo a
left join kaverimrg.partytypemaster ptm on ptm.partytypeid=a.partytypeid
left join kaverimrg.salutationmaster s on s.salutationid=a.salutationid
where a.applicationnumber = _applicationnumber
and a.propertyid = pm.propertyid
group by a.address, a.isexecutor, a.ispresenter,a.partytypeid,a.firstname,a.middlename,  a.lastname,a.partyid,ptm.descriptioninenglish, a.salutationid, a.age,s.descriptione
 
)partypndetails) as partyinfopropnumberdetails,


 
( select array_to_json(array_agg(row_to_json(prptyno)))
 
from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
 
pntm.typenameenglish as propertynumbertype, --pnd.propertynumberdetailid,
 
pnd.currentnumber,pnd.hissa_no,pnd.survey_no,pnd.description as propertynumberdescription
 
from kaverimrg.propertynumberdetails pnd
 
 left join kaverimrg.propertynotypemaster pntm
 
on (pntm.propertytypeid = pnd.currentpropertytypeid)
 
 where pnd.propertyid = pm.propertyid and
 
pm.applicationnumber = _applicationnumber
 
 )prptyno )
 
as propertynumberdetails,
 
( select array_to_json(array_agg(row_to_json(propertyschedules)))
from
(select scheduleid,
ps.propertyid,
ps.srocode,
ps.partyid,
ps.scheduletype,
pm.totalarea,
ps.unitid,
ps.description,
ps.partyids,
ps.aileniatedauthorityid,
ps.alieniatedorder,
ps.bhoomisellerpartyids,
ps.govtrestricorder,
ps.govtrestrictionid,
ps.landcode,propertygroup,
ps.giftshare,
ps.giftsharedetails,
ps.easttowest,
ps.northtosouth,
ps.blockchainpropertyid,
ps.assignedblockchainpid,
ps.applicationnumber,
ps.verified,
ps.issroapproved,
ps.eastboundary,
ps.westboundary,
ps.northboundary,
ps.southboundary,
mm.measurementnamee
from kaverimrg.propertyschedules ps
 join kaverimrg.propertymaster pmm on ps.propertyid=pmm.propertyid 
left join kaverimrg.stamprulesflag sf on sf.stampruleid =pmm.stampruleid 
left join kaverimrg.measurementmaster mm on ps.unitid= mm.measurementcode
where ps.applicationnumber=_applicationnumber and ps.propertyid= pm.propertyid
order by ps.scheduleid
) propertyschedules) as propertyschedulesdata,

pm.roadcode as roadcode,
rd.roadnamee as roadnamee,
ta.unit as unittype,
pt.isagri as isagriculture
from kaverimrg.propertymaster pm 
left join kaverimrg.villagemaster vi on (pm.villagecode = vi.villagecode)
left join kaverimrg.sromaster sm on (vi.srocode=sm.srocode)
left join kaverimrg.hoblimaster ho on (ho.hoblicode = vi.hoblicode)
left join kaverimrg.talukmaster ta on (ta.talukcode=vi.talukcode)
left join kaverimrg.districtmaster di on (di.districtcode = sm.districtcode)
--left join kaverimrg.bhoomidistrictmasterdi on (di.districtcode = ta.districtcode)
left join kaverimrg.documentmaster dc on (dc.regarticlecode = pm.regarticlecode and dc.documentid=pm.documentid)
left join kaverimrg.stamparticles sp on (sp.stamparticlecode = pm.stamparticlecode)
left join kaverimrg.stamprules sr on (sr.stampruleid = pm.stampruleid)
left join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
left join kaverimrg.booktypemaster bt on (bt.bookid = sr.bookid)
left join kaverimrg.sromaster se on (se.srocode = pm.srocode)
left join kaverimrg.propertytypemaster pt on pt.propertytypeid = pm.propertytypeid
left join kaverimrg.villagewardmapping vw on vw.villagecode = pm.villagecode and vw.wardid = pm.wardid and pm.ismovableproperty=false
left join kaverimrg.warddetails w on w.wardid = pm.wardid
left join kaverimrg.measunitmaster me on me.unitid = pm.unitid
left join kaverimrg.integrationdepartment zone on pm.zoneid = zone.udeptid
left join kaverimrg.roadmaster rd on (pm.roadcode=rd.roadcode)
where pm.applicationnumber = _applicationnumber
group by pm.propertyid,pm.villagecode,vi.villagenamee,vi.hoblicode,ho.hoblinamee,vi.talukcode,ta.taluknamee,sm.districtcode,di.districtnamee
,pm.stamparticlecode,sp.articlenamee,pm.stampruleid,sr.descriptione,pm.regarticlecode,ra.articlenamee,sr.bookid,bt.booknameenglish
,pm.srocode,se.sronamee,
pm.propertytypeid,
pt.propertytypename,
pm.noofscanpages,
pm.ismovableproperty,
pm.movablepropertydesc,
w.wardid,
pm.totalarea,
me.descriptionenglish,
w.wardnumber,
pm.landmark,
pm.zoneid,
zone.departmentname,
subpropertytypeid,pm.applicationnumber,pm.assessment,pm.ownedarea,pm.roadcode,rd.roadnamee,ta.unit,pt.isagri , pm.valuationreport
offset pageoffset
fetch next pagesize rows only
 
)app_json


) data_json;
return v_data_json;
	END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_property_details_rule_17_3_json(_applicationnumber text, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_property_numbertype_details_json_check(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_property_numbertype_details_json_check(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(app_json) into v_data_json
from (
select  a.wardid,a.wardnumber,b.villagecode,c.villagenamee,
d.roadcode,d.roadnamee,c.talukcode,e.taluknamee,c.hoblicode,
f.hoblinamee,e.districtcode,g.districtnamee,i.currentnumber as UPORNumber,
	( select array_to_json(array_agg(row_to_json(propertynotype)))
      from (
	   select i.currentpropertytypeid,
j.typenameenglish as propertytype,i.currentnumber as propertynumberdetails
	  )propertynotype) as propertynotype
	from kaverimrg.warddetails a 
inner join kaverimrg.villagewardmapping b
on a.wardid = b.wardid and a.integrationenabled = true
inner join kaverimrg.villagemaster c on c.villagecode = b.villagecode
inner join kaverimrg.roadmaster d on d.villagecode = c.villagecode
inner join kaverimrg.talukmaster e on e.talukcode = c.talukcode
inner join kaverimrg.hoblimaster f on f.hoblicode = c.hoblicode
inner join kaverimrg.districtmaster g on g.districtcode = e.districtcode
inner join kaverimrg.propertymaster h on h.villagecode = b.villagecode
inner join kaverimrg.propertynumberdetails i on i.propertyid = h.propertyid 
and i.currentpropertytypeid = h.propertytypeid
inner join kaverimrg.propertynotypemaster j on j.propertytypeid = i.currentpropertytypeid
inner join kaverimrg.sromaster k on k.districtcode = g.districtcode 
where h.applicationnumber = _applicationnumber
	order by a.wardid,a.wardnumber,b.villagecode,d.roadcode,c.talukcode,
c.hoblicode,e.districtcode
) app_json ;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_property_numbertype_details_json_check(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_propertyinfo_by_name(character varying, character varying, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_propertyinfo_by_name(_englishname character varying, _kannadaname character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber character varying, finalregistrationnumber character varying, uploaddocdeedpath text, articlenamee character varying, name1 text, address character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$




DECLARE
PageOffset INTEGER := 0;

begin
	
	PageOffset := ((pagenumber - 1) * pagesize);
	return query
	with cte as (select distinct 
d.applicationnumber,d.finalregistrationnumber,d.uploaddocdeedpath,r.articlenamee,
concat_ws(' '::text, e.descriptione, p.firstname, p.middlename, p.lastname) AS name,
p.address
from kaverimrg.partyinfo p 
join kaverimrg.documentmaster d  on p.applicationnumber=d.applicationnumber
LEFT JOIN kaverimrg.salutationmaster e ON p.salutationid = e.salutationid
join kaverimrg.registrationarticles r on d.regarticlecode=r.regarticlecode 
where d.isregistrationcompleted=true  and 
( concat_ws(' '::text, p.firstname, p.middlename, p.lastname)
ilike ('%'||_englishname::text||'%') or concat_ws(' '::text, p.firstname, p.middlename, p.lastname)
ilike ('%'||_kannadaname::text||'%'))),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_propertyinfo_by_name(_englishname character varying, _kannadaname character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_propertyinfo_by_proofid(integer, character varying, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_propertyinfo_by_proofid(_idprooftypeid integer, _idproofno character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber character varying, finalregistrationnumber character varying, uploaddocdeedpath text, articlenamee character varying, name1 text, address character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;

begin
	
	PageOffset := ((pagenumber - 1) * pagesize);
	return query
	with cte as (select distinct 
d.applicationnumber,d.finalregistrationnumber,d.uploaddocdeedpath,r.articlenamee,
concat_ws(' '::text, e.descriptione, p.firstname, p.middlename, p.lastname) AS name,
p.address
from kaverimrg.partyinfo p 
join kaverimrg.documentmaster d  on p.applicationnumber=d.applicationnumber
LEFT JOIN kaverimrg.salutationmaster e ON p.salutationid = e.salutationid
join kaverimrg.registrationarticles r on d.regarticlecode=r.regarticlecode 
where d.isregistrationcompleted=true  and p.idprooftypeid=_idprooftypeid and p.pan=_idproofno),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_propertyinfo_by_proofid(_idprooftypeid integer, _idproofno character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_propertyinfo_by_propertyid(bigint, bigint, bigint, character varying, character varying, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_propertyinfo_by_propertyid(_districtcode bigint, _srocode bigint, _villagecode bigint, _propertyinfoeng character varying, _propertyinfokannada character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(applicationnumber character varying, finalregistrationnumber character varying, uploaddocdeedpath text, articlenamee character varying, name1 text, address text, totalcount bigint)
    LANGUAGE plpgsql
    AS $_$




DECLARE
PageOffset INTEGER := 0;
v_propertyideng integer;
v_eng boolean;
v_propertyidkan integer;
v_kan boolean;
v_propertyid integer;


begin
	
	PageOffset := ((pagenumber - 1) * pagesize);
SELECT TRIM(BOTH ' ' FROM _propertyinfoeng) into _propertyinfoeng;
SELECT TRIM(BOTH ' ' FROM _propertyinfokannada) into _propertyinfokannada;
--SELECT _propertyinfoeng ~ '^[0-9]+$' into v_eng;
--SELECT _propertyinfokannada ~ '^[0-9]+$' into v_kan;
	return query
	with cte as (select distinct 
d.applicationnumber,d.finalregistrationnumber,d.uploaddocdeedpath,r.articlenamee,
string_agg(distinct concat_ws(' '::text, e.descriptione, p.firstname, p.middlename, p.lastname),',') AS name,
string_agg(distinct concat_ws(' '::text, e.descriptione, p.firstname, p.middlename, p.lastname)|| ' '||p.address,
',')
from kaverimrg.partyinfo p 
join kaverimrg.documentmaster d  on p.applicationnumber=d.applicationnumber
left JOIN kaverimrg.salutationmaster e ON p.salutationid = e.salutationid
join kaverimrg.registrationarticles r on d.regarticlecode=r.regarticlecode
join kaverimrg.propertymaster p2  on d.applicationnumber=p2.applicationnumber 
join kaverimrg.propertynumberdetails pn2 on p2.propertyid=pn2.propertyid 
join kaverimrg.villagemaster v on p2.villagecode=v.villagecode 
join kaverimrg.sromaster sm on d.srocode=sm.srocode 
join kaverimrg.propertyschedules ps on ps.propertyid=p2.propertyid 
where d.isregistrationcompleted=true   
and ( p2.propertyid::text=_propertyinfoeng  or pn2.currentnumber=_propertyinfoeng 
or p2.propertyid::text=_propertyinfokannada  or pn2.currentnumber=_propertyinfokannada
or ps.description ilike '%'||_propertyinfoeng||'%' or ps.description ilike '%'||_propertyinfokannada||'%' )
and (

                    CASE

                       WHEN _districtcode <> 0 THEN  sm.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  sm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
                    
                   and 
                   (

                    CASE

                    WHEN _villagecode <> 0 THEN  p2.villagecode=_villagecode

                    ELSE TRUE

                    end

                    )
                    
                    group by d.applicationnumber,d.finalregistrationnumber,d.uploaddocdeedpath,
                    r.articlenamee
),
cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
end;
$_$;


ALTER FUNCTION kaverimrg.fn_fetch_propertyinfo_by_propertyid(_districtcode bigint, _srocode bigint, _villagecode bigint, _propertyinfoeng character varying, _propertyinfokannada character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_protestentry(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_protestentry(_finalregistrationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
	    from ( select c.districtnamee,c.districtnamee as droffice,
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,d.finalregistrationnumber,d.durationoffirm
			from kaverimrg.firmmaster d 
		join kaverimrg.applicantapplicationdetails a on d.applicationnumber =a.applicationnumber
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.finalregistrationnumber =_finalregistrationnumber
	   	group  by 	a.currentstatus,  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,d.finalregistrationnumber,d.durationoffirm)Firmdetails) as Firmdetails,
	
			  ( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT distinct ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid 
   FROM kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.firmprotestentry f ON f.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE  f.finalregistrationnumber =_finalregistrationnumber ) fdasdafetch) as fdasdafetch,
			  
			  	   
( select array_to_json(array_agg(row_to_json(Branchdetails)))
  from ( select
			bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
		stlgd.statenamee||'-'||bg.branchpincode as Address, bg.branchphone
		from kaverimrg.firmmaster d 
		inner join kaverimrg.firmbranches bg on d.applicationnumber =bg.applicationnumber
		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode 			                       
        where d.applicationnumber=bg.applicationnumber  and
		d.finalregistrationnumber = _finalregistrationnumber )Branchdetails) as Branchdetails,
		  
		  
( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,

( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,6)
	 order by firmpersonid)partnerdetails
) as partnerdetails,	  
							
( select array_to_json(array_agg(row_to_json(firmwitness)))
  from (select coalesce(fe.firstname,null) as firstname,coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID
					from kaverimrg.firmmaster d 	
 inner join kaverimrg.frm_witnessdetails fe  on d.applicationnumber=fe.applicationnumber
			where d.finalregistrationnumber =_finalregistrationnumber)firmwitness) as firmwitness
			  ,
			  
( select array_to_json(array_agg(row_to_json(remark))) from 
 ( SELECT ar.firmdetailsremarks_fda_sda, 
ar.presenterdetailsremarks_fda_sda, 
ar.partnerdetailsremarks_fda_sda,
ar.witnessdetailsremarks_fda_sda,
ar.stampdutyandfeedetailsremarks_fda_sda,
ar.uploaddocumentremarks_fda_sda,
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.witnessdetailsremarks_dr,
ar.stampdutyandfeedetailsremarks_dr,
ar.canprocesstopaymentremarks_dr,
ar.uploaddocumentremarks_dr
   FROM 
    kaverimrg.firmprotestentry f 
    left join  kaverimrg.firmapplicationremarks ar  on f.applicationnumber::text = ar.applicationnumber::text
 WHERE f.finalregistrationnumber =_finalregistrationnumber)remark)as remarks
   
from kaverimrg.firmmaster d 	
    inner join 	kaverimrg.firmparty a on d.applicationnumber=a.applicationnumber
inner join kaverimrg.districtmaster c on a.predistrictcode = c.districtcode
where d.finalregistrationnumber =_finalregistrationnumber
   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_protestentry(_finalregistrationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_protestentry_department(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_protestentry_department(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
	    from ( select c.districtnamee,c.districtnamee as droffice,
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,d.finalregistrationnumber,d.durationoffirm
			from kaverimrg.firmmaster d 
		join kaverimrg.applicantapplicationdetails a on d.applicationnumber =a.applicationnumber
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber and fp.presentertypeid in (1,6)
		inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where pe.applicationnumber =_applicationnumber
	   	group  by 	a.currentstatus,  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,d.finalregistrationnumber,d.durationoffirm)Firmdetails) as Firmdetails,
			  
			  	   
( select array_to_json(array_agg(row_to_json(Branchdetails)))
  from ( select
			bg.branchid,bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
		stlgd.statenamee||'-'||bg.branchpincode as Address, bg.branchphone
		from kaverimrg.firmbranches bg
		inner join kaverimrg.firmmaster d on d.applicationnumber =bg.applicationnumber
		inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode 			                       
        where pe.applicationnumber =_applicationnumber)Branchdetails) as Branchdetails,
		  
		  
( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
	inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where pe.applicationnumber =_applicationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,

( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
	  inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where pe.applicationnumber =_applicationnumber and br.presentertypeid in (1,6)
	 order by firmpersonid)partnerdetails
) as partnerdetails,	  
							
( select array_to_json(array_agg(row_to_json(firmwitness)))
  from (select coalesce(fe.firstname,null) as firstname,coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID
		from kaverimrg.firmmaster d 
inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
 inner join kaverimrg.frm_witnessdetails fe  on d.applicationnumber=fe.applicationnumber
			where pe.applicationnumber =_applicationnumber)firmwitness) as firmwitness,
			  
( select array_to_json(array_agg(row_to_json(remark))) from 
 ( SELECT
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.protestentrynotedremarks_dr,
ar.protestentryisnotvalidremarks_dr,
ar.uploaddocumentremarks_dr
   FROM  kaverimrg.firmapplicationremarks ar  
 WHERE ar.applicationnumber =_applicationnumber)remark)as remarks,
			  
			  	 ( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid
   FROM kaverimrg.applicantapplicationdetails ad
   LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
   LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 50
and ad.applicationnumber =_applicationnumber) fdasdafetch) as fdasdafetch
   
from kaverimrg.firmmaster d 	
inner join kaverimrg.firmprotestentry pe on pe.finalregistrationnumber=d.finalregistrationnumber
inner join kaverimrg.districtmaster c on d.districtcode = c.districtcode
where pe.applicationnumber =_applicationnumber
   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_protestentry_department(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_prpty_data_doc_summary(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_prpty_data_doc_summary(_applicationnumber text) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json1 json;
v_app text;
begin
v_app:=	_applicationnumber;
	

select array_to_json(array_agg(row_to_json(propertyinfo))) into v_data_json1
from (SELECT pm.applicationnumber,	  
			pm.propertyid,
			pm.documentid,
			stm.articlenamee as stamparticle,
			pm.ismovableproperty,
			d.villagenamee,
			pm.propertytypeid,
			ptm.propertytypename as propertytype,
			c.sronamee sroname,
			pm.northboundary,
			pm.denodescription ,
			pm.estampdescription,
			pm.adjudescription ,
			pm.southboundary,
			pm.eastboundary,
			pm.westboundary,
			pm.landmark,
			pm.consideration,
			pm.marketvalue,
			pm.sroconsideration,
			case when pm.sromarketvalue is null then 0 else pm.sromarketvalue end sromarketvalue,
			pm.cessduty,
			pm.govtduty,
			pm.additionalduty,
			pm.stampduty,
			pm.valid1 as duplicatecopies,
			calc.duplicatefee,
			calc.duplicatestampduty,
			calc.duplicateregistrationfee,
			calc.privateattandancefee,
			--calc.stampduty, 		
			pm.valuationreport,
			pm.sronoofscanpages, /* added a new column on 07/10/2022 to fetch number of scan pages in document summary page */
			sr.ismarketvaluationdone, /* added a new column on 06/11/2022 */
			h.hoblinamee as hobli, /* added a new column on 06/11/2022 */
			srf.ispartytopropertyschd, /* added a new column on 07/11/2022 */
			( select array_to_json(array_agg(row_to_json(schd)))
			  from (

				  select distinct ps.propertyid as propertyschedulespropertyid, 
						ps.scheduletype, 
						ps.totalarea,
					string_agg(pi.name,',') as bhoomisellername, pnam.firstname as name, ps.description as scheduledescription,
					case when pm.propertytypeid=17 then string_agg(pi.name,',') else null end as bhoomisellerparty,
					ps.eastboundary, ps.westboundary, ps.northboundary, ps.southboundary
				  from kaverimrg.propertyschedules ps 
				  left join kaverimrg.vw_fetch_party pi on pi.propertyid = ps.propertyid
				  left join (select ps1.scheduleid, array_to_string(array_agg(distinct pi2.name),',') 
								AS firstname from kaverimrg.partyschedules ps1
			left join 
						(select name,partyid from kaverimrg.vw_fetch_party vf where vf.applicationnumber = v_app ) as pi2 
							 on pi2.partyid = ps1.partyid 
							group by ps1.scheduleid)
				  as pnam on ps.scheduleid = pnam.scheduleid
				  where  ps.propertyid = pm.propertyid 
				  group by ps.propertyid, ps.scheduletype, ps.totalarea, pnam.firstname, ps.description, ps.eastboundary,
				  ps.westboundary, ps.northboundary, ps.southboundary)schd ) as propertyschedules,			
			  ( select array_to_json(array_agg(row_to_json(prptyno)))
			   from (select pnd.propertyid propertynumberpropertyid,pnd.currentpropertytypeid,
					 pntm.typenameenglish as propertynumbertype, pnd.currentnumber, coalesce(pnd.hissa_no,'') as hissa_no,
					 coalesce(pnd.survey_no,0) as survey_no, pnd.description as propertynumberdescription
					from kaverimrg.propertynumberdetails pnd 
					 left join kaverimrg.propertynotypemaster pntm on (pntm.propertytypeid = pnd.currentpropertytypeid) 
					 where pnd.propertyid = pm.propertyid )prptyno ) as propertynumberdetails
		   FROM kaverimrg.propertymaster pm 
		    join kaverimrg.propertytypemaster ptm on (ptm.propertytypeid = pm.propertytypeid) 
			 join kaverimrg.stamparticles stm on (stm.stamparticlecode=pm.stamparticlecode)
			 join kaverimrg.stamprules sr on pm.stampruleid = sr.stampruleid
			 join kaverimrg.stamprulesflag srf ON sr.stampruleid = srf.stampruleid
		    join  kaverimrg.sromaster c on (pm.srocode = c.srocode)
		    join kaverimrg.villagemaster d on (pm.villagecode = d.villagecode)
			 join kaverimrg.hoblimaster h on d.hoblicode = h.hoblicode
		    left join kaverimrg.vw_fee_calculation_details_chk_v2 calc on (pm.applicationnumber = calc.applicationnumber)
		   where pm.applicationnumber=v_app) as propertyinfo;
	
	
return v_data_json1;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_prpty_data_doc_summary(_applicationnumber text) OWNER TO postgres;

--
-- Name: fn_fetch_ratedetails(bigint, boolean, timestamp with time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_ratedetails(_roadcode bigint, isreadyrecknor boolean, _date timestamp with time zone) RETURNS TABLE(flaterateid bigint, floor character varying, floorid smallint, propertytype character varying, unit character varying, unitid integer, amenities character varying, amenitiesid integer, rate numeric)
    LANGUAGE plpgsql
    AS $$



declare
v_cnt int;
v_max_rate bigint;
v_measure_id int;
begin
	

	if (isreadyrecknor=false)
		then 
		return query
		select s.flaterateid,s.floor,s.floorid,s.propertytype, s.unit, s.unitid, s.amenities, s.amenitiesid,s.rate from (
		select flatRates.flaterateid,flatRates.floor,flatRates.floorid,flatRates.propertytype, flatRates.unit, flatRates.unitid, flatRates.amenities,flatRates.amenitiesid,  
		(case when flatRates.unitid = 3 then (flatRates.rate::decimal * 10.7639::decimal) else flatRates.rate::decimal end) 
		as rate from (select frm.flaterateid,br.description as floor,br.floorid,pm.propertytypename as propertytype,mu.descriptionenglish as unit
		,mu.unitid ,am.namewithamenities as amenities,am.amenitiesid,frm.rate, ROW_NUMBER() OVER(PARTITION BY frm.propertytypeid , 
		frm.floorid,frm.unitid,frm.amenitiesid  ORDER BY frm.effectivedate  desc) AS Row from kaverimrg.mas_val_flatrates frm
		left join kaverimrg.measunitmaster mu on frm.unitid=mu.unitid
		left join kaverimrg.mas_val_buildingfloors br on frm.floorid=br.floorid
		left join kaverimrg.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
		left join kaverimrg.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
		where frm.roadid=_roadcode and frm.effectivedate::date <= _date )flatRates where row =1) s;
			
	
	elsif(isreadyrecknor=true)
		then
		select count(*) into v_cnt from (select frm.flaterateid,br.description as floor,br.floorid,pm.propertytypename as propertytype,mu.descriptionenglish as unit
		,mu.unitid ,am.namewithamenities as amenities,am.amenitiesid,frm.rate, ROW_NUMBER() OVER(PARTITION BY frm.propertytypeid, 
		frm.floorid,frm.unitid,frm.amenitiesid  ORDER BY frm.effectivedate  desc) AS Row from kaverimrg.mas_val_flatrates frm 
	    left join kaverimrg.measunitmaster mu on frm.unitid=mu.unitid
		left join kaverimrg.mas_val_buildingfloors br on frm.floorid=br.floorid
		left join kaverimrg.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
		left join kaverimrg.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
		where frm.roadid=_roadcode and frm.effectivedate::date <= _date)flatRates where row =1;
		
		if(v_cnt>1)
		then
			return query
			select m.flaterateid,m.floor,m.floorid,m.propertytype, m.unit, m.unitid, m.amenities, m.amenitiesid,m.rate from (
			select flatRates.flaterateid,flatRates.floor,flatRates.floorid,flatRates.propertytype, flatRates.unit, flatRates.unitid, flatRates.amenities
			, flatRates.amenitiesid,  
			(case when flatRates.unitid = 3 then (flatRates.rate::decimal * 10.7639::decimal) else flatRates.rate::decimal end) 
			as rate from (select frm.flaterateid,br.description as floor,br.floorid,pm.propertytypename as propertytype,mu.descriptionenglish as unit
			,mu.unitid ,am.namewithamenities as amenities,am.amenitiesid,frm.rate, ROW_NUMBER() OVER(PARTITION BY frm.propertytypeid, 
			frm.floorid,frm.unitid,frm.amenitiesid  ORDER BY frm.effectivedate  desc) AS Row from kaverimrg.mas_val_flatrates frm 
			left join kaverimrg.measunitmaster mu on frm.unitid=mu.unitid
			left join kaverimrg.mas_val_buildingfloors br on frm.floorid=br.floorid
			left join kaverimrg.mas_val_apartmentsamenities am on frm.amenitiesid=am.amenitiesid 
			left join kaverimrg.propertytypemaster pm on frm.propertytypeid=pm.propertytypeid
			where frm.roadid=_roadcode and frm.effectivedate::date <= _date)flatRates where row =1) m;
		
		else
		
		
			select ss.rate into v_max_rate  from (
			select (case when o.measurementcode=3 then max(o.rate)::decimal * 10.7639::decimal  
			else max(o.rate)::decimal end) as rate ,
			--into v_max_rate ,
			o.effectivedate,
			COALESCE(lead(o.effectivedate, 1) OVER (PARTITION BY o.roadcode, o.propertytypeid 
			ORDER BY o.effectivedate), CURRENT_DATE::timestamp without time zone) AS effectivetodate
			from kaverimrg.openbuiltratedetail o where roadcode =_roadcode
			group by o.measurementcode,o.effectivedate,o.roadcode, o.propertytypeid) as ss 
			where CURRENT_DATE >= ss.effectivedate AND CURRENT_DATE <= ss.effectivetodate
				;
			
	
		
	
			return query	
			select null::bigint as flaterateid,'Ground Floor'::character varying as floor,1::smallint as floorid
			,'Commercial'::character varying as propertytype,'Sq.metre'::character varying as unit,4 as unitid
			, 'Readyreckoner Rate'::character varying  as amenities,null::int as amenitiesid, flatrate::numeric as rate from kaverimrg.mas_val_readyreckoner_flats mvrf 
				where (vctratefrom<=v_max_rate and vctrateto>=v_max_rate); 
		
		end if;
	end if;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_ratedetails(_roadcode bigint, isreadyrecknor boolean, _date timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_fetch_receipt(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_receipt(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json  
	    from ( select c.districtnamee,c.districtnamee as droffice,	
			  
		 (select array_to_json(array_agg(row_to_json(totalfee)))  
		  from 
 ( SELECT sum(fr.payableamount) as totalamount,s.servicename,br.firstname||''||br.middlename||''||br.lastname as presentername,
  pm.chlnrefnum as challannumber,pm.inserteddatetime::date as paymentdate,fr.applicationnumber,f.inserteddatetime::date as DateOfRegistration,
  p.descriptionenglish as paymentmode,--fm.descriptionk as feerulenamek,
  f.finalregistrationnumber
   FROM kaverimrg.firm_requiredfees fr 
     JOIN kaverimrg.firmmaster f ON f.applicationnumber::text = fr.applicationnumber::text
  inner join kaverimrg.applicantapplicationdetails a on a.applicationnumber::text=f.applicationnumber::text
  inner join kaverimrg.servicesmaster s on a.applicationtypeid=s.serviceid
  inner join kaverimrg.firmparty br on f.applicationnumber::text=br.applicationnumber::text and br.presentertypeid in (1,2)
  inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
  left join kaverimrg.ams_reg_epaymenttransdetails pm on pm.applicationnumber::text=fr.applicationnumber::text
  left join kaverimrg.receiptpaymentdetails r on r.receiptid=pm.receiptid
  left join kaverimrg.paymentmodemaster p on p.paymentmodeid=r.paymentmodeid
  inner join kaverimrg.feesrulemaster fm on fr.feeruleid=fm.feerulecode
   WHERE f.applicationnumber =_applicationnumber
 GROUP BY s.servicename,br.firstname,br.middlename,br.lastname,pm.chlnrefnum,pm.inserteddatetime,fr.applicationnumber,
 f.inserteddatetime,p.descriptionenglish,f.finalregistrationnumber--,fm.descriptionk
 ) totalfee) as totalfee,
			  
			   ( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT --sum(fr.payableamount) as totalamount,
  fr.feeruleid,fr.feedescription,fr.payableamount,fm.descriptionk as feerulenamek
   FROM kaverimrg.firm_requiredfees fr 
    inner JOIN kaverimrg.firmmaster f ON f.applicationnumber::text = fr.applicationnumber::text
   inner join kaverimrg.feesrulemaster fm on fr.feeruleid=fm.feerulecode
   WHERE fr.applicationnumber =_applicationnumber
 -- GROUP BY fr.feeruleid,fr.feedescription,fr.payableamount
 ) feesrequiredbyappl) as feesrequiredbyappl,
			  	  
( select array_to_json(array_agg(row_to_json(partnerdetails))) 		  
from (select br.firstname||''||br.middlename||''||br.lastname as partnername, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID, br.firmpersonid,
br.presentertypeid,br.perhousebuildname||' '||br.perstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||br.perpincode as Address,
CASE
WHEN r.presentertypeid=8 THEN  r.firstname||''||r.middlename||''||r.lastname --as name
else
	  NULL 
END as G_tname,
	  
CASE
WHEN r.presentertypeid=8 THEN  'Guardian'--pt.description 
else
	  NULL 
END as G_designation,
	  
CASE
WHEN r.presentertypeid=8 THEN r.phoneno 
else
	  NULL 
END as G_phonenumber,
CASE
WHEN r.presentertypeid=8 THEN  r.mailaddress 
else
	  NULL 
END as G_EmailID,
	  
CASE
WHEN r.presentertypeid=8 THEN  r.firmpersonid
else
	  NULL 
END as G_firmpersonid,

CASE
WHEN r.presentertypeid=8 THEN  r.presentertypeid
else
	  NULL 
END as G_presentertypeid,

	  CASE
WHEN r.presentertypeid=8 THEN  r.perhousebuildname||' '||r.perstreetname||' '||di.districtnamee||' '||ta.taluknamee||' '||
ho.hoblinamee||' '||vi.villagenamee||'-'||br.perpincode --as Address
else
	  NULL 
END as G_Address  	  
from kaverimrg.firmparty br
left JOIN kaverimrg.firmparty r on br.linkfirmpersonid=r.firmpersonid
left JOIN kaverimrg.firmparty rs on rs.linkfirmpersonid=r.firmpersonid
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode
left join kaverimrg.districtmaster di on r.perdistrictcode  = di.districtcode 
left join kaverimrg.talukmaster ta on r.pertalukacode  = ta.talukcode 
left join kaverimrg.hoblimaster ho on r.perhoblicode  = ho.hoblicode 
left join kaverimrg.villagemaster vi on r.percityvillagecode  = vi.villagecode	  
where br.applicationnumber = _applicationnumber and br.presentertypeid!=8 and br.presentertypeid in (1,6,2))partnerdetails) as partnerdetails,
			  
(select array_to_json(array_agg(row_to_json(firmwitness)))
	from (select   fe.firmwitnessid,fe.firstname||'-'||fe.middlename||'-'||fe.lastname as  witnessname,fe.witnessfathername,
fe.withousebuildname||' '||fe.witstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||fe.witpincode as Address 
	from kaverimrg.frm_witnessdetails fe 
	left join kaverimrg.districtmaster dis on fe.witdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fe.wittalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fe.withoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fe.witcityvillagecode  = vil.villagecode	  	  
	where fe.applicationnumber =_applicationnumber)firmwitness) as firmwitness
			  
 from kaverimrg.firmparty a 
inner join kaverimrg.sromaster b on a.perdistrictcode = b.districtcode 
inner join kaverimrg.districtmaster c on a.perdistrictcode = c.districtcode
where a.applicationnumber = _applicationnumber	   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_receipt(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_receipt_amendment(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_receipt_amendment(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json  
	    from ( select c.districtnamee,c.districtnamee as droffice,	
			  
		 (select array_to_json(array_agg(row_to_json(totalfee)))  
		  from 
 ( SELECT sum(fr.payableamount) as totalamount,s.servicename,sm.descriptione||' '||br.firstname||' '||br.middlename||' '||br.lastname as presentername,
  br.amendhousebuildingname||''||br.amendstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||br.amendpincode as presenterAddres,
  pm.chlnrefnum as challannumber,pm.inserteddatetime::date as paymentdate,f.applicationnumber,f.inserteddatetime as DateOfRegistration,
  p.descriptionenglish as paymentmode,f.finalregistrationnumber
   FROM kaverimrg.firm_requiredfees fr 
     JOIN kaverimrg.firmamendment f ON f.applicationnumber::text = fr.applicationnumber::text
  inner join kaverimrg.applicantapplicationdetails a on a.applicationnumber::text=f.applicationnumber::text
inner join kaverimrg.servicesmaster s on a.applicationtypeid=s.serviceid
 inner join kaverimrg.amendmentfirmparty br on f.amendmentid=br.amendmentid and br.presentertypeid in (1,2)
  inner join kaverimrg.salutationmaster sm on br.salutation=sm.salutationid
--   inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.ams_reg_epaymenttransdetails pm on pm.applicationnumber::text=fr.applicationnumber::text
left join kaverimrg.receiptpaymentdetails r on r.receiptid=pm.receiptid
 left join kaverimrg.paymentmodemaster p on p.paymentmodeid=r.paymentmodeid
   left join kaverimrg.districtmaster dis on br.amenddistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.amendtalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.amendhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.amendcityvillagecode  = vil.villagecode
   WHERE f.applicationnumber =_applicationnumber
 GROUP BY s.servicename,sm.descriptione,br.firstname,br.middlename,br.lastname,pm.chlnrefnum,pm.inserteddatetime,f.applicationnumber,
   br.amendhousebuildingname,br.amendstreetaddress,dis.districtnamee,tal.taluknamee,hob.hoblinamee,vil.villagenamee,br.amendpincode,
 f.inserteddatetime,p.descriptionenglish,f.finalregistrationnumber) totalfee) as totalfee,
			  
( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT fr.feeruleid,fr.feedescription,fr.payableamount,fm.descriptionk as feerulenamek
   FROM kaverimrg.firm_requiredfees fr 
    inner JOIN kaverimrg.firmamendment f ON f.applicationnumber::text = fr.applicationnumber::text
  inner join kaverimrg.feesrulemaster fm on fr.feeruleid=fm.feerulecode
   WHERE f.applicationnumber =_applicationnumber) feesrequiredbyappl) as feesrequiredbyappl,
			  
( select row_to_json(oldfirmdetails)  from 
 ( SELECT fr.firmname,
  fr.housebuildingname||' '||fr.streetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||
  fr.pincode as oldfirmname,fr.registrationid
   FROM kaverimrg.firmmaster fr
  inner join kaverimrg.firmamendment fa on fa.finalregistrationnumber=fr.finalregistrationnumber
  left join kaverimrg.districtmaster dis on fr.districtcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fr.talukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fr.hoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fr.cityvillagecode  = vil.villagecode
  WHERE fa.applicationnumber =_applicationnumber) oldfirmdetails) as oldfirmdetails,			  
			  		  
( select row_to_json(Newfirmdetails)  from 
 ( SELECT fr.firmname,
  fr.amendhousebuildingname||' '||fr.amendstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||
  fr.amendpincode as Newfirmname,fr.amendmentid
   FROM kaverimrg.firmamendment fr
  left join kaverimrg.districtmaster dis on fr.amenddistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fr.amendtalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fr.amendhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fr.amendcityvillagecode  = vil.villagecode
  WHERE fr.applicationnumber =_applicationnumber) Newfirmdetails) as Newfirmdetails,
			  
( select array_to_json(array_agg(row_to_json(removedBranchdetails)))
  from ( 
	  (select bg.branchid,ab.amendmentid, bg.branchhousebuildingname||' '||bg.branchstreetaddress||' '||tal.taluknamee||' '||dis.districtnamee||' '||
		s.statenamee ||' '|| bg.branchpincode as branchaddess  
		from kaverimrg.firmamendment fa
        inner join kaverimrg.firmmaster f on fa.finalregistrationnumber=f.finalregistrationnumber
		join kaverimrg.firmbranches  bg on bg.applicationnumber=f.applicationnumber
	   inner join kaverimrg.amendmentfirmbranches ab on ab.amendmentid=fa.amendmentid and ab.branchid=bg.branchid
		left join kaverimrg.lgd_statemaster s on bg.branchstatecode  = s.statecode 
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode 
	    left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode       
		where bg.branchid in (select branchid from kaverimrg.amendmentfirmbranches fb where fb.isremoved=true and fb.amendmentid=fa.amendmentid)
		and ab.applicationnumber=_applicationnumber))removedBranchdetails) as removedBranchdetails,
   
 ( select array_to_json(array_agg(row_to_json(AddedsBranchdetails)))
  from ( 
	  select fb.amendmentbranchid ,fb.amendmentid, fb.amendhousebuildingname||' '||fb.amendstreetaddress||' '||tal.taluknamee||' '||dis.districtnamee||' '||
		s.statenamee ||' '|| fb.amendpincode as branchaddess  
	   from kaverimrg.firmamendment fa
        join kaverimrg.amendmentfirmbranches fb on fa.amendmentid=fb.amendmentid 
        left join kaverimrg.lgd_statemaster s on fb.amendstatecode  = s.statecode 
		left join kaverimrg.lgd_districtmaster dis on fb.amenddistrictcode = dis.districtcode 
	    left join kaverimrg.lgd_talukmaster tal on fb.amendtalukacode = tal.talukcode       
        where fb.isremoved=false and fa.applicationnumber=_applicationnumber)AddedsBranchdetails) as AddedsBranchdetails,			  
			  	  
( select array_to_json(array_agg(row_to_json(oldpartnerdetails))) 		  
from (
 select br.firstname||' '||br.middlename||' '||br.lastname as partnername, pt.description as designation, br.firmpersonid,
br.presentertypeid,br.perhousebuildname ||' '||br.perstreetname ||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||br.perpincode  as Address
from kaverimrg.firmamendment a
inner join kaverimrg.firmmaster f on a.finalregistrationnumber=f.finalregistrationnumber
inner join kaverimrg.firmparty br  on f.applicationnumber=br.applicationnumber
inner join kaverimrg.amendmentfirmparty d on d.amendmentid=a.amendmentid and d.firmpersonid=br.firmpersonid
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode
where br.firmpersonid in (select firmpersonid from kaverimrg.amendmentfirmparty fb where fb.firmpersonid =br.firmpersonid 
and fb.amendmentid=a.amendmentid)
and a.applicationnumber =_applicationnumber and d.presentertypeid in (6) and a.amendmenttypeid=3)oldpartnerdetails) as oldpartnerdetails,
 
( select array_to_json(array_agg(row_to_json(newpartnerdetails))) 		  
from (select br.firstname||' '||br.middlename||' '||br.lastname as partnername, pt.description as designation, br.firmpersonid ,
br.presentertypeid,br.amendhousebuildingname||' '||br.amendstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||br.amendpincode as Address
from kaverimrg.amendmentfirmparty br
inner join kaverimrg.firmamendment a on a.amendmentid=br.amendmentid
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.districtmaster dis on br.amenddistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.amendtalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.amendhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.amendcityvillagecode  = vil.villagecode
where a.applicationnumber = _applicationnumber and br.presentertypeid in (6) and a.amendmenttypeid=3)newpartnerdetails) as newpartnerdetails,
			  
( select array_to_json(array_agg(row_to_json(minorpartnerdetails))) 		  
from (select ap.firstname,ap.middlename,ap.lastname,ap.firmpersonid,ap.amendmentpersonid,ap.amendmentid,ap.age
        from  kaverimrg.firmamendment am 
		inner join kaverimrg.amendmentfirmparty ap on am.amendmentid=ap.amendmentid
			where am.applicationnumber =_applicationnumber and ap.presentertypeid=6 and am.amendmenttypeid=4
)minorpartnerdetails) as minorpartnerdetails,			  
			 
(select array_to_json(array_agg(row_to_json(firmwitness)))
	from (select   fe.firmwitnessid,fe.firstname||'-'||fe.middlename||'-'||fe.lastname as  witnessname,fe.witnessfathername,
fe.withousebuildname||' '||fe.witstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||fe.witpincode as Address 
	from kaverimrg.frm_witnessdetails fe 
		  inner join kaverimrg.firmmaster f on f.applicationnumber=fe.applicationnumber
		  inner join kaverimrg.firmamendment a on a.finalregistrationnumber=f.finalregistrationnumber
	left join kaverimrg.districtmaster dis on fe.witdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fe.wittalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fe.withoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fe.witcityvillagecode  = vil.villagecode	  	  
	where a.applicationnumber =_applicationnumber)firmwitness) as firmwitness
			  
 from kaverimrg.firmparty a 
			  inner join kaverimrg.firmmaster fm on a.applicationnumber=fm.applicationnumber
			  inner join kaverimrg.firmamendment f on f.finalregistrationnumber=fm.finalregistrationnumber
inner join kaverimrg.sromaster b on f.drcode  = b.districtcode 
inner join kaverimrg.districtmaster c on f.drcode = c.districtcode
where f.applicationnumber = _applicationnumber	   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_receipt_amendment(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_receipt_dissolution(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_receipt_dissolution(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json  
	    from ( select c.districtnamee,c.districtnamee as droffice,	
			  
		 (select array_to_json(array_agg(row_to_json(totalfee)))  
		  from 
 (SELECT sum(fr.payableamount) as totalamount,s.servicename,br.firstname||''||br.middlename||''||br.lastname as presentername,
  br.perhousebuildingname||''||br.perstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||br.perpincode as presenterAddres,
  pm.chlnrefnum as challannumber,pm.inserteddatetime::date as paymentdate,fa.applicationnumber,fa.inserteddatetime::date as DateOfRegistration,
  p.descriptionenglish as paymentmode,fa.finalregistrationnumber 
   FROM kaverimrg.firm_requiredfees fr
inner join kaverimrg.firm_dissolution fa on fa.applicationnumber=fr.applicationnumber 
inner join kaverimrg.applicantapplicationdetails a on a.applicationnumber::text=fa.applicationnumber::text
inner join kaverimrg.servicesmaster s on a.applicationtypeid=s.serviceid
inner join kaverimrg.dissolutionfirmparty br on fa.applicationnumber::text=br.applicationnumber::text and br.presentertypeid in (1,2)
left join kaverimrg.ams_reg_epaymenttransdetails pm on pm.applicationnumber::text=fr.applicationnumber::text
left join kaverimrg.receiptpaymentdetails r on r.receiptid=pm.receiptid
left join kaverimrg.paymentmodemaster p on p.paymentmodeid=r.paymentmodeid
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode
WHERE fa.applicationnumber =_applicationnumber
 GROUP BY s.servicename,pm.chlnrefnum,pm.inserteddatetime,fa.applicationnumber,
 fa.inserteddatetime,p.descriptionenglish,fa.finalregistrationnumber,br.firstname,br.middlename,br.lastname,
 br.perhousebuildingname,br.perstreetaddress,dis.districtnamee,tal.taluknamee,hob.hoblinamee,vil.villagenamee,br.perpincode) totalfee) as totalfee,
			  
( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT fr.feeruleid,fr.feedescription,fr.payableamount,fm.descriptionk as feerulenamek
   FROM kaverimrg.firm_requiredfees fr 
    inner JOIN kaverimrg.firm_dissolution f ON f.applicationnumber::text = fr.applicationnumber::text
  inner join kaverimrg.feesrulemaster fm on fr.feeruleid=fm.feerulecode
   WHERE f.applicationnumber =_applicationnumber) feesrequiredbyappl) as feesrequiredbyappl,			  
			  		  
(select array_to_json(array_agg(row_to_json(dateofdissolution)))
  from (select fd.dateofdissolutionofdate::date,fd.dissolutionid
		from kaverimrg.firm_dissolution fd 
			where fd.applicationnumber =_applicationnumber)dateofdissolution) as dateofdissolution,
			 		  
( select array_to_json(array_agg(row_to_json(Presenterdetails))) 		  
from (select br.firstname||''||br.middlename||''||br.lastname as Presentername, pt.description as designation, br.phoneno as phonenumber,br.email as EmailID,
br.presentertypeid,br.perhousebuildingname||' '||br.perstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||br.perpincode as Address,br.dissolutionpersonid	  
from kaverimrg.dissolutionfirmparty br
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode 
where br.applicationnumber = _applicationnumber and br.presentertypeid in (1,2))Presenterdetails) as Presenterdetails,		  
			 			  		  
(select array_to_json(array_agg(row_to_json(firmwitness)))
	from (select   fe.firmwitnessid,fe.firstname||'-'||fe.middlename||'-'||fe.lastname as  witnessname,fe.witnessfathername,
fe.withousebuildname||' '||fe.witstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||fe.witpincode as Address 
	from kaverimrg.frm_witnessdetails fe 
		  inner join kaverimrg.firmmaster f on f.applicationnumber=fe.applicationnumber
		  inner join kaverimrg.firm_dissolution a on a.finalregistrationnumber=f.finalregistrationnumber
	left join kaverimrg.districtmaster dis on fe.witdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fe.wittalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fe.withoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fe.witcityvillagecode  = vil.villagecode	  	  
	where a.applicationnumber =_applicationnumber)firmwitness) as firmwitness
			  
 from kaverimrg.firmparty a 
			  inner join kaverimrg.firmmaster fm on a.applicationnumber=fm.applicationnumber
			  inner join kaverimrg.firm_dissolution f on f.finalregistrationnumber=fm.finalregistrationnumber
inner join kaverimrg.sromaster b on a.perdistrictcode = b.districtcode 
inner join kaverimrg.districtmaster c on a.perdistrictcode = c.districtcode
where f.applicationnumber = _applicationnumber  
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_receipt_dissolution(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_receipt_reconstitution(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_receipt_reconstitution(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json  
	    from ( select c.districtnamee,c.districtnamee as droffice,	
			  
		 (select array_to_json(array_agg(row_to_json(totalfee)))  
		  from 
 ( SELECT sum(fr.payableamount) as totalamount,s.servicename,br.firstname||''||br.middlename||''||br.lastname as presentername,
  br.perhousebuildname||''||br.perstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||br.perpincode as presenterAddres,
  pm.chlnrefnum as challannumber,pm.inserteddatetime::date as paymentdate,fa.applicationnumber,fa.inserteddatetime::date as DateOfRegistration,
  p.descriptionenglish as paymentmode,fa.firmfinalregnumber
   FROM kaverimrg.firm_requiredfees fr
   inner join kaverimrg.firmreconstitution fa on fa.applicationnumber=fr.applicationnumber 
  inner join kaverimrg.applicantapplicationdetails a on a.applicationnumber::text=fa.applicationnumber::text
inner join kaverimrg.servicesmaster s on a.applicationtypeid=s.serviceid
 inner join kaverimrg.firmreconstitutionparty br on fa.reconstitutionid=br.reconstitutionid and br.presentertypeid in (1,2)
 left join kaverimrg.ams_reg_epaymenttransdetails pm on pm.applicationnumber::text=fr.applicationnumber::text
left join kaverimrg.receiptpaymentdetails r on r.receiptid=pm.receiptid
 left join kaverimrg.paymentmodemaster p on p.paymentmodeid=r.paymentmodeid
     left join kaverimrg.districtmaster dis on br.predistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pretalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.prehoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.precityvillagecode  = vil.villagecode
   WHERE fa.applicationnumber =_applicationnumber
 GROUP BY s.servicename,br.firstname,br.middlename,br.lastname,pm.chlnrefnum,pm.inserteddatetime,fa.applicationnumber,
  br.perhousebuildname,br.perstreetname,dis.districtnamee,tal.taluknamee,hob.hoblinamee,vil.villagenamee,br.perpincode,
 fa.inserteddatetime,p.descriptionenglish,fa.firmfinalregnumber) totalfee) as totalfee,
			  
( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT fr.feeruleid,fr.feedescription,fr.payableamount,fm.descriptionk as feerulenamek
   FROM kaverimrg.firm_requiredfees fr 
    inner JOIN kaverimrg.firmreconstitution f ON f.applicationnumber::text = fr.applicationnumber::text
  inner join kaverimrg.feesrulemaster fm on fr.feeruleid=fm.feerulecode
   WHERE f.applicationnumber =_applicationnumber) feesrequiredbyappl) as feesrequiredbyappl,			  
			  		  
--   (select array_to_json(array_agg(row_to_json(IncommingpartnerName)))
--   from 
--    (select e.reconstitutionpartyid,e.reconstitutionid,e.firmpersonid,e.firstname||' '||e.middlename||' '||e.lastname as incomepartnername,
-- e.perhousebuildname||' '||e.perstreetname||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee
-- ||' '||stat.statenamee||'-'||e.perpincode as Address
-- 		from kaverimrg.firmreconstitutionparty e
-- 		inner join kaverimrg.firmreconstitution fa on e.reconstitutionid=fa.reconstitutionid
-- 		left join kaverimrg.districtmaster di on e.perdistrictcode = di.districtcode
-- 	    left join kaverimrg.talukmaster ta on e.pertalukacode = ta.talukcode
-- 		left join kaverimrg.hoblimaster ho on e.perhoblicode = ho.hoblicode
-- 		left join kaverimrg.villagemaster vill on e.percityvillagecode = vill.villagecode
-- 		left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
--    where fa.applicationnumber =_applicationnumber and e.isincoming=true)IncommingpartnerName) as IncommingpartnerName,

-- 			    (select array_to_json(array_agg(row_to_json(OutgoingpartnerName)))
--   from (select e.reconstitutionpartyid,e.reconstitutionid,e.firmpersonid,
-- e.firstname,e.middlename,e.lastname,e.perhousebuildname||' '||e.perstreetname||' '||di.districtnamee||' '||
-- ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||stat.statenamee||'-'||e.perpincode as Address
-- 		from kaverimrg.firmreconstitutionparty e
-- 		inner join kaverimrg.firmreconstitution fa on e.reconstitutionid=fa.reconstitutionid 
-- 		left join kaverimrg.districtmaster di on e.perdistrictcode = di.districtcode
-- 	    left join kaverimrg.talukmaster ta on e.pertalukacode = ta.talukcode
-- 		left join kaverimrg.hoblimaster ho on e.perhoblicode = ho.hoblicode
-- 		left join kaverimrg.villagemaster vill on e.percityvillagecode = vill.villagecode
-- 		left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
--    where fa.applicationnumber =_applicationnumber and e.isoutgoing is true)OutgoingpartnerName) as OutgoingpartnerName,
			  
			  
( select array_to_json(array_agg(row_to_json(partnerdetails))) 		  
from (select br.firstname||''||br.middlename||''||br.lastname as partnername, pt.description as designation, br.phoneno as phonenumber,br.emailid as EmailID, br.firmpersonid,
br.presentertypeid,br.prehousebuildname||' '||br.prestreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||br.prepincode as Address,br.reconstitutionpartyid,br.reconstitutionid,br.isincoming,br.isoutgoing 	  
from kaverimrg.firmreconstitutionparty br
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode 
where br.applicationnumber = _applicationnumber and br.presentertypeid in (6))partnerdetails) as partnerdetails,
			  
			  ( select array_to_json(array_agg(row_to_json(Presenterdetails))) 		  
from (select br.firstname||''||br.middlename||''||br.lastname as Presentername, pt.description as designation, br.phoneno as phonenumber,br.emailid as EmailID, br.firmpersonid,
br.presentertypeid,br.prehousebuildname||' '||br.prestreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||
hob.hoblinamee||' '||vil.villagenamee||'-'||br.prepincode as Address,br.reconstitutionpartyid,br.reconstitutionid	  
from kaverimrg.firmreconstitutionparty br
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
left join kaverimrg.districtmaster dis on br.perdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on br.pertalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on br.perhoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on br.percityvillagecode  = vil.villagecode 
where br.applicationnumber = _applicationnumber and br.presentertypeid in (1,2))Presenterdetails) as Presenterdetails,
			  		  
			  		  
(select array_to_json(array_agg(row_to_json(firmwitness)))
	from (select   fe.firmwitnessid,fe.firstname||'-'||fe.middlename||'-'||fe.lastname as  witnessname,fe.witnessfathername,
fe.withousebuildname||' '||fe.witstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||fe.witpincode as Address 
	from kaverimrg.frm_witnessdetails fe 
		  inner join kaverimrg.firmmaster f on f.applicationnumber=fe.applicationnumber
		  inner join kaverimrg.firmreconstitution a on a.firmfinalregnumber=f.finalregistrationnumber
	left join kaverimrg.districtmaster dis on fe.witdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fe.wittalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fe.withoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fe.witcityvillagecode  = vil.villagecode	  	  
	where a.applicationnumber =_applicationnumber)firmwitness) as firmwitness		  
 from kaverimrg.firmparty a 
			  inner join kaverimrg.firmmaster fm on a.applicationnumber=fm.applicationnumber
			  inner join kaverimrg.firmreconstitution f on f.firmfinalregnumber=fm.finalregistrationnumber
inner join kaverimrg.sromaster b on a.perdistrictcode = b.districtcode 
inner join kaverimrg.districtmaster c on a.perdistrictcode = c.districtcode
where f.applicationnumber = _applicationnumber  
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_receipt_reconstitution(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_reconstitution(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_reconstitution(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;

begin

select row_to_json(data_json) into v_data_json 
 -- from (select row_to_json(app_json) 
 from ( select  c.districtnamee,c.districtnamee as droffice,	
	   
 (select array_to_json(array_agg((row_to_json(Firmdetails))))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee
			||' '||
		stat.statenamee||'-'||d.pincode as Address,
		count(distinct firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		d.inserteddatetime::date as DateOfRegistration
			from kaverimrg.firmmaster d 
		inner join kaverimrg.firmreconstitution fa on d.finalregistrationnumber=fa.firmfinalregnumber 
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber and fp.presentertypeid in (1,6)
		inner join kaverimrg.applicantapplicationdetails a on fa.applicationnumber  =a.applicationnumber
		inner join kaverimrg.wrkflowmaster wf on a.currentstatus =wf.wrkflowstatusid 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
		where fa.applicationnumber =_applicationnumber
	   	group  by d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		d.inserteddatetime)Firmdetails) as Firmdetails,
		
		-------------
		( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select
br.firmpersonid,
br.relationship,
br.relativename,
br.dob,
br.gender,
br.age,
br.occupation,
br.dateofjoin,
br.presentertypeid,
br.salutation,
br.prehousebuildname,
br.prestreetname,
br.prestatecode,
br.predistrictcode,
br.pretalukacode,
br.prehoblicode,
br.precityvillagecode,
br.prepincode,
br.ispresentaddresssameaspermanent ,
br.perstreetname,
br.perstatecode,
br.perdistrictcode,
br.pertalukacode,
br.perhoblicode,
br.percityvillagecode,
br.perpincode,
br.identityproofid,
br.identityproofidpath,br.addressproofid,
br.addressproofidpath,  
br.linkfirmpersonid,
 br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
join kaverimrg.firmreconstitution f on f.firmfinalregnumber=d.finalregistrationnumber 
where f.applicationnumber = _applicationnumber  and br.presentertypeid in (1,6)
	 order by firmpersonid)partnerdetails
) as partnerdetails,

	   --------------------------------
	   
	     (select array_to_json(array_agg(row_to_json(IncommingpartnerName)))
  from (select e.reconstitutionpartyid,
e.reconstitutionid,
e.firmpersonid,
e.firstname,
e.middlename,
e.lastname,
e.relationship,
e.relativename,
e.dob,
e.gender,
e.age,
e.occupation,
e.phoneno,
e.emailid,
e.dateofsease,
e.dateofjoin,
e.presentertypeid,
e.salutation,
e.prehousebuildname,
e.prestreetname,
e.prestatecode,
e.predistrictcode,
e.pretalukacode,
e.prehoblicode,
e.precityvillagecode,
e.prepincode,
e.ispresentaddresssameaspermanent ,
e.perstreetname,
e.perstatecode,
e.perdistrictcode,
e.pertalukacode,
e.perhoblicode,
e.percityvillagecode,
e.perpincode,
e.identityproof_idprooftypeid,
e.identityproofidpath ,
e.addressproof_idprooftypeid ,
e.addressproofidpath ,  
e.gpaagentpath,
e.proofofauthorisationfortheagentid,
e.proofofauthorisationfortheagentpath,
e.isincoming,
e.isoutgoing,
e.isnewentry,
e.linkfirmpersonid,
e.perhousebuildname||' '||e.perstreetname||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee
			||' '||
		stat.statenamee||'-'||e.perpincode as Address

		from kaverimrg.firmreconstitutionparty e
		inner join kaverimrg.firmreconstitution fa on e.reconstitutionid=fa.reconstitutionid
		left join kaverimrg.districtmaster di on e.perdistrictcode = di.districtcode
	    left join kaverimrg.talukmaster ta on e.pertalukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on e.perhoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on e.percityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
   where fa.applicationnumber =_applicationnumber and e.isincoming=true)IncommingpartnerName) as IncommingpartnerName,
	   
	   
	   	     (select array_to_json(array_agg(row_to_json(OutgoingpartnerName)))
  from (select 
  		e.reconstitutionpartyid,
e.reconstitutionid,
e.firmpersonid,
e.firstname,
e.middlename,
e.lastname,
e.relationship,
e.relativename,
e.dob,
e.gender,
e.age,
e.occupation,
e.phoneno,
e.emailid,
e.dateofsease,
e.dateofjoin,
e.presentertypeid,
e.salutation,
e.prehousebuildname,
e.prestreetname,
e.prestatecode,
e.predistrictcode,
e.pretalukacode,
e.prehoblicode,
e.precityvillagecode,
e.prepincode,
e.ispresentaddresssameaspermanent ,
e.perstreetname,
e.perstatecode,
e.perdistrictcode,
e.pertalukacode,
e.perhoblicode,
e.percityvillagecode,
e.perpincode,
e.identityproof_idprooftypeid,
e.identityproofidpath ,
e.addressproof_idprooftypeid ,
e.addressproofidpath ,  
e.gpaagentpath,
e.proofofauthorisationfortheagentid,
e.proofofauthorisationfortheagentpath,
e.isincoming,
e.isoutgoing,
e.isnewentry,
e.linkfirmpersonid,
e.perhousebuildname||' '||e.perstreetname||' '||di.districtnamee||' '||
ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee
			||' '||
		stat.statenamee||'-'||e.perpincode as Address
		from kaverimrg.firmreconstitutionparty e
		inner join kaverimrg.firmreconstitution fa on e.reconstitutionid=fa.reconstitutionid
		left join kaverimrg.districtmaster di on e.perdistrictcode = di.districtcode
	    left join kaverimrg.talukmaster ta on e.pertalukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on e.perhoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on e.percityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
   where fa.applicationnumber =_applicationnumber and e.isoutgoing=true)OutgoingpartnerName) as OutgoingpartnerName,
	   	 	   	
---------------	   
	   	   ( select array_to_json(array_agg(row_to_json(presenterdetils)))
from (select br.reconstitutionpartyid,
br.reconstitutionid,
br.firmpersonid,
br.firstname,
br.middlename,
br.lastname,
br.relationship,
br.relativename,
br.dob,
br.gender,
br.age,
br.occupation,
br.phoneno,
br.emailid,
br.dateofsease,
br.dateofjoin,
br.presentertypeid,
br.salutation,
br.prehousebuildname,
br.prestreetname,
br.prestatecode,
br.predistrictcode,
br.pretalukacode,
br.prehoblicode,
br.precityvillagecode,
br.prepincode,
br.ispresentaddresssameaspermanent ,
br.perstreetname,
br.perstatecode,
br.perdistrictcode,
br.pertalukacode,
br.perhoblicode,
br.percityvillagecode,
br.perpincode,
br.identityproof_idprooftypeid,
br.identityproofidpath ,
br.addressproof_idprooftypeid ,
br.addressproofidpath ,  
br.gpaagentpath,
br.proofofauthorisationfortheagentid,
br.proofofauthorisationfortheagentpath,

br.isincoming,
br.isoutgoing,
br.isnewentry,
br.linkfirmpersonid

from kaverimrg.firmreconstitutionparty  br
inner join kaverimrg.firmreconstitution fa on br.reconstitutionid=fa.reconstitutionid
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where fa.applicationnumber =_applicationnumber and br.presentertypeid in (1,2))presenterdetils) as presenterdetils,

( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT distinct ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid 
   FROM kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.firmreconstitution f ON f.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 48 
and ad.applicationnumber =_applicationnumber ) fdasdafetch) as fdasdafetch,


( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT distinct fr.feeruleid,fr.feedescription,fr.payableamount
   FROM kaverimrg.firmreconstitution f 
    left JOIN kaverimrg.firm_requiredfees fr  ON f.applicationnumber::text = fr.applicationnumber::text
   WHERE f.applicationnumber =_applicationnumber ) feesrequiredbyappl) as feesrequiredbyappl,
   
   ( select array_to_json(array_agg(row_to_json(remarks)))  from 
 ( SELECT distinct ar.firmdetailsremarks_fda_sda, 
ar.presenterdetailsremarks_fda_sda, 
ar.partnerdetailsremarks_fda_sda,
ar.witnessdetailsremarks_fda_sda,
ar.stampdutyandfeedetailsremarks_fda_sda,
ar.uploaddocumentremarks_fda_sda,
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.witnessdetailsremarks_dr,
ar.stampdutyandfeedetailsremarks_dr,
ar.canprocesstopaymentremarks_dr,
ar.uploaddocumentremarks_dr
   FROM 
    kaverimrg.firmreconstitution f 
    left join  kaverimrg.firmapplicationremarks ar  on f.applicationnumber::text = ar.applicationnumber::text
 WHERE f.applicationnumber =_applicationnumber
  ) remarks)as remarks


from kaverimrg.firmreconstitution fa  
inner join kaverimrg.districtmaster c on fa.drcode = c.districtcode
where fa.applicationnumber =_applicationnumber
	   
) data_json;
 	  
return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_reconstitution(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_review_marriage_details(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_review_marriage_details(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json 
from (select row_to_json(app_json)
from (select m.regsrocode as srocode,
			sm.sronamee as sroname,
			a.citizenid,
			a.applicationtypeid,
			to_char(m.applicationsubmit,'DD-MM-YYYY') as applicationsubmit,
			m.signedformpath,
			m.esignedsummarypath,
			m.currentstatus,--c.districtnamee,--c.drcode
(select array_to_json(array_agg(row_to_json(Marriagedetails))) 
from (select d.dateofmarriage::date as marriagedate,
      			d.districtcode,
      			d.talukacode,
      			d.hoblicode,
      			d.cityvillagecode,
      			d.statecode,
      			case when fun.statecode = 29 then
				coalesce(d.housebuildingname,'')||', '||coalesce(d.streetaddr,'')||', '||fun.districtnamee||', '||fun.taluknamee||', '||coalesce(fun.hoblinamee,'')||', '||coalesce(fun.villagenamee,'')||', '||INITCAP(fun.statenamee)||'-'||d.pincode
				else coalesce(d.housebuildingname,'')||', '||coalesce(d.streetaddr,'')||', '||INITCAP(fun.districtnamee)||', '||fun.taluknamee||', '||INITCAP(fun.statenamee)||'-'||d.pincode end as marriageaddress,
            	d.combinephotopath as Jointphotoofthebrideandbridegroom,
            	d.form_1path,
            	d.form_1apath,
            	d.marriageproofid,
				d.marriageproofpath,--d.intendedfilepath,
				d.bridegroomphoto,
				d.bridephoto,
				d.marriagemodeid,
				d.marriagetypeid,
				mm.marriagemode,
				mt.marriagetype,
				d.scannedform1path,
				d.numberofcopy
from kaverimrg.marriageregistration d join kaverimrg.mas_marriagemode mm on mm.marriagemodeid = d.marriagemodeid
									join kaverimrg.mas_marriagetype mt on mt.marriagetypeid = d.marriagetypeid
--									left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
--			                        left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
--			                        left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
--			                        left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
--			                        left join kaverimrg.statemaster stat on d.statecode = stat.statecode
									left JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(d.statecode, d.districtcode, d.talukacode, d.hoblicode, d.cityvillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON d.statecode = fun.statecode							
			 						where d.applicationnumber = _applicationnumber)Marriagedetails) as Marriageform,
			 						
(select array_to_json(array_agg(row_to_json(Bridegroom)))
from (select bg.personid,
			bg.salutation,
			s.descriptione as salutation,
			bg.firstname,
			bg.middlename,
			bg.lastname,
			bg.age,
			bg.perdistrictcode,
			bg.pertalukacode,
			bg.perhoblicode,
			bg.percityvillagecode,
			bg.predistrictcode,
			bg.pretalukacode,
			bg.prehoblicode,
			bg.precityvillagecode,--bg.statecode,
			case when fun.statecode = 29 then
			coalesce(bg.perhousebuildname,'')||', '||coalesce(bg.perstreetname,'')||', '||fun.districtnamee||', '||fun.taluknamee||', '||coalesce(fun.hoblinamee,'')||', '||coalesce(fun.villagenamee,'')||', '||INITCAP(fun.statenamee)||'-'||bg.perpincode 
			else coalesce(bg.perhousebuildname)||', '||coalesce(bg.perstreetname,'')||', '||INITCAP(fun.districtnamee)||', '||fun.taluknamee||', '||INITCAP(fun.statenamee)||'-'||bg.perpincode end as permanentaddress,  
			case when fun1.statecode = 29 then 
            coalesce(bg.prehousebuildname,'')||', '||coalesce(bg.prestreetname,'')||', '||fun1.districtnamee||', '||fun1.taluknamee||', '||coalesce(fun1.hoblinamee,'')||', '||coalesce(fun1.villagenamee,'')||', '||INITCAP(fun1.statenamee)||'-'||bg.prepincode
            else coalesce(bg.prehousebuildname,'')||', '||coalesce(bg.prestreetname,'')||', '||INITCAP(fun1.districtnamee)||', '||fun1.taluknamee||', '||INITCAP(fun1.statenamee)||'-'||bg.prepincode end as currentaddress,--,bg.currentpincode,bg.status,
			bg.dob as dateofbirth,
			bg.phoneno as phonenumber,
			s.descriptione as salutation,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
			where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as fathersalutation,
			coalesce(bg.fatherfirstname,'')||' '||coalesce(bg.fathermiddlename,'')||' '||coalesce(bg.fatherlastname,'') as fathername,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
			where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as mothersalutation,
			coalesce(bg.motherfirstname,'')||' '||coalesce(bg.mothermiddlename,'')||' '||coalesce(bg.motherlastname,'') as mothername,--bg.durationin,
			bg.occupation,
			bg.deathcertificateid,
			bg.deathcertificatefilepath,
			bg.divorcecertificateid,
			bg.divorcecertificatefilepath,
			bg.identityproofid,bg.email,
			bg.identityprooffilepath,
			bg.ageproofid,
			bg.ageprooffilepath,
			bg.addressproofid,
			bg.addressprooffilepath,
			bg.durationofstayproofpath,
			mb.description as status
		from kaverimrg.persondetails bg left join kaverimrg.mas_marriagebeforestatus mb on mb.statusid =bg.statusid
									left join kaverimrg.districtmaster distper on bg.perdistrictcode = distper.districtcode 
--			                        left join kaverimrg.talukmaster talper on bg.pertalukacode = talper.talukcode 
--			                        left join kaverimrg.hoblimaster hobper on bg.perhoblicode = hobper.hoblicode 
--			                        left join kaverimrg.villagemaster vilper on bg.percityvillagecode = vilper.villagecode
--                                  left join kaverimrg.districtmaster distcur on bg.perdistrictcode = distcur.districtcode 
--			                        left join kaverimrg.talukmaster talcur on bg.pertalukacode = talcur.talukcode 
--			                        left join kaverimrg.hoblimaster hobcur on bg.perhoblicode = hobcur.hoblicode 
--			                        left join kaverimrg.villagemaster vilcur on bg.percityvillagecode = vilcur.villagecode  
--                                  left join kaverimrg.statemaster stat on bg.perstatecode = stat.statecode
								 	join kaverimrg.salutationmaster s on bg.salutation = s.salutationid
									left JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(bg.perstatecode, bg.perdistrictcode, bg.pertalukacode, bg.perhoblicode, bg.percityvillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON bg.perstatecode = fun.statecode
     								left JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(bg.prestatecode, bg.predistrictcode, bg.pretalukacode, bg.prehoblicode, bg.precityvillagecode::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON bg.prestatecode = fun1.statecode
									where bg.sex = 'M' and bg.applicationnumber = _applicationnumber)Bridegroom) as bridegroom,
									
(select array_to_json(array_agg(row_to_json(Bride)))
from(select br.personid,
			br.salutation,
			s.descriptione as salutation,
			br.firstname,
			br.middlename,
			br.lastname,
			br.age,--br.permanentaddress,br.presentaddress,
			br.perdistrictcode,
			br.pertalukacode,
			br.perhoblicode,
			br.percityvillagecode,
			br.predistrictcode,
			br.pretalukacode,
			br.prehoblicode,
			br.precityvillagecode,
			case when fun.statecode = 29 then
			coalesce(br.perhousebuildname,'')||', '||coalesce(br.perstreetname,'')||', '||fun.districtnamee||', '||fun.taluknamee||', '||coalesce(fun.hoblinamee,'')||', '||coalesce(fun.villagenamee,'')||', '||INITCAP(fun.statenamee)||'-'||br.perpincode 
			else coalesce(br.perhousebuildname,'')||', '||coalesce(br.perstreetname,'')||', '||INITCAP(fun.districtnamee)||', '||fun.taluknamee||', '||INITCAP(fun.statenamee)||'-'||br.perpincode end as permanentaddress,
            case when fun1.statecode = 29 then 
            coalesce(br.prehousebuildname,'')||', '||coalesce(br.prestreetname,'')||', '||fun1.districtnamee||', '||fun1.taluknamee||', '||coalesce(fun1.hoblinamee,'')||', '||coalesce(fun1.villagenamee,'')||', '||INITCAP(fun1.statenamee)||'-'||br.prepincode
            else coalesce(br.prehousebuildname,'')||', '||coalesce(br.prestreetname,'')||', '||INITCAP(fun1.districtnamee)||', '||fun1.taluknamee||', '||INITCAP(fun1.statenamee)||'-'||br.prepincode end as currentaddress,--br.status,
			br.dob as dateofbirth,
			br.phoneno as phonenumber,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
			where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as fathersalutation,
			coalesce(br.fatherfirstname,'')||' '||coalesce(br.fathermiddlename,'')||' '||coalesce(br.fatherlastname,'')  as fathername,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
			where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as mothersalutation,
			coalesce(br.motherfirstname,'')||' '||coalesce(br.mothermiddlename,'')||' '||coalesce(br.motherlastname,'')  as mothername,--br.durationin,
			br.occupation,
			br.deathcertificateid,
			br.deathcertificatefilepath,
			br.divorcecertificateid,
			br.divorcecertificatefilepath,
			br.identityproofid,
			br.email,
			br.identityprooffilepath,
			br.ageproofid,
			br.ageprooffilepath,
			br.addressproofid,
			br.addressprooffilepath,
			br.durationofstayproofpath,
			mb.description as status
			from kaverimrg.persondetails br left join kaverimrg.mas_marriagebeforestatus mb on mb.statusid =br.statusid
--									left join kaverimrg.districtmaster distper on br.perdistrictcode = distper.districtcode 
--			                        left join kaverimrg.talukmaster talper on br.pertalukacode = talper.talukcode 
--			                        left join kaverimrg.hoblimaster hobper on br.perhoblicode = hobper.hoblicode 
--			                        left join kaverimrg.villagemaster vilper on br.percityvillagecode = vilper.villagecode
--                                  left join kaverimrg.districtmaster distcur on br.predistrictcode = distcur.districtcode 
--			                        left join kaverimrg.talukmaster talcur on br.pretalukacode = talcur.talukcode 
--			                        left join kaverimrg.hoblimaster hobcur on br.prehoblicode = hobcur.hoblicode 
--			                        left join kaverimrg.villagemaster vilcur on br.precityvillagecode = vilcur.villagecode  
--                                  left join kaverimrg.statemaster stat on br.perstatecode = stat.statecode
									left join kaverimrg.salutationmaster s on br.salutation = s.salutationid
									left JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(br.perstatecode, br.perdistrictcode, br.pertalukacode, br.perhoblicode, br.percityvillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON br.perstatecode = fun.statecode
     								left JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(br.prestatecode, br.predistrictcode, br.pretalukacode, br.prehoblicode, br.precityvillagecode::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON br.prestatecode = fun1.statecode
									where br.sex = 'F' and br.applicationnumber = _applicationnumber)Bride) as bride,
									
									
(select array_to_json(array_agg(row_to_json(witness)))
from (select e.witnessid,
			e.salutation,
			s.descriptione as salutation,
			coalesce(e.firstname,null) as firstname,
			coalesce(e.middlename,'') as middlename,
			coalesce(e.lastname,'') as lastname,
			e.age,
			--a.presentaddress,a.permanentaddress,
			e.perdistrictcode,
			e.pertalukacode,
			e.perhoblicode,
			e.pervillagecode,
			coalesce(e.perhouseno,'')||', '||coalesce(e.perstreetaddress,'')||', '||INITCAP(distper.districtnamee)||', '||talper.taluknamee||', '||INITCAP(stat.statenamee)||'-'||perpincode as permanentaddress,
            coalesce(e.currenthouseno,'')||', '||coalesce(e.currentstreetaddress,'')||', '||INITCAP(distcur.districtnamee)||', '||talcur.taluknamee||', '||INITCAP(statcur.statenamee)||'-'||e.currentpincode as currentaddress,
--			case when fun.statecode = 29 then
--			coalesce(e.perhouseno,'')||' '||coalesce(e.perstreetaddress,'')||' '||fun.districtnamee||' '||fun.taluknamee||' '||fun.hoblinamee||' '||fun.villagenamee||' '||INITCAP(fun.statenamee)||'-'||perpincode
--			else coalesce(e.perhouseno,'')||' '||coalesce(e.perstreetaddress,'')||' '||INITCAP(fun.districtnamee)||' '||fun.taluknamee||' '||INITCAP(fun.statenamee)||'-'||perpincode end as permanentaddress,
--			case when fun1.statecode = 29 then
--          coalesce(e.currenthouseno,'')||' '||coalesce(e.currentstreetaddress,'')||' '||fun1.districtnamee||' '||fun1.taluknamee||' '||fun1.hoblinamee||' '||fun1.villagenamee||' '||INITCAP(fun1.statenamee)||'-'||e.currentpincode
--           else coalesce(e.currenthouseno,'')||' '||coalesce(e.currentstreetaddress,'')||' '||INITCAP(fun1.districtnamee)||' '||fun1.taluknamee||' '||INITCAP(fun1.statenamee)||'-'||e.currentpincode end as currentaddress,
			--case when a.sex = 'M'  then
			-- a.bridegroomrelation 
			----z.relationname
			--when a.sex = 'F' then
			-- a.briderelation end as relation ,
			-- case when z.persontypeid = 1  then
			--'Bride Groom'
			----z.relationname
			--when a.persontypeid = 2 then
			-- 'Bride' end as relation,
			--z.relationname end as relation,
             z.relationname as relation,
			 mp.persontypename as witnessrelatedto,
			 e.dob,
			 e.email,
			 e.phoneno,
			 g.descriptione as gender
	from kaverimrg.marriagewitnessinfo e left join kaverimrg.gendermaster g on g.genderid = e.genderid
									left join kaverimrg.marriagewitnessrelationmaster z on z.relationid = e.relationid --and
									inner join kaverimrg.marriageregistration mr on mr.applicationnumber = e.applicationnumber
									join kaverimrg.mas_persontype mp on mp.persontypeid = e.witnessrelatedto
                        			join kaverimrg.lgd_districtmaster distper on e.perdistrictcode = distper.districtcode 
			                        join kaverimrg.lgd_talukmaster talper on e.pertalukacode = talper.talukcode 
--			                        left join kaverimrg.hoblimaster hobper on e.perhoblicode = hobper.hoblicode 
--			                        left join kaverimrg.villagemaster vilper on e.pervillagecode = vilper.villagecode
                                    join kaverimrg.lgd_districtmaster distcur on e.currentdistrictcode = distcur.districtcode 
			                        join kaverimrg.lgd_talukmaster talcur on e.currenttalukacode = talcur.talukcode 
--			                        left join kaverimrg.hoblimaster hobcur on e.currenthoblicode = hobcur.hoblicode 
--			                        left join kaverimrg.villagemaster vilcur on e.currentvillagecode = vilcur.villagecode
			                        join kaverimrg.lgd_statemaster stat on e.perstatecode = stat.statecode
			                        join kaverimrg.lgd_statemaster statcur on e.currrentstatecode = statcur.statecode
--									JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(e.perstatecode, e.perdistrictcode, e.pertalukacode, e.perhoblicode, e.pervillagecode::bigint) fun(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON e.perstatecode = fun.statecode
--     								JOIN LATERAL kaverimrg.fn_fetch_marriage_lgdmaster1(e.currrentstatecode, e.currentdistrictcode, e.currenttalukacode, e.currenthoblicode, e.currentvillagecode::bigint) fun1(statecode, statenamee, districtcode, districtnamee, talukcode, taluknamee, hoblicode, hoblinamee, villagecode, villagenamee) ON e.currrentstatecode = fun1.statecode
									join kaverimrg.salutationmaster s on e.salutation = s.salutationid
							where e.applicationnumber = _applicationnumber order by e.witnessid asc )witness) as witness,
							
							
(select array_to_json(array_agg(row_to_json(VerificationDetails)))
from (select ar.verificationid,
			ar.marriagedetailsremarks_fda,
			ar.bridegroomdetailsremarks_fda,
			ar.bridedetailsremarks_fda,
			ar.witnessdetailsremarks_fda,
			ar.marriagedetailsremarks_sr,
			ar.bridegroomdetailsremarks_sr,
			ar.bridedetailsremarks_sr,
			ar.witnessdetailsremarks_sr,
			ar.canpreocesstopaymentremarks_sr,
			ar.marriagedetailsremarks_deo,
			ar.bridegroomdetailsremarks_deo,
			ar.bridedetailsremarks_deo,
			ar.witnessdetailsremarks_deo
from kaverimrg.marriageapplicationremarks ar where ar.applicationnumber = _applicationnumber )VerificationDetails) as VerificationRemarks
 				
from kaverimrg.marriageregistration m 
 			left join kaverimrg.applicantapplicationdetails a on m.applicationnumber = a.applicationnumber
 			join kaverimrg.sromaster sm on m.regsrocode = sm.srocode
 			--JOIN kaverimrg.villagemaster v ON v.villagecode = a.percityvillagecode
 			--JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
			--inner join kaverimrg.districtmaster c on sm.districtcode = c.districtcode     	
			where m.applicationnumber = _applicationnumber
		)app_json) data_json;
	return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_review_marriage_details(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_review_marriage_details_1(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_review_marriage_details_1(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json /*( select
  array_to_json(array_agg(row_to_json(app_json)))*/
  from (select row_to_json(app_json) 
 from ( select  a.srocode,
 				b.sronamee,
 				a.drcode,
 				c.districtnamee,
 (select array_to_json(array_agg(row_to_json(Marriagedetails)))
      from (select to_char(d.dateofmarriage::date,'DD-MM-YYYY' ) as marriagedate,
      				d.districtcode,
      				d.talukacode,
      				d.hoblicode,
      				d.cityvillagecode,
      				d.statecode,
					concat(coalesce(d.housebuildingname,''),', ',d.streetaddr,', ',di.districtnamee,', ',ta.taluknamee,', ',ho.hoblinamee,', ',vill.villagenamee,', ',stat.statenamee||'-'||d.pincode) as marriageaddress,
            		d.combinephotopath as Jointphotoofthebrideandbridegroom,
            		d.form_1path,
            		d.form_1apath,
            		d.marriageproofid,
					d.marriageproofpath,
					d.intendedfilepath,
					d.bridegroomphoto,
					d.bridephoto,
					d.marriagemodeid,
					d.marriagetypeid
			from kaverimrg.marriageregistration d left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
			                       left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
			                       left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
			                       left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
			                       left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.applicationnumber = a.applicationnumber and 
			  d.applicationnumber = _applicationnumber
		   )Marriagedetails) as Marriageform,
		  								 
(select array_to_json(array_agg(row_to_json(Bride)))
      from (select br.personid,
      				br.salutation,
      				s.descriptione as salutation,
      				br.firstname,
      				br.middlename,
      				br.lastname,
      				br.age,--br.permanentaddress,br.presentaddress,
					br.perdistrictcode,
					br.pertalukacode,
					br.perhoblicode,
					br.percityvillagecode,
					br.predistrictcode,
					br.pretalukacode,
					br.prehoblicode,
					br.precityvillagecode,
					concat(coalesce(br.perhousebuildname,''),', ',coalesce(br.perstreetname,''),', ',distper.districtnamee,', ',talper.taluknamee,', ',hobper.hoblinamee,', ',vilper.villagenamee,', ',s.statenamee||'-'||br.perpincode) as permanentaddress,
                    concat(coalesce(br.prehousebuildname,''),', ',coalesce(br.prestreetname,''),', ',distcur.districtnamee,', ',talcur.taluknamee,', ',hobcur.hoblinamee,', ',vilcur.villagenamee,', ',s.statenamee||'-'||br.prepincode) as currentaddress,
					br.status,
					to_char(br.dob::date,'DD-MM-YYYY') as dateofbirth,
					br.phoneno as phonenumber,
					(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
					where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as fathersalutation,
					coalesce(br.fatherfirstname,'')||' '||coalesce(br.fathermiddlename,'')||' '||coalesce(br.fatherlastname,'')  as fathername,
					(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
					where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as mothersalutation,
					coalesce(br.motherfirstname,'')||' '||coalesce(br.mothermiddlename,'')||' '||coalesce(br.motherlastname,'')  as mothername,
					br.durationin,
					br.occupation,
					br.deathcertificateid,
					br.deathcertificatefilepath,
					br.divorcecertificateid,
					br.divorcecertificatefilepath,
					br.identityproofid,
					br.email,
					br.identityprooffilepath,
					br.ageproofid,
					br.ageprooffilepath,
					br.addressproofid,
					br.addressprooffilepath,
					br.durationofstayproofpath
			   from kaverimrg.persondetails br left join kaverimrg.districtmaster distper on br.perdistrictcode = distper.districtcode 
			                                left join kaverimrg.talukmaster talper on br.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on br.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on br.percityvillagecode = vilper.villagecode
                                            left join kaverimrg.districtmaster distcur on br.predistrictcode = distcur.districtcode 
			                                left join kaverimrg.talukmaster talcur on br.pretalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on br.prehoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on br.precityvillagecode = vilcur.villagecode  
                                            left join kaverimrg.statemaster s on br.statecode = s.statecode
											left join kaverimrg.salutationmaster s on br.salutation = s.salutationid and br.mothersalutation = s.salutationid and br.fathersalutation= s.salutationid
											where br.sex = 'F' and br.applicationnumber = a.applicationnumber
		  									and br.applicationnumber = _applicationnumber)Bride) as bride,

(select array_to_json(array_agg(row_to_json(Bridegroom)))
      from (select bg.personid,
      				bg.salutation,
      				s.descriptione as salutation,
      				bg.firstname,
      				bg.middlename,
      				bg.lastname,
      				bg.age,
					bg.perdistrictcode,
					bg.pertalukacode,
					bg.perhoblicode,
					bg.percityvillagecode,
					bg.predistrictcode,
					bg.pretalukacode,
					bg.prehoblicode,
					bg.precityvillagecode,--bg.statecode,
					concat(coalesce(bg.perhousebuildname,''),', ',bg.perstreetname,', ',distper.districtnamee,', ',talper.taluknamee,', ',hobper.hoblinamee,', ',vilper.villagenamee,', ',s.statenamee||'-'||bg.perpincode) as permanentaddress,
                    concat(coalesce(bg.prehousebuildname,''),', ',bg.prestreetname,', ',distcur.districtnamee,', ',talcur.taluknamee,', ',hobcur.hoblinamee,', ',vilcur.villagenamee,', ',s.statenamee||'-'||bg.prepincode) as currentaddress,--,bg.currentpincode,
					bg.status,
					bg.dob as dateofbirth,
					bg.phoneno as phonenumber,
					s.descriptione as salutation,
					(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
					where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as fathersalutation,
					coalesce(bg.fatherfirstname,'')||' '||coalesce(bg.fathermiddlename,'')||' '||coalesce(bg.fatherlastname,'') as fathername,
					(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
					where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as mothersalutation,
					bg.motherfirstname||' '||coalesce(bg.mothermiddlename,'')||''||bg.motherlastname as mothername,
					bg.durationin,
					bg.occupation,
					bg.deathcertificateid,
					bg.deathcertificatefilepath,
					bg.divorcecertificateid,
					bg.divorcecertificatefilepath,
					bg.identityproofid,
					bg.email,
					bg.identityprooffilepath,
					bg.ageproofid,
					bg.ageprooffilepath,
					bg.addressproofid,
					bg.addressprooffilepath,
					bg.durationofstayproofpath
			from kaverimrg.persondetails bg left join kaverimrg.districtmaster distper on bg.perdistrictcode = distper.districtcode 
			                             left join kaverimrg.talukmaster talper on bg.pertalukacode = talper.talukcode 
			                             left join kaverimrg.hoblimaster hobper on bg.perhoblicode = hobper.hoblicode 
			                             left join kaverimrg.villagemaster vilper on bg.percityvillagecode = vilper.villagecode
                                         left join kaverimrg.districtmaster distcur on bg.perdistrictcode = distcur.districtcode 
			                             left join kaverimrg.talukmaster talcur on bg.pertalukacode = talcur.talukcode 
			                             left join kaverimrg.hoblimaster hobcur on bg.perhoblicode = hobcur.hoblicode 
			                             left join kaverimrg.villagemaster vilcur on bg.percityvillagecode = vilcur.villagecode  
                                         left join kaverimrg.statemaster s on bg.statecode = s.statecode
										 left join kaverimrg.salutationmaster s on bg.salutation = s.salutationid and bg.fathersalutation= s.salutationid
										 where bg.sex = 'M' and bg.applicationnumber = a.applicationnumber
		  								 and bg.applicationnumber = _applicationnumber)Bridegroom) as bridegroom,		  									

(select array_to_json(array_agg(row_to_json(witness)))
      from (select  e.witnessid,
      				e.salutation,
     				s.descriptione as salutation,
     				coalesce(e.firstname,null) as firstname,
     				coalesce(e.middlename,'') as middlename,
     				coalesce(e.lastname,'') as lastname,
     				e.age,
					--a.presentaddress,
					--a.permanentaddress,
					e.perdistrictcode,
					e.pertalukacode,
					e.perhoblicode,
					e.pervillagecode,
					concat(coalesce(e.perhouseno,''),', ',coalesce(e.perstreetaddress,''),', ',distper.districtnamee,', ',talper.taluknamee,', ',hobper.hoblinamee,', ',vilper.villagenamee,', ',s.statenamee||'-'||perpincode) as permanentaddress,
                    concat(coalesce(e.currenthouseno,''),', ',e.currentstreetaddress,', ',distcur.districtnamee,', ',talcur.taluknamee,', ',hobcur.hoblinamee,', ',vilcur.villagenamee,', ',s.statenamee||'-'||e.currentpincode) as currentaddress,
					case when sex = 'M'  then
 					--a.bridegroomrelation 
					z.relationname
					when sex = 'F' then
 					--a.briderelation end as relation 
					z.relationname end as relation,
					e.witnessrelatedto,
					e.dob,
					e.email,
					e.phoneno
			from kaverimrg.marriagewitnessinfo e  
						left join kaverimrg.marriagewitnessrelationmaster z on z.relationid = e.relationid and e.applicationnumber = a.applicationnumber and e.srocode = a.srocode 
                        left join kaverimrg.districtmaster distper on e.perdistrictcode = distper.districtcode 
			            left join kaverimrg.talukmaster talper on e.pertalukacode = talper.talukcode 
			            left join kaverimrg.hoblimaster hobper on e.perhoblicode = hobper.hoblicode 
			            left join kaverimrg.villagemaster vilper on e.pervillagecode = vilper.villagecode
                        left join kaverimrg.districtmaster distcur on e.currentdistrictcode = distcur.districtcode 
			            left join kaverimrg.talukmaster talcur on e.currenttalukacode = talcur.talukcode 
			            left join kaverimrg.hoblimaster hobcur on e.currenthoblicode = hobcur.hoblicode 
			            left join kaverimrg.villagemaster vilcur on e.currentvillagecode = vilcur.villagecode
						left join kaverimrg.salutationmaster s on e.salutation = s.salutationid
						left join kaverimrg.statemaster s on e.statecode = s.statecode
						where e.applicationnumber = _applicationnumber)witness) as witness,
						
(select array_to_json(array_agg(row_to_json(VerificationDetails)))
      from (select ar.verificationid,
      				ar.marriagedetailsremarks_fda,
      				ar.bridegroomdetailsremarks_fda,
					ar.bridedetailsremarks_fda,
					ar.witnessdetailsremarks_fda,
					ar.marriagedetailsremarks_sr,
					ar.bridegroomdetailsremarks_sr,
					ar.bridedetailsremarks_sr,
					ar.witnessdetailsremarks_sr,
					ar.canpreocesstopaymentremarks_sr
			from kaverimrg.marriageapplicationremarks ar where ar.applicationnumber = a.applicationnumber 
			and ar.applicationnumber = _applicationnumber)VerificationDetails) as VerificationRemarks	   
 	from kaverimrg.persondetails a inner join kaverimrg.sromaster b on a.srocode = b.srocode 
	inner join kaverimrg.districtmaster c on b.districtcode = c.districtcode
where a.applicationnumber = _applicationnumber) app_json ) data_json;
/*update kaverimrg.marriageregistration set   numberofcopy=_numberofcopy,
 declarationdate=current_timestamp,
 declarationplace=_declarationplace where applicationnumber = _applicationnumber;*/
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_review_marriage_details_1(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_review_marriage_details_160623(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_review_marriage_details_160623(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json /*( select
  array_to_json(array_agg(row_to_json(app_json)))*/
  from (select row_to_json(app_json) 
 from (select m.regsrocode as srocode,sm.sronamee as sroname,a.citizenid,--c.districtnamee,--c.drcode
 ( select array_to_json(array_agg(row_to_json(Marriagedetails)))
      from (select d.dateofmarriage::date as marriagedate,d.districtcode,d.talukacode,d.hoblicode,d.cityvillagecode,d.statecode,
			d.housebuildingname||' '||d.streetaddr||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||INITCAP(stat.statenamee)||'-'||d.pincode as marriageaddress,
            d.combinephotopath as Jointphotoofthebrideandbridegroom,d.form_1path,d.form_1apath,d.marriageproofid,
			d.marriageproofpath,--d.intendedfilepath,
			d.bridegroomphoto,d.bridephoto,d.marriagemodeid,d.marriagetypeid,mm.marriagemode,mt.marriagetype,d.scannedform1path
			
from kaverimrg.marriageregistration d join kaverimrg.mas_marriagemode mm on mm.marriagemodeid = d.marriagemodeid
									join kaverimrg.mas_marriagetype mt on mt.marriagetypeid = d.marriagetypeid
									left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
			                       left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
			                       left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
			                       left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
			                       left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where --d.applicationnumber = a.applicationnumber and 
			  d.applicationnumber = _applicationnumber
		   )Marriagedetails) as Marriageform,
( select array_to_json(array_agg(row_to_json(Bridegroom)))
      from ( select bg.personid,bg.salutation,s.descriptione as salutation,bg.firstname,bg.middlename,bg.lastname,bg.age,
bg.perdistrictcode,bg.pertalukacode,bg.perhoblicode,bg.percityvillagecode,bg.predistrictcode,bg.pretalukacode,bg.prehoblicode,bg.precityvillagecode,--bg.statecode,
			bg.perhousebuildname||' '||bg.perstreetname||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||' '||INITCAP(stat.statenamee)||'-'||bg.perpincode as permanentaddress,
                        bg.prehousebuildname||' '||bg.prestreetname||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||' '||INITCAP(stat.statenamee)||'-'||bg.prepincode as currentaddress,--,bg.currentpincode,
--bg.status,
bg.dob as dateofbirth,bg.phoneno as phonenumber,s.descriptione as salutation,(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as fathersalutation,
coalesce(bg.fatherfirstname,'')||' '||coalesce(bg.fathermiddlename,'')||' '||coalesce(bg.fatherlastname,'') as fathername,
(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as mothersalutation,
bg.motherfirstname||' '||coalesce(bg.mothermiddlename,'')||' '||bg.motherlastname as mothername,--bg.durationin,
bg.occupation,
bg.deathcertificateid,bg.deathcertificatefilepath,bg.divorcecertificateid,bg.divorcecertificatefilepath,bg.identityproofid,bg.email,
bg.identityprooffilepath,bg.ageproofid,bg.ageprooffilepath,bg.addressproofid,bg.addressprooffilepath,bg.durationofstayproofpath,mb.description as status
			from kaverimrg.persondetails bg left join kaverimrg.mas_marriagebeforestatus mb on mb.statusid =bg.statusid
											left join kaverimrg.districtmaster distper on bg.perdistrictcode = distper.districtcode 
			                              left join kaverimrg.talukmaster talper on bg.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on bg.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on bg.percityvillagecode = vilper.villagecode
                                                       left join kaverimrg.districtmaster distcur on bg.perdistrictcode = distcur.districtcode 
			                              left join kaverimrg.talukmaster talcur on bg.pertalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on bg.perhoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on bg.percityvillagecode = vilcur.villagecode  
                                                        left join kaverimrg.statemaster stat on bg.perstatecode = stat.statecode
left join kaverimrg.salutationmaster s on bg.salutation = s.salutationid 
			where bg.sex = 'M'-- and bg.applicationnumber = a.applicationnumber
		  and bg.applicationnumber = _applicationnumber
		   )Bridegroom) as bridegroom,
( select array_to_json(array_agg(row_to_json(Bride)))
      from ( select br.personid,br.salutation,s.descriptione as salutation,br.firstname,br.middlename,br.lastname,br.age,--br.permanentaddress,br.presentaddress,
br.perdistrictcode,br.pertalukacode,br.perhoblicode,br.percityvillagecode,br.predistrictcode,br.pretalukacode,br.prehoblicode,br.precityvillagecode,
			coalesce(br.perhousebuildname,'')||' '||coalesce(br.perstreetname,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||' '||INITCAP(stat.statenamee)||'-'||br.perpincode as permanentaddress,
             coalesce(br.prehousebuildname,'')||' '||coalesce(br.prestreetname,'')||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||' '||INITCAP(stat.statenamee)||'-'||br.prepincode as currentaddress,
--br.status,
br.dob as dateofbirth,br.phoneno as phonenumber,(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as fathersalutation,coalesce(br.fatherfirstname,'')||' '||coalesce(br.fathermiddlename,'')||' '||coalesce(br.fatherlastname,'')  as fathername,
(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as mothersalutation,coalesce(br.motherfirstname,'')||' '||coalesce(br.mothermiddlename,'')||' '||coalesce(br.motherlastname,'')  as mothername,--br.durationin,
br.occupation,
br.deathcertificateid,br.deathcertificatefilepath,br.divorcecertificateid,br.divorcecertificatefilepath,br.identityproofid,br.email,
br.identityprooffilepath,br.ageproofid,br.ageprooffilepath,br.addressproofid,br.addressprooffilepath,br.durationofstayproofpath,mb.description as status
from kaverimrg.persondetails br left join kaverimrg.mas_marriagebeforestatus mb on mb.statusid =br.statusid
										left join kaverimrg.districtmaster distper on br.perdistrictcode = distper.districtcode 
			                              left join kaverimrg.talukmaster talper on br.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on br.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on br.percityvillagecode = vilper.villagecode
                                                       left join kaverimrg.districtmaster distcur on br.predistrictcode = distcur.districtcode 
			                              left join kaverimrg.talukmaster talcur on br.pretalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on br.prehoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on br.precityvillagecode = vilcur.villagecode  
                                                        left join kaverimrg.statemaster stat on br.perstatecode = stat.statecode
left join kaverimrg.salutationmaster s on br.salutation = s.salutationid
where br.sex = 'F'-- and br.applicationnumber = a.applicationnumber
		  and br.applicationnumber = _applicationnumber 
		   )Bride) as bride,
( select array_to_json(array_agg(row_to_json(witness)))
      from (select  e.witnessid,e.salutation,s.descriptione as salutation,coalesce(e.firstname,null) as firstname,coalesce(e.middlename,'') as middlename,coalesce(e.lastname,'') as lastname,e.age,
--a.presentaddress,a.permanentaddress,
e.perdistrictcode,e.pertalukacode,e.perhoblicode,e.pervillagecode,
			coalesce(e.perhouseno,'')||coalesce(e.perstreetaddress,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||' '||INITCAP(stat.statenamee)||'-'||perpincode as permanentaddress,
            coalesce(e.currenthouseno,'')||coalesce(e.currentstreetaddress,'')||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||' '||INITCAP(stat.statenamee)||'-'||e.currentpincode as currentaddress,
--case when a.sex = 'M'  then
-- a.bridegroomrelation 
----z.relationname
--when a.sex = 'F' then
-- a.briderelation end as relation ,
-- case when z.persontypeid = 1  then
--'Bride Groom'
----z.relationname
--when a.persontypeid = 2 then
-- 'Bride' end as relation,
--z.relationname end as relation,
                        z.relationname as relation,
			mp.persontypename as witnessrelatedto,e.dob,e.email,e.phoneno,g.descriptione as gender
			from		
kaverimrg.marriagewitnessinfo e
			left join kaverimrg.gendermaster g on g.genderid = e.genderid
			left join kaverimrg.marriagewitnessrelationmaster z on z.relationid = e.relationid --and
			inner join kaverimrg.marriageregistration mr on mr.applicationnumber = e.applicationnumber
			left join kaverimrg.mas_persontype mp on mp.persontypeid = e.witnessrelatedto
			--e.applicationnumber = a.applicationnumber 
			--and e.srocode = sm.srocode 
                        left join kaverimrg.districtmaster distper on e.perdistrictcode = distper.districtcode 
			                              left join kaverimrg.talukmaster talper on e.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on e.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on e.pervillagecode = vilper.villagecode
                                                       left join kaverimrg.districtmaster distcur on e.currentdistrictcode = distcur.districtcode 
			                              left join kaverimrg.talukmaster talcur on e.currenttalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on e.currenthoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on e.currentvillagecode = vilcur.villagecode
			                                left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
left join kaverimrg.salutationmaster s on e.salutation = s.salutationid
			where e.applicationnumber = _applicationnumber order by e.witnessid asc
 )witness) as witness,
( select array_to_json(array_agg(row_to_json(VerificationDetails)))
      from (select ar.verificationid,ar.marriagedetailsremarks_fda,ar.bridegroomdetailsremarks_fda,
			ar.bridedetailsremarks_fda,ar.witnessdetailsremarks_fda,ar.marriagedetailsremarks_sr,
			ar.bridegroomdetailsremarks_sr,ar.bridedetailsremarks_sr,ar.witnessdetailsremarks_sr,
			ar.canpreocesstopaymentremarks_sr
			
from kaverimrg.marriageapplicationremarks ar where --ar.applicationnumber = a.applicationnumber and 
			  ar.applicationnumber = _applicationnumber
		   )VerificationDetails) as VerificationRemarks
 				from kaverimrg.marriageregistration m 
 				left join kaverimrg.applicantapplicationdetails a on m.applicationnumber = a.applicationnumber
 				join kaverimrg.sromaster sm on m.regsrocode = sm.srocode
 				--JOIN kaverimrg.villagemaster v ON v.villagecode = a.percityvillagecode
 				--JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
				--inner join kaverimrg.districtmaster c on sm.districtcode = c.districtcode     	
where m.applicationnumber = _applicationnumber
)app_json) data_json;
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_review_marriage_details_160623(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_review_marriage_details_200623(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_review_marriage_details_200623(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
begin
select row_to_json(data_json) into v_data_json 
from (select row_to_json(app_json)
from (select m.regsrocode as srocode,
			sm.sronamee as sroname,
			a.citizenid,--c.districtnamee,--c.drcode
(select array_to_json(array_agg(row_to_json(Marriagedetails))) 
from (select d.dateofmarriage::date as marriagedate,
      			d.districtcode,
      			d.talukacode,
      			d.hoblicode,
      			d.cityvillagecode,
      			d.statecode,
				d.housebuildingname||' '||d.streetaddr||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||INITCAP(stat.statenamee)||'-'||d.pincode as marriageaddress,
            	d.combinephotopath as Jointphotoofthebrideandbridegroom,
            	d.form_1path,
            	d.form_1apath,
            	d.marriageproofid,
				d.marriageproofpath,--d.intendedfilepath,
				d.bridegroomphoto,
				d.bridephoto,
				d.marriagemodeid,
				d.marriagetypeid,
				mm.marriagemode,
				mt.marriagetype,
				d.scannedform1path		
from kaverimrg.marriageregistration d join kaverimrg.mas_marriagemode mm on mm.marriagemodeid = d.marriagemodeid
									join kaverimrg.mas_marriagetype mt on mt.marriagetypeid = d.marriagetypeid
									left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
			                        left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
			                        left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
			                        left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
			                        left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			 						where d.applicationnumber = _applicationnumber)Marriagedetails) as Marriageform,
			 						
(select array_to_json(array_agg(row_to_json(Bridegroom)))
from (select bg.personid,
			bg.salutation,
			s.descriptione as salutation,
			bg.firstname,
			bg.middlename,
			bg.lastname,
			bg.age,
			bg.perdistrictcode,
			bg.pertalukacode,
			bg.perhoblicode,
			bg.percityvillagecode,
			bg.predistrictcode,
			bg.pretalukacode,
			bg.prehoblicode,
			bg.precityvillagecode,--bg.statecode,
			coalesce(bg.perhousebuildname,'')||' '||coalesce(bg.perstreetname,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||' '||INITCAP(stat.statenamee)||'-'||bg.perpincode as permanentaddress,
            coalesce(bg.prehousebuildname,'')||' '||coalesce(bg.prestreetname,'')||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||' '||INITCAP(stat.statenamee)||'-'||bg.prepincode as currentaddress,--,bg.currentpincode,bg.status,
			bg.dob as dateofbirth,
			bg.phoneno as phonenumber,
			s.descriptione as salutation,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
			where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as fathersalutation,
			coalesce(bg.fatherfirstname,'')||' '||coalesce(bg.fathermiddlename,'')||' '||coalesce(bg.fatherlastname,'') as fathername,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
			where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as mothersalutation,
			coalesce(bg.motherfirstname,'')||' '||coalesce(bg.mothermiddlename,'')||' '||coalesce(bg.motherlastname,'') as mothername,--bg.durationin,
			bg.occupation,
			bg.deathcertificateid,
			bg.deathcertificatefilepath,
			bg.divorcecertificateid,
			bg.divorcecertificatefilepath,
			bg.identityproofid,bg.email,
			bg.identityprooffilepath,
			bg.ageproofid,
			bg.ageprooffilepath,
			bg.addressproofid,
			bg.addressprooffilepath,
			bg.durationofstayproofpath,
			mb.description as status
		from kaverimrg.persondetails bg left join kaverimrg.mas_marriagebeforestatus mb on mb.statusid =bg.statusid
									left join kaverimrg.districtmaster distper on bg.perdistrictcode = distper.districtcode 
			                        left join kaverimrg.talukmaster talper on bg.pertalukacode = talper.talukcode 
			                        left join kaverimrg.hoblimaster hobper on bg.perhoblicode = hobper.hoblicode 
			                        left join kaverimrg.villagemaster vilper on bg.percityvillagecode = vilper.villagecode
                                    left join kaverimrg.districtmaster distcur on bg.perdistrictcode = distcur.districtcode 
			                        left join kaverimrg.talukmaster talcur on bg.pertalukacode = talcur.talukcode 
			                        left join kaverimrg.hoblimaster hobcur on bg.perhoblicode = hobcur.hoblicode 
			                        left join kaverimrg.villagemaster vilcur on bg.percityvillagecode = vilcur.villagecode  
                                    left join kaverimrg.statemaster stat on bg.perstatecode = stat.statecode
									left join kaverimrg.salutationmaster s on bg.salutation = s.salutationid 
									where bg.sex = 'M' and bg.applicationnumber = _applicationnumber)Bridegroom) as bridegroom,
									
(select array_to_json(array_agg(row_to_json(Bride)))
from(select br.personid,
			br.salutation,
			s.descriptione as salutation,
			br.firstname,
			br.middlename,
			br.lastname,
			br.age,--br.permanentaddress,br.presentaddress,
			br.perdistrictcode,
			br.pertalukacode,
			br.perhoblicode,
			br.percityvillagecode,
			br.predistrictcode,
			br.pretalukacode,
			br.prehoblicode,
			br.precityvillagecode,
			coalesce(br.perhousebuildname,'')||' '||coalesce(br.perstreetname,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||' '||INITCAP(stat.statenamee)||'-'||br.perpincode as permanentaddress,
            coalesce(br.prehousebuildname,'')||' '||coalesce(br.prestreetname,'')||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||' '||INITCAP(stat.statenamee)||'-'||br.prepincode as currentaddress,--br.status,
			br.dob as dateofbirth,
			br.phoneno as phonenumber,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
			where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as fathersalutation,
			coalesce(br.fatherfirstname,'')||' '||coalesce(br.fathermiddlename,'')||' '||coalesce(br.fatherlastname,'')  as fathername,
			(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
			where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as mothersalutation,
			coalesce(br.motherfirstname,'')||' '||coalesce(br.mothermiddlename,'')||' '||coalesce(br.motherlastname,'')  as mothername,--br.durationin,
			br.occupation,
			br.deathcertificateid,
			br.deathcertificatefilepath,
			br.divorcecertificateid,
			br.divorcecertificatefilepath,
			br.identityproofid,
			br.email,
			br.identityprooffilepath,
			br.ageproofid,
			br.ageprooffilepath,
			br.addressproofid,
			br.addressprooffilepath,
			br.durationofstayproofpath,
			mb.description as status
		from kaverimrg.persondetails br left join kaverimrg.mas_marriagebeforestatus mb on mb.statusid =br.statusid
									left join kaverimrg.districtmaster distper on br.perdistrictcode = distper.districtcode 
			                        left join kaverimrg.talukmaster talper on br.pertalukacode = talper.talukcode 
			                        left join kaverimrg.hoblimaster hobper on br.perhoblicode = hobper.hoblicode 
			                        left join kaverimrg.villagemaster vilper on br.percityvillagecode = vilper.villagecode
                                    left join kaverimrg.districtmaster distcur on br.predistrictcode = distcur.districtcode 
			                        left join kaverimrg.talukmaster talcur on br.pretalukacode = talcur.talukcode 
			                        left join kaverimrg.hoblimaster hobcur on br.prehoblicode = hobcur.hoblicode 
			                        left join kaverimrg.villagemaster vilcur on br.precityvillagecode = vilcur.villagecode  
                                    left join kaverimrg.statemaster stat on br.perstatecode = stat.statecode
									left join kaverimrg.salutationmaster s on br.salutation = s.salutationid
									where br.sex = 'F' and br.applicationnumber = _applicationnumber )Bride) as bride,
									
(select array_to_json(array_agg(row_to_json(witness)))
from (select e.witnessid,
			e.salutation,
			s.descriptione as salutation,
			coalesce(e.firstname,null) as firstname,
			coalesce(e.middlename,'') as middlename,
			coalesce(e.lastname,'') as lastname,
			e.age,
			--a.presentaddress,a.permanentaddress,
			e.perdistrictcode,
			e.pertalukacode,
			e.perhoblicode,
			e.pervillagecode,
			coalesce(e.perhouseno,'')||coalesce(e.perstreetaddress,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||' '||INITCAP(stat.statenamee)||'-'||perpincode as permanentaddress,
            coalesce(e.currenthouseno,'')||coalesce(e.currentstreetaddress,'')||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||' '||INITCAP(stat.statenamee)||'-'||e.currentpincode as currentaddress,
--case when a.sex = 'M'  then
-- a.bridegroomrelation 
----z.relationname
--when a.sex = 'F' then
-- a.briderelation end as relation ,
-- case when z.persontypeid = 1  then
--'Bride Groom'
----z.relationname
--when a.persontypeid = 2 then
-- 'Bride' end as relation,
--z.relationname end as relation,
             z.relationname as relation,
			 mp.persontypename as witnessrelatedto,
			 e.dob,
			 e.email,
			 e.phoneno,
			 g.descriptione as gender
	from kaverimrg.marriagewitnessinfo e left join kaverimrg.gendermaster g on g.genderid = e.genderid
									left join kaverimrg.marriagewitnessrelationmaster z on z.relationid = e.relationid --and
									inner join kaverimrg.marriageregistration mr on mr.applicationnumber = e.applicationnumber
									left join kaverimrg.mas_persontype mp on mp.persontypeid = e.witnessrelatedto
									--e.applicationnumber = a.applicationnumber 
									--and e.srocode = sm.srocode 
                        			left join kaverimrg.districtmaster distper on e.perdistrictcode = distper.districtcode 
			                        left join kaverimrg.talukmaster talper on e.pertalukacode = talper.talukcode 
			                        left join kaverimrg.hoblimaster hobper on e.perhoblicode = hobper.hoblicode 
			                        left join kaverimrg.villagemaster vilper on e.pervillagecode = vilper.villagecode
                                    left join kaverimrg.districtmaster distcur on e.currentdistrictcode = distcur.districtcode 
			                        left join kaverimrg.talukmaster talcur on e.currenttalukacode = talcur.talukcode 
			                        left join kaverimrg.hoblimaster hobcur on e.currenthoblicode = hobcur.hoblicode 
			                        left join kaverimrg.villagemaster vilcur on e.currentvillagecode = vilcur.villagecode
			                        left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
									left join kaverimrg.salutationmaster s on e.salutation = s.salutationid
							where e.applicationnumber = _applicationnumber order by e.witnessid asc )witness) as witness,

(select array_to_json(array_agg(row_to_json(VerificationDetails)))
from (select ar.verificationid,
			ar.marriagedetailsremarks_fda,
			ar.bridegroomdetailsremarks_fda,
			ar.bridedetailsremarks_fda,
			ar.witnessdetailsremarks_fda,
			ar.marriagedetailsremarks_sr,
			ar.bridegroomdetailsremarks_sr,
			ar.bridedetailsremarks_sr,
			ar.witnessdetailsremarks_sr,
			ar.canpreocesstopaymentremarks_sr		
from kaverimrg.marriageapplicationremarks ar where ar.applicationnumber = _applicationnumber )VerificationDetails) as VerificationRemarks
 				
from kaverimrg.marriageregistration m 
 			left join kaverimrg.applicantapplicationdetails a on m.applicationnumber = a.applicationnumber
 			join kaverimrg.sromaster sm on m.regsrocode = sm.srocode
 			--JOIN kaverimrg.villagemaster v ON v.villagecode = a.percityvillagecode
 			--JOIN kaverimrg.sromaster sm ON v.srocode = sm.srocode
			--inner join kaverimrg.districtmaster c on sm.districtcode = c.districtcode     	
			where m.applicationnumber = _applicationnumber
		)app_json) data_json;
	return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_review_marriage_details_200623(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_review_marriage_details_bck_120623(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_review_marriage_details_bck_120623(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json /*( select
  array_to_json(array_agg(row_to_json(app_json)))*/
  from (select row_to_json(app_json) 
 from ( select  a.srocode,b.sronamee,a.drcode,c.districtnamee,
 ( select array_to_json(array_agg(row_to_json(Marriagedetails)))
      from (select d.dateofmarriage::date as marriagedate,d.districtcode,d.talukacode,d.hoblicode,d.cityvillagecode,d.statecode,
			d.housebuildingname||' '||d.streetaddr||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||stat.statenamee||'-'||d.pincode as marriageaddress,
            d.combinephotopath as Jointphotoofthebrideandbridegroom,d.form_1path,d.form_1apath,d.marriageproofid,
			d.marriageproofpath,d.intendedfilepath,d.bridegroomphoto,d.bridephoto,d.marriagemodeid,d.marriagetypeid
			
from kaverimrg.marriageregistration d left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
			                       left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
			                       left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
			                       left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
			                       left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.applicationnumber = a.applicationnumber and 
			  d.applicationnumber = _applicationnumber
		   )Marriagedetails) as Marriageform,
( select array_to_json(array_agg(row_to_json(Bridegroom)))
      from ( select bg.personid,bg.salutation,s.descriptione as salutation,bg.firstname,bg.middlename,bg.lastname,bg.age,
bg.perdistrictcode,bg.pertalukacode,bg.perhoblicode,bg.percityvillagecode,bg.predistrictcode,bg.pretalukacode,bg.prehoblicode,bg.precityvillagecode,--bg.statecode,
			bg.perhousebuildname||' '||bg.perstreetname||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||'-'||bg.perpincode as permanentaddress,
                        bg.prehousebuildname||' '||bg.prestreetname||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||'-'||bg.prepincode as currentaddress,--,bg.currentpincode,
bg.status,bg.dob as dateofbirth,bg.phoneno as phonenumber,s.descriptione as salutation,(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as fathersalutation,
coalesce(bg.fatherfirstname,'')||' '||coalesce(bg.fathermiddlename,'')||' '||coalesce(bg.fatherlastname,'') as fathername,
(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
where bg.sex = 'M' and bg.applicationnumber = _applicationnumber) as mothersalutation,
bg.motherfirstname||' '||coalesce(bg.mothermiddlename,'')||''||bg.motherlastname as mothername,bg.durationin,bg.occupation,
bg.deathcertificateid,bg.deathcertificatefilepath,bg.divorcecertificateid,bg.divorcecertificatefilepath,bg.identityproofid,bg.email,
bg.identityprooffilepath,bg.ageproofid,bg.ageprooffilepath,bg.addressproofid,bg.addressprooffilepath,bg.durationofstayproofpath
			from kaverimrg.persondetails bg left join kaverimrg.districtmaster distper on bg.perdistrictcode = distper.districtcode 
			                              left join kaverimrg.talukmaster talper on bg.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on bg.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on bg.percityvillagecode = vilper.villagecode
                                                       left join kaverimrg.districtmaster distcur on bg.perdistrictcode = distcur.districtcode 
			                              left join kaverimrg.talukmaster talcur on bg.pertalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on bg.perhoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on bg.percityvillagecode = vilcur.villagecode  
                                                        --left join kaverimrg.statemaster s on bg.statecode = s.statecode
left join kaverimrg.salutationmaster s on bg.salutation = s.salutationid 
			where bg.sex = 'M' and bg.applicationnumber = a.applicationnumber
		  and bg.applicationnumber = _applicationnumber
		   )Bridegroom) as bridegroom,
( select array_to_json(array_agg(row_to_json(Bride)))
      from ( select br.personid,br.salutation,s.descriptione as salutation,br.firstname,br.middlename,br.lastname,br.age,--br.permanentaddress,br.presentaddress,
br.perdistrictcode,br.pertalukacode,br.perhoblicode,br.percityvillagecode,br.predistrictcode,br.pretalukacode,br.prehoblicode,br.precityvillagecode,
			coalesce(br.perhousebuildname,'')||' '||coalesce(br.perstreetname,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||'-'||br.perpincode as permanentaddress,
                        coalesce(br.prehousebuildname,'')||' '||coalesce(br.prestreetname,'')||' '||distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||'-'||br.prepincode as currentaddress,
br.status,br.dob as dateofbirth,br.phoneno as phonenumber,(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.fathersalutation = s.salutationid
where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as fathersalutation,coalesce(br.fatherfirstname,'')||' '||coalesce(br.fathermiddlename,'')||''||coalesce(br.fatherlastname,'')  as fathername,
(select descriptione from kaverimrg.salutationmaster s join kaverimrg.persondetails bg on bg.mothersalutation = s.salutationid
where bg.sex = 'F' and bg.applicationnumber = _applicationnumber) as mothersalutation,coalesce(br.motherfirstname,'')||' '||coalesce(br.mothermiddlename,'')||''||coalesce(br.motherlastname,'')  as mothername,br.durationin,br.occupation,
br.deathcertificateid,br.deathcertificatefilepath,br.divorcecertificateid,br.divorcecertificatefilepath,br.identityproofid,br.email,
br.identityprooffilepath,br.ageproofid,br.ageprooffilepath,br.addressproofid,br.addressprooffilepath,br.durationofstayproofpath
from kaverimrg.persondetails br left join kaverimrg.districtmaster distper on br.perdistrictcode = distper.districtcode 
			                              left join kaverimrg.talukmaster talper on br.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on br.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on br.percityvillagecode = vilper.villagecode
                                                       left join kaverimrg.districtmaster distcur on br.predistrictcode = distcur.districtcode 
			                              left join kaverimrg.talukmaster talcur on br.pretalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on br.prehoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on br.precityvillagecode = vilcur.villagecode  
                                                        --left join kaverimrg.statemaster s on br.statecode = s.statecode
left join kaverimrg.salutationmaster s on br.salutation = s.salutationid
where br.sex = 'F' and br.applicationnumber = a.applicationnumber
		  and br.applicationnumber = _applicationnumber 
		   )Bride) as bride,
( select array_to_json(array_agg(row_to_json(witness)))
      from (select  e.witnessid,e.salutation,s.descriptione as salutation,coalesce(e.firstname,null) as firstname,coalesce(e.middlename,'') as middlename,coalesce(e.lastname,'') as lastname,e.age,
--a.presentaddress,a.permanentaddress,
e.perdistrictcode,e.pertalukacode,e.perhoblicode,e.pervillagecode,
			coalesce(e.perhouseno,'')||coalesce(e.perstreetaddress,'')||' '||distper.districtnamee||' '||talper.taluknamee||' '||hobper.hoblinamee||' '||vilper.villagenamee||'-'||perpincode as permanentaddress,
                        distcur.districtnamee||' '||talcur.taluknamee||' '||hobcur.hoblinamee||' '||vilcur.villagenamee||'-'||e.currentpincode as currentaddress,
case when sex = 'M'  then
 --a.bridegroomrelation 
z.relationname
when sex = 'F' then
 --a.briderelation end as relation 
z.relationname end as relation,
			e.witnessrelatedto,e.dob,e.email,e.phoneno
			from		
kaverimrg.marriagewitnessinfo e  
			left join kaverimrg.marriagewitnessrelationmaster z on z.relationid = e.relationid and
			 e.applicationnumber = a.applicationnumber and e.srocode = a.srocode 
                        left join kaverimrg.districtmaster distper on e.perdistrictcode = distper.districtcode 
			                              left join kaverimrg.talukmaster talper on e.pertalukacode = talper.talukcode 
			                                left join kaverimrg.hoblimaster hobper on e.perhoblicode = hobper.hoblicode 
			                                left join kaverimrg.villagemaster vilper on e.pervillagecode = vilper.villagecode
                                                       left join kaverimrg.districtmaster distcur on e.currentdistrictcode = distcur.districtcode 
			                              left join kaverimrg.talukmaster talcur on e.currenttalukacode = talcur.talukcode 
			                                left join kaverimrg.hoblimaster hobcur on e.currenthoblicode = hobcur.hoblicode 
			                                left join kaverimrg.villagemaster vilcur on e.currentvillagecode = vilcur.villagecode
left join kaverimrg.salutationmaster s on e.salutation = s.salutationid
			where e.applicationnumber = _applicationnumber
 )witness) as witness,
( select array_to_json(array_agg(row_to_json(VerificationDetails)))
      from (select ar.verificationid,ar.marriagedetailsremarks_fda,ar.bridegroomdetailsremarks_fda,
			ar.bridedetailsremarks_fda,ar.witnessdetailsremarks_fda,ar.marriagedetailsremarks_sr,
			ar.bridegroomdetailsremarks_sr,ar.bridedetailsremarks_sr,ar.witnessdetailsremarks_sr,
			ar.canpreocesstopaymentremarks_sr
			
from kaverimrg.marriageapplicationremarks ar where ar.applicationnumber = a.applicationnumber and 
			  ar.applicationnumber = _applicationnumber
		   )VerificationDetails) as VerificationRemarks	   
 from kaverimrg.persondetails a inner join kaverimrg.sromaster b on a.srocode = b.srocode 
inner join kaverimrg.districtmaster c on b.districtcode = c.districtcode
where a.applicationnumber = _applicationnumber
)  app_json ) data_json;
/*update kaverimrg.marriageregistration set   numberofcopy=_numberofcopy,
 declarationdate=current_timestamp,
 declarationplace=_declarationplace where applicationnumber = _applicationnumber;*/
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_review_marriage_details_bck_120623(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_road_details(bigint, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_road_details(p_villagecode bigint, p_isactive boolean) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
if(p_isactive=true) THEN
			Return query
			select distinct  r.roadcode,r.roadnamee,r.roadnamek from kaverimrg.roadmaster r
			inner join kaverimrg.rateagriculturaldetail agri on r.roadcode=agri.roadcode
			where r.villagecode = p_villagecode and r.isactive = true and agri.rate>0
		Union all 	
			select distinct r.roadcode,r.roadnamee,r.roadnamek from kaverimrg.roadmaster r
		--left outer join kaverimrg.mas_val_flatrates f on r.roadcode=f.roadid
		left outer join kaverimrg.openbuiltratedetail o on r.roadcode=o.roadcode
		where r.villagecode = p_villagecode 
		 and r.isactive = true 
		 and o.rate>0;
		 --and (f.rate>0 and o.rate>0);		
ELSE
		return query
		select distinct r.roadcode,r.roadnamee,r.roadnamek from kaverimrg.roadmaster r
		left outer join kaverimrg.mas_val_flatrates f on r.roadcode=f.roadid
		left outer join kaverimrg.openbuiltratedetail o on r.roadcode=o.roadcode
		where r.villagecode = p_villagecode and r.isactive = true and (f.rate>0 or o.rate>0);
END IF;

END;
$$;


