ALTER FUNCTION kaverimrg.fn_fetch_road_details_backup_15022023(p_villagecode bigint, p_isactive boolean) OWNER TO postgres;

--
-- Name: fn_fetch_roadmasterdetails(integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_roadmasterdetails(_srocode integer, _districtcode integer, _talukacode integer, _hoblicode integer, _villagecode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(roadcode bigint, roadnamee character varying, roadnamek character varying, villagecode bigint, villagenamee character varying, isactive boolean, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);


return query 

with cte as (select  distinct r.roadcode,r.roadnamee,r.roadnamek,r.villagecode,v.villagenamee,r.isactive from kaverimrg.roadmaster r
inner join kaverimrg.villagemaster v on r.villagecode=v.villagecode
where r.villagecode =_villagecode),cte_count as (select count(*) as total_rows from cte)
   select * from cte
   right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_roadmasterdetails(_srocode integer, _districtcode integer, _talukacode integer, _hoblicode integer, _villagecode integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_fetch_roleinfo_byuseid(integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_roleinfo_byuseid(user_id integer) RETURNS TABLE(rolesinfo json)
    LANGUAGE plpgsql
    AS $$

DECLARE


BEGIN


	
   RETURN QUERY
   
	select (select array_to_json(array_agg(row_to_json(roles))) 
			from (
			select 0 as userroleid, dr.designationid,dm.designame,'Default' as rolename,
			false as candelete,
			sr.officename||'-'||mo.officetypedesc  as sroname, 
			sr.officenamer||'-'||mo.officetypedescr as sronamek,
			concat_ws(' '::text, dr.firstname, dr.lastname) AS Name,
			dr.mobileno  as MobileNumber, 
			concat_ws(' '::text, dr.firstname, dr.lastname)||' - '||dm.designame as displayName,
			dr.userid,0 as mappeduserid,'' as mappedUser
			FROM kaverimrg.desigmaster dm
			inner join kaverimrg.departmentusers dr on dm.designationid=dr.designationid  
			left join kaverimrg.mas_officemaster sr on(sr.officeid = dr.officeid)
			join kaverimrg.mas_officetypes mo on sr.officetypeid=mo.officetypeid
			where dr.userid=user_id	
			union all			
			select rl.userroleid ,rl.designationid,dmrl.designame::character varying,dmrl.designame::character varying as rolename,
			true as candelete,
			sr.officename||'-'||mo.officetypedesc  as sroname, 
			sr.officenamer||'-'||mo.officetypedescr as sronamek,
			concat_ws(' '::text, dr.firstname, dr.lastname) AS Name,
			dr.mobileno  as MobileNumber,
			concat_ws(' '::text, dr.firstname, dr.lastname)||' - '||dmrl.designame as displayName,
			dr.userid,rl.mappeduserid as mappeduserid, concat_ws(' '::text, c.firstname, c.lastname) as mappedUser
			from kaverimrg.departmentuserroles rl 
			inner join kaverimrg.desigmaster dmrl on (rl.designationid = dmrl.designationid)
			inner join kaverimrg.departmentusers dr on (dr.userid = rl.userid)
			inner join kaverimrg.departmentusers c  on (c.userid =rl.mappeduserid)
			left join kaverimrg.mas_officemaster sr on(sr.officeid = rl.mappedofficeid)
			join kaverimrg.mas_officetypes mo on sr.officetypeid=mo.officetypeid
			where rl.userid =user_id				
			Union All
			select rl.userroleid ,rl.designationid,dmrl.designame::character varying,dmrl.designame::character varying as rolename,
			true as candelete,
			sr.officename||'-'||mo.officetypedesc  as sroname, 
			sr.officenamer||'-'||mo.officetypedescr as sronamek,
			concat_ws(' '::text, dr.firstname, dr.lastname) AS Name,
			dr.mobileno  as MobileNumber,
			concat_ws(' '::text, dr.firstname, dr.lastname)||' - '||dmrl.designame as displayName,
			dr.userid,
			null  as mappeduserid, 
		     null  as mappedUser
			from kaverimrg.departmentuserroles rl 
			inner join kaverimrg.desigmaster dmrl on (rl.designationid = dmrl.designationid)
			inner join kaverimrg.departmentusers dr on (dr.userid = rl.userid) and rl.mappeduserid is NULL
			left join kaverimrg.mas_officemaster sr on(sr.officeid = dr.officeid)
			join kaverimrg.mas_officetypes mo on sr.officetypeid=mo.officetypeid
			where rl.userid =user_id 
								
			) roles)as roleinfo;
			

		
			
			END;
$$;


