--
-- Name: fn_fetch_transaction_count(timestamp without time zone, timestamp without time zone, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) RETURNS TABLE(documentregcount bigint, marriageregcount bigint, ecregcount bigint, ccregcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
DocumentregCount bigint;
marriageregcount bigint;
ecregcount bigint;
ccregcount bigint;
v_srocode bigint;
v_districtcode bigint;
v_array bigint[];
begin
	select  d.srocode,d2.districtcode into v_srocode,v_districtcode  from kaverimrg.departmentusers d 
		join kaverimrg.sromaster s on d.srocode =s.srocode 
		join kaverimrg.districtmaster d2 on d2.districtcode = s.districtcode where  d.userid=_userid ;
	
-- FETCH DOC COUNT---	
	
	select count(*) into DocumentregCount from kaverimrg.documentmaster d 
			join kaverimrg.sromaster s on d.srocode = s.srocode 
		join kaverimrg.districtmaster d2 on s.districtcode = d2.districtcode 
		where d.isregistrationcompleted =true and d.registrationdatetime  >= _fromDT and d.registrationdatetime  <= _TODT 
		and d.srocode in (v_srocode)   and d2.districtcode in (v_districtcode);

	-- Marriage Reg
	
	select count(*)  as MarriageRegCount into marriageregcount 
	from  kaverimrg.marriageregistration m
	join kaverimrg.sromaster s on s.srocode = m.regsrocode  
	join kaverimrg.districtmaster d2  on s.districtcode = d2.districtcode 
	where m.dateofregistration >=_fromDT and m.dateofregistration<= _TODT and m.regsrocode in (v_srocode) and d2.districtcode in(v_districtcode);

--- EC REG

	select count(*)  as ECRegCount into ecregcount  from kaverimrg.applicantapplicationdetails a
	join kaverimrg.sromaster s on s.srocode = a.srocode 
	join kaverimrg.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=13 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT 
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; -- sro EC

----CC REG
	
	select count(*)  as CCRegCount into ccregcount  from kaverimrg.applicantapplicationdetails a
	join kaverimrg.sromaster s on s.srocode = a.srocode 
	join kaverimrg.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=12 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; --ApplicantApplicatonDetails
	
	return query
	select DocumentregCount,marriageregcount,ecregcount,ccregcount;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_transaction_count(timestamp without time zone, timestamp without time zone, bigint, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint, _desigid bigint) RETURNS TABLE(documentregcount bigint, marriageregcount bigint, ecregcount bigint, ccregcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
DocumentregCount bigint;
marriageregcount bigint;
ecregcount bigint;
ccregcount bigint;
v_srocode bigint;
v_districtcode bigint;
v_array bigint[];
begin
	select  d.srocode,d2.districtcode into v_srocode,v_districtcode  from kaverimrg.departmentusers d 
		join kaverimrg.sromaster s on d.srocode =s.srocode 
		join kaverimrg.districtmaster d2 on d2.districtcode = s.districtcode where d.designationid=_desigid and d.userid=_userid ;
	
-- FETCH DOC COUNT---	
	
	select count(*) into DocumentregCount from kaverimrg.documentmaster d 
			join kaverimrg.sromaster s on d.srocode = s.srocode 
		join kaverimrg.districtmaster d2 on s.districtcode = d2.districtcode 
		where d.isregistrationcompleted =true and d.registrationdatetime  >= _fromDT and d.registrationdatetime  <= _TODT 
		and d.srocode in (v_srocode)   and d2.districtcode in (v_districtcode);

	-- Marriage Reg
	
	select count(*)  as MarriageRegCount into marriageregcount 
	from  kaverimrg.marriageregistration m
	join kaverimrg.sromaster s on s.srocode = m.srocode 
	join kaverimrg.districtmaster d2  on s.districtcode = d2.districtcode 
	where m.dateofregistration >=_fromDT and m.dateofregistration<= _TODT and m.srocode in (v_srocode) and d2.districtcode in(v_districtcode);

--- EC REG

	select count(*)  as ECRegCount into ecregcount  from kaverimrg.applicantapplicationdetails a
	join kaverimrg.sromaster s on s.srocode = a.srocode 
	join kaverimrg.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=13 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT 
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; -- sro EC

	select count(*)  as CCRegCount into ccregcount  from kaverimrg.applicantapplicationdetails a
	join kaverimrg.sromaster s on s.srocode = a.srocode 
	join kaverimrg.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=12 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationenddate  <=_TODT
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; --ApplicantApplicatonDetails
	
	return query
	select DocumentregCount,marriageregcount,ecregcount,ccregcount;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_transaction_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint, _desigid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_transaction_sakalapending_count(timestamp without time zone, timestamp without time zone, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_transaction_sakalapending_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) RETURNS TABLE(documentregcount bigint, marriageregcount bigint, ecregcount bigint, ccregcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
DocumentregCount bigint;
marriageregcount bigint;
ecregcount bigint;
ccregcount bigint;
v_srocode bigint;
v_districtcode bigint;
v_array bigint[];
v_desigid bigint;
begin

--- Fetching SRO CODE AND DR CODE---	
select d.srocode,d2.districtcode into v_srocode, v_districtcode from kaverimrg.departmentusers d 
join kaverimrg.sromaster s on d.srocode = s.srocode 
join kaverimrg.districtmaster d2 on s.districtcode  = d2.districtcode 
where d.srocode  not in (select srocode  from kaverimrg.sakala_partydetails sp)  and userid =_userid;

--- FETCHING COUNT OF DOCUMENT REGISTERED

select count(*) into DocumentregCount from kaverimrg.documentmaster d 
		join kaverimrg.sromaster s on d.srocode = s.srocode 
		join kaverimrg.districtmaster d2 on s.districtcode = d2.districtcode 
		where d.isregistrationcompleted =true and d.executiondatetime >= _fromDT and d.executiondatetime <= _TODT 
		and d.srocode in (v_srocode)  and isregistrationcompleted = true and d2.districtcode in (v_districtcode);


select count(*) as Marriageregcount into marriageregcount 
	from  kaverimrg.marriageregistration m
	join kaverimrg.sromaster s on s.srocode = m.regsrocode 
	join kaverimrg.districtmaster d2  on s.districtcode = d2.districtcode 
	where m.dateofregistration >=_fromDT and m.dateofregistration<= _TODT and m.regsrocode in (v_srocode) and d2.districtcode in(v_districtcode);

	select count(*)  as ECRegCount into ecregcount  from kaverimrg.applicantapplicationdetails a
	join kaverimrg.sromaster s on s.srocode = a.srocode 
	join kaverimrg.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=13 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationstartdate <=_TODT 
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; -- sro EC

	select count(*)  as CCRegCount into ccregcount  from kaverimrg.applicantapplicationdetails a
	join kaverimrg.sromaster s on s.srocode = a.srocode 
	join kaverimrg.districtmaster d on d.districtcode = s.districtcode 
	where a.applicationtypeid=12 and a.currentstatus = 'CD120' and a.applicationstartdate <=_fromDT and a.applicationstartdate <=_TODT
	and a.srocode in (v_srocode) and d.districtcode in (v_districtcode) ; --ApplicantApplicatonDetails
	
	return query
	select DocumentregCount,marriageregcount,ecregcount,ccregcount;

end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_transaction_sakalapending_count(_fromdt timestamp without time zone, _todt timestamp without time zone, _userid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_uploaddocument_firm(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_uploaddocument_firm(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN

select array_to_json(array_agg(row_to_json(data_json))) into v_data_json 
      from  (select --a.applicationnumber,
			  
( select (row_to_json(Firmdocuments))
  from 
 (select f.partnershipdeedid,f.partnershipdeedpath,f.affidavit,f.firmaddressproofid,f.firmaddressproofidpath,
  f.supportingdocument1path,f.supportingdocument2path,f.document_challan_number
        from kaverimrg.firmmaster f
		where f.applicationnumber =_applicationnumber) Firmdocuments) as Firmdocuments,
  
 ( select (row_to_json(presenter_detils))
from 
   (select f2.agentproofid,f2.agentproofidpath
from kaverimrg.firmparty f2
where f2.applicationnumber =_applicationnumber and f2.presentertypeid in (1,2)) presenter_detils) as presenter_detils,
   

( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select f3.identityproofid,f3.identityproofidpath,f3.addressproofid,f3.addressproofidpath, f3.firmpersonid
from kaverimrg.firmparty f3
where f3.applicationnumber =_applicationnumber and f3.presentertypeid in (6))partnerdetails ) as partnerdetails,
			 
( select array_to_json(array_agg(row_to_json(witnessdetails)))
from (select f4.identityproofid,f4.identityproofidpath,f4.addressproofid,f4.addressproofidpath, f4.firmwitnessid
from kaverimrg.frm_witnessdetails f4
where f4.applicationnumber =_applicationnumber)witnessdetails ) as witnessdetails,

			 ( select array_to_json(array_agg(row_to_json(Branchdetails)))
from (select f5.branchdocument,f5.branchid
from kaverimrg.firmbranches f5
where f5.applicationnumber =_applicationnumber)Branchdetails ) as Branchdetails
			 
-- 		 from kaverimrg.firmparty a 
-- where a.applicationnumber = _applicationnumber		 
			 
)data_json;
  
return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_uploaddocument_firm(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetch_valuations_json_data(text, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_valuations_json_data(_applicationnumber text, _propertytypeid bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
BEGIN
		

select row_to_json(data_json) into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json)))
	--select row_to_json(app_json) into v_data_json
from (select a.applicationnumber,a.propertyid,
  a.valid,a.srocode,i.sronamee,a.regsrocode,a.villagecode,
a.roadcode,a.valuationdate::date valuationdate,a.propertytypeid,a.totalarea,a.unitid,a.marketvalue,
a.leasetype,a.leaseamount,a.northboundary,a.southboundary,a.eastboundary,
a.westboundary, a.assessment,a.regarticlecode,a.verified,
a.issroapproved,
	   (
      select array_to_json(array_agg(row_to_json(agri)))
		   from (
	  	select ag.agriculturedetailsid,ag.agrilandtypeid,ag.unitid,ag.valuationid,
								ag.verified,ag.agrirateid,ag.rate,ag.srocode,ag.regsrocode
								from kaverimrg.val_agriculturedetails ag
			                    where a.valid = ag.valuationid)agri)as agriculture,
    (
      select array_to_json(array_agg(row_to_json(val)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
			b.flatrateid,b.rate,k.floorid
FROM 
kaverimrg.val_flatratedetails b,
kaverimrg.mas_val_flatrates k
where a.valid = b.valuationid 
and a.propertytypeid = b.propertytypeid 
and a.unitid = b.unitid
and b.flatrateid = k.flaterateid
		   ) val
    ) as flatratedetails,	
	    (
      select array_to_json(array_agg(row_to_json(val)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
b.openbuiltvalid,b.rate,b.openbuiltrateid 
FROM --kaverimrg.valuationdetails a,
kaverimrg.val_openbuiltvaluationdetails b,
kaverimrg.mas_val_openbuiltrates k
where a.valid = b.valuationid 
and a.propertytypeid = b.propertytypeid 
and a.unitid = b.unitid
and b.openbuiltrateid = k.openbuiltrateid
		   ) val
    ) as openbuiltvaluationdetails,	
	(
	select array_to_json(array_agg(row_to_json(crd)))
	 from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
		   s.constructiondetailsid,s.constructiontypeid,s.gfarea,s.agfarea,
		   s.rate,s.verified,s.valuationid,s.srocode,s.regsrocode
		   from kaverimrg.val_constructionratedetails s
		   where a.valid = s.valuationid
		   ) crd
	)  as constructionratedetails,
	  
	 (
      select array_to_json(array_agg(row_to_json(amn)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
c.amenetiesdetailsid,c.apartmentamenetyruleid,c.rate as rate1
FROM 
kaverimrg.val_apartmentamenitydetails c
where a.valid = c.valuationid 
		   ) amn
    ) as apartmentamenitydetails,
/* ============================================*/
	  
	  (
      select array_to_json(array_agg(row_to_json(amz)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,d.useramenetiesdetailsid,
d.apartmentamenityid,d.isselected,d.verified
FROM --kaverimrg.valuationdetails a,
kaverimrg.val_userapartmentamenitydetails d
where a.valid = d.valuationid 
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   ) amz
    ) as userapartmentamenitydetails,
	  
/*  ===========================================*/
	  
	(  select array_to_json(array_agg(row_to_json(anx)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
d.annexuredetailsid,d.annexureid,d.rate as rate2,d.isselected,d.area
FROM --kaverimrg.valuationdetails a,
kaverimrg.val_annexuredetails d
where a.valid = d.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   ) anx
	) as annexuredetails,
	( select array_to_json(array_agg(row_to_json(prk)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
e.parkingdetailsid,e.parkingtypeid,e.totalparkings,e.rate as rate3
FROM --kaverimrg.valuationdetails a,
kaverimrg.val_parkingratedetails e
where a.valid = e.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   )prk ) as parkingratedetails,
	( select array_to_json(array_agg(row_to_json(flr)))
      from (SELECT distinct a.valid,a.applicationnumber,a.propertyid,
f.flatfloordetailsid,f.apartmentfloorrateid,f.rate as rate4 
FROM --kaverimrg.valuationdetails a,
kaverimrg.val_flatfloordetails f
where a.valid = f.valuationid
--and a.propertytypeid =12  and a.applicationnumber = 'PRP-15122021-01686'
		   )flr ) as flatfloordetails
  FROM kaverimrg.valuationdetails a 
	  left join kaverimrg.sromaster i on (a.srocode = i.srocode) where 
	a.propertytypeid =_propertytypeid--12  
	  and a.applicationnumber = _applicationnumber--'PRP-15122021-01686'
)  app_json ) data_json;

return v_data_json;

END;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_valuations_json_data(_applicationnumber text, _propertytypeid bigint) OWNER TO postgres;

--
-- Name: fn_fetch_village_deptid(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_village_deptid(_villagecode bigint) RETURNS TABLE(deptid integer, villagecode integer, departmentname character varying)
    LANGUAGE plpgsql
    AS $$
declare 

begin
	if(_villagecode in(select a.villagecode from kaverimrg.villageurbanmapping a)) then 
	return query
	select v.deptid,v.villagecode,i.departmentname from kaverimrg.villageurbanmapping v 
	join kaverimrg.integrationdepartment i on v.deptid=i.udeptid where v.villagecode = _villagecode and v.deptid in (2,46,10);
	else
	return query
	select distinct v.deptid, _villagecode as villagecode ,i.departmentname from kaverimrg.villageurbanmapping v 
	join kaverimrg.integrationdepartment i on v.deptid=i.udeptid where v.deptid in (2,46);
end if;
--return query;
--select deptid,villagecode,departmentname;
end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_village_deptid(_villagecode bigint) OWNER TO postgres;

--
-- Name: fn_fetch_wrkflowcount(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetch_wrkflowcount(_srocode bigint) RETURNS TABLE(receivedfromcitizen bigint, allocatedtofda_sda bigint, receivedfromfda_sda_sda bigint, senttocitizenforconfirmations bigint, receivedfromcitizenafterconfirmation bigint, allocatedtodeo_sda bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
v_AllocatedtoFDA_SDA bigint;
v_ReceivedfromFDA_SDA_SDA bigint;
--v_array bigint[];
begin 

select Count(*) as ReceivedFromCitizen into ReceivedFromCitizen  from(
select distinct * from kaverimrg.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD102') receivedfromcit;
	
select Count(*) as AllocatedtoFDA_SDA  into AllocatedtoFDA_SDA from(
select distinct * from kaverimrg.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD103')wrkflw;


select Count(*) as ReceivedfromFDA_SDA_SDA into ReceivedfromFDA_SDA_SDA     from(
select distinct * from kaverimrg.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD104') sda ;

select Count(*) as SenttocitizenforConfirmations into SenttocitizenforConfirmations  from(
select distinct * from kaverimrg.vw_fetch_pending_sro_appnum where srocode= _srocode and currentstatus='CD106')SenttocitizenforConfirmation;

select Count(*) as Receivedfromcitizenafterconfirmation into Receivedfromcitizenafterconfirmation  from(
SELECT distinct * FROM kaverimrg.vw_fetch_pending_docreg where SROCODE= 173 and currentstatus in ('CD108','CD109'))Receivedfromcitizenafterconfirmatio;

select Count(*) as AllocatedtoDEo_SDA into AllocatedtoDEo_SDA  from(
SELECT distinct * FROM kaverimrg.vw_fetch_pending_docreg where SROCODE= 173 and currentstatus in ('CD110'))AllocatedtoDEo_SD;


return query 
select ReceivedFromCitizen,AllocatedtoFDA_SDA,ReceivedfromFDA_SDA_SDA,SenttocitizenforConfirmations,Receivedfromcitizenafterconfirmation,AllocatedtoDEo_SDA;



end;
$$;


ALTER FUNCTION kaverimrg.fn_fetch_wrkflowcount(_srocode bigint) OWNER TO postgres;

