CREATE FUNCTION kaverimrg.fn_fetchfirmregdetails(_applicationnumber character varying) RETURNS TABLE(applicationnumber character varying, registrationid numeric, firmname character varying, firmphone character varying, nature character varying, housebuildingname character varying, streetaddress character varying, statecode integer, districtcode integer, talukacode integer, hoblicode integer, cityvillagecode integer, pincode integer, dateofconstitutionofthefirm timestamp without time zone, underoneyearstampdutypaid boolean, underoneyearstampdutynotpaid boolean, morethanoneyearstampdutypaid boolean, morethanoneyearstampdutynotpaid boolean, challanreceipt character varying, durationoffirm boolean, hasbranches boolean, frimbranches json)
    LANGUAGE plpgsql
    AS $$


