--v_data_json json;
BEGIN

RETURN QUERY 

select f.applicationnumber as applicationnumber, f.registrationid, f.firmname,f.firmphone, f.nature, f.housebuildingname, f.streetaddress,

f.statecode, f.districtcode, f.talukacode, f.hoblicode, f.cityvillagecode, f.pincode, f.dateofconstitutionofthefirm, f.underoneyearstampdutypaid,

