--
-- Name: fn_fetchprintamendment(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetchprintamendment(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
 -- from (select row_to_json(app_json) 
 from ( select  c.districtnamee,c.districtnamee as droffice,	
	   
 (select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	fa.amendpincode,
		count(firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		fa.inserteddatetime::date as DateOfRegistration
			from kaverimrg.firmmaster d 
		inner join kaverimrg.amendmentmaster am on am.finalregistrationnumber=d.finalregistrationnumber
		left join kaverimrg.firmamendment fa on am.applicationnumber=fa.applicationnumber
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber
		inner join kaverimrg.applicantapplicationdetails a on am.applicationnumber  =a.applicationnumber
		inner join kaverimrg.wrkflowmaster wf on a.currentstatus =wf.wrkflowstatusid 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where am.applicationnumber =_applicationnumber
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		fa.inserteddatetime,fa.amendpincode)Firmdetails) as Firmdetails,
	   
	   
	   	 (select array_to_json(array_agg(row_to_json(ChangenameFirmdetails)))
  from (select d.firmname as Newfirmname,
			d.amendhousebuildingname||' '||d.amendstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.amendpincode as NewfirmAddress	
		from kaverimrg.firmamendment d 
		inner join kaverimrg.amendmentmaster am on am.applicationnumber=d.applicationnumber
		left join kaverimrg.districtmaster di on  d.amenddistrictcode=di.districtcode  
	    left join kaverimrg.talukmaster ta on  d.amendtalukacode=ta.talukcode 
		left join kaverimrg.hoblimaster ho on d.amendhoblicode =ho.hoblicode 
		left join kaverimrg.villagemaster vill on d.amendcityvillagecode =vill.villagecode 
		left join kaverimrg.statemaster stat on d.amendstatecode =stat.statecode 
			where d.applicationnumber =_applicationnumber)ChangenameFirmdetails) as ChangenameFirmdetails,
---------------	   
	   	   ( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname, --pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID,
	  br.firmpersonid,br.presentertypeid
from kaverimrg.firmparty br
 inner join kaverimrg.firmmaster fm on fm.applicationnumber=br.applicationnumber
   inner join kaverimrg.amendmentmaster am on am.finalregistrationnumber=fm.finalregistrationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where am.applicationnumber =_applicationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,
	   
--------------------------------
	     (select array_to_json(array_agg(row_to_json(Current_partner_Name)))
  from (select d.firstname||''||d.middlename||''||d.lastname as Currentpartner_Name
			from 
			kaverimrg.amendmentfirmparty d
		--inner join  kaverimrg.firmparty e  on d.firmpersonid=e.firmpersonid
   inner join kaverimrg.amendmentmaster am on am.applicationnumber=d.applicationnumber
			where am.applicationnumber =_applicationnumber)Current_partner_Name) as Current_partner_Name,
	   
	   	   (select array_to_json(array_agg(row_to_json(New_partner_Name)))
  from (select d.firstname||''||d.middlename||''||d.lastname as Newpartner_Name
			from  kaverimrg.amendmentfirmparty d 
		 inner join kaverimrg.amendmentmaster am on am.applicationnumber=d.applicationnumber
			where am.applicationnumber =_applicationnumber)New_partner_Name) as New_partner_Name,    
	   
		 (select array_to_json(array_agg(row_to_json(current_Partner_Address)))
  from (select e.perhousebuildname||' '||e.perstreetname||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||e.perpincode as currentPartner_Addres
		from  kaverimrg.amendmentfirmparty d 
		 inner join kaverimrg.amendmentmaster am on am.applicationnumber=d.applicationnumber
	inner join  kaverimrg.firmparty e  on d.firmpersonid=e.firmpersonid
		left join kaverimrg.districtmaster di on e.perdistrictcode = di.districtcode
	    left join kaverimrg.talukmaster ta on e.pertalukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on e.perhoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on e.percityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on e.perstatecode = stat.statecode
			where am.applicationnumber =_applicationnumber)current_Partner_Address) as current_Partner_Address,  
	   
	 (select array_to_json(array_agg(row_to_json(NewPartner)))
  from (select d.amendhousebuildingname||' '||d.amendstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.amendpincode as NewPartner_Address
		from kaverimrg.amendmentfirmparty d 
		inner join kaverimrg.amendmentmaster am on am.applicationnumber=d.applicationnumber
		left join kaverimrg.districtmaster di on d.amenddistrictcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.amendtalukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.amendhoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.amendcityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.amendstatecode = stat.statecode
			where am.applicationnumber =_applicationnumber)NewPartner) as NewPartner,
-----------------------   
	   (select array_to_json(array_agg(row_to_json(minorpartnerName)))
  from (select d.firstname,d.middlename,d.lastname
			from kaverimrg.firmparty d 
		inner join kaverimrg.firmmaster fm on fm.applicationnumber=d.applicationnumber
   inner join kaverimrg.amendmentmaster am on am.finalregistrationnumber=fm.finalregistrationnumber
			where am.applicationnumber =_applicationnumber and d.age< 18)minorpartnerName) as minorpartnerName,
------------------------------
		
	(select array_to_json(array_agg(row_to_json(amendmentbranch)))
  from (select d.branchid, d.branchhousebuildingname ||' '||d.branchstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.branchpincode as current_branch_address,
		am.amendhousebuildingname||' '||am.amendstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||am.amendpincode as new_branch_address
		from kaverimrg.firmbranches d 
		inner join kaverimrg.amendmentfirmbranches am on am.branchid  =d.branchid
		left join kaverimrg.districtmaster di on d.branchdistrictcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.branchtalukacode  = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.branchhoblicode  = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.branchcityvillagecode  = vill.villagecode
		left join kaverimrg.statemaster stat on d.branchstatecode  = stat.statecode
		where am.applicationnumber = _applicationnumber and am.isremoved= true)amendmentbranch) as amendmentbranch		
	   	  	   
 from kaverimrg.firmparty a 
	   inner join kaverimrg.firmmaster fm on a.applicationnumber=fm.applicationnumber
inner join kaverimrg.amendmentmaster fa on fm.finalregistrationnumber=fa.finalregistrationnumber	   
inner join kaverimrg.sromaster b on a.predistrictcode = b.districtcode 
inner join kaverimrg.districtmaster c on a.predistrictcode = c.districtcode
where fa.applicationnumber =_applicationnumber
	  ) data_json;
	  
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetchprintamendment(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetchprintamendment1(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetchprintamendment1(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
v_amendmenttypeid integer;
begin
	
select amendmenttypeid into v_amendmenttypeid  from kaverimrg.firmamendment 
where applicationnumber=_applicationnumber;
if v_amendmenttypeid=1 then  
select row_to_json(data_json) into v_data_json 
 -- from (select row_to_json(app_json) 
 from ( select  c.districtnamee,c.districtnamee as droffice,	
	   
 (select array_to_json(array_agg(row_to_json(Firmdetails)))
  from (select  distinct d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||
			' '||stat.statenamee||'-'||d.pincode as Address,	fa.amendpincode,
		count(distinct firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		fa.inserteddatetime::date as DateOfRegistration
			from kaverimrg.firmmaster d 
		--inner join kaverimrg.amendmentmaster am on am.finalregistrationnumber=d.finalregistrationnumber
		join kaverimrg.firmamendment fa on d.finalregistrationnumber=fa.finalregistrationnumber 
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber and fp.presentertypeid in (1,6)
		inner join kaverimrg.applicantapplicationdetails a on fa.applicationnumber  =a.applicationnumber
		inner join kaverimrg.wrkflowmaster wf on a.currentstatus =wf.wrkflowstatusid 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
		where fa.applicationnumber =_applicationnumber
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		fa.inserteddatetime,fa.amendpincode)Firmdetails) as Firmdetails,
	   
	   
	   	 (select array_to_json(array_agg(row_to_json(ChangenameFirmdetails)))
  from (select distinct  d.firmname as Newfirmname,
			d.amendhousebuildingname||' '||d.amendstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.amendpincode as NewfirmAddress	
		from kaverimrg.firmamendment d 
		--inner join kaverimrg.amendmentmaster am on am.applicationnumber=d.applicationnumber
		left join kaverimrg.districtmaster di on  d.amenddistrictcode=di.districtcode  
	    left join kaverimrg.talukmaster ta on  d.amendtalukacode=ta.talukcode 
		left join kaverimrg.hoblimaster ho on d.amendhoblicode =ho.hoblicode 
		left join kaverimrg.villagemaster vill on d.amendcityvillagecode =vill.villagecode 
		left join kaverimrg.statemaster stat on d.amendstatecode =stat.statecode 
			where d.applicationnumber =_applicationnumber)ChangenameFirmdetails) as ChangenameFirmdetails,
---------------	   
	   	   ( select array_to_json(array_agg(COALESCE(row_to_json(presenter_detils),
	   	   json_build_object(firstname,null,middlename,null,
	   	   lastname,null)))
	   	  )
from (select distinct  br.firstname,br.middlename,br.lastname, --pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID,
	  br.firmpersonid,br.presentertypeid
from kaverimrg.firmamendment  am 
left join kaverimrg.amendmentfirmparty  br on am.amendmentid=br.amendmentid
left join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where 
am.applicationnumber =_applicationnumber  and 
br.presentertypeid in (1,2))presenter_detils) as presenter_detils,

( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT distinct ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid 
   FROM kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.firmamendment f ON f.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 47 
and ad.applicationnumber =_applicationnumber ) fdasdafetch) as fdasdafetch,

 ( select array_to_json(array_agg(row_to_json(feesrequiredbyappl)))  from 
 ( SELECT distinct fr.feeruleid,fr.feedescription,fr.payableamount
   FROM kaverimrg.firmamendment f 
    left JOIN kaverimrg.firm_requiredfees fr  ON f.applicationnumber::text = fr.applicationnumber::text
   WHERE f.applicationnumber =_applicationnumber ) feesrequiredbyappl) as feesrequiredbyappl,
   
   ( select array_to_json(array_agg(row_to_json(remarks)))  from 
 ( SELECT distinct ar.firmdetailsremarks_fda_sda, 
ar.presenterdetailsremarks_fda_sda, 
ar.partnerdetailsremarks_fda_sda,
ar.witnessdetailsremarks_fda_sda,
ar.stampdutyandfeedetailsremarks_fda_sda,
ar.uploaddocumentremarks_fda_sda,
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.witnessdetailsremarks_dr,
ar.stampdutyandfeedetailsremarks_dr,
ar.canprocesstopaymentremarks_dr,
ar.uploaddocumentremarks_dr
   FROM 
    kaverimrg.firmamendment f 
    left join  kaverimrg.firmapplicationremarks ar  on f.applicationnumber::text = ar.applicationnumber::text
 WHERE f.applicationnumber =_applicationnumber
  ) remarks)as remarks,
	   
(select array_to_json(array_agg(row_to_json(firmwitness)))
	from (select   fe.firmwitnessid,fe.firstname||' '||fe.middlename||' '||fe.lastname as  witnessname,fe.witnessfathername,
fe.withousebuildname||' '||fe.witstreetname||' '||dis.districtnamee||' '||tal.taluknamee||' '||hob.hoblinamee||' '||vil.villagenamee||'-'||fe.witpincode as Address,age 
	from kaverimrg.frm_witnessdetails fe 
		  inner join kaverimrg.firmmaster f on f.applicationnumber=fe.applicationnumber
		  inner join kaverimrg.firmamendment a on a.finalregistrationnumber=f.finalregistrationnumber
	left join kaverimrg.districtmaster dis on fe.witdistrictcode  = dis.districtcode 
left join kaverimrg.talukmaster tal on fe.wittalukacode  = tal.talukcode 
left join kaverimrg.hoblimaster hob on fe.withoblicode  = hob.hoblicode 
left join kaverimrg.villagemaster vil on fe.witcityvillagecode  = vil.villagecode	  	  
	where a.applicationnumber =_applicationnumber)firmwitness) as firmwitness	   
from 
--kaverimrg.firmparty a 
	--   inner join kaverimrg.firmmaster fm on a.applicationnumber=fm.applicationnumber
--inner join kaverimrg.amendmentmaster fa on fm.finalregistrationnumber=fa.finalregistrationnumber	
kaverimrg.firmamendment fa  
--inner join kaverimrg.sromaster b on fa.drcode  = b.districtcode 
left join kaverimrg.districtmaster c on fa.drcode = c.districtcode
where fa.applicationnumber =_applicationnumber
	   
  ) data_json;
 
	  
return v_data_json;

else 

 return null;
end if;
END;
$$;


ALTER FUNCTION kaverimrg.fn_fetchprintamendment1(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_fetchprintamendment2(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_fetchprintamendment2(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
--from (select row_to_json(app_json) 
 from ( select  c.districtnamee,c.districtnamee as droffice,--,a.sfdaid ,a.applicationnumber ,a.applicationdate ,s.servicename,
	   
 (select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||
			' '||stat.statenamee||'-'||d.pincode as Address,	fa.amendpincode,
		count(distinct firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		fa.inserteddatetime::date as DateOfRegistration
			from kaverimrg.firmmaster d 
		--inner join kaverimrg.amendmentmaster am on am.finalregistrationnumber=d.finalregistrationnumber
		join kaverimrg.firmamendment fa on d.finalregistrationnumber=fa.finalregistrationnumber 
		left join kaverimrg.firmbranches f on d.applicationnumber ::text=f.applicationnumber::text 
		inner join kaverimrg.firmparty fp on d.applicationnumber::text=fp.applicationnumber::text and fp.presentertypeid in (1,6)
		inner join kaverimrg.applicantapplicationdetails a on fa.applicationnumber::text =a.applicationnumber::text
		inner join kaverimrg.wrkflowmaster wf on a.currentstatus =wf.wrkflowstatusid 
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
		where fa.applicationnumber =_applicationnumber
	   	group  by d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,a.currentstatus,wf.wrkflowstatusnamee,d.durationoffirm,d.finalregistrationnumber,
		fa.inserteddatetime,fa.amendpincode)Firmdetails) as Firmdetails,
		
	(select row_to_json(amendmentbranch)
  	from (select 
  	(select array_to_json(array_agg(row_to_json(branch_to_remove))) from 
		(select am.amendmentbranchid,
		am.branchid, 
		am.amendhousebuildingname||' '||am.amendstreetaddress||' '||dis.districtnamee||' '||tal.taluknamee||' '||--ho.hoblinamee||' '||vill.villagenamee||' '||
		stlgd.statenamee||'-'||am.amendpincode as branch_addres,am.dateofcommencement_discontinuation as dateofdiscontinuation
		from kaverimrg.amendmentfirmbranches am 
		left join kaverimrg.lgd_statemaster stlgd on am.amendstatecode  = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on am.amenddistrictcode  = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on am.amendtalukacode = tal.talukcode 
		where am.applicationnumber = _applicationnumber and am.isremoved= true order by amendmentbranchid desc
		
--		select am.amendmentbranchid,
--		am.branchid, 
--		am.amendhousebuildingname||' '||am.amendstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
--		stat.statenamee||'-'||am.amendpincode as branch_addres,am.dateofcommencement_discontinuation as dateofdiscontinuation
--		from kaverimrg.amendmentfirmbranches am 
--		left join kaverimrg.districtmaster di on am.amenddistrictcode = di.districtcode
--	    left join kaverimrg.talukmaster ta on am.amendtalukacode = ta.talukcode
--		left join kaverimrg.hoblimaster ho on am.amendhoblicode  = ho.hoblicode
--		left join kaverimrg.villagemaster vill on am.amendcityvillagecode  = vill.villagecode
--		left join kaverimrg.statemaster stat on am.amendstatecode = stat.statecode
--		where am.applicationnumber = _applicationnumber and am.isremoved= true
		) branch_to_remove) as branch_to_remove,
		
		(select array_to_json(array_agg(row_to_json(branch_to_add))) from 
		(select am.amendmentbranchid,
		am.branchid,
		am.amendhousebuildingname||' '||am.amendstreetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||am.amendpincode as branch_addres, am.dateofcommencement_discontinuation as dateofcommencement
		from kaverimrg.amendmentfirmbranches am 
		left join kaverimrg.districtmaster di on am.amenddistrictcode = di.districtcode
	    left join kaverimrg.talukmaster ta on am.amendtalukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on am.amendhoblicode  = ho.hoblicode
		left join kaverimrg.villagemaster vill on am.amendcityvillagecode  = vill.villagecode
		left join kaverimrg.statemaster stat on am.amendstatecode = stat.statecode
		where am.applicationnumber = _applicationnumber and am.isremoved= false order by amendmentbranchid desc) branch_to_add) as branch_to_add
		 )amendmentbranch) as amendmentbranch,	
	   	  	   
		( select row_to_json(presenter_detils)
	from (select br.firstname,br.middlename,br.lastname,br.amendmentpersonid,br.presentertypeid
	from kaverimrg.amendmentfirmparty br
	inner join kaverimrg.firmamendment  am on am.amendmentid=br.amendmentid
	inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
	where 
	am.applicationnumber =_applicationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,
	
	( select array_to_json(array_agg(row_to_json(amendremarks)))  from 
 ( SELECT ar.firmdetailsremarks_fda_sda, 
ar.presenterdetailsremarks_fda_sda, 
ar.partnerdetailsremarks_fda_sda,
ar.witnessdetailsremarks_fda_sda,
ar.stampdutyandfeedetailsremarks_fda_sda,
ar.uploaddocumentremarks_fda_sda,
ar.branchdetailsremarks_fda_sda,
ar.firmdetailsremarks_dr,
ar.presenterdetailsremarks_dr,
ar.partnerdetailsremarks_dr,
ar.witnessdetailsremarks_dr,
ar.stampdutyandfeedetailsremarks_dr,
ar.canprocesstopaymentremarks_dr,
ar.uploaddocumentremarks_dr,
ar.branchdetailsremarks_dr
   FROM kaverimrg.firmapplicationremarks ar 
     JOIN kaverimrg.firmamendment f on f.applicationnumber::text = ar.applicationnumber::text
  WHERE ar.applicationnumber =_applicationnumber) amendremarks) as amendremarks,
	
	( select array_to_json(array_agg(row_to_json(fdasdafetch)))  from 
 ( SELECT distinct ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    sm.servicename,ad.sfdaid
   FROM kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.firmamendment f ON f.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaverimrg.vw_department_users usr ON usr.userid = ad.sfdaid
     LEFT JOIN kaverimrg.servicesmaster sm ON ad.applicationtypeid = sm.serviceid
  WHERE ad.applicationtypeid = 47 
and ad.applicationnumber =_applicationnumber ) fdasdafetch) as fdasdafetch

		
from kaverimrg.firmamendment fa  
--inner join kaverimrg.sromaster b on fa.drcode  = b.districtcode
left join kaverimrg.applicantapplicationdetails a on a.applicationnumber::text = fa.applicationnumber::text 
left join kaverimrg.servicesmaster s on s.serviceid = a.applicationtypeid 
inner join kaverimrg.districtmaster c on fa.drcode = c.districtcode
where fa.applicationnumber =_applicationnumber--)app_json
	  ) data_json;
	  
return v_data_json;
END;
$$;


