-- Name: fn_firmbranches_log(); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_firmbranches_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin

    if tg_op = 'UPDATE' then
        insert into kaverimrg.firmbranches_log
		(
    username ,	action ,	query ,  
	branchid, registrationid, branchaddress, branchphone, addedon, oldaddress, changedate, fax, cell,
	drcode, branchhousebuildingname, branchstreetaddress, branchstatecode, branchdistrictcode, branchtalukacode,
	branchhoblicode, branchcityvillagecode, branchpincode, applicationnumber, branchstatus, dateofdiscontinuation,
	dateofcommencement, applicationtypeid, finalregistrationnumber, form_2path, amendbranchsignedformpath,
	addressproofid, addressproofpath, proofofauthorisationfortheagentid, proofofauthorisationfortheagentpath, supporting_document1_path,
	supporting_document2_path
	)
		
	 values (current_user::text||' 2'||session_user::text, 'Updated', current_query(),
	 old.branchid, old.registrationid, old.branchaddress, old.branchphone, old.addedon, old.oldaddress, old.changedate, old.fax, old.cell,
	old.drcode, old.branchhousebuildingname, old.branchstreetaddress, old.branchstatecode, old.branchdistrictcode, old.branchtalukacode,
	old.branchhoblicode, old.branchcityvillagecode, old.branchpincode, old.applicationnumber, old.branchstatus, old.dateofdiscontinuation,
	old.dateofcommencement, old.applicationtypeid, old.finalregistrationnumber, old.form_2path, old.amendbranchsignedformpath,
    old.addressproofid, old.addressproofpath, old.proofofauthorisationfortheagentid, old.proofofauthorisationfortheagentpath, 
	old.supporting_document1_path, old.supporting_document2_path
	); return new;	
		
	elsif tg_op = 'DELETE' then
       insert into kaverimrg.firmbranches_log
		(
   username ,	action ,	query ,  
	branchid, registrationid, branchaddress, branchphone, addedon, oldaddress, changedate, fax, cell,
	drcode, branchhousebuildingname, branchstreetaddress, branchstatecode, branchdistrictcode, branchtalukacode,
	branchhoblicode, branchcityvillagecode, branchpincode, applicationnumber, branchstatus, dateofdiscontinuation,
	dateofcommencement, applicationtypeid, finalregistrationnumber, form_2path, amendbranchsignedformpath,
	addressproofid, addressproofpath, proofofauthorisationfortheagentid, proofofauthorisationfortheagentpath, supporting_document1_path,
	supporting_document2_path
	)
		
	 values (current_user::text||' 2'||session_user::text, 'Deleted', current_query(),
	  old.branchid, old.registrationid, old.branchaddress, old.branchphone, old.addedon, old.oldaddress, old.changedate, old.fax, old.cell,
	old.drcode, old.branchhousebuildingname, old.branchstreetaddress, old.branchstatecode, old.branchdistrictcode, old.branchtalukacode,
	old.branchhoblicode, old.branchcityvillagecode, old.branchpincode, old.applicationnumber, old.branchstatus, old.dateofdiscontinuation,
	old.dateofcommencement, old.applicationtypeid, old.finalregistrationnumber, old.form_2path, old.amendbranchsignedformpath,
	old.addressproofid, old.addressproofpath, old.proofofauthorisationfortheagentid, old.proofofauthorisationfortheagentpath, 
	old.supporting_document1_path, old.supporting_document2_path
	); return old;
    
	elsif tg_op = 'INSERT' then
	
	insert into kaverimrg.firmbranches_log 
		(
   username ,	action ,	query ,  
	branchid, registrationid, branchaddress, branchphone, addedon, oldaddress, changedate, fax, cell,
	drcode, branchhousebuildingname, branchstreetaddress, branchstatecode, branchdistrictcode, branchtalukacode,
	branchhoblicode, branchcityvillagecode, branchpincode, applicationnumber, branchstatus, dateofdiscontinuation,
	dateofcommencement, applicationtypeid, finalregistrationnumber, form_2path, amendbranchsignedformpath,
	addressproofid, addressproofpath, proofofauthorisationfortheagentid, proofofauthorisationfortheagentpath, supporting_document1_path,
	supporting_document2_path
	)
        	 values (current_user::text||' 2'||session_user::text, 'Inserted', current_query(),
	 new.branchid, new.registrationid, new.branchaddress, new.branchphone, new.addedon, new.oldaddress, new.changedate, new.fax, new.cell,
	new.drcode, new.branchhousebuildingname, new.branchstreetaddress, new.branchstatecode, new.branchdistrictcode, new.branchtalukacode,
	new.branchhoblicode, new.branchcityvillagecode, new.branchpincode, new.applicationnumber, new.branchstatus, new.dateofdiscontinuation,
	new.dateofcommencement, new.applicationtypeid, new.finalregistrationnumber, new.form_2path, new.amendbranchsignedformpath,
	new.addressproofid, new.addressproofpath, new.proofofauthorisationfortheagentid, new.proofofauthorisationfortheagentpath, 
	new.supporting_document1_path, new.supporting_document2_path
	); return new;
	
   end if;
end;
$$;


ALTER FUNCTION kaverimrg.fn_firmbranches_log() OWNER TO postgres;

--
-- Name: fn_firmcheckandregisterstatus(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_firmcheckandregisterstatus(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

BEGIN

	update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR115' 
     where ad.applicationnumber = _applicationnumber and applicationtypeid=6 ;
    
    update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FA113' 
     where ad.applicationnumber = _applicationnumber and applicationtypeid=47 ;
    
    update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC115' 
     where ad.applicationnumber = _applicationnumber and applicationtypeid=48 ;
	 
	    update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FD115' 
     where ad.applicationnumber = _applicationnumber and applicationtypeid=49; 
		 
return _applicationnumber;
		 
END;
$$;


ALTER FUNCTION kaverimrg.fn_firmcheckandregisterstatus(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_firmregistrationcompleted(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_firmregistrationcompleted(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

declare

v_applicationtype integer;
v_success boolean;
v_finalregistrationnumber character varying;

begin
	v_success:=false;
	select ad.applicationtypeid   into v_applicationtype 
	from kaverimrg.applicantapplicationdetails ad 
 	where ad.applicationnumber = _applicationnumber; 
 
 if v_applicationtype=6 then  --Firm Registration

	update kaverimrg.ApplicantApplicationdetails ad 
	set currentstatus='FR118',
	applicationenddate=current_date
	where ad.applicationnumber = _applicationnumber
	returning true into v_success; 
    
    update kaverimrg.firmmaster fm  
    set isregistrationcompleted=true ,
    dateofregistration=current_date
    where fm.applicationnumber = _applicationnumber
    returning true into v_success;
    
  elsif v_applicationtype=47 then  --Firm amendment
  
  		update kaverimrg.ApplicantApplicationdetails ad
	 	set currentstatus='FA127' ,
	 	applicationenddate=current_date
	   	where ad.applicationnumber = _applicationnumber
	    returning true into v_success;     
    
    	update kaverimrg.firmamendment  fa  
			set isamendmentcompleted=true ,
    	amendmentdatetime=current_date
    	 where fa.applicationnumber = _applicationnumber
    	returning true into v_success; 
    
  
  elsif v_applicationtype=48 then  --Firm Reconstitution
  
  		update kaverimrg.ApplicantApplicationdetails ad
	 	set currentstatus='FC121' ,
	 	applicationenddate=current_date
	    where ad.applicationnumber = _applicationnumber
	   returning true into v_success;  
    
    
    
   	 	update kaverimrg.firmreconstitution  fc  
   		 set isreconstitutioncompleted=true ,
    	reconstitutionenddate=current_date
    	 where fc.applicationnumber = _applicationnumber
    	returning true into v_success; 
  
  elsif v_applicationtype=49 then  --Firm Dissolution
  
  		update kaverimrg.ApplicantApplicationdetails ad
	 	set currentstatus='FD120' ,
	 	applicationenddate=current_date
	    where ad.applicationnumber = _applicationnumber
	   returning true into v_success;  
	   
   		 update kaverimrg.firm_dissolution  fd  
    	  set isdissolutioncompleted =true ,
   		 applicationcompleteddate =current_date
    	 where fd.applicationnumber = _applicationnumber
    	 returning true into v_success; 
		 
		select finalregistrationnumber into v_finalregistrationnumber from kaverimrg.firm_dissolution 
		where applicationnumber =_applicationnumber;
		
		  update kaverimrg.firmmaster f  
    	 set isactive =false
    	 where f.finalregistrationnumber = v_finalregistrationnumber
    	 returning true into v_success; 
  
  
  end if;
    
	if v_success=true then 	 
	return _applicationnumber;
	else 
	return null;
	end if;
		 
END;
$$;


ALTER FUNCTION kaverimrg.fn_firmregistrationcompleted(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_get_applicationreview_details_sro(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_get_applicationreview_details_sro(p_applicationnumber character varying) RETURNS TABLE(applicationnumber character varying, currentstatus character varying, srocode integer, reviewid integer, reviewname text, issroapprove boolean, sroremarks text, deptuserid integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
  
  select ad.applicationnumber,ad.currentstatus,ad.srocode
,ad.reviewid,ad.reviewname,ar.isverified,ar.remarks,ar.deptuserid 
from 
	(select a.applicationnumber,a.currentstatus,a.srocode,arm.reviewid,arm.reviewname
		from kaverimrg.applicantapplicationdetails a,
		kaverimrg.applicationreviewmaster arm where a.applicationnumber= p_applicationnumber
	 ) ad 
left join 
		(select arr.applicationnumber,arr.reviewid,arr.isverified,arr.remarks,arr.deptuserid,arr.crtdate 
		from kaverimrg.applicationreviewdetails arr 
		where coalesce(arr.issroremarks,'true')='true' and 
      arr.applicationnumber = p_applicationnumber and 
	  arr.crtdate = (select max(crtdate) from kaverimrg.applicationreviewdetails rd 
					where rd.applicationnumber=arr.applicationnumber 
					 and rd.reviewid =arr.reviewid))ar
					 
on 
		(ar.applicationnumber = ad.applicationnumber 
		and ad.reviewid = ar.reviewid)
where 
		ad.applicationnumber= p_applicationnumber ;
END;
$$;


ALTER FUNCTION kaverimrg.fn_get_applicationreview_details_sro(p_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_get_login_details1(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_get_login_details1(p_login_name text) RETURNS TABLE(userid bigint, loginname text, srocode integer, username text, designationid integer, designame character varying, mobile bigint, active boolean, sroname text, sronamek text, districtcode integer, districtname character varying, passwrd text, rolesinfo json)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
 select du.userid,
 du.loginname,
 mofm.kaverimrgcode::integer  as srocode,
 du.firstname||' '||du.lastname as username,
  du.designationid,
  dm.designame::character varying ,
  du.mobileno as mobile,du.serviceflag as active,
 mofm.officename  as sroname,
 mofm.officenamer  as sronamek,
 di.districtcode,
  di.districtnamee as districtname,du.passwd,
  (  select array_to_json(array_agg(row_to_json(roles)))
      from (select 0 as userroleId, du.designationid,du.userid as mappeduserid, dm.designame::character varying,
	  'Default' as rolename,du.srocode as mappedsroid,sr.sronamee as sroname,sr.sronamek as sronamek
			union all
			select rl.userroleid as userroleId, rl.designationid,rl.mappeduserid as mappeduserid,dmrl.designame::character varying,
			dmrl.designame::character varying as rolename,rl.mappedsroid as mappedsroid,sr.sronamee as sroname,sr.sronamek as sronamek
			from kaverimrg.departmentuserroles rl 
			left join kaverimrg.sromaster sr on (sr.srocode=rl.mappedsroid)
			inner join kaverimrg.desigmaster dmrl on (rl.designationid = dmrl.designationid)
where du.userid = rl.userid ) roles
	) as rolesinfo
from kaverimrg.departmentusers du
inner join kaverimrg.desigmaster dm on (du.designationid = dm.designationid)
left join kaverimrg.mas_officemaster mofm on du.officeid=mofm.officeid 
left join kaverimrg.districtmaster di on (mofm.districtid =di.districtcode)
left join kaverimrg.sromaster sr on du.srocode=sr.srocode
where du.serviceflag= 'true' and du.loginname= p_login_name;
END;
$$;


ALTER FUNCTION kaverimrg.fn_get_login_details1(p_login_name text) OWNER TO postgres;

--
-- Name: fn_get_login_details_backup_20_07_2023(text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_get_login_details_backup_20_07_2023(p_login_name text) RETURNS TABLE(userid bigint, loginname text, srocode integer, username text, designationid integer, designame character varying, mobile bigint, active boolean, sroname character varying, sronamek character varying, districtcode integer, districtname character varying, passwrd text, rolesinfo json)
    LANGUAGE plpgsql
    AS $$

BEGIN
   RETURN QUERY
 select du.userid, du.loginname,case when du.designationid =5 then sr.districtcode else du.srocode end
  as srocode,du.firstname||' '||du.lastname as username,
  du.designationid,dm.designame::character varying ,du.mobileno as mobile,du.serviceflag as active,
  case when du.designationid =5 then di.districtnamee else sr.sronamee end as sroname,
  case when du.designationid =5 then di.districtnamek else sr.sronamek end as sronamek,
  sr.districtcode,
  di.districtnamee as districtname,du.passwd,
  (  select array_to_json(array_agg(row_to_json(roles)))
      from (select 0 as userroleId, du.designationid,du.userid as mappeduserid, dm.designame::character varying, 'Default' as rolename,
			case when du.designationid =5 then sr.districtcode else du.srocode end as mappedsroid,
			case when du.designationid =5 then di.districtnamee else sr.sronamee end as sroname,
			case when du.designationid =5 then di.districtnamek else sr.sronamek end as sronamek
			--du.srocode as mappedsroid,
			--sr.sronamee as sroname,
			--sr.sronamek as sronamek
			union all
			select rl.userroleid as userroleId, rl.designationid,rl.mappeduserid as mappeduserid,dmrl.designame::character varying,dmrl.designame::character varying as rolename,rl.mappedsroid as mappedsroid,sr.sronamee as sroname,sr.sronamek as sronamek
			from kaverimrg.departmentuserroles rl 
			left join kaverimrg.sromaster sr on (sr.srocode=rl.mappedsroid)
			left join kaverimrg.districtmaster di on (sr.districtcode=di.districtcode)
			inner join kaverimrg.desigmaster dmrl on (rl.designationid = dmrl.designationid)
where du.userid = rl.userid ) roles
	) as rolesinfo
from kaverimrg.departmentusers du
inner join kaverimrg.desigmaster dm on (du.designationid = dm.designationid)
left join kaverimrg.sromaster sr on (sr.srocode=du.srocode)
left join kaverimrg.districtmaster di on (sr.districtcode=di.districtcode)
where du.serviceflag= 'true' and du.loginname= p_login_name;
END;
$$;


ALTER FUNCTION kaverimrg.fn_get_login_details_backup_20_07_2023(p_login_name text) OWNER TO postgres;

--
-- Name: fn_ins_propertymaster_dupe(character varying, character varying, boolean, bigint, bigint, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_ins_propertymaster_dupe(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_valheaderid bigint;
	v_applicationnumber character varying;
	v_ary_propertyid bigint[];
	v_propertyid_reference bigint;
	v_propertyid bigint;
	v_ary_partyid bigint[];
	v_partyid_reference bigint;
	v_partyid bigint;
	v_mutation_partyid bigint;
	v_swap boolean;
	
	v_bookid   integer ;
	v_srocode integer ; 
	v_registrationdatetime timestamp without time zone;
	v_docid character varying;
	v_regdatetime character varying;
BEGIN 
	select applicationnumber,documentid,to_char(registrationdatetime::date,'DDMMYYYY')::text into v_applicationnumber,v_docid,v_regdatetime
	from kaverimrg.documentmaster 
	where finalregistrationnumber = p_finalregnum;

--	select documentid into v_docid
--	from kaverimrg.documentmaster 
--	where finalregistrationnumber = p_finalregnum;
--	
--		select registrationdatetime::date  into v_applicationnumber,v_docid,v_regdatetime
--	from kaverimrg.documentmaster 
--	where finalregistrationnumber = p_finalregnum;


	if p_stampruleid in (281,278,273,284,164) then 
	v_swap = false;
	else
	v_swap = true;
	end if;
	
	if (v_applicationnumber is not null and v_applicationnumber <> '') then 
	
	select array_agg(propertyid) into v_ary_propertyid from kaverimrg.propertymaster 
	where applicationnumber = v_applicationnumber;
	
	if (v_ary_propertyid is not null and array_length(v_ary_propertyid,1)>0) then
		 FOReach v_propertyid_reference IN array v_ary_propertyid--(SELECT kaverimrg.fn_fetch_1d_arrayofarray(v_partyid)) 
					loop
				begin
				
				insert into kaverimrg.propertymaster 
					(propertyid, documentid,applicationnumber,referencepropertyid, villagecode, regsrocode, 
					 srocode, totalarea, unitid, northboundary, southboundary,
			eastboundary, westboundary, landmark, marketvalue, assessment, sdcalculationstring, stampduty, transferliabilities,
			consideration, additionalduty, cessduty, govtduty, isexempted, exemptiondescription, ismovableproperty, sdrefund,
			docmarketvalue, valid1, isimdemnified, restriction, restrictiontype, restrictiondescription, enumber, claimingblocknumber, 
			retainingblocknumber, valuationreport, loanpurposeid, verified, issroapproved, stamparticlecode,
			stampruleid, regarticlecode, propertytypeid, noofscanpages, movablepropertydesc, roadcode, wardid, pidno, udeptid, 
			sfdastamparticlecode, sfdastampruleid, sfdanoofscanpages, srostamparticlecode, srostampruleid, sronoofscanpages, 
			sfdamarketvalue, sromarketvalue, ownedarea, sfdanatureofdocument, sronatureofdocument, denodescription, 
			estampdescription, adjudescription, sroconsideration, sfdaconsideration,inserteddatetime)
				select nextval('kaverimrg.propertymastersequence_seq'),0,p_applicationnum,v_propertyid_reference,villagecode, regsrocode,
				srocode, totalarea, unitid, northboundary, southboundary,
			eastboundary, westboundary, landmark, marketvalue, assessment, p_finalregnum, stampduty, transferliabilities,
			consideration, additionalduty, cessduty, govtduty, isexempted, exemptiondescription, ismovableproperty, sdrefund,
			docmarketvalue, valid1, isimdemnified, restriction, restrictiontype, restrictiondescription, enumber, claimingblocknumber, 
			retainingblocknumber, valuationreport, loanpurposeid, verified, issroapproved, p_stamparticlecode,
			p_stampruleid, p_regarticlecode, propertytypeid, noofscanpages, movablepropertydesc, roadcode, wardid, pidno, udeptid, 
			sfdastamparticlecode, sfdastampruleid, sfdanoofscanpages, srostamparticlecode, srostampruleid, sronoofscanpages, 
			sfdamarketvalue, sromarketvalue, ownedarea, sfdanatureofdocument, sronatureofdocument, denodescription, 
			estampdescription, adjudescription, sroconsideration, sfdaconsideration , current_timestamp
			from kaverimrg.propertymaster where propertyid = v_propertyid_reference 
			  RETURNING propertyid::bigint into v_propertyid;
			
			insert into kaverimrg.propertynumberdetails 
				(propertyid, srocode, currentpropertytypeid, currentnumber, oldpropertytypeid, oldnumber, description, 
				survey_no, surnoc, hissa_no )
			select v_propertyid, srocode, currentpropertytypeid, currentnumber, oldpropertytypeid, oldnumber, description, 
				survey_no, surnoc, hissa_no from kaverimrg.propertynumberdetails where propertyid = v_propertyid_reference ;

			insert into kaverimrg.propertyschedules 
				(propertyid,applicationnumber, srocode, partyid, scheduletype, totalarea, unitid, description, partyids, 
				aileniatedauthorityid, alieniatedorder, bhoomisellerpartyids, govtrestricorder, govtrestrictionid, landcode, 
				propertygroup, giftshare, giftsharedetails, easttowest, northtosouth, blockchainpropertyid, assignedblockchainpid,
				verified, issroapproved, eastboundary, westboundary, northboundary, southboundary)
			SELECT  v_propertyid,p_applicationnum, srocode, partyid, scheduletype, totalarea, unitid, description, partyids, 
				aileniatedauthorityid, alieniatedorder, bhoomisellerpartyids, govtrestricorder, govtrestrictionid, landcode, 
