ALTER FUNCTION kaverimrg.fn_ins_propertymaster_dupe(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) OWNER TO postgres;

--
