CREATE FUNCTION kaverimrg.fn_ins_propertymaster_dupe_tst(p_finalregnum character varying, p_applicationnum character varying, p_mutationflag boolean, p_regarticlecode bigint, p_stamparticlecode bigint, p_stampruleid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_valheaderid bigint;
	v_applicationnumber character varying;
