	select p.stampduty into v_stampduty from kaverimrg.propertymaster p where p.propertytypeid in (17) and p.sdcalculationstring =p_finalregnum limit 1;
	
	if p_stampruleid in (281,278,273,284,164) then 
	v_swap = false;
	else
	v_swap = true;
	end if;
	
