			 	select array_agg(partyid) into v_ary_partyid from kaverimrg.partyinfo 
	where applicationnumber = v_applicationnumber and linkpartyid is null;
	
		if (v_ary_partyid is not null and array_length(v_ary_partyid,1)>0) then
