isendorseprinted, thumbremarks
	FROM kaverimrg.partyinfo where partyid = v_partyid_reference 
	returning partyid into v_partyid;
	
	update kaverimrg.partyinfo pi set propertyid = (select propertyid from kaverimrg.propertymaster 
	where referencepropertyid = pi.propertyid and inserteddatetime between (current_timestamp - interval '10 seconds') and (current_timestamp + interval '10 seconds')) where pi.partyid=v_partyid;
	
	 insert into kaverimrg.partyinfo
			 (partyid,applicationnumber,documentid,partyidreference, partytypeid,  srocode,firstname, 
			  middlename, lastname, address, age, sex, isexecutor, 
ispresenter, admissiondate, aliasname, correctedname, relationship, relativename, epic, pan, phonenumber, 
