propertyid, propertynumber, idprooftypeid, isconsentwitness, isprivateattendance, coveringletterno, section88file,
isendorseprinted, thumbremarks)
			 SELECT nextval('kaverimrg.partyinfo_partyid_seq'),p_applicationnum,0,partyid, 
