    _middlename character varying(50),
    _lastname character varying(50),
    _mothersalutation smallint,
    _motherfirstname character varying(100),
    _mothermiddlename character varying(100),
    _motherlastname character varying(100),
    _fathersalutation smallint,
    _fatherfirstname character varying(100),
    _fathermiddlename character varying(100),
    _fatherlastname character varying(100),
    _sex character varying(1),
    _prehousebuildname character varying(80),
