CREATE TABLE kaverimrg.val_apartmentamenitydetails2_input (
    _amenetiesdetailsid bigint,
    _apartmentamenetyruleid smallint,
    _rate numeric(20,4),
    _valuationid bigint,
    _verified boolean,
    _srocode integer,
    _regsrocode integer
);


ALTER TABLE kaverimrg.val_apartmentamenitydetails2_input OWNER TO postgres;

--
-- Name: fn_insert_apartmentamenitydetails(kaverimrg.val_apartmentamenitydetails2_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_apartmentamenitydetails(p_apt_rev kaverimrg.val_apartmentamenitydetails2_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
Declare
   v_apartment_arry kaverimrg.val_apartmentamenitydetails2_input[];
     v_cnt integer;
   v_valid bigint;
   v_pid bigint[];
begin

	if(p_apt_rev is not null and array_length(p_apt_rev,1)>0 ) then
		FOR v_apartment_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_apt_rev)) 
			loop
				v_cnt:= 0;
				Select count(*) into v_cnt from kaverimrg.val_apartmentamenitydetails b,kaverimrg.mas_val_apartmentspecialamenetyrules c where amenetiesdetailsid in 
						(select a._amenetiesdetailsid from unnest(v_apartment_arry) a) and b.apartmentamenetyruleid = c.apartmentamenetyruleid;
				 if v_cnt = 0 then
				insert into kaverimrg.val_apartmentamenitydetails (
								amenetiesdetailsid,
    							apartmentamenetyruleid,
    							rate,
    							valuationid,
    							verified,
    							srocode,
    							regsrocode
								)
								select 
								 nextval('kaverimrg.val_apartmentamenitydetails_seq'),
								_apartmentamenetyruleid,
    							_rate,
    							_valuationid,
    							_verified,
    							_srocode,
    							_regsrocode
								from unnest(v_apartment_arry)	
								 returning valuationid::bigint into v_valid;
							else
								update kaverimrg.val_apartmentamenitydetails set
										--apartmentamenetyruleid=a._apartmentamenetyruleid,
    										rate=a._rate,
    										valuationid=a._valuationid,
    										verified=a._verified,
    										srocode=a._srocode,
    										regsrocode=a._regsrocode
												 from unnest(v_apartment_arry ) a where amenetiesdetailsid in 
														 (select a._amenetiesdetailsid from unnest(v_apartment_arry ) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						 v_pid := array_append(v_pid,v_valid);
					end loop;
				end if;
			return v_pid;
   END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_apartmentamenitydetails(p_apt_rev kaverimrg.val_apartmentamenitydetails2_input[]) OWNER TO postgres;

