--

CREATE FUNCTION kaverimrg.fn_insert_application_auditentry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
V_ACTIVITYORDER INTEGER DEFAULT 0;
BEGIN
SELECT COALESCE(MAX(ACTIVITYORDER),0)+1 INTO V_ACTIVITYORDER FROM kaverimrg.ApplicationAudit
WHERE applicationnumber = NEW.applicationnumber;
         INSERT INTO kaverimrg.ApplicationAudit(applicationnumber,srocode,wrkflowstatusid,activityby,ACTIVITYORDER,remarks)
         VALUES(NEW.applicationnumber,new.srocode,new.currentstatus,new.lastupdatedby,V_ACTIVITYORDER,new.remarks);
 
    RETURN NEW;
END;
$$;


