--

CREATE TABLE kaverimrg.application_reviewdetails_input (
    _reviewid integer,
    _applicationnumber character varying(50),
    _issroapprove boolean,
    _sroremarks text,
    _deptuserid integer
);


ALTER TABLE kaverimrg.application_reviewdetails_input OWNER TO postgres;

--
-- Name: fn_insert_appreviewdetails(kaverimrg.application_reviewdetails_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_appreviewdetails(kaverimrg.application_reviewdetails_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
   party_arry $1%type;
   v_applicationnumber text;
   v_issro boolean default null;
   v_srocnt bigint default 0;
BEGIN
   FOR party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray($1))    
	loop
	if(v_srocnt = 0 and v_issro is null) then 
		select count(*) into v_srocnt from kaverimrg.vw_department_users
		where userid in ( SELECT _deptuserid FROM unnest(party_arry)) and designationid in (1) ;
		if v_srocnt > 0 then
			v_issro = 'true';
		else
			v_issro = 'false';
		end if;
	end if;
	
	  INSERT INTO kaverimrg.applicationreviewdetails (reviewid,applicationnumber,isverified,remarks,deptuserid,issroremarks)
	  SELECT _reviewid,_applicationnumber,_issroapprove,_sroremarks,_deptuserid,v_issro FROM unnest(party_arry)
	  RETURNING applicationnumber::TEXT INTO v_applicationnumber;
     END LOOP;
   return v_applicationnumber;
END;
$_$;


