CREATE TABLE kaverimrg.application_verification_input (
    _applicationnumber character varying(100),
    _eval_presentor boolean,
    _eval_executiondate boolean,
    _eval_partydetails boolean,
    _eval_scheduleid boolean,
    _eval_voluntaryexec boolean,
    _eval_docclasstype boolean,
    _eval_valuationduty boolean,
    _eval_payment boolean,
    _eval_requireddocuments boolean,
    _eval_deedattachment boolean,
    _eval_attestation boolean,
    _eval_executantsbeforeme boolean,
    _eval_annexure boolean
);


ALTER TABLE kaverimrg.application_verification_input OWNER TO postgres;

--
-- Name: fn_insert_appverification(kaverimrg.application_verification_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_appverification(p_verification kaverimrg.application_verification_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_applicationnumber text;
   v_cnt bigint default 0;
BEGIN
  
update kaverimrg.APPLICATIONVERIFICATION set
	eval_Presentor = a._eval_Presentor,
    eval_executiondate   = a._eval_executiondate,
    eval_partydetails  = a._eval_partydetails,
    eval_scheduleid  = a._eval_scheduleid,
	eval_voluntaryexec  = a._eval_voluntaryexec,
	eval_docclasstype  = a._eval_docclasstype,
	eval_valuationduty  = a._eval_valuationduty,
	eval_payment  = a._eval_payment,
	eval_requireddocuments  = a._eval_requireddocuments,
	eval_deedattachment  = a._eval_deedattachment,
	eval_attestation  = a._eval_attestation,
	eval_executantsbeforeme =a._eval_executantsbeforeme ,
	eval_annexure =a._eval_annexure
			from unnest(p_verification) a
		 where applicationnumber= a._applicationnumber
		 returning applicationnumber into v_applicationnumber;
		 
if(v_applicationnumber is null or v_applicationnumber = '') then 
insert into kaverimrg.APPLICATIONVERIFICATION (
	applicationnumber,eval_Presentor,eval_executiondate,eval_partydetails ,
    eval_scheduleid ,eval_voluntaryexec,eval_docclasstype,eval_valuationduty ,
	eval_payment ,eval_requireddocuments,eval_deedattachment,eval_attestation,eval_executantsbeforeme,eval_annexure) 
	select _applicationnumber,_eval_Presentor,_eval_executiondate,_eval_partydetails ,
    _eval_scheduleid ,_eval_voluntaryexec,_eval_docclasstype,_eval_valuationduty ,
	_eval_payment ,_eval_requireddocuments,_eval_deedattachment,_eval_attestation,_eval_executantsbeforeme,_eval_annexure from unnest(p_verification) 
	returning applicationnumber into v_applicationnumber;
end if;
		 
   return v_applicationnumber;
END;
$$;


