--
-- Name: fn_insert_cc_applicationdetails(bigint, timestamp without time zone, bigint, smallint, integer, integer, character varying, smallint, character varying, integer, numeric, boolean, smallint, bigint, timestamp without time zone, smallint, smallint, kaverimrg.cc_requiredfees_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_cc_applicationdetails(_ccid bigint, _ccdate timestamp without time zone, _userid bigint, _documenttype smallint, _kaverimrgdrocode integer, _kaverimrgsrocode integer, _documentnumber character varying, _booktype smallint, _yearofregistration character varying, _pagecount integer, _totalamount numeric, _isappliedforsignedcopy boolean, _documentstatusid smallint, _submittedby bigint, _submitteddatetime timestamp without time zone, _marriagetypeid smallint, _firmtypeid smallint, p_ccrequiredfees kaverimrg.cc_requiredfees_input[]) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
v_ccid bigint;
v_cnt integer;
v_shortnamee text;
v_nomenclature text;
v_scheduletype text;
v_finyear text;
v_applicationnumber text;
_inserted_id text;
l_now text;
 v_ccrequiredfees p_ccrequiredfees%type;
  v_pid bigint[];
begin
select count(*) into v_cnt from kaverimrg.cc_applicationdetails where ccid = _ccid;
/*select shortnamee into v_shortnamee from kaverimrg.sromaster where srocode = _kaverimrgsrocode;
select nomenclature into v_nomenclature from kaverimrg.servicesmaster where serviceid = 12;
select distinct scheduletype into v_scheduletype from kaverimrg.propertyschedules where scheduletype = _scheduletype;
select lpad(nextval('kaverimrg.cc_applicationnumber_seq')::text,5,'0') into _inserted_id;
select cast(to_char(now(),'YYYY')as bigint)-1 ||'-'|| cast(to_char(now(),'YY')as bigint) into l_now;
v_applicationnumber := v_shortnamee  ||'-'||v_nomenclature ||'-'||_scheduletype ||'-'||_inserted_id||'-'||l_now;*/

select lpad(nextval('kaverimrg.tmp_applicationnumber_seq')::text,5,'0') into _inserted_id;
v_applicationnumber := 'TMPCC-'||_inserted_id;

if v_cnt = 0 then
insert into kaverimrg.cc_applicationdetails (
       ccid,
   -- ccnumber,
    ccdate,
    userid,
    documenttype,
    kaverimrgdrocode,
    kaverimrgsrocode,
    documentnumber,
    booktype,
    yearofregistration,
    pagecount,
    totalamount,
    isappliedforsignedcopy,
    documentstatusid,
    submittedby,
    submitteddatetime,
/*    preparedby,
    prepareddatetime,
    signedby,
    signeddatetime,
    appliedsignedcopy,
    comparedby,
    compareddatetime,
    certificatenumber,
    accepteddatetime,*/
    marriagetypeid,
    firmtypeid,
	applicationnumber
) values
(
nextval('kaverimrg.cc_applicationdetails_seq'),
  -- _ccnumber,
    _ccdate,
    _userid,
    _documenttype,
    _kaverimrgdrocode,
    _kaverimrgsrocode,
    _documentnumber,
    _booktype,
    _yearofregistration,
    _pagecount,
    _totalamount,
    _isappliedforsignedcopy,
    _documentstatusid,
    _submittedby,
    _submitteddatetime,
   /* _preparedby,
    _prepareddatetime,
    _signedby,
    _signeddatetime,
    _appliedsignedcopy,
    _comparedby,
    _compareddatetime,
    _certificatenumber,
    _accepteddatetime,*/
    _marriagetypeid,
    _firmtypeid,
	v_applicationnumber
) returning ccid::bigint into v_ccid;
else
update kaverimrg.cc_applicationdetails set 
	  -- ccnumber=_ccnumber,
    ccdate=_ccdate,
    userid=_userid,
    documenttype=_documenttype,
    kaverimrgdrocode=_kaverimrgdrocode,
    kaverimrgsrocode=_kaverimrgsrocode,
    documentnumber=_documentnumber,
    booktype=_booktype,
    yearofregistration=_yearofregistration,
    pagecount=_pagecount,
    totalamount=_totalamount,
    isappliedforsignedcopy=_isappliedforsignedcopy,
    documentstatusid=_documentstatusid,
    submittedby=_submittedby,
    submitteddatetime=_submitteddatetime,
   /* preparedby=_preparedby,
    prepareddatetime=_prepareddatetime,
    signedby=_signedby,
    signeddatetime=_signeddatetime,
    appliedsignedcopy=_appliedsignedcopy,
    comparedby=_comparedby,
    compareddatetime=_compareddatetime,
    certificatenumber=_certificatenumber,
    accepteddatetime=_accepteddatetime,*/
    marriagetypeid=_marriagetypeid,
    firmtypeid=_firmtypeid
	--applicationnumber=v_applicationnumber
	where ccid = _ccid returning ccid::bigint into v_ccid;
       -- v_pid := array_append(v_pid,v_ccid);
	  -- v_pid := array_append(v_pid,v_applicationnumber);
	end if;
	
	

/* Fees Required */
	if(p_ccrequiredfees is not null and array_length(p_ccrequiredfees,1)>0 ) then
FOR v_ccrequiredfees IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_ccrequiredfees))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaverimrg.cc_requiredfees where requiredfeeid in 
(select a._requiredfeeid from unnest(v_ccrequiredfees) a) ;
if v_cnt = 0 then 
INSERT INTO kaverimrg.cc_requiredfees( 
     requiredfeeid,
    ccid,
    feeruleid,
    payableamount,
    ispaid,
    serviceid,
    feedescription
)
	select nextval('kaverimrg.cc_requiredfees_seq'),
   v_ccid,
  a._feeruleid,
a._payableamount,
a._ispaid,
a._serviceid,
a._feedescription
from unnest(v_ccrequiredfees) a	
	 returning ccid::bigint into v_ccid;
	 else
	 update kaverimrg.cc_requiredfees set
	 ccid=v_ccid,
   feeruleid=a._feeruleid,
   payableamount=a._payableamount,
   ispaid=a._ispaid,
   serviceid=a._serviceid,
   feedescription=a._feedescription
	from unnest(v_ccrequiredfees) a where requiredfeeid in 
			 (select a._requiredfeeid from unnest(v_ccrequiredfees) a) 
			 RETURNING ccid::bigint into v_ccid;
	 end if;
--v_pid := array_append(v_pid,v_ccid);
--v_pid := array_append(v_pid,v_applicationnumber);
	end loop;
       end if;
	update kaverimrg.applicantapplicationdetails set currentstatus = 'CC106',
APPLICATIONDATE = current_timestamp where applicationnumber = v_applicationnumber;
 Return v_applicationnumber;
end;
$$;


