CREATE FUNCTION kaverimrg.fn_insert_cc_cscapplicantdetails(_cscapplicantid bigint, _firstname character varying, _middlename character varying, _lastname character varying, _address character varying, _pincode character varying, _mobilenumber character varying, _email character varying, _uid character varying, _ccid bigint, _operatorid character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_ccid bigint;
v_cscapplicantid bigint;
v_count integer;
begin
select count(*) into v_count from kaverimrg.cc_cscapplicantdetails where cscapplicantid = _cscapplicantid;
