    lastname,
    address,
    pincode,
    mobilenumber,
    email,
    uid,
    ccid,
    operatorid
) values
(
nextval('kaverimrg.cc_cscapplicantid_seq'),
    _firstname,
    _middlename,
    _lastname,
    _address,
    _pincode,
    _mobilenumber,
    _email,
    _uid,
    _ccid,
    _operatorid
) returning cscapplicantid::bigint into v_cscapplicantid;
else
update kaverimrg.cc_cscapplicantdetails set 
