-- Name: fn_insert_cc_remarks(character varying, character varying, smallint, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_cc_remarks(_remark character varying, _applicationnumber character varying, _documentstatusid smallint, _userid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_ccid bigint;
v_remarkid integer := 0;
v_documentstatusid integer;
begin
--Get the CC ID for the given application number
select ccid into v_ccid from kaverimrg.cc_applicationdetails where applicationnumber=   _applicationnumber;
/*select documentstatusid  into v_documentstatusid from  kaverimrg.mas_documentstatustypes a inner join
kaverimrg.servicesmaster b on a.serviceid = b.serviceid and b.serviceid = 12;*/
if v_ccid is not null then
    insert into kaverimrg.cc_remarkdetails (
        remarkid,
        remark,
        ccid,
        documentstatusid,
        userid,
        documentstatusdatetime
    ) values ( 
        nextval('kaverimrg.remarkid_seq'),
        _remark,
        v_ccid,
        _documentstatusid,
        _userid,
        CURRENT_TIMESTAMP
    ) returning remarkid into v_remarkid;
end if;
return v_remarkid;
end;
$$;


