--

CREATE TABLE kaverimrg.constructionratedetails_input (
    _constructiondetailsid bigint,
    _constructiontypeid smallint,
    _gfarea numeric,
    _agfarea numeric,
    _rate numeric,
    _verified boolean,
    _valuationid bigint,
    _srocode integer,
    _regsrocode integer
);


ALTER TABLE kaverimrg.constructionratedetails_input OWNER TO postgres;

--
-- Name: fn_insert_constructionratedetails(kaverimrg.constructionratedetails_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_constructionratedetails(p_constructionratedetails kaverimrg.constructionratedetails_input[] DEFAULT NULL::kaverimrg.constructionratedetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_constructionratedetails kaverimrg.constructionratedetails_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_constructionratedetails is not null and array_length(p_constructionratedetails,1)>0 ) then
				FOR v_arry_constructionratedetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_constructionratedetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaverimrg.val_constructionratedetails where constructiondetailsid in 
						(select a._constructiondetailsid from unnest(v_arry_constructionratedetails) a) ;
						if v_cnt = 0 then
							insert into kaverimrg.val_constructionratedetails (
								constructiondetailsid,
                                constructiontypeid,
                                gfarea,
                                agfarea,
                                rate,
                                verified,
                                valuationid,
                                 srocode,
                                 regsrocode
								)
								select 
								 nextval('kaverimrg.val_constructionratedetails_seq'),
								 a._constructiontypeid,
                                a._gfarea,
                                a._agfarea,
                                a._rate,
                                a._verified,
                                a._valuationid,
                                 a._srocode,
                                 a._regsrocode
								from unnest(v_arry_constructionratedetails)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaverimrg.val_constructionratedetails set
												 constructiontypeid=a._constructiontypeid,
                                                 gfarea=a._gfarea,
                                                 agfarea=a._agfarea,
                                                 rate=a._rate,
                                                 verified=a._verified,
                                                 valuationid=a._valuationid,
                                                 srocode=a._srocode,
                                                 regsrocode=a._regsrocode
												 from unnest(v_arry_constructionratedetails) a where constructiondetailsid in 
														 (select a._constructiondetailsid from unnest(v_arry_constructionratedetails) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_constructionratedetails(p_constructionratedetails kaverimrg.constructionratedetails_input[]) OWNER TO postgres;

