CREATE FUNCTION kaverimrg.fn_insert_dec_drpndnote(_noteid integer, _orderid bigint, _propertyid bigint, _note_preparedpart character varying, _note_enteredpart character varying, _userid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
v_orderid bigint;
v_cnt bigint;
begin
select count(*) into v_cnt from kaverimrg.dec_drpndnote a inner join 
kaverimrg.dec_drordermaster b on a.orderid = b.orderid and a.noteid = _noteid;
if v_cnt = 0 then
insert into  kaverimrg.dec_drpndnote 
(
    noteid,
    orderid,
    propertyid,
	note_preparedpart,
    note_enteredpart,
	userid
)
values
(
   nextval('kaverimrg.noteid_seq'),
   _orderid,
   _propertyid,
	_note_preparedpart,
   _note_enteredpart,
   _userid
) returning orderid into v_orderid;
end if;
return v_orderid;
end;
$$;


