--
-- Name: fn_insert_departmentloginloginfo(bigint, integer, character varying, bigint, character varying, bigint, character varying, character varying, character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_departmentloginloginfo(_userid bigint, _srocode integer, _publicip character varying, _localport bigint, _localip character varying, _remoteport bigint, _macaddress character varying, _location character varying, _country character varying, _isactive boolean, _jwttoken character varying, _reftoken character varying) RETURNS TABLE(userid bigint, isactive boolean, ismultilogin boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_isactive character varying;
v_array character varying[];
v_citizenid character varying;
BEGIN

if((select count(c.*) from kaverimrg.departmentloginloginfo c where c.userid = _userid and c.isactive=true)>0) 
THEN
 update kaverimrg.departmentloginloginfo cll set ismultilogin=true where cll.userid = _userid and cll.isactive=true;
 
 	insert into kaverimrg.departmentloginloginfo(c_userid,userid,srocode ,	localip ,localport,publicip ,remoteport ,macaddress ,location ,country,isactive ,jwttoken,reftoken)
	values(NEXTVAL('kaverimrg.departmentloginlog'),_userid,_srocode,_localip,_localport,_publicip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

RETURN QUERY ( select b.userid, true as isactive, true as ismultilogin from kaverimrg.departmentloginloginfo b where b.userid = _userid limit 1);

else
	insert into kaverimrg.departmentloginloginfo(c_userid,userid,srocode ,	localip ,localport,publicip ,remoteport ,macaddress ,location ,country,isactive ,jwttoken,reftoken)
	values(NEXTVAL('kaverimrg.departmentloginlog'),_userid,_srocode,_localip,_localport,_publicip,_remoteport,_macaddress,_location,_country,_isactive,_jwttoken,_reftoken);

RETURN QUERY (select c.userid, true as isactive, false as ismultilogin from kaverimrg.departmentloginloginfo c where c.userid = _userid limit 1);
end if;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_departmentloginloginfo(_userid bigint, _srocode integer, _publicip character varying, _localport bigint, _localip character varying, _remoteport bigint, _macaddress character varying, _location character varying, _country character varying, _isactive boolean, _jwttoken character varying, _reftoken character varying) OWNER TO postgres;

