--
-- Name: fn_insert_dissolutiondate(character varying, character varying, timestamp without time zone, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_dissolutiondate(_finalregistrationnumber character varying, _applicationnumber character varying, _dateofdissolutionofdate timestamp without time zone, _isactive boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationnumber varchar(50);
v_dissolutionid integer;
v_drcode integer;
begin

select count(*) into v_cnt from kaverimrg.firm_dissolution where applicationnumber = _applicationnumber;

select drcode into v_drcode from kaverimrg.firmmaster where finalregistrationnumber=_finalregistrationnumber;

if v_cnt = 0 then
insert into kaverimrg.firm_dissolution
			      (dissolutionid,
				  applicationnumber,
			      finalregistrationnumber,
			      dateofdissolutionofdate,
			      isactive,
				  drcode)
				  
			   values( nextval('kaverimrg.dissolutionid_seq'),
				  _applicationnumber,
				  _finalregistrationnumber,
				  _dateofdissolutionofdate,
			      _isactive,
				 v_drcode)
				returning dissolutionid into v_dissolutionid;
				
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FD104' 
       where applicationnumber=_applicationnumber;	
	   
	   select dissolutionid into v_dissolutionid  from kaverimrg.firm_dissolution where applicationnumber=_applicationnumber;
				
	else
update kaverimrg.firm_dissolution p1 set 
	--applicationnumber=_applicationnumber,
	finalregistrationnumber=_finalregistrationnumber,
	dateofdissolutionofdate=_dateofdissolutionofdate,
	isactive=_isactive,
	drcode=v_drcode
	where applicationnumber=_applicationnumber
				returning dissolutionid into v_dissolutionid;		
				  
		update kaverimrg.ApplicantApplicationdetails set currentstatus='FD104' 
       where applicationnumber=_applicationnumber;				  
				  
				  
 end if;
 
 return v_dissolutionid;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_dissolutiondate(_finalregistrationnumber character varying, _applicationnumber character varying, _dateofdissolutionofdate timestamp without time zone, _isactive boolean) OWNER TO postgres;

