--
-- Name: fn_insert_dlt_branch_amendment_details(kaverimrg.dlt_branch_details[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_dlt_branch_amendment_details(p_branchdetails kaverimrg.dlt_branch_details[] DEFAULT NULL::kaverimrg.dlt_branch_details[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$

declare
v_cnt bigint;
p_branch bigint; 
v_branchid bigint[];
v_branchid1 bigint;
v_dlt_brch_array p_branchdetails%type;
v_amendmentid bigint;

begin 

--FOR v_dlt_brch_array IN (select * from unnest($1)a)
--loop

--if(p_branchdetails is not null and array_length(p_branchdetails,1)>0 ) then
FOR v_dlt_brch_array IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_branchdetails))
loop	
	
	Select count(*) into v_cnt from kaverimrg.firmbranches f where branchid in (select a._branchid from unnest(v_dlt_brch_array)a);
	select count(*) into p_branch from kaverimrg.amendmentfirmbranches a2 where branchid in (select b._branchid from unnest(v_dlt_brch_array)b);	
	select amendmentid into v_amendmentid from kaverimrg.firmamendment f where applicationnumber in (select c._applicationnumber from unnest(v_dlt_brch_array)c);

if (v_cnt>0)
then 
	if(p_branch=0)
	then
		insert into kaverimrg.amendmentfirmbranches(
				amendmentbranchid,
				amendmentid,
			    branchid,
			    amendhousebuildingname,
			    amendstreetaddress,
			    amendstatecode,
			    amenddistrictcode,
			    amendtalukacode,
			    amendhoblicode,
			    amendcityvillagecode,	
			    amendpincode,
			    dateofcommencement_discontinuation,
			    isremoved,
				applicationnumber
				)
		select
				nextval('kaverimrg.amendmentbranchid_seq'),
				v_amendmentid,
			    branchid,
			    branchhousebuildingname,
			    branchstreetaddress,
			    branchstatecode,
			    branchdistrictcode,
			    branchtalukacode,
			    branchhoblicode,
			    branchcityvillagecode,	
			    branchpincode,
			    (select a._discontinuation from unnest(v_dlt_brch_array)a),
--			    v_dlt_brch_array._discontinuation,
			    true,
			    (select a._applicationnumber from unnest(v_dlt_brch_array)a)
--				v_dlt_brch_array._applicationnumber
				from kaverimrg.firmbranches f where branchid in (select b._branchid from unnest(v_dlt_brch_array)b) returning branchid into v_branchid1;
	 	else 
		update kaverimrg.amendmentfirmbranches
				set dateofcommencement_discontinuation =  (select b._discontinuation from unnest(v_dlt_brch_array)b),--v_dlt_brch_array._discontinuation,
					applicationnumber = (select b._applicationnumber from unnest(v_dlt_brch_array)b)--v_dlt_brch_array._applicationnumber
					--isremoved =true
				where branchid in (select b._branchid from unnest(v_dlt_brch_array)b) returning branchid into v_branchid1;
		end if;
end if;
v_branchid:=array_append(v_branchid,v_branchid1);
end loop;
--select array_agg(a2.branchid) into v_branchid from kaverimrg.amendmentfirmbranches a2 where branchid in (select a._branchid from unnest(v_dlt_brch_array)a);
return v_branchid;
end;
$_$;


