--
-- Name: fn_insert_documentmaster_pending_regis(character varying, character varying, bigint, bigint, timestamp without time zone, bigint, text, timestamp without time zone, character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_documentmaster_pending_regis(_applicationnumber character varying, _finalregnumber character varying, _srocode bigint, _regarticlecode bigint, _stamp5datetime timestamp without time zone, _bookid bigint, _remarks text, _executiondatetime timestamp without time zone, _pendingdocumentnumber character varying DEFAULT NULL::character varying, _pagecount integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$


declare 
v_cnt int;
v_docid int;
v_isbefore2003 boolean;
begin 
	
	select isbefore2003 into v_isbefore2003 from kaverimrg.minutebook_data md where applicationnumber = _applicationnumber ;
	
	select count(*) into v_cnt from kaverimrg.documentmaster where -- finalregistrationnumber=_finalregnumber 
	applicationnumber = _applicationnumber
	and srocode=_srocode ; 
	

	if (v_cnt=0)
	then
	insert into kaverimrg.documentmaster (documentid,applicationnumber,finalregistrationnumber,srocode,regarticlecode,stamp5datetime,bookid, executiondatetime,presentdatetime ,pendingdocumentnumber)
	values (nextval('kaverimrg.document_seq'),_applicationnumber,_finalregnumber,_srocode,_regarticlecode,_stamp5datetime,_bookid,_executiondatetime,_executiondatetime,concat('P-',_pendingdocumentnumber))
	returning documentid into v_docid;

--update kaverimrg.propertymaster set documentid = v_docid,
--regsrocode=_srocode
--where applicationnumber = _applicationnumber; -- Krishna goutam changes 26-04-2023

update kaverimrg.propertymaster 
set documentid = v_docid,
	sroconsideration = consideration,
	sromarketvalue = marketvalue,
	regsrocode=_srocode,
	srocode = _srocode,
	sronoofscanpages = _pagecount,
	noofscanpages = _pagecount
where applicationnumber = _applicationnumber;

update kaverimrg.propertyschedules set srocode=_srocode where applicationnumber = _applicationnumber;

update kaverimrg.partyinfo set documentid = v_docid,
srocode=_srocode where applicationnumber = _applicationnumber;

update kaverimrg.applicantapplicationdetails set srocode=_srocode,regsrocode = _srocode,remarks=_remarks 
where applicationnumber = _applicationnumber;

--update kaverimrg.minutebook_data b 
--set reasonid =rr.reasonid_k1 from kaverimrg.reasonmaster_k1 rr where b.reasonid =rr.reasonid and b.applicationnumber =_applicationnumber;

if v_isbefore2003 = true then

	update kaverimrg.minutebook_data b 
	set srocode = _srocode
	where b.applicationnumber = _applicationnumber;

else
	update kaverimrg.minutebook_data b 
	set reasonid = rr.reasonid
	from kaverimrg.reasonmaster_k1 rr where b.reasonid = rr.reasonid_k1 and b.applicationnumber = _applicationnumber;

end if;
end if;

return v_docid;
	
end;
$$;


