CREATE FUNCTION kaverimrg.fn_insert_dr_firmapplicationremarks(_applicationnumber character varying, _firmdetailsremarks_dr character varying, _firmdetailsverified_dr boolean, _presenterdetailsremarks_dr character varying, _presenterdetailsverified_dr boolean, _partnerdetailsremarks_dr character varying, _partnerdetailsverified_dr boolean, _witnessdetailsremarks_dr character varying, _witnessdetailsverified_dr boolean, _stampdutyandfeedetailsremarks_dr character varying, _stampdutyandfeedetailsverified_dr boolean, _canprocesstopaymentremarks_dr character varying, _canprocesstopaymentverified_dr boolean, _uploaddocumentremarks_dr character varying, _uploaddocumentverified_dr boolean, _branchdetailsremarks_dr character varying, _branchdetailsverified_dr boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationnumber text;
begin
select count(*) into v_cnt from kaverimrg.firmapplicationremarks where applicationnumber = _applicationnumber;
if v_cnt = 0 then
insert into kaverimrg.firmapplicationremarks
(
  verificationid,
  applicationnumber,
  firmdetailsremarks_dr,
  firmdetailsverified_dr,
  presenterdetailsremarks_dr,
  presenterdetailsverified_dr,
  partnerdetailsremarks_dr,
  partnerdetailsverified_dr,
  witnessdetailsremarks_dr,
  witnessdetailsverified_dr,
