  stampdutyandfeedetailsverified_dr,
  canprocesstopaymentremarks_dr,
  canprocesstopaymentverified_dr,
  uploaddocumentremarks_dr,
  uploaddocumentverified_dr,
  branchdetailsremarks_dr,
  branchdetailsverified_dr
) values
(nextval('kaverimrg.firmapplicationremarks_verificationid_seq'),
    _applicationnumber,
    _firmdetailsremarks_dr,
    _firmdetailsverified_dr,
    _presenterdetailsremarks_dr,
    _presenterdetailsverified_dr,
    _partnerdetailsremarks_dr,
    _partnerdetailsverified_dr,
    _witnessdetailsremarks_dr,
    _witnessdetailsverified_dr,
 	_stampdutyandfeedetailsremarks_dr,
    _stampdutyandfeedetailsverified_dr,
    _canprocesstopaymentremarks_dr,
    _canprocesstopaymentverified_dr,
    _uploaddocumentremarks_dr,
	_uploaddocumentverified_dr,
    _branchdetailsremarks_dr,
    _branchdetailsverified_dr
) returning applicationnumber into v_applicationnumber;

if(_firmdetailsremarks_dr is not null
   or _presenterdetailsremarks_dr is not null 
   or _partnerdetailsremarks_dr is not null 
   or  _witnessdetailsremarks_dr is not null 
   or _stampdutyandfeedetailsremarks_dr is not null 
   or _canprocesstopaymentremarks_dr is not null  
   or _uploaddocumentremarks_dr is not null 
   or _branchdetailsremarks_dr is not null 
  )
then 
update kaverimrg.applicantapplicationdetails a
set currentstatus='FR111'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=6;
update kaverimrg.applicantapplicationdetails a
set currentstatus='FA116'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=47;
update kaverimrg.applicantapplicationdetails a
set currentstatus='FC111'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=48;
update kaverimrg.applicantapplicationdetails a
set currentstatus='FD111'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=49;

elsif( _firmdetailsremarks_dr is  null
   and _presenterdetailsremarks_dr is  null 
   and _partnerdetailsremarks_dr is  null 
   and  _witnessdetailsremarks_dr is  null 
   and _stampdutyandfeedetailsremarks_dr is  null 
   and _canprocesstopaymentremarks_dr is null
   and _uploaddocumentremarks_dr is null
   and _branchdetailsremarks_dr is null )
   then
update kaverimrg.applicantapplicationdetails a
set currentstatus='FR110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=6;
update kaverimrg.applicantapplicationdetails a
set currentstatus='FA115'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=47;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FC110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=48;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FD110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=49;

end if;

else
update kaverimrg.firmapplicationremarks set
 firmdetailsremarks_dr=_firmdetailsremarks_dr,
 firmdetailsverified_dr= _firmdetailsverified_dr,
presenterdetailsremarks_dr=_presenterdetailsremarks_dr,
 presenterdetailsverified_dr=  _presenterdetailsverified_dr,
 partnerdetailsremarks_dr= _partnerdetailsremarks_dr,
 partnerdetailsverified_dr= _partnerdetailsverified_dr,
 witnessdetailsremarks_dr= _witnessdetailsremarks_dr,
 witnessdetailsverified_dr= _witnessdetailsverified_dr,
 stampdutyandfeedetailsremarks_dr=_stampdutyandfeedetailsremarks_dr,
 stampdutyandfeedetailsverified_dr=  _stampdutyandfeedetailsverified_dr,
canprocesstopaymentremarks_dr=_canprocesstopaymentremarks_dr,
 canprocesstopaymentverified_dr= _canprocesstopaymentverified_dr,
  uploaddocumentremarks_dr=_uploaddocumentremarks_dr,
  uploaddocumentverified_dr= _uploaddocumentverified_dr,
  branchdetailsremarks_dr=_branchdetailsremarks_dr,
  branchdetailsverified_dr=_branchdetailsverified_dr
  
where applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;

if(_firmdetailsremarks_dr is not null
   or _presenterdetailsremarks_dr is not null 
   or _partnerdetailsremarks_dr is not null 
   or _witnessdetailsremarks_dr is not null 
   or _stampdutyandfeedetailsremarks_dr is not null 
   or _canprocesstopaymentremarks_dr is not null
   or _uploaddocumentremarks_dr is not null
   or _branchdetailsremarks_dr is not null)
then 
update kaverimrg.applicantapplicationdetails a
set currentstatus='FR111'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=6;
update kaverimrg.applicantapplicationdetails a
set currentstatus='FA116'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=47;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FC111'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=48;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FD111'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=49;

elsif( _firmdetailsremarks_dr is  null
   and _presenterdetailsremarks_dr is  null 
   and _partnerdetailsremarks_dr is  null 
   and  _witnessdetailsremarks_dr is  null 
   and _stampdutyandfeedetailsremarks_dr is  null 
   and _canprocesstopaymentremarks_dr is null
   and _uploaddocumentremarks_dr is null
   and _branchdetailsremarks_dr is null) 
   
   then
update kaverimrg.applicantapplicationdetails a
set currentstatus='FR110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=6;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FA115'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=47;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FC110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=48;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FD110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=49;

end if;

end if;
return v_applicationnumber;
end;
$$;


