--
-- Name: fn_insert_dr_protestentryremarks(character varying, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_dr_protestentryremarks(_applicationnumber character varying, _firmdetailsremarks_dr character varying, _firmdetailsverified_dr boolean, _presenterdetailsremarks_dr character varying, _presenterdetailsverified_dr boolean, _partnerdetailsremarks_dr character varying, _partnerdetailsverified_dr boolean, _protestentrynotedremarks_dr character varying, _protestentrynotedverified_dr boolean, _protestentryisnotvalidremarks_dr character varying, _protestentryisnotvalidverified_dr boolean, _uploaddocumentremarks_dr character varying, _uploaddocumentverified_dr boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationnumber text;
begin
select count(*) into v_cnt from kaverimrg.firmapplicationremarks where applicationnumber = _applicationnumber;
if v_cnt = 0 then
insert into kaverimrg.firmapplicationremarks
(
  verificationid,
  applicationnumber,
  firmdetailsremarks_dr,
  firmdetailsverified_dr,
  presenterdetailsremarks_dr,
  presenterdetailsverified_dr,
  partnerdetailsremarks_dr,
  partnerdetailsverified_dr,
  protestentrynotedremarks_dr,
  protestentrynotedverified_dr,
  protestentryisnotvalidremarks_dr,
  protestentryisnotvalidverified_dr,
  uploaddocumentremarks_dr,
  uploaddocumentverified_dr
) values
(nextval('kaverimrg.firmapplicationremarks_verificationid_seq'),
    _applicationnumber,
    _firmdetailsremarks_dr,
    _firmdetailsverified_dr,
    _presenterdetailsremarks_dr,
    _presenterdetailsverified_dr,
    _partnerdetailsremarks_dr,
    _partnerdetailsverified_dr,
    _protestentrynotedremarks_dr,
    _protestentrynotedverified_dr,
    _protestentryisnotvalidremarks_dr,
    _protestentryisnotvalidverified_dr,
    _uploaddocumentremarks_dr,
	_uploaddocumentverified_dr
) returning applicationnumber into v_applicationnumber;

if(_firmdetailsremarks_dr is not null
   or _presenterdetailsremarks_dr is not null 
   or _partnerdetailsremarks_dr is not null  
   or _uploaddocumentremarks_dr is not null 
  )
then 
update kaverimrg.applicantapplicationdetails a
set currentstatus='FP109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=50;

elsif(
    _protestentrynotedremarks_dr is not null 
)
then 
update kaverimrg.applicantapplicationdetails a
set currentstatus='FP108'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=50;

elsif( 
    _protestentryisnotvalidremarks_dr is not null 
)
   then
update kaverimrg.applicantapplicationdetails a
set currentstatus='FP110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=50;

end if;

else
update kaverimrg.firmapplicationremarks set
 firmdetailsremarks_dr=_firmdetailsremarks_dr,
 firmdetailsverified_dr= _firmdetailsverified_dr,
 presenterdetailsremarks_dr=_presenterdetailsremarks_dr,
 presenterdetailsverified_dr=  _presenterdetailsverified_dr,
 partnerdetailsremarks_dr= _partnerdetailsremarks_dr,
 partnerdetailsverified_dr= _partnerdetailsverified_dr,
  protestentrynotedremarks_dr=_protestentrynotedremarks_dr,
  protestentrynotedverified_dr=_protestentrynotedverified_dr,
  protestentryisnotvalidremarks_dr=_protestentryisnotvalidremarks_dr,
  protestentryisnotvalidverified_dr=_protestentryisnotvalidverified_dr,
  uploaddocumentremarks_dr=_uploaddocumentremarks_dr,
  uploaddocumentverified_dr= _uploaddocumentverified_dr
where applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;

if(_firmdetailsremarks_dr is not null
   or _presenterdetailsremarks_dr is not null 
   or _partnerdetailsremarks_dr is not null  
   or _uploaddocumentremarks_dr is not null 
  )
then 
update kaverimrg.applicantapplicationdetails a
set currentstatus='FP109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=50;

elsif(
  _protestentrynotedremarks_dr is not null 
)
then 
update kaverimrg.applicantapplicationdetails a
set currentstatus='FP108'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=50;

elsif( 
   _protestentryisnotvalidremarks_dr is not null 
)
   then
update kaverimrg.applicantapplicationdetails a
set currentstatus='FP110'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=50;

end if;


end if;
return v_applicationnumber;
end;
$$;


