(select a._ecpropertynoid from unnest($1) a) ;*/
   if(p_propertynodetails is not null and array_length(p_propertynodetails,1)>0 ) then
FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_propertynodetails))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaverimrg.ec_propertynumberdetails where ecpropertynoid in 
(select a._ecpropertynoid from unnest(v_party_arry) a) ;
if v_cnt = 0 then 
INSERT INTO kaverimrg.ec_propertynumberdetails( 
 ecpropertynoid,
    ecid,
    propertynotypeid,
    oldpropertynumber,
    newpropertynumber,
