	from unnest(v_party_arry) a where ecpropertynoid in 
			 (select a._ecpropertynoid from unnest(v_party_arry) a) 
			 RETURNING ecid::bigint into v_ecid;
	 end if;
	--v_pid := array_append(v_pid,v_ecid);
	end loop;
	end if;
	/* Fees Required */
	if(p_ecrequiredfees is not null and array_length(p_ecrequiredfees,1)>0 ) then
FOR v_ecrequiredfees IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_ecrequiredfees))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaverimrg.ec_requiredfees where requiredfeeid in 
(select a._requiredfeeid from unnest(v_ecrequiredfees) a) ;
if v_cnt = 0 then 
INSERT INTO kaverimrg.ec_requiredfees( 
requiredfeeid,
ecid,
feeruleid,
payableamount,
ispaid,
serviceid,
feedescription
)
	select nextval('kaverimrg.ec_requiredfees_seq'),
   v_schid,
  a._feeruleid,
a._payableamount,
a._ispaid,
a._serviceid,
a._feedescription
from unnest(v_ecrequiredfees) a	
	 returning ecid::bigint into v_ecid;		
	 else
	 update kaverimrg.ec_requiredfees set
	 ecid=v_ecid,
   feeruleid=a._feeruleid,
   payableamount=a._payableamount,
   ispaid=a._ispaid,
   serviceid=a._serviceid,
   feedescription=a._feedescription
	from unnest(v_ecrequiredfees) a where requiredfeeid in 
			 (select a._requiredfeeid from unnest(v_ecrequiredfees) a) 
			 RETURNING ecid::bigint into v_ecid;
	 end if;
	--v_pid := array_append(v_pid,v_ecid);
	end loop;
	end if;
        Return v_applicationnumber;
		--Return v_applicationnumber;
end;
$_$;


