--
-- Name: fn_insert_ec_applicationdetail_firm(kaverimrg.ec_applicationdetailsfirm_input, kaverimrg.ec_firmregistrationdetails_input); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_ec_applicationdetail_firm(p_ec_firminput kaverimrg.ec_applicationdetailsfirm_input, p_ecfirmdetailinput kaverimrg.ec_firmregistrationdetails_input) RETURNS TABLE(applno text, current_status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
v_cnt integer;
v_ecid bigint;
l_now varchar(8);
l_reset_date varchar(8);
_nomenclature character varying(3);
_servicestatus text; 
_application text;
_inserted_id text;
_applicationnumber text;
BEGIN


select count(*) into v_cnt from  kaverimrg.ec_applicationdetails_firm  
where applicationnumber  = p_ec_firminput._applicationnumber ;

raise notice 'v_cnt=%',v_cnt;

if v_cnt = 0 then 
l_now := to_char(now(),'DDMMYYYY');

l_reset_date := to_char(now(),'DDMM');

select nomenclature into _nomenclature from kaverimrg.servicesmaster where serviceid=51; 
select lpad(nextval('kaverimrg.ec_applicationdetail_firm_seq')::text,7,'0') into _inserted_id;
_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;
_servicestatus = 'IS102';

INSERT INTO kaverimrg.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
		
    )
    select  
	p_ec_firminput._submittedby,
	_applicationnumber, 
	51,
	now(),
	_servicestatus
		
    RETURNING applicationnumber
	into _application;
	
INSERT INTO kaverimrg.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	select _applicationnumber, _servicestatus,p_ec_firminput._submittedby,
1, p_ec_firminput._submittedby;
--from  p_ec_firminput as  a;
	
INSERT INTO kaverimrg.ec_applicationdetails_firm
(
ecid,
ecnumber,
certificatenumber,
ecdate,
userid,
searchfromdate,
searchtodate,
kaverimrgdrocode,
kaverimrgtalukcode,
pagecount,
submittedby,
submitteddatetime,
acceptedby,
acceptedon,
documentstatusid,
preparedby,
prepareddatetime, 
remarktoreprepareec,
partyname,
isnamesearch,
isfirmregnosearch,
isdocviewable,
applicationnumber,
signedform22
)
select 
ltrim(_inserted_id, '0')::integer,
p_ec_firminput._ecnumber,
p_ec_firminput._certificatenumber,
p_ec_firminput._ecdate,
p_ec_firminput._submittedby,
p_ec_firminput._searchfromdate,
p_ec_firminput._searchtodate,
p_ec_firminput._kaverimrgdrocode,
p_ec_firminput._kaverimrgtalukcode,
p_ec_firminput._pagecount,
p_ec_firminput._submittedby,
p_ec_firminput._submitteddatetime,
p_ec_firminput._acceptedby,
p_ec_firminput._acceptedon,
p_ec_firminput._documentstatusid,
p_ec_firminput._preparedby,
p_ec_firminput._prepareddatetime, 
p_ec_firminput._remarktoreprepareec,
p_ec_firminput._partyname,
p_ec_firminput._isnamesearch,
p_ec_firminput._isfirmregnosearch,
p_ec_firminput._isdocviewable,
_applicationnumber,
p_ec_firminput._signedform22
 returning ecid::bigint into v_ecid;

INSERT INTO kaverimrg.ec_firmregistrationdetails
(ecfirmid, ecid, firmname, finalregistrationnumber)
select nextval('kaverimrg.ecfirmid_seq'),
v_ecid,
p_ecfirmdetailinput._firmname, 
p_ecfirmdetailinput._finalregistrationnumber;

else
		_servicestatus = 'IS102';
		
			
			update kaverimrg.ec_applicationdetails_firm
			set
			ecnumber=p_ec_firminput._ecnumber,
			certificatenumber=p_ec_firminput._certificatenumber,
			ecdate=p_ec_firminput._ecdate,
			userid=p_ec_firminput._submittedby,
			searchfromdate=p_ec_firminput._searchfromdate,
			searchtodate=p_ec_firminput._searchtodate,
			kaverimrgdrocode=p_ec_firminput._kaverimrgdrocode,
			kaverimrgtalukcode=p_ec_firminput._kaverimrgtalukcode,
			pagecount=p_ec_firminput._pagecount,
			submittedby=p_ec_firminput._submittedby,
			submitteddatetime=p_ec_firminput._submitteddatetime,
			acceptedby=p_ec_firminput._acceptedby,
			acceptedon=p_ec_firminput._acceptedon,
			documentstatusid=p_ec_firminput._documentstatusid,
			preparedby=p_ec_firminput._preparedby,
			prepareddatetime=p_ec_firminput._prepareddatetime, 
			remarktoreprepareec=p_ec_firminput._remarktoreprepareec,
			partyname=p_ec_firminput._partyname,
			isnamesearch=p_ec_firminput._isnamesearch,
			isfirmregnosearch=p_ec_firminput._isfirmregnosearch,
			isdocviewable=p_ec_firminput._isdocviewable,
			signedform22=p_ec_firminput._signedform22
			--from  p_ec_firminput as  a
			where applicationnumber  =p_ec_firminput._applicationnumber 
			  returning ecid::bigint into v_ecid;
			 raise notice 'ecid:%',v_ecid;
			
      
        
         
        	
			UPDATE kaverimrg.ec_firmregistrationdetails
			SET  firmname=p_ecfirmdetailinput._firmname, 
			finalregistrationnumber=p_ecfirmdetailinput._finalregistrationnumber
			--from  p_ecfirmdetailinput as  a
			WHERE ecid=v_ecid;
		
	
	
	  update kaverimrg.applicantapplicationdetails set currentstatus=_servicestatus 
	  where applicationnumber=p_ec_firminput._applicationnumber
	 returning applicationnumber  into _applicationnumber;
	
end if;

return query select _applicationnumber,_servicestatus;
end;
$$;


