--
-- Name: fn_insert_fda_firmapplicationremarks(character varying, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean, character varying, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_fda_firmapplicationremarks(_applicationnumber character varying, _firmdetailsremarks_fda_sda character varying, _firmdetailsverified_fda_sda boolean, _presenterdetailsremarks_fda_sda character varying, _presenterdetailsverified_fda_sda boolean, _partnerdetailsremarks_fda_sda character varying, _partnerdetailsverified_fda_sda boolean, _witnessdetailsremarks_fda_sda character varying, _witnessdetailsverified_fda_sda boolean, _stampdutyandfeedetailsremarks_fda_sda character varying, _stampdutyandfeedetailsverified_fda_sda boolean, _uploaddocumentremarks_fda_sda character varying, _uploaddocumentverified_fda_sda boolean, _branchdetailsremarks_fda_sda character varying, _branchdetailsverified_fda_sda boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_applicationnumber text;
begin
select count(*) into v_cnt from kaverimrg.firmapplicationremarks where applicationnumber = _applicationnumber;
if v_cnt = 0 then
insert into kaverimrg.firmapplicationremarks
(
  verificationid,
 applicationnumber,
  firmdetailsremarks_fda_sda,
  firmdetailsverified_fda_sda,
  presenterdetailsremarks_fda_sda,
  presenterdetailsverified_fda_sda,
  partnerdetailsremarks_fda_sda,
  partnerdetailsverified_fda_sda,
  witnessdetailsremarks_fda_sda,
  witnessdetailsverified_fda_sda,
  stampdutyandfeedetailsremarks_fda_sda,
  stampdutyandfeedetailsverified_fda_sda,
  uploaddocumentremarks_fda_sda,
  uploaddocumentverified_fda_sda,
  branchdetailsremarks_fda_sda,
  branchdetailsverified_fda_sda

) values
(nextval('kaverimrg.firmapplicationremarks_verificationid_seq'),
    _applicationnumber,
    _firmdetailsremarks_fda_sda,
    _firmdetailsverified_fda_sda,
    _presenterdetailsremarks_fda_sda,
    _presenterdetailsverified_fda_sda,
    _partnerdetailsremarks_fda_sda,
    _partnerdetailsverified_fda_sda,
    _witnessdetailsremarks_fda_sda,
    _witnessdetailsverified_fda_sda,
 	_stampdutyandfeedetailsremarks_fda_sda,
    _stampdutyandfeedetailsverified_fda_sda,
    _uploaddocumentremarks_fda_sda,
	_uploaddocumentverified_fda_sda,
    _branchdetailsremarks_fda_sda,
    _branchdetailsverified_fda_sda

) returning applicationnumber into v_applicationnumber;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FR109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=6;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FA114'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=47;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FC109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=48;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FD109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=49;

else
update kaverimrg.firmapplicationremarks set
 firmdetailsremarks_fda_sda= _firmdetailsremarks_fda_sda,
firmdetailsverified_fda_sda=_firmdetailsverified_fda_sda,
 presenterdetailsremarks_fda_sda= _presenterdetailsremarks_fda_sda,
  presenterdetailsverified_fda_sda=  _presenterdetailsverified_fda_sda,
partnerdetailsremarks_fda_sda=_partnerdetailsremarks_fda_sda,
 partnerdetailsverified_fda_sda= _partnerdetailsverified_fda_sda,
witnessdetailsremarks_fda_sda=_witnessdetailsremarks_fda_sda,
 witnessdetailsverified_fda_sda=  _witnessdetailsverified_fda_sda,
 stampdutyandfeedetailsremarks_fda_sda=_stampdutyandfeedetailsremarks_fda_sda,
 stampdutyandfeedetailsverified_fda_sda=_stampdutyandfeedetailsverified_fda_sda,
  uploaddocumentremarks_fda_sda=_uploaddocumentremarks_fda_sda,
  uploaddocumentverified_fda_sda=_uploaddocumentverified_fda_sda,
  branchdetailsremarks_fda_sda=_branchdetailsremarks_fda_sda,
  branchdetailsverified_fda_sda=_branchdetailsverified_fda_sda
where applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FR109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=6;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FA114'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=47;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FC109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=48;

update kaverimrg.applicantapplicationdetails a
set currentstatus='FD109'
where a.applicationnumber=_applicationnumber and a.applicationtypeid=49;

end if;
return v_applicationnumber;
end;
$$;


