--
-- Name: fn_insert_feesrequired(kaverimrg.feesrequired_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_feesrequired(kaverimrg.feesrequired_input[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$

DECLARE

   id_val integer;

   fees_arry $1%type;

   v_applicationnumber text;

    v_txt text;

   v_propertyid bigint;

   v_cnt integer;

   var_r record;

   v_pid integer[];

BEGIN

  FOR fees_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray($1))

     loop

   Select count(*) into v_cnt from kaverimrg.feesrequired where (coalesce(propertyid,0),applicationnumber,feerulecode) in

(select coalesce(a._propertyid,0),a._applicationnumber,a._feerulecode from unnest(fees_arry) a);

  if v_cnt = 0 then

INSERT INTO kaverimrg.feesrequired(

    documentid,

    feerulecode,

    isexempted,

    exemptdescription,

    isactive,

    feecalculationstring,

    srocode,

    isonline,

    amountrequired,

	undervaluationamount,

    applicationnumber,

    propertyid,

    exemtype,

    exemamount,

    exemdocpath,

    denodocpath,

    regexemtype,

    regexemamount,

    lastupdateddate,

    paymentstatus

) select

    _documentid,

    _feerulecode,

    _isexempted,

    _exemptdescription,

    _isactive,

    _feecalculationstring,

    _srocode,

    _isonline,

    _amountrequired,

                undervaluationamount,

    _applicationnumber,

    _propertyid,

    _exemtype,

    _exemamount,

    _exemdocpath,

    _denodocpath,

    _regexemtype,

    _regexemamount,

    CURRENT_TIMESTAMP,

    'Pending'

from unnest(fees_arry)                        

    RETURNING feerulecode::integer into id_val;

    else

update kaverimrg.feesrequired set

    documentid = b._documentid,

    feerulecode = b._feerulecode,

    isexempted = b._isexempted,

    exemptdescription = b._exemptdescription,

    isactive=b._isactive,

    feecalculationstring=b._feecalculationstring,

    srocode=b._srocode,

    isonline=b._isonline,

    amountrequired = b._amountrequired,

                undervaluationamount = b.undervaluationamount,

    applicationnumber = b._applicationnumber,

    propertyid = b._propertyid,

    exemtype=b._exemtype,

    exemamount=b._exemamount,

    exemdocpath=b._exemdocpath,

    denodocpath=b._denodocpath,

    regexemtype=b._regexemtype,

    regexemamount=b._regexemamount

    from unnest(fees_arry) b

    where (coalesce(propertyid,0),applicationnumber,feerulecode) in

   (select coalesce(a._propertyid,0),a._applicationnumber,a._feerulecode from unnest(fees_arry) a)

RETURNING feerulecode::integer into id_val;

    end if;

     v_pid := array_append(v_pid,id_val);

    end loop;

    return v_pid;

end;

$_$;


