--
-- Name: feesrequired_check1_input; Type: TABLE; Schema: kaverimrg; Owner: postgres
--

CREATE TABLE kaverimrg.feesrequired_check1_input (
    _applicationnumber character varying,
    _feerulecode integer,
    _valuatiotypeid smallint,
    _amountpaid numeric
);


ALTER TABLE kaverimrg.feesrequired_check1_input OWNER TO postgres;

--
-- Name: fn_insert_feesrequired_check(kaverimrg.feesrequired_check1_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_feesrequired_check(p_feesdetails kaverimrg.feesrequired_check1_input[]) RETURNS integer[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val integer;
   --fees_arry $1%type;
   v_fees_arry kaverimrg.feesrequired_check1_input[];
   v_applicationnumber text;
    v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   var_r record;
   v_pid integer[];
   v_srostamparticlecode integer;
   v_srostampruleid integer;
   v_sronatureofdocument integer;
   v_valuatiotypeid smallint;
BEGIN
 Select count(*) into v_cnt from kaverimrg.feesrequired where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._valuatiotypeid from unnest($1) a);
if(p_feesdetails  is not null and array_length(p_feesdetails ,1)>0 ) then
  FOR v_fees_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_feesdetails))
     loop
   Select count(*) into v_cnt from kaverimrg.feesrequired where (applicationnumber,feerulecode) in 
(select a._applicationnumber,a._feerulecode from unnest(v_fees_arry) a);
  if v_cnt >= 1 then
	update kaverimrg.feesrequired set
	valuatiotypeid=_valuatiotypeid
	--amountpaid=_amountpaid -- november 03, 2023 - removed amountpaid updation, this is already handled in fn_save_paymentgateway post payment, verification
	from unnest(v_fees_arry)
	where (applicationnumber,feerulecode) in 
(select 
 a._applicationnumber,a._feerulecode from unnest(v_fees_arry) a) 
RETURNING feerulecode::integer into id_val;
    end if;
	/* logic to implement if valuationtype (valuatiotypeid -2 )is normal update 
    stamparticlecode,stampruleid,natureofdocument to 
	srostamparticlecode,srostampruleid,sronatureofdocument*/
	select a.srostamparticlecode,a.srostampruleid,a.sronatureofdocument,b.valuatiotypeid
	into v_srostamparticlecode,v_srostampruleid,v_sronatureofdocument,v_valuatiotypeid from kaverimrg.propertymaster a
	inner join kaverimrg.feesrequired b on a.applicationnumber = b.applicationnumber and b.valuatiotypeid = 2
	and (a.applicationnumber) in 
(select a._applicationnumber from unnest(v_fees_arry) a);
    if v_valuatiotypeid::smallint = '2' and 
	(v_srostamparticlecode::integer is not null and v_srostampruleid::integer is not null
							   and v_sronatureofdocument::integer is not null) then
	update kaverimrg.propertymaster set stamparticlecode = v_srostamparticlecode::integer,
	stampruleid = v_srostampruleid::integer,
	regarticlecode = v_sronatureofdocument ::integer
	from unnest(v_fees_arry)
	where (applicationnumber) in 
(select 
 a._applicationnumber from unnest(v_fees_arry) a) ;
--RETURNING feerulecode::integer into id_val;
end if;
	 v_pid := array_append(v_pid,id_val);
    end loop;
	end if;
	return v_pid;
end;
$_$;


ALTER FUNCTION kaverimrg.fn_insert_feesrequired_check(p_feesdetails kaverimrg.feesrequired_check1_input[]) OWNER TO postgres;

--
-- Name: fn_insert_feesrequired_check_03112023(kaverimrg.feesrequired_check1_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
