--
-- Name: fn_insert_fruits_data(character varying, integer, text, text, character varying, character varying, character varying, bigint, integer, character varying, character, boolean, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_consideration_amt bigint;
v_propertyid bigint;
v_bookid integer;
v_applicationstatus integer;
v_reqid integer;
v_noofscanpages integer;
v_scanfees numeric;
v_value numeric;
v_mutationfee numeric;
v_cnt bigint;
BEGIN
/* Application Status Codes for FRUITS
	0 -> Status Pending as SRO
	1 -> AutoFiled
	2 -> Registered
	3 -> Withdrawn
	4 -> Rejected
*/
v_applicationstatus = 0;

select value into v_value from kaverimrg.feesrulemaster where feerulecode = 2;

v_noofscanpages = _noofpages + 3;
v_scanfees = (v_noofscanpages * v_value)::numeric;

select value into v_value from kaverimrg.feesrulemaster where feerulecode = 6;
select count(propertyid) into v_cnt  from kaverimrg.propertymaster where applicationnumber=_applicationnumber;

v_mutationfee:= (v_value * v_cnt)::numeric;

select consideration, propertyid into v_consideration_amt, v_propertyid from kaverimrg.propertymaster p 
where p.applicationnumber = _applicationnumber;

update kaverimrg.propertymaster set sroconsideration = consideration,documentid=_documentid where applicationnumber = _applicationnumber;
update kaverimrg.documentmaster set considerationamount = v_consideration_amt where applicationnumber = _applicationnumber;


--if(v_consideration_amt > 300000 or _formiiidata = '' ) then	
--if(v_consideration_amt > 300000) then	
if(_transactiontype = 'M' ) then --if(_formiiipath = '') then
	-- Insert scanning/ service fee and Mutation fee(35 Rs), into feesrequired table
	/*perform kaverimrg.fn_insert_feesrequired_check(
		array[(_applicationnumber, 2, 2, 45)]::kaverimrg.feesrequired_check1_input[]);*/

	v_bookid = 1;
	perform kaverimrg.fn_insert_feesrequired(
		array[
		(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
		(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaverimrg.feesrequired_input[]);
	
	perform kaverimrg.fn_insert_deptfeesrequired(
		array[
		(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
		(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaverimrg.feesrequired_input[], true);		

	update kaverimrg.applicantapplicationdetails a set currentstatus = 'CD106'
	where a.applicationnumber = _applicationnumber;

	update kaverimrg.propertymaster set sronoofscanpages = v_noofscanpages
	where applicationnumber = _applicationnumber;
else 
	if(_transactiontype in ('A',  'R') or _isaadharapatra = true) then
		v_bookid = 10;
	else
		v_bookid = 9;
	end if;

	update kaverimrg.applicantapplicationdetails a set currentstatus = 'CD112'
	where a.applicationnumber = _applicationnumber;
end if;
/*if(v_consideration_amt <= 300000 and _formiiidata != '' ) then
	v_applicationstatus = 1;
else
	v_applicationstatus = 0;
end if;*/

/*if(_transactiontype = 'M') then
	--if(v_consideration_amt > 300000 or _formiiidata = '') then
	if(v_consideration_amt > 300000) then
		v_bookid = 1;
		/*update kaverimrg.propertymaster set sronoofscanpages = v_noofscanpages --4
		where applicationnumber = _applicationnumber;	*/
		
		-- Commenting as below operation should happen regardless of Book-I or Book-i Part IV/ V
		/*update kaverimrg.documentmaster 
			set uploaddocdeedpath = _formiiipath,
			deedattachpath = _formiiipath
		where applicationnumber = _applicationnumber;*/
	elsif(_isaadharapatra = true) then		
		v_bookid = 10;
	/*elsif(_formiiidata != '' ) then
		v_bookid = 9;*/
	else
		v_bookid = 9;
		
		/*update kaverimrg.propertymaster set sronoofscanpages = 4
		where applicationnumber = _applicationnumber;	*/
	end if;
elsif(_transactiontype = 'R') then
	v_bookid = 10;
end if;
*/
update kaverimrg.documentmaster d 
	set bookid = v_bookid, uploaddocdeedpath = _formiiipath, deedattachpath = _formiiipath
where d.applicationnumber = _applicationnumber;

INSERT INTO kaverimrg.fruits_data_recv_details (
	psrocode, referenceno, srocode, formiiidata, transxml, formiiipath, transxmlpath, aknowledgementno, 
	datareceiveddate, documentid, issignedformiiiuploaded, kaigreg_insertdatetime, 
	applicationnumber, transactiontype, isformiiisrsigned, applicationstatus, isaadharapatra, consideration
	--istransmitted, isrejectedtransmitted, actiondatetime, actionstatuscode, formiiidatasigned, documentstatuscode, 
) VALUES (
	_srocode, _referenceno, _srocode, _formiiidata, _transxml, _formiiipath, _transxmlpath, _acknowledgementno, 
	CURRENT_TIMESTAMP, _documentid, _issignedformiiiuploaded, CURRENT_TIMESTAMP, 
	_applicationnumber, _transactiontype, false, v_applicationstatus, _isaadharapatra, v_consideration_amt
) returning requestid into v_reqid;

return v_reqid;
END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer) OWNER TO postgres;

--
-- Name: fn_insert_fruits_data(character varying, integer, text, text, character varying, character varying, character varying, bigint, integer, character varying, character, boolean, integer, character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer, _loantype character varying, _cropcode integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_consideration_amt bigint;
v_propertyid bigint;
v_bookid integer;
v_stampruleid integer;
v_applicationstatus integer;
v_reqid integer;
v_noofscanpages integer;
v_scanfees numeric;
v_value numeric;
v_mutationfee numeric;
v_cnt bigint;
v_sd numeric;
v_regfees numeric;
v_sdvalue numeric;
v_sdunit integer;
v_sdcalcon bpchar(2);
v_sdispercent bool;
v_sdisfixduty bool;
v_regval numeric;
v_regpercent bool;
v_regvalue numeric; 
v_regispercent bool ;
v_regmaxlimit numeric;
v_regcalconconsideration char;
v_issurcharge bool;
v_surchargeval numeric;
v_surcharge numeric;
BEGIN
/* Application Status Codes for FRUITS
	0 -> Status Pending as SRO
	1 -> AutoFiled
	2 -> Registered
	3 -> Withdrawn
	4 -> Rejected
*/
v_applicationstatus = 0;

select value into v_value from kaverimrg.feesrulemaster where feerulecode = 2;

v_noofscanpages = _noofpages + 3;
v_scanfees = (v_noofscanpages * v_value)::numeric;

select value into v_value from kaverimrg.feesrulemaster where feerulecode = 6;
select count(propertyid), stampruleid, consideration, propertyid into v_cnt, v_stampruleid, v_consideration_amt, v_propertyid 
from kaverimrg.propertymaster where applicationnumber=_applicationnumber
group by stampruleid, consideration, propertyid ;

v_mutationfee:= (v_value * v_cnt)::numeric;

--select consideration, propertyid into v_consideration_amt, v_propertyid from kaverimrg.propertymaster p 
--where p.applicationnumber = _applicationnumber;

update kaverimrg.propertymaster set sroconsideration = consideration,documentid=_documentid where applicationnumber = _applicationnumber;
update kaverimrg.documentmaster set considerationamount = v_consideration_amt where applicationnumber = _applicationnumber;
update kaverimrg.partyinfo set documentid = _documentid,srocode=_srocode where applicationnumber = _applicationnumber; 
update kaverimrg.orgdatajslip set documentid=_documentid where applicationnumber = _applicationnumber;

if(_transactiontype = 'M') then 
--if(_formiiipath = '') then
--if(v_consideration_amt > 300000 or _formiiidata = '' ) then	
--if(v_consideration_amt > 300000) then	
	-- Insert scanning/ service fee and Mutation fee(35 Rs), into feesrequired table
	/*perform kaverimrg.fn_insert_feesrequired_check(
		array[(_applicationnumber, 2, 2, 45)]::kaverimrg.feesrequired_check1_input[]);*/
		
	v_bookid = 1;
	if(_cropcode in (67, 69, 210, 211, 212, 305, 306)) then
		select value, unit, sdcalcon, isinpercentage, isfixduty, regvalue, regispercent, regmaxlimit, regcalconconsideration,issurcharge, ruralvalue
		into v_sdvalue, v_sdunit, v_sdcalcon, v_sdispercent, v_sdisfixduty,v_regvalue,v_regispercent,v_regmaxlimit,v_regcalconconsideration,v_issurcharge, v_surchargeval
		from kaverimrg.stamprules where stampruleid=v_stampruleid;
		
		if(v_sdisfixduty) then
			v_sd=v_sdvalue;
		elsif(v_sdispercent and v_sdcalcon='C') then
			v_sd=(v_sdvalue/v_sdunit)*v_consideration_amt;
		end if;
		
		if (v_regispercent and v_regcalconconsideration='C') then
			v_regfees=(v_regvalue/100)*v_consideration_amt;
			if(v_regfees > v_regmaxlimit) then 
				v_regfees=v_regmaxlimit;
			end if;
		end if;
		
		if(v_issurcharge) then
				v_surcharge=(v_surchargeval/100)*v_sd;
		end if;
	
		perform kaverimrg.fn_insert_feesrequired(array[
			(_documentid, 36, false, '', true, '36', _srocode, true, v_sd, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 58, false, '', true, '58', _srocode, true, v_surcharge, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 1, false, '', true, '1', _srocode, true, v_regfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaverimrg.feesrequired_input[]);
		
		perform kaverimrg.fn_insert_deptfeesrequired(array[
			(_documentid, 36, false, '', true, '36', _srocode, true, v_sd, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 58, false, '', true, '58', _srocode, true, v_surcharge, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 1, false, '', true, '1', _srocode, true, v_regfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaverimrg.feesrequired_input[], true);	
	else
		perform kaverimrg.fn_insert_feesrequired(
			array[
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaverimrg.feesrequired_input[]);
		
		perform kaverimrg.fn_insert_deptfeesrequired(
			array[
			(_documentid, 2, false, '', true, '2', _srocode, true, v_scanfees, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0),
			(_documentid, 6, false, '', true, '6', _srocode, true, v_mutationfee, _applicationnumber, v_propertyid, '', 0, '', '', '', 0, 0)]::kaverimrg.feesrequired_input[], true);			
	end if;

	update kaverimrg.applicantapplicationdetails a set currentstatus = 'CD106'
	where a.applicationnumber = _applicationnumber;

	update kaverimrg.propertymaster set sronoofscanpages = v_noofscanpages
	where applicationnumber = _applicationnumber;
else 
	if(_transactiontype in ('A',  'R') or _isaadharapatra = true) then
		v_bookid = 10;
	else
		v_bookid = 9;
	end if;

	update kaverimrg.applicantapplicationdetails a set currentstatus = 'CD112'
	where a.applicationnumber = _applicationnumber;
end if;
/*if(v_consideration_amt <= 300000 and _formiiidata != '' ) then
	v_applicationstatus = 1;
else
	v_applicationstatus = 0;
end if;*/

/*if(_transactiontype = 'M') then
	--if(v_consideration_amt > 300000 or _formiiidata = '') then
	if(v_consideration_amt > 300000) then
		v_bookid = 1;
		update kaverimrg.propertymaster set sronoofscanpages = v_noofscanpages --4
		where applicationnumber = _applicationnumber;	
		
		-- Commenting as below operation should happen regardless of Book-I or Book-i Part IV/ V
		update kaverimrg.documentmaster 
			set uploaddocdeedpath = _formiiipath,
			deedattachpath = _formiiipath
		where applicationnumber = _applicationnumber;
	elsif(_isaadharapatra = true) then		
		v_bookid = 10;
	elsif(_formiiidata != '' ) then
		v_bookid = 9;
	else
		v_bookid = 9;
		
		update kaverimrg.propertymaster set sronoofscanpages = 4
		where applicationnumber = _applicationnumber;	
	end if;
elsif(_transactiontype = 'R') then
	v_bookid = 10;
end if;*/

update kaverimrg.documentmaster d 
	set bookid = v_bookid, uploaddocdeedpath = _formiiipath, deedattachpath = _formiiipath
where d.applicationnumber = _applicationnumber;

INSERT INTO kaverimrg.fruits_data_recv_details (
	psrocode, referenceno, srocode, formiiidata, transxml, formiiipath, transxmlpath, aknowledgementno, 
	datareceiveddate, documentid, issignedformiiiuploaded, kaigreg_insertdatetime, 
	applicationnumber, transactiontype, isformiiisrsigned, applicationstatus, isaadharapatra, consideration, loantype, cropid
	--istransmitted, isrejectedtransmitted, actiondatetime, actionstatuscode, formiiidatasigned, documentstatuscode, 
) VALUES (
	_srocode, _referenceno, _srocode, _formiiidata, _transxml, _formiiipath, _transxmlpath, _acknowledgementno, 
	CURRENT_TIMESTAMP, _documentid, _issignedformiiiuploaded, CURRENT_TIMESTAMP, 
	_applicationnumber, _transactiontype, false, v_applicationstatus, _isaadharapatra, v_consideration_amt, _loanType, _cropcode
) returning requestid into v_reqid;

return v_reqid;
END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_fruits_data(_referenceno character varying, _srocode integer, _formiiidata text, _transxml text, _formiiipath character varying, _transxmlpath character varying, _acknowledgementno character varying, _documentid bigint, _issignedformiiiuploaded integer, _applicationnumber character varying, _transactiontype character, _isaadharapatra boolean, _noofpages integer, _loantype character varying, _cropcode integer) OWNER TO postgres;

--
-- Name: fn_insert_into_applicantapplicationdetails(bigint, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_into_applicantapplicationdetails(_citizenid bigint, _applicationtypeid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
	--id_val bigint;
	_applicationnumber text;
	_application text;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
		l_reset_date varchar(8);
begin
l_now := to_char(now(),'DDMMYYYY');

l_reset_date := to_char(now(),'DDMM');

select nomenclature into _nomenclature   from kaverimrg.servicesmaster where serviceid = _applicationtypeid;

if _applicationtypeid = 13 then
_servicestatus = 'CE101';
else 
_servicestatus = 'CD101';
end if;

/* In the April 01st the serquence will reset to 1 */
/*
if l_reset_date = '0104' then
ALTER SEQUENCE kaverimrg.ApplicantApplicationdetails_applicationnumber_seq RESTART WITH 1;
end if;
*/

--select lpad(nextval('kaverimrg.ApplicantApplicationdetails_applicationnumber_seq')::text,5,'0') into _inserted_id;

select lpad(nextval('kaverimrg.ApplicantApplicationdetails_applicationnumber_seq')::text,7,'0') into _inserted_id;

_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;

INSERT INTO kaverimrg.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    values  
	(_citizenid,
	_applicationnumber, 
	_applicationtypeid,
	now(),
	_servicestatus)			 
    RETURNING applicationnumber into _application;

INSERT INTO kaverimrg.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	VALUES (_applicationnumber, _servicestatus, _citizenid, 1, _citizenid);

    RETURN _application;
end
$$;


