--
-- Name: fn_insert_into_property_master_movable_property(bigint, bigint, bigint, integer, integer, numeric, integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, numeric, smallint, numeric, numeric, numeric, numeric, boolean, character varying, boolean, numeric, numeric, bigint, boolean, character varying, character varying, character varying, character varying, character varying, character varying, character varying, smallint, character varying, boolean, character varying, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_into_property_master_movable_property(_propertyid bigint, _documentid bigint, _villagecode bigint, _regsrocode integer, _srocode integer, _totalarea numeric, _unitid integer, _northboundary character varying, _southboundary character varying, _eastboundary character varying, _westboundary character varying, _landmark character varying, _marketvalue numeric, _assessment character varying, _sdcalculationstring character varying, _stampduty numeric, _transferliabilities smallint, _consideration numeric, _additionalduty numeric, _cessduty numeric, _govtduty numeric, _isexempted boolean, _exemptiondescription character varying, _ismovableproperty boolean, _sdrefund numeric, _docmarketvalue numeric, _valid1 bigint, _isimdemnified boolean, _restriction character varying, _restrictiontype character varying, _restrictiondescription character varying, _enumber character varying, _claimingblocknumber character varying, _retainingblocknumber character varying, _valuationreport character varying, _loanpurposeid smallint, _applicationnumber character varying, _verified boolean, _issroapproved character varying, _stamparticlecode integer, _stampruleid integer, _regarticlecode integer, _propertytypeid integer, _noofscanpages integer, _movablepropertydesc text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE 
_cnt integer;
v_propertyid bigint;
begin
select count(*) into _cnt from kaverimrg.propertymaster where propertyid = _propertyid
and ismovableproperty = true;
if _cnt = 0 then
INSERT INTO kaverimrg.propertymaster(
	 propertyid,
    documentid,
    villagecode,
    regsrocode,
    srocode,
    totalarea,
    unitid,
    northboundary,
    southboundary,
    eastboundary,
    westboundary,
    landmark,
    marketvalue,
    assessment,
    sdcalculationstring,
    stampduty,
    transferliabilities,
    consideration,
    additionalduty,
    cessduty,
    govtduty,
    isexempted,
    exemptiondescription,
    ismovableproperty,
    sdrefund,
    docmarketvalue,
    valid1,
    isimdemnified,
    restriction,
    restrictiontype,
    restrictiondescription,
    enumber,
    claimingblocknumber,
    retainingblocknumber,
    valuationreport,
    loanpurposeid,
    applicationnumber,
    verified,
    issroapproved,
    stamparticlecode,
    stampruleid,
     regarticlecode,
    propertytypeid,
    noofscanpages,
    movablepropertydesc)
	values
    (nextval('kaverimrg.propertymastersequence_seq'),
    _documentid,
    _villagecode,
    _regsrocode,
    _srocode,
    _totalarea,
    _unitid,
    _northboundary,
    _southboundary,
    _eastboundary,
    _westboundary,
    _landmark,
    _marketvalue,
    _assessment,
    _sdcalculationstring,
    _stampduty,
    _transferliabilities,
    _consideration,
    _additionalduty,
    _cessduty,
    _govtduty,
    _isexempted,
    _exemptiondescription,
    _ismovableproperty,
    _sdrefund,
    _docmarketvalue,
    _valid1,
    _isimdemnified,
    _restriction,
    _restrictiontype,
    _restrictiondescription,
    _enumber,
    _claimingblocknumber,
    _retainingblocknumber,
    _valuationreport,
    _loanpurposeid,
    _applicationnumber,
    _verified,
    _issroapproved,
    _stamparticlecode,
    _stampruleid,
	 _regarticlecode,
	 _propertytypeid,
	 _noofscanpages,
	 _movablepropertydesc
	) returning propertyid into v_propertyid;
	else 
	update  kaverimrg.propertymaster set
	 documentid = _documentid,
    villagecode = _villagecode,
    regsrocode = _regsrocode,
    srocode = _srocode,
    totalarea = _totalarea,
    unitid = _unitid,
    northboundary = _northboundary,
    southboundary = _southboundary,
