--

CREATE FUNCTION kaverimrg.fn_insert_into_slottxn(kaverimrg.slot_booking_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
Declare
v_schid bigint;
v_schid1 bigint;
 cit_id text;
   property_arry $1%type;
   v_sltid bigint;
   var_r record;
   v_pid bigint[];
v_cnt integer;
v_cnt1 integer;
v_sltbookingid text;
begin
Select count(*) into v_cnt from kaverimrg.slotmaster where sltid in 
(select a._sltid from unnest($1) a) ;
FOR property_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray($1))
loop
if v_cnt = 0 then 
INSERT INTO kaverimrg.slotmaster(
	sltid,
    srocode,-- integer NOT NULL,
    serviceid,-- integer NOT NULL,
    sltdate ,--date,-- NOT NULL,
    sltstarttime,-- timestamp without time zone NOT NULL,
    sltendtime,-- timestamp without time zone NOT NULL,
    sltcapacity ,--integer,-- DEFAULT 0,
    sltavlcapacity,-- integer,-- DEFAULT 0,
    sltisactive,-- boolean,
    sltexpstarttime,-- timestamp without time zone,
    sltexpendtime,-- timestamp without time zone,
    sltexpcapacity,-- integer DEFAULT 0,
    sltexpisactive,-- boolean,
    sltcomments,-- text COLLATE pg_catalog.default,
    crtusr,-- character varying(10) COLLATE pg_catalog.default,
    crtdt,-- timestamp without time zone,
    lstupusr,-- character varying(10) COLLATE pg_catalog.default,
    lstupddt --timestamp without time zone,
) select 
	null,--nextval('kaverimrg.slotmaster_sltid_seq'),
    _srocode,-- integer NOT NULL,
    _serviceid,-- integer NOT NULL,
    _sltdate,-- date,-- NOT NULL,
    _sltstarttime,-- timestamp without time zone NOT NULL,
    _sltendtime,-- timestamp without time zone NOT NULL,
    _sltcapacity ,--integer,-- DEFAULT 0,
    _sltavlcapacity,-- integer,-- DEFAULT 0,
    _sltisactive,-- boolean,
    _sltexpstarttime,-- timestamp without time zone,
    _sltexpendtime,-- timestamp without time zone,
    _sltexpcapacity,-- integer DEFAULT 0,
    _sltexpisactive,-- boolean,
    _sltcomments,-- text COLLATE pg_catalog.default,
    _crtusr,-- character varying(10) COLLATE pg_catalog.default,
    _crtdt,-- timestamp without time zone,
    _lstupusr,-- character varying(10) COLLATE pg_catalog.default,
    _lstupddt --timestamp without time zone,
from unnest(property_arry)	
	 returning sltid::bigint into v_sltid;
	else
	update kaverimrg.slotmaster set
	srocode= _srocode,
    serviceid=_serviceid,
    sltdate=_sltdate,
    sltstarttime=_sltstarttime,
    sltendtime=_sltendtime,
    sltcapacity=_sltcapacity ,
    sltavlcapacity=_sltavlcapacity,
    sltisactive=_sltisactive,
    sltexpstarttime=_sltexpstarttime,
    sltexpendtime=_sltexpendtime,
    sltexpcapacity=_sltexpcapacity,
    sltexpisactive=_sltexpisactive,
    sltcomments=_sltcomments,
    crtusr=_crtusr,
    crtdt=_crtdt,
    lstupusr=_lstupusr,
    lstupddt=_lstupddt
	from unnest(property_arry) where sltid in 
			 (select a._sltid from unnest(property_arry) a) 
			 RETURNING sltid::bigint into v_sltid;
	end if;
	/*end loop;
	Select count(*) into v_cnt1 from kaverimrg.slottxn where sltid in 
(select a._sltid from unnest($1) a) ;
FOR property_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray($1))
	loop
	if v_cnt1 = 0 then
INSERT INTO kaverimrg.slottxn(
	sltbookingid,
    sltid,
    sltbookedfor,
    sltbookedon,
    sltbookedby,
    usrtypeid,
    sltservicestatus,
    sltreservice,
	applicationnumber
)
	select _sltbookingid,--nextval('kaverimrg.slt_seq'), 
	 v_sltid--nextval('kaverimrg.slot_seq'),
    _sltbookedfor,
    _sltbookedon,
    _sltbookedby,
    _usrtypeid,
    _sltservicestatus,
    _sltreservice,
	_applicationnumber
     from unnest(property_arry)	
	  returning sltid::bigint into v_sltid;
	 else
	 update kaverimrg.slottxn set
	 sltbookedfor= _sltbookedfor,
    sltbookedon=_sltbookedon,
    sltbookedby=_sltbookedby,
    usrtypeid=_usrtypeid,
    sltservicestatus=_sltservicestatus,
    sltreservice=_sltreservice,
	applicationnumber=_applicationnumber
	from unnest(property_arry) where sltid in 
			 (select a._sltid from unnest(property_arry) a) 
			 returning sltid::bigint into v_sltid;
	end if;*/
	v_pid := array_append(v_pid,v_sltid);
	end loop;
    Return v_pid;
   END;
$_$;


ALTER FUNCTION kaverimrg.fn_insert_into_slottxn(kaverimrg.slot_booking_input[]) OWNER TO postgres;

--
-- Name: fn_insert_into_slottxn(bigint, integer, integer, timestamp without time zone, bigint, integer, integer, boolean, character varying, integer, integer, timestamp without time zone, text, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_into_slottxn(_sltbookingid bigint, _sltid integer, _sltbookedfor integer, _sltbookedon timestamp without time zone, _sltbookedby bigint, _usrtypeid integer, _sltservicestatus integer, _sltreservice boolean, _applicationnumber character varying, _appointmenttypeid integer, _srocode integer, _sltbookeddate timestamp without time zone, _sltbooktime text, _lstupddate timestamp without time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_schid bigint;
v_schid1 bigint;
_cnt integer;
_cnt1 integer;
v_slotsrvcid bigint;
v_slotbookingid bigint;
v_slot bigint;
v_sltservicestatus integer;
v_cnt integer;
v_sltavlcapacity integer;
v_applicationnumber text;
begin

if COALESCE(_sltbookingid,0)>0 and _sltservicestatus=3 then
select sltid into v_schid from kaverimrg.slottxn where sltbookingid=_sltbookingid;
select applicationnumber into v_applicationnumber from kaverimrg.slottxn where sltbookingid=_sltbookingid;
select sltavlcapacity into v_sltavlcapacity from kaverimrg.slotmaster where sltid = v_schid FOR UPDATE;
update kaverimrg.slotmaster set sltavlcapacity = v_sltavlcapacity + 1 where sltid = v_schid;
update kaverimrg.applicantapplicationdetails set currentstatus='CD107' where applicationnumber=v_applicationnumber;	
update  kaverimrg.slottxn set sltservicestatus = 3 where sltbookingid=_sltbookingid;
v_slotbookingid=-1;

elseif COALESCE(_sltbookingid,0)>0 and _sltservicestatus=2 then
select sltid into v_schid from kaverimrg.slottxn where sltbookingid=_sltbookingid;
select sltavlcapacity into v_sltavlcapacity from kaverimrg.slotmaster where sltid = v_schid FOR UPDATE;
update kaverimrg.slotmaster set sltavlcapacity = v_sltavlcapacity + 1 where sltid = v_schid;
update  kaverimrg.slottxn set sltservicestatus = 2 where sltbookingid=_sltbookingid;

select sltavlcapacity into v_sltavlcapacity from kaverimrg.slotmaster where sltid = _sltid FOR UPDATE;

if v_sltavlcapacity > 0 then

update kaverimrg.slotmaster set sltavlcapacity = v_sltavlcapacity - 1 where sltid = _sltid;

update kaverimrg.applicantapplicationdetails set currentstatus='CD108' where applicationnumber=_applicationnumber;	
_sltservicestatus=1;
INSERT INTO kaverimrg.slottxn(
	--sltbookingid,
    sltid,
    sltbookedfor,
    sltbookedon,
    sltbookedby,
    usrtypeid,
    sltservicestatus,
    sltreservice,
    applicationnumber,
    appointmenttypeid,
    srocode,
    sltbookeddate,
    sltbooktime,
	lstupddate,
	oldsltbookingid
)
	VALUES (--null,--nextval('kaverimrg.slottxn_seq'), 
	 _sltid,
    _sltbookedfor,
    _sltbookedon,
    _sltbookedby,
    _usrtypeid,
    _sltservicestatus,
    _sltreservice,
    _applicationnumber,
    _appointmenttypeid,
    _srocode,
    _sltbookeddate,
    _sltbooktime,
	_lstupddate,
	_sltbookingid) RETURNING sltbookingid into v_slotbookingid;
    else  
   update kaverimrg.slotmaster set sltavlcapacity = v_sltavlcapacity where sltid = _sltid;
   v_slotbookingid=0;
end if;

else
select count(1) into v_slot  from kaverimrg.slottxn where applicationnumber=_applicationnumber and sltservicestatus=1;
if v_slot >= 1 then
select sltbookingid into v_slotbookingid  from kaverimrg.slottxn where applicationnumber=_applicationnumber and sltservicestatus=1;
else 

select sltavlcapacity into v_sltavlcapacity from kaverimrg.slotmaster where sltid = _sltid FOR UPDATE;

if v_sltavlcapacity > 0 then

update kaverimrg.slotmaster set sltavlcapacity = v_sltavlcapacity - 1 where sltid = _sltid;

update kaverimrg.applicantapplicationdetails set currentstatus='CD108' where applicationnumber=_applicationnumber;	

INSERT INTO kaverimrg.slottxn(
	--sltbookingid,
    sltid,
    sltbookedfor,
    sltbookedon,
    sltbookedby,
    usrtypeid,
    sltservicestatus,
    sltreservice,
    applicationnumber,
    appointmenttypeid,
    srocode,
    sltbookeddate,
    sltbooktime,
	lstupddate
)
	VALUES (--null,--nextval('kaverimrg.slottxn_seq'), 
	 _sltid,
    _sltbookedfor,
    _sltbookedon,
    _sltbookedby,
    _usrtypeid,
    _sltservicestatus,
    _sltreservice,
    _applicationnumber,
    _appointmenttypeid,
    _srocode,
    _sltbookeddate,
    _sltbooktime,
	_lstupddate) RETURNING sltbookingid into v_slotbookingid;
    else  
   update kaverimrg.slotmaster set sltavlcapacity = v_sltavlcapacity where sltid = _sltid;
   v_slotbookingid=0;
end if;
end if;
end if;

Return v_slotbookingid;
   END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_into_slottxn(_sltbookingid bigint, _sltid integer, _sltbookedfor integer, _sltbookedon timestamp without time zone, _sltbookedby bigint, _usrtypeid integer, _sltservicestatus integer, _sltreservice boolean, _applicationnumber character varying, _appointmenttypeid integer, _srocode integer, _sltbookeddate timestamp without time zone, _sltbooktime text, _lstupddate timestamp without time zone) OWNER TO postgres;

