--

CREATE FUNCTION kaverimrg.fn_insert_k1documentdetails(_applicationnumber character varying, _finalregistrationnumber character varying, _bookid integer, _stampduty numeric, _srocode integer, _registrationdate timestamp without time zone, _prevregid bigint, _prevarticlecode integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_applicationnumber character varying;
   v_cnt integer;
begin

Select count(*) into v_cnt from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber;

if v_cnt = 0 then

INSERT INTO kaverimrg.k1documentdetails( 
	applicationnumber ,
	finalregistrationnumber,
	bookid ,
	stampduty ,  
	srocode ,
	registrationdate,
	prevregid,
	prevarticlecode
)
    select  
	_applicationnumber ,
	_finalregistrationnumber,
	_bookid ,
	_stampduty ,
	_srocode ,
	_registrationdate,
	_prevregid,
	_prevarticlecode
	returning applicationnumber::character varying into v_applicationnumber;
else

  update kaverimrg.k1documentdetails
  set 
	applicationnumber = _applicationnumber,
	finalregistrationnumber = _finalregistrationnumber,
	bookid = _bookid ,
	stampduty = _stampduty,
	srocode = _srocode,
	registrationdate = _registrationdate,
	prevregid=_prevregid,
	prevarticlecode=_prevarticlecode
where applicationnumber = _applicationnumber
		 returning applicationnumber::character varying into v_applicationnumber;

	end if;
Return v_applicationnumber;
end;
$$;


