CREATE FUNCTION kaverimrg.fn_insert_marriageregistration(_applicationnumber character varying, _marriagetypeid integer, _marriagemodeid integer, _dateofmarriage timestamp without time zone, _housebuildingname character varying, _streetaddress character varying, _statecode bigint, _districtcode bigint, _talukacode bigint, _hoblicode bigint, _cityvillagecode bigint, _pincode bigint, _combinephotopath character varying, _bridegroomphoto character varying DEFAULT NULL::character varying, _bridephoto character varying DEFAULT NULL::character varying, _isprimaryapplicantbride boolean DEFAULT NULL::boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_registrationid integer;
v_dateofmarriage timestamp without time zone;
begin
select count(*) into v_cnt from kaverimrg.marriageregistration where applicationnumber =_applicationnumber ;

if _marriagetypeid = 2 then

	v_dateofmarriage = null;
	
else

	v_dateofmarriage = _dateofmarriage;
	
end if;

if v_cnt = 0 then
insert into kaverimrg.marriageregistration(
	registrationid,
	applicationnumber,
	marriagetypeid,
	marriagemodeid,
	dateofmarriage,
	housebuildingname,
	streetaddr,
	statecode,
	districtcode,
	talukacode,
	hoblicode,
	cityvillagecode,
	pincode,
	combinephotopath,
	regsrocode,
	bridegroomphoto,
	bridephoto,
	isprimaryapplicantbride
) 
values(
	nextval('kaverimrg.registrationid_seq'),
	_applicationnumber,
	_marriagetypeid,
	_marriagemodeid,
	v_dateofmarriage,
	_housebuildingname,
	_streetaddress,
	_statecode,
	_districtcode,
	_talukacode,
	_hoblicode,
	_cityvillagecode,
	_pincode,
	_combinephotopath,
	0,
	_bridegroomphoto,
	_bridephoto,
	_isprimaryapplicantbride
) returning registrationid into v_registrationid;
else

if (_marriagetypeid = 2) then

update kaverimrg.marriageregistration set
	--applicationnumber=_applicationnumber,
	marriagetypeid=_marriagetypeid,
	marriagemodeid=_marriagemodeid,
	dateofmarriage=v_dateofmarriage,
	housebuildingname=_housebuildingname,
	streetaddr=_streetaddress,
	combinephotopath=_combinephotopath,
	bridegroomphoto=_bridegroomphoto,
	bridephoto=_bridephoto,
	isprimaryapplicantbride=_isprimaryapplicantbride
where applicationnumber =_applicationnumber 
returning registrationid into v_registrationid;


else
update kaverimrg.marriageregistration set
	--applicationnumber=_applicationnumber,
	marriagetypeid=_marriagetypeid,
	marriagemodeid=_marriagemodeid,
	dateofmarriage=v_dateofmarriage,
	housebuildingname=_housebuildingname,
	streetaddr=_streetaddress,
	statecode=_statecode,
	districtcode=_districtcode,
	talukacode=_talukacode,
	hoblicode=_hoblicode,
	cityvillagecode=_cityvillagecode,
	pincode=_pincode,
	combinephotopath=_combinephotopath,
	bridegroomphoto=_bridegroomphoto,
	bridephoto=_bridephoto,
	isprimaryapplicantbride=_isprimaryapplicantbride
where applicationnumber =_applicationnumber 
returning registrationid into v_registrationid;
end if;
end if;
return v_registrationid;
end;
$$;


