--
-- Name: fn_insert_masvaluation_detail(kaverimrg.valratedetail_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_masvaluation_detail(p_valratedetail kaverimrg.valratedetail_input[] DEFAULT NULL::kaverimrg.valratedetail_input[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
  v_valratedetail_arry kaverimrg.valratedetail_input[];
   v_propertytypeid bigint;   
   v_agrilandtypeid bigint;
   v_amenitiesid bigint;
   v_valratedetailid bigint;
   v_cnt bigint;
   v_isdelete boolean ;
   v_success int ;
BEGIN

if(p_valratedetail is not null and array_length(p_valratedetail,1)>0 ) then
--   v_success:='Success';
 FOR v_valratedetail_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_valratedetail)) 
					loop
		v_cnt:= 0;
	begin
	
	--select count(*) into v_cnt from kaverimrg.mas_valratedetail where valratedetailid in 
