ALTER FUNCTION kaverimrg.fn_insert_masvaluation_detail_temp(p_valratedetail kaverimrg.valratedetail_input[]) OWNER TO postgres;

--
-- Name: fn_insert_masvaluation_header(bigint, timestamp without time zone, bigint, text, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_masvaluation_header(p_srocode bigint, p_effectivedate timestamp without time zone, p_sfdaid bigint, p_circularpath text, p_circularinfo text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_valheaderid bigint;
BEGIN 
		insert into kaverimrg.mas_valrateheader 
		(srocode,effectivedate,active,sfdaid,circularpath,circularinfo,updatedby,requestdate)
		values (p_srocode,p_effectivedate,'true',p_sfdaid,p_circularpath,p_circularinfo,p_sfdaid::character varying,current_timestamp) 
		returning valrateheaderid into v_valheaderid;
		
		insert into kaverimrg.mas_valratedetail 
		(valrateheaderid,roadcode,srocode,propertytypeid,agrilandtypeid,
			floorid,amenitiesid, unitid,rate,sfdaid,updatedby,effectivedate)
		select v_valheaderid,roadcode,srocode,propertytypeid,agrilandtypeid,
			floorid,amenitiesid, unitid,rate,p_sfdaid,p_sfdaid::character varying,p_effectivedate
		from kaverimrg.mas_valuationrates 
		where srocode = p_srocode and sfdaid=p_sfdaid and valrateheaderid is null;
		
		update kaverimrg.mas_valuationrates set valrateheaderid=v_valheaderid,effectivedate=p_effectivedate
		where srocode = p_srocode and sfdaid=p_sfdaid and valrateheaderid is null;

	return v_valheaderid; 
END;
$$;


