--

CREATE FUNCTION kaverimrg.fn_insert_mrg_feedetail(p_mrgrequiredfees kaverimrg.mrg_requiredfees_input[]) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
     v_mrgrequiredfees p_mrgrequiredfees%type;
 v_cnt integer;
 v_applicationnumber character varying;
 v_srocode int;
 
BEGIN
	/* Fees Required */
	
	if(p_mrgrequiredfees is not null and array_length(p_mrgrequiredfees,1)>0 ) then
FOR v_mrgrequiredfees IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_mrgrequiredfees))
loop
v_cnt:= 0;
Select count(*) into v_cnt from kaverimrg.mrg_requiredfees where applicationnumber in 
(select a._applicationnumber from unnest(v_mrgrequiredfees) a) and feeruleid in 
(select a._feeruleid from unnest(v_mrgrequiredfees) a);

select regsrocode into v_srocode from kaverimrg.applicantapplicationdetails a where applicationnumber in
(select a._applicationnumber from unnest(v_mrgrequiredfees) a);

if v_cnt = 0 then 
INSERT INTO kaverimrg.mrg_requiredfees(
requiredfeeid,
mrgregistrationid,
feeruleid,
payableamount,
ispaid,
serviceid,
feedescription,
applicationnumber,
srocode,
amountpaid
)
select nextval('kaverimrg.mrg_requiredfees_seq'),
a._mrgregistrationid,
a._feeruleid,
a._payableamount,
a._ispaid,
a._serviceid,
a._feedescription,
a._applicationnumber,
v_srocode,
a._payableamount
from unnest(v_mrgrequiredfees) a
RETURNING applicationnumber::character varying into v_applicationnumber;
else 
	 update kaverimrg.mrg_requiredfees set
	 mrgregistrationid=a._mrgregistrationid,
   feeruleid=a._feeruleid,
   payableamount=a._payableamount,
   ispaid=a._ispaid,
   serviceid=a._serviceid,
   feedescription=a._feedescription,
   applicationnumber = a._applicationnumber,
   srocode = v_srocode,
   amountpaid = a._payableamount
	from unnest(v_mrgrequiredfees) a where applicationnumber in 
			 (select a._applicationnumber from unnest(v_mrgrequiredfees) a) and feeruleid in 
(select a._feeruleid from unnest(v_mrgrequiredfees) a)
		RETURNING applicationnumber::character varying into v_applicationnumber;
	 end if;
	
--	if a._ispaid = true 
--	
--	update kaverimrg.mrg_requiredfees set amountpaid = a._payableamount from unnest(v_mrgrequiredfees) a where applicationnumber in 
--			 (select a._applicationnumber from unnest(v_mrgrequiredfees) a) and feeruleid in 
--	(select a._feeruleid from unnest(v_mrgrequiredfees) a)
	
	end loop;
	end if;
        Return v_applicationnumber;
		
end;
$$;


