--
-- Name: fn_insert_multiplerole(integer, bigint, boolean, integer, kaverimrg.multiplerole_type[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_multiplerole(_userid integer, _phoneno bigint, _isactive boolean, _updatedby integer, _rollinfo_array kaverimrg.multiplerole_type[] DEFAULT NULL::kaverimrg.multiplerole_type[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$




DECLARE

v_permission_row record;
v_count integer;
v_counter integer;
BEGIN 

	if(_rollinfo_array is not null and array_length(_rollinfo_array,1)=1 ) then
	
		for v_permission_row in 
				(
				 	 select a.userid,a.designationid  from unnest(_rollinfo_array)a 
				)
				
					loop
						
						update kaverimrg.departmentusers set designationid=v_permission_row.designationid,
						mobileno=_phoneno,serviceflag=_isactive,createdby=_updatedby where userid=_userid;
		
	  					 delete from kaverimrg.departmentuserroles  where userid=_userid and (mappeduserid is null or mappeduserid=0);
						
							
					end loop;
		
	
	elsif(_rollinfo_array is not null and array_length(_rollinfo_array,1)>1 ) then

			
				for v_permission_row in 
				(
				 (select userid,designationid  from kaverimrg.departmentuserroles where userid=_userid  and  (mappeduserid is null or mappeduserid=0)
				 except 
				 select a.userid,a.designationid  from unnest(_rollinfo_array)a )
				 
				 union all
				 
				 select a.userid,a.designationid  from unnest(_rollinfo_array)a limit 1
				 
				 
				)
				
					loop
						
						delete from kaverimrg.departmentuserroles  where  userid=v_permission_row.userid and designationid=v_permission_row.designationid and (mappeduserid is null or mappeduserid=0);
							
					end loop;
		
				v_counter:=1;
				 for v_permission_row in  
				 (	select a.userid,a.designationid  from unnest(_rollinfo_array)a  )
				 	
				 	loop
					    if v_counter=1 then
						
							update kaverimrg.departmentusers set designationid=v_permission_row.designationid,
							mobileno=_phoneno,serviceflag=_isactive,createdby=_updatedby where userid=_userid;
						ELSE
						
						
						
								select count(*) into v_count from kaverimrg.departmentuserroles  where  userid=v_permission_row.userid and
								designationid=v_permission_row.designationid and (mappeduserid is null or mappeduserid=0);
							
								if v_count=0 then
						
									insert into kaverimrg.departmentuserroles (userid,designationid,updatedby)
									values(v_permission_row.userid,v_permission_row.designationid,_updatedby);
								end if;
						end if;
					 v_counter:=v_counter+1;
					 	
					 	
				 		
				 	end loop;

end if;
 	
		


 
raise notice 'roll updated for rollid %',_userid;
return _userid;
  

END;

$$;


ALTER FUNCTION kaverimrg.fn_insert_multiplerole(_userid integer, _phoneno bigint, _isactive boolean, _updatedby integer, _rollinfo_array kaverimrg.multiplerole_type[]) OWNER TO postgres;

