--

CREATE FUNCTION kaverimrg.fn_insert_openbuiltvaluationdetails(p_openbuiltvaluationdetails kaverimrg.val_openbuiltvaluationdetails_input[] DEFAULT NULL::kaverimrg.val_openbuiltvaluationdetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_openbuiltvaluationdetails kaverimrg.val_openbuiltvaluationdetails_input[];
v_cnt integer;
v_valid bigint;
 v_pid bigint[];
begin
		if(p_openbuiltvaluationdetails is not null and array_length(p_openbuiltvaluationdetails,1)>0 ) then
				FOR v_arry_openbuiltvaluationdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_openbuiltvaluationdetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaverimrg.val_openbuiltvaluationdetails where openbuiltvalid in 
						(select a._openbuiltvalid from unnest(v_arry_openbuiltvaluationdetails) a) ;
						if v_cnt = 0 then
							insert into kaverimrg.val_openbuiltvaluationdetails (
								 openbuiltvalid,
									propertytypeid,
									roadid,
									unitid,
									rate,
									valuationid,
									verified,
									openbuiltrateid,
									srocode,
									regsrocode)
									select nextval('kaverimrg.val_openbuiltvaluationdetails_seq'),
									a._propertytypeid,
									a._roadid,
									a._unitid,
									a._rate,
									a._valuationid,
									a._verified,
									a._openbuiltrateid,
									a._srocode,
									a._regsrocode
								from unnest(v_arry_openbuiltvaluationdetails) a
								 returning valuationid::bigint into v_valid;
								--v_pid := array_append(v_pid,v_valid);
						else
							update kaverimrg.val_openbuiltvaluationdetails set
												--annexuredetailsid = a._annexuredetailsid,
												propertytypeid=a._propertytypeid,
									           roadid=a._roadid,
									           unitid=a._unitid,
									           rate=a._rate,
									          valuationid=a._valuationid,
									          verified=a._verified,
									          openbuiltrateid=a._openbuiltrateid,
									          srocode=a._srocode,
									          regsrocode=a._regsrocode
												 from unnest(v_arry_openbuiltvaluationdetails) a where openbuiltvalid in 
														 (select a._openbuiltvalid from unnest(v_arry_openbuiltvaluationdetails) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						--v_pid := array_append(v_pid,v_valid);
					end loop;
			end if;
Return v_valid;
   END;
$$;


