--

CREATE FUNCTION kaverimrg.fn_insert_orgdatajslip(kaverimrg.orgdatajslip_input[] DEFAULT NULL::kaverimrg.orgdatajslip_input[]) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare 
v_cnt integer;
v_applicationnumber character varying;
begin 
	select count(*) into v_cnt from kaverimrg.orgdatajslip where propertyid  in (select a2._propertyid from unnest($1) a2) 
and partyid in (select a3._partyid from unnest($1)a3) and partytypeid in (select a4._partytypeid from unnest($1) a4);

if (v_cnt=0)

then 
insert into kaverimrg.orgdatajslip(partyid ,documentid ,propertyid,partytypeid ,firstname ,mainownerno ,ownerno ,transactextacre ,transactextgunta ,transactextfgunta ,applicationnumber,relativename,relationship)
select a._partyid 
,a._documentid 
,a._propertyid 
,a._partytypeid
,a._firstname 
,a._mainownereno 
,a._ownerno ,a._transactextacre ,a._transactextgunta ,a._transactextfgunta ,a._applicationnumber,a._relativename,a._relationship from unnest($1) a;
 select a1._applicationnumber into v_applicationnumber from unnest($1) a1 ;

else 
v_applicationnumber:='Already Exists';
end if;

return  v_applicationnumber;
end;
$_$;


