--

CREATE FUNCTION kaverimrg.fn_insert_otherreceiptdetails(kaverimrg.otherpaymentdetails_input[], _otherfeerequired kaverimrg.otherfeereequired[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
	  DECLARE
	  v_Arr bigint;
	  v_departmentuserid bigint;
	  
	  begin
		 
		  select departmentuserid into v_departmentuserid from unnest(_otherfeerequired);
		 
	  insert into kaverimrg.otherreceiptdetails
       (receiptid,
       partyfirstname,
       partymiddlename,
       partylastname,
       receipttype,
       receiptdate,
       paymentmode,
       receipttotal,
       paymentdescription,
       ifsccode,
       micrcode,
       ddchallannumber,
       dddate ,
       subpurposedetails,
       receipttypefromdate,
       receipttypetodate,
       financialYears,
       bookdetails,
       ceritificateruletype,departmentuserid)
       select 
       nextval('kaverimrg.otherrecdetail_receiptid_seq'),
       b.partyfirstname ,
       b.partymiddlename ,
       b.partylastname ,
       b.receipttype,
       b.receiptdate,
       b.paymentmode,
       b.receipttotal,
       b.paymentdescription,
       b.ifsccode,
       b.micrcode ,
       b.ddchallannumber,
       b.dddate,
       b.subpurposedetails,
       b.receipttypefromdate,
       b.receipttypetodate,
       b.financialYears,
       b.bookdetails,
       b.ceritificateruletype, 
       v_departmentuserid from unnest($1) b
	  	returning receiptid::bigint into v_Arr;
	   
	   insert into kaverimrg.otherfeesrequired 
	   (feerulecode,
	   applicationnumber,
	   feerequied,
	   receiptid,
	   departmentuserid)
	   select 
	   c.feerulecode,
	   c.applicationnumber,
	   c.feerequired,
		v_Arr,
	   v_departmentuserid
	  from unnest(_otherfeerequired) c;
		
	
		 return v_Arr;
	  
	  end;
	 
	  $_$;


