--

CREATE FUNCTION kaverimrg.fn_insert_party_info(p_partydetails kaverimrg.party_input[] DEFAULT NULL::kaverimrg.party_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
   cit_id text;
  -- party_arry $1%type;
  v_party_arry kaverimrg.party_input[];
   v_txt text;
   v_partyid bigint;
   v_partyid1 bigint;
   v_partytypeid integer;
   v_cnt integer;
   var_r record;
   v_linkpartyid bigint;
   v_pid bigint[];
BEGIN
Select count(*) into v_cnt from kaverimrg.partyinfo where partyid in 
(select a._partyid from unnest($1) a) ;
if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
 --FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray($1))   
 FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partydetails)) 
					loop
						v_cnt:= 0;
 Select count(*) into v_cnt from kaverimrg.partyinfo where partyid in 
						(select a._partyid from unnest(v_party_arry) a) ;
	 if v_cnt = 0 then
  INSERT INTO kaverimrg.partyinfo(partyid,
							 srocode, documentid, partytypeid, firstname, middlename, lastname, address, age, sex, isexecutor, ispresenter, admissiondate, aliasname, correctedname, relationship, relativename, epic, pan, phonenumber, availableextacre, availableextgunta, availableextfgunta, bincom, category, dateofdeath, fingerid, fingerverificationstatusid, ispartofrtc, landcode, mainownerno, ownerno, partypoa, photopath, poaadmission, poapresentation, primaryseller, profession, restriction, restrictiondescription, restrictiontype, section88exemption, thumbmatchfailedreasonid, thumbminutiae, thumbpath, totalextacre, totalextgunta, totalextfgunta, transactextacre, transactextgunta, transactextfgunta, volumename, hasgpa, isaua, importedpartyparentid, salutationid, isorganization, organizationid,applicationnumber,verified,issroapproved,districtcode,talukcode,hoblicode,villagecode,
							tanno,yearofincorp,orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname,linkpartyid,housenumber,pin,propertyid,propertynumber,idprooftypeid,coveringLetterNo,section88File,idcardhash)
    select  nextval('kaverimrg.partyinfo_partyid_seq'),
	--_partyid,
	_srocode, _documentid, _partytypeid, _firstname,_middlename,_lastname, _address,_age,_sex,_isexecutor,
	_ispresenter,_admissiondate, _aliasname,_correctedname,_relationship,_relativename,_epic,rPAD('*', (LENGTH(_pan) - 4), '*')||right(_pan , 4),_phonenumber,
	_availableextacre ,_availableextgunta ,_availableextfgunta ,_bincom,_category,_dateofdeath,_fingerid ,
	_fingerverificationstatusid ,_ispartofrtc ,_landcode ,_mainownerno ,_ownerno ,_partypoa,_photopath,
	_poaadmission ,_poapresentation ,_primaryseller ,_profession,_restriction,_restrictiondescription,
	_restrictiontype,_section88exemption ,_thumbmatchfailedreasonid ,_thumbminutiae ,_thumbpath,_totalextacre ,
	_totalextgunta ,_totalextfgunta ,_transactextacre ,_transactextgunta ,_transactextfgunta ,_volumename,
	_hasgpa ,_isaua ,_importedpartyparentid ,_salutationid ,_isorganization ,_organizationid,_applicationnumber,
	_verified,_issroapproved,_districtcode,_talukcode,_hoblicode,_villagecode,
	 _tanno,
    _yearofincorp,
    _orgpoaauthsignfname,
    _orgpoaauthsignmname,
    _orgpoaauthsignlname,
    _linkpartyid,
	_housenumber,
	_pin,
	_propertyid,
	_propertynumber,
	_idprooftypeid,
	_coveringLetterNo,
	_section88File,
	encode(sha256(_pan::bytea),'hex')
	--from unnest(party_arry)	
	from unnest(v_party_arry)
    RETURNING partyid::bigint into v_partyid;
	 else
