--
-- Name: fn_insert_party_info_020323(kaverimrg.partyinfo_input[], bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_party_info_020323(p_partydetails kaverimrg.partyinfo_input[] DEFAULT NULL::kaverimrg.partyinfo_input[], p_linkpartyid bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$

DECLARE
  v_party_arry kaverimrg.partyinfo_input[];
   v_partyid bigint;
   v_cnt integer;
   v_partyid_guid varchar(50);
   v_party_success boolean default 'true';
   v_party_exists boolean default 'false';
   v_isdelete boolean ;
   v_application varchar(100);
BEGIN

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
   
 FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partydetails)) 
					loop
		v_cnt:= 0;
		v_partyid:=null;
		v_partyid_guid :=null;
		v_party_exists := 'false';

	begin					
	select a._partyid,(a._partyid ~ '^[0-9]+$'),a._verified,a._applicationnumber into 
		v_partyid_guid,v_party_exists,v_isdelete,v_application from unnest(v_party_arry) a ;
		
	if (v_partyid_guid is not null) then 
	  Select count(*) into v_cnt from kaverimrg.partyinfo where partyid in 
					(case when v_party_exists ='true' then v_partyid_guid::bigint 
							   else 0 end);							   
	if v_cnt = 0 then
  INSERT INTO kaverimrg.partyinfo(partyid,
srocode,DOCUMENTID, partytypeid, firstname, middlename, lastname, address, age, sex, 
isexecutor, ispresenter,  aliasname, relationship, relativename,  pan, 
	phonenumber, dateofdeath, partypoa, profession, restriction, restrictiondescription, restrictiontype, section88exemption, 
isaua, salutationid, isorganization, organizationid,applicationnumber,verified,districtcode,talukcode,
hoblicode,villagecode,
tanno,yearofincorp,orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname,linkpartyid,housenumber,pin,
		idprooftypeid,propertyid,availableextacre,availableextgunta,availableextfgunta,
	bincom,category,landcode,mainownerno,ownerno,totalextacre,totalextgunta,totalextfgunta,
	transactextacre,transactextgunta,transactextfgunta,isconsentwitness,isprivateattendance,
			coveringLetterNo,section88File,isduplicate,duplicatepartyid,photopath,thumbpath,isendorseprinted,islateapperance,admissiondate )
    select  nextval('kaverimrg.partyinfo_partyid_seq'),
	_srocode,0, _partytypeid, _firstname,_middlename,_lastname, coalesce(_address,' '),_age,_sex,_isexecutor,
	_ispresenter, _aliasname,_relationship,_relativename,_pan,_phonenumber,
	_dateofdeath,_partypoa,_profession,_restriction,_restrictiondescription,
	_restrictiontype,_section88exemption ,_isaua,_salutationid ,_isorganization ,_organizationid,_applicationnumber,
	_verified,_districtcode,_talukcode,_hoblicode,_villagecode,
	 _tanno,_yearofincorp,_orgpoaauthsignfname,_orgpoaauthsignmname,_orgpoaauthsignlname,
    coalesce(p_linkpartyid,(CASE WHEN _linkpartyid IS NOT NULL THEN _linkpartyid::BIGINT ELSE NULL END),NULL),_housenumber,_pin,_idprooftypeid,
	_propertyid,_availableextacre,_availableextgunta,_availableextfgunta,
	_bincom,_category,_landcode,_mainownerno,_ownerno,_totalextacre,_totalextgunta,_totalextfgunta,
	_transactextacre,_transactextgunta,_transactextfgunta ,_isconsentwitness,_isprivateattendance,
	_coveringLetterNo,_section88File,_isduplicate,_duplicatepartyid,_photopath,_thumbpath,_isendorseprinted,_islateapperance,_admissiondate
	from unnest(v_party_arry)
    RETURNING partyid::bigint into v_partyid;
	 else
  update kaverimrg.partyinfo set
srocode = a._srocode,
partytypeid = a._partytypeid, 
firstname = a._firstname, 
middlename = a._middlename, 
lastname = a._lastname, 
address = coalesce(a._address,' '), 
age = a._age, 
sex = a._sex, 
isexecutor = a._isexecutor, 
ispresenter=a._ispresenter, 
aliasname=a._aliasname, 
relationship=a._relationship, 
relativename=a._relativename,
pan=a._pan, 
phonenumber=a._phonenumber, 
dateofdeath=a._dateofdeath, 
partypoa=a._partypoa, 
profession=a._profession, 
restriction=a._restriction, 
restrictiondescription=a._restrictiondescription, 
restrictiontype=a._restrictiontype, 
section88exemption=a._section88exemption, 
isaua=a._isaua,
salutationid=a._salutationid, 
isorganization=a._isorganization, 
organizationid=a._organizationid,
applicationnumber=a._applicationnumber,
verified=a._verified,
districtcode=a._districtcode,
talukcode=a._talukcode,
hoblicode=a._hoblicode,
villagecode=a._villagecode,
tanno = a._tanno,
yearofincorp = a._yearofincorp,
orgpoaauthsignfname = a._orgpoaauthsignfname, 
orgpoaauthsignmname = a._orgpoaauthsignmname, 
orgpoaauthsignlname = a._orgpoaauthsignlname,
housenumber=a._housenumber,
	pin=a._pin,
	idprooftypeid=a._idprooftypeid,
	isconsentwitness=a._isconsentwitness,
	isprivateattendance=a._isprivateattendance	,
	coveringLetterNo=a._coveringLetterNo,
	section88File=a._section88File,
	isduplicate=a._isduplicate,
	duplicatepartyid =a._duplicatepartyid,
	photopath=a._photopath,
	thumbpath=a._thumbpath,
	isendorseprinted=a._isendorseprinted,
	islateapperance =a._islateapperance,
	admissiondate =a._admissiondate
	from unnest(v_party_arry) a
  where partyid = v_partyid_guid::bigint
 RETURNING partyid::bigint into v_partyid;
 end if;
 end if;
 -- exception when others then
	-- v_party_success:='false';
	--  RAISE EXCEPTION 'Party ID --> %', v_application
    --  USING HINT = 'Please check party data';
	 end ;
	 
 END LOOP;
 end if;
	return v_partyid;
END;
$_$;


