    LANGUAGE plpgsql
    AS $_$

DECLARE
  v_party_arry kaverimrg.partyinfo_input[];
   v_partyid bigint;
   v_cnt integer;
   v_partyid_guid varchar(50);
   v_party_success boolean default 'true';
   v_party_exists boolean default 'false';
   v_isdelete boolean ;
   v_application varchar(100);
   v_propertyid int;
   v_partytypeid int;
  v_partyid_org int;
BEGIN

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
   
 FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partydetails)) 
					loop
		v_cnt:= 0;
		v_partyid:=null;
		v_partyid_guid :=null;
		v_party_exists := 'false';

	begin					
	select a._partyid,(a._partyid ~ '^[0-9]+$'),a._verified,a._applicationnumber into 
		v_partyid_guid,v_party_exists,v_isdelete,v_application from unnest(v_party_arry) a ;
		
	if (v_partyid_guid is not null) then 
	  Select count(*) into v_cnt from kaverimrg.partyinfo where partyid in 
					(case when v_party_exists ='true' then v_partyid_guid::bigint 
							   else 0 end);							   
							   
	
	if v_cnt = 0 then
  INSERT INTO kaverimrg.partyinfo(partyid,
srocode,DOCUMENTID, partytypeid, firstname, middlename, lastname, address, age, sex, 
isexecutor, ispresenter,  aliasname, relationship, relativename,  pan, 
