orgpoaauthsignfname = a._orgpoaauthsignfname, 
orgpoaauthsignmname = a._orgpoaauthsignmname, 
orgpoaauthsignlname = a._orgpoaauthsignlname,
housenumber=a._housenumber,
	pin=a._pin,
	idprooftypeid=a._idprooftypeid,
	isconsentwitness=a._isconsentwitness,
	isprivateattendance=a._isprivateattendance	,
	coveringLetterNo=a._coveringLetterNo,
	section88File=a._section88File,
	isduplicate=a._isduplicate,
	duplicatepartyid=a._duplicatepartyid,
	photopath=a._photopath,
	thumbpath=a._thumbpath,
	isendorseprinted=a._isendorseprinted,
	islateapperance =a._islateapperance,
	admissiondate =a._admissiondate
	from unnest(v_party_arry) a
  where partyid = v_partyid_guid::bigint
 RETURNING partyid::bigint into v_partyid;

select a._partyid  into
		v_partyid_org from unnest(v_party_arry) a ;

select partytypeid into v_partytypeid from kaverimrg.orgdatajslip where partyid =v_partyid_org::bigint and partytypeid=1;	
		
 if (v_partytypeid is not null)
 then 
 
 update kaverimrg.orgdatajslip set firstname=a._firstname , relativename=a._relativename,relationship=a._relationship
 from unnest(v_party_arry) a
 where partyid=v_partyid_org::bigint and partytypeid=1;
 
 end if;
 
 end if;
 end if;
 -- exception when others then
	-- v_party_success:='false';
