$_$;


ALTER FUNCTION kaverimrg.fn_insert_party_info_03112023(p_partydetails kaverimrg.partyinfo_input[], p_linkpartyid bigint) OWNER TO postgres;

--
-- Name: party_schedules_input; Type: TABLE; Schema: kaverimrg; Owner: postgres
--

CREATE TABLE kaverimrg.party_schedules_input (
    _partyscheduleid bigint,
    _partyid character varying(50),
    _scheduleid bigint,
    _propertyid bigint,
    _applicationnumber character varying(50),
    _isdelete boolean
);


ALTER TABLE kaverimrg.party_schedules_input OWNER TO postgres;

--
-- Name: fn_insert_party_info_all(kaverimrg.party_schedules_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_party_info_all(party_schedules kaverimrg.party_schedules_input[] DEFAULT NULL::kaverimrg.party_schedules_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$


DECLARE

 v_arr_partyschedule kaverimrg.party_schedules_input[];
   v_applicationnumber character varying;
   v_pid bigint[];
   v_partyid bigint;
   v_partyscheduled bigint ;
   v_partyschedulecnt bigint;
   v_partyscheduleid bigint;
   v_isdelete_partyschedule boolean  default 'false';
   v_countofparty bigint;
BEGIN

   if (party_schedules is not null and array_length(party_schedules,1)>0) then
             FOR v_arr_partyschedule IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(party_schedules))
                loop
                v_partyschedulecnt:= 0;
                v_isdelete_partyschedule := 'false';
                v_partyscheduleid:=null;
                begin
                
                select a._partyscheduleid,a._isdelete,a._partyid,a._scheduleid,a._applicationnumber into
                v_partyscheduleid,v_isdelete_partyschedule,v_partyid,v_partyscheduled,v_applicationnumber
                from unnest(v_arr_partyschedule) a ;
            
--                select b.partyid,b.scheduleid  into v_partyids,v_partyschedules  from kaverimrg.partyschedules b ;
                
                if(v_isdelete_partyschedule = 'false' and v_partyscheduleid is null ) then                     
                 
                   select count(partyid) into v_countofparty from kaverimrg.partyschedules p where p.applicationnumber=v_applicationnumber and p.scheduleid=v_partyscheduled
                    and p.partyid=v_partyid;
                    
                    if(v_countofparty=0) then
                    INSERT INTO kaverimrg.partyschedules(
                    partyid ,scheduleid,  propertyid,applicationnumber)
                    select v_partyid ,a._scheduleid,  a._propertyid,a._applicationnumber
                        from unnest(v_arr_partyschedule) a;
--                    ELSE
--                    
--                            delete from kaverimrg.partyschedules where applicationnumber=v_applicationnumber and partyid=v_partyid and scheduleid=v_partyscheduled;
--                            /*delete from kaverimrg.partyschedules where
--                         partyscheduleid  in  (select a._partyscheduleid
--                        from unnest(v_arr_partyschedule) a);*/
                    end if;
                    
                elsif (v_isdelete_partyschedule = 'true' and v_partyscheduleid is not null)
                then
                         select count(partyid) into v_countofparty from kaverimrg.partyschedules p where p.applicationnumber=v_applicationnumber and p.scheduleid=v_partyscheduled
                    and p.partyid=v_partyid;
                    
                    if(v_countofparty>0) then
                    /*delete from kaverimrg.partyschedules where
