                        delete from kaverimrg.partyschedules where applicationnumber=v_applicationnumber and partyid=v_partyid and scheduleid=v_partyscheduled
						and partyscheduleid=v_partyscheduleid;
						delete from kaverimrg.orgdatajslip where applicationnumber=v_applicationnumber and partyid=v_partyid and propertyid in 
						(select propertyid from kaverimrg.propertyschedules where scheduleid=v_partyscheduled) and partytypeid = 1;
                    else
                    INSERT INTO kaverimrg.partyschedules(
                    partyid ,scheduleid,  propertyid,applicationnumber)
                    select v_partyid ,a._scheduleid,  a._propertyid,a._applicationnumber
                        from unnest(v_arr_partyschedule) a;
                    end if;                    
                end if;            
            -- exception when others then
            -- RAISE EXCEPTION 'Partydata ID --> %', v_partyid
              --    USING HINT = 'Please check partyschedules data';
             end;
             end loop;
             
            end if;
        
