ALTER FUNCTION kaverimrg.fn_insert_party_info_all_newtemp(p_partydetails kaverimrg.partyinfo_input_newtemp[], p_party_schedules kaverimrg.party_schedules_input[]) OWNER TO postgres;

--
-- Name: fn_insert_party_info_bck150423(kaverimrg.partyinfo_input_150423[], bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_party_info_bck150423(p_partydetails kaverimrg.partyinfo_input_150423[] DEFAULT NULL::kaverimrg.partyinfo_input_150423[], p_linkpartyid bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_party_arry kaverimrg.partyinfo_input[];
   v_partyid bigint;
   v_cnt integer;
   v_partyid_guid varchar(50);
   v_party_success boolean default 'true';
   v_party_exists boolean default 'false';
   v_isdelete boolean ;
   v_application varchar(100);
BEGIN

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
   
 FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partydetails)) 
					loop
		v_cnt:= 0;
		v_partyid:=null;
		v_partyid_guid :=null;
		v_party_exists := 'false';

	begin					
	select a._partyid,(a._partyid ~ '^[0-9]+$'),a._verified,a._applicationnumber into 
		v_partyid_guid,v_party_exists,v_isdelete,v_application from unnest(v_party_arry) a ;
		
	if (v_partyid_guid is not null) then 
	  Select count(*) into v_cnt from kaverimrg.partyinfo where partyid in 
					(case when v_party_exists ='true' then v_partyid_guid::bigint 
							   else 0 end);							   
	if v_cnt = 0 then
  INSERT INTO kaverimrg.partyinfo(partyid,
srocode,DOCUMENTID, partytypeid, firstname, middlename, lastname, address, age, sex, 
isexecutor, ispresenter,  aliasname, relationship, relativename,  pan, 
	phonenumber, dateofdeath, partypoa, profession, restriction, restrictiondescription, restrictiontype, section88exemption, 
isaua, salutationid, isorganization, organizationid,applicationnumber,verified,districtcode,talukcode,
hoblicode,villagecode,
tanno,yearofincorp,orgpoaauthsignfname, orgpoaauthsignmname, orgpoaauthsignlname,linkpartyid,housenumber,pin,
		idprooftypeid,propertyid,availableextacre,availableextgunta,availableextfgunta,
	bincom,category,landcode,mainownerno,ownerno,totalextacre,totalextgunta,totalextfgunta,
	transactextacre,transactextgunta,transactextfgunta,isconsentwitness,isprivateattendance,
			coveringLetterNo,section88File,isduplicate,duplicatepartyid )
    select  nextval('kaverimrg.partyinfo_partyid_seq'),
	_srocode,0, _partytypeid, _firstname,_middlename,_lastname, coalesce(_address,' '),_age,_sex,_isexecutor,
	_ispresenter, _aliasname,_relationship,_relativename,_pan,_phonenumber,
	_dateofdeath,_partypoa,_profession,_restriction,_restrictiondescription,
	_restrictiontype,_section88exemption ,_isaua,_salutationid ,_isorganization ,_organizationid,_applicationnumber,
	_verified,_districtcode,_talukcode,_hoblicode,_villagecode,
	 _tanno,_yearofincorp,_orgpoaauthsignfname,_orgpoaauthsignmname,_orgpoaauthsignlname,
    coalesce(p_linkpartyid,(CASE WHEN _linkpartyid IS NOT NULL THEN _linkpartyid::BIGINT ELSE NULL END),NULL),_housenumber,_pin,_idprooftypeid,
	_propertyid,_availableextacre,_availableextgunta,_availableextfgunta,
	_bincom,_category,_landcode,_mainownerno,_ownerno,_totalextacre,_totalextgunta,_totalextfgunta,
	_transactextacre,_transactextgunta,_transactextfgunta ,_isconsentwitness,_isprivateattendance,
	_coveringLetterNo,_section88File,_isduplicate,_duplicatepartyid
	from unnest(v_party_arry)
    RETURNING partyid::bigint into v_partyid;
	 else
  update kaverimrg.partyinfo set
srocode = a._srocode,
partytypeid = a._partytypeid, 
firstname = a._firstname, 
middlename = a._middlename, 
lastname = a._lastname, 
address = coalesce(a._address,' '), 
age = a._age, 
sex = a._sex, 
isexecutor = a._isexecutor, 
ispresenter=a._ispresenter, 
aliasname=a._aliasname, 
relationship=a._relationship, 
relativename=a._relativename,
pan=a._pan, 
phonenumber=a._phonenumber, 
dateofdeath=a._dateofdeath, 
partypoa=a._partypoa, 
profession=a._profession, 
restriction=a._restriction, 
restrictiondescription=a._restrictiondescription, 
restrictiontype=a._restrictiontype, 
section88exemption=a._section88exemption, 
isaua=a._isaua,
salutationid=a._salutationid, 
isorganization=a._isorganization, 
organizationid=a._organizationid,
applicationnumber=a._applicationnumber,
verified=a._verified,
districtcode=a._districtcode,
talukcode=a._talukcode,
hoblicode=a._hoblicode,
villagecode=a._villagecode,
tanno = a._tanno,
yearofincorp = a._yearofincorp,
orgpoaauthsignfname = a._orgpoaauthsignfname, 
orgpoaauthsignmname = a._orgpoaauthsignmname, 
orgpoaauthsignlname = a._orgpoaauthsignlname,
housenumber=a._housenumber,
	pin=a._pin,
	idprooftypeid=a._idprooftypeid,
	isconsentwitness=a._isconsentwitness,
	isprivateattendance=a._isprivateattendance	,
	coveringLetterNo=a._coveringLetterNo,
	section88File=a._section88File,
	duplicatepartyid=a._duplicatepartyid,
	isduplicate=a._isduplicate
	from unnest(v_party_arry) a
  where partyid = v_partyid_guid::bigint
 RETURNING partyid::bigint into v_partyid;
 end if;
 end if;
 -- exception when others then
	-- v_party_success:='false';
	--  RAISE EXCEPTION 'Party ID --> %', v_application
    --  USING HINT = 'Please check party data';
	 end ;
	 
 END LOOP;
 end if;
	return v_partyid;
END;
$_$;


ALTER FUNCTION kaverimrg.fn_insert_party_info_bck150423(p_partydetails kaverimrg.partyinfo_input_150423[], p_linkpartyid bigint) OWNER TO postgres;

--
-- Name: fn_insert_party_info_court(bigint, kaverimrg.bannedparties_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_party_info_court(p_courtorderid bigint, p_partydetails kaverimrg.bannedparties_input[]) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_party_arry kaverimrg.bannedparties_INPUT[];
   v_txt text;
   v_partyid bigint;
   V_party_success boolean default 'true';
   v_cnt integer;
   v_isdelete boolean;
BEGIN

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then
 FOR v_party_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partydetails)) 
loop
			begin
			v_cnt:= 0;
			 Select count(*) into v_cnt 
			 from kaverimrg.bannedparties where courtpartyid in 
									(select a._partyid from unnest(v_party_arry) a) ;
		select a._isdelete into v_isdelete from unnest(v_party_arry) a ;
		if v_cnt = 0 then
			  INSERT INTO kaverimrg.bannedparties(srocode,orderid,salutation,firstname,
			middlename,lastname,age,house_building_name,address,
			villagecode,districtcode,statecode,pincode)
				select 
				a._srocode,p_courtorderid,a._salutation,a._firstname,
			a._middlename,a._lastname,a._age,a._house_building_name,a._address,
			a._villagecode,a._districtcode,a._statecode,a._pincode
				from unnest(v_party_arry) a;
		elsif(v_isdelete = 'true') then 
			update kaverimrg.bannedparties   set 
			isdelete = 	v_isdelete
				from unnest(v_party_arry) a
			  where (orderid,courtpartyid) in  (select p_courtorderid,a._partyid from unnest(v_party_arry) a);
		else
			  update kaverimrg.bannedparties   set 
			   srocode = COALESCE(a._srocode,srocode),
			  salutation = COALESCE(a._salutation,salutation),
			 firstname = COALESCE(a._firstname,firstname),
				middlename =	COALESCE(a._middlename,middlename),
				lastname = 	 COALESCE(a._lastname,lastname),
				age =	COALESCE(a._age ,age),
				house_building_name =	COALESCE(a._house_building_name,house_building_name),
				address =	COALESCE(a._address,address),
				villagecode =	COALESCE(a._villagecode,villagecode),
				districtcode = 	 COALESCE(a._districtcode,districtcode),
				statecode =	COALESCE(a._statecode ,statecode),
				pincode =	COALESCE(a._pincode,pincode)
				from unnest(v_party_arry) a
			  where (orderid,courtpartyid) in  (select p_courtorderid,a._partyid from unnest(v_party_arry) a);
 end if;
exception when others then
V_party_success:= 'false';
			    RAISE; --EXCEPTION 'Courtorder --> %', p_courtorderid
      				--USING HINT = 'Please check party data';
					end;
 END LOOP;
 end if;
	return V_party_success;
END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_party_info_court(p_courtorderid bigint, p_partydetails kaverimrg.bannedparties_input[]) OWNER TO postgres;

--
-- Name: fn_insert_partyinfo_personaldetails(character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_partyinfo_personaldetails(_applicationnumber character varying DEFAULT NULL::character varying, _id integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_firstname character varying;
v_middlename character varying;
v_lastname character varying;
v_saluation int;
v_cnt int;
--v_ispresenter bool;
v_address character varying;
v_applicationnumber character varying;
v_srocode bigint;
v_documentid bigint;
v_cnt2 int;
v_partyid bigint;
--v_partytypeid int;

begin 
	
	select count(*) into v_cnt from kaverimrg.persondetails p where personid =_id and applicationnumber=_applicationnumber;

	select count(*) into v_cnt2 from kaverimrg.partyinfo p where applicationnumber =_applicationnumber;

	select documentid into v_documentid from kaverimrg.documentmaster d where applicationnumber =_applicationnumber;

	if (v_cnt>0)
	then 
		select firstname,middlename ,lastname ,salutation,srocode into 
			v_firstname,v_middlename,v_lastname,v_saluation,v_srocode
			from kaverimrg.persondetails p where personid=_id and applicationnumber=_applicationnumber;
	
	if (v_documentid is null)
		then  
				insert into kaverimrg.documentmaster (srocode,bookid,regarticlecode ,applicationnumber)
				values (v_srocode,1,133,_applicationnumber)
				returning documentid into v_documentid;
	end if;


	if(v_cnt2=0)
	then		
		insert into kaverimrg.partyinfo (firstname,middlename,lastname,salutationid,ispresenter,partytypeid
			,srocode,documentid,address,isexecutor,applicationnumber)
		values (v_firstname,v_middlename,v_lastname,v_saluation,true ,1,v_srocode,v_documentid,' ',false,_applicationnumber)
		returning partyid into v_partyid;
	end if;

	end if;


--v_applicationnumber:=_applicationnumber; 
	
	
return v_partyid;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_partyinfo_personaldetails(_applicationnumber character varying, _id integer) OWNER TO postgres;

--
-- Name: fn_insert_property_details_court(bigint, kaverimrg.bannedproperties_input[], kaverimrg.bannedpropertynumbers_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_property_details_court(p_courtorderid bigint, p_courtproperties kaverimrg.bannedproperties_input[], p_courtpropertynumberdetails kaverimrg.bannedpropertynumbers_input[]) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
DECLARE 
   v_arr_courtproperties p_courtproperties%type;
   v_arr_propertynumberdetails kaverimrg.bannedpropertynumbers_INPUT[];
   v_propertyid bigint;
   v_propertynumberid bigint;
   v_propertyid_guid varchar(50);
   v_propertynumberpropertyid_guid varchar(50);
   v_cnt integer;
   v_cnt1 integer;
   v_property_success boolean default 'true';
   v_property_exists boolean default 'false';
   v_isdelete boolean ;
   v_isdelete_propertynumber boolean ;
begin

if(p_courtproperties is not null and array_length(p_courtproperties,1)>0 ) then
	FOR v_arr_courtproperties IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_courtproperties)) 
	loop
		v_cnt:= 0;
		v_propertyid:=null;
		v_propertyid_guid :=null;
		v_property_exists := 'false';
		begin
		
		select a._propertyid,(a._propertyid ~ '^[0-9]+$'),a._isdelete into 
		v_propertyid_guid, v_property_exists, v_isdelete from unnest(v_arr_courtproperties) a ;
		
		if(v_propertyid_guid is not null) then
			Select count(*) into v_cnt from kaverimrg.bannedproperties where --v_property_exists ='true' and
			courtpropertyid in (case when v_property_exists ='true' then v_propertyid_guid::bigint 
							   else -1 end) ;
				 if v_cnt = 0 then 
				 INSERT INTO kaverimrg.bannedproperties(
				 ORDERID,srocode,jurisdictionsrcode,
		villagecode,propertydescription,isagriculturalproperty,
		northboundary,southboundary,eastboundary,westboundary ,
		extentinformation,area,measurementunit)
			select p_courtorderid,a._srocode,a._jurisdictionsrcode,
		a._villagecode,a._propertydescription,a._isagriculturalproperty,
		a._northboundary,a._southboundary,a._eastboundary,a._westboundary ,
		a._extentinformation,a._area,a._measurementunit
				from unnest(v_arr_courtproperties) a	
				 returning COURTpropertyid::bigint into v_propertyid;
	elsif(v_isdelete = 'true') then
		update kaverimrg.bannedproperties set 
			isdelete = v_isdelete where (orderid,COURTpropertyid) in
			(select p_courtorderid,a._propertyid::bigint from unnest(v_arr_courtproperties) a);
			update kaverimrg.bannedpropertynumbers set 
			isdelete = v_isdelete where (orderid,propertyid) in
			(select p_courtorderid,a._propertyid::bigint from unnest(v_arr_courtproperties) a);
	else 
				update kaverimrg.bannedproperties set
				villagecode = COALESCE(a._villagecode,villagecode),
				propertydescription = COALESCE(a._propertydescription,propertydescription),
				isagriculturalproperty = COALESCE(a._isagriculturalproperty,isagriculturalproperty),
				northboundary =COALESCE( a._northboundary,northboundary),
				southboundary =COALESCE( a._southboundary,southboundary),
				eastboundary = COALESCE(a._eastboundary,eastboundary),
				westboundary = COALESCE(a._westboundary ,westboundary),
				extentinformation = COALESCE(a._extentinformation,extentinformation),
				area = COALESCE(a._area,area),
				measurementunit = COALESCE(a._measurementunit,measurementunit)
				from unnest(v_arr_courtproperties) a	
				 where (orderid,COURTpropertyid) in  
				 (select p_courtorderid,a._propertyid::bigint from unnest(v_arr_courtproperties) a)
			 RETURNING COURTpropertyid::bigint into v_propertyid;
			 end if;
			end if;
	
	 exception when others then
	 v_property_success:='false';
	 RAISE EXCEPTION 'Courtorderid ID --> %', p_courtorderid
     USING HINT = 'Please check property data';
	 end ;
	 
 		if(v_propertyid is not null and coalesce(v_isdelete,'false') = 'false') then
			--select a._propertynumbers into p_arr_propertynumberdetails 
			--from unnest(v_arr_courtproperties) a;
			
			FOR v_arr_propertynumberdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_courtpropertynumberdetails))
				loop
				v_cnt1:= 0;
				v_property_exists := 'false';
				v_propertynumberpropertyid_guid:=null;
				begin
				
				select a._propertyid,(a._propertyid ~ '^[0-9]+$'),a._isdelete,a._propertynumberid into v_propertynumberpropertyid_guid
				,v_property_exists,v_isdelete_propertynumber,v_propertynumberid 
				from unnest(v_arr_propertynumberdetails) a ;
				if(v_propertynumberpropertyid_guid = v_propertyid_guid) then 
					
				--Select count(*) into v_cnt1 from kaverimrg.bannedpropertynumbers a where (propertyid,currentpropertytypeid) in  
					--	(select v_propertyid,a._currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
				if (v_propertynumberid is null or v_propertynumberid = 0) then --and v_propertyid1 = v_propertyid then
						 INSERT INTO kaverimrg.bannedpropertynumbers(
					srocode,propertyid,orderid,currentpropertytypeid,
					currentnumber,oldnumber,
					survey_no,hissa_no)
					select a._srocode,v_propertyid,p_courtorderid,a._currentpropertytypeid,
						a._currentnumber,a._oldnumber,
						a._survey_no,a._hissa_no
						from unnest(v_arr_propertynumberdetails) a;
				elsif (v_isdelete_propertynumber = 'true') then
						update  kaverimrg.bannedpropertynumbers set
						isdelete = v_isdelete_propertynumber where
						 (propertyid,courtpropertynumberid) 
						 in  (select v_propertyid,a._propertynumberid 
						from unnest(v_arr_propertynumberdetails) a);
						
				else 
						update  kaverimrg.bannedpropertynumbers set
						currentnumber=coalesce(a._currentnumber,currentnumber),
						oldnumber = coalesce(a._oldnumber,oldnumber),
						survey_no = coalesce(a._survey_no,survey_no),
						hissa_no = coalesce(a._hissa_no,hissa_no)
						from unnest(v_arr_propertynumberdetails)	a
						 where (propertyid,courtpropertynumberid) 
						 in  (select v_propertyid,a._propertynumberid 
						from unnest(v_arr_propertynumberdetails) a);
				end if;
			end if;
			 exception when others then
			 v_property_success := 'false';
			 RAISE EXCEPTION 'Courtorderid ID --> %', p_courtorderid
      			USING HINT = 'Please check propertynumber data';
			 end;
			 end loop; 
 		end if;
 	end loop;
 end if;

 RETURN v_property_success;
 end;
$_$;


