CREATE FUNCTION kaverimrg.fn_insert_property_master(kaverimrg.property_input[]) RETURNS character varying[]
    LANGUAGE plpgsql
    AS $_$


DECLARE 
   cit_id text;
   property_arry $1%type;
   v_txt text;
   v_propertyid character varying[];
   v_cnt integer;
   var_r record;
  v_applicationnumber character varying;
--   v_pid bigint[];
begin
Select count(*) into v_cnt from kaverimrg.propertymaster pm where pm.propertyid in 
(select a.propertyid from unnest($1) a) ;

select a.applicationnumber into v_applicationnumber from unnest($1) a;

	 if v_cnt = 0 then

--select nextval('kaverimrg.propertymastersequence_seq')::bigint into v_propertyid ;
	 
INSERT INTO kaverimrg.propertymaster(
	 propertyid,
    documentid,
    villagecode,
    regsrocode,
    srocode,
    totalarea,
    unitid,
    northboundary,
    southboundary,
    eastboundary,
    westboundary,
    landmark,
    marketvalue,
    assessment,
    sdcalculationstring,
    stampduty,
    transferliabilities,
    consideration,
    additionalduty,
    cessduty,
    govtduty,
    isexempted,
    exemptiondescription,
    ismovableproperty,
    sdrefund,
    docmarketvalue,
    valid1,
    isimdemnified,
    restriction,
    restrictiontype,
    restrictiondescription,
    enumber,
    claimingblocknumber,
    retainingblocknumber,
    valuationreport,
    loanpurposeid,
    applicationnumber,
    verified,
    issroapproved,
    stamparticlecode,
    stampruleid,
    regarticlecode,
	propertytypeid,
	 noofscanpages,
	 denodescription,
	estampdescription,
	adjudescription,
	 surcharge)
select 
   nextval('kaverimrg.propertymastersequence_seq') ,
    b.documentid,
    b.villagecode,
   b.regsrocode,
    b.srocode,
    b.totalarea,
    b.unitid,
    b.northboundary,
    b.southboundary,
    b.eastboundary,
    b.westboundary,  
    b.landmark,
    b.marketvalue,
    b.assessment,
    b.sdcalculationstring,
    b.stampduty,
    b.transferliabilities,
    b.consideration,
    b.additionalduty,
    b.cessduty,
    b.govtduty,
    b.isexempted,
    b.exemptiondescription,
    b.ismovableproperty,
    b.sdrefund,
    b.docmarketvalue,
    b.valid1,
    b.isimdemnified,
    b.restriction,
    b.restrictiontype,
    b.restrictiondescription,
    b.enumber,
    b.claimingblocknumber,
    b.retainingblocknumber,
    b.valuationreport,
    b.loanpurposeid,
   	b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.stamparticlecode,
    b.stampruleid,
	b.regarticlecode,
	b.propertytypeid,
	b.noofscanpages,
	b.denodescription,
	b.estampdescription,
	b.adjudescription,
	b.surcharge
	from unnest($1) b;
	select propertyid into v_propertyid  from unnest($1) ;--::kaverimrg.property_input[] 	;
	else 
	update kaverimrg.propertymaster pm set
	 documentid = a.documentid,
    villagecode = a.villagecode,
   	regsrocode = a.regsrocode,
    srocode = a.srocode,
    totalarea = a.totalarea,
    unitid = a.unitid,
    northboundary = a.northboundary,
    southboundary = a.southboundary,
    eastboundary = a.eastboundary,
    westboundary = a.westboundary,
    landmark = a.landmark,
    marketvalue = a.marketvalue,
    assessment = a.assessment,
    sdcalculationstring = a.sdcalculationstring,
    stampduty = a.stampduty,
    transferliabilities = a.transferliabilities,
    consideration = a.consideration,
    additionalduty = a.additionalduty,
    cessduty = a.cessduty,
    govtduty = a.govtduty,
    isexempted = a.isexempted,
    exemptiondescription = a.exemptiondescription,
    ismovableproperty = a.ismovableproperty,
    sdrefund = a.sdrefund,
    docmarketvalue = a.docmarketvalue,
    valid1 = a.valid1,
    isimdemnified = a.isimdemnified,
    restriction = a.restriction,
    restrictiontype = a.restrictiontype,
    restrictiondescription = a.restrictiondescription,
    enumber = a.enumber,
    claimingblocknumber = a.claimingblocknumber,
    retainingblocknumber = a.retainingblocknumber,
    valuationreport = a.valuationreport,
    loanpurposeid = a.loanpurposeid,
    applicationnumber = a.applicationnumber,
    verified = a.verified,
    issroapproved = a.issroapproved,
    stamparticlecode = a.stamparticlecode,
    stampruleid = a.stampruleid,
	regarticlecode=a.regarticlecode,
	propertytypeid=a.propertytypeid,
	 noofscanpages=a.noofscanpages,
	 denodescription=a.denodescription,
	estampdescription=a.estampdescription,
	adjudescription=a.adjudescription,
	surcharge=a.surcharge,
	inserteddatetime=now()
	from unnest($1) a--::kaverimrg.property_input[] 	;
	where pm.propertyid = a.propertyid;
			select array_Agg(s) into v_propertyid  from 
		(select propertyid  from unnest($1) )s;
	end if;
	
--	and p.documentid in (select documentid from unnest($1))) s;
--	 v_pid := array_append(v_pid,v_propertyid);
-- end loop;
 RETURN v_propertyid;
 end;
$_$;


