		a.regsrocode,
		a.srocode,
		a.totalarea,
		a.unitid,
		a.northboundary,
		a.southboundary,
		a.eastboundary,
		a.westboundary,
		a.landmark,
		a.marketvalue,
		a.assessment,
		a.sdcalculationstring,
		a.stampduty,
		a.transferliabilities,
		a.consideration,
		a.additionalduty,
		a.cessduty,
		a.govtduty,
		a.isexempted,
		a.exemptiondescription,
		a.ismovableproperty,
		a.sdrefund,
		a.docmarketvalue,
