		isimdemnified = a.isimdemnified,
		restriction = a.restriction,
		restrictiontype = a.restrictiontype,
		restrictiondescription = a.restrictiondescription,
		enumber = a.enumber,
		claimingblocknumber = a.claimingblocknumber,
		retainingblocknumber = a.retainingblocknumber,
		valuationreport = a.valuationreport,
		loanpurposeid = a.loanpurposeid,
		applicationnumber = a.applicationnumber,
