    --propertyid=a._propertyid,
    pid=a.pid,
    xml=a.xml,
    srocode=a.srocode
	from unnest(v_arr_eaasti_eswatuxmllog)	a
                       where p2.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog ) a1)
                       returning a.propertyid::bigint into v_propertyid;
	end if;
	end loop;
	end if;
	end loop;
 end if;
 RETURN v_pid;
 end;
$_$;


ALTER FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_check_1(p_propertymaster kaverimrg.property_input_array[], p_mojanixmldetails kaverimrg.mojanixml_input[], p_bhoomixmllogdetails kaverimrg.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaverimrg.eaasti_eswatuxmllog_array[]) OWNER TO postgres;

--
