 		end if;
 	v_pid := array_append(v_pid,v_schid);
	/* Mojani starts here */
	if(v_propertyid is not null and p_mojanixmldetails is not null and array_length(p_mojanixmldetails,1)>0) then
			
			FOR v_arr_mojanixmldetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_mojanixmldetails))
