ALTER FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_check_26042023(p_propertymaster kaverimrg.property_input_array[], p_mojanixmldetails kaverimrg.mojanixml_input[], p_bhoomixmllogdetails kaverimrg.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaverimrg.eaasti_eswatuxmllog_array[]) OWNER TO postgres;

