CREATE FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_check_backup_2(p_propertymaster kaverimrg.property_input_array[] DEFAULT NULL::kaverimrg.property_input_array[], p_mojanixmldetails kaverimrg.mojanixml_input[] DEFAULT NULL::kaverimrg.mojanixml_input[], p_bhoomixmllogdetails kaverimrg.bhoomixmllog_input[] DEFAULT NULL::kaverimrg.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaverimrg.eaasti_eswatuxmllog_array[] DEFAULT NULL::kaverimrg.eaasti_eswatuxmllog_array[]) RETURNS bigint[]
    LANGUAGE plpgsql PARALLEL SAFE
    AS $_$
DECLARE 
   v_schid bigint;
   cit_id text; 
   v_arr_propertymaster p_propertymaster%type;
   v_propertyid_for_chk bigint;
   
   p_arr_propertynumberdetails kaverimrg.propertynumberdetails_input[];
   v_arr_propertynumberdetails kaverimrg.propertynumberdetails_input[];
   v_arr_mojanixmldetails kaverimrg.mojanixml_input[];
   v_arr_bhoomixmllogdetails p_bhoomixmllogdetails%type;
