		       a.ackxmldetails,
		       a.acknumber,
		       a.sentxmldetails,
		       a.isfinalregistration
                       from unnest(v_arr_mojanixmldetails) a	
				 returning propertyid::bigint into v_schid;
                     /*else 
				update  kaverimrg.mojanixml set
                       -- inputsketchdetails=a._inputsketchdetails,
		       			receivedxmldetails=a._receivedxmldetails,
		       			receivedencxmldetails=a._receivedencxmldetails,
		       			verified=a._verified,
		       			isuploaded=a._isuploaded,
		       			uploaddatetime=a._uploaddatetime,
		       			ackxmldetails=a._ackxmldetails,
		       			acknumber=a._acknumber,
		       			sentxmldetails=a._sentxmldetails,
		       			isfinalregistration=a._isfinalregistration
						from unnest(v_arr_mojanixmldetails)	a
						 changed propertyid to inputsketchdetails on 23/09/2022 in order to avoid duplicate mojini sketch number entry */
                    /*where inputsketchdetails in (select a._inputsketchdetails from unnest(v_arr_mojanixmldetails ) a)
                       returning propertyid::bigint into v_schid;
                   end if;*/
				  end loop;
			end if;
			 select documentid,srocode into v_documentid,v_srocode
			 from kaverimrg.propertymaster where propertyid = v_propertyid;
			 if(v_propertyid is not null and p_bhoomixmllogdetails is not null and array_length(p_bhoomixmllogdetails,1)>0) then
			FOR v_arr_bhoomixmllogdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_bhoomixmllogdetails))
				loop
				v_cnt2:= 0;			 
                      Select count(*) into v_cnt2 from kaverimrg.bhoomixmllog a where
                      propertyid in (select a.propertyid from unnest(v_arr_bhoomixmllogdetails) a);
                  --if (v_cnt2 = 0) then
                   insert into kaverimrg.bhoomixmllog(
                      logid,
    		      propertyid,
    		      inputrtcowners,
    		      rtcowners,
    		      inputsurveynolist,
    		      surveynolist,
    		      srocode
                      )
                     select nextval('kaverimrg.bhoomi_logid_seq'),
                     v_propertyid,
                      bh.inputrtcowners,
    		      bh.rtcowners,
    		      bh.inputsurveynolist,
    		      bh.surveynolist,
    		      v_srocode
                      from unnest(v_arr_bhoomixmllogdetails) bh	
				 returning propertyid::bigint into v_schid;
                   /*  else
                     update  kaverimrg.bhoomixmllog set
                      inputrtcowners=a._inputrtcowners,
					   rtcowners=a._rtcowners,
                      inputsurveynolist=a._inputsurveynolist,
					  surveynolist=a._surveynolist
					  from unnest(v_arr_bhoomixmllogdetails) a
                       where propertyid in (select a._propertyid from unnest(v_arr_bhoomixmllogdetails ) a)
                       returning propertyid::bigint into v_schid;
                   end if;*/                                         
             end loop;
          end if;
	if(v_propertyid is not null and p_eaasti_eswatuxmllog is not null and array_length(p_eaasti_eswatuxmllog,1)>0) then
			FOR v_arr_eaasti_eswatuxmllog IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_eaasti_eswatuxmllog))
	loop
				v_cnt2:= 0;			 
                      Select count(*) into v_cnt2 from kaverimrg.eaasti_eswatuxmllog a where
                      a.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog) a1);
                  if (v_cnt2 = 0) then
	insert into kaverimrg.eaasti_eswatuxmllog
	(
	  logid,
    documentid,
    propertyid,
    pid,
    xml,
    srocode
	) 
	select
	 nextval('kaverimrg.logid_seq'),
    v_documentid,
	v_propertyid,
    --v_propertyid,
    a.pid,
    a.xml,
    v_srocode
	 from unnest(v_arr_eaasti_eswatuxmllog) a	
				 returning propertyid::bigint into v_propertyid;
	 else
     update  kaverimrg.eaasti_eswatuxmllog p2 set
	 documentid=a._documentid,
    --propertyid=a._propertyid,
    pid=a.pid,
    xml=a.xml,
    srocode=a.srocode
	from unnest(v_arr_eaasti_eswatuxmllog)	a
                       where p2.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog ) a1)
                       returning a.propertyid::bigint into v_propertyid;
	end if;
	end loop;
	end if;
	end loop;
 end if;
 RETURN v_pid;
 end;
$_$;


ALTER FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_check_backup_2(p_propertymaster kaverimrg.property_input_array[], p_mojanixmldetails kaverimrg.mojanixml_input[], p_bhoomixmllogdetails kaverimrg.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaverimrg.eaasti_eswatuxmllog_array[]) OWNER TO postgres;

--
-- Name: fn_insert_property_master_and_propertyno_details_check_bck_1406(kaverimrg.property_input_array[], kaverimrg.mojanixml_input[], kaverimrg.bhoomixmllog_input[], kaverimrg.eaasti_eswatuxmllog_array[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_check_bck_1406(p_propertymaster kaverimrg.property_input_array[] DEFAULT NULL::kaverimrg.property_input_array[], p_mojanixmldetails kaverimrg.mojanixml_input[] DEFAULT NULL::kaverimrg.mojanixml_input[], p_bhoomixmllogdetails kaverimrg.bhoomixmllog_input[] DEFAULT NULL::kaverimrg.bhoomixmllog_input[], p_eaasti_eswatuxmllog kaverimrg.eaasti_eswatuxmllog_array[] DEFAULT NULL::kaverimrg.eaasti_eswatuxmllog_array[]) RETURNS bigint[]
    LANGUAGE plpgsql PARALLEL SAFE
    AS $_$
DECLARE 
   v_schid bigint;
   cit_id text; 
   v_arr_propertymaster p_propertymaster%type;
   v_propertyid_for_chk bigint;
   
   p_arr_propertynumberdetails kaverimrg.propertynumberdetails_input[];
   v_arr_propertynumberdetails kaverimrg.propertynumberdetails_input[];
   v_arr_mojanixmldetails kaverimrg.mojanixml_input[];
   v_arr_bhoomixmllogdetails p_bhoomixmllogdetails%type;
   v_arr_eaasti_eswatuxmllog kaverimrg.eaasti_eswatuxmllog_array[];
   
   --property_arry $1%type;
   v_txt text;
   v_propertyid bigint;
   v_cnt integer;
   v_cnt1 integer;
   v_cnt2 integer;
   var_r record;
   v_pid bigint[];
   v_propertytypeid integer;
   v_srocode integer;
   v_documentid integer;
  -- v_propertyid_for_chk bigint;
   v_currentnumber text;
   v_cnt_currno integer;
   v_cnt3 integer;
   v_registercount integer;
begin
/*Select count(*) into v_cnt from kaverimrg.propertymaster where propertyid in 
(select a._propertyid from unnest($1) a) ;*/

if(p_propertymaster is not null and array_length(p_propertymaster,1)>0 ) then
	FOR v_arr_propertymaster IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_propertymaster)) 
	loop
		v_cnt:= 0;
		v_propertyid:=null;
    /* ============================================*/	
   /* first we will check whether this data has mojani data associated with it
   if Yes then we will check whether the sketch number exist */
   select count(*) into v_registercount from kaverimrg.documentmaster where applicationnumber in (select a.applicationnumber from unnest(v_arr_propertymaster) a);
   
   	
   if(p_mojanixmldetails is not null and array_length(p_mojanixmldetails,1)>0) then
			
			FOR v_arr_mojanixmldetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_mojanixmldetails))
				loop
				v_cnt3:= 0;			 
                      Select count(*) into v_cnt3 from kaverimrg.mojanixml a where
                      inputsketchdetails in (select a.inputsketchdetails 
											 from unnest(v_arr_mojanixmldetails) a);
                      if (v_cnt3 > 0 and v_registercount > 0) then
					  return '{1003}';
					  end if;
				 end loop;
	else 
   /* we are searching for existing properties against the submitted applicationnumbers */
				
				/*
	for v_propertyid_for_chk in	(select a3.propertyid from kaverimrg.propertymaster a3 where (applicationnumber,villagecode) 
		in(select a.applicationnumber,a.villagecode from unnest(v_arr_propertymaster) a)) 
		loop  
	-- for these properties we will find if the current number provided in propertynumber details
	-- match the current number submitted 
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
				
				
	select count(*) into v_cnt_currno from kaverimrg.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	end if;
*/
	    /* ============================================*/	
	
	
	

-- execture for agriculture propertytypeid = 17
for v_propertyid_for_chk in	(select a3.propertyid from kaverimrg.propertymaster a3 where (applicationnumber,villagecode, propertytypeid) 
		in(select a.applicationnumber,a.villagecode, a.propertytypeid from unnest(v_arr_propertymaster) a    ) and a3.propertytypeid = 17) 
  loop
	/* for these properties we will find if the current number provided in propertynumber details
	match the current number submitted */
	
	
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
			
	select count(*) into v_cnt_currno from kaverimrg.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	

-- execture for non-agriculture propertytypeid = 28
for v_propertyid_for_chk in	(select a3.propertyid from kaverimrg.propertymaster a3 where (applicationnumber,villagecode, propertytypeid) 
		in(select a.applicationnumber,a.villagecode, a.propertytypeid from unnest(v_arr_propertymaster) a ) and a3.propertytypeid = 28) 
  loop
	/* for these properties we will find if the current number provided in propertynumber details
	match the current number submitted */
		
	select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop		
			
	select count(*) into v_cnt_currno from kaverimrg.propertynumberdetails where 
	propertyid = v_propertyid_for_chk and (currentnumber,currentpropertytypeid) 
	in (select a.currentnumber,a.currentpropertytypeid 
		from unnest(v_arr_propertynumberdetails) a  where a.currentpropertytypeid in (60, 65));
	

	if v_cnt_currno > 0 then
	return '{1003}';
	end if;
	end loop;
	end loop;
	
end if;	
	
	
	/* following section is the original query that inserts or updates property details */
	Select count(*) into v_cnt from kaverimrg.propertymaster where propertyid in 
	(select a.propertyid from unnest(v_arr_propertymaster) a) ;
		 if v_cnt = 0 then
		 INSERT INTO kaverimrg.propertymaster(
		 propertyid,
		documentid,
		villagecode,
		regsrocode,
		srocode,
		totalarea,
		unitid,
		northboundary,
		southboundary,
		eastboundary,
		westboundary,
		landmark,
		marketvalue,
		assessment,
		sdcalculationstring,
		stampduty,
		transferliabilities,
		consideration,
		additionalduty,
		cessduty,
		govtduty,
		isexempted,
		exemptiondescription,
		ismovableproperty,
		sdrefund,
		docmarketvalue,
		valid1,
		isimdemnified,
		restriction,
		restrictiontype,
		restrictiondescription,
		enumber,
		claimingblocknumber,
		retainingblocknumber,
		valuationreport,
		loanpurposeid,
		applicationnumber,
		verified,
		issroapproved,
		stamparticlecode,
		stampruleid,
		regarticlecode,
		propertytypeid,
		noofscanpages,
		movablepropertydesc,
		roadcode,
		ownedarea,
		wardid,   -- To Save the ward number with respect to the wardid in BBMP Screen
	    isbefore2004,
		zoneId,
		subpropertytypeid
		--,pidno
		 )
	select 
		nextval('kaverimrg.propertymastersequence_seq'),
		a.documentid,
		a.villagecode,
		a.regsrocode,
		a.srocode,
		a.totalarea,
		a.unitid,
		a.northboundary,
		a.southboundary,
		a.eastboundary,
		a.westboundary,
		a.landmark,
		a.marketvalue,
		a.assessment,
		a.sdcalculationstring,
		a.stampduty,
		a.transferliabilities,
		a.consideration,
		a.additionalduty,
		a.cessduty,
		a.govtduty,
		a.isexempted,
		a.exemptiondescription,
		a.ismovableproperty,
		a.sdrefund,
		a.docmarketvalue,
		a.valid1,
		a.isimdemnified,
		a.restriction,
		a.restrictiontype,
		a.restrictiondescription,
		a.enumber,
		a.claimingblocknumber,
		a.retainingblocknumber,
		a.valuationreport,
		a.loanpurposeid,
		a.applicationnumber,
		a.verified,
		a.issroapproved,
		a.stamparticlecode,
		a.stampruleid,
		a.regarticlecode,
		a.propertytypeid,
		a.noofscanpages,
		a.movablepropertydesc,
		a.roadcode,
		a.ownedarea,
		a.wardid,
		a.isbefore2004,
		a.zoneId,
		a.subpropertytypeid
		 --, a._pidno
		from unnest(v_arr_propertymaster) a	
		 returning propertyid::bigint into v_propertyid;
		else 
		update kaverimrg.propertymaster p set
		documentid = a.documentid,
		villagecode = a.villagecode,
		regsrocode = a.regsrocode,
		srocode = a.srocode,
		totalarea = a.totalarea,
		unitid = a.unitid,
		northboundary = a.northboundary,
		southboundary = a.southboundary,
		eastboundary = a.eastboundary,
		westboundary = a.westboundary,
		landmark = a.landmark,
		marketvalue = a.marketvalue,
		assessment = a.assessment,
		sdcalculationstring = a.sdcalculationstring,
		stampduty = a.stampduty,
		transferliabilities = a.transferliabilities,
		consideration = a.consideration,
		additionalduty = a.additionalduty,
		cessduty = a.cessduty,
		govtduty = a.govtduty,
		isexempted = a.isexempted,
		exemptiondescription = a.exemptiondescription,
		ismovableproperty = a.ismovableproperty,
		sdrefund = a.sdrefund,
		docmarketvalue = a.docmarketvalue,
		valid1 = a.valid1,
		isimdemnified = a.isimdemnified,
		restriction = a.restriction,
		restrictiontype = a.restrictiontype,
		restrictiondescription = a.restrictiondescription,
		enumber = a.enumber,
		claimingblocknumber = a.claimingblocknumber,
		retainingblocknumber = a.retainingblocknumber,
		valuationreport = a.valuationreport,
		loanpurposeid = a.loanpurposeid,
		applicationnumber = a.applicationnumber,
		verified = a.verified,
		issroapproved = a.issroapproved,
		stamparticlecode = a.stamparticlecode,
		stampruleid = a.stampruleid,
		regarticlecode=a.regarticlecode,
		propertytypeid=a.propertytypeid,
		 noofscanpages=a.noofscanpages,
		 movablepropertydesc=a.movablepropertydesc,
		 roadcode=a.roadcode,
		 ownedarea=a.ownedarea,
		 wardid=a.wardid,
		 isbefore2004=a.isbefore2004/*,
		 zoneId=a._zoneid,
		 subpropertytypeid=a._subpropertytypeid*/
		 --pidno=a._pidno
		from unnest(v_arr_propertymaster) a	
		 where p.propertyid in  (select a1.propertyid from unnest(v_arr_propertymaster) a1)
	 RETURNING a.propertyid::bigint into v_propertyid;
	 end if;
 		if(v_propertyid is not null) then
			select a.propertynumberdetails into p_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;
			FOR v_arr_propertynumberdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_arr_propertynumberdetails))
				loop
				v_cnt1:= 0;
				 select documentid,srocode,propertytypeid into v_documentid,v_srocode,v_propertytypeid
			 from kaverimrg.propertymaster where propertyid = v_propertyid;
				Select count(*) into v_cnt1 from kaverimrg.propertynumberdetails a  
				where (propertyid,currentpropertytypeid) in  
				(select a.propertyid,a.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a);
			/*Select count(*) into v_cnt from kaverimrg.propertynumberdetails where propertyid in 
			(select a._propertyid from unnest($1) a) ;*/
			 if (v_cnt1 = 0 ) then --and v_propertyid1 = v_propertyid then
				 INSERT INTO kaverimrg.propertynumberdetails(
				propertyid,
				srocode,
				currentpropertytypeid,
				currentnumber,
			   -- oldpropertytypeid,
			   -- oldnumber,
			   -- description,
				survey_no,
			   -- surnoc,
				hissa_no)
			select 
				 v_propertyid,
				v_srocode,
				a.currentpropertytypeid,
				a.currentnumber,
			   -- null,--_oldpropertytypeid,
			   -- null,--_oldnumber,
			   -- null,--_description,
				a.survey_no,
			   --  null,--_surnoc,
				a.hissa_no
				from unnest(v_arr_propertynumberdetails) a	
				 returning propertyid::bigint into v_schid;
				else 
				update  kaverimrg.propertynumberdetails p1 set
				-- propertyid = _propertyid,
				srocode=a.srocode,
				currentpropertytypeid=a.currentpropertytypeid,
				currentnumber=a.currentnumber,
			   -- oldpropertytypeid=null,--_oldpropertytypeid,
			   -- oldnumber=null,--_oldnumber,
			   -- description=null,--_description,
				survey_no=a.survey_no,
			  --  surnoc=null,--_surnoc,
				hissa_no=a.hissa_no
				from unnest(v_arr_propertynumberdetails)	a
				 where (p1.propertyid,p1.currentpropertytypeid) in  (select a1.propertyid,a1.currentpropertytypeid from unnest(v_arr_propertynumberdetails) a1)
			 RETURNING a.propertyid::bigint into v_schid;
			 end if;
			  -- v_pid := array_append(v_pid,v_schid);
			 end loop; 
 		end if;
 	v_pid := array_append(v_pid,v_schid);
	/* Mojani starts here */
	if(v_propertyid is not null and p_mojanixmldetails is not null and array_length(p_mojanixmldetails,1)>0) then
			
			FOR v_arr_mojanixmldetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_mojanixmldetails))
				loop
				v_cnt2:= 0;			 
				/* changed propertyid to inputsketchdetails on 23/09/2022 in order to avoid duplicate mojini sketch number entry 
                      Select count(*) into v_cnt2 from kaverimrg.mojanixml a where
                      inputsketchdetails in (select a._inputsketchdetails from unnest(v_arr_mojanixmldetails) a);
                      if (v_cnt2 = 0) then */
                      insert into kaverimrg.mojanixml
                     (
                       logid,
                       srocode,
		       propertyid,
		       inputsketchdetails,
		       receivedxmldetails,
		       receivedencxmldetails,
		       verified,
		       isuploaded,
		       uploaddatetime,
		       ackxmldetails,
		       acknumber,
		       sentxmldetails,
		       isfinalregistration
                     )
                     select 
                     nextval('kaverimrg.mojini_logid_seq'),
                       v_srocode,
		       v_propertyid,
		       a.inputsketchdetails,
		       a.receivedxmldetails,
		       a.receivedencxmldetails,
		       a.verified,
		       a.isuploaded,
		       a.uploaddatetime,
		       a.ackxmldetails,
		       a.acknumber,
		       a.sentxmldetails,
		       a.isfinalregistration
                       from unnest(v_arr_mojanixmldetails) a	
				 returning propertyid::bigint into v_schid;
                     /*else 
				update  kaverimrg.mojanixml set
                       -- inputsketchdetails=a._inputsketchdetails,
		       			receivedxmldetails=a._receivedxmldetails,
		       			receivedencxmldetails=a._receivedencxmldetails,
		       			verified=a._verified,
		       			isuploaded=a._isuploaded,
		       			uploaddatetime=a._uploaddatetime,
		       			ackxmldetails=a._ackxmldetails,
		       			acknumber=a._acknumber,
		       			sentxmldetails=a._sentxmldetails,
		       			isfinalregistration=a._isfinalregistration
						from unnest(v_arr_mojanixmldetails)	a
						 changed propertyid to inputsketchdetails on 23/09/2022 in order to avoid duplicate mojini sketch number entry */
                    /*where inputsketchdetails in (select a._inputsketchdetails from unnest(v_arr_mojanixmldetails ) a)
                       returning propertyid::bigint into v_schid;
                   end if;*/
				  end loop;
			end if;
			 select documentid,srocode into v_documentid,v_srocode
			 from kaverimrg.propertymaster where propertyid = v_propertyid;
			 if(v_propertyid is not null and p_bhoomixmllogdetails is not null and array_length(p_bhoomixmllogdetails,1)>0) then
			FOR v_arr_bhoomixmllogdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_bhoomixmllogdetails))
				loop
				v_cnt2:= 0;			 
                      Select count(*) into v_cnt2 from kaverimrg.bhoomixmllog a where
                      propertyid in (select a.propertyid from unnest(v_arr_bhoomixmllogdetails) a);
                  --if (v_cnt2 = 0) then
                   insert into kaverimrg.bhoomixmllog(
                      logid,
    		      propertyid,
    		      inputrtcowners,
    		      rtcowners,
    		      inputsurveynolist,
    		      surveynolist,
    		      srocode
                      )
                     select nextval('kaverimrg.bhoomi_logid_seq'),
                     v_propertyid,
                      bh.inputrtcowners,
    		      bh.rtcowners,
    		      bh.inputsurveynolist,
    		      bh.surveynolist,
    		      v_srocode
                      from unnest(v_arr_bhoomixmllogdetails) bh	
				 returning propertyid::bigint into v_schid;
                   /*  else
                     update  kaverimrg.bhoomixmllog set
                      inputrtcowners=a._inputrtcowners,
					   rtcowners=a._rtcowners,
                      inputsurveynolist=a._inputsurveynolist,
					  surveynolist=a._surveynolist
					  from unnest(v_arr_bhoomixmllogdetails) a
                       where propertyid in (select a._propertyid from unnest(v_arr_bhoomixmllogdetails ) a)
                       returning propertyid::bigint into v_schid;
                   end if;*/                                         
             end loop;
          end if;
	if(v_propertyid is not null and p_eaasti_eswatuxmllog is not null and array_length(p_eaasti_eswatuxmllog,1)>0) then
			FOR v_arr_eaasti_eswatuxmllog IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_eaasti_eswatuxmllog))
	loop
				v_cnt2:= 0;			 
                      Select count(*) into v_cnt2 from kaverimrg.eaasti_eswatuxmllog a where
                      a.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog) a1);
                  if (v_cnt2 = 0) then
	insert into kaverimrg.eaasti_eswatuxmllog
	(
	  logid,
    documentid,
    propertyid,
    pid,
    xml,
    srocode
	) 
	select
	 nextval('kaverimrg.logid_seq'),
    v_documentid,
	v_propertyid,
    --v_propertyid,
    a.pid,
    a.xml,
    v_srocode
	 from unnest(v_arr_eaasti_eswatuxmllog) a	
				 returning propertyid::bigint into v_propertyid;
	 else
     update  kaverimrg.eaasti_eswatuxmllog p2 set
	 documentid=a._documentid,
    --propertyid=a._propertyid,
    pid=a.pid,
    xml=a.xml,
    srocode=a.srocode
	from unnest(v_arr_eaasti_eswatuxmllog)	a
                       where p2.propertyid in (select a1.propertyid from unnest(v_arr_eaasti_eswatuxmllog ) a1)
                       returning a.propertyid::bigint into v_propertyid;
	end if;
	end loop;
	end if;
	end loop;
 end if;
 RETURN v_pid;
 end;
$_$;


