--
-- Name: fn_insert_property_master_and_propertyno_details_rule17_bk(kaverimrg.property_rule_17_input_array[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_rule17_bk(p_propertymaster kaverimrg.property_rule_17_input_array[] DEFAULT NULL::kaverimrg.property_rule_17_input_array[]) RETURNS bigint
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
DECLARE 

   v_arr_propertymaster p_propertymaster%type;
   v_arr_propertynumberdetails kaverimrg.propertynumberdetails_input[];
   v_arr_propertyscheduledetails kaverimrg.obj_property_schedules[];
   
   v_propertyid bigint;
   v_cnt integer;
   v_cnt1 integer;
   v_cnt2 integer;
   v_pid bigint[];
   v_propertytypeid integer;
   v_srocode integer;
   v_documentid integer;
   v_currentnumber text;
   v_cnt_currno integer;
   v_cnt3 integer;
   v_registercount integer;
   v_arr_parties_rule_17_input kaverimrg.parties_rule_17_input[];
   v_property_rule_17_input_array kaverimrg.property_rule_17_input_array[];
 
 	v_p_no_id bigint[];
	v_p_sc_id bigint[];


  begin

	if(p_propertymaster is not null and array_length(p_propertymaster,1)>0 ) then
	 
	/* following section is the original query that inserts or updates property details */
	 
	FOR v_arr_propertymaster IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_propertymaster))

	loop
		Select count(*) into v_cnt from kaverimrg.propertymaster where propertyid in 
	(select a.propertyid from unnest(v_arr_propertymaster) a) ;
	if v_cnt = 0 then
		 INSERT INTO kaverimrg.propertymaster(
		 propertyid,
		documentid,
		villagecode,
		regsrocode,
		srocode,
		totalarea,
		unitid,
		northboundary,
		southboundary,
		eastboundary,
		westboundary,
		landmark,
		marketvalue,
		assessment,
		sdcalculationstring,
		stampduty,
		transferliabilities,
		consideration,
		additionalduty,
		cessduty,
		govtduty,
		isexempted,
		exemptiondescription,
		ismovableproperty,
		sdrefund,
		docmarketvalue,
		valid1,
		isimdemnified,
		restriction,
		restrictiontype,
		restrictiondescription,
		enumber,
		claimingblocknumber,
		retainingblocknumber,
		valuationreport,
		loanpurposeid,
		applicationnumber,
		verified,
		issroapproved,
		stamparticlecode,
		stampruleid,
		regarticlecode,
		propertytypeid,
		noofscanpages,
		movablepropertydesc,
		roadcode,
		ownedarea,
		wardid,   -- To Save the ward number with respect to the wardid in BBMP Screen
	    isbefore2004,
		zoneId,
		subpropertytypeid
		--,pidno
		 )
	select 
		nextval('kaverimrg.propertymastersequence_seq'),
		a.documentid,
		a.villagecode,
		a.regsrocode,
		a.srocode,
		a.totalarea,
		a.unitid,
		a.northboundary,
		a.southboundary,
		a.eastboundary,
		a.westboundary,
		a.landmark,
		a.marketvalue,
		a.assessment,
		a.sdcalculationstring,
		a.stampduty,
		a.transferliabilities,
		a.consideration,
		a.additionalduty,
		a.cessduty,
		a.govtduty,
		a.isexempted,
		a.exemptiondescription,
		a.ismovableproperty,
		a.sdrefund,
		a.docmarketvalue,
		a.valid1,
		a.isimdemnified,
		a.restriction,
		a.restrictiontype,
		a.restrictiondescription,
		a.enumber,
		a.claimingblocknumber,
		a.retainingblocknumber,
		a.valuationreport,
		a.loanpurposeid,
		a.applicationnumber,
		a.verified,
		a.issroapproved,
		a.stamparticlecode,
		a.stampruleid,
		a.regarticlecode,
		a.propertytypeid,
		a.noofscanpages,
		a.movablepropertydesc,
		a.roadcode,
		a.ownedarea,
		a.wardid,
		a.isbefore2004,
		a.zoneId,
		a.subpropertytypeid
		 --, a._pidno
		from unnest(v_arr_propertymaster) a	
		 returning propertyid::bigint into v_propertyid;
		else 
		update kaverimrg.propertymaster p set
		documentid = a.documentid,
		villagecode = a.villagecode,
		regsrocode = a.regsrocode,
		srocode = a.srocode,
		totalarea = a.totalarea,
		unitid = a.unitid,
		northboundary = a.northboundary,
		southboundary = a.southboundary,
		eastboundary = a.eastboundary,
		westboundary = a.westboundary,
		landmark = a.landmark,
		marketvalue = a.marketvalue,
		assessment = a.assessment,
		sdcalculationstring = a.sdcalculationstring,
		stampduty = a.stampduty,
		transferliabilities = a.transferliabilities,
		consideration = a.consideration,
		additionalduty = a.additionalduty,
		cessduty = a.cessduty,
		govtduty = a.govtduty,
		isexempted = a.isexempted,
		exemptiondescription = a.exemptiondescription,
		ismovableproperty = a.ismovableproperty,
		sdrefund = a.sdrefund,
		docmarketvalue = a.docmarketvalue,
		valid1 = a.valid1,
		isimdemnified = a.isimdemnified,
		restriction = a.restriction,
		restrictiontype = a.restrictiontype,
		restrictiondescription = a.restrictiondescription,
		enumber = a.enumber,
		claimingblocknumber = a.claimingblocknumber,
		retainingblocknumber = a.retainingblocknumber,
		valuationreport = a.valuationreport,
		loanpurposeid = a.loanpurposeid,
		applicationnumber = a.applicationnumber,
		verified = a.verified,
		issroapproved = a.issroapproved,
		stamparticlecode = a.stamparticlecode,
		stampruleid = a.stampruleid,
		regarticlecode=a.regarticlecode,
		propertytypeid=a.propertytypeid,
		 noofscanpages=a.noofscanpages,
		 movablepropertydesc=a.movablepropertydesc,
		 roadcode=a.roadcode,
		 ownedarea=a.ownedarea,
		 wardid=a.wardid,
		 isbefore2004=a.isbefore2004/*,
		 zoneId=a._zoneid,
		 subpropertytypeid=a._subpropertytypeid*/
		 --pidno=a._pidno
		from unnest(v_arr_propertymaster) a	
		 where p.propertyid in  (select a1.propertyid from unnest(v_arr_propertymaster) a1)
	 RETURNING a.propertyid::bigint into v_propertyid;
	 end if;
		 		if(v_propertyid is not null) then
		 		
				 select a.propertynumberdetails into v_arr_propertynumberdetails from unnest(v_arr_propertymaster) a;

		 		 SELECT kaverimrg.fn_insert_property_number_details(v_propertyid,v_arr_propertynumberdetails) into v_p_no_id;
 
		 			select a.objpropertyschedules into v_arr_propertyscheduledetails from unnest(v_arr_propertymaster) a;
		 	
		 			SELECT kaverimrg.fn_insert_property_rule_17_schedules(v_propertyid, v_arr_propertyscheduledetails) into v_p_sc_id;
		 	
			 end if;
		
	end loop;
 	
 end if;
 RETURN v_propertyid;
 end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_property_master_and_propertyno_details_rule17_bk(p_propertymaster kaverimrg.property_rule_17_input_array[]) OWNER TO postgres;

