    stamparticlecode,
    stampruleid,
    regarticlecode,
	propertytypeid,
	 noofscanpages,
	 denodescription,
	estampdescription,
	adjudescription,
	 surcharge)
select 
   nextval('kaverimrg.propertymastersequence_seq'),
    b.documentid,
    b.villagecode,
   b.regsrocode,
    b.srocode,
    b.totalarea,
    b.unitid,
    b.northboundary,
    b.southboundary,
    b.eastboundary,
    b.westboundary,  
    b.landmark,
    b.marketvalue,
    b.assessment,
    b.sdcalculationstring,
    b.stampduty,
    b.transferliabilities,
    b.consideration,
    b.additionalduty,
    b.cessduty,
    b.govtduty,
    b.isexempted,
    b.exemptiondescription,
    b.ismovableproperty,
    b.sdrefund,
    b.docmarketvalue,
    b.valid1,
    b.isimdemnified,
    b.restriction,
    b.restrictiontype,
    b.restrictiondescription,
    b.enumber,
    b.claimingblocknumber,
    b.retainingblocknumber,
    b.valuationreport,
    b.loanpurposeid,
   	b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.stamparticlecode,
    b.stampruleid,
	b.regarticlecode,
	b.propertytypeid,
	b.noofscanpages,
	b.denodescription,
	b.estampdescription,
	b.adjudescription,
	b.surcharge
	from unnest($1) b;--::kaverimrg.property_input[] 	;
	else 
	update kaverimrg.propertymaster pm set
	 documentid = a.documentid,
    villagecode = a.villagecode,
   	regsrocode = a.regsrocode,
    srocode = a.srocode,
    totalarea = a.totalarea,
