--

CREATE FUNCTION kaverimrg.fn_insert_propertyxml_temp(_guid text, _bhoomixml text, _mojinixml text, _eswathuxml text, _easthixml text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_referenceid bigint;

begin 

INSERT INTO kaverimrg.propertyxml_temp
(guid, bhoomixml, mojinixml, eswathuxml, easthixml)
VALUES(_guid,_bhoomixml,_mojinixml,_eswathuxml,_easthixml) returning referenceid into v_referenceid;

return v_referenceid;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_propertyxml_temp(_guid text, _bhoomixml text, _mojinixml text, _eswathuxml text, _easthixml text) OWNER TO postgres;

--
-- Name: fn_insert_propertyxml_temp(bigint, text, text, text, text, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_propertyxml_temp(_refid bigint, _guid text, _bhoomixml text, _mojinixml text, _eswathuxml text, _easthixml text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_referenceid bigint;
v_refid int;

begin 

select count(*) into v_refid from kaverimrg.propertyxml_temp where referenceid = _refid and guid = _guid;

if(v_refid = 0)then
	
INSERT INTO kaverimrg.propertyxml_temp
(guid, bhoomixml, mojinixml, eswathuxml, easthixml)
VALUES(_guid,_bhoomixml,_mojinixml,_eswathuxml,_easthixml) returning referenceid into v_referenceid;

else 
update kaverimrg.propertyxml_temp
set mojinixml = _mojinixml
where referenceid = _refid and guid = _guid
returning referenceid into v_referenceid;
end if;
return v_referenceid;
end;
$$;


