--
-- Name: fn_insert_protestentry(character varying, character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_protestentry(_applicationnumber character varying, _finalregistrationnumber character varying, _frm_applicationtypeid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE

	v_cnt bigint;
	v_protestorid integer;
	
begin


select count(*) into v_cnt from kaverimrg.firmprotestentry where applicationnumber = _applicationnumber;
					
	if v_cnt = 0 then
	
		insert into kaverimrg.firmprotestentry
						(protestorid,
						 applicationnumber,
						 finalregistrationnumber,
						 frm_applicationtypeid
						)
						values
						(nextval('kaverimrg.protestorid_seq'),
						_applicationnumber,
						_finalregistrationnumber,
						_frm_applicationtypeid)
						returning protestorid into v_protestorid;
						
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FP102' 
       where applicationnumber=_applicationnumber;	
	   
	   
	   else
update kaverimrg.firmprotestentry p1 set 
	finalregistrationnumber=_finalregistrationnumber,
    frm_applicationtypeid=_frm_applicationtypeid
	where applicationnumber=_applicationnumber
				returning protestorid into v_protestorid;		
				  
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FP102' 
    where applicationnumber=_applicationnumber;	   
	   
end if;

return v_protestorid;
end;
	
$$;


ALTER FUNCTION kaverimrg.fn_insert_protestentry(_applicationnumber character varying, _finalregistrationnumber character varying, _frm_applicationtypeid integer) OWNER TO postgres;

--
-- Name: fn_insert_referencemaster_registered_document_chk_backup_010620(bigint, integer, integer, character varying, character varying, integer, character varying, integer, character varying, integer, timestamp without time zone, character varying, integer, integer, boolean, integer, integer, integer, character varying, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_referencemaster_registered_document_chk_backup_010620(_srocode bigint, _trid integer, _throughid integer, _referencetextnew character varying, _referencetextold character varying, _bookidnew integer, _yearnew character varying, _bookidold integer, _yearold character varying, _courtordernumber integer, _courtorderdate timestamp without time zone, _nameofcourt character varying, _newdocumentnumber integer, _olddocumentnumber integer, _isregisterinnewbifurcatedoffice boolean, _volumnnumber integer, _frompagenumber integer, _topagenumber integer, _uploadcourtorderpath character varying, _oldisregisterinnewbifurcatedoffice boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
 _referenceno text;
 l_now varchar(4);
v_cnt bigint;
_inserted_id text;
v_refid integer;
v_cnt1 integer;
v_cnt_old bigint default 0;
v_documentid bigint;
v_documentid_old bigint;
begin

select count(*), documentid into v_cnt, v_documentid from kaverimrg.documentmaster where srocode = _srocode and
documentnumber = _newdocumentnumber and bookid = _bookidnew and
case when cast(to_char(REGISTRATIONDATETIME,'MM') as bigint)>3 then cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(REGISTRATIONDATETIME  + interval '1 year','YY')
else cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(REGISTRATIONDATETIME,'YY') end=_yearnew
group by documentid;

/*if not found then 
return 1002;
end if;*/

select count(*), documentid into v_cnt_old, v_documentid_old from kaverimrg.documentmaster where srocode = _srocode and
documentnumber = _olddocumentnumber and bookid = _bookidold  and
case when cast(to_char(REGISTRATIONDATETIME,'MM') as bigint)>3 then cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint) ||'-'|| to_char(REGISTRATIONDATETIME  + interval '1 year','YY')
else cast(to_char(REGISTRATIONDATETIME,'YYYY')as bigint)-1 ||'-'|| to_char(REGISTRATIONDATETIME,'YY') end=_yearold
group by documentid;

if not found and split_part(_yearold,'-',1)::bigint>2003 then 
return 1001;
end if;

--if v_cnt >= 1 then
insert into kaverimrg.referencemaster
(
  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    volumnnumber,
    frompagenumber,
    topagenumber,
    uploadcourtorderpath,
	oldisregisterinnewbifurcatedoffice
)
values
(
    v_documentid,
    _srocode,
    _trid,
    _throughid,
    _referencetextnew,
    _bookidnew,
    _yearnew,
    _courtordernumber,
    _courtorderdate,
    _nameofcourt,
    _newdocumentnumber,
    _isregisterinnewbifurcatedoffice,
    _volumnnumber,
    _frompagenumber,
    _topagenumber,
    _uploadcourtorderpath,
	_oldisregisterinnewbifurcatedoffice
) RETURNING refid into v_refid;
--end if;

if v_cnt_old >= 1 then
insert into kaverimrg.referencemaster
(
  documentid,
  srocode,
  trid,
  throughid,
  referencetext,
  bookid,
  year,
   courtordernumber,
    courtorderdate,
    nameofcourt,
    documentnumber,
    isregisterinnewbifurcatedoffice,
    volumnnumber,
    frompagenumber,
    topagenumber,
    uploadcourtorderpath,
	oldisregisterinnewbifurcatedoffice
)
values
(
    v_documentid_old,
    _srocode,
    _trid,
    _throughid,
    _referencetextold,
    _bookidold,
    _yearold,
    _courtordernumber,
    _courtorderdate,
    _nameofcourt,
    _olddocumentnumber,
    _isregisterinnewbifurcatedoffice,
    _volumnnumber,
    _frompagenumber,
    _topagenumber,
    _uploadcourtorderpath,
	_oldisregisterinnewbifurcatedoffice
) RETURNING refid into v_refid;
end if;
 RETURN 1000;
end
$$;


