--
-- Name: fn_insert_sakala_gscno(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_sakala_gscno(_applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt integer;
v_gscno text;
begin
v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaverimrg.gsc_no_seq'),'fm00000000');
--select 'IG000'||to_char(current_date,'YY')||to_char(nextval('kaverimrg.gsc_no_seq'),'fm00000000')
if substring(_applicationnumber,1,3) = 'ECC' then
	update kaverimrg.ec_applicationdetails set gscno = v_gscno
		where applicationnumber=_applicationnumber;
else if substring(_applicationnumber,1,3) = 'CCA' then
	update kaverimrg.cc_applicationdetails set gscno = v_gscno
		where applicationnumber=_applicationnumber;
	
else
	update kaverimrg.documentmaster set gscno = v_gscno
		where applicationnumber=_applicationnumber;

end if;
end if;
return v_gscno;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_sakala_gscno(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_insert_sakala_gscno_test(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_sakala_gscno_test(_applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt integer;
v_gscno text;
v_check character varying;
--v_check1 character varying;
--v_check2 character varying;
begin
	
	select gscno into v_check from kaverimrg.documentmaster where applicationnumber = _applicationnumber
	union 
	select gscno from kaverimrg.ec_applicationdetails where applicationnumber = _applicationnumber
	union
	select gscno from kaverimrg.cc_applicationdetails where applicationnumber = _applicationnumber;

if v_check is not null then

	select v_check into v_gscno;

else

v_gscno='IG000'||to_char(current_date,'YY')||to_char(nextval('kaverimrg.gsc_no_seq'),'fm00000000');
--select 'IG000'||to_char(current_date,'YY')||to_char(nextval('kaverimrg.gsc_no_seq'),'fm00000000')
if substring(_applicationnumber,1,3) = 'ECC' then
	update kaverimrg.ec_applicationdetails set gscno = v_gscno
		where applicationnumber=_applicationnumber;
else if substring(_applicationnumber,1,3) = 'CCA' then
	update kaverimrg.cc_applicationdetails set gscno = v_gscno
		where applicationnumber=_applicationnumber;
	
else
	update kaverimrg.documentmaster set gscno = v_gscno
		where applicationnumber=_applicationnumber;

end if;
end if;
end if;
return v_gscno;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_sakala_gscno_test(_applicationnumber character varying) OWNER TO postgres;

