--

CREATE FUNCTION kaverimrg.fn_insert_scannedfileuploaddetails(_documentid bigint, _srocode integer, _scannedfilename character varying, _uploadpath character varying, _uploaddatetime timestamp without time zone, _rootdirectory character varying, _documenttypeid integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
v_docid bigint;
v_count integer;
begin
select count(*) into v_count from kaverimrg.scannedfileuploaddetails where documentid = _documentid;
if v_count = 0 then
insert into kaverimrg.scannedfileuploaddetails (
     documentid,
	srocode,
    scannedfilename,
    uploadpath,
    uploaddatetime,
    rootdirectory,
    documenttypeid
) values
(
nextval('kaverimrg.scannedfileuploaddetails_seq'),
  _srocode,
    _scannedfilename,
    _uploadpath,
    _uploaddatetime,
    _rootdirectory,
    _documenttypeid
) returning documentid::bigint into v_docid;
else
update kaverimrg.scannedfileuploaddetails set 
	 srocode=_srocode,
    scannedfilename=_scannedfilename,
    uploadpath=_uploadpath,
    uploaddatetime=_uploaddatetime,
    rootdirectory=_rootdirectory,
    documenttypeid=_documenttypeid
	where documentid = _documentid returning documentid::bigint into v_docid;
	end if;
return v_docid;
end;
$$;


