--
-- Name: fn_insert_signed_file_upload_details(text, character varying, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_signed_file_upload_details(_fileid text, _applicationnumber character varying, _filepath text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
v_fileid text;
v_cnt integer;
begin
	select count(*) into v_cnt from kaverimrg.signed_file_upload_details where applicationnumber =_applicationnumber;
	
	if (v_cnt)=0
	then 
	
	insert into kaverimrg.signed_file_upload_details (fileid,applicationnumber,filepath)
	values (_fileid,_applicationnumber,_filepath);
	
	v_fileid:=_fileid;

	else
	
	update kaverimrg.signed_file_upload_details 
	set filepath=_filepath
	where applicationnumber=_applicationnumber;
	
	select fileid into v_fileid from kaverimrg.signed_file_upload_details where applicationnumber =_applicationnumber;
	
	end if;	

return v_fileid;
end
$$;


