(nextval('kaverimrg.slotmaster_sltid_seq'),_srocode,1,_sltdate,'15:00','16:00',5,5,true,true),
(nextval('kaverimrg.slotmaster_sltid_seq'),_srocode,1,_sltdate,'16:00','17:00',5,5,true,true);
--returning sltid into v_sltid;
else

insert into kaverimrg.slotmaster 
(
    sltid,
    srocode,
    serviceid,
    sltdate,
    sltstarttime,
    sltendtime,
    sltcapacity,
    sltavlcapacity,
    sltisactive,
    isexpress) values
(nextval('kaverimrg.slotmaster_sltid_seq'),_srocode,1,_sltdate,'09:00','10:00',5,5,true,true),
