(nextval('kaverimrg.slotmaster_sltid_seq'),_srocode,1,_sltdate,'16:00','17:00',5,5,true,true);
end if;
--v_sltidp:=v_sltid;
--select array_to_json(array_agg(ss)) into v_sltid from (select sltid  from kaverimrg.slotmaster where srocode = _srocode and sltdate=_sltdate) ss;

return query
select s.sltid from kaverimrg.slotmaster s where srocode=_srocode and sltdate=_sltdate;

--return v_sltid;
end;
$$;


