--

CREATE FUNCTION kaverimrg.fn_insert_sms_transactions(_templateid bigint, _smsmobileto character varying DEFAULT NULL::character varying, _smsmessage text DEFAULT NULL::text, _initiatedby character varying DEFAULT NULL::character varying, _requestedon timestamp without time zone DEFAULT NULL::timestamp without time zone, _senton timestamp without time zone DEFAULT NULL::timestamp without time zone, _status character varying DEFAULT NULL::character varying, _isdepartment boolean DEFAULT NULL::boolean, _isotp boolean DEFAULT NULL::boolean, _applicationnumber character varying DEFAULT NULL::character varying, _lastupdatedby character varying DEFAULT NULL::character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare 
--_user text;
v_transaction_id bigint;
v_message text;
begin

	INSERT INTO kaverimrg.sms_transaction_details(
	templateid, smsmobileto, smsmessage, initiatedby, requestedon, senton, 
	status, isdepartment, isotp, applicationnumber, lastupdated, lastupdatedby)
	VALUES (_templateid, _smsmobileto,_smsmessage,_initiatedby,_requestedon,_senton,
	_status,_isdepartment,_isotp,_applicationnumber, CURRENT_TIMESTAMP at time zone 'Asia/Kolkata',_lastupdatedby) returning 'Message Request Sent to '||smsmobileto into v_message;
    return v_message;

end;
$$;


