--
-- Name: fn_insert_update_amendment_details_input(kaverimrg.insert_firm_details_amendmentinput[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_update_amendment_details_input(kaverimrg.insert_firm_details_amendmentinput[] DEFAULT NULL::kaverimrg.insert_firm_details_amendmentinput[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$


declare
v_cnt bigint;
v_amendmentid bigint;
v_registrationid bigint;
v_existingfirmnumber character varying;
v_applicationnumber character varying;	
begin

-- select finalregistrationnumber into v_finalregnumber from kaverimrg.firmmaster where applicationnumber in
-- (select a2._firmnumber from unnest($1) a2);
/*(amendmentid, amendmentcount, firmname, firmaddress,
amendmentdatetime, drcode, k1k2_flag, inserteddatetime,
amendhousebuildingname, amendstreetaddress, amendstatecode,
amenddistrictcode, amendtalukacode, amendhoblicode, amendcityvillagecode, 
amendpincode, firmsignedformpath, amendmentdeedtypeid, amendmentdeedpath,
addressproofid, addressproofpath, proofofauthorisationfortheagentid, 
proofofauthorisationfortheagentpath, supporting_document1_path, supporting_document2_path,
formpath, finalregistrationnumber, amendmentdocument_challan_number, amendmenttypeid,
firmapplicationtypeid, applicationnumber, firmdigsignpath, fees, isactive)*/
 	select count(*) into v_cnt from kaverimrg.firmamendment 
	where amendmentid in (select _amendmentid from unnest($1)) ;
 
		if v_cnt = 0 then
		
			insert into kaverimrg.firmamendment
			(amendmentid,
			firmname,
			amendhousebuildingname,
			amendstreetaddress,
			amendstatecode,
			amenddistrictcode,
			amendtalukacode,
			amendhoblicode,
			amendcityvillagecode,
			amendpincode,
			finalregistrationnumber,
			amendmenttypeid,
		    firmapplicationtypeid,
		    applicationnumber 
					  )
			select 
			nextval('kaverimrg.amendmentid_seq'),
			a._firmname,
			a._amendhousebuildingname,
			a._amendstreetaddress,
			a._amendstatecode,
			a._amenddistrictcode,
			a._amendtalukacode,
			a._amendhoblicode,
			a._amendcityvillagecode,
			a._amendpincode,
			a._finalregistrationnumber,
			a._amendmenttypeid,
			a._firmapplicationtypeid,
			a._applicationnumber
			
 			from unnest($1) a
			returning amendmentid into v_amendmentid;
			
	select applicationnumber into v_applicationnumber from kaverimrg.firmamendment 
	where applicationnumber in (select a._applicationnumber from unnest($1) a);
	
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FA123' 
    where applicationnumber =v_applicationnumber;	

	else
 			update kaverimrg.firmamendment p1 set 
			firmname=COALESCE(a._firmname,firmname) ,
			amendhousebuildingname=COALESCE(a._amendhousebuildingname,amendhousebuildingname),
			amendstreetaddress=COALESCE(a._amendstreetaddress,amendstreetaddress),
			amendstatecode=COALESCE(a._amendstatecode,amendstatecode),
			amenddistrictcode=COALESCE(a._amenddistrictcode,amenddistrictcode),
			amendtalukacode=COALESCE(a._amendtalukacode,amendtalukacode),
			amendhoblicode=COALESCE(a._amendhoblicode,amendhoblicode),
			amendcityvillagecode=COALESCE(a._amendcityvillagecode,amendcityvillagecode),
			amendpincode=COALESCE(a._amendpincode,amendpincode),
			finalregistrationnumber=a._finalregistrationnumber,
			amendmenttypeid=a._amendmenttypeid,
			firmapplicationtypeid=a._firmapplicationtypeid,
			applicationnumber=a._applicationnumber
	
			from unnest($1) a
			  where p1.amendmentid in  (select a._amendmentid from unnest($1) a)
				returning _amendmentid into v_amendmentid;
				
					select applicationnumber into v_applicationnumber from kaverimrg.firmamendment 
	where applicationnumber in (select a._applicationnumber from unnest($1) a);
	
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FA123' 
    where applicationnumber =v_applicationnumber;	
	
			   
 end if;
 
 return v_amendmentid;
 
end;
$_$;


ALTER FUNCTION kaverimrg.fn_insert_update_amendment_details_input(kaverimrg.insert_firm_details_amendmentinput[]) OWNER TO postgres;

