--

CREATE FUNCTION kaverimrg.fn_insert_update_applicantapplicationdetails_firm(f_firmmaster kaverimrg.firmmaster_input[] DEFAULT NULL::kaverimrg.firmmaster_input[], f_firmbranches kaverimrg.firmbranches_input[] DEFAULT NULL::kaverimrg.firmbranches_input[]) RETURNS text
    LANGUAGE plpgsql
    AS $$


DECLARE
	_applicationnumber text;
	_application text;
	v_application_arry f_firmmaster%type;
	v_branch_arry f_firmbranches%type;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
		l_reset_date varchar(8);
	v_cnt bigint;
v_branchid bigint;
v_registrationid bigint;
v_pid bigint[];
v_srocode integer;
	
begin

l_now := to_char(now(),'DDMMYYYY');

l_reset_date := to_char(now(),'DDMM');
if(f_firmmaster is not null and array_length(f_firmmaster,1)>0 ) then
	FOR v_application_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(f_firmmaster)) 
	loop

		select nomenclature into _nomenclature from kaverimrg.servicesmaster where serviceid in (select a._applicationtypeid from unnest(v_application_arry) a);

if (select a._applicationtypeid from unnest(v_application_arry) a) = 6 then
_servicestatus = 'FR101';
end if;

select lpad(nextval('kaverimrg.ApplicantApplicationdetails_applicationnumber_seq')::text,7,'0') into _inserted_id;

_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;

v_cnt:=0;	 
select count(*) into v_cnt from kaverimrg.firmmaster where registrationid in 
														(select a._registrationid from unnest(v_application_arry) a) ;
					
					--applicationnumber =_applicationnumber ;
						if v_cnt = 0 then
						
		select srocode into v_srocode from kaverimrg.villagemaster where villagecode in (select a._cityvillagecode from unnest(v_application_arry) a );				
						
	INSERT INTO kaverimrg.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus,
		srocode
    )
    select  
	a._citizenid,
	_applicationnumber, 
	a._applicationtypeid,
	now(),
	_servicestatus,
	v_srocode
	from unnest(v_application_arry) a
    RETURNING applicationnumber
	into _application;

INSERT INTO kaverimrg.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr,srocode)
	select _applicationnumber, _servicestatus, a._citizenid, 1, a._citizenid,v_srocode from unnest(v_application_arry) a;

						insert into kaverimrg.firmmaster
						(registrationid,
						applicationnumber,
						firmname,
						firmphone,
						nature,
						housebuildingname,
						streetaddress,
						statecode,
						districtcode,
						talukacode,
						hoblicode,
						cityvillagecode,
						pincode,
						dateofconstitutionofthefirm,
						underoneyearstampdutypaid,
					    underoneyearstampdutynotpaid,
					    morethanoneyearstampdutypaid,
					    morethanoneyearstampdutynotpaid, 
						hasbranches,
						drcode,
						durationoffirm,
						challanreceipt
						)
						select
						nextval('kaverimrg.registrationid_seq'),
						_applicationnumber,
						a._Firmname,
						a._firmphone,
						a._nature,
						a._housebuildingname,
						a._streetaddress,
						a._statecode,
						a._districtcode,
						a._talukacode,
						a._hoblicode,
						a._cityvillagecode,
						a._pincode,
						a._dateofconstitutionofthefirm,
						a._underoneyearstampdutypaid,
					    a._underoneyearstampdutynotpaid,
					    a._morethanoneyearstampdutypaid,
					    a._morethanoneyearstampdutynotpaid,
						a._hasbranches,
						a._drcode,
						a._durationoffirm,
						a._challanreceipt
						from unnest(v_application_arry) a
					 	returning registrationid into v_registrationid;
				
				update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR102' 
 where ad.applicationnumber =_applicationnumber;
 
					    else
						
						update kaverimrg.firmmaster set
						--applicationnumber=_applicationnumber,
						firmname=a._Firmname,firmphone=a._firmphone,nature=a._nature,
						housebuildingname=a._housebuildingname,streetaddress=a._streetaddress,statecode=a._statecode,districtcode=a._districtcode,
						talukacode=a._talukacode,hoblicode=a._hoblicode,cityvillagecode=a._cityvillagecode,pincode=a._pincode,
						dateofconstitutionofthefirm=a._dateofconstitutionofthefirm,underoneyearstampdutypaid=a._underoneyearstampdutypaid,
					    underoneyearstampdutynotpaid=a._underoneyearstampdutynotpaid,
					    morethanoneyearstampdutypaid=a._morethanoneyearstampdutypaid,
					    morethanoneyearstampdutynotpaid=a._morethanoneyearstampdutynotpaid,
						hasbranches=a._hasbranches,
						--firmaddress=a._housebuildingname||' '||a._streetaddress||' '||a._districtcode||' '||a._talukacode||' '||a._hoblicode||' '||a._cityvillagecode||' '||a._statecode||'-'||a._pincode,
						drcode=a._drcode,
						durationoffirm=a._durationoffirm,
						challanreceipt=a._challanreceipt
						from unnest(v_application_arry) a
						where registrationid in  (select a._registrationid from unnest(v_application_arry) a) 
								   returning registrationid into v_registrationid;
								   
								   select applicationnumber into _applicationnumber from kaverimrg.firmmaster where registrationid=v_registrationid;
					end if;	
					
									update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR102' 
                                    where ad.applicationnumber =_applicationnumber;
 
end LOOP;
end if;
--select null as durationoffirm from kaverimrg.firmmaster

-- select count(*) into v_cnt from kaverimrg.firmbranches where applicationtypeid in 
-- 									(select a._applicationtypeid from unnest(v_application_arry) a) ;

-- if v_cnt = 0 then*/
if (select a._hasbranches from unnest(v_application_arry) a) is true then
	if(f_firmbranches is not null and array_length(f_firmbranches,1)>0 ) then

 	FOR v_branch_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(f_firmbranches)) 	
 	loop
	v_cnt:=0; 
	v_branchid:=0;
 	select count(*) into v_cnt from kaverimrg.firmbranches where branchid in 
									(select b._branchid from unnest(v_branch_arry) b) ;
	if v_cnt = 0 then
	insert into kaverimrg.firmbranches
	(
	branchid,
	registrationid,
	branchhousebuildingname,
	branchstreetaddress,
	branchstatecode,
	branchdistrictcode,
	branchtalukacode,
	branchhoblicode,
	branchcityvillagecode,	
	branchpincode,
	applicationnumber,
	applicationtypeid)
	select
	nextval('kaverimrg.branchid_seq'),
	v_registrationid,
	b._branchhousebuildingname,
	b._branchstreetaddress,
	b._branchstatecode,
	b._branchdistrictcode,
	b._branchtalukacode,
	b._branchhoblicode,
	b._branchcityvillagecode,
	b._branchpincode,
	_applicationnumber,
	b._applicationtypeid
	from unnest(v_branch_arry) b
	returning branchid::bigint into v_branchid;
	
 update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR102' 
 where ad.applicationnumber =_applicationnumber;
	
	else

	update kaverimrg.firmbranches set
	registrationid=v_registrationid,
	branchhousebuildingname	=b._branchhousebuildingname,
	branchstreetaddress=b._branchstreetaddress,
	branchstatecode	=b._branchstatecode,
	branchdistrictcode=b._branchdistrictcode,
	branchtalukacode=b._branchtalukacode,
	branchhoblicode	=b._branchhoblicode,
	branchcityvillagecode=b._branchcityvillagecode,
	branchpincode=b._branchpincode,
	--applicationnumber=b._applicationnumber,
	applicationtypeid=b._applicationtypeid

	from unnest(v_branch_arry) b
	where branchid in 
			 (select b._branchid from unnest(v_branch_arry) b) 
			 RETURNING branchid::bigint into v_branchid;
			 
 	end if;
	
 update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR102' 
 where ad.applicationnumber =_applicationnumber;
 
 	v_pid := array_append(v_pid,v_branchid);
	END LOOP;
 end if;
end if;
return _applicationnumber;
end;
	
$$;


ALTER FUNCTION kaverimrg.fn_insert_update_applicantapplicationdetails_firm(f_firmmaster kaverimrg.firmmaster_input[], f_firmbranches kaverimrg.firmbranches_input[]) OWNER TO postgres;

