--
-- Name: fn_insert_update_applicantapplicationdetails_firmrecon(kaverimrg.firmreconstitution_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_update_applicantapplicationdetails_firmrecon(f_firmrecon kaverimrg.firmreconstitution_input[] DEFAULT NULL::kaverimrg.firmreconstitution_input[]) RETURNS TABLE(applicationnumber2 text, reconstititionid bigint, currentstatus text)
    LANGUAGE plpgsql
    AS $$

DECLARE
	v_applicationnumber text;
	_application text;
	v_application_arry f_firmrecon%type;
	_nomenclature character varying(3);
	l_now varchar(8);
	_inserted_id text;
	_servicestatus text; 
		l_reset_date varchar(8);
	v_cnt bigint;
v_reconstititionid bigint;
v_drcode bigint;
	
begin

l_now := to_char(now(),'DDMMYYYY');

l_reset_date := to_char(now(),'DDMM');
if(f_firmrecon is not null and array_length(f_firmrecon,1)>0 ) then
	FOR v_application_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(f_firmrecon)) 
	loop



v_cnt:=0;	 
select count(*) into v_cnt from kaverimrg.firmreconstitution where applicationnumber in 
														(select a._applicationnumber from unnest(v_application_arry) a) ;
					
	if v_cnt = 0 then
	select nomenclature into _nomenclature from kaverimrg.servicesmaster where serviceid in (select a._applicationtypeid from unnest(v_application_arry) a);

if (select a._applicationtypeid from unnest(v_application_arry) a) = 48 then
_servicestatus = 'FC101';
end if;

select lpad(nextval('kaverimrg.ApplicantApplicationdetails_applicationnumber_seq')::text,7,'0') into _inserted_id;

v_applicationnumber := _nomenclature ||'-'||l_now ||'-'||_inserted_id;
select drcode  into v_drcode  from kaverimrg.firmmaster f where f.finalregistrationnumber 
in
(select a._firmfinalregnumber from unnest(v_application_arry) a) ;
INSERT INTO kaverimrg.applicantapplicationdetails(
	citizenid,
    applicationnumber,
    applicationtypeid,
    applicationstartdate,
    currentstatus
    )
    select  
	a._citizenid,
	v_applicationnumber, 
	a._applicationtypeid,
	now(),
	_servicestatus
	from unnest(v_application_arry) a
    RETURNING applicationnumber
	into _application;

INSERT INTO kaverimrg.applicationaudit(
	applicationnumber, wrkflowstatusid, activityby, activityorder, crtusr)
	select v_applicationnumber, _servicestatus, a._citizenid, 1, a._citizenid from unnest(v_application_arry) a;

	insert into kaverimrg.firmreconstitution
						(reconstitutionid,
						 applicationnumber,
						firmapplicationtypeid,
						firmfinalregnumber,
						firmname,
						firmaddress,
						drcode,
						reconstitutionstartdate)
						select
						nextval('kaverimrg.reconstitutionid_seq'),
						v_applicationnumber,
						a._frm_applicationtypeid,
						a._firmfinalregnumber,
						a._firmname,
						a._firmaddress,
						v_drcode,
						now()
						from unnest(v_application_arry) a
					RETURNING  reconstitutionid	into v_reconstititionid;	
						
					end if;	
					end loop;
end if;

return query select _application,v_reconstititionid,_servicestatus;
end;
	
$$;


ALTER FUNCTION kaverimrg.fn_insert_update_applicantapplicationdetails_firmrecon(f_firmrecon kaverimrg.firmreconstitution_input[]) OWNER TO postgres;

