--
-- Name: fn_insert_update_branch_amendment_details_1(kaverimrg.insert_branch_details_amendmentinput[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_update_branch_amendment_details_1(p_branchdetails kaverimrg.insert_branch_details_amendmentinput[] DEFAULT NULL::kaverimrg.insert_branch_details_amendmentinput[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_cnt1 bigint;
v_amendmentbranchid bigint;
v_amendmentid bigint;
v_branch_arry p_branchdetails%type;
--v_amendment_array p_amendment%type;
--v_exiapplicationnumber varchar(50);
v_pid bigint[];
v_branchid integer;

begin 
	

if(p_branchdetails is not null and array_length(p_branchdetails,1)>0 ) then
FOR v_branch_arry  IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_branchdetails))
loop
  
	--select applicationnumber into v_exiapplicationnumber from kaverimrg.firmmaster f where finalregistrationnumber in (select a._finalregistrationnumber from unnest(v_branch_arry)a);
	
	--select branchid into v_branchid from kaverimrg.firmbranches f where finalregistrationnumber in (select a._finalregistrationnumber from unnest(v_branch_arry)a);
	
	select amendmentid into v_amendmentid from kaverimrg.firmamendment f where applicationnumber in (select a._applicationnumber from unnest(v_branch_arry)a);
	
v_cnt:= 0;
  	Select count(*) into v_cnt from kaverimrg.amendmentfirmbranches where amendmentbranchid in 
  	(select a._amendmentbranchid from unnest(v_branch_arry) a) ;
	
  	if v_cnt = 0 then
	insert into kaverimrg.amendmentfirmbranches
	(
		amendmentbranchid,	
	    amendmentid,
	    --branchid,
	    amendhousebuildingname,
	    amendstreetaddress,
	    amendstatecode,
	    amenddistrictcode,
	    amendtalukacode,
	    amendhoblicode,
	    amendcityvillagecode,	
	    amendpincode,
	    dateofcommencement_discontinuation,
	    isremoved,
		applicationnumber
		--finalregistrationnumber,
		--existingapplicationnumber
	)
	select
		nextval('kaverimrg.amendmentbranchid_seq'),
		v_amendmentid,
		--v_branchid,
		b._amendhousebuildingname,
		b._amendstreetaddress,
		b._amendstatecode,
		b._amenddistrictcode,
		b._amendtalukacode,
		b._amendhoblicode,
		b._amendcityvillagecode,
		b._amendpincode,
		b._dateofcommencement_discontinuation,
		false,
		b._applicationnumber
		--b._finalregistrationnumber,
		--v_exiapplicationnumber
	from unnest(v_branch_arry) b
	returning amendmentbranchid::bigint into v_amendmentbranchid;
	
	else

	update kaverimrg.amendmentfirmbranches set
		    amendmentid=v_amendmentid,
		    --branchid=v_branchid,
		    amendhousebuildingname=	b._amendhousebuildingname,
		    amendstreetaddress=b._amendstreetaddress,
		    amendstatecode=b._amendstatecode,
		    amenddistrictcode=b._amenddistrictcode,
		    amendtalukacode=b._amendtalukacode,
		    amendhoblicode=b._amendhoblicode,
		    amendcityvillagecode=b._amendcityvillagecode,
		    amendpincode=b._amendpincode,
		    dateofcommencement_discontinuation=b._dateofcommencement_discontinuation,
		    isremoved=false,
			applicationnumber=b._applicationnumber
			--finalregistrationnumber=b._finalregistrationnumber,
			--existingapplicationnumber = v_exiapplicationnumber
	from unnest(v_branch_arry) b
	where amendmentbranchid in (select b._amendmentbranchid from unnest(v_branch_arry) b) 
			 RETURNING amendmentbranchid::bigint into v_amendmentbranchid;
 	end if;
 v_pid :=array_append(v_pid,v_amendmentbranchid);
 end loop;
end if;
return v_pid;
end;
$$;


ALTER FUNCTION kaverimrg.fn_insert_update_branch_amendment_details_1(p_branchdetails kaverimrg.insert_branch_details_amendmentinput[]) OWNER TO postgres;

--
-- Name: cvcopeningclosing_input; Type: TABLE; Schema: kaverimrg; Owner: postgres
--

CREATE TABLE kaverimrg.cvcopeningclosing_input (
    _srocode integer,
    _districtcode integer,
    _opendate timestamp without time zone,
    _closedate timestamp without time zone,
    _extendedcloserdate timestamp without time zone,
    _remark character varying(100),
    _entrydoneby bigint,
    _entrydate timestamp without time zone,
    _isenabled boolean,
    _disabledby bigint,
    _disabledate timestamp without time zone,
    _isapplicabletoalldistrict boolean,
    _isapplicabletoallstate boolean,
    _lasteditedby bigint,
    _lastediteddate timestamp without time zone,
    _id bigint
);


ALTER TABLE kaverimrg.cvcopeningclosing_input OWNER TO postgres;

--
-- Name: fn_insert_update_cvcopeningclosing(kaverimrg.cvcopeningclosing_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_update_cvcopeningclosing(kaverimrg.cvcopeningclosing_input[] DEFAULT NULL::kaverimrg.cvcopeningclosing_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$

declare
v_cnt int;
v_id bigint;
v_check int;
begin 
	
	select count(*) into v_cnt from kaverimrg.cvcopeningclosing where id in(select a._id from unnest($1)a);
	
--	select count(*) into v_check from( 
--	select * from kaverimrg.cvcopeningclosing c 
--	join kaverimrg.sromaster s on s.srocode = c.srocode
--	where c.srocode = a._srocode 
--	and (opendate >=a._opendate or closedate >= a._closedate or extendedcloserdate >= a._extendedcloserdate) and
--	((opendate <= a._opendate or closedate <= a._closedate or extendedcloserdate <= a._extendedcloserdate)))b 
--	where b.srocode in(select a._srocode from unnest($1)a);


select count(*) into v_check from( 
	select * from kaverimrg.cvcopeningclosing c 
	join kaverimrg.sromaster s on s.srocode = c.srocode
	where c.srocode = (select a._srocode from unnest($1)a)
	and (opendate >=(select a._opendate from unnest($1)a) or closedate >= (select a._closedate from unnest($1)a) or extendedcloserdate >=(select a._extendedcloserdate from unnest($1)a)) and
	((opendate <=(select a._opendate from unnest($1)a) or closedate <=(select a._closedate from unnest($1)a) or extendedcloserdate <=(select a._extendedcloserdate from unnest($1)a))))b;
	

	if(v_check = 0)then

		if (v_cnt = 0) then
		insert into kaverimrg.cvcopeningclosing(
			id,
			srocode,
			districtcode,
			opendate,
			closedate,
			extendedcloserdate,
			remark,
			entrydoneby,
			entrydate,
			isenabled,
			disabledby,
			disabledate,
			isapplicabletoalldistrict,
			isapplicabletoallstate,
			lasteditedby,
			lastediteddate
			)
			select
			nextval('kaverimrg.cvcid_seq'),
			a._srocode,
			a._districtcode,
			a._opendate,
			a._closedate,
			a._extendedcloserdate,
			a._remark,
			a._entrydoneby,
			a._entrydate,
			a._isenabled,
			a._disabledby,
			a._disabledate,
			a._isapplicabletoalldistrict,
			a._isapplicabletoallstate,
			a._lasteditedby,
			current_timestamp
			from unnest($1) a
			returning id into v_id;
		
		else
		
		update kaverimrg.cvcopeningclosing set
			--srocode = a._srocode,
			--districtcode = a._districtcode,
			--opendate = a._opendate,
			--closedate = a._closedate,
			extendedcloserdate = a._extendedcloserdate,
			--remark = a._remark,
			--entrydoneby = a._entrydoneby,
			--entrydate = a._entrydate,
			isenabled = a._isenabled,
			disabledby = a._disabledby,
			disabledate = a._disabledate,
			--isapplicabletoalldistrict = a._isapplicabletoalldistrict,
			--isapplicabletoallstate = a._isapplicabletoallstate,
			lasteditedby = a._lasteditedby,
			lastediteddate = current_timestamp
			from unnest($1) a
			where id in (select a._id from unnest($1)a) returning id into v_id;
		end if;
	else
		select -1 into v_id;
	end if;
	
return v_id;
end
$_$;


ALTER FUNCTION kaverimrg.fn_insert_update_cvcopeningclosing(kaverimrg.cvcopeningclosing_input[]) OWNER TO postgres;

