--
-- Name: fn_insert_update_firmwitness(kaverimrg.firmwitness_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_update_firmwitness(f_witnessdetails kaverimrg.firmwitness_input[] DEFAULT NULL::kaverimrg.firmwitness_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$


DECLARE
DECLARE
	id_val bigint;
--v_firmwitness_array F_firmwitnessdetails%type;
   v_firmwitness_arry kaverimrg.firmwitness_input[];
   v_firmwitnessid bigint;
   v_pid bigint[];
  v_firmpersonidarray integer[];
 v_firmpersonid integer;
v_cnt integer;
v_cnt2 integer;
v_applicationnumber varchar;

begin

if(F_witnessdetails  is not null and array_length(F_witnessdetails,1)>0 ) then

FOR v_firmwitness_arry  IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(F_witnessdetails))

loop
v_cnt:= 0;
v_firmwitnessid:=0;

       Select count(*) into v_cnt from kaverimrg.frm_witnessdetails where firmwitnessid in 
           (select a._firmwitnessid from unnest(v_firmwitness_arry) a) ;

	if v_cnt = 0 then
		insert into kaverimrg.frm_witnessdetails
 		( firmwitnessid,
 		applicationnumber,
   		 salutation,
    	firstname,
   		 middlename,
   		 lastname,
    	 dateofbirth,
    	age,
    	genderid,
    	profession,
	    phonenumber,
	    mailaddress,
	    dateofjoin,
	    withousebuildname,
		witstreetname,
		witstatecode,
		witdistrictcode,
		wittalukacode,
		withoblicode,
		witcityvillagecode,
		witpincode,
	    status,
	    verified,
	    isapproved,
	    date,
 		witnessfathername
		)
    select  
	nextval('kaverimrg.firmwitnessid_seq'),
     a._applicationnumber,
	 a._salutationid,
	 a._firstname,
	 a._middlename,
	 a._lastname ,
	 a._dob,
	 a._age,
	 a._gender,
	 a._profession,
	 a._phoneno,
	 a._email,
	 a._dateofjoin,
	 a._withousebuildname,
	 a._witstreetname,
	 a._witstatecode,
	 a._witdistrictcode,
	 a._wittalukacode,
	 a._withoblicode,
	 a._witcityvillagecode,
	 a._witpincode,
	 a._status,
     a._verified,
     a._isapproved,
	 a._date,
	 a._witnessfathername
	 from unnest(v_firmwitness_arry) a
	 returning firmwitnessid into v_firmwitnessid;
 	Select a._firmpersonid into v_firmpersonidarray 
  from unnest(v_firmwitness_arry) a; 
  for v_firmpersonid in (select unnest(v_firmpersonidarray))
  loop
	  select count(*) into v_cnt2 from kaverimrg.frm_partnerwitnessrelations 
	   where firmpersonid=v_firmpersonid ;
	  
	  if v_cnt2=0 then
	  
		 insert into kaverimrg.frm_partnerwitnessrelations (partnerwitnessid,firmpersonid,firmwitnessid)
	  	 values (nextval('kaverimrg.partnerwitnessid_seq'),v_firmpersonid,v_firmwitnessid);
	  else 
	  
	    update kaverimrg.frm_partnerwitnessrelations set firmwitnessid=v_firmwitnessid where firmpersonid=v_firmpersonid;
	  end if;
  	
  end loop;
  

 			
	 
select a._applicationnumber into v_applicationnumber from unnest(v_firmwitness_arry) a;

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR104' 
 where ad.applicationnumber in (v_applicationnumber);
 
			 
    else 
      update kaverimrg.frm_witnessdetails f set 
      applicationnumber=a._applicationnumber,
    salutation=a._salutationid,
    firstname=a._firstname,
    middlename=a._middlename,
    lastname=a._lastname,
    dateofbirth=a._dob,
    age=a._age,
    genderid=a._gender,
    profession=a._profession,
    phonenumber=a._phoneno,
    mailaddress=a._email,
    dateofjoin=a._dateofjoin,
    withousebuildname=a._withousebuildname,
	witstreetname=a._witstreetname,
	witstatecode=a._witstatecode,
	witdistrictcode=a._witdistrictcode,
	wittalukacode=a._wittalukacode,
	withoblicode=a._withoblicode,
	witcityvillagecode=a._witcityvillagecode,
	witpincode=a._witpincode,
    status=a._status,
    verified=a._verified,
    isapproved=a._isapproved,
	date=a._date,
	witnessfathername=a._witnessfathername
	  	from unnest(v_firmwitness_arry) a 
		where f.firmwitnessid in (select a._firmwitnessid from unnest(v_firmwitness_arry) a) 
			 RETURNING a._firmwitnessid into v_firmwitnessid;
			
			
	Select a._firmpersonid into v_firmpersonidarray 
  	from unnest(v_firmwitness_arry) a; 
  	for v_firmpersonid in (select unnest(v_firmpersonidarray))
 	 loop
	  select count(*) into v_cnt2 from kaverimrg.frm_partnerwitnessrelations 
	   where firmpersonid=v_firmpersonid ;
	  
	  if v_cnt2=0 then
	  
		 insert into kaverimrg.frm_partnerwitnessrelations (partnerwitnessid,firmpersonid,firmwitnessid)
	  	 values (nextval('kaverimrg.partnerwitnessid_seq'),v_firmpersonid,v_firmwitnessid);
	  else 
	  
	    update kaverimrg.frm_partnerwitnessrelations set firmwitnessid=v_firmwitnessid where firmpersonid=v_firmpersonid;
	  end if;
  	
  end loop;
			
	
	end if;
	
	v_pid := array_append(v_pid,v_firmwitnessid);
	
	end loop;
	
	end if;
	
return v_pid;	
--Return v_firmwitnessid;

end;
$$;


