CREATE FUNCTION kaverimrg.fn_insert_update_rule17filing_remarks(_applicationnumber character varying, _propertydetailsremarks_fda character varying, _propertydetailsverified_fda boolean, _boundarydetailsremarks_fda character varying, _boundarydetailsverified_fda boolean, _scheduledesciptiondetailsremarks_fda character varying, _scheduledesciptiondetailsverified_fda boolean, _partydetailsremarks_fda character varying, _partydetailsverified_fda boolean, _verificationdatetime_fda timestamp without time zone, _propertydetailsremarks_sr character varying, _propertydetailsverified_sr boolean, _boundarydetailsremarks_sr character varying, _boundarydetailsverified_sr boolean, _scheduledesciptiondetailsremarks_sr character varying, _scheduledesciptiondetailsverified_sr boolean, _partydetailsremarks_sr character varying, _partydetailsverified_sr boolean, _canpreocesstopaymentremarks_sr character varying, _canpreocesstopaymentverified_sr boolean, _verificationdatetime_sr timestamp without time zone, _propertydetailsremarks_sda character varying, _propertydetailsverified_sda boolean, _boundarydetailsremarks_sda character varying, _boundarydetailsverified_sda boolean, _scheduledesciptiondetailsremarks_sda character varying, _scheduledesciptiondetailsverified_sda boolean, _partydetailsremarks_sda character varying, _partydetailsverified_sda boolean, _canpreocesstopaymentremarks_sda character varying, _canpreocesstopaymentverified_sda boolean, _verificationdatetime_sda timestamp without time zone, _inserteddatetime timestamp without time zone, _k1k2_flag integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare

v_cnt bigint;

v_verificationid integer default 0;

begin

select count(*) into v_cnt from kaverimrg.rule17filingremarks where applicationnumber = _applicationnumber ;


if v_cnt = 0 then

insert into kaverimrg.rule17filingremarks (verificationid, applicationnumber,
	propertydetailsremarks_fda,
	propertydetailsverified_fda,
	boundarydetailsremarks_fda,
	boundarydetailsverified_fda,
	scheduledesciptiondetailsremarks_fda,
	scheduledesciptiondetailsverified_fda,
	partydetailsremarks_fda,
	partydetailsverified_fda,
	verificationdatetime_fda,
	propertydetailsremarks_sr,
	propertydetailsverified_sr,
	boundarydetailsremarks_sr,
	boundarydetailsverified_sr,
	scheduledesciptiondetailsremarks_sr,
	scheduledesciptiondetailsverified_sr,
	partydetailsremarks_sr,
	partydetailsverified_sr,
	canpreocesstopaymentremarks_sr,
	canpreocesstopaymentverified_sr,
	verificationdatetime_sr,
	propertydetailsremarks_sda,
	propertydetailsverified_sda,
	boundarydetailsremarks_sda,
	boundarydetailsverified_sda,
	scheduledesciptiondetailsremarks_sda,
	scheduledesciptiondetailsverified_sda,
	partydetailsremarks_sda,
	partydetailsverified_sda,
	canpreocesstopaymentremarks_sda,
	canpreocesstopaymentverified_sda,
	verificationdatetime_sda,
	inserteddatetime,
	k1k2_flag )
values (nextval('kaverimrg.rule17filingremarks_verificationid_seq') ,
_applicationnumber,
_propertydetailsremarks_fda,
_propertydetailsverified_fda,
_boundarydetailsremarks_fda,
_boundarydetailsverified_fda,
_scheduledesciptiondetailsremarks_fda,
_scheduledesciptiondetailsverified_fda,
_partydetailsremarks_fda,
_partydetailsverified_fda,
_verificationdatetime_fda,
_propertydetailsremarks_sr,
_propertydetailsverified_sr,
_boundarydetailsremarks_sr,
_boundarydetailsverified_sr,
_scheduledesciptiondetailsremarks_sr,
_scheduledesciptiondetailsverified_sr,
_partydetailsremarks_sr,
_partydetailsverified_sr,
_canpreocesstopaymentremarks_sr,
_canpreocesstopaymentverified_sr,
_verificationdatetime_sr,
_propertydetailsremarks_sda,
_propertydetailsverified_sda,
_boundarydetailsremarks_sda,
_boundarydetailsverified_sda,
_scheduledesciptiondetailsremarks_sda,
_scheduledesciptiondetailsverified_sda,
_partydetailsremarks_sda,
_partydetailsverified_sda,
_canpreocesstopaymentremarks_sda,
_canpreocesstopaymentverified_sda,
_verificationdatetime_sda,
_inserteddatetime,
_k1k2_flag ) returning verificationid into v_verificationid ;

else

update
	kaverimrg.rule17filingremarks
set
	--propertydetailsremarks_fda = _propertydetailsremarks_fda,
	--propertydetailsverified_fda = _propertydetailsverified_fda,
	--boundarydetailsremarks_fda = _boundarydetailsremarks_fda,
	--boundarydetailsverified_fda = _boundarydetailsverified_fda,
	--scheduledesciptiondetailsremarks_fda = _scheduledesciptiondetailsremarks_fda,
	--scheduledesciptiondetailsverified_fda = _scheduledesciptiondetailsverified_fda,
