	boundarydetailsremarks_sda= _boundarydetailsremarks_sda,
	boundarydetailsverified_sda= _boundarydetailsverified_sda,
	scheduledesciptiondetailsremarks_sda= _scheduledesciptiondetailsremarks_sda,
	scheduledesciptiondetailsverified_sda= _scheduledesciptiondetailsverified_sda,
	partydetailsremarks_sda= _partydetailsremarks_sda,
	partydetailsverified_sda= _partydetailsverified_sda,
