	canpreocesstopaymentverified_sda= _canpreocesstopaymentverified_sda,
	verificationdatetime_sda= _verificationdatetime_sda
	
where
	applicationnumber = _applicationnumber
	
	returning verificationid into v_verificationid;

end if;

return v_verificationid;


end;

$$;


