--

CREATE TABLE kaverimrg.val_userapartmentamenitydetails_input (
    _useramenetiesdetailsid bigint,
    _apartmentamenityid smallint,
    _isselected boolean,
    _valuationid bigint,
    _verified boolean,
    _srocode integer,
    _regsrocode integer
);


ALTER TABLE kaverimrg.val_userapartmentamenitydetails_input OWNER TO postgres;

--
-- Name: fn_insert_userapartmentamenitydetails(kaverimrg.val_userapartmentamenitydetails_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_userapartmentamenitydetails(p_apt_rev kaverimrg.val_userapartmentamenitydetails_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
Declare
   v_apartment_arry kaverimrg.val_userapartmentamenitydetails_input[];
     v_cnt integer;
   v_valid bigint;
   v_pid bigint[];
begin

	if(p_apt_rev is not null and array_length(p_apt_rev,1)>0 ) then
		FOR v_apartment_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_apt_rev)) 
			loop
				v_cnt:= 0;
				Select count(*) into v_cnt from kaverimrg.val_userapartmentamenitydetails b 
				inner join kaverimrg.mas_val_apartmentsamenities c 
				on (b.apartmentamenityid = c.amenitiesid)
				where (apartmentamenityid,valuationid) in
						(select a._apartmentamenityid,a._valuationid from unnest(v_apartment_arry) a);
				 if v_cnt = 0 then
				 
                                 insert into kaverimrg.val_userapartmentamenitydetails
                                 (
    					apartmentamenityid,
    					isselected,
    					valuationid,
    					verified,
    					srocode,
    					regsrocode

                                )
                                   select --null,
                         _apartmentamenityid,
    					_isselected,
    					_valuationid,
    					_verified,
    					_srocode,
    					_regsrocode
					from unnest(v_apartment_arry)	
								 returning valuationid::bigint into v_valid;
					else
                        update kaverimrg.val_userapartmentamenitydetails set 
    					isselected=a._isselected,
    					verified=a._verified,
    					srocode=a._srocode,
    					regsrocode=a._regsrocode
                        from unnest(v_apartment_arry) a where (valuationid,apartmentamenityid) in 
					(select a._valuationid,a._apartmentamenityid  from unnest(v_apartment_arry ) a) 
					RETURNING valuationid::bigint into v_valid;
                                	end if;
				v_pid := array_append(v_pid,v_valid);
				end loop;
				end if;
				return v_pid;
   END;
$$;


ALTER FUNCTION kaverimrg.fn_insert_userapartmentamenitydetails(p_apt_rev kaverimrg.val_userapartmentamenitydetails_input[]) OWNER TO postgres;

