--
-- Name: fn_insert_val_agriculture(kaverimrg.agriculturedetails_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_val_agriculture(p_agriculturedetails kaverimrg.agriculturedetails_input[] DEFAULT NULL::kaverimrg.agriculturedetails_input[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare

v_arry_agriculture kaverimrg.agriculturedetails_input[];
v_cnt integer;
v_valid bigint;
begin
		if(p_agriculturedetails is not null and array_length(p_agriculturedetails,1)>0 ) then
				FOR v_arry_agriculture IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_agriculturedetails)) 
					loop
						v_cnt:= 0;
						Select count(*) into v_cnt from kaverimrg.val_agriculturedetails where agriculturedetailsid in 
						(select a._agriculturedetailsid from unnest(v_arry_agriculture) a) ;
						if v_cnt = 0 then
							insert into kaverimrg.val_agriculturedetails (
								agriculturedetailsid,agrilandtypeid,unitid,valuationid,
								verified,agrirateid,rate,srocode,regsrocode)
								select nextval('kaverimrg.val_agricultural_details_seq'),
								 a._agrilandtypeid,a._unitid,a._valuationid,--p_valuationid,
								 a._verified,a._agrirateid,a._rate,
								 a._srocode,a._regsrocode
								from unnest(v_arry_agriculture)	a
								 returning valuationid::bigint into v_valid;
						else
							update kaverimrg.val_agriculturedetails set
												agrilandtypeid = a._agrilandtypeid,
												unitid=a._unitid,
												verified = a._verified,
												agrirateid = a._agrirateid,
												rate=a._rate,
												srocode = a._srocode,
												regsrocode = a._regsrocode
												 from unnest(v_arry_agriculture) a where agriculturedetailsid in 
														 (select a._agriculturedetailsid from unnest(v_arry_agriculture) a) 
														 RETURNING valuationid::bigint into v_valid;
						end if;
						
					end loop;
			end if;
Return v_valid;
   END;
$$;


