--
-- Name: fn_insert_valuation_details(kaverimrg.valuation_details[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_valuation_details(p_valuationdetails kaverimrg.valuation_details[] DEFAULT NULL::kaverimrg.valuation_details[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_arry_valuation p_valuationdetails%type;
v_valuationid bigint;
v_cnt integer;
v_valid bigint;
begin
/*select count(*) into v_cnt from kaverimrg.valuationdetails where valid in 
(select a._valid from unnest(p_valuationdetails) a) ;*/
if(p_valuationdetails is not null and array_length(p_valuationdetails,1)>0 ) then
	FOR v_arry_valuation IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_valuationdetails)) 
		loop
			v_cnt:= 0;
			select count(*) into v_cnt from kaverimrg.valuationdetails where valid in 
			(select a._valid from unnest(v_arry_valuation) a) ;
			
			if v_cnt = 0 then
			  INSERT INTO kaverimrg.valuationdetails(
				valid ,
				srocode,
				regsrocode,
				villagecode,
				roadcode,
				valuationdate,
				propertytypeid,
				totalarea,
				unitid,
				marketvalue,
				leasetype,
				leaseamount,
				northboundary,
				southboundary,
				eastboundary,
				westboundary,
				assessment,
				regarticlecode,
				applicationnumber,
				 verified,
				issroapproved,
				propertyid)
				select  nextval('kaverimrg.valuationdetails_seq'), 
				a._srocode,
				a._regsrocode,
				a._villagecode,
				a._roadcode,
				a._valuationdate,
				a._propertytypeid,
				a._totalarea,
				a._unitid,
				a._marketvalue,
				a._leasetype,
				a._leaseamount,
				a._northboundary,
				a._southboundary,
				a._eastboundary,
				a._westboundary,
				a._assessment,
				a._regarticlecode,
				a._applicationnumber,
				 a._verified,
				a._issroapproved,
				a._propertyid from unnest(v_arry_valuation) a
				 returning valid::bigint into v_valuationid;
			else 
				update kaverimrg.valuationdetails
				set srocode=a._srocode,
				regsrocode=a._regsrocode,
				villagecode=a._villagecode,
				roadcode=a._roadcode,
				valuationdate=a._valuationdate,
				propertytypeid=a._propertytypeid,
				totalarea=a._totalarea,
				unitid=a._unitid,
				marketvalue=a._marketvalue,
				leasetype=a._leasetype,
				leaseamount=a._leaseamount,
				northboundary=a._northboundary,
				southboundary=a._southboundary,
				eastboundary=a._eastboundary,
				westboundary=a._westboundary,
				assessment=a._assessment,
				regarticlecode=a._regarticlecode,
				applicationnumber=a._applicationnumber,
				verified = a._verified,
				issroapproved=a._issroapproved,
				propertyid=a._propertyid from unnest(v_arry_valuation) a  where valid in 
						 (select a._valid from unnest(v_arry_valuation) a) 
						 RETURNING valid::bigint  into v_valuationid;
			end if;	
	   end loop;
end if;
Return v_valuationid;
	--Return v_schid;
   END;
$$;


