-- Name: fn_insert_witness_info_save(kaverimrg.witnessinfo1_save_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insert_witness_info_save(p_witnessdetails kaverimrg.witnessinfo1_save_input[] DEFAULT NULL::kaverimrg.witnessinfo1_save_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
	id_val bigint;
    --inserted_id integer;
	cit_id text;
   --property_arry $1%type;
   v_arr_witnessinfo p_witnessdetails%type;
   p_arr_partywitnessdetails kaverimrg.party_witness_input[];
   v_arr_partywitnessdetails kaverimrg.party_witness_input[];
   v_witnessid bigint;
   vs_witnessid bigint;
   var_r record;
   v_pid bigint[];
v_cnt integer;
v_cnt1 integer;
v_srocode bigint;
v_partyid bigint;
begin
/*Select count(*) into v_cnt from kaverimrg.witnessinfo where witnessid in 
(select a._witnessid from unnest($1) a) ;*/
if(p_witnessdetails  is not null and array_length(p_witnessdetails,1)>0 ) then
FOR v_arr_witnessinfo  IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_witnessdetails))
loop
v_cnt:= 0;
v_witnessid:=0;
Select count(*) into v_cnt from kaverimrg.witnessinfo where witnessid in 
(select a.wid from unnest(v_arr_witnessinfo) a) ;
if v_cnt = 0 then
INSERT INTO kaverimrg.witnessinfo( witnessid,
    documentid,
    name,
    address,
    sex,
    age,
    profession,
    registrationid,
    dateofbirth,
    status,
    phoneno,
    relation,
    mothername,
    fathersname,
    presentatsolemanization,
	srocode,
    isonline,
	applicationnumber,
	verified,
	issroapproved,
	statecode,
    districtcode,
    talukcode,
    hoblicode,
    villagecode,
    relativename,
    pincode,
    middlename,
    lastname,
    houseno,
    iscliment,
    isexicutent)
    select  
	nextval('kaverimrg.witnessinfo_witnessid_seq'),
    documentid,
    name,
    address,
    sex,
    age,
    profession,
    registrationid,
    dateofbirth,
    status,
    phoneno,
    relation,
    mothername,
    fathersname,
    presentatsolemanization,
	srocode,
    isonline,
	applicationnumber,
	verified,
	issroapproved,
	statecode,
    districtcode,
    talukcode,
    hoblicode,
    villagecode,
    relativename,
    pincode,
    middlename,
    lastname,
    houseno,
    iscliment,
    isexicutent
	from unnest(v_arr_witnessinfo)	
	 returning witnessid::bigint into v_witnessid;
	 else
	 update kaverimrg.witnessinfo set
	  documentid= a.documentid,
    name=a.name,
    address=a.address,
    sex=a.sex,
    age=a.age,
    profession=a.profession,
    registrationid=a.registrationid,
    dateofbirth=a.dateofbirth,
    status=a.status,
    phoneno=a.phoneno,
    relation=a.relation,
    mothername=a.mothername,
    fathersname=a.fathersname,
    presentatsolemanization=a.presentatsolemanization,
	--srocode=a.srocode,
    isonline=a.isonline,
	applicationnumber=a.applicationnumber,
	verified=a.verified,
	issroapproved=a.issroapproved,
	statecode=a.statecode,
    districtcode=a.districtcode,
    talukcode=a.talukcode,
    hoblicode=a.hoblicode,
    villagecode=a.villagecode,
    relativename=a.relativename,
    pincode=a.pincode,
    middlename=a.middlename,
    lastname=a.lastname,
    houseno=a.houseno,
    iscliment=a.iscliment,
    isexicutent=a.isexicutent
	from unnest(v_arr_witnessinfo) a  where witnessid in 
			 (select b.wid from unnest(v_arr_witnessinfo) b)
			 RETURNING witnessid::bigint into v_witnessid;
			 --select c.witnessid into v_witnessid from unnest(v_arr_witnessinfo) c limit 1;
	end if;
      
        if(v_witnessid is not null) then  /* To check whether the witnessid returned from witnessinfo is null or not null */
       /* select a._partywitness into p_arr_partywitnessdetails from unnest(v_arr_witnessinfo) a;*/
		 --if(v_witnessid is not null) then
		--if(p_arr_partywitnessdetails  is not null and array_length(p_witnessdetails,1)>0 ) then
			  delete from kaverimrg.partywitness where witnessid= v_witnessid;
		select a.partywitness into p_arr_partywitnessdetails from unnest(v_arr_witnessinfo) a;
			FOR v_arr_partywitnessdetails IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_arr_partywitnessdetails))
				loop
	
          select srocode into v_srocode from kaverimrg.witnessinfo where witnessid = v_witnessid;	

        INSERT INTO kaverimrg.partywitness( partyid,witnessid,witnessdate, srocode)
	select partyid,v_witnessid,witnessdate,v_srocode 
	from  unnest(v_arr_partywitnessdetails)	
	 returning witnessid::bigint into v_witnessid;
		v_pid := array_append(v_pid,v_witnessid);
        end loop;
        end if;
	v_pid := array_append(v_pid,v_witnessid);
	end loop;
	end if;
Return v_pid;
end;
$_$;


