--
-- Name: type_insertamendmentmaster; Type: TABLE; Schema: kaverimrg; Owner: postgres
--

CREATE TABLE kaverimrg.type_insertamendmentmaster (
    _aid integer,
    _applicationnumber character varying,
    _amendmenttypeid integer,
    _finalregistrationnumber character varying,
    _firmapplicationtypeid integer,
    _isactive boolean
);


ALTER TABLE kaverimrg.type_insertamendmentmaster OWNER TO postgres;

--
-- Name: fn_insertamendmentmaster(kaverimrg.type_insertamendmentmaster[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insertamendmentmaster(a_amendmentmaster kaverimrg.type_insertamendmentmaster[] DEFAULT NULL::kaverimrg.type_insertamendmentmaster[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$

declare
v_cnt bigint;
v_aid bigint;
v_applicationnumber character varying;
v_amendmenttypeid integer;
begin


 Select count(*) into v_cnt from kaverimrg.firmamendment where applicationnumber in (select a._applicationnumber from unnest($1)a) ;
 raise notice 'v_cnt=%',v_cnt;
	if v_cnt = 0 then
		
			insert into kaverimrg.firmamendment
			(amendmentid,
			 applicationnumber,
			 amendmenttypeid,
			 finalregistrationnumber,
			 firmapplicationtypeid,
			 isactive
					  )
			select 
			nextval('kaverimrg.aid_seq'),
			a._applicationnumber,
			a._amendmenttypeid,
			a._finalregistrationnumber,
			a._firmapplicationtypeid,
			a._isactive
	
			from unnest($1) a
				returning amendmentid into v_aid;
			
		with selectedtable as 	(select fm.firmname,fm.firmaddress,fm.drcode,fm.housebuildingname,
		fm.streetaddress,fm.statecode,fm.districtcode,
				fm.talukacode,fm.hoblicode,fm.cityvillagecode,fm.pincode 	from kaverimrg.firmmaster fm 
				where  fm.finalregistrationnumber =(select a._finalregistrationnumber from unnest($1)a))
				
		 update  kaverimrg.firmamendment fm
		 set 
		 firmname=selectedtable.firmname,
		 firmaddress=selectedtable.firmaddress,
		 drcode=selectedtable.drcode,
		 amendhousebuildingname=selectedtable.housebuildingname,
		 amendstreetaddress=selectedtable.streetaddress,
		 amendstatecode=selectedtable.statecode,
		 amenddistrictcode=selectedtable.districtcode,
		 amendtalukacode=selectedtable.talukacode,
		 amendhoblicode=selectedtable.hoblicode,
		amendcityvillagecode=selectedtable.cityvillagecode,
		amendpincode=selectedtable.pincode
		from selectedtable
		where fm.amendmentid=v_aid;			
	
		select b._applicationnumber into v_applicationnumber from unnest(a_amendmentmaster) b;
		update kaverimrg.applicantapplicationdetails a
		set currentstatus='FA101'
		where a.applicationnumber=v_applicationnumber;





	else
 	update kaverimrg.firmamendment p1 set 
 	applicationnumber=a._applicationnumber,
 	amendmenttypeid=a._amendmenttypeid,
 	finalregistrationnumber=a._finalregistrationnumber,
 	firmapplicationtypeid=a._firmapplicationtypeid,
 	isactive=a._isactive
	 from unnest($1) a
			 where applicationnumber=(select a._applicationnumber from unnest($1)a)
				returning p1.amendmentid into v_aid;
				
				

	select b._applicationnumber into v_applicationnumber from unnest(a_amendmentmaster) b;
	update kaverimrg.applicantapplicationdetails a
			set currentstatus='FA101'
			where a.applicationnumber=v_applicationnumber;



	end if;		



 
 return v_aid;
 
end;
$_$;


ALTER FUNCTION kaverimrg.fn_insertamendmentmaster(a_amendmentmaster kaverimrg.type_insertamendmentmaster[]) OWNER TO postgres;

