--
-- Name: fn_insertfirmpartydetails(kaverimrg.type_insertfirmpartydetails[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_insertfirmpartydetails(p_partnerdetails kaverimrg.type_insertfirmpartydetails[] DEFAULT NULL::kaverimrg.type_insertfirmpartydetails[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$

declare
v_cnt bigint;
v_firmpersonid bigint;
v_partner_arry kaverimrg.type_insertfirmpartydetails[];
v_pid bigint[];
v_applicationnumber character varying;
v_presentertypeid int;
v_linkfirmpersonid bigint;
v_age int;
begin

if(p_partnerdetails is not null and array_length(p_partnerdetails,1)>0 ) then

 FOR v_partner_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partnerdetails)) 
loop
v_cnt:=0; 
v_firmpersonid:=0;

			 Select count(*) into v_cnt 
			 from kaverimrg.firmparty where firmpersonid in (select a._firmpersonid from unnest(v_partner_arry) a) ;
		if v_cnt = 0 
		then
			  insert into kaverimrg.firmparty
			  (firmpersonid,
			   applicationnumber,
			   registrationid,
			   salutation,
			   firstname,
			   middlename,
			   lastname,
			   relationship,
	           relativename,
			   dob,
			   age,
			   Gender,
			   occupation,
			   phoneno,
			   mailaddress,
			   dateofjoin,
			   datetime,
			   prehousebuildname,
			   prestreetname,
			   prestatecode,
			   predistrictcode,
			   pretalukacode,
			   prehoblicode,
			   precityvillagecode,
			   prepincode,
			   ispresentaddresssameaspermanent,
			   perhousebuildname,
			   perstreetname,
			   perstatecode,
			   perdistrictcode,
			   pertalukacode,
			   perhoblicode,
			   percityvillagecode,
			   perpincode,
			   drcode,
			   applicationtypeid,
			   presentertypeid,
			   isactive,
			   uploadgpa,
			   linkfirmpersonid
			  )
select 
nextval('kaverimrg.firmpersonid_seq'),
	a._applicationnumber,
	a._registrationid,
	a._salutation,
	a._firstname ,
	a._middlename,
	a._lastname,
	a._relationship,
	a._relativename,
	a._dob,
	a._age ,
	a._Gender,
	a._occupation ,
	a._phoneno,
	a._email,
    a._dateofjoin,
	a._datetime,
	a._prehousebuildname,
	a._prestreetname,
	a._prestatecode,
	a._predistrictcode,
	a._pretalukacode,
	a._prehoblicode,
	a._precityvillagecode ,
	a._prepincode,
	a._ispresentaddresssameaspermanent,
	a._perhousebuildname,
	a._perstreetname,
	a._perstatecode,
	a._perdistrictcode,
	a._pertalukacode,
	a._perhoblicode,
	a._percityvillagecode,
	a._perpincode,
	a._drcode,
	a._applicationtypeid,
	a._presentertypeid,
	a._isactive,
	a._uploadgpa,
	a._linkfirmpersonid
 from unnest(v_partner_arry) a
	returning firmpersonid into v_firmpersonid;
	
select a._applicationnumber into v_applicationnumber from unnest(v_partner_arry) a;
select a._presentertypeid into v_presentertypeid from unnest(v_partner_arry) a;

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR103' 
 where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (1,2) ;	

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR104' 
 where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (6);	

		else
			  update kaverimrg.firmparty p1 set 
			  applicationnumber=COALESCE(a._applicationnumber,applicationnumber),
			  registrationid= COALESCE(a._registrationid,registrationid),
			  salutation=COALESCE(a._salutation,salutation),
			  firstname = COALESCE(a._firstname,firstname), 
			  middlename = COALESCE(a._middlename,middlename),
lastname = COALESCE(a._lastname,lastname),
relationship= COALESCE(a._relationship,relationship),
relativename= COALESCE(a._relativename,relativename),
dob= COALESCE(a._dob,dob),
age= COALESCE(a._age,age),
Gender=COALESCE(a._Gender,Gender),
occupation = COALESCE(a._occupation),
phoneno= COALESCE(a._phoneno,phoneno),
mailaddress= COALESCE(a._email,mailaddress),
dateofjoin=COALESCE(a._dateofjoin,dateofjoin),
datetime=COALESCE(a._datetime,datetime),
prehousebuildname= COALESCE(a._prehousebuildname,prehousebuildname),
prestreetname= COALESCE(a._prestreetname,prestreetname),
prestatecode = COALESCE(a._prestatecode,prestatecode),
predistrictcode = COALESCE(a._predistrictcode,predistrictcode),
pretalukacode = COALESCE(a._pretalukacode,pretalukacode),
prehoblicode = COALESCE(a._prehoblicode,prehoblicode),
precityvillagecode = COALESCE(a._precityvillagecode,precityvillagecode),
prepincode=COALESCE(a._prepincode,prepincode),
ispresentaddresssameaspermanent=COALESCE(a._ispresentaddresssameaspermanent,ispresentaddresssameaspermanent),
perhousebuildname= COALESCE(a._perhousebuildname,perhousebuildname),
perstreetname= COALESCE(a._perstreetname,perstreetname),
perstatecode = COALESCE(a._perstatecode,perstatecode),
perdistrictcode = COALESCE(a._perdistrictcode,perdistrictcode),
pertalukacode = COALESCE(a._pertalukacode,pertalukacode),
perhoblicode = COALESCE(a._perhoblicode,perhoblicode),
percityvillagecode = COALESCE(a._percityvillagecode,percityvillagecode),
perpincode=COALESCE(a._perpincode,perpincode),
drcode=COALESCE(a._drcode,drcode),
applicationtypeid=COALESCE(a._applicationtypeid,applicationtypeid),
presentertypeid=COALESCE(a._presentertypeid,presentertypeid),
isactive=COALESCE(a._isactive,isactive),
uploadgpa=COALESCE(a._uploadgpa,uploadgpa)--,
--linkfirmpersonid=COALESCE(a._linkfirmpersonid,linkfirmpersonid)
				from unnest(v_partner_arry) a
			  where p1.firmpersonid in  (select a._firmpersonid from unnest(v_partner_arry) a)
				returning a._firmpersonid into v_firmpersonid;
 end if;
 
  select presentertypeid,linkfirmpersonid,age into v_presentertypeid,v_linkfirmpersonid,v_age
	from kaverimrg.firmparty where firmpersonid = v_firmpersonid;
	
	
	if ( v_age<18) and (v_linkfirmpersonid is not null) then
	null;
	end if;
	
	
	if ( v_age<18) and (v_linkfirmpersonid is null) 
	then
	update kaverimrg.firmparty set linkfirmpersonid = v_firmpersonid+1 where presentertypeid = 6 -- Guardian
	and firmpersonid = v_firmpersonid;
	end if;
	
	update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR103' 
 where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (1,2) ;	

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR104' 
 where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (6);	
 
	
 v_pid := array_append(v_pid,v_firmpersonid);
 
  END LOOP;
 end if;

return v_pid;

end;
$$;


