--
-- Name: fn_marriage_applicant_phone(bigint, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_marriage_applicant_phone(cid bigint, appnum character varying) RETURNS TABLE(v_phone bigint, v_partyid integer)
    LANGUAGE plpgsql
    AS $$

declare

v_citizenid bigint;
v_applicationvalid bool;
v_primaryapplicant bool;
v_partyid int;
v_phone bigint;

	begin
		
		select (case  when appnum LIKE '%MRG%' then true else false end )  into v_applicationvalid;
	
		if v_applicationvalid then 
	
				select coalesce((select isprimaryapplicantbride  from kaverimrg.marriageregistration p where p.applicationnumber = appnum and p.marriagetypeid=2) , null) into v_primaryapplicant;
			
			
			if v_primaryapplicant is null then
					
					select phone into v_phone from kaverimrg.citizenmaster c where citizenid = cid ;
				
			elseif v_primaryapplicant is true then
	
					select p.phoneno into v_phone from kaverimrg.persondetails p  where p.applicationnumber = appnum and p.persontypeid = 1 ;
	
			elseif v_primaryapplicant is false then
	
					select p.phoneno into v_phone from kaverimrg.persondetails p  where p.applicationnumber = appnum and p.persontypeid = 2;
	
			else
	
					select phone into v_phone from kaverimrg.citizenmaster c where citizenid = cid;
	
		end if;
	
			
		else
	
				select phone into v_phone from kaverimrg.citizenmaster c where citizenid = cid;

		end if;
	
			return query select v_phone,0;
	
	END;
$$;


ALTER FUNCTION kaverimrg.fn_marriage_applicant_phone(cid bigint, appnum character varying) OWNER TO postgres;

--
-- Name: fn_reconstitutionfetch_firm_details(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_reconstitutionfetch_firm_details(_finalregistrationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$


declare 
v_data_json json;
BEGIN
select row_to_json(data_json) into v_data_json 
	    from ( select c.districtnamee,c.districtnamee as droffice,
		
 ( select (row_to_json(Firmdetails))
  from (select d.firmname, d.nature as natureofbusiness, d.firmphone as phone_number,
  d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname||' '||d.streetaddress||' '||di.districtnamee||' '||ta.taluknamee||' '||ho.hoblinamee||' '||vill.villagenamee||' '||
		stat.statenamee||'-'||d.pincode as Address,	
		count(firmpersonid) as Number_of_members,
		count(distinct f.branchid) as No_of_Branches,d.finalregistrationnumber,d.durationoffirm
			from kaverimrg.firmmaster d 
		left join kaverimrg.firmbranches f on d.applicationnumber =f.applicationnumber 
		inner join kaverimrg.firmparty fp on d.applicationnumber=fp.applicationnumber
		left join kaverimrg.districtmaster di on d.districtcode = di.districtcode
	    left join kaverimrg.talukmaster ta on d.talukacode = ta.talukcode
		left join kaverimrg.hoblimaster ho on d.hoblicode = ho.hoblicode
		left join kaverimrg.villagemaster vill on d.cityvillagecode = vill.villagecode
		left join kaverimrg.statemaster stat on d.statecode = stat.statecode
			where d.finalregistrationnumber =_finalregistrationnumber
	   	group  by 	  d.firmname, d.nature,d.firmphone,d.registrationid,d.applicationnumber,
		d.housebuildingname,d.streetaddress,d.districtcode, di.districtcode,d.talukacode,ta.taluknamee,d.hoblicode,ho.hoblinamee,
		d.cityvillagecode,vill.villagenamee ,d.statecode,stat.statenamee,
			d.housebuildingname,d.streetaddress,di.districtnamee,ta.taluknamee,ho.hoblinamee,vill.villagenamee,
		stat.statenamee,d.pincode,d.finalregistrationnumber,d.durationoffirm)Firmdetails) as Firmdetails,
			  
			  	   
( select array_to_json(array_agg(row_to_json(Branchdetails)))
  from ( select
			--bg.branchid,d.finalregistrationnumber,
			coalesce(bg.branchhousebuildingname,' ')||' '||
			coalesce(bg.branchstreetaddress,' ')||' '||
			dis.districtnamee||' '||tal.taluknamee||' '||
		stlgd.statenamee||'-'||
		coalesce(bg.branchpincode::text,' ') as Address, bg.branchphone
		from kaverimrg.firmmaster d 
		inner join kaverimrg.firmbranches bg on d.applicationnumber =bg.applicationnumber
		left join kaverimrg.lgd_statemaster stlgd on bg.branchstatecode = stlgd.statecode
		left join kaverimrg.lgd_districtmaster dis on bg.branchdistrictcode = dis.districtcode
		left join kaverimrg.lgd_talukmaster tal on bg.branchtalukacode = tal.talukcode 			                       
        where d.applicationnumber=bg.applicationnumber  and
		d.finalregistrationnumber = _finalregistrationnumber )Branchdetails) as Branchdetails,
		  
		  
( select row_to_json(presenter_detils)
from (select br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,2))presenter_detils) as presenter_detils,

( select array_to_json(array_agg(row_to_json(partnerdetails)))
from (select
br.firmpersonid,
br.relationship,
br.relativename,
br.dob,
br.gender,
br.age,
br.occupation,
br.dateofjoin,
br.presentertypeid,
br.salutation,
br.prehousebuildname,
br.prestreetname,
br.prestatecode,
br.predistrictcode,
br.pretalukacode,
br.prehoblicode,
br.precityvillagecode,
br.prepincode,
br.ispresentaddresssameaspermanent ,
br.perstreetname,
br.perstatecode,
br.perdistrictcode,
br.pertalukacode,
br.perhoblicode,
br.percityvillagecode,
br.perpincode,
br.identityproofid,
br.identityproofidpath,br.addressproofid,
br.addressproofidpath,  
br.linkfirmpersonid,
 br.firstname,br.middlename,br.lastname, pt.description as designation, br.phoneno as phonenumber,br.mailaddress as EmailID
from kaverimrg.firmmaster d 
	inner join kaverimrg.firmparty br on d.applicationnumber=br.applicationnumber
inner join kaverimrg.mas_frm_presentertypes pt on br.presentertypeid=pt.presentertypeid
where d.finalregistrationnumber = _finalregistrationnumber and br.presentertypeid in (1,6)
	 order by firmpersonid)partnerdetails
) as partnerdetails,	  
							
( select array_to_json(array_agg(row_to_json(firmwitness)))
  from (select coalesce(fe.firstname,null) as firstname,coalesce(fe.middlename,'') as middlename,
		coalesce(fe.lastname,'') as lastname,coalesce(fe.profession,null) as profession,
		coalesce(fe.phonenumber,'') as phonenumber,coalesce(fe.mailaddress,'') as EmailID
					from kaverimrg.firmmaster d 	
 inner join kaverimrg.frm_witnessdetails fe  on d.applicationnumber=fe.applicationnumber
			where d.finalregistrationnumber =_finalregistrationnumber)firmwitness) as firmwitness
	   
from kaverimrg.firmmaster d 	
    inner join 	kaverimrg.firmparty a on d.applicationnumber=a.applicationnumber
inner join kaverimrg.districtmaster c on a.predistrictcode = c.districtcode
where d.finalregistrationnumber =_finalregistrationnumber
   
			 ) data_json;

return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.fn_reconstitutionfetch_firm_details(_finalregistrationnumber character varying) OWNER TO postgres;

--
-- Name: fn_reject_fruits_filing(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_reject_fruits_filing(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_referenceno varchar;
BEGIN  
update kaverimrg.documentmaster set currentstatus = 'CD134'
where applicationnumber= _applicationnumber;

update kaverimrg.fruits_data_recv_details set applicationstatus = 4
where applicationnumber= _applicationnumber returning referenceno into v_referenceno;
return v_referenceno;
END;
$$;


ALTER FUNCTION kaverimrg.fn_reject_fruits_filing(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_save_docesign(character varying, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_docesign(_doc_guid character varying, _esign_data text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cnt int;
   v_doc_guid text;
BEGIN
   select count(1) into v_cnt from kaverimrg.document_esign where doc_guid = _doc_guid;
   if (coalesce(v_cnt,0) > 0 ) then
    update kaverimrg.document_esign set esign_data = _esign_data where doc_guid = _doc_guid 
		 returning  doc_guid into v_doc_guid;	 
	else
		 INSERT INTO kaverimrg.document_esign (doc_guid,esign_data,docdate)
	  values (_doc_guid,_esign_data,current_timestamp)	returning  doc_guid into v_doc_guid;
	 end if;
   return v_doc_guid;
END;
$$;


ALTER FUNCTION kaverimrg.fn_save_docesign(_doc_guid character varying, _esign_data text) OWNER TO postgres;

--
-- Name: fn_save_documentmaster(bigint, character varying, boolean, boolean, text, boolean, text, text, boolean, boolean, boolean, character varying, character varying, text, text, integer[], timestamp without time zone, character varying, boolean, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_documentmaster(_documentid bigint, _applicationnumber character varying, _isregistrationaccepted boolean DEFAULT NULL::boolean, _isuploadprintsummary boolean DEFAULT NULL::boolean, _uploadsummarydocpath text DEFAULT NULL::text, _isprintendorsement boolean DEFAULT NULL::boolean, _uploadregistereddocpath text DEFAULT NULL::text, _uploadannexuredocpath text DEFAULT NULL::text, _isuploaddocuments boolean DEFAULT NULL::boolean, _isdigitalsigned boolean DEFAULT NULL::boolean, _isregistrationcompleted boolean DEFAULT NULL::boolean, _currentstatus character varying DEFAULT NULL::character varying, _lastupdatedby character varying DEFAULT NULL::character varying, _remarks text DEFAULT NULL::text, _remarksk text DEFAULT NULL::text, p_wintess integer[] DEFAULT NULL::integer[], _ackdatetime timestamp without time zone DEFAULT NULL::timestamp without time zone, _ackuser character varying DEFAULT NULL::character varying, _isphotothumbtransmitted boolean DEFAULT NULL::boolean, _isprintsummary boolean DEFAULT NULL::boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$


Declare
v_appnumber text;
v_finalregnum text;
v_srocode bigint;
v_valid bigint;
_cnt integer;
v_fruits_appl integer;
v_isdigitalsigned boolean;
v_isbefore2003 bool;
v_finalregcheck text;
begin

select count(*) into v_fruits_appl from kaverimrg.fruits_data_recv_details fdrd where fdrd.applicationnumber = _applicationnumber; 

select finalregistrationnumber into v_finalregcheck from kaverimrg.documentmaster d where applicationnumber = _applicationnumber;

if (v_finalregcheck is null) then

if(_currentstatus is not null and _currentstatus <> '' and _lastupdatedby is not null and _lastupdatedby<> '') then 
select kaverimrg.fn_upd_application_status(p_applicationnumber=>_applicationnumber,
										p_currentstatus=>_currentstatus,
										p_lastupdatedby=>_lastupdatedby,
									   p_remarks=>_remarks,
									   p_remarksk=>_remarksk   --- To update the Kannada text added on 28-11-2022
									   ) into v_appnumber;
end if;

/*select isdigitalsigned into v_isdigitalsigned from kaverimrg.documentmaster
where documentid = _documentid and 
	applicationnumber= _applicationnumber;
*/
--if (v_isdigitalsigned is null) or (v_isdigitalsigned is not null and v_isdigitalsigned =true or v_isdigitalsigned =false)  then 
--if(v_isdigitalsigned is not null and v_isdigitalsigned =true)  then 
if( _isdigitalsigned =true) then 
	UPDATE kaverimrg.documentmaster set 
	isdigitalsigned=_isdigitalsigned,
	uploaddocdeedpath=_uploadregistereddocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	--returning applicationnumber into v_appnumber;
	
end if;

if(_isregistrationaccepted is not null) then 
	UPDATE kaverimrg.documentmaster set 
	isregistrationaccepted=_isregistrationaccepted
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber,srocode into v_appnumber,v_srocode;
	select kaverimrg.fn_fetch_pending_regnumber(v_srocode::integer,v_appnumber::character varying) into v_appnumber;
	
end if;

if(_isuploadprintsummary is not null) then 
	UPDATE kaverimrg.documentmaster set 
	isprintsummary=_isuploadprintsummary,
	uploadsummarydocpath = _uploadsummarydocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;	
	
end if;

if(_isprintendorsement is not null) then
	UPDATE kaverimrg.documentmaster set 
	isprintendorsement=_isprintendorsement
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber,srocode into v_appnumber,v_srocode;
	 
	
	if(_currentstatus = 'CD112') THEN
		select kaverimrg.fn_update_final_regnumber(v_srocode::integer,v_appnumber::character varying) into v_finalregnum;
	end if;
	
	
	if(_isprintendorsement = true) then
	update kaverimrg.partyinfo set isEndorsePrinted= 'true' where documentid = _documentid and 
	applicationnumber= _applicationnumber and ((thumbpath is not null and photopath is not null 
	and thumbpath <> '' and photopath <> '' )or(section88exemption =true));
	
--	update kaverimrg.partyinfo set isEndorsePrinted= 'true' where documentid = _documentid and 
--    applicationnumber= _applicationnumber and section88exemption =true;
--	
		if(p_wintess is not null and array_length(p_wintess,1) > 0) then
			update kaverimrg.witnessinfo set isEndorsePrinted= 'true'
			where witnessid in (select * from unnest(p_wintess::int[]));
		end if;
	end if;	
end if;

if (_isuploaddocuments is not null and _isuploaddocuments= true) then
	UPDATE kaverimrg.documentmaster set 
	isuploaddocuments=_isuploaddocuments,
	uploaddocdeedpath = _uploadregistereddocpath,
	uploaddocannexurepath = _uploadannexuredocpath,
	uploaddocdatetime = CURRENT_TIMEstamp
	where documentid = _documentid and 
	applicationnumber= _applicationnumber
	returning applicationnumber into v_appnumber;	
end if;

/*if(_isdigitalsigned is not null and _isdigitalsigned ='True') then 
--if( _isdigitalsigned =true::boolean) then 
	UPDATE kaverimrg.documentmaster set 
	isdigitalsigned=_isdigitalsigned::boolean,
	uploaddocdeedpath=_uploadregistereddocpath
	where documentid = _documentid and 
	applicationnumber= _applicationnumber;
	--returning applicationnumber into v_appnumber;
	
end if;*/

if(_isregistrationcompleted is not null and _isregistrationcompleted =true) then 
