--
-- Name: fn_save_minutebook_data(character varying, integer, character varying, integer, text, boolean, timestamp without time zone, text, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_minutebook_data(_applicationnumber character varying, _reasonid integer, _remarks character varying, _srocode integer, _remarkcomment text, _ispendingdocument boolean DEFAULT false, _minutedate timestamp without time zone DEFAULT (CURRENT_TIMESTAMP)::timestamp without time zone, _pendingregistrationnumber text DEFAULT NULL::text, _isbefore2003 boolean DEFAULT NULL::boolean) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

Declare
v_docid bigint;
begin
if (select count(*) from kaverimrg.minutebook_data where applicationnumber = _applicationnumber) = 0
then 
insert into kaverimrg.minutebook_data(
    docid,
    applicationnumber,
    reasonid,
    remarks,
    issystem,
    srocode,remark_comment,ispendingdocument,minutedate,pendingregistrationnumber,isBefore2003) values
(
nextval('kaverimrg.docid_seq'),
  _applicationnumber,
     _reasonid,
    _remarks,
    false,
    _srocode,
    _remarkcomment,
    _ispendingdocument,
    _minutedate,
    _pendingregistrationnumber,
    _isBefore2003
) returning docid into v_docid;

else 

update kaverimrg.minutebook_data
set 
    --docid=nextval('kaverimrg.docid_seq'),
    reasonid=_reasonid,
    remarks=_remarks,
    issystem=false,
    remark_comment=_remarkcomment,
    isbefore2003 = _isBefore2003
--    ispendingdocument
where applicationnumber = _applicationnumber returning docid into v_docid;
end if;

return v_docid;
   END;
$$;


