	left join kaverimrg.mas_officemaster mo on (mo.officeid = epay.officeid ) 
	left join kaverimrg.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
  where khj.deptreferencecode = v_deptrefcode 
) app_json ;

	RETURN v_data_json;
   END;
