begin

v_deptrefcode := '';
v_nomenclature :='RG'||to_char(now(),'MM')||''||to_char(now(),'YY');
v_transactionid:=v_nomenclature||v_serial;


select count(*) into v_cnt from kaverimrg.ec_applicationdetails 
where applicationnumber = _applicationnumber;

if(v_cnt > 0) then
select count(*) into v_count  from kaverimrg.ams_reg_epaymenttransdetails where applicationnumber=_applicationnumber;
if (v_count=0)
then
select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,8,'0') into v_serial ;
