select count(*) into v_cnt from kaverimrg.cc_applicationdetails 
where applicationnumber = _applicationnumber;

if(v_cnt > 0) then
select count(*) into v_count from kaverimrg.ams_reg_epaymentamtpaiddetails where applicationnumber=_applicationnumber;
if(v_count=0)
then
select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,8,'0') into v_serial ;
