			where fees.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead 
					group by  app.applicationnumber,fees.feerulecode, fm.feerulename, 
					   fm.deptpurposeid, fm.accntheadname, fm.prpsname, fm.subrefcode,
			fm.trsrycode,fm.prpsnamehead,app.srocode,cm.firstname, cm.middlename, cm.lastname)
	
