					where ccapp.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL)
					
loop 
	v_deptrefcode := '';
	v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
