	values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
	
	for subref_row in (select ccapp.applicationnumber,ccfees.ccid, ccfees.feeruleid, ccfees.payableamount, 
			ccfees.serviceid,fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
			fm.trsrycode,fm.prpsnamehead,ccapp.kaverimrgsrocode,fm.subrefcode,
					   concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS remittername from 
					   kaverimrg.cc_applicationdetails ccapp 
					   inner join kaverimrg.cc_requiredfees ccfees on ccapp.ccid = ccfees.ccid
					   left join kaverimrg.citizenmaster cm on (ccapp.userid = cm.citizenid)
			left join kaverimrg.vw_feesrule_mapping fm on  ccfees.feeruleid = fm.feerulecode
			where applicationnumber = _applicationnumber and fm.prpsnamehead=pmnt_row.prpsnamehead
			 )
loop		
		v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
	insert into kaverimrg.ams_reg_epaymentamtpaiddetails(
	chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
	values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
		   _applicationnumber,v_deptrefcode) ;
	
		INSERT INTO kaverimrg.ams_reg_epaymenttransdetails
		( officeid, remittername, totalamount, chlnrefnum, 
	deptreferencecode,  applicationnumber,treasurycode)
	values(subref_row.kaverimrgsrocode,subref_row.remittername,abs(subref_row.payableamount),
	v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode) ;
	
		end loop;
	
    end loop;
end if;
select row_to_json(app_json) into v_data_json
from (
  select khj.deptreferencecode,khj.applicationnumber,khj.datetimestamp, 
	epay.officeid,epay.remittername,epay.treasurycode, epay.totalamount,
	ddo.ddocode,'33E' AS deptrefcode,
     (
      select array_to_json(array_agg(row_to_json(subref)))
      from (select deptreferencecode,chlnrefnum, deptpurposeid, headofaccount as prpsname, totalamount as amount
			from kaverimrg.ams_reg_epaymentamtpaiddetails sub_ref
			where sub_ref.deptreferencecode = khj.deptreferencecode and totalamount > 0) subref
