ALTER FUNCTION kaverimrg.fn_save_paymentdetails_check(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentdetails_prod(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_paymentdetails_prod(_applicationnumber character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$

Declare
v_appnumber text;
v_nomenclature character varying (50);
v_serial character varying (50);
v_deptrefcode character varying (50);
v_subdeptrefcode character varying (50);
v_transactionid character varying (50);

pmnt_row record;
subref_row record;
v_data_json json;
v_cnt bigint ;
v_nomen character varying (50);
v_serialno character varying (50);
v_transactid character varying (50);
v_count bigint;
v_exemption_amount numeric;
v_deptreferencecode_delete character varying(50);
begin

v_deptrefcode := '';
v_nomenclature :='RG'||to_char(now(),'MM')||''||to_char(now(),'YY');
v_transactionid:=v_nomenclature||v_serial;


select count(*) into v_cnt from kaverimrg.ec_applicationdetails 
where applicationnumber = _applicationnumber;

if(v_cnt > 0) then
select count(*) into v_count  from kaverimrg.ams_reg_epaymenttransdetails where applicationnumber=_applicationnumber;
if (v_count=0) then
    select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,8,'0') into v_serial ;
    for pmnt_row in (select distinct ecapp.applicationnumber,ecfees.ecid, fm.prpsnamehead 
        from kaverimrg.ec_applicationdetails ecapp
        inner join kaverimrg.ec_requiredfees ecfees on ecapp.ecid = ecfees.ecid 
        left join kaverimrg.vw_feesrule_mapping fm on  ecfees.feeruleid = fm.feerulecode
        where ecapp.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL) loop 
        v_deptrefcode := '';
        v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
        insert into kaverimrg.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
        values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
        
	    for subref_row in (select ecapp.applicationnumber,ecfees.ecid, ecfees.feeruleid, ecfees.payableamount, 
			ecfees.serviceid,fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
			fm.trsrycode,fm.prpsnamehead,ecapp.kaverimrgsrocode,fm.subrefcode,
					   concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS remittername from 
					   kaverimrg.ec_applicationdetails ecapp 
					   inner join kaverimrg.ec_requiredfees ecfees on ecapp.ecid = ecfees.ecid
					   left join kaverimrg.citizenmaster cm on (ecapp.userid = cm.citizenid)
			left join kaverimrg.vw_feesrule_mapping fm on  ecfees.feeruleid = fm.feerulecode
			where ecapp.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead ) loop		
		    
            v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
        
            insert into kaverimrg.ams_reg_epaymentamtpaiddetails(
            chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
            values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
                _applicationnumber,v_deptrefcode) ;
                	
            INSERT INTO kaverimrg.ams_reg_epaymenttransdetails
            ( officeid, remittername, totalamount, chlnrefnum, deptreferencecode,  applicationnumber,treasurycode , documentid,  feerulecode,ecid )
            values(subref_row.kaverimrgsrocode,subref_row.remittername,abs(subref_row.payableamount),
            v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.ecid, subref_row.feeruleid,subref_row.ecid  ) ;            
		end loop;	
    end loop;
	else 
	    select deptreferencecode into v_deptrefcode from kaverimrg.ams_reg_epaymenttransdetails where applicationnumber=_applicationnumber;
    end if;
end if;

/* Logic for Property Registration */

select count(*) into v_cnt from kaverimrg.feesrequired where applicationnumber=_applicationnumber;
if (v_cnt > 0) then
    
    --* Commented on Jun 14, 2023; to start generating new deptrefcode on every transaction and handle null on exemption amount.
	 select distinct deptreferencecode into v_deptreferencecode_delete from kaverimrg.ams_reg_epaymenttransdetails ept --join kaverimrg.ams_reg_epaymentbankackdetails epb on ept.deptreferencecode=epb.deptreferencecode
	 where ept.applicationnumber=_applicationnumber and ept.isdelete=false; --and (epb.paymentstatuscode='10700066');
    
	update kaverimrg.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=v_deptreferencecode_delete;
	
	select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemption_amount from kaverimrg.feesrequired f 
    where f.applicationnumber = _applicationnumber and f.feerulecode in ('35', '104', '88','89');

    select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,12,'0') into v_serial ;
    for pmnt_row in (select distinct app.applicationnumber,fm.prpsnamehead
        from kaverimrg.applicantapplicationdetails app
        inner join kaverimrg.feesrequired fees on fees.applicationnumber = app.applicationnumber
        left join kaverimrg.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
        where app.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL) loop 
            
        v_deptrefcode := '';
        v_deptrefcode :=v_nomenclature||v_serial;
    
        insert into kaverimrg.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
        values (v_deptrefcode,_applicationnumber,v_transactid,current_timestamp) ;
    
        for subref_row in (select app.applicationnumber,fees.feerulecode, 
            sum(case when fees.feerulecode='36' then
                    (case when coalesce(fees.amountpaid,0) <= v_exemption_amount then 0 
                    else (coalesce(fees.amountpaid,0) - v_exemption_amount) end)
                else coalesce(fees.amountpaid,0) end) as amountrequired, fm.feerulename, fm.deptpurposeid, 
            fm.accntheadname, fm.prpsname, fm.trsrycode,fm.prpsnamehead,app.srocode,fm.subrefcode,
            (case when cm.isinstitution=true then cm.middlename else concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) end) AS remittername,
            fees.documentid ,  fees.feerulecode from  kaverimrg.applicantapplicationdetails app 
            -- join kaverimrg.partyinfo p on app.applicationnumber =p.applicationnumber
            inner join kaverimrg.feesrequired fees on app.applicationnumber = fees.applicationnumber and coalesce(fees.amountpaid,0)>0
            --commented on March 15, 2023 to calculate the sum total of deficit duties
            --left join kaverimrg.feesrequired fees_def on (app.applicationnumber = fees_def.applicationnumber and fees_def.feerulecode in ('35', '104'))
            join kaverimrg.citizenmaster cm on (app.citizenid = cm.citizenid)
            join kaverimrg.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
            where fees.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead 
            group by  app.applicationnumber,fees.feerulecode, fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, fm.subrefcode,
            fm.trsrycode,fm.prpsnamehead,app.srocode,cm.firstname, cm.middlename, cm.lastname, fees.documentid ,  fees.feerulecode,cm.isinstitution ) loop
            
            v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
    
            insert into kaverimrg.ams_reg_epaymentamtpaiddetails(
            chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
            values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,(subref_row.amountrequired),0,
                _applicationnumber,v_deptrefcode) ;
    
            INSERT INTO kaverimrg.ams_reg_epaymenttransdetails
            ( officeid, remittername, totalamount, chlnrefnum, 
            deptreferencecode,  applicationnumber,treasurycode, documentid ,feerulecode  )
            values(subref_row.srocode,subref_row.remittername,(subref_row.amountrequired),
            v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.documentid  ,
            subref_row.feerulecode ) ;
        end loop;
    end loop;
    /* if (v_count=0) then		
    else
        select deptreferencecode into v_deptrefcode from kaverimrg.ams_reg_epaymenttransdetails 
        where applicationnumber=_applicationnumber and isdelete=false order by inserteddatetime desc limit 1;		
        --update kaverimrg.ams_reg_epaymenttransdetails  set isdelete=true where deptreferencecode<>v_deptrefcode;
	end if;		  */
end if;
	
/* Logic for Certified copy */
select count(*) into v_cnt from kaverimrg.cc_applicationdetails  where applicationnumber = _applicationnumber;

if(v_cnt > 0) then
    select count(*) into v_count from kaverimrg.ams_reg_epaymentamtpaiddetails where applicationnumber=_applicationnumber;
    if(v_count=0) then
        select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,8,'0') into v_serial ;
        for pmnt_row in (select distinct ccapp.applicationnumber,ccfees.ccid, fm.prpsnamehead 
            from kaverimrg.cc_applicationdetails ccapp
            inner join kaverimrg.cc_requiredfees ccfees on ccapp.ccid = ccfees.ccid 
            left join kaverimrg.vw_feesrule_mapping fm on  ccfees.feeruleid = fm.feerulecode
            where ccapp.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL) loop 

            v_deptrefcode := '';
            v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
            insert into kaverimrg.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
            values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
	
	        for subref_row in (select ccapp.applicationnumber,ccfees.ccid, ccfees.feeruleid, ccfees.payableamount, 
                ccfees.serviceid,fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
                fm.trsrycode,fm.prpsnamehead,ccapp.kaverimrgsrocode,fm.subrefcode,
                concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname)  AS remittername 
                from kaverimrg.cc_applicationdetails ccapp 
                --  join kaverimrg.partyinfo p on ccapp.applicationnumber =p.applicationnumber 
                inner join kaverimrg.cc_requiredfees ccfees on ccapp.ccid = ccfees.ccid
                left join kaverimrg.citizenmaster cm on (ccapp.userid = cm.citizenid)
			    left join kaverimrg.vw_feesrule_mapping fm on  ccfees.feeruleid = fm.feerulecode
			    where ccapp.applicationnumber = _applicationnumber and fm.prpsnamehead=pmnt_row.prpsnamehead) loop		
		        
                v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
                insert into kaverimrg.ams_reg_epaymentamtpaiddetails(
                chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
                values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
                    _applicationnumber,v_deptrefcode) ;
                
                INSERT INTO kaverimrg.ams_reg_epaymenttransdetails
                ( officeid, remittername, totalamount, chlnrefnum, deptreferencecode,  applicationnumber,treasurycode , documentid,  feerulecode,ccid)
                values(subref_row.kaverimrgsrocode,subref_row.remittername,abs(subref_row.payableamount),
                v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode,subref_row.ccid,subref_row.feeruleid,subref_row.ccid) ;
		    end loop;
        end loop;
    else
        select deptreferencecode into v_deptrefcode from kaverimrg.ams_reg_epaymenttransdetails am where am.applicationnumber=_applicationnumber;
    end if;
end if;

	/* Logic for marriage regiatration */
select count(*) into v_cnt from kaverimrg.mrg_requiredfees where applicationnumber=_applicationnumber;
if (v_cnt > 0) then
			 select distinct deptreferencecode into v_deptreferencecode_delete from kaverimrg.ams_reg_epaymenttransdetails ept --join kaverimrg.ams_reg_epaymentbankackdetails epb on ept.deptreferencecode=epb.deptreferencecode
			where ept.applicationnumber=_applicationnumber and ept.isdelete=false; --and (epb.paymentstatuscode='10700066');
			
		update kaverimrg.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=v_deptreferencecode_delete;	
		
		select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemption_amount from kaverimrg.feesrequired f 
		where f.applicationnumber = _applicationnumber and f.feerulecode in ('35', '104', '88','89');
		
		--select count(*) into v_count from kaverimrg.ams_reg_epaymenttransdetails where applicationnumber=_applicationnumber;
			--if (v_count=0)
			--then 
			select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,8,'0') into v_serial ;
			for pmnt_row in (select distinct app.applicationnumber,app.registrationid,fm.prpsnamehead
			from kaverimrg.marriageregistration app
			inner join kaverimrg.mrg_requiredfees fees on fees.applicationnumber = app.applicationnumber
			left join kaverimrg.vw_feesrule_mapping fm on  fees.feeruleid = fm.feerulecode
			where app.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL)
loop 
	v_deptrefcode := '';
	v_deptrefcode :=v_nomenclature||v_serial;
	insert into kaverimrg.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
	values (v_deptrefcode,_applicationnumber,v_transactionid,current_timestamp) ;
	
	for subref_row in (select app.applicationnumber,m.registrationid,fees.feeruleid, 
				   fees.payableamount,fees.serviceid,
		fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
			fm.trsrycode,fm.prpsnamehead,app.srocode,fm.subrefcode,
					   concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS remittername from 
				   kaverimrg.applicantapplicationdetails app 
				inner join kaverimrg.marriageregistration m on app.applicationnumber = m.applicationnumber
					   inner join kaverimrg.mrg_requiredfees fees on app.applicationnumber = fees.applicationnumber --and fees.srocode = pmnt_row.srocode
					   and coalesce(fees.payableamount,0)>0
					 left join kaverimrg.citizenmaster cm on (app.citizenid = cm.citizenid)
			left join kaverimrg.vw_feesrule_mapping fm on  fees.feeruleid = fm.feerulecode
			where fees.applicationnumber = _applicationnumber  
			--and fm.prpsnamehead=pmnt_row.prpsnamehead  -- Commented by Partha
			)

loop		
		v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
	insert into kaverimrg.ams_reg_epaymentamtpaiddetails(
	chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
	values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname,abs(subref_row.payableamount),0,
		   _applicationnumber,v_deptrefcode) ;
	
		INSERT INTO kaverimrg.ams_reg_epaymenttransdetails
		( officeid, remittername, totalamount, chlnrefnum, 
	deptreferencecode,  applicationnumber,treasurycode,documentid,feerulecode)
	values(subref_row.srocode,subref_row.remittername,abs(subref_row.payableamount),
	v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode,subref_row.registrationid,subref_row.feeruleid) ;
	
	update kaverimrg.marriageregistration set feesreceived = abs(subref_row.payableamount)	
	where applicationnumber = _applicationnumber;
	end loop;
	end loop;
	--else 
	--select deptreferencecode into v_deptrefcode from kaverimrg.ams_reg_epaymenttransdetails where applicationnumber=_applicationnumber;
--end if;
end if;
/* logic for marriage registration ends her */

/* =====================Generation of Json begins here ==================== */
--select deptreferencecode into v_deptrefcode from kaverimrg.ams_reg_epaymenttransdetails 
--where applicationnumber=_applicationnumber order by inserteddatetime desc limit 1;




select row_to_json(app_json) into v_data_json
from (
  select khj.deptreferencecode,khj.applicationnumber,khj.datetimestamp, 
	epay.officeid,epay.remittername,epay.treasurycode,
	 epay.totalamount,
	ddo.ddocode,'33E' AS deptrefcode,
     (
      select array_to_json(array_agg(row_to_json(subref)))
      from (select deptreferencecode,chlnrefnum, deptpurposeid, headofaccount as prpsname, --1 as amount
			abs(totalamount) as amount
			from kaverimrg.ams_reg_epaymentamtpaiddetails sub_ref
			where sub_ref.deptreferencecode = khj.deptreferencecode and totalamount > 0) subref
    ) as ChlnDetailsList

  from kaverimrg.ams_reg_khajaneresponselog khj 
	inner join (select officeid,deptreferencecode,remittername,treasurycode, --7 as totalamount -- 
				sum(totalamount) as totalamount
				from kaverimrg.ams_reg_epaymenttransdetails where totalamount>0 group by officeid,deptreferencecode,remittername,treasurycode) epay
		on (epay.deptreferencecode = khj.deptreferencecode)
	-- left join kaverimrg.mas_officemaster mo on (mo.officeid = epay.officeid ) 
	 join kaverimrg.mas_officemaster mo on (mo.kaverimrgcode = epay.officeid and mo.officetypeid = 3) 
	-- left join kaverimrg.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
	 join kaverimrg.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
	
  where khj.deptreferencecode = v_deptrefcode 
) app_json ;

	RETURN v_data_json;
   END;
$$;


ALTER FUNCTION kaverimrg.fn_save_paymentdetails_prod(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentgateway(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS TABLE(deptreferencecode character varying, applicationnumber character varying, applicationtypeid integer, applicationtype character varying, srocode integer, sronamee character varying, presentername text)
    LANGUAGE plpgsql
    AS $$
Declare
--v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
v_applicationtypeid int;
v_citizenid bigint;
v_applicationnumber character varying;
v_exemptamount bigint;
v_deptrefcodeexits bigint;
v_paystatuscode character varying;
begin

select a.applicationtypeid,a.citizenid,a.applicationnumber,a.srocode into v_applicationtypeid,  v_citizenid,  v_applicationnumber
from kaverimrg.ams_reg_epaymenttransdetails r
join kaverimrg.applicantapplicationdetails a on a.applicationnumber=r.applicationnumber
where r.deptreferencecode=_deptreferencecode;

select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemptamount 
from kaverimrg.feesrequired f where f.applicationnumber = v_applicationnumber and f.feerulecode in ('104', '88','89');

if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') 
then



insert into kaverimrg.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
												  

	if (_paymentstatuscode = '10700066') then
		v_amount = _amount;
	
		/* for upd_amnt_row in (select a.chlnrefnum,a.totalamount,a.deptreferencecode
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a
							 where a.deptreferencecode = _deptreferencecode and totalamount>0 
							order by totalamount)
			*/				
					--24/05/2023 bankackdetails Update only on Payment Success; In case of Pending Payments, isdelete flag continues to be false		
		
							
		for upd_amnt_row in ( select b.feerulecode, b.documentid , a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a 
						  join kaverimrg.ams_reg_epaymenttransdetails b on a.deptreferencecode = b.deptreferencecode and a.chlnrefnum  = b.chlnrefnum
						where a.totalamount > 0 and a.deptreferencecode = _deptreferencecode
						order by totalamount
					) loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaverimrg.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
				update kaverimrg.feesrequired a
				set paymentstatus = 'Online Success',amountpaid =(case when feerulecode=36 then v_paidamount+v_exemptamount else v_paidamount end )
				where a.applicationnumber =  upd_amnt_row.applicationnumber
				and documentid = upd_amnt_row.documentid 
				and feerulecode = upd_amnt_row.feerulecode ;
				

				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;
		
		
		if (v_applicationtypeid=1 or v_applicationtypeid=2)
		then 
			update kaverimrg.applicantapplicationdetails a set currentstatus= 'CD107' 
			where a.applicationnumber=v_applicationnumber;
		elsif (v_applicationtypeid=4)
		then 
		perform kaverimrg.fn_update_marriageregistartion_status(v_applicationnumber);
		elsif(v_applicationtypeid =12)
		then 
			perform kaverimrg.fn_update_ccapplicantdetails(v_applicationnumber,v_citizenid,'update');
		elsif (v_applicationtypeid=13)
		then
			perform kaverimrg.fn_update_ecapplicantdetails(v_applicationnumber,v_citizenid,'update');
		end if;

		elsif (_paymentstatuscode not in ('10700092','10700070'))
		then
		update kaverimrg.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=_deptreferencecode;
		--end if;
		
	end if;
	

end if;

return query

select distinct a.deptreferencecode,a.applicationnumber,b.applicationtypeid,e.servicename as applicationtype,
b.srocode,d.sronamee,
f.descriptione||' '||c.firstname||' '||c.middlename||' '||c.lastname as presentername
from 
	kaverimrg.ams_reg_epaymentamtpaiddetails a 
left join
	kaverimrg.applicantapplicationdetails b
on a.applicationnumber = b.applicationnumber
left join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber and 
			b.srocode = c.srocode and ispresenter=true
left join kaverimrg.sromaster d on c.srocode = d.srocode
left join kaverimrg.servicesmaster e on b.applicationtypeid = e.serviceid
left join kaverimrg.salutationmaster f on c.salutationid = f.salutationid
where a.deptreferencecode = _deptreferencecode;
--

   END;
  
$$;


