		then 
		perform kaverimrg.fn_update_marriageregistartion_status(v_applicationnumber);
		elsif(v_applicationtypeid =12)
		then 
			perform kaverimrg.fn_update_ccapplicantdetails(v_applicationnumber,v_citizenid,'update');
		elsif (v_applicationtypeid=13)
		then
			perform kaverimrg.fn_update_ecapplicantdetails(v_applicationnumber,v_citizenid,'update');
		
		end if;
	else 
		--epaymenttransactiondetail with isdelete =true 
		update kaverimrg.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=_deptreferencecode;
		
	end if;
	

end if;
return _deptreferencecode;

   END;
$$;


ALTER FUNCTION kaverimrg.fn_save_paymentgateway_27062023(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentgateway_300623(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_paymentgateway_300623(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare
--v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
v_applicationtypeid int;
v_citizenid bigint;
v_applicationnumber character varying;
v_exemptamount bigint;
v_deptrefcodeexits bigint;
v_paystatuscode character varying;
begin

select a.applicationtypeid,a.citizenid,a.applicationnumber into v_applicationtypeid,  v_citizenid,  v_applicationnumber
from kaverimrg.ams_reg_epaymenttransdetails r
join kaverimrg.applicantapplicationdetails a on a.applicationnumber=r.applicationnumber
where deptreferencecode=_deptreferencecode;

select coalesce(abs(sum(coalesce(amountpaid,0))),0) into v_exemptamount 
from kaverimrg.feesrequired f where f.applicationnumber = v_applicationnumber and f.feerulecode in ('104', '88','89');

if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') 
then



insert into kaverimrg.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
												  

	if (_paymentstatuscode = '10700066') then
		v_amount = _amount;
	
		/* for upd_amnt_row in (select a.chlnrefnum,a.totalamount,a.deptreferencecode
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a
							 where a.deptreferencecode = _deptreferencecode and totalamount>0 
							order by totalamount)
			*/				
					--24/05/2023 bankackdetails Update only on Payment Success; In case of Pending Payments, isdelete flag continues to be false		
		
							
		for upd_amnt_row in ( select b.feerulecode, b.documentid , a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a 
						  join kaverimrg.ams_reg_epaymenttransdetails b on a.deptreferencecode = b.deptreferencecode and a.chlnrefnum  = b.chlnrefnum
						where a.totalamount > 0 and a.deptreferencecode = _deptreferencecode
						order by totalamount
					) loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaverimrg.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
				update kaverimrg.feesrequired a
				set paymentstatus = 'Online Success',amountpaid =(case when feerulecode=36 then v_paidamount+v_exemptamount else v_paidamount end )
				where a.applicationnumber =  upd_amnt_row.applicationnumber
				and documentid = upd_amnt_row.documentid 
				and feerulecode = upd_amnt_row.feerulecode ;
				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;

			
		if (v_applicationtypeid=1 or v_applicationtypeid=2)
		then 
			update kaverimrg.applicantapplicationdetails set currentstatus= 'CD107' 
			where applicationnumber=v_applicationnumber;
		elsif (v_applicationtypeid=4)
		then 
		perform kaverimrg.fn_update_marriageregistartion_status(v_applicationnumber);					   
	   
																			
		elsif(v_applicationtypeid =12)
		then 
			perform kaverimrg.fn_update_ccapplicantdetails(v_applicationnumber,v_citizenid,'update');
		elsif (v_applicationtypeid=13)
		then
			perform kaverimrg.fn_update_ecapplicantdetails(v_applicationnumber,v_citizenid,'update');
  
		end if;

		elsif (_paymentstatuscode not in ('10700092','10700070'))
		then
		update kaverimrg.ams_reg_epaymenttransdetails set isdelete=true where deptreferencecode=_deptreferencecode;
		--end if;
		
	end if;
	

end if;

return _deptreferencecode;
--
exception
when UNIQUE_VIOLATION then

	return _deptreferencecode;
   END;
  
$$;


