--
-- Name: fn_save_paymentgateway_backup_06_apr(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_paymentgateway_backup_06_apr(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
