join kaverimrg.applicantapplicationdetails a on a.applicationnumber=r.applicationnumber
where deptreferencecode=_deptreferencecode;

if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') 
then

insert into kaverimrg.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
--returning deptreferencecode into v_deptrefcode;
	if (_paymentstatuscode = '10700066') then
		v_amount = _amount;
	
		/* for upd_amnt_row in (select a.chlnrefnum,a.totalamount,a.deptreferencecode
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a
							 where a.deptreferencecode = _deptreferencecode and totalamount>0 
							order by totalamount)
			*/				
							
							
		for upd_amnt_row in ( select b.feerulecode, b.documentid , a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a 
						  join kaverimrg.ams_reg_epaymenttransdetails b on a.deptreferencecode = b.deptreferencecode and a.chlnrefnum  = b.chlnrefnum
						where a.totalamount > 0 and a.deptreferencecode = _deptreferencecode
						order by totalamount
					) loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaverimrg.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
				update kaverimrg.feesrequired a
				set paymentstatus = 'Online Success'
				where a.applicationnumber =  upd_amnt_row.applicationnumber
				and documentid = upd_amnt_row.documentid 
				and feerulecode = upd_amnt_row.feerulecode ;
				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;

			
			if (v_applicationtypeid=2)
			then 
				update kaverimrg.applicantapplicationdetails set currentstatus= 'CD107' 
				where applicationnumber=v_applicationnumber;
			elsif(v_applicationtypeid =12)
			then 
				perform kaverimrg.fn_update_ccapplicantdetails(v_applicationnumber,v_citizenid,'update');
			elsif (v_applicationtypeid=13)
			then
				perform kaverimrg.fn_update_ecapplicantdetails(v_applicationnumber,v_citizenid,'update');
			end if;
	end if;
	

end if;
return v_deptrefcode;

   END;
$$;


ALTER FUNCTION kaverimrg.fn_save_paymentgateway_backup_06_apr(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO postgres;

--
-- Name: fn_save_paymentgateway_backup_30_03_2023(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_paymentgateway_backup_30_03_2023(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS TABLE(deptreferencecode character varying, applicationnumber character varying, applicationtypeid integer, applicationtype character varying, srocode integer, sronamee character varying, presentername text)
    LANGUAGE plpgsql
    AS $$
Declare
v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
begin
if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') then

insert into kaverimrg.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
--returning deptreferencecode into v_deptrefcode;
	if (_paymentstatuscode = '10700066') then
		v_amount = _amount;
	
		/* for upd_amnt_row in (select a.chlnrefnum,a.totalamount,a.deptreferencecode
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a
							 where a.deptreferencecode = _deptreferencecode and totalamount>0 
							order by totalamount)
			*/				
							
							
	for upd_amnt_row in (	 select  
b.feerulecode, b.documentid ,
a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a 
						  join 
						       kaverimrg.ams_reg_epaymenttransdetails b 
							 on a.deptreferencecode = b.deptreferencecode 						 
							 and a.chlnrefnum  = b.chlnrefnum
							 where a.totalamount > 0   
							and a.deptreferencecode = _deptreferencecode
						order by totalamount
					)
						
						
						
		loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaverimrg.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
			update kaverimrg.feesrequired a
			set 
				paymentstatus = 'Online Success'
			where  
			    a.applicationnumber =  upd_amnt_row.applicationnumber
			and documentid = upd_amnt_row.documentid 
			and feerulecode = upd_amnt_row.feerulecode ;
		 
				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;	
	end if;

end if;
--return v_deptrefcode;
return query

select distinct a.deptreferencecode,a.applicationnumber,b.applicationtypeid,e.servicename as applicationtype,
b.srocode,d.sronamee,
f.descriptione||' '||c.firstname||' '||c.middlename||' '||c.lastname as presentername
from 
	kaverimrg.ams_reg_epaymentamtpaiddetails a 
left join
	kaverimrg.applicantapplicationdetails b
on a.applicationnumber = b.applicationnumber
left join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber and 
			b.srocode = c.srocode and ispresenter=true
left join kaverimrg.sromaster d on c.srocode = d.srocode
left join kaverimrg.servicesmaster e on b.applicationtypeid = e.serviceid
left join kaverimrg.salutationmaster f on c.salutationid = f.salutationid
where a.deptreferencecode = _deptreferencecode;

   END;
$$;


