				-- To update the Fees paid status 
				update kaverimrg.feesrequired a
				set paymentstatus = 'Online Success',amountpaid =(case when feerulecode=36 then v_paidamount+v_exemptamount else v_paidamount end )
				where a.applicationnumber =  upd_amnt_row.applicationnumber
				and documentid = upd_amnt_row.documentid 
				and feerulecode = upd_amnt_row.feerulecode ;
				

				
				v_amount = v_amount-v_paidamount;
			end if;			
		end loop;
		
		select  * into v_receiptidcnt from kaverimrg.fn_updatefetch_receipt_paid_details(v_applicationnumber,v_srocode) ;
		if (array_length(v_receiptidcnt,1)=0) then 
