ALTER FUNCTION kaverimrg.fn_save_paymentgateway_test(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO postgres;

--
-- Name: fn_save_pending_paymentdetails(character varying, character varying, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_pending_paymentdetails(_applicationnumber character varying, _challennumber character varying, _challendate timestamp without time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
Declare
v_appnumber text;
v_nomenclature character varying (50);
v_serial character varying (50);
v_deptrefcode character varying (50);
v_subdeptrefcode character varying (50);
v_transactionid character varying (50);

pmnt_row record;
subref_row record;
v_data_json json;
v_cnt bigint ;
v_nomen character varying (50);
v_serialno character varying (50);
v_transactid character varying (50);
begin

v_deptrefcode := _challennumber;

v_nomenclature :='IG'||to_char(now(),'MM')||''||to_char(now(),'YY');

select lpad(nextval('kaverimrg.deptreferencecode_seq')::text,8,'0') into v_serial ;
v_transactionid:=v_nomenclature||v_serial;

		select count(*) into v_cnt from kaverimrg.feesrequired where applicationnumber=_applicationnumber;
		if (v_cnt > 0) then
		
		for pmnt_row in (select distinct app.applicationnumber,fm.prpsnamehead 
				 from kaverimrg.applicantapplicationdetails app
					inner join kaverimrg.feesrequired fees on fees.applicationnumber = app.applicationnumber 
					left join kaverimrg.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
					where app.applicationnumber = _applicationnumber AND fm.prpsnamehead IS NOT NULL)

loop 
	v_deptrefcode := _challennumber ;
--	v_deptrefcode :=v_nomenclature||pmnt_row.prpsnamehead||v_serial;
	
	insert into kaverimrg.ams_reg_khajaneresponselog (deptreferencecode,applicationnumber,transactionid,datetimestamp)
	values (v_deptrefcode,_applicationnumber,v_transactid,current_timestamp) ;
	
	for subref_row in (select app.applicationnumber,fees.feerulecode, fees.amountpaid,
					fm.feerulename, fm.deptpurposeid, fm.accntheadname, fm.prpsname, 
					fm.trsrycode,fm.prpsnamehead,app.srocode,fm.subrefcode,
					   concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS remittername ,
					   fees.documentid ,  fees.feerulecode
					   from 
					   kaverimrg.applicantapplicationdetails app 
					   inner join kaverimrg.feesrequired fees on app.applicationnumber = fees.applicationnumber 
					   and coalesce(fees.amountpaid,0)>0
					 --  left join kaverimrg.feesrequired fees_def on 
					  -- (app.applicationnumber = fees_def.applicationnumber 
						--	 and fees_def.feerulecode='35')
					   left join kaverimrg.citizenmaster cm on (app.citizenid = cm.citizenid)
			left join kaverimrg.vw_feesrule_mapping fm on  fees.feerulecode = fm.feerulecode
			where fees.applicationnumber = _applicationnumber  and fm.prpsnamehead=pmnt_row.prpsnamehead
					   and fees.paymentstatus='Pending'
					group by  app.applicationnumber,fees.feerulecode, fm.feerulename, 
					   fm.deptpurposeid, fm.accntheadname, fm.prpsname, fm.subrefcode,
			fm.trsrycode,fm.prpsnamehead,app.srocode,cm.firstname, cm.middlename, cm.lastname,
				fees.amountpaid,fees.documentid ,  fees.feerulecode
			)
	
		loop		
		v_subdeptrefcode:=v_deptrefcode||UPPER(subref_row.subrefcode);
	
	insert into kaverimrg.ams_reg_epaymentamtpaiddetails(
	chlnrefnum, deptpurposeid, headofaccount, totalamount,amountpaid, applicationnumber, deptreferencecode)
	values(v_subdeptrefcode,subref_row.deptpurposeid,subref_row.prpsname, subref_row.amountpaid,
	subref_row.amountpaid,  _applicationnumber, v_deptrefcode) ;
	
		INSERT INTO kaverimrg.ams_reg_epaymenttransdetails
		( officeid, remittername, totalamount, chlnrefnum, 
	deptreferencecode,  applicationnumber,treasurycode, documentid ,feerulecode  )
	values(subref_row.srocode,subref_row.remittername,subref_row.amountpaid,
	v_subdeptrefcode,v_deptrefcode,_applicationnumber,subref_row.trsrycode, subref_row.documentid  ,
	subref_row.feerulecode ) ;
	

		end loop;
	
    end loop;
	end if;

/* =====================Generation of Json begins here ==================== */
select row_to_json(app_json) into v_data_json
from (
  select khj.deptreferencecode,khj.applicationnumber,khj.datetimestamp, 
	epay.officeid,epay.remittername,epay.treasurycode,
	 epay.totalamount,
	ddo.ddocode,'33E' AS deptrefcode,
     (
      select array_to_json(array_agg(row_to_json(subref)))
      from (select deptreferencecode,chlnrefnum, deptpurposeid, headofaccount as prpsname, --1 as amount
			abs(totalamount) as amount
			from kaverimrg.ams_reg_epaymentamtpaiddetails sub_ref
			where sub_ref.deptreferencecode = khj.deptreferencecode and totalamount > 0) subref
    ) as ChlnDetailsList

  from kaverimrg.ams_reg_khajaneresponselog khj 
	inner join (select officeid,deptreferencecode,remittername,treasurycode, --7 as totalamount -- 
				sum(totalamount) as totalamount
				from kaverimrg.ams_reg_epaymenttransdetails group by officeid,deptreferencecode,remittername,treasurycode) epay
		on (epay.deptreferencecode = khj.deptreferencecode)
	left join kaverimrg.mas_officemaster mo on (mo.officeid = epay.officeid ) 
	left join kaverimrg.mas_ams_khajaneddocodemapping ddo on (ddo.srocode = epay.officeid)
  where khj.deptreferencecode = v_deptrefcode 
) app_json ;

	RETURN v_data_json;
   END;
$$;


ALTER FUNCTION kaverimrg.fn_save_pending_paymentdetails(_applicationnumber character varying, _challennumber character varying, _challendate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_save_pending_paymentgateway(character varying, bigint, character varying, character varying, character varying, character varying, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_pending_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) RETURNS TABLE(deptreferencecode character varying, applicationnumber character varying, applicationtypeid integer, applicationtype character varying, srocode integer, sronamee character varying, presentername text)
    LANGUAGE plpgsql
    AS $$
Declare
v_deptrefcode character varying(100);
v_amount bigint;
v_paidamount bigint;
upd_amnt_row record;
begin
if (_deptreferencecode is not null and coalesce(_deptreferencecode,'') <> '') then

insert into kaverimrg.ams_reg_epaymentbankackdetails(deptreferencecode, banktransactionnumber, bankname, paymentmode, 
												   paymentstatuscode, transactiontimestamp, amount, checksum) 
values (_deptreferencecode, _banktransactionnumber, _bankname, _paymentmode, 
												   _paymentstatuscode, _transactiontimestamp, _amount, _checksum);
--returning deptreferencecode into v_deptrefcode;
	if (_paymentstatuscode = '10700066') then
		v_amount = _amount;
							
	for upd_amnt_row in (	 select  
b.feerulecode, b.documentid ,
a.chlnrefnum,a.totalamount,a.deptreferencecode , b.applicationnumber
						 from kaverimrg.ams_reg_epaymentamtpaiddetails a 
						  join 
						       kaverimrg.ams_reg_epaymenttransdetails b 
							 on a.deptreferencecode = b.deptreferencecode 						 
							 and a.chlnrefnum  = b.chlnrefnum
							 where a.totalamount > 0   
							and a.deptreferencecode = _deptreferencecode
						order by totalamount
					)
						
						
						
		loop 
			if(v_amount > 0) then
				v_paidamount = upd_amnt_row.totalamount;			
				if (v_amount > 0 and v_amount < v_paidamount) then
					v_paidamount:=v_amount;
				end if;				
				
				update kaverimrg.ams_reg_epaymentamtpaiddetails a  
				set amountpaid = v_paidamount
				where chlnrefnum = upd_amnt_row.chlnrefnum and 
				a.deptreferencecode = upd_amnt_row.deptreferencecode ;
				
				
				-- To update the Fees paid status 
			update kaverimrg.feesrequired a
			set 
				paymentstatus = 'Challan Success'
			where  
			    a.applicationnumber =  upd_amnt_row.applicationnumber
			and documentid = upd_amnt_row.documentid 
			and feerulecode = upd_amnt_row.feerulecode ;
		 
		 v_amount = v_amount-v_paidamount;
			end if;			
		end loop;	
	end if;

end if;
--return v_deptrefcode;
return query

select distinct a.deptreferencecode,a.applicationnumber,b.applicationtypeid,e.servicename as applicationtype,
b.srocode,d.sronamee,
f.descriptione||' '||c.firstname||' '||c.middlename||' '||c.lastname as presentername
from 
	kaverimrg.ams_reg_epaymentamtpaiddetails a 
left join
	kaverimrg.applicantapplicationdetails b
on a.applicationnumber = b.applicationnumber
left join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber and 
			b.srocode = c.srocode and ispresenter=true
left join kaverimrg.sromaster d on c.srocode = d.srocode
left join kaverimrg.servicesmaster e on b.applicationtypeid = e.serviceid
left join kaverimrg.salutationmaster f on c.salutationid = f.salutationid
where a.deptreferencecode = _deptreferencecode;

   END;
$$;


ALTER FUNCTION kaverimrg.fn_save_pending_paymentgateway(_banktransactionnumber character varying, _amount bigint, _deptreferencecode character varying, _paymentstatuscode character varying, _bankname character varying, _paymentmode character varying, _transactiontimestamp timestamp without time zone, _checksum character varying) OWNER TO postgres;

--
-- Name: fn_save_post_in_office(integer, integer, text, integer, integer, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_post_in_office(_createdby integer, _designationid integer, _postdescription text, _officetypeid integer, _officeid integer, _supportingdocpath text) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

v_postid integer;
v_count integer;

BEGIN 
	
	select count(*) into v_count from  kaverimrg.post_office_details where 
	officeid=_officeid and designationid=_designationid and officetypeid=_officetypeid;
	
	if v_count>0 then 
	  
		v_postid=0;
	ELSE
	
	 insert into kaverimrg.post_office_details(createdby,postid,designationid,postdescription,officetypeid,officeid,supportingdocpath)
	 values(_createdby,nextval('kaverimrg.postid_seq'::regclass),_designationid,_postdescription,_officetypeid,_officeid,_supportingdocpath)
	 returning postid into v_postid;
	 
	 end if;
	 
	 return v_postid;

	

END;

$$;


