--

CREATE TABLE kaverimrg.rescandetails_input (
    documentid bigint,
    documenttypeid integer,
    backuppath character varying,
    filename character varying
);


ALTER TABLE kaverimrg.rescandetails_input OWNER TO postgres;

--
-- Name: fn_save_rescandetails(kaverimrg.rescandetails_input[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_save_rescandetails(kaverimrg.rescandetails_input[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$
DECLARE
   id_val bigint;
   fees_arry $1%type;
    v_txt text;
   v_documentid bigint;
   v_cnt integer;
   var_r record;
   v_pid bigint[];
BEGIN
  FOR fees_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray($1))
     loop
	 
   Select count(*) into v_cnt from kaverimrg.rescandetails where (coalesce(documentid,0)) in 
(select coalesce(a.documentid,0) from unnest(fees_arry) a);

  if v_cnt = 0 then
INSERT INTO kaverimrg.rescandetails(
	documentid,
	documenttypeid,
	backuppath,
    filename,
	istransmitted,
	isuploaded
) select 
	documentid,
	documenttypeid,
	backuppath,
    filename,
	True,
	True
 from unnest(fees_arry)						 
    RETURNING documentid::bigint into id_val;
	else
update kaverimrg.rescandetails set
	documentid=a.documentid,
	documenttypeid=a.documenttypeid,
	backuppath=a.backuppath,
    filename=a.filename
	from unnest(fees_arry) a
	where coalesce(documentid,0) in 
   (select coalesce(a.documentid,0) from unnest(fees_arry) a) 
RETURNING documentid::bigint into id_val;
    end if;
	 v_pid := array_append(v_pid,id_val);
    end loop;
	return v_pid;
end;
$_$;


ALTER FUNCTION kaverimrg.fn_save_rescandetails(kaverimrg.rescandetails_input[]) OWNER TO postgres;

