--
-- Name: fn_sro_approval(integer, timestamp without time zone, character varying, text, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_sro_approval(_srocode integer, _executiondatetime timestamp without time zone, _applicationnumber character varying, _deedattachpath text, _annexurepath text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

declare
v_applicationnumber character varying;
v_documentid bigint;
v_cnt integer;
v_bookid integer;
v_regarticlecode integer;
v_pagecount integer;
_movable boolean default true;
--_vararry bigint;
_minval int;
v_movableproperty boolean;
v_stampruleid bigint;
_varbookid bigint;
v_stamparticlecode integer;
v_feecount integer;
v_isgricnt int;
v_jsrocode bigint;
v_propertyids bigint;
begin
begin

select documentid into v_documentid from kaverimrg.documentmaster where applicationnumber = _applicationnumber limit 1;
exception when no_data_found then
	v_documentid = 0;
end;


select stamparticlecode into v_stamparticlecode from kaverimrg.propertymaster
where applicationnumber =_applicationnumber;
	
if (v_stamparticlecode = 14) then
	select bookid into v_bookid from kaverimrg.k1documentdetails where applicationnumber = _applicationnumber ;

	if (v_bookid is null) then 
		for v_movableproperty,v_stampruleid,v_regarticlecode  --, v_stamparticlecode
			in select ismovableproperty,stampruleid,regarticlecode  --, stamparticlecode
			from kaverimrg.propertymaster where applicationnumber =_applicationnumber loop

			if(v_movableproperty=false) then
				_movable = false;
			end if;
			select bookid into _varbookid from kaverimrg.stamprules where stampruleid=v_stampruleid ;
	--		_vararry=_varbookid;
		end loop;
		select min(bookid) into _minval from kaverimrg.stamprules where stampruleid=v_stampruleid;
		if(_movable=True and _minval=1) then
			v_bookid=4;
		else 
			v_bookid=_minval;
		end if;
	end if;
else 
	for v_movableproperty,v_stampruleid,v_regarticlecode  --, v_stamparticlecode
		in select ismovableproperty,stampruleid,regarticlecode  --, stamparticlecode
		from kaverimrg.propertymaster where applicationnumber =_applicationnumber loop

		if(v_movableproperty=false) then
			_movable = false;
		end if;
		select bookid into _varbookid from kaverimrg.stamprules where stampruleid=v_stampruleid ;
--		_vararry=_varbookid;
	end loop;
	select min(bookid) into _minval from kaverimrg.stamprules where stampruleid=v_stampruleid;
	if(_movable=True and _minval=1)
	then
		v_bookid=4;
	else 
		v_bookid=_minval;
	end if;
end if;

	
if (v_documentid = 0  or v_documentid is null)  then

	select distinct  pm.regarticlecode, pm.noofscanpages into v_regarticlecode,v_pagecount 
	from kaverimrg.propertymaster pm inner join kaverimrg.registrationarticles ra on (ra.regarticlecode = pm.regarticlecode)
		where pm.applicationnumber = _applicationnumber limit 1;
	
	insert into kaverimrg.documentmaster
	 (  documentid,srocode, bookid,regarticlecode,
		 executiondatetime,pagecount,applicationnumber
	 ) values ( nextval('kaverimrg.document_seq'),
	 _srocode,v_bookid,v_regarticlecode,
	 _executiondatetime,v_pagecount,_applicationnumber ) returning documentid into v_documentid;
	 
	 if not found then 
		raise exception 'Something went wrong! DocumentMaster insertion failed.'; 
	end if;
	  
	update kaverimrg.applicantapplicationdetails set regarticlecode=coalesce(regarticlecode,v_regarticlecode) 
	where applicationnumber = _applicationnumber ;
	if not found then 
		raise exception 'Something went wrong! ApplicantApplicationDetails updation failed.'; 
	end if;
else
	update kaverimrg.documentmaster set
	srocode= _srocode, 
	executiondatetime=_executiondatetime 
	where applicationnumber=_applicationnumber
	returning documentid into v_documentid;
 end if; 

update kaverimrg.partyinfo set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber ; 
if not found then 
	raise exception 'Something went wrong! PartyInfo updation failed.'; 
end if;

update kaverimrg.propertymaster set documentid = v_documentid,regsrocode=_srocode where applicationnumber = _applicationnumber ;
if not found then 
	raise exception 'Something went wrong! PropertyMaster updation failed.'; 
end if;

--select count(*) into v_isgricnt from kaverimrg.propertymaster p where propertytypeid =17 and applicationnumber = _applicationnumber;

select count(*) into v_isgricnt from kaverimrg.propertymaster p 
join kaverimrg.stamprulesflag s on p.stampruleid = s.stampruleid
where propertytypeid =17 and s.isprevregddocnoreqd = false and applicationnumber = _applicationnumber;


if (v_isgricnt>0)
then
update kaverimrg.orgdatajslip set documentid=v_documentid where applicationnumber = _applicationnumber ;
if not found then 
	raise exception 'Something went wrong! OrgDataJslip updation failed.'; 
end if;
end if;


for v_propertyids,v_jsrocode in (select propertyid,srocode from kaverimrg.propertymaster where applicationnumber=_applicationnumber)
loop
update kaverimrg.propertyschedules set srocode=v_jsrocode where propertyid = v_propertyids;
end loop;
-- need to uncomment the srocode update once the functionality is present 
update kaverimrg.witnessinfo set documentid = v_documentid, srocode=_srocode where applicationnumber = _applicationnumber ;

-- partywitness need to be updated with the same srocode during document for approval
update kaverimrg.partywitness set srocode = _srocode where witnessid in 
(select witnessid from kaverimrg.witnessinfo where applicationnumber = _applicationnumber);

select count(*) into v_feecount from kaverimrg.feesrequired where applicationnumber=_applicationnumber; 
if v_feecount>0 then
	update kaverimrg.feesrequired set documentid = v_documentid,srocode=_srocode where applicationnumber = _applicationnumber ;
	if not found then 
		raise exception 'Something went wrong! FeesRequired updation failed.'; 
	end if;
end if;
 --srocode update should be removed later
update kaverimrg.mojanixml set documentid = v_documentid,srocode=_srocode where propertyid in (select propertyid from kaverimrg.propertymaster
where applicationnumber = _applicationnumber) ;

update kaverimrg.bhoomixmllog set documentid = v_documentid,srocode=_srocode where propertyid in (select propertyid from kaverimrg.propertymaster
where applicationnumber = _applicationnumber) ;
 
update kaverimrg.applicantapplicationdetails set currentstatus = 'CD102'
,bookid=v_bookid,regarticlecode= v_regarticlecode
,regsrocode=_srocode,srocode=_srocode,issubmitted=true,isduecorrection=false
,deedattachpath=_deedattachpath,annexurepath=_annexurepath
,APPLICATIONDATE = current_timestamp,lastupdatedby=citizenid::text where applicationnumber = _applicationnumber;



--end if;
return v_documentid;
end;
$$;


ALTER FUNCTION kaverimrg.fn_sro_approval(_srocode integer, _executiondatetime timestamp without time zone, _applicationnumber character varying, _deedattachpath text, _annexurepath text) OWNER TO postgres;

--
-- Name: fn_sro_approval(bigint, integer, integer, integer, integer, integer, character varying, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, character varying, boolean, boolean, boolean, boolean, boolean, boolean, boolean, boolean, timestamp without time zone, character varying, character varying, character varying, bigint, character varying, character varying, character varying, boolean, integer, character varying, boolean, boolean, timestamp without time zone, boolean, numeric, numeric, numeric, character varying, character varying, boolean, character varying, text); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_sro_approval(_documentid bigint, _srocode integer, _bookid integer, _stamparticlecode integer, _regarticlecode integer, _documentnumber integer, _finalregistrationnumber character varying, _presentdatetime timestamp without time zone, _executiondatetime timestamp without time zone, _dateofstamp timestamp without time zone, _stamp1datetime timestamp without time zone, _stamp2datetime timestamp without time zone, _stamp3datetime timestamp without time zone, _stamp4datetime timestamp without time zone, _stamp5datetime timestamp without time zone, _withdrawaldate timestamp without time zone, _pagecount integer, _index2shera character varying, _isvisited boolean, _isfiling boolean, _ispending boolean, _isscanned boolean, _isrefused boolean, _ispaymentofmoney boolean, _isadjudicated boolean, _iswithdrawn boolean, _refusaldate timestamp without time zone, _refusalreason character varying, _remarksbyuser character varying, _remarksbysystem character varying, _correctionreference bigint, _olddocreference character varying, _adjudicationdetails character varying, _cdnumber character varying, _isxmltransferredtobhoomi boolean, _uid integer, _pendingdocumentnumber character varying, _istransmitted boolean, _isphotothumbtransmitted boolean, _inserteddatetime timestamp without time zone, _initialtransmitted boolean, _considerationamount numeric, _requiredstampduty numeric, _paidstampduty numeric, _documentstatus character varying, _applicationnumber character varying, _verified boolean, _issroapproved character varying, _deedattachpath text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
_cnt integer;
v_applicationnumber character varying;
v_documentid bigint;
v_cnt integer;
--v_documentid bigint;
--v_cnt integer;
_movable boolean default true;
--_vararry bigint;
_minval int;
v_bookid int;
v_movableproperty boolean;
v_stampruleid bigint;
_varbookid bigint;
v_regarticlecode bigint;
v_feecount integer;
v_jsrocode bigint;
v_propertyids bigint;
begin
	

	for v_movableproperty,v_stampruleid,v_regarticlecode in select ismovableproperty,stampruleid,regarticlecode  from kaverimrg.propertymaster
	where applicationnumber =_applicationnumber
	loop
		if(v_movableproperty=false)
		then
		_movable = false;
		end if;
		select bookid into _varbookid from kaverimrg.stamprules where stampruleid=v_stampruleid ;
--		_vararry=_varbookid;
	end loop;
		 if(_movable=True)
		then
		v_bookid=4;
		else 
		select min(bookid) into _minval from kaverimrg.stamprules where stampruleid=v_stampruleid;
		v_bookid=_minval;
		end if;

select count(*) into v_cnt from kaverimrg.documentmaster where documentid = _documentid;
if v_cnt = 0 then
insert into kaverimrg.documentmaster
 ( 
documentid,
 srocode, 
 bookid, 
 stamparticlecode, 
 regarticlecode, 
 documentnumber, 
 finalregistrationnumber, 
 presentdatetime, 
 executiondatetime, 
 dateofstamp, 
 stamp1datetime, 
 stamp2datetime, 
 stamp3datetime, 
 stamp4datetime, 
 stamp5datetime, 
 withdrawaldate, 
 pagecount, 
 index2shera, 
 isvisited, 
 isfiling, 
 ispending, 
 isscanned, 
 isrefused, 
 ispaymentofmoney, 
 isadjudicated, 
 iswithdrawn, 
 refusaldate, 
 refusalreason, 
 remarksbyuser, 
 remarksbysystem, 
 correctionreference, 
 olddocreference, 
 adjudicationdetails, 
 cdnumber, 
 isxmltransferredtobhoomi, 
 uid, 
 pendingdocumentnumber, 
 istransmitted, 
 isphotothumbtransmitted, 
 inserteddatetime, 
 initialtransmitted, 
 considerationamount, 
 requiredstampduty, 
 paidstampduty, 
 documentstatus, 
 applicationnumber, 
 verified, 
 issroapproved,
 deedattachpath
 ) values (
 nextval('kaverimrg.document_seq'),
 _srocode, 
 v_bookid, 
 _stamparticlecode, 
 v_regarticlecode, 
 _documentnumber, 
 _finalregistrationnumber, 
 _presentdatetime, 
 _executiondatetime, 
 _dateofstamp, 
 _stamp1datetime, 
 _stamp2datetime, 
 _stamp3datetime, 
 _stamp4datetime, 
 _stamp5datetime, 
 _withdrawaldate, 
 _pagecount, 
 _index2shera, 
 _isvisited, 
 _isfiling, 
 _ispending, 
 _isscanned, 
 _isrefused, 
 _ispaymentofmoney, 
 _isadjudicated, 
 _iswithdrawn, 
 _refusaldate, 
 _refusalreason, 
 _remarksbyuser, 
 _remarksbysystem, 
 _correctionreference, 
 _olddocreference, 
 _adjudicationdetails, 
 _cdnumber, 
 _isxmltransferredtobhoomi, 
 _uid, 
 _pendingdocumentnumber, 
 _istransmitted, 
 _isphotothumbtransmitted, 
 _inserteddatetime, 
 _initialtransmitted, 
 _considerationamount, 
 _requiredstampduty, 
 _paidstampduty, 
 _documentstatus, 
 _applicationnumber, 
 _verified, 
 _issroapproved,
 _deedattachpath
  ) returning documentid into v_documentid;
  else
  
  update kaverimrg.documentmaster set
 srocode= _srocode, 
 bookid=v_bookid, 
 stamparticlecode=_stamparticlecode, 
 regarticlecode=v_regarticlecode, 
 documentnumber=_documentnumber, 
 finalregistrationnumber=finalregistrationnumber, 
 presentdatetime=_presentdatetime, 
 executiondatetime=_executiondatetime, 
 dateofstamp=_dateofstamp, 
 stamp1datetime=_stamp1datetime, 
 stamp2datetime=_stamp2datetime, 
 stamp3datetime=_stamp3datetime, 
 stamp4datetime=_stamp4datetime, 
 stamp5datetime=_stamp5datetime, 
 withdrawaldate=_withdrawaldate, 
 pagecount=_pagecount, 
 index2shera=_index2shera, 
 isvisited=_isvisited, 
 isfiling=_isfiling, 
 ispending=_ispending, 
 isscanned=_isscanned, 
 isrefused=_isrefused, 
 ispaymentofmoney=_ispaymentofmoney, 
 isadjudicated=_isadjudicated, 
 iswithdrawn=_iswithdrawn, 
 refusaldate=_refusaldate, 
 refusalreason=_refusalreason, 
 remarksbyuser=_remarksbyuser, 
 remarksbysystem=_remarksbysystem, 
 correctionreference=_correctionreference, 
 olddocreference=_olddocreference, 
 adjudicationdetails=_adjudicationdetails, 
 cdnumber=_cdnumber, 
 isxmltransferredtobhoomi=_isxmltransferredtobhoomi, 
 uid=_uid, 
 pendingdocumentnumber=_pendingdocumentnumber, 
 istransmitted=_istransmitted, 
 isphotothumbtransmitted=_isphotothumbtransmitted, 
 inserteddatetime=_inserteddatetime, 
 initialtransmitted=_initialtransmitted, 
 considerationamount=_considerationamount, 
 requiredstampduty=_requiredstampduty, 
 paidstampduty=_paidstampduty, 
 documentstatus=_documentstatus, 
 applicationnumber=_applicationnumber, 
