--
-- Name: fn_total_revenue_collection(bigint, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_total_revenue_collection(_userid bigint, _from_date character varying, _to_date character varying) RETURNS TABLE(srooffice character varying, droffice character varying, fname text, mname text, lname text, stampduty numeric, registrationfee numeric, otherfee numeric, totalfee numeric)
    LANGUAGE plpgsql
    AS $$

BEGIN	
	return query
select b.sronamee as srooffice,c.districtnamee as droffice,
a.firstname as fname,a.middlename as mname,a.lastname as lname,
sum(feecalculation.stampduty) as stampduty,
sum(feecalculation.registrationfee) as registrationfee,
sum(feecalculation.otherfee) as otherfee,
sum(feecalculation.stampduty) + sum(feecalculation.registrationfee) + sum(feecalculation.otherfee) as Totalfee
from kaverimrg.departmentusers a join kaverimrg.sromaster b on a.srocode = b.srocode
join kaverimrg.districtmaster c on b.districtcode = c.districtcode
join 
(
select srocode,documentid,
	sum(case when feerulecode = 36 then
/* stampduty */
amountpaid else 0 end) as stampduty,
sum(case when feerulecode = 1 then
/* Registrationfee */
	amountpaid else 0 end) as registrationfee,
sum(case when feerulecode = 2 then
/* scanningfee */
amountpaid else 0 end) as scanningfee,
/* otherfee */
sum(case when feerulecode not in (36,1,2) then
amountpaid else 0 end) 
as otherfee	
	from
	kaverimrg.feesrequired 
	group by srocode,documentid
) as feecalculation on feecalculation.srocode = b.srocode
join kaverimrg.documentmaster e on feecalculation.documentid = e.documentid
where e.isregistrationcompleted = true and to_date(to_char(e.registrationdatetime,'yyyy-mm-dd'),'yyyy-mm-dd') >= to_date(_from_date,'yyyy-mm-dd') and
to_date(to_char(e.registrationdatetime,'yyyy-mm-dd'),'yyyy-mm-dd') <= to_date(_to_date,'yyyy-mm-dd') and a.userid = _userid
group by b.sronamee ,c.districtnamee,
firstname,middlename,lastname
;
END;
$$;


ALTER FUNCTION kaverimrg.fn_total_revenue_collection(_userid bigint, _from_date character varying, _to_date character varying) OWNER TO postgres;

--
-- Name: fn_transactionauditlog(); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_transactionauditlog() RETURNS character
    LANGUAGE plpgsql
    AS $$
begin
 --   if tg_op = 'INSERT' then
        
	
		
insert into kaverimrg.TransactionAuditLog
(
pid, databasename  ,username ,app_name ,client_address,state ,wait_event ,blocking_pid ,query ,backend_type ,active_since ,
query_start )

SELECT
    pid,
    datname,
    usename,
    application_name,
    client_addr,
    state,
    wait_event_type || ': ' || wait_event AS wait_event,
    pg_catalog.pg_blocking_pids(pid) AS blocking_pids,
    query,
	backend_type,
	CASE WHEN state = 'active' THEN ROUND((extract(epoch from now() - query_start) / 60)::numeric, 2) ELSE 0 END AS active_since ,
	pg_catalog.to_char(query_start, 'YYYY-MM-DD HH24:MI:SS TZ') AS query_start
FROM
    pg_catalog.pg_stat_activity a 
WHERE  datname = 'kav2igrdevnew' 
--and not exists (select 1 from pg_catalog.pg_stat_activity b where a.pid = b.pid)
and not exists (select 1 from kaverimrg.TransactionAuditLog b where a.pid = b.pid)  
ORDER BY pid;


        return '';
	
    --end if;
end;
$$;


ALTER FUNCTION kaverimrg.fn_transactionauditlog() OWNER TO postgres;

--
-- Name: fn_transfer_dept_user(integer, integer, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_transfer_dept_user(_userid integer, _newofficeid integer, _doj_new_office timestamp without time zone, _designationid integer, _updatedby integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$



DECLARE

v_count integer;
v_success integer;
v_srocode bigint;
v_temp_record record;
v_officetypeid integer;
v_loginname text;
BEGIN 

 select loginname into v_loginname from kaverimrg.departmentusers d where userid=_userid;
SELECT  regexp_replace(v_loginname,'^\d+', '') AS login_name into v_loginname;
  select officetypeid  into v_officetypeid from kaverimrg.mas_officemaster  where officeid=_newofficeid;
  
  if v_officetypeid < 3 then
    select srocode into v_srocode from kaverimrg.sromaster where districtcode=
	(select  districtid from kaverimrg.mas_officemaster mo where officeid=_newofficeid ) limit 1;
  ELSE
	select  kaverimrgcode into v_srocode from kaverimrg.mas_officemaster mo where officeid=_newofficeid;

 end if;

 
  select count(*) into v_count from kaverimrg.departmentusers where userid=_userid;
  if v_count=1 then 
	select * into v_temp_record from kaverimrg.departmentusers where userid=_userid;
	--insert previous service history
	--office1
   select v_srocode||v_loginname into v_loginname;
	update kaverimrg.departmentusers_service_history set isactive=false where userid=_userid;
	insert into kaverimrg.departmentusers_service_history(userid,srocode,designationid,updatedby,officeid,servicestartdate,serviceexpdate,employeetypeid,isactive)
	values(_userid,v_temp_record.srocode,v_temp_record.designationid,_updatedby,v_temp_record.officeid,v_temp_record.doj,current_date,v_temp_record.employeetypeid,true);
   update kaverimrg.departmentusers
   set srocode=v_srocode,doj=_doj_new_office,officeid=_newofficeid,designationid=_designationid,createdby=_updatedby,
   loginname=v_loginname
   where userid=_userid; --office2
   v_success=1;
   
   ELSE
   
   
   v_success=0;
   
   end if;
    
   
 
return v_success;
END;

$$;


ALTER FUNCTION kaverimrg.fn_transfer_dept_user(_userid integer, _newofficeid integer, _doj_new_office timestamp without time zone, _designationid integer, _updatedby integer) OWNER TO postgres;

