--
-- Name: fn_update_amendmenttype_application(character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_amendmenttype_application(_applicationnumber character varying, _amendmenttypeid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
v_cnt integer;	

begin

select count(*) into v_cnt  from kaverimrg.firmamendment f  where applicationnumber=_applicationnumber;
if v_cnt=1 then

  update kaverimrg.firmamendment set amendmenttypeid=_amendmenttypeid
  where   applicationnumber=_applicationnumber;
  if (_amendmenttypeid=1 )	then 
	update kaverimrg.applicantapplicationdetails a
	set currentstatus='FA103'
	where a.applicationnumber=_applicationnumber;

	elsif(_amendmenttypeid=2 )
   then
	update kaverimrg.applicantapplicationdetails a
	set currentstatus='FA104'
	where a.applicationnumber=_applicationnumber;

	elsif(_amendmenttypeid=3 )
   then
	update kaverimrg.applicantapplicationdetails a
	set currentstatus='FA105'
	where a.applicationnumber=_applicationnumber;

	elsif(_amendmenttypeid=4)
   then
	update kaverimrg.applicantapplicationdetails a
	set currentstatus='FA106'
	where a.applicationnumber=_applicationnumber;
	end if;
	RETURN _applicationnumber;
	

else
   RETURN null;
 
end if;
end
$$;


ALTER FUNCTION kaverimrg.fn_update_amendmenttype_application(_applicationnumber character varying, _amendmenttypeid integer) OWNER TO postgres;

--
-- Name: fn_update_anywhere_reg(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_anywhere_reg(_applicationnumber character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
v_cnt integer := 0;
unjurisdictional_prop_cnt integer := 0;
is_reg_complete boolean := false;
rw record;
v_jdistrictcode int;
v_rdistrictcode int;
BEGIN	

select isregistrationcompleted into is_reg_complete 
from kaverimrg.documentmaster d where d.applicationnumber=_applicationnumber;

if(is_reg_complete = true) then
	select count(*) into v_cnt from kaverimrg.propertymaster p 
	where p.applicationnumber = _applicationnumber;
		
	if(v_cnt>0) then
		for rw in (select pm.documentid, pm.applicationnumber, pm.propertyid, pm.regsrocode, pm.srocode,pm.ismovableproperty,pm.villagecode from kaverimrg.propertymaster pm where pm.applicationnumber=_applicationnumber) loop
			if(rw.srocode != rw.regsrocode and (rw.ismovableproperty=false or rw.ismovableproperty is null)) then
				
				select districtcode into v_jdistrictcode from kaverimrg.sromaster where srocode in (rw.srocode);
				select districtcode into v_rdistrictcode from kaverimrg.sromaster where srocode in (rw.regsrocode);
				if( (v_rdistrictcode not in (35,36,1,34,33)) or
					(v_jdistrictcode<>v_rdistrictcode and  v_rdistrictcode in (35,36,1,34,33))) --district not bangalore revenue districts
				then
				insert into kaverimrg.anywhere_reg_log(documentid, applicationnumber, propertyid, regsrocode, srocode, ismemosent, isjurisdictionsroaccepted)
				values (rw.documentid, _applicationnumber, rw.propertyid, rw.regsrocode, rw.srocode, false, false);
				unjurisdictional_prop_cnt = unjurisdictional_prop_cnt + 1;
				end if;
			end if;
		end loop;
	end if;
end if;

return unjurisdictional_prop_cnt;
end;
$$;


ALTER FUNCTION kaverimrg.fn_update_anywhere_reg(_applicationnumber character varying) OWNER TO postgres;

