--
-- Name: fn_update_dr_approved_amendments(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_dr_approved_amendments(_applicationnumber character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare
v_check boolean;
v_applicationtype int;
v_applicationstatus varchar(50);
v_registrationid bigint;
v_branchrecord record;
v_isremoved boolean;
--v_registrationid_branch bigint;
v_applicationnumber character varying;
v_branchid bigint;
v_partyrecord record;
--v_registrationid_party bigint;
v_minorrecord record;

begin

select amendmenttypeid into v_applicationtype from kaverimrg.firmamendment f where applicationnumber = _applicationnumber;

select currentstatus into v_applicationstatus from kaverimrg.applicantapplicationdetails a where applicationnumber = _applicationnumber;

if(v_applicationstatus = 'FA122') then

	if(v_applicationtype = 1)then
	
		select registrationid into v_registrationid from kaverimrg.firmmaster f 
		where finalregistrationnumber in (select finalregistrationnumber from kaverimrg.firmamendment f2 where applicationnumber=_applicationnumber);
		
		update kaverimrg.firmmaster
		set firmname = a.firmname,
			housebuildingname = a.amendhousebuildingname,
			streetaddress = a.amendstreetaddress,
			statecode = a.amendstatecode,
			districtcode = a.amenddistrictcode,
			talukacode = a.amendtalukacode,
			hoblicode = a.amendhoblicode,
			cityvillagecode = a.amendcityvillagecode,
			pincode = a.amendpincode
		from (select * from kaverimrg.firmamendment where applicationnumber = _applicationnumber) a
		where registrationid = v_registrationid 
		returning true into v_check;
		
	elsif(v_applicationtype = 2)then 
		
		for v_branchrecord in (select amendmentbranchid from kaverimrg.amendmentfirmbranches a where applicationnumber = _applicationnumber)
		loop
			
			select branchid into v_branchid from kaverimrg.amendmentfirmbranches where amendmentbranchid in (v_branchrecord.amendmentbranchid);
			
			select isremoved  into v_isremoved from kaverimrg.amendmentfirmbranches a2
			where applicationnumber = _applicationnumber and amendmentbranchid in (v_branchrecord.amendmentbranchid);
			
			select registrationid into v_registrationid from kaverimrg.firmmaster f
			where finalregistrationnumber in (select finalregistrationnumber from kaverimrg.firmamendment f2 where applicationnumber= _applicationnumber);
		
			select applicationnumber into v_applicationnumber from kaverimrg.firmmaster f
			where finalregistrationnumber in (select finalregistrationnumber from kaverimrg.firmamendment f2 where applicationnumber= _applicationnumber);
			
			if v_isremoved = false then
				insert into kaverimrg.firmbranches(
					branchid,
					registrationid,
					applicationnumber,
					branchhousebuildingname,
					branchstreetaddress,
					branchstatecode,
					branchdistrictcode,
					branchtalukacode,
					branchhoblicode,
					branchcityvillagecode,
					branchpincode)
				select
				    nextval('kaverimrg.branchid_seq'),
				    v_registrationid,
				    v_applicationnumber,
				    amendhousebuildingname,
				    amendstreetaddress,
				    amendstatecode,
				    amenddistrictcode,
				    amendtalukacode,
				    amendhoblicode,
				    amendcityvillagecode,	
				    amendpincode from kaverimrg.amendmentfirmbranches a 
				    where a.amendmentbranchid in (v_branchrecord.amendmentbranchid) and applicationnumber =_applicationnumber
				    returning true into v_check;
				else
					delete from kaverimrg.amendmentfirmbranches a where branchid in (v_branchid);
					delete from kaverimrg.firmbranches where branchid in (v_branchid)
					returning true into v_check;
				end if;
		end loop;
	
	elsif(v_applicationtype = 3) then
		
		for v_partyrecord in (select firmpersonid from kaverimrg.amendmentfirmparty a where amendmentid in(select amendmentid from kaverimrg.firmamendment f where applicationnumber =_applicationnumber) and presentertypeid = 6)
		loop
		
			update kaverimrg.firmparty b
			set salutation = a.salutation,
				firstname = a.firstname,
				middlename = a.middlename,
				lastname = a.lastname,
				prehousebuildname = a.amendhousebuildingname,
				prestreetname = a.amendstreetaddress,
				prestatecode = a.amendstatecode,
				predistrictcode = a.amenddistrictcode,
				pretalukacode = a.amendtalukacode,
				prehoblicode = a.amendtalukacode,
				precityvillagecode = a.amendcityvillagecode,
				prepincode = a.amendpincode
				from (select * from kaverimrg.amendmentfirmparty where firmpersonid = v_partyrecord.firmpersonid) a
				where b.firmpersonid = v_partyrecord.firmpersonid returning true into v_check;	
		end loop;
		
	else
		for v_minorrecord in (select firmpersonid from kaverimrg.amendmentfirmparty a where amendmentid in(select amendmentid from kaverimrg.firmamendment f where applicationnumber =_applicationnumber))
		loop 
			update kaverimrg.firmparty b
			set age = a.age
			from (select * from kaverimrg.amendmentfirmparty where firmpersonid = v_minorrecord.firmpersonid) a
			where b.firmpersonid = v_minorrecord.firmpersonid returning true into v_check;		
		end loop;
end if;
else
	v_check:=false;
	--raise notice 'DR is not approved';
end if;
return v_check;
end;
$$;


ALTER FUNCTION kaverimrg.fn_update_dr_approved_amendments(_applicationnumber character varying) OWNER TO postgres;

