--
-- Name: fn_update_final_regnumber(integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_final_regnumber(_srocode integer, _applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_regnumber text;
   v_serialnumber bigint;
   v_BOOKID bigint;
   v_regdocnumber text default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
  
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select dm.finalregistrationnumber,dm.bookid,sro.shortnamee,coalesce(srl.finalserial,0)+1
into v_regdocnumber,v_BOOKID,v_shortname,v_serialnumber
from kaverimrg.documentmaster dm 
inner join kaverimrg.sromaster  sro on (dm.srocode=sro.srocode) 
inner join kaverimrg.sroserialmaster srl on (srl.srocode=dm.srocode and srl.bookid=dm.bookid and srl.finyear = V_FINYEAR)
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode limit 1;
			
v_regnumber:= v_shortname||'-'||v_BOOKID||'-'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

/* select COALESCE(sro.registrationdocserial,0)+1,shortnamee into v_serialnumber,v_shortname
 from  kaverimrg.sromaster sro where srocode = _srocode;
SELECT BOOKID INTO v_BOOKID FROM kaverimrg.DOCUMENTMASTER WHERE applicationnumber = _applicationnumber LIMIT 1;
select dm.finalregistrationnumber,sm.servicename into v_regdocnumber,applicationtype from kaverimrg.documentmaster dm 
left join kaverimrg.applicantapplicationdetails appd on (dm.applicationnumber = appd.applicationnumber)
left join kaverimrg.servicesmaster sm on (appd.applicationtypeid = sm.serviceid)  
where dm.applicationnumber = _applicationnumber and dm.srocode= _srocode;*/

if (v_regdocnumber is null) then
update kaverimrg.documentmaster set finalregistrationnumber= v_regnumber,documentnumber=v_serialnumber,
registrationdatetime = CURRENT_TIMEstamp
where applicationnumber = _applicationnumber and srocode= _srocode
and finalregistrationnumber is null;
v_regdocnumber:=v_regnumber;
else 
return v_regdocnumber;
end if;
return v_regdocnumber;
END;
$$;


ALTER FUNCTION kaverimrg.fn_update_final_regnumber(_srocode integer, _applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_update_final_regnumber_firm(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_final_regnumber_firm(_applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_regnumber text;
   v_marriagetype character varying(5);
   v_serialnumber bigint;
   v_regdocnumber text default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
  
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select f.finalregistrationnumber,d.shortnamee,f.registrationid
into v_regdocnumber,v_shortname,v_serialnumber
from kaverimrg.firmmaster f
inner join kaverimrg.districtmaster d on d.districtcode = f.drcode
where f.applicationnumber = _applicationnumber limit 1;
			
v_regnumber:= v_shortname||'-'||'F'||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

if (v_regdocnumber is null) then
update kaverimrg.firmmaster set finalregistrationnumber= v_regnumber,
dateofregistration = CURRENT_TIMEstamp,
isregistrationcompleted=true
where applicationnumber = _applicationnumber
and finalregistrationnumber is null;
v_regdocnumber:=v_regnumber;
else 
return v_regdocnumber;
end if;
return v_regdocnumber;
END;
$$;


