--
-- Name: fn_update_final_regnumber_marriage(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_final_regnumber_marriage(_applicationnumber character varying) RETURNS TABLE(v_regdocnumber character varying, v_dateofreg timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
declare
   v_cnt int;
   v_regnumber text;
   v_marriagetype character varying(5);
   v_serialnumber bigint;
   v_regdocnumber character varying(50) default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
   v_dateofreg timestamp;
  
BEGIN

	select count(finalregistrationnumber) into v_cnt  from kaverimrg.marriageregistration m where applicationnumber = _applicationnumber;

if(v_cnt = 1)then

	select finalregistrationnumber into v_regdocnumber from kaverimrg.marriageregistration m where applicationnumber =_applicationnumber;
	select dateofregistration into v_dateofreg from kaverimrg.marriageregistration m where applicationnumber =_applicationnumber;
	return query
	select v_regdocnumber ,v_dateofreg;

else
	
V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select m.finalregistrationnumber,sro.shortnamee,mt.shortnamee,nextval('kaverimrg.marriage_finalreg_seq')
into v_regdocnumber,v_shortname,v_marriagetype,v_serialnumber
from kaverimrg.marriageregistration m 
inner join kaverimrg.sromaster sro on (m.regsrocode=sro.srocode) 
inner join kaverimrg.districtmaster d on d.districtcode = sro.districtcode
inner join kaverimrg.mas_marriagetype mt on mt.marriagetypeid = m.marriagetypeid
where m.applicationnumber = _applicationnumber limit 1;
			
v_regnumber:= v_shortname||'-'||v_marriagetype||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

if (v_regdocnumber is null) then
update kaverimrg.marriageregistration 
set finalregistrationnumber= v_regnumber,
	dateofregistration = CURRENT_TIMEstamp,
	documentnumber=v_serialnumber,
	isregistraioncomplete = true
where applicationnumber = _applicationnumber
and finalregistrationnumber is null
returning finalregistrationnumber,dateofregistration into v_regdocnumber,v_dateofreg;
--v_regdocnumber:=v_regnumber;
--v_dateofreg:=dateofregistration;
end if;
return query
select v_regdocnumber,v_dateofreg;
end if;
END;
$$;


ALTER FUNCTION kaverimrg.fn_update_final_regnumber_marriage(_applicationnumber character varying) OWNER TO postgres;

--
-- Name: fn_update_final_regnumber_marriage_060523(character varying, boolean); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_final_regnumber_marriage_060523(_applicationnumber character varying, _isregistraioncomplete boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_regnumber text;
   v_marriagetype character varying(5);
   v_serialnumber bigint;
   v_regdocnumber text default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
  
begin
	
	if(_isregistraioncomplete = true)then

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select m.finalregistrationnumber,sro.shortnamee,mt.shortnamee,nextval('kaverimrg.marriage_finalreg_seq')
into v_regdocnumber,v_shortname,v_marriagetype,v_serialnumber
from kaverimrg.marriageregistration m 
inner join kaverimrg.sromaster  sro on (m.regsrocode=sro.srocode) 
inner join kaverimrg.districtmaster d on d.districtcode = sro.districtcode
inner join kaverimrg.mas_marriagetype mt on mt.marriagetypeid = m.marriagetypeid
where m.applicationnumber = _applicationnumber limit 1;
			
v_regnumber:= v_shortname||'-'||v_marriagetype||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

if (v_regdocnumber is null) then
update kaverimrg.marriageregistration set finalregistrationnumber= v_regnumber,
dateofregistration = CURRENT_TIMEstamp,documentnumber=v_serialnumber,isregistraioncomplete =true
where applicationnumber = _applicationnumber
and finalregistrationnumber is null;
v_regdocnumber:=v_regnumber;
else 
return v_regdocnumber;
end if;
end if;
return v_regdocnumber;
END;
$$;


ALTER FUNCTION kaverimrg.fn_update_final_regnumber_marriage_060523(_applicationnumber character varying, _isregistraioncomplete boolean) OWNER TO postgres;

--
-- Name: fn_update_final_regnumber_marriage_bck_120623(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_final_regnumber_marriage_bck_120623(_applicationnumber character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
   v_regnumber text;
   v_marriagetype character varying(5);
   v_serialnumber bigint;
   v_regdocnumber text default null;
   v_shortname character varying(50);
   V_FINYEAR character varying(50);
  
BEGIN

V_FINYEAR:=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );

select m.finalregistrationnumber,d.shortnamee,mt.shortnamee,m.registrationid
into v_regdocnumber,v_shortname,v_marriagetype,v_serialnumber
from kaverimrg.marriageregistration m 
inner join kaverimrg.sromaster  sro on (m.regsrocode=sro.srocode) 
inner join kaverimrg.districtmaster d on d.districtcode = sro.districtcode
inner join kaverimrg.mas_marriagetype mt on mt.marriagetypeid = m.marriagetypeid
where m.applicationnumber = _applicationnumber limit 1;
			
v_regnumber:= v_shortname||'-'||v_marriagetype||to_char(v_serialnumber,'fm00000')||'-'||V_FINYEAR;

if (v_regdocnumber is null) then
update kaverimrg.marriageregistration set finalregistrationnumber= v_regnumber,
dateofregistration = CURRENT_TIMEstamp
where applicationnumber = _applicationnumber
and finalregistrationnumber is null;
v_regdocnumber:=v_regnumber;
else 
return v_regdocnumber;
end if;
return v_regdocnumber;
END;
$$;


