	perstreetaddress=a._perstreetaddress,
	perstatecode=a._perstatecode,
	perdistrictcode=a._perdistrictcode,
	pertalukacode=a._pertalukacode,
	perhoblicode=a._perhoblicode,
	percityvillagecode=a._percityvillagecode,
	perpincode=a._perpincode,
	isminor=a._isminor,
	presentertypeid=a._presentertypeid,
	isactive=a._isactive,
	applicationnumber=a._applicationnumber
				from unnest($1) a
			  where p1.dissolutionpersonid in  (select a._dissolutionpersonid from unnest($1) a)
				returning a._dissolutionpersonid into v_dissolutionpersonid;
				
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FD103' 
       where applicationnumber=v_applicationnumber;	
 
 end if;
 
-- v_pid := v_dissolutionpersonid;
-- end loop;
 
-- end if;

return v_dissolutionpersonid;

end;
$_$;


