CREATE FUNCTION kaverimrg.fn_update_insertagentdetailsamendment(p_agentdetails kaverimrg.partnerdetailsamendment[] DEFAULT NULL::kaverimrg.partnerdetailsamendment[]) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$


declare
v_cnt bigint;
v_firmpersonid bigint;
v_amendmentpersonid_req bigint;
v_presentertypeid_req bigint;
v_pid bigint;
v_amendmentid integer;
v_partner_arry kaverimrg.partnerdetailsamendment[];
v_applicationnumber  varchar;
--v_finalregnumber character varying;
v_existing_presenterid  bigint;	
v_existing_presentertypeid bigint;
	
	
begin

-- select finalregistrationnumber into v_finalregnumber from kaverimrg.firmmaster where applicationnumber in
-- (select a2._applicationnumber from unnest($1) a2);
raise notice 'outside if';

if(p_agentdetails is not null and array_length(p_agentdetails,1)=1 ) then    --if1
 FOR v_partner_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_agentdetails))
 loop
		
	   
	
 
			v_cnt:=0; 
		-- find existing presenter in amendment
			select amendmentpersonid,presentertypeid  into v_existing_presenterid,v_existing_presentertypeid
			from kaverimrg.amendmentfirmparty where presentertypeid in (1,2)
			and  amendmentid =(select a._amendmentid from unnest(v_partner_arry) a );
		-- find type of presenter requested
			select a._amendmentpersonid,a._presentertypeid into 
		     v_amendmentpersonid_req,v_presentertypeid_req from unnest(v_partner_arry) a ;
		    
		    if v_existing_presenterid=v_amendmentpersonid_req then  --if2 start
		    
		    		update kaverimrg.amendmentfirmparty p1 set 
			  		amendmentid=a._amendmentid,
					firmpersonid=a._firmpersonid,
					salutation=a._salutation,
					firstname=a._firstname,
					middlename=a._middlename,
					lastname=a._lastname,
					amendhousebuildingname=a._amendhousebuildingname,
					amendstreetaddress=a._amendstreetaddress,
					amendstatecode=a._amendstatecode,
					amenddistrictcode=a._amenddistrictcode,
					amendtalukacode=a._amendtalukacode,
					amendhoblicode=a._amendhoblicode,
					amendcityvillagecode=a._amendcityvillagecode,
					amendpincode=a._amendpincode,
					isminor=a._isminor,
					presentertypeid=a._presentertypeid,
					gpaagentpath=a._uploadgpadoc,
					dob=a._dob,
					age=a._age,
				    phoneno=a._phoneno,
					gender=a._gender,
					email=a._email,
					isactive=a._isactive
	
					from unnest(v_partner_arry) a
			  		where p1.amendmentpersonid=v_existing_presenterid
					returning a._amendmentpersonid into v_amendmentpersonid_req;
					
			else 
		    
		      
		    
		    		if v_existing_presenterid is null then  --no existing presenter --if3 start
		    
							    	insert into kaverimrg.amendmentfirmparty
										(amendmentpersonid ,
										amendmentid,
										firmpersonid,
										salutation,
										firstname,
										middlename,
										lastname,
										amendhousebuildingname,
										amendstreetaddress,
										amendstatecode,
										amenddistrictcode,
										amendtalukacode ,
										amendhoblicode,
										amendcityvillagecode,
										amendpincode,
										isminor,
										presentertypeid,
										gpaagentpath,
										dob,
										age,
									    phoneno,
										gender,
										email,
										isactive
										)
									select 
									nextval('kaverimrg.amendmentpersonid_seq'),
										a._amendmentid,
										a._firmpersonid,
										a._salutation,
										a._firstname,
										a._middlename,
										a._lastname,
										a._amendhousebuildingname,
										a._amendstreetaddress,
										a._amendstatecode,
										a._amenddistrictcode,
										a._amendtalukacode,
										a._amendhoblicode,
										a._amendcityvillagecode,
										a._amendpincode,
										a._isminor,
										a._presentertypeid,
										a._uploadgpadoc,
										a._dob,
										a._age,
										a._phoneno,
										a._gender,
										a._email,
										a._isactive
										from unnest(v_partner_arry) a
										returning amendmentpersonid into v_amendmentpersonid_req;
				
					else   --presenter exists
		    
		      		    
										    if v_presentertypeid_req=2  then  -- if4 requested is an agent
										       
										        if v_existing_presentertypeid=2 then  -- update existing agent --if5 
										        
										          update kaverimrg.amendmentfirmparty p1 set 
											  		amendmentid=a._amendmentid,
													firmpersonid=a._firmpersonid,
													salutation=a._salutation,
													firstname=a._firstname,
													middlename=a._middlename,
													lastname=a._lastname,
													amendhousebuildingname=a._amendhousebuildingname,
													amendstreetaddress=a._amendstreetaddress,
													amendstatecode=a._amendstatecode,
													amenddistrictcode=a._amenddistrictcode,
													amendtalukacode=a._amendtalukacode,
													amendhoblicode=a._amendhoblicode,
													amendcityvillagecode=a._amendcityvillagecode,
													amendpincode=a._amendpincode,
													isminor=a._isminor,
													presentertypeid=a._presentertypeid,
													gpaagentpath=a._uploadgpadoc,
													dob=a._dob,
													age=a._age,
												    phoneno=a._phoneno,
													gender=a._gender,
													email=a._email,
													isactive=a._isactive
									
													from unnest(v_partner_arry) a
											  		where p1.amendmentpersonid=v_existing_presenterid
													returning amendmentpersonid into v_amendmentpersonid_req;
											
													elsif v_existing_presentertypeid=1 then 
											
														delete from  kaverimrg.amendmentfirmparty 
														where amendmentpersonid =v_existing_presenterid;
																insert into kaverimrg.amendmentfirmparty
																(amendmentpersonid ,
																amendmentid,
																firmpersonid,
																salutation,
																firstname,
																middlename,
																lastname,
																amendhousebuildingname,
																amendstreetaddress,
																amendstatecode,
																amenddistrictcode,
																amendtalukacode ,
																amendhoblicode,
																amendcityvillagecode,
																amendpincode,
																isminor,
																presentertypeid,
																gpaagentpath,
																dob,
																age,
																phoneno,
																gender,
																email,
																isactive
																)
															select 
															nextval('kaverimrg.amendmentpersonid_seq'),
																a._amendmentid,
																a._firmpersonid,
																a._salutation,
																a._firstname,
																a._middlename,
																a._lastname,
																a._amendhousebuildingname,
																a._amendstreetaddress,
																a._amendstatecode,
																a._amenddistrictcode,
																a._amendtalukacode,
																a._amendhoblicode,
																a._amendcityvillagecode,
																a._amendpincode,
																a._isminor,
																a._presentertypeid,
																a._uploadgpadoc,
																a._dob,
																a._age,
																a._phoneno,
																a._gender,
																a._email,
																a._isactive
																from unnest(v_partner_arry) a
																returning amendmentpersonid into v_amendmentpersonid_req;
													end if; --if5 
			
										elsif v_presentertypeid_req=1 then 
			
											if v_existing_presentertypeid=2 then   --if6
			    
														return null;
											 elsif v_existing_presentertypeid=1 then 
			     
														 delete from kaverimrg.amendmentfirmparty 
														  where amendmentpersonid =v_existing_presenterid;
														  
														 insert into kaverimrg.amendmentfirmparty
															(amendmentpersonid ,
															amendmentid,
															firmpersonid,
															salutation,
															firstname,
															middlename,
															lastname,
															amendhousebuildingname,
															amendstreetaddress,
															amendstatecode,
															amenddistrictcode,
															amendtalukacode ,
															amendhoblicode,
															amendcityvillagecode,
															amendpincode,
															isminor,
															presentertypeid,
															gpaagentpath,
															dob,
															age,
															phoneno,
															gender,
															email,
															isactive
															)
														select 
														nextval('kaverimrg.amendmentpersonid_seq'),
															a._amendmentid,
															a._firmpersonid,
															a._salutation,
