--
-- Name: fn_update_marriageregistartion_status(character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_marriageregistartion_status(_applicationnumber character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
Declare

v_marriagemodeid int ;

begin 
	
--		select r.paymentmodeid into v_paymentmodeid from kaverimrg.receiptmaster r2 
--		join kaverimrg.receiptpaymentdetails r on r2.receiptid =r.receiptid 
--		where r2.applicationnumber =_applicationnumber;

		select marriagemodeid into v_marriagemodeid from kaverimrg.marriageregistration m where applicationnumber =_applicationnumber ;
	
		if(v_marriagemodeid=1)
		then 
		update kaverimrg.applicantapplicationdetails set currentstatus='MR114' where applicationnumber=_applicationnumber;
		
		elsif(v_marriagemodeid=2)
		then
			update kaverimrg.applicantapplicationdetails set currentstatus='MR113' where applicationnumber=_applicationnumber;
		
		end if;
		
	
	return 	_applicationnumber;	
end;
$$;


