CREATE FUNCTION kaverimrg.fn_update_sectionfilepath(_applicationnumber character varying, _section88file character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
v_cnt bigint;
v_status integer;
begin
v_status = 0;
select count(*) into v_cnt from kaverimrg.partyinfo where applicationnumber = _applicationnumber ;
if  v_cnt > 0 then
update kaverimrg.partyinfo set section88file= _section88file where applicationnumber = _applicationnumber
returning 1 into v_status;
end if;
return v_status;

end;
$$;


