ALTER FUNCTION kaverimrg.fn_update_sro_dr_marriageregistration(_applicationnumber character varying, _sro_option character varying) OWNER TO postgres;

--
-- Name: fn_update_sro_dr_marriageregistration_bck_120623(character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_sro_dr_marriageregistration_bck_120623(_applicationnumber character varying, _sro_option character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
v_cnt integer;
v_applicationnumber text;
v_srocode integer;
v_districtcode integer;
v_sro_option text;
begin

select a.srocode,b.districtcode into v_srocode,v_districtcode
From kaverimrg.vw_fetch_marriage_srooffice a left join kaverimrg.sromaster b
on a.srocode = b.srocode
where applicationnumber = _applicationnumber and sro_option = _sro_option;

if (_sro_option = 'BrideGroom_SRO')   then
update kaverimrg.persondetails set 
srocode = v_srocode,
drcode=v_districtcode
where
applicationnumber = _applicationnumber and
sex like 'M%'
returning applicationnumber into v_applicationnumber;

elsif(_sro_option = 'Bride_SRO') then
update kaverimrg.persondetails set 
srocode = v_srocode,
drcode=v_districtcode
where
applicationnumber = _applicationnumber and
sex like 'F%'
returning applicationnumber into v_applicationnumber;

elsif(_sro_option = 'Marriage_Place_SRO') then
update kaverimrg.marriageregistration set 
srocode = v_srocode,drcode=v_districtcode
where
applicationnumber = _applicationnumber 
returning applicationnumber into v_applicationnumber;

elsif(_sro_option = 'Registration_SRO') then
update kaverimrg.marriageregistration set 
regsrocode = v_srocode where applicationnumber = _applicationnumber 
returning applicationnumber into v_applicationnumber;
update kaverimrg.applicantapplicationdetails set 
srocode = v_srocode
where applicationnumber = _applicationnumber 
returning applicationnumber into v_applicationnumber;
end if;

update kaverimrg.applicantapplicationdetails set srocode=v_srocode,regsrocode = v_srocode where applicationnumber =_applicationnumber;
update kaverimrg.persondetails set srocode=v_srocode,drcode=v_districtcode where applicationnumber =_applicationnumber;
update kaverimrg.marriageregistration  set srocode=v_srocode,regsrocode = v_srocode ,drcode = v_districtcode where applicationnumber =_applicationnumber  ;

return v_applicationnumber;
end;
$$;


ALTER FUNCTION kaverimrg.fn_update_sro_dr_marriageregistration_bck_120623(_applicationnumber character varying, _sro_option character varying) OWNER TO postgres;

