--

CREATE FUNCTION kaverimrg.fn_update_sro_serial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
V_ACTIVITYORDER INTEGER DEFAULT 0;
BEGIN

if(old.pendingdocumentnumber is null and new.pendingdocumentnumber is not null) then
--update kaverimrg.sromaster set pendingdocserial = COALESCE(pendingdocserial,0)+1 
--where srocode= new.srocode;
update kaverimrg.sroserialmaster set pendingserial = COALESCE(pendingserial,0)+1 
where srocode= new.srocode and bookid=new.bookid and finyear=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
'-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
			||'-' || to_char(current_date + interval '12 month', 'YY') end );
end if;

-- if(old.finalregistrationnumber is null and new.finalregistrationnumber is not null) then
-- update kaverimrg.sroserialmaster set finalserial = COALESCE(finalserial,0)+1 
-- where srocode= new.srocode and bookid=new.bookid and finyear=(case when EXTRACT(MONTH FROM CURRENT_DATE) <= 3 then 
-- 			to_CHAR(current_date + interval '-12 month', 'YYYY') || 
-- '-' || to_char(CURRENT_DATE, 'YY') else to_char(CURRENT_DATE, 'YYYY') 
-- 			||'-' || to_char(current_date + interval '12 month', 'YY') end );
-- end if;
return new;
END;
$$;


ALTER FUNCTION kaverimrg.fn_update_sro_serial() OWNER TO postgres;

--
-- Name: fn_update_time_citizen_master(bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_update_time_citizen_master(_citizenid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
v_citizenid bigint;

begin

update kaverimrg.citizenmaster set lstupddt=Current_timestamp
where citizenid = _citizenid returning citizenid into v_citizenid;
return v_citizenid;
exception
WHEN unique_violation then
raise notice 'duplicate user';
  end;
$$;


