--
-- Name: fn_updatefetch_mrg_receipt_paid_details(character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_updatefetch_mrg_receipt_paid_details(_applicationnumber character varying, _srocode integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
v_loop_count integer;
v_pay_cnt integer;
--v_receipt_count integer[];
v_pending_fee_count integer;
v_cnt integer;
array_receiptarray record;
v_receiptnumber bigint[];
v_receiptid bigint;
v_total numeric;
v_data json;
BEGIN

/* checking the receiptid already exists */
-- What if there will be more recipt for given applicationnumber and srocode ??
select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
left join kaverimrg.receiptdetails rd
on rm.receiptid = rd.receiptid
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;

/*check whether all payments in mrg_requiredfees table has a receipt issued*/
select count(*) into v_pending_fee_count from kaverimrg.mrg_requiredfees where applicationnumber = _applicationnumber
and receiptid is null and payableamount>=1;

/* if receiptid exists then it returns receiptid */

if v_pending_fee_count=0 then
select array_to_json(array_agg(temp1)) as payment_history into v_data
from 
(select mr.receiptid,are2.deptreferencecode, are2.transactiontimestamp,amount,are3.remittername,
(select array_to_json(array_agg(temp)) as paymentdetails from 
(select distinct feeruleid,feedescription,mr.amountpaid 
from kaverimrg.mrg_requiredfees mr 
where mr.applicationnumber=_applicationnumber and srocode=_srocode)temp)

from kaverimrg.mrg_requiredfees mr 
join kaverimrg.ams_reg_epaymentamtpaiddetails arr on mr.applicationnumber = arr.applicationnumber
join kaverimrg.ams_reg_epaymentbankackdetails are2 on are2.deptreferencecode = arr.deptreferencecode
join kaverimrg.ams_reg_epaymenttransdetails are3 on are3.deptreferencecode = are2.deptreferencecode  
where mr.applicationnumber=_applicationnumber and srocode=_srocode limit 1)temp1;
return v_data;
end if;

select count(*) into v_pay_cnt from (
select epa.deptreferencecode,epa.amount as receiptamount, epd.applicationnumber,
sum(epd.amountpaid) as amountreceived, sum(epd.totalamount) as requestedamount
from kaverimrg.ams_reg_epaymentamtpaiddetails epd
inner join kaverimrg.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.deptreferencecode
where epd.applicationnumber = _applicationnumber and
paymentstatuscode='10700066'
group by epa.deptreferencecode,epa.amount,epd.applicationnumber
) x where requestedamount = amountreceived and amountreceived = receiptamount;

/* if the payment count is greater than zero, it means that payment is done
as such we can now insert into paymentmaster and child tables */

if(v_pay_cnt > 0) then

select sum(payableamount) into v_total from kaverimrg.mrg_requiredfees where 
applicationnumber=_applicationnumber and srocode = _srocode and receiptid is null;

v_loop_count:=0;

for array_receiptarray in (
select a.registrationid, b.feeruleid,c.citizenid, b.payableamount 
from kaverimrg.marriageregistration a
inner join kaverimrg.applicantapplicationdetails c on c.applicationnumber = a.applicationnumber
inner join kaverimrg.mrg_requiredfees b on a.applicationnumber = b.applicationnumber and b.payableamount is not null and b.payableamount>=1
and a.regsrocode = b.srocode and b.receiptid is null)
--inner join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber 
--and ispresenter=true and b.srocode = c.srocode
--where a.applicationnumber=_applicationnumber and a.srocode = _srocode)
loop

--Take a copy of the documentid and partyid for later updation
--select documentid into v_documentid1 from unnest(array_receiptarray) ;
--select partyid into v_partyid1 from unnest(array_receiptarray) ;

if (v_loop_count=0) then
Insert into kaverimrg.receiptmaster
(
receiptid , -- Auto Increment
documentid ,
srocode ,
receipttypeid ,
receiptnumber , -- AutoIncrement
partyid ,
dateofreceipt ,
isprinted ,
printbanner ,
docreturntime ,
applicationnumber,
totalamount
)
values
(
nextval('kaverimrg.receiptmaster_receiptid_seq'),
array_receiptarray.registrationid,
_srocode,
5, -- receipttypeid 1 -- document
nextval('kaverimrg.receiptmaster_receiptnumber_seq'),
array_receiptarray.citizenid,
current_timestamp,
	false,
	null,
	null,
	_applicationnumber,
	v_total
	) returning receiptid into v_receiptid;
	
end if;

--Insert multiple entries for multiple feerulecode
--select feerulecode into v_feerulecode1 from unnest(array_receiptarray) ;
--select amountrequired into v_amountrequired1 from unnest(array_receiptarray) ;
--Multiple entry for each feerulecode

insert into kaverimrg.receiptdetails (receiptid ,
srocode ,
feerulecode ,
amountpaid) values
(
v_receiptid ,
_srocode ,
array_receiptarray.feeruleid,
array_receiptarray.payableamount
);

v_loop_count=v_loop_count+1;

insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);


end loop;

--Update null values in receiptid column of the feesrequired table with new receiptid
update kaverimrg.mrg_requiredfees set receiptid=v_receiptid where applicationnumber=_applicationnumber
and receiptid is null and payableamount>=1;

update kaverimrg.marriageregistration set receiptid=v_receiptid where applicationnumber=_applicationnumber;

update kaverimrg.ams_reg_epaymenttransdetails set receiptid=v_receiptid where applicationnumber = _applicationnumber
and receiptid is null;

/* inserting data into receipt details wrto receiptid */
/*
insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);
*/


elseif (v_pay_cnt=0) then
RAISE NOTICE'Payment Not Done';
end if;

--Return all the receipts available
/*select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;*/

select array_to_json(array_agg(temp1)) as payment_history into v_data
from 
(select mr.receiptid,are2.deptreferencecode, are2.transactiontimestamp,amount,are3.remittername,
(select array_to_json(array_agg(temp)) as paymentdetails from 
(select distinct feeruleid,feedescription,mr.amountpaid 
from kaverimrg.mrg_requiredfees mr 
where mr.applicationnumber=_applicationnumber and srocode=_srocode)temp)

from kaverimrg.mrg_requiredfees mr 
join kaverimrg.ams_reg_epaymentamtpaiddetails arr on mr.applicationnumber = arr.applicationnumber
join kaverimrg.ams_reg_epaymentbankackdetails are2 on are2.deptreferencecode = arr.deptreferencecode
join kaverimrg.ams_reg_epaymenttransdetails are3 on are3.deptreferencecode = are2.deptreferencecode  
where mr.applicationnumber=_applicationnumber and srocode=_srocode limit 1)temp1;

return v_data;

end;
$$;


ALTER FUNCTION kaverimrg.fn_updatefetch_mrg_receipt_paid_details(_applicationnumber character varying, _srocode integer) OWNER TO postgres;

--
-- Name: fn_updatefetch_mrg_receipt_paid_details_18_07_2023(character varying, integer); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_updatefetch_mrg_receipt_paid_details_18_07_2023(_applicationnumber character varying, _srocode integer) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
v_loop_count integer;
v_pay_cnt integer;
--v_receipt_count integer[];
v_pending_fee_count integer;
v_cnt integer;
array_receiptarray record;
v_receiptnumber bigint[];
v_receiptid bigint;
v_total numeric;
BEGIN

/* checking the receiptid already exists */
-- What if there will be more recipt for given applicationnumber and srocode ??
select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
left join kaverimrg.receiptdetails rd
on rm.receiptid = rd.receiptid
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;

/*check whether all payments in mrg_requiredfees table has a receipt issued*/
select count(*) into v_pending_fee_count from kaverimrg.mrg_requiredfees where applicationnumber = _applicationnumber
and receiptid is null and payableamount>=1;

/* if receiptid exists then it returns receiptid */

if v_pending_fee_count=0 then
return(v_receiptnumber);
end if;

select count(*) into v_pay_cnt from (
select epa.deptreferencecode,epa.amount as receiptamount, epd.applicationnumber,
sum(epd.amountpaid) as amountreceived, sum(epd.totalamount) as requestedamount
from kaverimrg.ams_reg_epaymentamtpaiddetails epd
inner join kaverimrg.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.deptreferencecode
where epd.applicationnumber = _applicationnumber and
paymentstatuscode='10700066'
group by epa.deptreferencecode,epa.amount,epd.applicationnumber
) x where requestedamount = amountreceived and amountreceived = receiptamount;

/* if the payment count is greater than zero, it means that payment is done
as such we can now insert into paymentmaster and child tables */

if(v_pay_cnt > 0) then

select sum(payableamount) into v_total from kaverimrg.mrg_requiredfees where 
applicationnumber=_applicationnumber and srocode = _srocode and receiptid is null;

v_loop_count:=0;



for array_receiptarray in (
select a.registrationid, b.feeruleid,c.citizenid, b.payableamount 
from kaverimrg.marriageregistration a
inner join kaverimrg.applicantapplicationdetails c on c.applicationnumber = a.applicationnumber
inner join kaverimrg.mrg_requiredfees b on a.applicationnumber = b.applicationnumber and b.payableamount is not null and b.payableamount>=1
and a.regsrocode = b.srocode and b.receiptid is null)
--inner join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber 
--and ispresenter=true and b.srocode = c.srocode
--where a.applicationnumber=_applicationnumber and a.srocode = _srocode)
loop

--Take a copy of the documentid and partyid for later updation
--select documentid into v_documentid1 from unnest(array_receiptarray) ;
--select partyid into v_partyid1 from unnest(array_receiptarray) ;

if (v_loop_count=0) then
Insert into kaverimrg.receiptmaster
(
receiptid , -- Auto Increment
documentid ,
srocode ,
receipttypeid ,
receiptnumber , -- AutoIncrement
partyid ,
dateofreceipt ,
isprinted ,
printbanner ,
docreturntime ,
applicationnumber,
totalamount
)
values
(
nextval('kaverimrg.receiptmaster_receiptid_seq'),
array_receiptarray.registrationid,
_srocode,
5, -- receipttypeid 1 -- document
nextval('kaverimrg.receiptmaster_receiptnumber_seq'),
array_receiptarray.citizenid,
current_timestamp,
	false,
	null,
	null,
	_applicationnumber,
	v_total
	) returning receiptid into v_receiptid;
	
end if;

--Insert multiple entries for multiple feerulecode
--select feerulecode into v_feerulecode1 from unnest(array_receiptarray) ;
--select amountrequired into v_amountrequired1 from unnest(array_receiptarray) ;
--Multiple entry for each feerulecode

insert into kaverimrg.receiptdetails (receiptid ,
srocode ,
feerulecode ,
amountpaid) values
(
v_receiptid ,
_srocode ,
array_receiptarray.feeruleid,
array_receiptarray.payableamount
);

v_loop_count=v_loop_count+1;

insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);


end loop;

--Update null values in receiptid column of the feesrequired table with new receiptid
update kaverimrg.mrg_requiredfees set receiptid=v_receiptid where applicationnumber=_applicationnumber
and receiptid is null and payableamount>=1;

update kaverimrg.marriageregistration set receiptid=v_receiptid where applicationnumber=_applicationnumber;

update kaverimrg.ams_reg_epaymenttransdetails set receiptid=v_receiptid where applicationnumber = _applicationnumber
and receiptid is null;

/* inserting data into receipt details wrto receiptid */
/*
insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);
*/


elseif (v_pay_cnt=0) then
RAISE NOTICE'Payment Not Done';
end if;

--Return all the receipts available
select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;

return v_receiptnumber;

end;
$$;


