'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);


end loop;

--Update null values in receiptid column of the feesrequired table with new receiptid
update kaverimrg.feesrequired set receiptid=v_receiptid where applicationnumber=_applicationnumber
and receiptid is null and amountpaid>=1;

update kaverimrg.ams_reg_epaymenttransdetails set receiptid=v_receiptid where applicationnumber = _applicationnumber
and receiptid is null;

/* inserting data into receipt details wrto receiptid */
/*
insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);
*/


elseif (v_pay_cnt=0) then
RAISE NOTICE'Payment Not Done';
end if;

--Return all the receipts available
select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
where applicationnumber = _applicationnumber
and rm.srocode = _srocode
Group by rm.receiptid) into v_receiptnumber;

return v_receiptnumber;

end;
$$;


ALTER FUNCTION kaverimrg.fn_updatefetch_receipt_paid_details_bck_10072023(_applicationnumber character varying, _srocode integer) OWNER TO postgres;

--
-- Name: fn_updatefetch_receipt_paid_details_by_challan(character varying, integer, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_updatefetch_receipt_paid_details_by_challan(_applicationnumber character varying, _srocode integer, _challanno character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
pmnt_row record;
v_pay_cnt integer;
v_receipt_count integer;
v_cnt integer;
v_receiptnumber integer;
v_documentid integer;
v_feerulecode integer;
v_amountrequired numeric;
v_partyid bigint;
v_total numeric;
BEGIN

/* checking the receiptid is already exists */
-- What if there will be more recipt for given applicationnumber and srocode ??
select count(*), rm.receiptid into v_receipt_count, v_receiptnumber
from kaverimrg.receiptmaster rm
left join kaverimrg.receiptdetails rd on rm.receiptid = rd.receiptid
left join kaverimrg.ams_reg_epaymenttransdetails et
on rd.receiptid = et.receiptid
where rm.applicationnumber = _applicationnumber
and rm.srocode = _srocode
and et.deptreferencecode = _challanno  /* added challanno as output parameter as requested by Krishna Gautam*/
Group by rm.receiptid;

/* if receiptid exists then it returns receiptid */

if v_receipt_count >=1 then
return(v_receiptnumber);
end if;

/*select count(*) into v_pay_cnt
from kaverimrg.ams_reg_epaymentamtpaiddetails epd
left join kaverimrg.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.chlnrefnum
where applicationnumber=_applicationnumber and
paymentstatuscode='10700066';*/

select count(*) into v_pay_cnt from (
select epa.deptreferencecode,epa.amount as receiptamount, epd.applicationnumber,
sum(epd.amountpaid) as amountreceived, sum(epd.totalamount) as requestedamount
from kaverimrg.ams_reg_epaymentamtpaiddetails epd
inner join kaverimrg.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.deptreferencecode
where epd.applicationnumber = _applicationnumber and epd.deptreferencecode = _challanno and
paymentstatuscode='10700066'
group by epa.deptreferencecode,epa.amount,epd.applicationnumber
) x where requestedamount = amountreceived and amountreceived = receiptamount;

/* if the payment count is greater than zero then insert into paymentmaster and child tables */

if(v_pay_cnt > 0) then

select distinct a.documentid,--b.amountpaid,
c.partyid  
into v_documentid,--v_amountrequired,
v_partyid
from kaverimrg.documentmaster a inner join kaverimrg.feesrequired b on 
a.applicationnumber = b.applicationnumber and amountpaid is not null
and a.srocode = b.srocode
inner join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber 
and ispresenter=true and b.srocode = c.srocode
where a.applicationnumber=_applicationnumber and a.srocode = _srocode;

/*select sum(amountpaid) into v_total from kaverimrg.feesrequired where 
applicationnumber=_applicationnumber and srocode = _srocode;*/

select sum(f.amountpaid) into v_total from kaverimrg.feesrequired f
join kaverimrg.ams_reg_epaymenttransdetails am on am.feerulecode=f.feerulecode
where
f.applicationnumber=_applicationnumber and f.srocode = _srocode and f.paymentstatus in ('Challan Success','Online Success')
and am.deptreferencecode=_challanno;
if v_receipt_count = 0 then
Insert into kaverimrg.receiptmaster
(
receiptid , -- Auto Increment
documentid ,
srocode ,
receipttypeid ,
receiptnumber , -- AutoIncrement
partyid ,
 dateofreceipt ,
 isprinted ,
 printbanner ,
 docreturntime ,
applicationnumber,
 totalamount
)
values
(
nextval('kaverimrg.receiptmaster_receiptid_seq'),
v_documentid ,
_srocode,
1, -- receipttypeid 1 -- document
nextval('kaverimrg.receiptmaster_receiptnumber_seq'),
v_partyid,
current_timestamp,
	false,
	null,
	null,
	_applicationnumber,
	v_total
	) returning receiptid into v_receiptnumber;
	end if;
select count(*) into v_cnt from kaverimrg.feesrequired a
left join kaverimrg.ams_reg_epaymenttransdetails b on a.documentid = b.documentid and a.feerulecode = b.feerulecode
where a.applicationnumber=_applicationnumber and b.deptreferencecode = _challanno;

/* inserting multiple records wrto feerulecode and amount required */

		if (v_cnt > 0) then
for pmnt_row in (
select a.documentid,b.feerulecode,b.amountpaid,c.partyid  
--into v_documentid,v_feerulecode,v_amountrequired,v_partyid
from kaverimrg.documentmaster a inner join kaverimrg.feesrequired b on 
a.applicationnumber = b.applicationnumber and amountpaid is not null
and a.srocode = b.srocode
inner join kaverimrg.partyinfo c on b.applicationnumber = c.applicationnumber 
and ispresenter=true and b.srocode = c.srocode
where a.applicationnumber=_applicationnumber and a.srocode = _srocode)
loop
insert into kaverimrg.receiptdetails (receiptid ,
srocode ,
feerulecode ,
-- deptsubpurposeid ,
amountpaid) values
(
v_receiptnumber ,
_srocode ,
pmnt_row.feerulecode ,
-- deptsubpurposeid ,
pmnt_row.amountpaid
)
returning receiptid into v_receiptnumber;
end loop;
end if;

/* inserting data into receipt details wrto receiptid */

insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptnumber ,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
) returning receiptid into v_receiptnumber;
elsif (v_pay_cnt=0) then
RAISE NOTICE'Payment Not Done';
end if;
return v_receiptnumber;
end;
$$;


ALTER FUNCTION kaverimrg.fn_updatefetch_receipt_paid_details_by_challan(_applicationnumber character varying, _srocode integer, _challanno character varying) OWNER TO postgres;

--
-- Name: fn_updatefetch_receipt_paid_details_firm(character varying, bigint); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_updatefetch_receipt_paid_details_firm(_applicationnumber character varying, _drcode bigint) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$
DECLARE
v_loop_count integer;
v_pay_cnt integer;
--v_receipt_count integer[];
v_pending_fee_count integer;
v_cnt integer;
array_receiptarray record;
v_receiptnumber bigint[];
v_receiptid bigint;
v_total numeric;
BEGIN

/* checking the receiptid already exists */
-- What if there will be more recipt for given applicationnumber and srocode ??
select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
left join kaverimrg.receiptdetails rd
on rm.receiptid = rd.receiptid
where applicationnumber = _applicationnumber

--and rm.srocode = _srocode
Group by rm.receiptid order by rm.receiptid desc  limit 1) into v_receiptnumber;

/*check whether all payments in feerequired table has a receipt issued*/
select count(*) into v_pending_fee_count from kaverimrg.firm_requiredfees 
where applicationnumber = _applicationnumber
and receiptid is null and amountpaid>=1;

/* if receiptid exists then it returns receiptid */

if v_pending_fee_count=0 then
return(v_receiptnumber);
end if;

select count(*) into v_pay_cnt from (
select epa.deptreferencecode,epa.amount as receiptamount, epd.applicationnumber,
sum(epd.amountpaid) as amountreceived, sum(epd.totalamount) as requestedamount
from kaverimrg.ams_reg_epaymentamtpaiddetails epd
inner join kaverimrg.ams_reg_epaymentbankackdetails epa
on epa.deptreferencecode=epd.deptreferencecode
where epd.applicationnumber = _applicationnumber and
paymentstatuscode in ('10700066','10700072')
group by epa.deptreferencecode,epa.amount,epd.applicationnumber
) x where requestedamount = amountreceived and amountreceived = receiptamount;

/* if the payment count is greater than zero, it means that payment is done
as such we can now insert into paymentmaster and child tables */

if(v_pay_cnt > 0) then

select sum(amountpaid) into v_total from kaverimrg.firm_requiredfees  where 
applicationnumber=_applicationnumber and  receiptid is null;

v_loop_count:=0;

for array_receiptarray in (
select b.registrationid  , b.feeruleid,b.amountpaid,c.citizenid 
from kaverimrg.applicantapplicationdetails  a 
inner join kaverimrg.firm_requiredfees b on a.applicationnumber = b.applicationnumber
and amountpaid is not null and amountpaid>=1 and b.receiptid is null
inner join kaverimrg.citizenmaster  c on c.citizenid  = a.citizenid 
 --and b.srocode = c.srocode
where a.applicationnumber=_applicationnumber )
loop

--Take a copy of the documentid and partyid for later updation
--select documentid into v_documentid1 from unnest(array_receiptarray) ;
--select partyid into v_partyid1 from unnest(array_receiptarray) ;

if (v_loop_count=0) then
Insert into kaverimrg.receiptmaster
(
receiptid , -- Auto Increment
documentid ,
srocode ,
receipttypeid ,
receiptnumber , -- AutoIncrement
partyid ,
 dateofreceipt ,
 isprinted ,
 printbanner ,
 docreturntime ,
applicationnumber,
 totalamount
)
values
(
nextval('kaverimrg.receiptmaster_receiptid_seq'),
array_receiptarray.registrationid ,
_drcode,
1, -- receipttypeid 1 -- document
nextval('kaverimrg.receiptmaster_receiptnumber_seq'),
array_receiptarray.citizenid,
current_timestamp,
	false,
	null,
	null,
	_applicationnumber,
	v_total
	) returning receiptid into v_receiptid;
	
end if;

--Insert multiple entries for multiple feerulecode
--select feerulecode into v_feerulecode1 from unnest(array_receiptarray) ;
--select amountrequired into v_amountrequired1 from unnest(array_receiptarray) ;
--Multiple entry for each feerulecode
insert into kaverimrg.receiptdetails (receiptid ,
srocode ,
feerulecode ,
amountpaid) values
(
v_receiptid ,
_drcode ,
array_receiptarray.feeruleid ,
array_receiptarray.amountpaid
);

v_loop_count=v_loop_count+1;



insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_drcode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);


end loop;

--Update null values in receiptid column of the feesrequired table with new receiptid
update kaverimrg.firm_requiredfees set receiptid=v_receiptid where applicationnumber=_applicationnumber
and receiptid is null and amountpaid>=1;

update kaverimrg.ams_reg_epaymenttransdetails set receiptid=v_receiptid where applicationnumber = _applicationnumber
and receiptid is null;

/* inserting data into receipt details wrto receiptid */
/*
insert into kaverimrg.receiptpaymentdetails
(
receiptid ,
srocode ,
paymentmodeid,
description ,
ddnumber ,
dddate ,
ifsccodeid,
ifsccode ,
micrcode ,
amount
)
values(
v_receiptid,
_srocode,--rm.srocode ,
4, -- paymentmodeid
'Paid through e-Payment an amount of Rs.' || v_total ,
null,--sd.ddnumber ,
null,--sd.ddchaldate as dddate,
null,--sd.ifccodeid ,
null,--sd.ifccode ,
null,--sd.micrcode ,
v_total
);
*/


else if (v_pay_cnt=0) then
RAISE NOTICE'Payment Not Done';
end if;
end if;
--Return all the receipts available
select array(select distinct rm.receiptid
from kaverimrg.receiptmaster rm
where applicationnumber = _applicationnumber 

--and rm.srocode = _srocode
Group by rm.receiptid order by rm.receiptid desc  limit 1) into v_receiptnumber;

return v_receiptnumber;

end;
$$;


