ALTER TABLE kaverimrg.type_insertreconstitutionpartydetails OWNER TO postgres;

--
-- Name: fn_updateinsertreconstitutionpartydetails(kaverimrg.type_insertreconstitutionpartydetails[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_updateinsertreconstitutionpartydetails(p_partydetails kaverimrg.type_insertreconstitutionpartydetails[] DEFAULT NULL::kaverimrg.type_insertreconstitutionpartydetails[]) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$



declare
v_cnt bigint;
v_firmpersonid bigint;
v_partner_arry kaverimrg.type_insertreconstitutionpartydetails[];
v_pid bigint[];
v_applicationnumber character varying;
v_presentertypeid int;
v_linkfirmpersonid bigint;
v_reconstitutionpartyid bigint;

begin

if(p_partydetails is not null and array_length(p_partydetails,1)>0 ) then

 FOR v_partner_arry IN (SELECT kaverimrg.fn_fetch_1d_arrayofarray(p_partydetails)) 
loop
v_cnt:=0; 
v_firmpersonid:=0;

			 Select count(*) into v_cnt 
			 from kaverimrg.firmreconstitutionparty where reconstitutionpartyid in 
			(select a._reconstitutionpartyid from unnest(v_partner_arry) a) ;
		if v_cnt = 0 
		then
			  insert into kaverimrg.firmreconstitutionparty
			  (
			  reconstitutionpartyid,
			  reconstitutionid,
			  firmpersonid,
			  salutation,
			  firstname,
			  middlename,
			  lastname,
			  relationship,
			  relativename,
			  dob,
			  gender,
			  age,
			  occupation,
			  phoneno,
			  emailid,
			  prehousebuildname,
			  prestreetname,
			  prestatecode,
			  predistrictcode,
			  pretalukacode,
			  prehoblicode,
			  precityvillagecode,
			  prepincode,
			  ispresentaddresssameaspermanent,
			  perhousebuildname,
			  perstreetname,
			  perstatecode,
			  perdistrictcode,
			  pertalukacode,
			  perhoblicode,
			  percityvillagecode,
			  perpincode,
			  dateofsease,
			  dateofjoin,
			  isnewentry,
			  identityproof_idprooftypeid,
			  identityproofidpath,
			  addressproof_idprooftypeid,
			  addressproofidpath,
			  gpaagentpath,
			  presentertypeid,
			  proofofauthorisationfortheagentid,
			  proofofauthorisationfortheagentpath,
			  isincoming,
			  isoutgoing,
			  applicationnumber,
			  linkfirmpersonid,
			  inserteddatetime
			  )
		select 
		nextval('kaverimrg.reconstitutionpartyid_seq'),
		a._reconstitutionid,
		a._firmpersonid,
		a._salutation ,
		a._firstname ,
		a._middlename,
		a._lastname ,
		a._relationship ,
		a._relativename ,
		a._dob ,
		a._gender,
		a._age  ,
		a._occupation ,
		a._phoneno ,
		a._email ,
		a._prehousebuildname,
		a._prestreetname,
		a._prestatecode,
		a._predistrictcode,
		a._pretalukacode,
		a._prehoblicode,
		a._precityvillagecode,
		a._prepincode,
		a._ispresentaddresssameaspermanent,
		a._perhousebuildname,
		a._perstreetname,
		a._perstatecode,
		a._perdistrictcode,
		a._pertalukacode,
		a._perhoblicode,
		a._percityvillagecode,
		a._perpincode,
		a._dateofsease,
		a._dateofjoin,
		a._isnewentry,
		a._identityproof_idprooftypeid,
		a._identityproofidpath,
		a._addressproof_idprooftypeid,
		a._addressproofidpath,
		a._gpaagentpath,
		a._presentertypeid ,
		a._proofofauthorisationfortheagentid  ,
		a._proofofauthorisationfortheagentpath ,
		a._isincoming ,
		a._isoutgoing ,
		a._applicationnumber ,
		a._linkfirmpersonid ,
		a._inserteddatetime
	
 from unnest(v_partner_arry) a
	returning reconstitutionpartyid into v_reconstitutionpartyid;
	
		select a._applicationnumber into v_applicationnumber from unnest(v_partner_arry) a;
		select a._presentertypeid into v_presentertypeid from unnest(v_partner_arry) a;

		update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC103' 
		where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (1,2) ;	

		update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC105' 
		where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (6);	

		else
			  update kaverimrg.firmreconstitutionparty 
								 set  
								 --reconstitutionpartyid =_reconstitutionpartyid,
					 -- reconstitutionid =a._reconstitutionid,
					  firmpersonid =a._firmpersonid,
					  salutation =a._salutation ,
					  firstname =a._firstname ,
					  middlename =a._middlename,
					  lastname =a._lastname ,
					  relationship =a._relationship ,
					  relativename =a._relativename ,
					  dob =a._dob ,
					  gender =a._gender,
					  age =a._age  ,
					  occupation =a._occupation ,
					  phoneno =a._phoneno ,
					  emailid =a._email ,
					  prehousebuildname =a._prehousebuildname,
					  prestreetname =a._prestreetname,
					  prestatecode =a._prestatecode,
					  predistrictcode =a._predistrictcode,
					  pretalukacode =a._pretalukacode,
					  prehoblicode =a._prehoblicode,
					  precityvillagecode =a._precityvillagecode,
					  prepincode =a._prepincode,
					  ispresentaddresssameaspermanent =a._ispresentaddresssameaspermanent,
					  perhousebuildname =a._perhousebuildname,
					  perstreetname =a._perstreetname,
					  perstatecode =a._perstatecode,
					  perdistrictcode =a._perdistrictcode,
					  pertalukacode =a._pertalukacode,
					  perhoblicode =a._perhoblicode,
					  percityvillagecode =a._percityvillagecode,
					  perpincode =a._perpincode,
					  dateofsease =a._dateofsease ,
					  dateofjoin=a._dateofjoin,
					  isnewentry =a._isnewentry,
					  identityproof_idprooftypeid =a._identityproof_idprooftypeid,
					  identityproofidpath =a._identityproofidpath,
					  addressproof_idprooftypeid =a._addressproof_idprooftypeid,
					  addressproofidpath =a._addressproofidpath,
					  gpaagentpath =a._gpaagentpath,
					  presentertypeid =a._presentertypeid ,
					  proofofauthorisationfortheagentid =a._proofofauthorisationfortheagentid  ,
					  proofofauthorisationfortheagentpath =a._proofofauthorisationfortheagentpath ,
					  isincoming =a._isincoming ,
					  isoutgoing =a._isoutgoing ,
					  applicationnumber =a._applicationnumber ,
					  linkfirmpersonid =a._linkfirmpersonid ,
					  inserteddatetime =a._inserteddatetime
				from unnest(v_partner_arry) a
			  where reconstitutionpartyid in (select a._reconstitutionpartyid from unnest(v_partner_arry) a)
				returning reconstitutionpartyid into v_reconstitutionpartyid;
 end if;
 
select firmpersonid into v_firmpersonid from kaverimrg.firmreconstitutionparty f 
where f.reconstitutionpartyid=v_reconstitutionpartyid; 
  select presentertypeid,linkfirmpersonid into v_presentertypeid,v_linkfirmpersonid
	from kaverimrg.firmreconstitutionparty where firmpersonid = v_firmpersonid;
	
	
	if ( v_presentertypeid = 8) and (v_linkfirmpersonid is not null) then
	null;
	end if;
	
	
	if ( v_presentertypeid = 8) and (v_linkfirmpersonid is null) 
	then
	update kaverimrg.firmreconstitutionparty set linkfirmpersonid = v_firmpersonid-1 where presentertypeid = 8 -- Guardian
	and firmpersonid = v_firmpersonid;
	end if;
	
	update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC103' 
 where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (1,2) ;	

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC105' 
 where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (6);	
 
	
 v_pid := array_append(v_pid,v_reconstitutionpartyid);
 
  END LOOP;
  return array_append(v_pid,1::bigint);
 end if;
 
return v_pid;

end;
$$;


ALTER FUNCTION kaverimrg.fn_updateinsertreconstitutionpartydetails(p_partydetails kaverimrg.type_insertreconstitutionpartydetails[]) OWNER TO postgres;

--
-- Name: fn_updateinsertreconstitutionpresenterdetails(kaverimrg.type_insertreconstitutionpartydetails); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_updateinsertreconstitutionpresenterdetails(p_presenter kaverimrg.type_insertreconstitutionpartydetails DEFAULT NULL::kaverimrg.type_insertreconstitutionpartydetails) RETURNS bigint
    LANGUAGE plpgsql
    AS $$




declare
v_applicationnumber character varying;
v_reconstitutionpartyid bigint;
v_presenterid bigint;
v_presentertypeid bigint;
v_cnt bigint;

begin


			
				
			
		v_presenterid:=null;
		v_presentertypeid:=null;
	
		select count(*)  into v_cnt from kaverimrg.firmreconstitutionparty where 
		 reconstitutionpartyid=p_presenter._reconstitutionpartyid ;
		 
					
		 select reconstitutionpartyid,presentertypeid  into  v_presenterid,v_presentertypeid
		 from kaverimrg.firmreconstitutionparty
		 where applicationnumber=p_presenter._applicationnumber 
		and presentertypeid in (1,2) limit 1; 
		raise notice 'presenterid %,presenter_typeid %',v_presenterid,v_presentertypeid;
			if v_presenterid is null and v_presentertypeid is null and v_cnt=0 then 
			
			raise notice 'inside insert of new entry';
			
			insert into kaverimrg.firmreconstitutionparty
			 			 (
							  reconstitutionpartyid,
							  reconstitutionid,
							  firmpersonid,
							  salutation,
							  firstname,
							  middlename,
							  lastname,
							  relationship,
							  relativename,
							  dob,
							  gender,
							  age,
							  occupation,
							  phoneno,
							  emailid,
							  prehousebuildname,
							  prestreetname,
							  prestatecode,
							  predistrictcode,
							  pretalukacode,
							  prehoblicode,
							  precityvillagecode,
							  prepincode,
							  ispresentaddresssameaspermanent,
							  perhousebuildname,
							  perstreetname,
							  perstatecode,
							  perdistrictcode,
							  pertalukacode,
							  perhoblicode,
							  percityvillagecode,
							  perpincode,
							  dateofsease,
							  dateofjoin,
							  isnewentry,
							  identityproof_idprooftypeid,
							  identityproofidpath,
							  addressproof_idprooftypeid,
							  addressproofidpath,
							  gpaagentpath,
							  presentertypeid,
							  proofofauthorisationfortheagentid,
							  proofofauthorisationfortheagentpath,
							  isincoming,
							  isoutgoing,
							  applicationnumber,
							  linkfirmpersonid,
							  inserteddatetime
							  )
								select 
								nextval('kaverimrg.reconstitutionpartyid_seq'),
								p_presenter._reconstitutionid,
								p_presenter._firmpersonid,
								p_presenter._salutation ,
								p_presenter._firstname ,
								p_presenter._middlename,
								p_presenter._lastname ,
								p_presenter._relationship ,
								p_presenter._relativename ,
								p_presenter._dob ,
								p_presenter._gender,
								p_presenter._age  ,
								p_presenter._occupation ,
								p_presenter._phoneno ,
								p_presenter._email ,
								p_presenter._prehousebuildname,
								p_presenter._prestreetname,
								p_presenter._prestatecode,
								p_presenter._predistrictcode,
								p_presenter._pretalukacode,
								p_presenter._prehoblicode,
								p_presenter._precityvillagecode,
								p_presenter._prepincode,
								p_presenter._ispresentaddresssameaspermanent,
								p_presenter._perhousebuildname,
								p_presenter._perstreetname,
								p_presenter._perstatecode,
								p_presenter._perdistrictcode,
								p_presenter._pertalukacode,
								p_presenter._perhoblicode,
								p_presenter._percityvillagecode,
								p_presenter._perpincode,
								p_presenter._dateofsease,
								p_presenter._dateofjoin,
								p_presenter._isnewentry,
								p_presenter._identityproof_idprooftypeid,
								p_presenter._identityproofidpath,
								p_presenter._addressproof_idprooftypeid,
								p_presenter._addressproofidpath,
								p_presenter._gpaagentpath,
								p_presenter._presentertypeid ,
								p_presenter._proofofauthorisationfortheagentid  ,
								p_presenter._proofofauthorisationfortheagentpath ,
								p_presenter._isincoming ,
								p_presenter._isoutgoing ,
								p_presenter._applicationnumber ,
								p_presenter._linkfirmpersonid ,
								p_presenter._inserteddatetime
							 
								returning reconstitutionpartyid into v_reconstitutionpartyid;
			
			  elsif v_presenterid=p_presenter._reconstitutionpartyid  then
			  
			  raise notice 'inside existing reconstitution id ';
			  
			  update kaverimrg.firmreconstitutionparty 
								 set  
								 --reconstitutionpartyid =_reconstitutionpartyid,
					 -- reconstitutionid =p_presenter._reconstitutionid,
					  firmpersonid =p_presenter._firmpersonid,
					  salutation =p_presenter._salutation ,
					  firstname =p_presenter._firstname ,
					  middlename =p_presenter._middlename,
					  lastname =p_presenter._lastname ,
					  relationship =p_presenter._relationship ,
					  relativename =p_presenter._relativename ,
					  dob =p_presenter._dob ,
					  gender =p_presenter._gender,
					  age =p_presenter._age  ,
					  occupation =p_presenter._occupation ,
					  phoneno =p_presenter._phoneno ,
					  emailid =p_presenter._email ,
					  prehousebuildname =p_presenter._prehousebuildname,
					  prestreetname =p_presenter._prestreetname,
					  prestatecode =p_presenter._prestatecode,
					  predistrictcode =p_presenter._predistrictcode,
					  pretalukacode =p_presenter._pretalukacode,
					  prehoblicode =p_presenter._prehoblicode,
					  precityvillagecode =p_presenter._precityvillagecode,
					  prepincode =p_presenter._prepincode,
					  ispresentaddresssameaspermanent =p_presenter._ispresentaddresssameaspermanent,
					  perhousebuildname =p_presenter._perhousebuildname,
					  perstreetname =p_presenter._perstreetname,
					  perstatecode =p_presenter._perstatecode,
					  perdistrictcode =p_presenter._perdistrictcode,
					  pertalukacode =p_presenter._pertalukacode,
					  perhoblicode =p_presenter._perhoblicode,
					  percityvillagecode =p_presenter._percityvillagecode,
					  perpincode =p_presenter._perpincode,
					  dateofsease =p_presenter._dateofsease ,
					  dateofjoin=p_presenter._dateofjoin,
					  isnewentry =p_presenter._isnewentry,
					  identityproof_idprooftypeid =p_presenter._identityproof_idprooftypeid,
					  identityproofidpath =p_presenter._identityproofidpath,
					  addressproof_idprooftypeid =p_presenter._addressproof_idprooftypeid,
					  addressproofidpath =p_presenter._addressproofidpath,
					  gpaagentpath =p_presenter._gpaagentpath,
					  presentertypeid =p_presenter._presentertypeid ,
					  proofofauthorisationfortheagentid =p_presenter._proofofauthorisationfortheagentid  ,
					  proofofauthorisationfortheagentpath =p_presenter._proofofauthorisationfortheagentpath ,
					  isincoming =p_presenter._isincoming ,
					  isoutgoing =p_presenter._isoutgoing ,
					  applicationnumber =p_presenter._applicationnumber ,
					  linkfirmpersonid =p_presenter._linkfirmpersonid ,
					  inserteddatetime =p_presenter._inserteddatetime
					  where reconstitutionpartyid=p_presenter._reconstitutionpartyid 
				returning reconstitutionpartyid into v_reconstitutionpartyid;
					  
			elsif v_presentertypeid =2  then 
			
			raise notice 'inside one agent present';
			
			  raise notice 'already one agent as presenter present';
					 return null;
					
					
			elsif v_presentertypeid=1 then 
			
			
			raise notice 'inside one partner as presenter';
			
			 	 update kaverimrg.firmreconstitutionparty set presentertypeid=6 
			  		 where reconstitutionpartyid=v_presenterid ;
			 	 update kaverimrg.firmreconstitutionparty 
								 set  
								 --reconstitutionpartyid =_reconstitutionpartyid,
					 -- reconstitutionid =p_presenter._reconstitutionid,
					  firmpersonid =p_presenter._firmpersonid,
					  salutation =p_presenter._salutation ,
					  firstname =p_presenter._firstname ,
					  middlename =p_presenter._middlename,
					  lastname =p_presenter._lastname ,
					  relationship =p_presenter._relationship ,
					  relativename =p_presenter._relativename ,
					  dob =p_presenter._dob ,
					  gender =p_presenter._gender,
					  age =p_presenter._age  ,
					  occupation =p_presenter._occupation ,
					  phoneno =p_presenter._phoneno ,
					  emailid =p_presenter._email ,
					  prehousebuildname =p_presenter._prehousebuildname,
					  prestreetname =p_presenter._prestreetname,
					  prestatecode =p_presenter._prestatecode,
					  predistrictcode =p_presenter._predistrictcode,
					  pretalukacode =p_presenter._pretalukacode,
					  prehoblicode =p_presenter._prehoblicode,
					  precityvillagecode =p_presenter._precityvillagecode,
					  prepincode =p_presenter._prepincode,
					  ispresentaddresssameaspermanent =p_presenter._ispresentaddresssameaspermanent,
					  perhousebuildname =p_presenter._perhousebuildname,
					  perstreetname =p_presenter._perstreetname,
					  perstatecode =p_presenter._perstatecode,
					  perdistrictcode =p_presenter._perdistrictcode,
					  pertalukacode =p_presenter._pertalukacode,
					  perhoblicode =p_presenter._perhoblicode,
					  percityvillagecode =p_presenter._percityvillagecode,
					  perpincode =p_presenter._perpincode,
					  dateofsease =p_presenter._dateofsease ,
					  dateofjoin=p_presenter._dateofjoin,
					  isnewentry =p_presenter._isnewentry,
					  identityproof_idprooftypeid =p_presenter._identityproof_idprooftypeid,
					  identityproofidpath =p_presenter._identityproofidpath,
					  addressproof_idprooftypeid =p_presenter._addressproof_idprooftypeid,
					  addressproofidpath =p_presenter._addressproofidpath,
					  gpaagentpath =p_presenter._gpaagentpath,
					  presentertypeid =p_presenter._presentertypeid ,
					  proofofauthorisationfortheagentid =p_presenter._proofofauthorisationfortheagentid  ,
					  proofofauthorisationfortheagentpath =p_presenter._proofofauthorisationfortheagentpath ,
					  isincoming =p_presenter._isincoming ,
					  isoutgoing =p_presenter._isoutgoing ,
					  applicationnumber =p_presenter._applicationnumber ,
					  linkfirmpersonid =p_presenter._linkfirmpersonid ,
					  inserteddatetime =p_presenter._inserteddatetime
					  where reconstitutionpartyid=p_presenter._reconstitutionpartyid 
				returning reconstitutionpartyid into v_reconstitutionpartyid;
			
			else 
			raise notice 'inside else';
			update kaverimrg.firmreconstitutionparty 
								 set  
								 --reconstitutionpartyid =_reconstitutionpartyid,
					 -- reconstitutionid =p_presenter._reconstitutionid,
					  firmpersonid =p_presenter._firmpersonid,
					  salutation =p_presenter._salutation ,
					  firstname =p_presenter._firstname ,
					  middlename =p_presenter._middlename,
					  lastname =p_presenter._lastname ,
					  relationship =p_presenter._relationship ,
					  relativename =p_presenter._relativename ,
					  dob =p_presenter._dob ,
					  gender =p_presenter._gender,
					  age =p_presenter._age  ,
					  occupation =p_presenter._occupation ,
					  phoneno =p_presenter._phoneno ,
					  emailid =p_presenter._email ,
					  prehousebuildname =p_presenter._prehousebuildname,
					  prestreetname =p_presenter._prestreetname,
					  prestatecode =p_presenter._prestatecode,
					  predistrictcode =p_presenter._predistrictcode,
					  pretalukacode =p_presenter._pretalukacode,
					  prehoblicode =p_presenter._prehoblicode,
					  precityvillagecode =p_presenter._precityvillagecode,
					  prepincode =p_presenter._prepincode,
					  ispresentaddresssameaspermanent =p_presenter._ispresentaddresssameaspermanent,
					  perhousebuildname =p_presenter._perhousebuildname,
					  perstreetname =p_presenter._perstreetname,
					  perstatecode =p_presenter._perstatecode,
					  perdistrictcode =p_presenter._perdistrictcode,
					  pertalukacode =p_presenter._pertalukacode,
					  perhoblicode =p_presenter._perhoblicode,
					  percityvillagecode =p_presenter._percityvillagecode,
					  perpincode =p_presenter._perpincode,
					  dateofsease =p_presenter._dateofsease ,
					  dateofjoin=p_presenter._dateofjoin,
					  isnewentry =p_presenter._isnewentry,
					  identityproof_idprooftypeid =p_presenter._identityproof_idprooftypeid,
					  identityproofidpath =p_presenter._identityproofidpath,
					  addressproof_idprooftypeid =p_presenter._addressproof_idprooftypeid,
					  addressproofidpath =p_presenter._addressproofidpath,
					  gpaagentpath =p_presenter._gpaagentpath,
					  presentertypeid =p_presenter._presentertypeid ,
					  proofofauthorisationfortheagentid =p_presenter._proofofauthorisationfortheagentid  ,
					  proofofauthorisationfortheagentpath =p_presenter._proofofauthorisationfortheagentpath ,
					  isincoming =p_presenter._isincoming ,
					  isoutgoing =p_presenter._isoutgoing ,
					  applicationnumber =p_presenter._applicationnumber ,
					  linkfirmpersonid =p_presenter._linkfirmpersonid ,
					  inserteddatetime =p_presenter._inserteddatetime
					  where reconstitutionpartyid=p_presenter._reconstitutionpartyid 
				returning reconstitutionpartyid into v_reconstitutionpartyid;
			
			  
			
			end if;
			  
			           
			
	
		select p_presenter._applicationnumber into v_applicationnumber;
		select p_presenter._presentertypeid into v_presentertypeid;

		update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC103' 
		where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (1,2) ;	

		update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC105' 
		where ad.applicationnumber in (v_applicationnumber)and v_presentertypeid in (6);	

	 
  
  return v_reconstitutionpartyid;
 
 end;
$$;


ALTER FUNCTION kaverimrg.fn_updateinsertreconstitutionpresenterdetails(p_presenter kaverimrg.type_insertreconstitutionpartydetails) OWNER TO postgres;

--
-- Name: fn_upload_documents_dissolution(character varying, integer, character varying, integer, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_documents_dissolution(_applicationnumber character varying, _dissolutiondeedid integer, _dissolutiondeedpath character varying, _affidavitid integer, _affidavitpath character varying, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
v_applicationnumber text;
v_cnt integer;

begin

update kaverimrg.firm_dissolution fd
    set 
    dissolutiondeedid=_dissolutiondeedid,
	dissolutiondeedpath=_dissolutiondeedpath,
	affidavitid=_affidavitid,
	affidavitpath=_affidavitpath,
	proofofauthorisationfortheagentid=_proofofauthorisationfortheagentid,
	Proofofauthorisationfortheagentpath=_Proofofauthorisationfortheagentpath,
	Supportingdocument1path=_Supportingdocument1path,
	Supportingdocument2path=_Supportingdocument2path
	
where 	
	fd.applicationnumber = _applicationnumber 
	returning fd.applicationnumber into v_applicationnumber;
	
	
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FD106' 
    where applicationnumber =_applicationnumber;	
	
return v_applicationnumber;

end;
$$;


ALTER FUNCTION kaverimrg.fn_upload_documents_dissolution(_applicationnumber character varying, _dissolutiondeedid integer, _dissolutiondeedpath character varying, _affidavitid integer, _affidavitpath character varying, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) OWNER TO postgres;

