--
-- Name: fn_upload_documents_firm(kaverimrg.type_firmuploaddoc[], kaverimrg.type_witnessfirmuploaddoc[], kaverimrg.type_branchuploaddoc[], character varying, character varying, integer, character varying, character varying, character varying, integer, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_documents_firm(firmuploaddoc kaverimrg.type_firmuploaddoc[], witnessfirmuploaddoc kaverimrg.type_witnessfirmuploaddoc[], branchuploaddoc kaverimrg.type_branchuploaddoc[], _applicationnumber character varying, _form_1path character varying, _partnershipdeedid integer, _partnershipdeedpath character varying, _documentnumber_e_stamp_challannumber character varying, _affidavit character varying, _firmaddressproofid integer, _firmaddressproofidpath character varying, _newfirmproofofauthorisationfortheagentid integer, _newfirmproofofauthorisationfortheagentidpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) RETURNS TABLE(applicationnumber character varying, _currentstatus character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE
--v_array v_upload_arry%type;
v_applicationnumber varchar;
v_newfirmidentityproofid int;
v_row kaverimrg.type_firmuploaddoc[];
v_row1 kaverimrg.type_witnessfirmuploaddoc[];
v_row2 kaverimrg.type_branchuploaddoc[];
v_presentertypeid int;
v_arry record;
v_witnesarry record;
v_brancharry record;
v_currentstatus varchar;

begin

v_applicationnumber:=_applicationnumber;

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(firmuploaddoc))
	loop
		for v_arry in (select a._newfirmidentityproofid,a._newfirmidentityproofidpath,
					   a._newfirmaddressproofid,a._newfirmaddressproofidpath,
					   a._firmpersonid,a._presentertypeid  from  unnest(v_row) a)
		

		loop
		update kaverimrg.firmparty f set 
   		identityproofid =v_arry._newfirmidentityproofid,
		identityproofidpath=v_arry._newfirmidentityproofidpath,
        addressproofid=v_arry._newfirmaddressproofid,
        addressproofidpath=v_arry._newfirmaddressproofidpath
		
		where 
		 f.firmpersonid=v_arry._firmpersonid and f.presentertypeid =v_arry._presentertypeid;

		end loop;
	end loop;
	
	
--2

	for v_row1 in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(witnessfirmuploaddoc))
	loop
		for v_witnesarry in (select a._newfirmidentityproofid,a._newfirmidentityproofidpath,
					   a._newfirmaddressproofid,a._newfirmaddressproofidpath,
					   a._firmwitnessid from  unnest(v_row1) a)
		
		loop
		update kaverimrg.frm_witnessdetails w set 
   		identityproofid =v_witnesarry._newfirmidentityproofid,
		identityproofidpath=v_witnesarry._newfirmidentityproofidpath,
        addressproofid=v_witnesarry._newfirmaddressproofid,
        addressproofidpath=v_witnesarry._newfirmaddressproofidpath
		
		where 
		 w.firmwitnessid=v_witnesarry._firmwitnessid;

		end loop;
	end loop;
	
	--3
	
	for v_row2 in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(branchuploaddoc))
	loop
		for v_brancharry in (select a._branchdocument,
					   a._branchid from unnest(v_row2) a)
		
		loop
		update kaverimrg.firmbranches b set 
   	    branchdocument =v_brancharry._branchdocument
		where 
		 b.branchid=v_brancharry._branchid;

		end loop;
	end loop;
	
	
update kaverimrg.firmmaster fm
    set 
	form_1path = _form_1path, 
    --firmsignedformpath=_firmsignedformpath,
	partnershipdeedid=_partnershipdeedid,
	partnershipdeedpath=_partnershipdeedpath,
	document_challan_number=_documentnumber_e_stamp_challannumber,
	affidavit=_affidavit,
	firmaddressproofid=_firmaddressproofid,
	firmaddressproofidpath=_firmaddressproofidpath,
	supportingdocument1path=_supportingdocument1path,
	supportingdocument2path=_supportingdocument2path
	
where 	
	fm.applicationnumber = _applicationnumber 
	returning fm.applicationnumber into v_applicationnumber;

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR106' 
 where ad.applicationnumber = v_applicationnumber 
returning currentstatus into v_currentstatus ;
 
 
 update kaverimrg.firmparty fp 
set 
agentproofid=_Newfirmproofofauthorisationfortheagentid,
agentproofidpath=_Newfirmproofofauthorisationfortheagentidpath
where 
fp.applicationnumber=v_applicationnumber and fp.presentertypeid in (2,1);
    
return query 
select v_applicationnumber,v_currentstatus;

end;
$$;


ALTER FUNCTION kaverimrg.fn_upload_documents_firm(firmuploaddoc kaverimrg.type_firmuploaddoc[], witnessfirmuploaddoc kaverimrg.type_witnessfirmuploaddoc[], branchuploaddoc kaverimrg.type_branchuploaddoc[], _applicationnumber character varying, _form_1path character varying, _partnershipdeedid integer, _partnershipdeedpath character varying, _documentnumber_e_stamp_challannumber character varying, _affidavit character varying, _firmaddressproofid integer, _firmaddressproofidpath character varying, _newfirmproofofauthorisationfortheagentid integer, _newfirmproofofauthorisationfortheagentidpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) OWNER TO postgres;

--
-- Name: fn_upload_documents_firm_1st_oct_2023(kaverimrg.type_firmuploaddoc[], kaverimrg.type_witnessfirmuploaddoc[], kaverimrg.type_branchuploaddoc[], character varying, character varying, integer, character varying, character varying, character varying, integer, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_documents_firm_1st_oct_2023(firmuploaddoc kaverimrg.type_firmuploaddoc[], witnessfirmuploaddoc kaverimrg.type_witnessfirmuploaddoc[], branchuploaddoc kaverimrg.type_branchuploaddoc[], _applicationnumber character varying, _form_1path character varying, _partnershipdeedid integer, _partnershipdeedpath character varying, _documentnumber_e_stamp_challannumber character varying, _affidavit character varying, _firmaddressproofid integer, _firmaddressproofidpath character varying, _newfirmproofofauthorisationfortheagentid integer, _newfirmproofofauthorisationfortheagentidpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
--v_array v_upload_arry%type;
v_applicationnumber varchar;
v_newfirmidentityproofid int;
v_row kaverimrg.type_firmuploaddoc[];
v_row1 kaverimrg.type_witnessfirmuploaddoc[];
v_row2 kaverimrg.type_branchuploaddoc[];
v_presentertypeid int;
v_arry record;
v_witnesarry record;
v_brancharry record;

begin

v_applicationnumber:=_applicationnumber;

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(firmuploaddoc))
	loop
		for v_arry in (select a._newfirmidentityproofid,a._newfirmidentityproofidpath,
					   a._newfirmaddressproofid,a._newfirmaddressproofidpath,
					   a._firmpersonid,a._presentertypeid  from  unnest(v_row) a)
		

		loop
		update kaverimrg.firmparty f set 
   		identityproofid =v_arry._newfirmidentityproofid,
		identityproofidpath=v_arry._newfirmidentityproofidpath,
        addressproofid=v_arry._newfirmaddressproofid,
        addressproofidpath=v_arry._newfirmaddressproofidpath
		
		where 
		 f.firmpersonid=v_arry._firmpersonid and f.presentertypeid =v_arry._presentertypeid;

		end loop;
	end loop;
	
	
--2

	for v_row1 in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(witnessfirmuploaddoc))
	loop
		for v_witnesarry in (select a._newfirmidentityproofid,a._newfirmidentityproofidpath,
					   a._newfirmaddressproofid,a._newfirmaddressproofidpath,
					   a._firmwitnessid from  unnest(v_row1) a)
		
		loop
		update kaverimrg.frm_witnessdetails w set 
   		identityproofid =v_witnesarry._newfirmidentityproofid,
		identityproofidpath=v_witnesarry._newfirmidentityproofidpath,
        addressproofid=v_witnesarry._newfirmaddressproofid,
        addressproofidpath=v_witnesarry._newfirmaddressproofidpath
		
		where 
		 w.firmwitnessid=v_witnesarry._firmwitnessid;

		end loop;
	end loop;
	
	--3
	
	for v_row2 in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(branchuploaddoc))
	loop
		for v_brancharry in (select a._branchdocument,
					   a._branchid from unnest(v_row2) a)
		
		loop
		update kaverimrg.firmbranches b set 
   	    branchdocument =v_brancharry._branchdocument
		where 
		 b.branchid=v_brancharry._branchid;

		end loop;
	end loop;
	
	
update kaverimrg.firmmaster fm
    set 
	form_1path = _form_1path, 
    --firmsignedformpath=_firmsignedformpath,
	partnershipdeedid=_partnershipdeedid,
	partnershipdeedpath=_partnershipdeedpath,
	document_challan_number=_documentnumber_e_stamp_challannumber,
	affidavit=_affidavit,
	firmaddressproofid=_firmaddressproofid,
	firmaddressproofidpath=_firmaddressproofidpath,
	supportingdocument1path=_supportingdocument1path,
	supportingdocument2path=_supportingdocument2path
	
where 	
	fm.applicationnumber = _applicationnumber 
	returning fm.applicationnumber into v_applicationnumber;

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FR106' 
 where ad.applicationnumber = v_applicationnumber ;
 
 
 update kaverimrg.firmparty fp 
set 
agentproofid=_Newfirmproofofauthorisationfortheagentid,
agentproofidpath=_Newfirmproofofauthorisationfortheagentidpath
where 
fp.applicationnumber=v_applicationnumber and fp.presentertypeid in (2,1);
    
return v_applicationnumber;

end;
$$;


