--
-- Name: fn_upload_documents_reconstitution(kaverimrg.type_reconstitutionuploaddoc[], character varying, integer, character varying, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_documents_reconstitution(firmuploaddoc kaverimrg.type_reconstitutionuploaddoc[], _applicationnumber character varying, _reconstitutiondeedid integer, _reconstitutiondeedpath character varying, _documentnumber_e_stamp_challannumber character varying, _affidavitpath character varying, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentidpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
v_applicationnumber varchar;
v_row kaverimrg.type_reconstitutionuploaddoc[];
v_presentertypeid int;
v_arry record;

begin

v_applicationnumber:=_applicationnumber;

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(firmuploaddoc))
	loop
		for v_arry in (select a._identityproofid,a._identityproofidpath,
					   a._addressproofid,a._addressproofidpath,a._reconstitutionpartyid,
					   a._firmpersonid,a._presentertypeid  from  unnest(v_row) a)
		
		loop
		update kaverimrg.firmreconstitutionparty f set 
   		identityproof_idprooftypeid =v_arry._identityproofid,
		identityproofidpath=v_arry._identityproofidpath,
        addressproof_idprooftypeid=v_arry._addressproofid,
        addressproofidpath=v_arry._addressproofidpath
	
		where 
		 f.reconstitutionpartyid=v_arry._reconstitutionpartyid and 
		 f.firmpersonid=v_arry._firmpersonid and 
		 f.presentertypeid =v_arry._presentertypeid;

		end loop;
	end loop;
	
	
update kaverimrg.firmreconstitution fm
    set  
	reconstitutiondeedtypeid=_reconstitutiondeedid,
	reconstitutiondeedpath=_reconstitutiondeedpath,
	reconstitutiondeeddocument_challan_number=_documentnumber_e_stamp_challannumber,
	--affidavitid=_affidavitid,
	affidavitpath=_affidavitpath,
	proofofauthorisationfortheagentid=_proofofauthorisationfortheagentid,
	proofofauthorisationfortheagentpath=_proofofauthorisationfortheagentidpath,
	supportingdocument1path=_supportingdocument1path,
	supportingdocument2path=_supportingdocument2path

where 	
	fm.applicationnumber = _applicationnumber 
	returning fm.applicationnumber into v_applicationnumber;

update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FC106' 
 where ad.applicationnumber = v_applicationnumber ;
    
return v_applicationnumber;

end;
$$;


