--
-- Name: fn_upload_documentsamendment2(kaverimrg.upload_branch[], integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_documentsamendment2(kaverimrg.upload_branch[], _amendmentid integer, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _supportingdocument1path character varying DEFAULT NULL::character varying, _supportingdocument2path character varying DEFAULT NULL::character varying) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $_$

DECLARE
v_applicationnumber varchar;
v_upload_brch_array record;
v_amendmentbranchid bigint[];
v_amendmentpersonid bigint;

begin
	
FOR v_upload_brch_array in (select * from unnest($1)a)
loop

	update kaverimrg.amendmentfirmbranches fm
    set --signedformpath = v_upload_brch_array._signedformpath,
    	addressproofid = v_upload_brch_array._addressproofid,
    	addressproofidpath  = v_upload_brch_array._addressproofidpath
    	--proofofauthorisationfortheagentid  = v_upload_brch_array._proofofauthorisationfortheagentid,
    	--proofofauthorisationfortheagentpath = v_upload_brch_array._proofofauthorisationfortheagentpath,
    	--supporting_document1_path = v_upload_brch_array._supportingdocument1path,
    	--supporting_document2_path = v_upload_brch_array._supportingdocument2path	
		where amendmentbranchid = v_upload_brch_array._amendmentbranchid;
		
		select array_agg(a2.amendmentbranchid) into v_amendmentbranchid  from kaverimrg.amendmentfirmbranches a2 where amendmentbranchid in (select a._amendmentbranchid from unnest($1) a);
end loop;


	update kaverimrg.firmamendment fm
    set 
    proofofauthorisationfortheagentid=_proofofauthorisationfortheagentid,
	proofofauthorisationfortheagentpath=_proofofauthorisationfortheagentpath,
	supporting_document1_path=_supportingdocument1path,
	supporting_document2_path=_supportingdocument2path
    where fm.amendmentid = _amendmentid;
    
select applicationnumber into v_applicationnumber from kaverimrg.firmamendment f where amendmentid = _amendmentid;
	
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FA111' 
    where applicationnumber =v_applicationnumber;
	
return v_amendmentbranchid;

end;
$_$;


ALTER FUNCTION kaverimrg.fn_upload_documentsamendment2(kaverimrg.upload_branch[], _amendmentid integer, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _supportingdocument1path character varying, _supportingdocument2path character varying) OWNER TO postgres;

