-- Name: type_amendmentperson; Type: TABLE; Schema: kaverimrg; Owner: postgres
--

CREATE TABLE kaverimrg.type_amendmentperson (
    _namechangeaffidavitpath character varying,
    _idprooftypeid integer,
    _idproof character varying,
    _addressproofid integer,
    _addressproofidpath character varying,
    _firmpersonid bigint,
    _amendmentpersonid bigint,
    _presentertypeid integer
