--
-- Name: fn_upload_documentsamendment4(kaverimrg.type_amendmentminorperson[], integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_documentsamendment4(amendmentperson kaverimrg.type_amendmentminorperson[], _amendmentid integer, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _supporting_document1_path character varying, _supporting_document2_path character varying) RETURNS bigint[]
    LANGUAGE plpgsql
    AS $$

DECLARE
v_applicationnumber varchar;
v_cnt integer;
v_row kaverimrg.type_amendmentminorperson[];
v_arry record;
v_amendmentpersonid bigint;
v_pid bigint[];
v_amendmentid bigint;
v_presentertypeid integer;
begin

select presentertypeid into v_presentertypeid from kaverimrg.amendmentfirmparty where amendmentpersonid in 
(select a._amendmentpersonid from  unnest(v_row) a);

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(amendmentperson))
	loop
		for v_arry in (select a._idprooftypeid,
					   a._idproof,a._addressproofid,
					   a._addressproofidpath,a._firmpersonid,
					   a._amendmentpersonid,a._presentertypeid  from  unnest(v_row) a)
		
		loop
		update kaverimrg.amendmentfirmparty f set 
		idprooftypeid=v_arry._idprooftypeid,
        idproof=v_arry._idproof,
        addressproofid=v_arry._addressproofid,
		addressproofidpath=v_arry._addressproofidpath
		where 
		 f.firmpersonid=v_arry._firmpersonid and f.presentertypeid =v_arry._presentertypeid 
		 and f.amendmentpersonid=v_arry._amendmentpersonid and f.presentertypeid in (6)
		 returning f.amendmentpersonid into v_amendmentpersonid ;

		end loop;
	end loop;
	
	
-- 	select amendmentpersonid into v_amendmentpersonid from kaverimrg.amendmentfirmparty  where  amendmentid=_amendmentid
-- 	 and presentertypeid=2;
	 
-- 	 if v_amendmentpersonid is not null
-- 	 then 

update kaverimrg.firmamendment fm
    set 
    proofofauthorisationfortheagentid=_proofofauthorisationfortheagentid,
	proofofauthorisationfortheagentpath=_proofofauthorisationfortheagentpath,
	supporting_document1_path=_Supporting_document1_path,
	supporting_document2_path=_Supporting_document2_path
    where fm.amendmentid = _amendmentid
    returning _amendmentid into v_amendmentid;
	
--end if;

	select f.applicationnumber into v_applicationnumber from kaverimrg.amendmentfirmparty a
	inner join kaverimrg.firmamendment f on a.amendmentid=f.amendmentid
	where a.amendmentpersonid in (select b._amendmentpersonid from unnest(v_row) b);
	
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FA111' 
    where applicationnumber =v_applicationnumber;	

 v_pid := array_append(v_pid,v_amendmentpersonid);

return v_pid;

end;
$$;


