--

CREATE FUNCTION kaverimrg.fn_upload_documentsprotestentry(amendmentperson kaverimrg.type_protestentryperson[], _applicationnumber character varying, _proofofprotestid integer, _proofofprotestpath character varying, _presenteridentityproofid integer, _presenteridentityproofpath character varying, _presenteraddressproofid integer, _presenteraddressproofpath character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
v_applicationnumber varchar;
v_row kaverimrg.type_protestentryperson[];
v_arry record;
v_protestentrypersonid bigint;
begin

select protestentrypersonid into v_protestentrypersonid from kaverimrg.protestentryfirmparty where protestentrypersonid in 
(select a._protestentrypersonid from  unnest(v_row) a);

for v_row in (SELECT kaverimrg.fn_fetch_1d_arrayofarray(amendmentperson))
	loop
		for v_arry in (select a._partneridentityproofid,a._partneridentityproofpath,
					   a._partneraddressproofid,a._partneraddressproofpath,
					   a._protestentrypersonid  from  unnest(v_row) a)
		
		loop
		update kaverimrg.protestentryfirmparty f set 
   		partneridentityproofid =v_arry._partneridentityproofid,
		partneridentityproofpath=v_arry._partneridentityproofpath,
        partneraddressproofid=v_arry._partneraddressproofid,
        partneraddressproofpath=v_arry._partneraddressproofpath
		where 
		 f.protestentrypersonid=v_arry._protestentrypersonid
		  returning f.applicationnumber into v_applicationnumber;

		end loop;
	end loop;

update kaverimrg.protestentryfirmparty fm
    set 
proofofprotestid =_proofofprotestid,
proofofprotestpath=_proofofprotestpath,
presenteridentityproofid=_presenteridentityproofid,
presenteridentityproofpath=_presenteridentityproofpath,
presenteraddressproofid =_presenteraddressproofid,
presenteraddressproofpath=_presenteraddressproofpath
    where fm.applicationnumber =_applicationnumber
    returning applicationnumber into v_applicationnumber;
	
	
	update kaverimrg.ApplicantApplicationdetails set currentstatus='FP104' 
    where applicationnumber =_applicationnumber;	

return _applicationnumber;

end;
$$;


