--
-- Name: fn_upload_firmsignedformpath(character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fn_upload_firmsignedformpath(_firmnumber character varying, _firmsignedformpath character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$


DECLARE
v_firmnumber text;
begin

	--if _firmregistrationtypeid=1 then
	update kaverimrg.firmmaster 
    set 
	firmdigsignpath = _firmsignedformpath
	where 	
	applicationnumber = _firmnumber ;
	--returning applicationnumber into v_firmnumber;
	
	update kaverimrg.applicantapplicationdetails a
	set currentstatus ='FR119'
	where a.applicationnumber=_firmnumber and a.applicationtypeid=6;

	update kaverimrg.firmamendment
    set 
  	firmdigsignpath = _firmsignedformpath
	where 	
	applicationnumber = _firmnumber ;
	--returning applicationnumber into v_firmnumber;
	
	update kaverimrg.applicantapplicationdetails a
	set currentstatus ='FA122'
	where a.applicationnumber=_firmnumber and a.applicationtypeid=47;

	update kaverimrg.firmreconstitution f
    set 
     
  	firmdigsignpath = _firmsignedformpath
	where 	
	applicationnumber = _firmnumber ;
	--returning applicationnumber into v_firmnumber;
	
	update kaverimrg.applicantapplicationdetails a
	set currentstatus ='FC119'
	where a.applicationnumber=_firmnumber and a.applicationtypeid=48;
	

	update kaverimrg.firm_dissolution f
    set 
  	firmdigsignpath = _firmsignedformpath
	where 	
	applicationnumber = _firmnumber ;
	
	update kaverimrg.applicantapplicationdetails a
	set currentstatus ='FD120'
	where a.applicationnumber=_firmnumber and a.applicationtypeid=49;

return _firmnumber;

end;
$$;


ALTER FUNCTION kaverimrg.fn_upload_firmsignedformpath(_firmnumber character varying, _firmsignedformpath character varying) OWNER TO postgres;

