--
-- Name: fnuploaddocumentsamendment4(character varying, character varying, integer, character varying, integer, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.fnuploaddocumentsamendment4(_applicationnumber character varying, _signedformpath character varying, _idproofid integer, _idproofpath character varying, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _addressproofid integer, _addressproofidpath character varying, _supporting_document1_path character varying, _supporting_document2_path character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

DECLARE
v_applicationnumber varchar;
v_cnt int;

begin
	
	select count(*) into v_cnt from kaverimrg.amendmentminordetails where applicationnumber = _applicationnumber;

if v_cnt = 0 then

	insert into kaverimrg.amendmentminordetails(
		applicationnumber,
		signedformpath,
		idproofid,
		idproofpath,
		proofofauthorisationfortheagentid,
		proofofauthorisationfortheagentpath,
		addressproofid,
		addressproofidpath,
		supporting_document1_path,
		supporting_document2_path
		)
		values(
		_applicationnumber,
		_signedformpath,
		_idproofid,
		_idproofpath,
		_proofofauthorisationfortheagentid,
		_proofofauthorisationfortheagentpath,
		_addressproofid,
		_addressproofidpath,
		_supporting_document1_path,
		_supporting_document2_path
		);
else	
	update kaverimrg.amendmentminordetails set
		signedformpath = _signedformpath,
		idproofid = _idproofid,
		idproofpath = _idproofpath,
		proofofauthorisationfortheagentid = _proofofauthorisationfortheagentid,
		proofofauthorisationfortheagentpath = _proofofauthorisationfortheagentpath,
		addressproofid = _addressproofid,
		addressproofidpath = _addressproofidpath,
		supporting_document1_path = _supporting_document1_path,
		supporting_document2_path = _supporting_document2_path
		where applicationnumber = _applicationnumber returning applicationnumber into v_applicationnumber;
end if;
	
update kaverimrg.ApplicantApplicationdetails ad set currentstatus='FA110' 
where ad.applicationnumber = _applicationnumber 
returning ad.applicationnumber into v_applicationnumber;
	
return v_applicationnumber;

end;
$$;


ALTER FUNCTION kaverimrg.fnuploaddocumentsamendment4(_applicationnumber character varying, _signedformpath character varying, _idproofid integer, _idproofpath character varying, _proofofauthorisationfortheagentid integer, _proofofauthorisationfortheagentpath character varying, _addressproofid integer, _addressproofidpath character varying, _supporting_document1_path character varying, _supporting_document2_path character varying) OWNER TO postgres;

--
-- Name: get_sro_by_villagecode(bigint[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.get_sro_by_villagecode(p_values bigint[]) RETURNS json
    LANGUAGE plpgsql
    AS $$

declare
v_data_json json;
v_array_length numeric(100,0) := 0;
v_msg character varying(100) := null;
i integer;
begin
 v_array_length:= array_length(p_values,1);
  if (v_array_length > 0 ) then
--  for i in 1..v_array_length loop
select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
select a.srocode,b.sronamee,b.districtcode,d.districtnamee from kaverimrg.villagemaster a
inner join kaverimrg.sromaster b on a.srocode = b.srocode
inner join kaverimrg.districtmaster d on b.districtcode = d.districtcode
where a.villagecode in  ( select unnest(p_values) ) 
union
select sro.srocode,sro.sronamee,sro.districtcode, d.districtnamee from kaverimrg.sromaster sro 
inner join kaverimrg.districtmaster d 
on sro.districtcode=d.districtcode where sro.districtcode in (
select distinct districtcode from kaverimrg.sromaster s inner join kaverimrg.villagemaster v
on v.srocode = s.srocode and (v.villagecode) in (select unnest(p_values))) and sro.districtcode in (1,33,34,35,36)
union
select sro.srocode,sro.sronamee,sro.districtcode, d.districtnamee from kaverimrg.sromaster sro inner join kaverimrg.districtmaster d 
on sro.districtcode=d.districtcode where sro.districtcode in (
select distinct districtcode from kaverimrg.sromaster s inner join kaverimrg.villagemaster v
on v.srocode = s.srocode and (v.villagecode) in (select unnest(p_values))) 
	--and sro.districtcode in (1,33,34,35,36)	
	and sro.srocode = 206

union 
select 204,'Bangalore Development Authority',35, 'Gandhinagara' from kaverimrg.sromaster sro 
inner join kaverimrg.districtmaster d 
on sro.districtcode=d.districtcode where sro.districtcode in (
select distinct districtcode from kaverimrg.sromaster s inner join kaverimrg.villagemaster v
on v.srocode = s.srocode and (v.villagecode) in (select unnest(p_values))) and sro.districtcode in (1,33,34,35,36)
--or sro.srocode=204

	
/*
select sro.srocode,sro.sronamee,sro.districtcode,d.districtnamee 
from kaverimrg.sromaster sro 
inner join kaverimrg.districtmaster d on sro.districtcode = d.districtcode 
where sro.districtcode in (1,33,34,35,36) and 
exists (select 1 from kaverimrg.sromaster s, kaverimrg.villagemaster v  
	   where v.srocode = s.srocode and s.districtcode In (1,33,34,35,36) 
	and (v.villagecode) =any(p_values) ) 
	*/
	ORDER BY SRONAMEE
)
			as drodetails
	) dro;
	--  end loop;

	  	  end if;
		  --	  	 i=i+1;
	return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.get_sro_by_villagecode(p_values bigint[]) OWNER TO postgres;

