union all	
	select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaverimrg.districtmaster a right join kaverimrg.sromaster b on a.districtcode = b.districtcode
left join kaverimrg.villagemaster c on b.srocode = c.srocode
where a.districtcode not in (1,33,34,35,36) and
	 c.villagecode in (select unnest(p_values) ) ) as a order by a.districtcode,a.srocode
	
/*======================================*/
		   )
			as drodetails
	) dro;
	else
	select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(others))) as SRO_identify_concerned_DRO from (
	
/*======================================*/
	select * from (
select distinct a.districtcode,districtnamee,b.srocode,sronamee from 
kaverimrg.districtmaster a inner join kaverimrg.sromaster b on a.districtcode = b.districtcode
inner join kaverimrg.villagemaster c on b.srocode = c.srocode
where a.districtcode not in (1,33,34,35,36) and
	 c.villagecode in (select unnest(p_values))--(29013,687,23911)
)  as a order by a.districtcode,a.srocode
	
/*======================================*/
		   )
			as others
	) dro;
 end if;
	  	  end if;
	return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.get_sro_by_villagecode_chk(p_values bigint[]) OWNER TO postgres;

--
-- Name: get_sro_metadata_integer_records_by_villagecode(bigint[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.get_sro_metadata_integer_records_by_villagecode(p_values bigint[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
v_array_length numeric(100,0) := 0;
v_msg character varying(100) := null;
i integer;
begin
 v_array_length:= array_length(p_values,1);
  if (v_array_length > 0 ) then
--  for i in 1..v_array_length loop
select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(drodetails))) as SRO_identify_concerned_DRO from (
select a.srocode,b.sronamee,b.districtcode,d.districtnamee from kaverimrg.villagemaster a
inner join kaverimrg.sromaster b on a.srocode = b.srocode
inner join kaverimrg.districtmaster d on b.districtcode = d.districtcode
where a.villagecode in  (select unnest(p_values) ) /*(select villagecode from kaverimrg.villagemaster 
					where villagecode in (select unnest(p_values)))*/--= any('{23982,687}')
		   )
			as drodetails
	) dro;
	--  end loop;

	  	  end if;
		  --	  	 i=i+1;
	return v_data_json;
END;
$$;


ALTER FUNCTION kaverimrg.get_sro_metadata_integer_records_by_villagecode(p_values bigint[]) OWNER TO postgres;

--
-- Name: get_witness_from_party(bigint[]); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.get_witness_from_party(p_values bigint[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare
v_data_json json;
v_array_length numeric(100,0) := 0;
--v_msg character varying(100) := null;
i integer;
begin
  if (v_array_length > 0 ) then
select row_to_json(dro) into v_data_json
from (
select array_to_json(array_agg(row_to_json(witnessdetails))) as witness_identify_concerned_party from (
select a.witnessid,b.partyid,c.firstname||''||c.middlename||''||c.lastname as partyname
from kaverimrg.witnessinfo a inner join kaverimrg.partywitness b on a.witnessid = b.witnessid
inner join kaverimrg.partyinfo c on b.partyid = c.partyid
where c.partyid in (select unnest(p_values))
order by a.witnessid,b.partyid
  )
			as witnessdetails
	) witness;
  end if;
		  	  	-- i=i+1;
	return v_data_json;
END;
$$;


