--
-- Name: mis_booki_iii_iv(character varying, character varying, integer, character varying, character varying); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.mis_booki_iii_iv(IN v_passfromdate character varying, IN v_passtodate character varying, IN v_passsrocode integer, IN v_type character varying, IN v_docordmy character varying)
    LANGUAGE plpgsql
    AS $$                 -- kaverimrg_2


--delete From BookI_III_IV_Data

Begin

if V_DOCorDMY='DOC' -----------------------For DocWise---------------------------------------------
Then
	begin  -- Begin of 'DOC'

insert into kaverimrg.BookI_III_IV_Data
		select  
			S1.Month,
			S1.BookID,
			S1.DocNo, 
			S1.NatureOfDoc as NatureOfDoc,
			Coalesce(SSum.MarketValue,0) as MarketValue,
			Coalesce(SSum.Consideration,0) as Consideration
			,Coalesce(SR.RegistrationFees,0) as RegistrationFees,
			Coalesce(SF.ScanningFees,0) as ScanningFees, 
			Coalesce(SFine.Fine,0) as Fine, 
			Coalesce(SO.OtherFees,0) as OtherFees,
			Coalesce(SSum.GovtDuty,0) as GovtDuty,
			Coalesce(SSum.SurchargeDuty,0) as SurchargeDuty,
			Coalesce(SSum.CessDuty,0) as CessDuty ,
			'dd' as DDMMYY
		from
		
		(
			select  
				-- LEFT(CONVERT(varchar(4000),DocumentMAster.Stamp5DateTime,126),10) as Month, -- 2022-03-23
				LEFT(DocumentMAster.Stamp5DateTime::varchar,10) as Month , 
				DocumentMaster.FinalRegistrationNumber as DocNo,
				DocumentMaster.BookID as BookID ,
				PropertyMaster.DocumentID as DocID,
				RegistrationArticles.ArticleNameE as NatureOfDoc
				--sum(PropertyMaster.MarketValue) as MarketValue,
				--sum(PropertyMaster.Consideration)  as Consideration,
				--sum(PropertyMaster.GovtDuty) as GovtDuty,
				--sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				--sum(PropertyMaster.CessDuty) as CessDuty
			from 
				kaverimrg.PropertyMaster , 
				kaverimrg.DocumentMaster, 
				kaverimrg.RegistrationArticles		
		where 
				RegistrationArticles.RegArticleCode=DocumentMaster.RegArticleCode
				--and PropertyMaster.totalArea<>-7274 
				and DocumentMaster.DocumentID>15
				and PropertyMaster.DocumentID=DocumentMaster.DocumentID
				--and PropertyMaster.SROCode=DocumentMaster.SROCode
				--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
				--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
				
				and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0 
				and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
				
				
				and DocumentMaster.SROCode=V_PassSROCode
				--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
				and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''
				and DocumentMaster.BookID in(1,3,4,5,6,7,8,9,10)
		group by 
					PropertyMaster.DocumentID ,DocumentMaster.BookID,
					DocumentMAster.Stamp5DateTime, DocumentMaster.FinalRegistrationNumber
					,RegistrationArticles.ArticleNameE
			) as S1
		Left Outer Join
		(
		select 
			PropertyMaster.DocumentID as DocID,
			sum(PropertyMaster.MarketValue) as MarketValue,
			sum(PropertyMaster.Consideration)  as Consideration,
			sum(PropertyMaster.GovtDuty) as GovtDuty,
			sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
			sum(PropertyMaster.CessDuty) as CessDuty
		from 
			kaverimrg.PropertyMaster ,
			kaverimrg.DocumentMaster
		where 
			PropertyMaster.totalArea<>-7274 
			and DocumentMaster.DocumentID>15
			and PropertyMaster.DocumentID=DocumentMaster.DocumentID
			--and PropertyMaster.SROCode=DocumentMaster.SROCode
			--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
			--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
				and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
			and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
			and DocumentMaster.SROCode=V_PassSROCode
			--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
			and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
			and DocumentMaster.BookID in(1,5,6,7,8,9,10)   
		group by 
			PropertyMaster.DocumentID 
			
union
		select 
				PropertyMaster.DocumentID as DocID,
				sum(PropertyMaster.MarketValue) as MarketValue,
				sum(PropertyMaster.Consideration)  as Consideration,
				--Market_Val(PropertyMaster.DocumentID) as MarketValue ,
				--Consi_Val(PropertyMaster.DocumentID) as Consideration ,
				sum(PropertyMaster.GovtDuty) as GovtDuty,
				sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				sum(PropertyMaster.CessDuty) as CessDuty
		from 
				kaverimrg.PropertyMaster ,
				kaverimrg.DocumentMaster
		where 
				--PropertyMaster.totalArea<>-7274 
				DocumentMaster.DocumentID>15
				and PropertyMaster.DocumentID=DocumentMaster.DocumentID
				--and PropertyMaster.SROCode=DocumentMaster.SROCode
				--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
				--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
				and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
				and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and DocumentMaster.SROCode=V_PassSROCode
				--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
				and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
				and DocumentMaster.BookID in(3,4)
		group by 
				PropertyMaster.DocumentID 
		) as SSum
		on S1.DocID = SSum.DocID
Left Outer Join
		(
		SELECT 
				DocumentMaster.DocumentID as DocIDReg,
				sum(ReceiptDetails.AmountPaid) as RegistrationFees 
				from 
						kaverimrg.ReceiptMaster, 
						kaverimrg.ReceiptDetails, 
						kaverimrg.FeesRuleMaster , 
						kaverimrg.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode= 1--Registration Fee
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
					and DocumentMaster.SROCode=V_PassSROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
		) as SR
		on S1.DocID = SR.DocIDReg
left outer join 
			(
			SELECT 
				DocumentMaster.DocumentID as DocIDScan,
				sum(ReceiptDetails.AmountPaid) as ScanningFees 
				from 
					kaverimrg.ReceiptMaster, 
					kaverimrg.ReceiptDetails, 
					kaverimrg.FeesRuleMaster , 
					kaverimrg.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode= 2--Scanning Fee
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
					and DocumentMaster.SROCode=V_PassSROCode
				--	and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
--					and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
					DocumentMaster.DocumentID
			) as SF
		on 
			S1.DocID=SF.DocIDScan
left Outer join
			(
				SELECT DocumentMaster.DocumentID as DocIDOthr,
						sum(ReceiptDetails.AmountPaid) as OtherFees 
				from 
						kaverimrg.ReceiptMaster, 
						kaverimrg.ReceiptDetails, 
						kaverimrg.FeesRuleMaster , 
						kaverimrg.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode Not in(1,2,19,20)	--Other Fee(Except Registration Fee and Scanning Fee and Fine Under Sec 25 & 34)
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
						and DocumentMaster.SROCode=V_PassSROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
			) as SO
		on 
				S1.DocID=SO.DocIDOthr	
left Outer join
			(
				SELECT 
						DocumentMaster.DocumentID as DocIDFine,
						sum(ReceiptDetails.AmountPaid) as Fine 
				from 
						kaverimrg.ReceiptMaster, 
						kaverimrg.ReceiptDetails, 
						kaverimrg.FeesRuleMaster , 
						kaverimrg.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
					and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
					and ReceiptDetails.FeeRuleCode  in(19,20)	--Fine( Fine Under Sec 25 & 34)
					and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
					and DocumentMaster.DocumentID>15
						and DocumentMaster.SROCode=V_PassSROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
			) as SFine
		on 
				S1.DocID=SFine.DocIDFine	
		
		Order By S1.BookID;

end ;   -- End of V_DOCorDMY='DOC'


elseif V_DOCorDMY='DMY'  -----------------------For DMYwise-----------------------------------------
Then 
begin   -- Start V_DOCorDMY='DMY'

			insert into 
				kaverimrg.BookI_III_IV_Data
			select 
				case V_Type
							When 'mm' Then (Datename(mm,a.Month))+datename(yy,a.Month)
							When 'dd' Then	--convert(varchar,a.Month,103 )
											a.Month::varchar	
							When 'yy' Then	
									case 
										when month(a.Month) < 4 then cast((year(a.Month)-1) as varchar(4)) ||'-'|| right(cast((year(a.Month)) as varchar(4)),2)
										when month(a.Month) > 3 then cast((year(a.Month)) as varchar(4)) || '-' || right(cast((year(a.Month)+1) as varchar(4)) ,2)
									end
						End as Month,
				a.BookID as BookID,
				Count(a.DocNo) as DocNo,
				'' as NatureOfDoc,
				sum(a.MarketValue) as MarketValue,
				sum(a.Consideration) as Consideration,
				sum(a.RegistrationFees) as RegistrationFees,
				sum(a.ScanningFees) as ScanningFees,
				sum(a.Fine) as Fine,
				sum(a.OtherFees) as OtherFees,
				sum(a.GovtDuty) as GovtDuty,
				sum(a.SurchargeDuty) as SurchargeDuty,
				sum(a.CessDuty) as CessDuty
				,V_Type as DDMMYY
			
			from
			(
			
			select  
					S1.Month,
					S1.BookID,
					S1.DocNo, 
					S1.NatureOfDoc as NatureOfDoc,
					Coalesce(SSum.MarketValue,0) as MarketValue,
					Coalesce(SSum.Consideration,0) as Consideration,
					Coalesce(SR.RegistrationFees,0) as RegistrationFees,
					Coalesce(SF.ScanningFees,0) as ScanningFees,
					Coalesce(SFine.Fine,0) as Fine, 
					Coalesce(SO.OtherFees,0) as OtherFees,
					Coalesce(SSum.GovtDuty,0) as GovtDuty,
					Coalesce(SSum.SurchargeDuty,0) as SurchargeDuty,
					Coalesce(SSum.CessDuty,0) as CessDuty
			from
			
				(
				select  
						--LEFT(CONVERT(varchar(4000),DocumentMAster.Stamp5DateTime,126),10) as Month, 
						left(DocumentMAster.Stamp5DateTime::varchar,10) as Month,
						DocumentMaster.FinalRegistrationNumber as DocNo,
						DocumentMaster.BookID as BookID ,PropertyMaster.DocumentID as DocID,
						RegistrationArticles.ArticleNameE as NatureOfDoc
						--sum(PropertyMaster.MarketValue) as MarketValue,
						--sum(PropertyMaster.Consideration)  as Consideration,
						--sum(PropertyMaster.GovtDuty) as GovtDuty,
						--sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
						--sum(PropertyMaster.CessDuty) as CessDuty
					from 
							kaverimrg.PropertyMaster ,
							kaverimrg.DocumentMaster,
							kaverimrg.RegistrationArticles
				where 
						RegistrationArticles.RegArticleCode=DocumentMaster.RegArticleCode
						--and PropertyMaster.totalArea<>-7274 
						and DocumentMaster.DocumentID>15
						and PropertyMaster.DocumentID=DocumentMaster.DocumentID
						--and PropertyMaster.SROCode=DocumentMaster.SROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and DocumentMaster.SROCode=V_PassSROCode
						--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
						and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
						and DocumentMaster.BookID in(1,3,4,5,6,7,8,9,10)
			group by 
						PropertyMaster.DocumentID ,
						DocumentMaster.BookID,DocumentMAster.Stamp5DateTime
						,DocumentMaster.FinalRegistrationNumber
						,RegistrationArticles.ArticleNameE
			) as S1
Left Outer Join
			(
			select 
				PropertyMaster.DocumentID as DocID,
				sum(PropertyMaster.MarketValue) as MarketValue,
				sum(PropertyMaster.Consideration)  as Consideration,
				sum(PropertyMaster.GovtDuty) as GovtDuty,
				sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				sum(PropertyMaster.CessDuty) as CessDuty
			from 
					kaverimrg.PropertyMaster , 
					kaverimrg.DocumentMaster
			where 
					PropertyMaster.totalArea<>-7274 
					and DocumentMaster.DocumentID>15
					and PropertyMaster.DocumentID=DocumentMaster.DocumentID
					--and PropertyMaster.SROCode=DocumentMaster.SROCode
				--	and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
				--	and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and DocumentMaster.SROCode=V_PassSROCode
					--and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and DocumentMaster.BookID in(1,5,6,7,8,9,10)     
			group by 
					PropertyMaster.DocumentID 
union
			select 
				PropertyMaster.DocumentID as DocID,
				sum(PropertyMaster.MarketValue) as MarketValue,
				sum(PropertyMaster.Consideration)  as Consideration,
				--Market_Val(PropertyMaster.DocumentID) as MarketValue ,
				--Consi_Val(PropertyMaster.DocumentID) as Consideration ,
				sum(PropertyMaster.GovtDuty) as GovtDuty,
				sum(PropertyMaster.AdditionalDuty) as SurchargeDuty,
				sum(PropertyMaster.CessDuty) as CessDuty
			from 
					kaverimrg.PropertyMaster ,
					kaverimrg.DocumentMaster
			where 
					--PropertyMaster.totalArea<>-7274 
					DocumentMaster.DocumentID>15
					and PropertyMaster.DocumentID=DocumentMaster.DocumentID
					--and PropertyMaster.SROCode=DocumentMaster.SROCode
					--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
					--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
					and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
					and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					and DocumentMaster.SROCode=V_PassSROCode
				--	and isnull(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and COALESCE(DocumentMaster.FinalRegistrationNumber,'')<>''	
					and DocumentMaster.BookID in(3,4)
			group by 
				PropertyMaster.DocumentID 
			
			) as SSum
		on 
				S1.DocID = SSum.DocID
Left Outer Join
			(
			SELECT 
					DocumentMaster.DocumentID as DocIDReg,
					sum(ReceiptDetails.AmountPaid) as RegistrationFees 
			from 
					kaverimrg.ReceiptMaster,
					kaverimrg.ReceiptDetails,
					kaverimrg.FeesRuleMaster ,
					kaverimrg.DocumentMaster
			where 	ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode= 1--Registration Fee
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
					
						and  ReceiptMaster.receipttypeid=1
				group by 
						DocumentMaster.DocumentID
			) as SR
			on 
					S1.DocID = SR.DocIDReg
	left outer join 
			(
			SELECT 	DocumentMaster.DocumentID as DocIDScan,
					sum(ReceiptDetails.AmountPaid) as ScanningFees 
					from 
						kaverimrg.ReceiptMaster,
						kaverimrg.ReceiptDetails,
						kaverimrg.FeesRuleMaster ,
						kaverimrg.DocumentMaster
					where ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode= 2--Scanning Fee
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and  ReceiptMaster.receipttypeid=1
					group by 
							DocumentMaster.DocumentID
			) as SF
		on 
				S1.DocID=SF.DocIDScan
left Outer join
			(
			SELECT DocumentMaster.DocumentID as DocIDOthr,
					sum(ReceiptDetails.AmountPaid) as OtherFees 
			from 
						kaverimrg.ReceiptMaster,
						kaverimrg.ReceiptDetails,
						kaverimrg.FeesRuleMaster ,
						kaverimrg.DocumentMaster
			where 
					ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode Not in(1,2,19,20)	--Other Fee(Except Registration Fee and Scanning Fee and Fine Under Sec 25 & 34)
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and  ReceiptMaster.receipttypeid=1
					group by 
						DocumentMaster.DocumentID
			) as SO
			on S1.DocID=SO.DocIDOthr	
left Outer join
			(
			SELECT DocumentMaster.DocumentID as DocIDFine,
					sum(ReceiptDetails.AmountPaid) as Fine 
			from kaverimrg.ReceiptMaster,
						kaverimrg.ReceiptDetails,
						kaverimrg.FeesRuleMaster ,
						kaverimrg.DocumentMaster
				where 
						ReceiptMaster.receiptid=ReceiptDetails.ReceiptId  
						and FeesRuleMaster.FeeRuleCode=ReceiptDetails.FeeRuleCode 
						and ReceiptDetails.FeeRuleCode  in(19,20)	--Fine( Fine Under Sec 25 & 34)
						and ReceiptMaster.DocumentId= DocumentMaster.DocumentID
						and DocumentMaster.DocumentID>15
							and DocumentMaster.SROCode=V_PassSROCode
						--and DATEDIFF ( d , DocumentMaster.Stamp5DateTime ,convert(datetime, V_PassFromDate ,103))<=0
						--and DATEDIFF ( d ,DocumentMaster.Stamp5DateTime ,convert(datetime,V_PassToDate,103))>=0
						and ( Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassFromDate::timestamp ) <=0
						and Date_Part('Day', DocumentMaster.Stamp5DateTime - V_PassToDate::timestamp ) >=0 )
						and  ReceiptMaster.receipttypeid=1
					group by 
							DocumentMaster.DocumentID
			) as SFine
		on 
				S1.DocID=SFine.DocIDFine		
				
			) as a 
			group by 
					a.BookID,
				case V_Type
					When 'mm' Then (Datename(mm,a.Month))+datename(yy,a.Month)
					When 'dd' Then	-- convert(varchar,a.Month,103 )
										a.Month::varchar
					When 'yy' Then	
						case 
							when month(a.Month) < 4 then cast((year(a.Month)-1) as varchar(4))|| '-' || right(cast((year(a.Month)) as varchar(4)),2)
							when month(a.Month) > 3 then cast((year(a.Month)) as varchar(4)) || '-' || right(cast((year(a.Month)+1) as varchar(4)) ,2)
					    end -- end of 2nd case 
				end; -- end of 1st case
		--End ;
End ; -- End of V_DOCorDMY='DMY'

End if ;


--End; -- End of First Begin 

End $$;


ALTER PROCEDURE kaverimrg.mis_booki_iii_iv(IN v_passfromdate character varying, IN v_passtodate character varying, IN v_passsrocode integer, IN v_type character varying, IN v_docordmy character varying) OWNER TO postgres;

--
-- Name: sf_dashboard_application_nomenclature_count(); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
--

CREATE FUNCTION kaverimrg.sf_dashboard_application_nomenclature_count() RETURNS TABLE(_applicationstartdate timestamp without time zone, _applicationenddate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
_DAYS integer;
_DAYS1 integer;
BEGIN
/*select date_trunc('month',
 current_date)+'1month'::interval::interval - date_trunc('month', current_date) into _DAYS1 ;*/
SELECT (applicationenddate::date - applicationstartdate::date ) into _DAYS from kaverimrg.applicantapplicationdetails;
if _DAYS < 30 then
   RETURN QUERY
  select extract('day' from date_trunc('week', applicationstartdate) -
                   date_trunc('week', date_trunc('month', applicationstartdate))) / 7 as weekno,
left(applicationnumber,3) nomenclature,count(*)
 from kaverimrg.applicantapplicationdetails where  applicationstartdate 
 between _applicationstartdate and _applicationenddate		
 group by weekno,nomenclature;
 else
 RETURN QUERY
 select TO_CHAR(applicationstartdate, 'Month') as month,left(applicationnumber,3) nomenclature,count(*)
 from kaverimrg.applicantapplicationdetails where  applicationstartdate 
				   between  _applicationstartdate and _applicationenddate			
 group by month,nomenclature;
 end if;
	END;
$$;


ALTER FUNCTION kaverimrg.sf_dashboard_application_nomenclature_count() OWNER TO postgres;

--
-- Name: sf_dashboard_application_nomenclature_count(timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimrg; Owner: postgres
