--
-- Name: sp_court_orders(integer, integer, character varying[], integer, character varying[]); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_court_orders(IN v_srocode integer, IN v_currentpropertytypeid integer, IN v_currentnumber character varying[], IN v_oldpropertytypeid integer, IN v_oldnumber character varying[])
    LANGUAGE plpgsql
    AS $$
BEGIN
SELECT  ID
      ,BPN.SROCode SRO,BPN.PropertyID,
 BPN.injuction_or_stay_flag,
      BPN.OrderID,CurrentPropertyTypeID
      ,CurrentNumber,OldPropertyTypeID
      ,OldNumber,BPN.Description Description1
      ,Survey_No,Surnoc
      ,Hissa_No,BP.PropertyDescription
 ,BP.IsAgriculturalProperty,BP.EastBoundary EastBoundary
 ,BP.NorthBoundary NorthBoundary,BP.WestBoundary WestBoundary
 ,BP.SouthBoundary SouthBoundary,BP.Area Area
 ,BP.MeasurementUnit,MUM.DescriptionEnglish
 ,CO.OrderNumber COURT_ORDER_NUMBER,CO.Description Description
 ,CO.OrderEntryDateTime,CO.IsCancelled
 ,CO.ReasonOfCancellation
  FROM kaverimrg.BannedPropertyNumbers BPN inner join kaverimrg.BannedProperties BP
  on
  BPN.PropertyID=BP.PropertyID and BPN.SROCode=BP.SROCode
  inner join kaverimrg.CourtOrders CO
  on
  BP.SROCode=CO.SROCode and BP.OrderID=CO.OrderID
  inner join kaverimrg.MeasUnitMaster MUM
  on MUM.UnitID=BP.MeasurementUnit
  where BPN.SROCode=V_SROCode and CurrentPropertyTypeID=V_CurrentPropertyTypeID and CurrentNumber=V_CurrentNumber
   or BPN.SROCode=V_SROCode and OldPropertyTypeID=V_OldPropertyTypeID and OldNumber=V_OldNumber;
   END;
$$;


ALTER PROCEDURE kaverimrg.sp_court_orders(IN v_srocode integer, IN v_currentpropertytypeid integer, IN v_currentnumber character varying[], IN v_oldpropertytypeid integer, IN v_oldnumber character varying[]) OWNER TO postgres;

--
-- Name: sp_court_orders1(); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_court_orders1()
    LANGUAGE plpgsql
    AS $$
BEGIN
SELECT  ID
      ,BPN.SROCode SRO,BPN.PropertyID,
 BPN.injuction_or_stay_flag,
      BPN.OrderID,CurrentPropertyTypeID
      ,CurrentNumber,OldPropertyTypeID
      ,OldNumber,BPN.Description Description1
      ,Survey_No,Surnoc
      ,Hissa_No,BP.PropertyDescription
 ,BP.IsAgriculturalProperty,BP.EastBoundary EastBoundary
 ,BP.NorthBoundary NorthBoundary,BP.WestBoundary WestBoundary
 ,BP.SouthBoundary SouthBoundary,BP.Area Area
 ,BP.MeasurementUnit,MUM.DescriptionEnglish
 ,CO.OrderNumber COURT_ORDER_NUMBER,CO.Description Description
 ,CO.OrderEntryDateTime,CO.IsCancelled
 ,CO.ReasonOfCancellation
  FROM kaverimrg.BannedPropertyNumbers BPN inner join kaverimrg.BannedProperties BP
  on
  BPN.PropertyID=BP.PropertyID and BPN.SROCode=BP.SROCode
  inner join kaverimrg.CourtOrders CO
  on
  BP.SROCode=CO.SROCode and BP.OrderID=CO.OrderID
  inner join kaverimrg.MeasUnitMaster MUM
  on MUM.UnitID=BP.MeasurementUnit
  where BPN.SROCode=209 and CurrentPropertyTypeID=3 and CurrentNumber='41'
   or BPN.SROCode=209 and OldPropertyTypeID=3 and OldNumber='41';
   END;
$$;


