			-- Need to add condition kaverimrg_2 Pending
			
		
		
			
		v_ExemptionDescription := '' ;


-- Added Join with kaverimrg.sromaster table as part of kaverimrg_2

if( Tmp_ReceiptCount=1)
	Then
			BEGIN				
				UPDATE kaverimrg.DailyReceiptFees D
				set 
					StampDuty = B.AmountByCash, 
					StampDuty_Others = B.AmountByOther 
				FROM
					( SELECT  
								
								A.DocumentId,  -- added new column kaverimrg_2
								SUM(Case A.StampTypeId WHEN 2 THEN A.Amount Else 0 END ) as AmountByCash,
								SUM(Case A.StampTypeId WHEN 2 THEN 0 Else A.Amount  END ) as AmountByOther
					From (
						SELECT 
								DocumentId,   -- Need to confirm the logic if DocumentId added on this place , any impact ??
								--SROCODE, 				
								SD.StampTypeId, 
						      SUM(SD.Amount) as Amount
						FROM 
							kaverimrg.StampDetails SD
						WHERE SD.DocumentId = cur_DailyRegister.DocumentID
					GROUP BY 
							DocumentId, SD.StampTypeId 
						) as A
						Group by A.DocumentId
					) as B,
					--kaverimrg.DailyReceiptFees  D,
					kaverimrg.sromaster  s
				WHERE 
						     D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and   s.srocode = Tmp_SROCode
					    and D.DocumentID = cur_DailyRegister.DocumentID
						and  D.DocumentID  = B.DocumentID   -- added new condition kaverimrg_2
					    and D.ReceiptID = cur_DailyRegister.receiptID ;
					 -- AND 1 = 2 ; ---  SRONAME =     --- Need to add condition as part of kaverimrg_2 Pending 
					  
			END;
	ELSEif (Tmp_ReceiptCounter=1)
		Then 
			BEGIN
		UPDATE kaverimrg.DailyReceiptFees D set 
			StampDuty = B.AmountByCash, 
			StampDuty_Others = B.AmountByOther 
			FROM
				( SELECT  StampDetails.DocumentId ,
						SUM(Case A.StampTypeId WHEN 2 THEN A.Amount Else 0 END ) as AmountByCash,
						SUM(Case A.StampTypeId WHEN 2 THEN 0 Else A.Amount  END ) as AmountByOther
					From (
						SELECT sd.StampTypeId, SUM(sd.Amount) as Amount
						FROM kaverimrg.StampDetails Sd
						WHERE StampDetails.DocumentId = cur_DailyRegister.DocumentID
					GROUP BY sd.StampTypeId
					    ) as A
					) as B,
					
					--kaverimrg.DailyReceiptFees D ,
					kaverimrg.sromaster  s
					
				WHERE 
						D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
					and   s.srocode = Tmp_SROCode
					and  D.DocumentID = cur_DailyRegister.DocumentID
					and D.DocumentID = B.DocumentID
					and  D.ReceiptID = cur_DailyRegister.receiptID ;
					 
					 
					 -- AND 1 = 2  ; --   SRONAME =     --- Need to add condition as part of kaverimrg_2 Pending
					 

			END;
	End if;

-----------------------------

	--declare cur_ForReceiptBifercation  scroll cursor for 
	for cur_ForReceiptBifercation in (
				select ReceiptMaster.DocumentID as DocumentID_Rec,
						ReceiptMaster.ReceiptID as ReceiptID_Rec,
						ReceiptDetails.AmountPaid  as AmountPaid_Rec,
						ReceiptDetails.FeeRuleCode as FeeRuleCode_Rec
				From 
						kaverimrg.ReceiptMaster,
						kaverimrg.ReceiptDetails
				where 
					ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID 
				AND ReceiptDetails.ReceiptID = cur_DailyRegister.ReceiptID
				ANd ReceiptMaster.SROCode = Tmp_SROCode   -- Added new Condition kaverimrg_2
			)

		--	open cur_ForReceiptBifercation;
		--	fetch next from cur_ForReceiptBifercation into   
		--			@Tmp_DocumentID_Rec,@Tmp_ReceiptID_Rec,@Tmp_ReceiptAmount_Rec,@Tmp_FeeRuleCode_Rec
		--		while @@fetch_status=0	
		loop	
		--	BEGIN
				-- print  cur_ForReceiptBifercation.p_FeeRuleCode_Rec
				RAISE NOTICE 'p_FeeRuleCode_Rec %', cur_ForReceiptBifercation.FeeRuleCode_Rec;
		


					
				
		if cur_ForReceiptBifercation.FeeRuleCode_Rec = 2
				Then
					BEGIN 
					--update DailyReceiptFees set CopyFees = ISNULL(CopyFees,0) + @Tmp_ReceiptAmount_Rec where DocumentID=@Tmp_DocumentID_Rec
					update kaverimrg.DailyReceiptFees D  set 
						--CopyFees = ISNULL(CopyFees,0) + cur_ForReceiptBifercation.ReceiptAmount_Rec 
						CopyFees = COALESCE(D.CopyFees,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 	 
						--kaverimrg.DailyReceiptFees D ,
						kaverimrg.sromaster  s
					WHERE 
						D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
					and s.srocode = Tmp_SROCode
					and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec 
					and D.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
						-- AND  1 = 2 ;  -- Pending Need to add condition kaverimrg_2 
					
					
					END ;
				ELSEif cur_ForReceiptBifercation.FeeRuleCode_Rec = 31
			Then
					BEGIN
					--update DailyReceiptFees set Deficient_RegistrationFees = ISNULL(Deficient_RegistrationFees,0) + @Tmp_ReceiptAmount_Rec where DocumentID=@Tmp_DocumentID_Rec
					update kaverimrg.DailyReceiptFees D 
				set 
					--Deficient_RegistrationFees = ISNULL(Deficient_RegistrationFees,0) + cur_ForReceiptBifercation.ReceiptAmount_Rec 
							Deficient_RegistrationFees = COALESCE(D.Deficient_RegistrationFees,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						-- kaverimrg.DailyReceiptFees D,
						 kaverimrg.sromaster  s
					where 
						    D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and s.srocode = Tmp_SROCode
						and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec
					    and D.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec;
						  -- and 1 = 2; -- Pending to add condition kaverimrg_2 
					END ;
				elseif cur_ForReceiptBifercation.FeeRuleCode_Rec = 6
			Then
					BEGIN
					--update DailyReceiptFees set MutationFee =ISNULL(MutationFee,0) +  @Tmp_ReceiptAmount_Rec where DocumentID=@Tmp_DocumentID_Rec	
				update kaverimrg.DailyReceiptFees D
					set 
					--MutationFee =ISNULL(MutationFee,0) +  cur_ForReceiptBifercation.ReceiptAmount_Rec 
					MutationFee = COALESCE(D.MutationFee,0) +  cur_ForReceiptBifercation.AmountPaid_Rec 
				From 
						--kaverimrg.DailyReceiptFees  D,
						kaverimrg.sromaster  s
					where 
						    D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and s.srocode = Tmp_SROCode
						and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec
						and D.receiptid = cur_ForReceiptBifercationReceiptID_Rec ;
					-- and 1 = 2 ; -- -- Pending to add condition kaverimrg_2 
					END ;
				elseif (cur_ForReceiptBifercation.FeeRuleCode_Rec = 28 or  cur_ForReceiptBifercation.FeeRuleCode_Rec = 35) -- Added Fee rule code 35 condition by aparna on 06-05-2019
			Then
				BEGIN
					--update DailyReceiptFees set Deficient_StampDuty = ISNULL(Deficient_StampDuty,0) + @Tmp_ReceiptAmount_Rec where DocumentID=@Tmp_DocumentID_Rec
					update kaverimrg.DailyReceiptFees D 
					set
						--Deficient_StampDuty = ISNULL(Deficient_StampDuty,0) + cur_ForReceiptBifercation.ReceiptAmount_Rec 
						Deficient_StampDuty = COALESCE(D.Deficient_StampDuty,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					From 
						--kaverimrg.DailyReceiptFees D , 
						 kaverimrg.sromaster  s
					where   D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and s.srocode = Tmp_SROCode
						and	D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec
					    and D.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
					-- and 1 = 2 ;  -- Pending to add condition kaverimrg_2 
					END;
			Else
					BEGIN
					--update DailyReceiptFees set RegistrationFees = ISNULL(RegistrationFees,0) + @Tmp_ReceiptAmount_Rec where DocumentID=@Tmp_DocumentID_Rec					
					update kaverimrg.DailyReceiptFees D
					set 
					--RegistrationFees = ISNULL(RegistrationFees,0) + cur_ForReceiptBifercation.ReceiptAmount_Rec 
						RegistrationFees = COALESCE(D.RegistrationFees,0) + cur_ForReceiptBifercation.AmountPaid_Rec 
					 From 
						--kaverimrg.DailyReceiptFees D,
						kaverimrg.sromaster  s
					where   D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and s.srocode = Tmp_SROCode
						and D.DocumentID = cur_ForReceiptBifercation.DocumentID_Rec
					    and D.receiptid = cur_ForReceiptBifercation.ReceiptID_Rec ;
					-- and 	1 = 2 ; -- Pending to add condition kaverimrg_2  ; 
					END ;
			
			--	fetch next from cur_ForReceiptBifercation into   
				--	@Tmp_DocumentID_Rec,@Tmp_ReceiptID_Rec,@Tmp_ReceiptAmount_Rec,@Tmp_FeeRuleCode_Rec
				END IF ;
		end loop;		


			Tmp_Corporation := 0::money;
			Tmp_Muncipal := 0::money;
			Tmp_TalukaBoard := 0::money;
		
		
			SELECT 
			    --Convert(Integer,SUBSTRING(SUBSTRING(SDCalculationString,PATINDEX('%<AD>%', SDCalculationString),6 ),6,1)) as SDCalculation,
				SDCalculationString as SDCalculation,
				AdditionalDuty , 
				GovtDuty as Tmp_GovtDuty, 
				CessDuty as Tmp_Infrastructure
			into 
				SDCalculation, v_AdditionalDuty, Tmp_GovtDuty, Tmp_Infrastructure
			FROM 
					kaverimrg.PropertyMaster
			WHERE DocumentId =  cur_DailyRegister.DocumentID and 
				TotalArea <> -7274;
		
		
			IF 
				SDCalculation = '1'  Then Tmp_Corporation  := v_AdditionalDuty;
				ELSEIf 
				 SDCalculation = '2' Then Tmp_Muncipal  := v_AdditionalDuty;
				ELSEIf
				SDCalculation = '3' Then Tmp_TalukaBoard  := v_AdditionalDuty;
			End If ; 	




	SELECT 	COALESCE(DocumentMaster.RequiredStampDuty,0) as StampDutyRequired  , 
				COALESCE(DocumentMaster.PaidStampDuty,0)  as StampDutyPaid
			into 	
				Tmp_StampDutyRequired, Tmp_StampDutyPaid
			FROM 
				kaverimrg.DocumentMaster, 
				kaverimrg.StampDetails
			WHERE DocumentMaster.DocumentID = cur_DailyRegister.DocumentID
			and DocumentMaster.DocumentID = StampDetails.DocumentID ;
			
		
		Tmp_GovtDuty := Tmp_GovtDuty + (Tmp_StampDutyPaid - Tmp_StampDutyRequired);
		
		
		
		if(Tmp_ReceiptCount = 1)
		Then 
			BEGIN			
					UPDATE kaverimrg.DailyReceiptFees D 
					SET 	
						GovtDuty 			=   Tmp_GovtDuty,
						Infrastructure 	=   Tmp_Infrastructure,
						Muncipal			= 	Tmp_Muncipal,
						Corporation		= 	Tmp_Corporation,
						TalukBoard		= 	Tmp_TalukaBoard		
					From 
						-- kaverimrg.DailyReceiptFees D,
						kaverimrg.sromaster  s
					where   
							D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and s.srocode = Tmp_SROCode
						and D.DocumentID =  cur_DailyRegister.DocumentID ;
					-- AND 1 = 2 ;  -- Pending to add filter kaverimrg_2
				END ;
		ELSEif (Tmp_ReceiptCounter = 1 )
			Then 
			BEGIN

					UPDATE kaverimrg.DailyReceiptFees D
					SET 	
						GovtDuty 	= Tmp_GovtDuty,
						Infrastructure 	= Tmp_Infrastructure,
						Muncipal	=  Tmp_Muncipal,
						Corporation	=  Tmp_Corporation,
						TalukBoard	=  Tmp_TalukaBoard	
					From 
					--	kaverimrg.DailyReceiptFees D,
						kaverimrg.sromaster  s
					where   
							D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
						and s.srocode = Tmp_SROCode
						and D.DocumentID = cur_DailyRegister.DocumentID ;
					-- and 1 = 2  ; -- pending to add filter kaverimrg_2
			End;
			
		END If ;
			
		
			Tmp_GovtDuty 	:= 0;
			Tmp_Infrastructure 	:= 0;
			Tmp_Muncipal 	:= 0;
			Tmp_GovtDuty 	:= 0;
			Tmp_MarketValue 	:= 0;
	
	

		if( Tmp_ReceiptCount> 1 )
		Then 
			Tmp_ReceiptCounter := Tmp_ReceiptCounter+1 ;
		end if;

		
		Tmp_PreviousDocumentID := cur_DailyRegister.DocumentID;

	
	
end loop;		-- ended cur_DailyRegister cursor 
			
	
	-------------------------------Need to add Marriger Reg part here ----------------------------------------------------------------
	
	
		
		

For cur_OtherFees in (

SELECT  Sum(ReceiptDetails.AmountPaid) as Amount, 
		ReceiptMaster.ReceiptNumber, 
		ReceiptMaster.DateOfReceipt, 
		ReceiptMaster.ReceiptTypeID, 
		ReceiptTypeMaster.DescriptionKannada,
		(PartyInfo.FirstName || ' ' || PartyInfo.MiddleName || ' ' || PartyInfo.LastName) as Name, 
		ReceiptDetails.FeeRulecode,
		ReceiptMaster.ReceiptID
			FROM 	
				kaverimrg.ReceiptMaster,
				kaverimrg.ReceiptDetails, 
				kaverimrg.PartyInfo, 
				kaverimrg.ReceiptTypeMaster
			WHERE     
				ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID		
				and ReceiptMaster.ReceiptTypeID in (2,3,4)
				and ReceiptMaster.PartyID = PartyInfo.PartyID
				and ReceiptTypeMaster.ReceiptTypeID = ReceiptMaster.ReceiptTypeID
				--and (DATEDIFF ( d , ReceiptMaster.DateofReceipt ,convert(datetime,@Tmp_DailyDate,103))=0    -- kaverimrg_2
				--or DATEDIFF ( d , ReceiptMaster.DateofReceipt  ,convert(datetime,@Tmp_PreviousDate ,103))=0 )	
				
				AND  ( Date_Part('Day', ReceiptMaster.DateofReceipt - Tmp_DailyDate::timestamp ) =0 OR 
					 Date_Part('Day', ReceiptMaster.DateofReceipt - Tmp_PreviousDate::timestamp ) =0)
				
			GROUP BY 
				ReceiptMaster.ReceiptNumber, ReceiptMaster.DateOfReceipt,ReceiptMaster.ReceiptTypeID,
				ReceiptTypeMaster.DescriptionKannada,ReceiptMaster.receiptID,
				PartyInfo.FirstName, PartyInfo.MiddleName, PartyInfo.LastName, ReceiptDetails.FeeRulecode
		)

	-- Tmp_OtherReceiptID := 0; 
	-- Tmp_OtherReceiptIDPresentOrNot := 0;
	 
loop 


select D.receiptID 
	into Tmp_OtherReceiptIDPresentOrNot
from kaverimrg.DailyReceiptFees D,
	 kaverimrg.sromaster  s
where   
		  D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
		and s.srocode = Tmp_SROCode
		and DailyReceiptFees.receiptID = cur_OtherFees.ReceiptID ;






	-- Begin Main IF 
	if Tmp_OtherReceiptIDPresentOrNot = cur_OtherFees.ReceiptID 
	Then 
		-- Begin 2nd IF 
 			BEGIN
				if cur_OtherFees.FeeRulecode = 36 THEN
					BEGIN
					RAISE NOTICE 'stampduty in other receipt Update';
					
						Tmp_AmountbyCash := 0::money;
						Tmp_AmountbyOther := 0::money;
						
						--changes done by Prashanth M V to solve other receipts problem 
	                  --select  @Tmp_AmountbyCash  = isnull(SUM(Amount),0) from ReceiptPaymentDetails where PaymentModeID = 1  AND receiptID =  @Tmp_OtherReceiptID
						--select  @Tmp_AmountbyOther = isnull(SUM(Amount),0) from ReceiptPaymentDetails where PaymentModeID <> 1 AND receiptID =  @Tmp_OtherReceiptID
	                  select sum(AmountPaid) 
						into Tmp_AmountbyCash
					  from kaverimrg.ReceiptDetails 
					  where receiptID =  cur_OtherFees.ReceiptID  and 
							FeeRuleCode = 36;
							
						update kaverimrg.DailyReceiptFees D
							set 
							--StampDuty = ISNULL(StampDuty,0) + @Tmp_AmountbyCash, StampDuty_Others = ISNULL(StampDuty_Others,0) + @Tmp_AmountbyOther 
							
							StampDuty = COALESCE(D.StampDuty,0)  + Tmp_AmountbyCash +  StampDuty_Others +  COALESCE(StampDuty_Others,0)
						from 
						--	kaverimrg.DailyReceiptFees D,
							kaverimrg.sromaster  s
						where   	
							D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
							and s.srocode = Tmp_SROCode
							and DailyReceiptFees.ReceiptID =  cur_OtherFees.ReceiptID ;
							-- and 1 = 2 ;  -- pending to add condition 
							
					END;
					
					ELSEif cur_OtherFees.FeeRulecode = 35 THEN 
					BEGIN
						RAISE NOTICE 'deficit stampduty in other receipt Update';
						
						Tmp_AmountbyCash := 0::money;
						Tmp_AmountbyOther := 0::money;
	                                        			
						
						--select  @Tmp_AmountbyCash  = isnull(SUM(Amount),0) from ReceiptPaymentDetails where PaymentModeID = 1  AND receiptID =  @Tmp_OtherReceiptID
						--select  @Tmp_AmountbyOther = isnull(SUM(Amount),0) from ReceiptPaymentDetails where PaymentModeID <> 1 AND receiptID =  @Tmp_OtherReceiptID
	                                                                  
						select sum(AmountPaid) into Tmp_AmountbyCash
						from kaverimrg.ReceiptDetails 
						where receiptID =  cur_OtherFees.ReceiptID and 
						     FeeRuleCode=35 ;
						
						update kaverimrg.DailyReceiptFees D
						set --StampDuty = ISNULL(StampDuty,0) + Tmp_AmountbyCash, 
							--StampDuty_Others = ISNULL(StampDuty_Others,0) + @Tmp_AmountbyOther 
							StampDuty = COALESCE(D.StampDuty,0) + Tmp_AmountbyCash, 
							StampDuty_Others = COALESCE(D.StampDuty_Others,0) + Tmp_AmountbyOther 							
						From 
							-- kaverimrg.DailyReceiptFees D,
							kaverimrg.sromaster  s
						where   	
							     D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
							and  s.srocode = Tmp_SROCode
							and  DailyReceiptFees.ReceiptID =  cur_OtherFees.ReceiptID ;
						
						
					END ;
					ELSE
					BEGIN  
						RAISE NOTICE 'Other Fees in Other receiept part Update';
						
						Tmp_AmountAlreadyPresent := 0;
						
					update kaverimrg.DailyReceiptFees D
						set 
						--OtherFees = ISNULL(OtherFees ,0) + @Tmp_ReceiptAmount
						OtherFees =  COALESCE(D.OtherFees,0) + cur_OtherFees.Amount
					From 
						-- kaverimrg.DailyReceiptFees  D,
						kaverimrg.sromaster  s
					where   	
							     D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
							and  s.srocode = Tmp_SROCode
							and  DailyReceiptFees.ReceiptID =  cur_OtherFees.ReceiptID; 
					END ;
				END If ;
			End; -- End of 2nd Begin
				
	ELSE
				BEGIN
					if cur_OtherFees.FeeRulecode = 36 THEN 
					BEGIN
						RAISE NOTICE  'stampduty in other receipt Insert';
						
						 Tmp_AmountbyCash = 0::money;
						 Tmp_AmountbyOther = 0::money;
	                                        
						select sum(COALESCE(cur_OtherFees.Amount,0)) 
							into Tmp_AmountbyCash
						from kaverimrg.ReceiptPaymentDetails 
						where PaymentModeID = 1  AND 
							receiptID =  cur_OtherFees.ReceiptID ; --@Tmp_OtherReceiptID;
						
						
						select  
						--@Tmp_AmountbyOther = isnull(SUM(Amount),0) 
						sum(COALESCE(cur_OtherFees.Amount,0)) 
						into 
							Tmp_AmountbyOther
						from kaverimrg.ReceiptPaymentDetails 
						where PaymentModeID <> 1 AND 
							  receiptID =  cur_OtherFees.ReceiptID ; -- @Tmp_OtherReceiptID;
	                                                       
														   
						INSERT INTO kaverimrg.DailyReceiptFees (
							PresentDateTime, 
							PresenterName, 
							DocumentNumber, 
							StampDuty, 
							StampDuty_Others,
							OtherFeesDesc,ReceiptID) 
						VALUES (
						  -- @Tmp_ReceiptDate,
						  cur_OtherFees.DateOfReceipt,
							cur_OtherFees.Name,   --   @Tmp_Name, 
							'(RN:' ||   cur_OtherFees.ReceiptNumber::varchar ||  ')',   --- + cast(@Tmp_ReceiptNumber as varchar(10)) + ')',  
							Tmp_AmountbyCash,
							Tmp_AmountbyOther, 
							cur_OtherFees.DescriptionKannada, --- @Tmp_ReceiptDescription,
							--@Tmp_OtherReceiptID 
							cur_OtherFees.ReceiptID 
							) ;
						
					END ;
					
					ELSEif cur_OtherFees.FeeRulecode = 35  THEN --  @Tmp_ReceiptFeeRulecode = 35 
					
					BEGIN
						RAISE NOTICE  'deficit stampduty in other receipt Insert';
						
						Tmp_AmountbyCash = 0::money;
						Tmp_AmountbyOther = 0::money;
	                                        
						select sum(COALESCE(cur_OtherFees.Amount,0)) 
							into Tmp_AmountbyCash
						from kaverimrg.ReceiptPaymentDetails 
						where PaymentModeID = 1  
						AND receiptID =  cur_OtherFees.ReceiptID ; -- @Tmp_OtherReceiptID  ;
						
						select  sum(COALESCE(cur_OtherFees.Amount,0)) 
							into Tmp_AmountbyOther 
						from kaverimrg.ReceiptPaymentDetails 
						where PaymentModeID <> 1 AND 
						receiptID = cur_OtherFees.ReceiptID  ; -- @Tmp_OtherReceiptID ;
	                                                                  
						INSERT INTO kaverimrg.DailyReceiptFees (
							PresentDateTime, 
							PresenterName, 
							DocumentNumber, 
							StampDuty, 
							StampDuty_Others,
							OtherFeesDesc,ReceiptID) 
						VALUES ( --@Tmp_ReceiptDate,
								cur_OtherFees.DateOfReceipt,
							cur_OtherFees.Name, --  @Tmp_Name, 
							'(RN:' || cur_OtherFees.ReceiptNumber::varchar ||  ')',    ---  + cast(@Tmp_ReceiptNumber as varchar(10)) + ')',  
							Tmp_AmountbyCash,
							Tmp_AmountbyOther, 
							cur_OtherFees.DescriptionKannada, --   @Tmp_ReceiptDescription,
							--@Tmp_OtherReceiptID 
							cur_OtherFees.ReceiptID 
							);
					END ;
				End If;
				
				BEGIN  
						RAISE NOTICE  'Other Fees in Other receiept part Insert';
						
						Tmp_AmountAlreadyPresent := 0::money;
						
						INSERT INTO kaverimrg.DailyReceiptFees (
							PresentDateTime, 
							PresenterName, 
							DocumentNumber, 
							OtherFees, 
							OtherFeesDesc,ReceiptID) 
						VALUES (
						--@Tmp_ReceiptDate,
						cur_OtherFees.DateOfReceipt,
							cur_OtherFees.Name, --  @Tmp_Name, 
							'(RN:' || cur_OtherFees.ReceiptNumber::varchar ||  ')',  ---  cast(@Tmp_ReceiptNumber as varchar(10)) + ')',  
							cur_OtherFees.Amount, --- @Tmp_ReceiptAmount, 
							cur_OtherFees.DescriptionKannada,   ---  @Tmp_ReceiptDescription, 
							--@Tmp_OtherReceiptID
							cur_OtherFees.ReceiptID 
							);
					END;

				END;
	
	Tmp_OtherReceiptIDPresentOrNot := 0;
	
			END	If ;
	

	
	
End loop;
	
	
	
--Preveious days transactions 

update kaverimrg.DailyReceiptFees D
set 
	PreviousDate = Tmp_PreviousDate 
From 
	--kaverimrg.DailyReceiptFees  D,
	kaverimrg.sromaster  s
where   	
	D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
	and  s.srocode = Tmp_SROCode ;
--where  1 = 2;   -- need to add condition for SRO office level details only pending 



/* Summary for previous day's transaction */  -- Commented as part of kaverimrg_2 changes 

/*
SELECT PrevTotalStampDuty = convert(money,(sum(IsNull(StampDuty,0))+sum(IsNull(StampDuty_DD,0))+sum(IsNull(StampDuty_others,0))+sum(IsNull(Deficient_StampDuty,0))))
from 
	kaverimrg.DailyReceiptFees WHERE CONVERT(VARCHAR(11), PresentDateTime, 113) = LEFT(convert(varchar(25),Tmp_PreviousDate, 113), 11);

SELECT PrevTotalRegistrationFees = (sum(IsNull(RegistrationFees,0))+sum(IsNull(Deficient_RegistrationFees,0)))
from 
	kaverimrg.DailyReceiptFees WHERE CONVERT(VARCHAR(11), PresentDateTime, 113) = LEFT(convert(varchar(25),Tmp_PreviousDate, 113), 11);

SELECT PrevTotalMutationFee = sum(IsNull(MutationFee,0))
from 
	kaverimrg.DailyReceiptFees WHERE CONVERT(VARCHAR(11), PresentDateTime, 113) = LEFT(convert(varchar(25),Tmp_PreviousDate, 113), 11);

SELECT PrevTotalCopyFees = sum(IsNull(CopyFees,0))
from 
	kaverimrg.DailyReceiptFees WHERE CONVERT(VARCHAR(11), PresentDateTime, 113) = LEFT(convert(varchar(25),Tmp_PreviousDate, 113), 11);

SELECT PrevTotalMarriageFee = (sum(IsNull(HinduMarriageFee,0))+sum(IsNull(SplOtherMarriageFee,0))+sum(IsNull(SplMarriageFee,0)))
from 
	kaverimrg.DailyReceiptFees WHERE CONVERT(VARCHAR(11), PresentDateTime, 113) = LEFT(convert(varchar(25),Tmp_PreviousDate, 113), 11);
*/


/* Summary for previous day's transaction */  -- kaverimrg_2

SELECT  

  SUM(COALESCE(RegistrationFees,0) +  COALESCE(Deficient_RegistrationFees,0) + COALESCE(StampDuty_others,0) + COALESCE(Deficient_StampDuty,0) ) as PrevTotalStampDuty,
-- convert(money,(sum(IsNull(StampDuty,0))+sum(IsNull(StampDuty_DD,0))+sum(IsNull(StampDuty_others,0))+sum(IsNull(Deficient_StampDuty,0)))) as PrevTotalStampDuty,
	sum(COALESCE(RegistrationFees,0) + COALESCE(Deficient_RegistrationFees,0)) as PrevTotalRegistrationFees,
--		(sum(IsNull(RegistrationFees,0))+sum(IsNull(Deficient_RegistrationFees,0))) as PrevTotalRegistrationFees,
	sum(COALESCE(MutationFee,0)) as PrevTotalMutationFee,
-- sum(IsNull(MutationFee,0)) as PrevTotalMutationFee, 
	sum(COALESCE(CopyFees,0)) as PrevTotalCopyFees,
--		sum(IsNull(CopyFees,0))  as PrevTotalCopyFees ,
	sum(COALESCE(HinduMarriageFee,0) + COALESCE(SplOtherMarriageFee,0) + COALESCE(SplMarriageFee,0)  ) as PrevTotalMarriageFee
-- (sum(IsNull(HinduMarriageFee,0))+sum(IsNull(SplOtherMarriageFee,0))+sum(IsNull(SplMarriageFee,0))) as PrevTotalMarriageFee
	into
			v_PrevTotalStampDuty, v_PrevTotalRegistrationFees, v_PrevTotalMutationFee, v_PrevTotalCopyFees, v_PrevTotalMarriageFee
from 
	kaverimrg.DailyReceiptFees D,
	kaverimrg.sromaster  s
where   	
		to_char(D.PresentDateTime, 'DD Mon YYYY') = to_char(Tmp_PreviousDate, 'DD Mon YYYY') 
	and   D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
	and  s.srocode = Tmp_SROCode ;
	
	
	-- CONVERT(VARCHAR(11), PresentDateTime, 113) = LEFT(convert(varchar(25),Tmp_PreviousDate, 113), 11)
	--and   -- need to add condition for SRO office level details only  pending 
	

Update kaverimrg.DailyReceiptFees D SET 
	PrevTotalStampDuty 	= 	v_PrevTotalStampDuty,
	PrevTotalRegistrationFees = v_PrevTotalRegistrationFees,
	PrevTotalMutationFee 	= v_PrevTotalMutationFee,
	PrevTotalCopyFees 	= v_PrevTotalCopyFees,
	PrevTotalMarriageFee  = v_PrevTotalMarriageFee 
From 
	kaverimrg.sromaster  s
Where 
	D.sroname =  s.sronamee           -- kaverimrg_2 need to clarify pending 
	and  s.srocode = Tmp_SROCode ;
	
   --Where 
   --1 = 2 ;    -- need to add condition for SRO office level details only  pending 
	
	
	
End $$;


