--
-- Name: sp_insert_into_citizenmaster(text, text, text, text, integer, text, bigint, text, integer, text, character, text, timestamp without time zone); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_insert_into_citizenmaster(IN _loginname text, IN _firstname text, IN _middlename text, IN _lastname text, IN _gender integer, IN _email text, IN _phone bigint, IN _password text, IN _secquestion integer, IN _secanswer text, IN _isloggedin character, IN _lstupdusr text, IN _lstupddt timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
declare
 cnt integer;
 err_constraint text;
 columnname text;
begin
INSERT INTO kaverimrg.citizenmaster
(loginname,firstname,middlename,lastname,gender,email,phone,password,secquestion,secanswer,isloggedin,
                                  lstupdusr,lstupddt)
   VALUES 
   (_loginname,_firstname,_middlename,_lastname,_gender,_email,_phone,_password,_secquestion,_secanswer,
	_isloggedin,_lstupdusr,_lstupddt
   );
   select  max(citizenid) into cnt from kaverimrg.citizenmaster;
   raise notice '%',cnt;
EXCEPTION
   WHEN SQLSTATE '23505' THEN  -- Class 23 — Integrity Constraint Violation
      GET STACKED DIAGNOSTICS err_constraint = CONSTRAINT_NAME;
	   GET STACKED DIAGNOSTICS columnname = COLUMN_NAME;
      -- do something with it, for instance:
      RAISE NOTICE '%', err_constraint;
	  RAISE NOTICE '%',columnname;
      --RAISE;  -- raise original error
   END;
$$;


ALTER PROCEDURE kaverimrg.sp_insert_into_citizenmaster(IN _loginname text, IN _firstname text, IN _middlename text, IN _lastname text, IN _gender integer, IN _email text, IN _phone bigint, IN _password text, IN _secquestion integer, IN _secanswer text, IN _isloggedin character, IN _lstupdusr text, IN _lstupddt timestamp without time zone) OWNER TO postgres;

--
-- Name: sp_insert_slots(bigint, date); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_insert_slots(IN _srocode bigint, IN _slotdate date)
    LANGUAGE plpgsql
    AS $$

BEGIN

insert into kaverimrg.slotmaster
(
srocode,
serviceid,
sltdate,
sltstarttime,
sltendtime,
sltcapacity,
sltavlcapacity,
sltisactive,
isexpress) values
(_srocode,1,_slotdate,'09:00','10:00',5,5,true,true),
(_srocode,1,_slotdate,'10:00','11:00',5,5,true,true),
(_srocode,1,_slotdate,'11:00','12:00',5,5,true,true),
(_srocode,1,_slotdate,'13:00','14:00',5,5,true,true),
(_srocode,1,_slotdate,'14:00','15:00',5,5,true,true),
(_srocode,1,_slotdate,'15:00','16:00',5,5,true,true),
(_srocode,1,_slotdate,'16:00','17:00',5,5,true,true);

exception 
	   when others then 
	      RAISE INFO 'Error Name:%',SQLERRM;
end;

$$;


ALTER PROCEDURE kaverimrg.sp_insert_slots(IN _srocode bigint, IN _slotdate date) OWNER TO postgres;

--
-- Name: sp_kaverimrg_grant_permission(character varying); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_kaverimrg_grant_permission(IN _role character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN

EXECUTE 'GRANT select,usage ON ALL SEQUENCES IN SCHEMA kaverimrg TO '||_role;

EXECUTE 'GRANT INSERT, SELECT, UPDATE, DELETE, REFERENCES, TRIGGER ON ALL tables IN SCHEMA kaverimrg TO '||_role;

EXECUTE 'GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA kaverimrg TO '||_role;

EXECUTE 'GRANT EXECUTE ON ALL PROCEDURES IN SCHEMA kaverimrg TO '||_role;

exception 
	   when others then 
	      RAISE INFO 'Error Name:%',SQLERRM;
end;

$$;


ALTER PROCEDURE kaverimrg.sp_kaverimrg_grant_permission(IN _role character varying) OWNER TO postgres;

--
-- Name: sp_mdm_master_data_sync(); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_mdm_master_data_sync()
    LANGUAGE plpgsql
    AS $$
             

-- Procedure to sync all newely added\updated master data from MDM tables to master tables.			 


Declare v_count int;
Declare v_id_char character;
Declare v_id_int int;
Declare i record;


-- MDM Table Sequence needs to follow For Stamp Atricles
--1. kaverimrg.booktypemaster
--2. kaverimrg.registrationarticles
--3. kaverimrg.stamparticles
--4. kaverimrg.stamprules
--5. kaverimrg.stamptypemaster 
--6. mdm_stampruleslabs 

Begin
  
----------------------------- Start : mdm_booktypemaster ----------------------------
 
select count(*) into v_count 
from kaverimrg.mdm_booktypemaster
where (StartDate = current_date +1 ) 
and isactive = true ;


if v_count >= 1
then
begin 

for i in (select bookid ,booknamekannada, booknameenglish, ispublic, printablename
from kaverimrg.mdm_booktypemaster
where (StartDate = current_date +1 ) 
and isactive = true )

loop

if (select count(*) from kaverimrg.booktypemaster where bookid = i.bookid) = 1
then

-- Update new changes from mdm table to master table 
Begin
	update kaverimrg.booktypemaster b
	set 
		booknamekannada = i.booknamekannada ,
		booknameenglish = i.booknameenglish ,
		ispublic = i.ispublic ,
		printablename = i.printablename
	from 
		kaverimrg.mdm_booktypemaster m
	where 
		b.bookid = i.bookid ;	
		
 		
	/* - Testing is pending 
	
	Update kaverimrg.mdm_booktypemaster
	set
	updateddate = current_date , 
	enddate  = current_date, 
	isactive = false 
	where bookid = i.bookid 
		and isactive = true 
		and StartDate < current_date +1 ;
     */ 	
		
end ;

else

Begin   

-- Insert new record from MDM table to master table.

INSERT INTO kaverimrg.booktypemaster (bookid,booknamekannada,booknameenglish,ispublic,printablename ) 
select i.bookid, i.booknamekannada, i.booknameenglish, i.ispublic, i.printablename ;


end ;

end if ; 


end loop ; 

End;
End If ;

----------------------------- End : mdm_booktypemaster ----------------------------




----------------------------- Start : mdm_registrationarticles ----------------------------


select count(*) into v_count 
from kaverimrg.mdm_registrationarticles
where (StartDate = current_date +1 ) 
and isactive = true ;


if v_count >= 1
then
begin 

for i in (select regarticlecode, articlenamek, articlenamee, userarticleno, bookid, getbhoomidata
from kaverimrg.mdm_registrationarticles
where (StartDate = current_date +1 ) 
and isactive = true )

loop

if (select count(*) from kaverimrg.registrationarticles where regarticlecode = i.regarticlecode) = 1
then

-- Update new changes from mdm table to master table 
Begin
	update kaverimrg.registrationarticles b
	set 
		articlenamek = i.articlenamek ,
		articlenamee = i.articlenamee , 
		userarticleno = i.userarticleno , 
		bookid = i.bookid,
		getbhoomidata = i.getbhoomidata
	from 
		kaverimrg.mdm_registrationarticles m
	where 
		b.regarticlecode = i.regarticlecode ;	
		
 		
	/* - Testing is pending 
	
	Update kaverimrg.mdm_registrationarticles
	set
	updateddate = current_date , 
	enddate  = current_date, 
	isactive = false 
	where regarticlecode = i.regarticlecode
		and isactive = true 
		and StartDate < current_date +1 ;
     */ 	
		
end ;

else

Begin   

-- Insert new record from MDM table to master table.

INSERT INTO kaverimrg.registrationarticles (regarticlecode,articlenamek,articlenamee,userarticleno,bookid,getbhoomidata) 
select i.regarticlecode, i.articlenamek, i.articlenamee, i.userarticleno, i.bookid, i.getbhoomidata ;


end ;

end if ; 


end loop ; 

End;
End If ;





----------------------------- End : mdm_registrationarticles ----------------------------


----------------------------- Start : mdm_stamparticles ----------------------------



select count(*) into v_count 
from kaverimrg.mdm_stamparticles
where (StartDate = current_date +1 ) 
and isactive = true ;



if v_count >= 1
then
begin 

for i in (select stamparticlecode, articlenamek, articlenamee, userarticleno
from kaverimrg.mdm_stamparticles
where (StartDate = current_date +1 ) 
and isactive = true )

loop

if (select count(*) from kaverimrg.stamparticles where stamparticlecode = i.stamparticlecode) = 1
then

-- Update new changes from mdm table to master table 
Begin
	update kaverimrg.stamparticles b
	set 
		articlenamek = i.articlenamek ,
		articlenamee = i.articlenamee ,
		userarticleno = i.userarticleno
		
	from 
		kaverimrg.mdm_stamparticles m
	where 
		b.stamparticlecode = i.stamparticlecode ;	
		
 		
	/* - Testing is pending 
	
	Update kaverimrg.mdm_stamparticles
	set
	updateddate = current_date , 
	enddate  = current_date, 
	isactive = false 
