--
-- Name: sp_statement(integer); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_statement(IN passyear integer)
    LANGUAGE plpgsql
    AS $$                 -- kaverimrg_2

--Variable declaration



  Declare Month		varchar(10); 
  Declare Year			integer;
  Declare TotalDocuments	integer;
  Declare TotalStampDuty 	money;	
  Declare TotalRegFees 	money;
  Declare SDRefund		money; 
  Declare PYear		integer;
  Declare PTotalDocuments	integer;
  Declare PTotalStampDuty 	money;	
  Declare PTotalRegFees 	money;
  Declare SROName		varchar(250); 

declare cur_statement record;
declare cur_statement_p record;

Begin
--declare cur_statement  scroll cursor for 

for cur_statement in   -- Create Cursor cur_statement
   (
	SELECT 	
		 TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month') AS Month,
		date_part('year',DocumentMaster.Stamp5DateTime) as Year,
		count(DocumentMaster.DocumentID) Documents, 
		sum(DocumentMaster.PaidStampDuty) StampDuty,
		sum(ReceiptDetails.AmountPaid) RegFees,
		SROMaster.SRONameK 
	FROM 	kaverimrg.DocumentMaster, 
			kaverimrg.ReceiptDetails, 
			kaverimrg.ReceiptMaster, 
			kaverimrg.SROMaster
	WHERE 	ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID 
	and	ReceiptMaster.DocumentID = DocumentMaster.DocumentID
	and	ReceiptDetails.FeeRuleCode = 1
	and	
	
	(
		-- ( Datepart(m,DocumentMaster.Stamp5DateTime) > 3	and
		 ( date_part('month',DocumentMaster.Stamp5DateTime) >3 and 
		--Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear)
		date_part('year',DocumentMaster.Stamp5DateTime)  = PassYear)  OR 
		
	--	or	(Datepart(m,DocumentMaster.Stamp5DateTime) < 4	and
	   ( date_part('month',DocumentMaster.Stamp5DateTime) <4 and 
		
    --	Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear+1)
		date_part('year',DocumentMaster.Stamp5DateTime) = PassYear+1 ) 
		
	)
	and	SROMaster.SROCode = DocumentMaster.SROCode 
	GROUP BY SROMaster.SRONamek, 
    	  TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month') ,
    	date_part('year',DocumentMaster.Stamp5DateTime)
  
	ORDER BY 
		--Datepart(yyyy,DocumentMaster.Stamp5DateTime),
		date_part('year',DocumentMaster.Stamp5DateTime) ,
	   TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month')
	   
		--Datepart(m,DocumentMaster.Stamp5DateTime) 
		-- date_part('month',DocumentMaster.Stamp5DateTime)
   )
   
   

	-- Delete from Statement;

loop

--	Open cur_statement;

/*
	fetch next from cur_statement into   
			   Month		, 
			   Year		,
			   TotalDocuments	,
			   TotalStampDuty 	,	
			   TotalRegFees 	,
			   SROName		;

	while fetch_status=0	
*/


		begin
			insert into kaverimrg.Statement(
						SROName,
						CMonth,
						CYear,
						CTotalDocuments ,
						CTotalStampDuty,
						CTotalRegFees
						)
			values			(
						cur_statement.SRONameK,
						cur_statement.Month,
						cur_statement.Year,
						cur_statement.Documents,
						cur_statement.StampDuty,
						cur_statement.RegFees
						) ;


			/* Cursor for previous year ***********begins***************************/
		--	declare cur_statement_p  scroll cursor for 
		
		for cur_statement_p in (
				SELECT 
					date_part('Year',DocumentMaster.Stamp5DateTime) as Year,
					count(DocumentMaster.DocumentID) as Documents, 
					sum(DocumentMaster.PaidStampDuty) as StampDuty,
					sum(ReceiptDetails.AmountPaid) as RegFees
				FROM 	kaverimrg.DocumentMaster, 
						kaverimrg.ReceiptDetails, 
						kaverimrg.ReceiptMaster
				WHERE 	ReceiptDetails.ReceiptID = ReceiptMaster.ReceiptID 
				and	ReceiptMaster.DocumentID = DocumentMaster.DocumentID
				and	ReceiptDetails.FeeRuleCode = 1
				and	
				/*((Datepart(m,DocumentMaster.Stamp5DateTime) > 3	and
					Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear-1)
				or	(Datepart(m,DocumentMaster.Stamp5DateTime) < 4	and
					Datepart(yyyy,DocumentMaster.Stamp5DateTime) = PassYear))
				*/	
			--(( EXTRACT(Month FROM TIMESTAMP DocumentMaster.Stamp5DateTime) >3 and 
			(  (date_part('month',DocumentMaster.Stamp5DateTime) >3 and 
			  
			--EXTRACT(YEAR,DocumentMaster.Stamp5DateTime) = PassYear-1)
			 date_part('Year',DocumentMaster.Stamp5DateTime) = PassYear-1)   OR
			 
			 --(EXTRACT(Month,DocumentMaster.Stamp5DateTime) < 4 and
			( date_part('Month',DocumentMaster.Stamp5DateTime) <4 and 
			  
			  --EXTRACT(YEAR,DocumentMaster.Stamp5DateTime) = PassYear)	)
				date_part('Year',DocumentMaster.Stamp5DateTime) = PassYear)	
			)
			 
	--		and 	Datename(m,DocumentMaster.Stamp5DateTime) = month 
			 AND TO_CHAR(DocumentMaster.Stamp5DateTime, 'Month') = cur_statement.Month
			
			GROUP BY 
					--Datepart(m,DocumentMaster.Stamp5DateTime),
					--Datepart(yyyy,DocumentMaster.Stamp5DateTime) 
					date_part('Month',DocumentMaster.Stamp5DateTime),
					date_part('Year',DocumentMaster.Stamp5DateTime)
		)


				--Open cur_statement_p;
			
			/*	fetch next from cur_statement_p into   
						   PYear		,
						   PTotalDocuments	,
						   PTotalStampDuty 	,	
						   PTotalRegFees 	;
			*/

			loop 
				--	while fetch_status=0	
						begin
							UPDATE kaverimrg.Statement	
							SET	PYear  = cur_statement_p.Year,
								PTotalDocuments = cur_statement_p.Documents ,
								PTotalStampDuty =  cur_statement_p.StampDuty,
								PTotalRegFees	  =  cur_statement_p.RegFees
							Where	CMonth = cur_statement.Month ;

							/*
							fetch next from cur_statement_p into   
							   PYear		,
							   PTotalDocuments	,
							   PTotalStampDuty 	,	
							   PTotalRegFees 	;
							  */
						end ;
				
			--	close cur_statement_p;
			--	deallocate cur_statement_p;
			
			end loop ; -- close cursor cur_statement_p

			/* Cursor for previous year ***********ends***************************/


		/*	fetch next from cur_statement into   
			   Month		, 
			   Year		,
			   TotalDocuments	,
			   TotalStampDuty 	,	
			   TotalRegFees 	,
			   SROName		;
		end
		*/
	End ;   -- End of First Begin 
--close cur_statement;
--deallocate cur_statement;

end loop ;   -- End cursor cur_statement




end $$;


ALTER PROCEDURE kaverimrg.sp_statement(IN passyear integer) OWNER TO postgres;

--
-- Name: sp_update_documentnumber(); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_update_documentnumber()
    LANGUAGE plpgsql
    AS $$


declare
v_applicationnumber character varying;
v_srocode bigint;
v_considerationamount bigint;
v_considerationfruits bigint;
begin

for v_applicationnumber,v_considerationfruits in (select p.applicationnumber,p.consideration  
from kaverimrg.fruits_data_recv_details  p join kaverimrg.documentmaster d on p.applicationnumber = d.applicationnumber)	
loop
	select considerationamount into v_considerationamount from kaverimrg.documentmaster d2  where applicationnumber =v_applicationnumber;
	if (v_considerationamount=0)
	then 
	update kaverimrg.documentmaster dm  set considerationamount=v_considerationfruits  where dm.applicationnumber =v_applicationnumber;
	raise notice 'applicationnubmer %',v_applicationnumber;
end if;
	
end loop;
end;
$$;


ALTER PROCEDURE kaverimrg.sp_update_documentnumber() OWNER TO postgres;

