-- Name: sp_update_srocode(); Type: PROCEDURE; Schema: kaverimrg; Owner: postgres
--

CREATE PROCEDURE kaverimrg.sp_update_srocode()
    LANGUAGE plpgsql
    AS $$


declare
v_applicationnumber character varying;
v_srocode bigint;
v_considerationamount bigint;
v_considerationfruits bigint;
begin

for v_applicationnumber in (select p.applicationnumber from kaverimrg.rule17filing p )	
loop
	select srocode into v_srocode from kaverimrg.rule17filing  where applicationnumber =v_applicationnumber;
	if (v_srocode is not null)
	then 
	update kaverimrg.applicantapplicationdetails ad
	set srocode=v_srocode  
	where ad.applicationnumber =v_applicationnumber;
	raise notice 'applicationnubmer %',v_applicationnumber;
end if;
	
end loop;
end;
$$;


