--
-- Name: feecalculation_v; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.feecalculation_v AS
 SELECT DISTINCT b.applicationnumber,
    a.valid,
    a.srocode,
    a.villagecode,
    a.roadcode,
    a.valuationdate,
    a.regarticlecode,
    a.propertytypeid,
    a.totalarea,
    a.unitid,
    c.measurementnamee,
    a.marketvalue,
    b.documentid,
    b.feerulecode,
    e.descriptione,
    b.amountrequired
   FROM kaverimrg.valuationdetails a,
    kaverimrg.feesrequired b,
    kaverimrg.measurementmaster c,
    kaverimrg.propertytypemaster d,
    kaverimrg.feesrulemaster e,
    kaverimrg.sromaster f,
    kaverimrg.villagemaster_bck_12062023 g,
    kaverimrg.roadmaster h,
    kaverimrg.documentmaster i,
    kaverimrg.stamparticles j
  WHERE (((a.applicationnumber)::text = (b.applicationnumber)::text) AND (a.srocode = b.srocode) AND (a.propertytypeid = d.propertytypeid) AND (a.unitid = c.measurementcode) AND (a.regarticlecode = e.regarticlecode) AND (a.regarticlecode = j.stamparticlecode) AND (b.feerulecode = e.feerulecode) AND (a.srocode = f.srocode) AND (a.villagecode = g.villagecode) AND (a.roadcode = h.roadcode));


ALTER TABLE kaverimrg.feecalculation_v OWNER TO postgres;

