--
-- Name: reg_article_sub_article_mapping; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.reg_article_sub_article_mapping AS
 SELECT d.regarticlecode,
    d.articlenamee AS nature_of_document,
    a.stamparticlecode,
    a.articlenamee AS article,
    c.stampruleid,
    c.descriptione AS subarticle
   FROM (((kaverimrg.stamparticles a
     JOIN kaverimrg.stamprules c ON ((a.stamparticlecode = c.stamparticlecode)))
     JOIN kaverimrg.stampregrelations b ON ((a.stamparticlecode = b.stamparticlecode)))
     JOIN kaverimrg.registrationarticles d ON ((b.regarticlecode = d.regarticlecode)));


ALTER TABLE kaverimrg.reg_article_sub_article_mapping OWNER TO postgres;

