                            mv.unitid AS measurementcode,
                            NULL::numeric AS rate,
                            CURRENT_DATE AS effectivedate,
                            (CURRENT_DATE + 1) AS effectivetodate
                           FROM kaverimrg.mas_valuationrates mv
                          WHERE ((mv.roadcode = rm.roadcode) AND (mv.agrilandtypeid IS NULL) AND (mv.amenitiesid IS NULL) AND (NOT ((mv.roadcode, mv.propertytypeid) IN ( SELECT op.roadcode,
                                    op.propertytypeid
                                   FROM kaverimrg.openbuiltratedetail op
                                  WHERE (op.roadcode = rm.roadcode)))))) ra
                     JOIN kaverimrg.propertytypemaster ptm ON ((ptm.propertytypeid = ra.propertytypeid)))
                     LEFT JOIN kaverimrg.mas_valuationrates val ON (((val.roadcode = ra.roadcode) AND (vm.srocode = val.srocode) AND (ra.propertytypeid = val.propertytypeid) AND (COALESCE(val.effectivedate, ((CURRENT_DATE + 1))::timestamp without time zone) > CURRENT_DATE))))
                     LEFT JOIN kaverimrg.propertytypemaster ptm_val ON ((val.propertytypeid = ptm_val.propertytypeid)))
                  WHERE ((ra.roadcode = rm.roadcode) AND (CURRENT_DATE >= ra.effectivedate) AND (CURRENT_DATE <= ra.effectivetodate))) nonagri) AS nonagri_val,
    ( SELECT array_to_json(array_agg(row_to_json(nonagri_flat.*))) AS array_to_json
           FROM ( SELECT ra.propertytypeid,
                    ptm.propertytypename,
                    ra.amenitiesid,
                    amn.namewithamenities,
                    ra.floorid,
                    ra.measurementcode AS unitid,
                    ra.rate,
                    val.propertytypeid AS propertytypeid_val,
                    val.amenitiesid AS amenitiesid_val,
                    amn_val.namewithamenities AS namewithamenities_val,
                    val.floorid AS floorid_val,
                    val.unitid AS unitid_val,
                    val.rate AS rate_val,
                    val.valratedetailid,
                        CASE
                            WHEN (val.valrateheaderid IS NULL) THEN false
                            ELSE true
                        END AS isdisable
                   FROM ((((( SELECT op.roadid AS roadcode,
                            op.propertytypeid,
                            op.amenitiesid,
                            op.floorid,
                            op.unitid AS measurementcode,
                            op.rate,
                            op.effectivedate,
                            COALESCE(lead(op.effectivedate, 1) OVER (PARTITION BY op.roadid, op.propertytypeid, op.amenitiesid, op.floorid ORDER BY op.effectivedate), (CURRENT_DATE)::timestamp without time zone) AS effectivetodate
                           FROM kaverimrg.mas_val_flatrates op
                          WHERE ((op.roadid = rm.roadcode) AND (op.amenitiesid IS NOT NULL))
                        UNION
                         SELECT mv.roadcode,
                            mv.propertytypeid,
                            mv.amenitiesid,
                            mv.floorid,
                            mv.unitid AS measurementcode,
                            NULL::numeric AS rate,
                            CURRENT_DATE AS effectivedate,
                            (CURRENT_DATE + 1) AS effectivetodate
                           FROM kaverimrg.mas_valuationrates mv
                          WHERE ((mv.roadcode = rm.roadcode) AND (mv.amenitiesid IS NOT NULL) AND (NOT ((mv.roadcode, mv.propertytypeid, mv.amenitiesid, mv.floorid) IN ( SELECT op.roadid,
                                    op.propertytypeid,
                                    op.amenitiesid,
                                    op.floorid
                                   FROM kaverimrg.mas_val_flatrates op
                                  WHERE (op.roadid = rm.roadcode)))))) ra
                     JOIN kaverimrg.mas_val_apartmentsamenities amn ON ((amn.amenitiesid = ra.amenitiesid)))
                     JOIN kaverimrg.propertytypemaster ptm ON ((ptm.propertytypeid = ra.propertytypeid)))
                     LEFT JOIN kaverimrg.mas_valuationrates val ON (((val.roadcode = ra.roadcode) AND (vm.srocode = val.srocode) AND (val.amenitiesid IS NOT NULL) AND (ra.amenitiesid = val.amenitiesid) AND (COALESCE(val.effectivedate, ((CURRENT_DATE + 1))::timestamp without time zone) > CURRENT_DATE))))
                     LEFT JOIN kaverimrg.mas_val_apartmentsamenities amn_val ON ((val.amenitiesid = amn_val.amenitiesid)))
                  WHERE ((ra.roadcode = rm.roadcode) AND (CURRENT_DATE >= ra.effectivedate) AND (CURRENT_DATE <= ra.effectivetodate))) nonagri_flat) AS nonagri_flat_val
   FROM ((kaverimrg.roadmaster rm
     JOIN kaverimrg.villagemaster_bck_12062023 vm ON ((vm.villagecode = rm.villagecode)))
     JOIN kaverimrg.hoblimaster_bck_12062023 h ON ((vm.hoblicode = h.hoblicode)));


ALTER TABLE kaverimrg.view_fetch_masterval_road_060723 OWNER TO postgres;

