    to_char(a.applicationstartdate, 'HH24:MI:SS'::text) AS "time",
    b.gscno AS sakalanumber,
    a.currentstatus,
    c.wrkflowstatusnamee AS applicationstatus
   FROM ((kaverimrg.applicantapplicationdetails a
     JOIN kaverimrg.sakala_partydetails b ON ((a.srocode = b.srocode)))
     JOIN kaverimrg.wrkflowmaster c ON (((a.currentstatus)::text = (c.wrkflowstatusid)::text)));


