--
-- Name: vw_citizen_dashbaord; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_citizen_dashbaord AS
 SELECT app.citizenid,
    app.applicationnumber,
    COALESCE(app.regsrocode, app.srocode) AS srocode,
    app.applicationstartdate,
    app.applicationenddate,
    app.applicationdate,
    app.issubmitted,
    app.isduecorrection,
    app.ispayment,
    app.isdueschedule,
    app.assignedto,
    app.applicationtypeid,
    ser.servicename,
    app.currentstatus,
    wrk.wrkflowstatusnamee AS currentstatusname,
    sr.sronamee AS sroname,
    sr.sronamek,
    app.remarks,
    ( SELECT ams_reg_epaymenttransdetails.deptreferencecode
           FROM kaverimrg.ams_reg_epaymenttransdetails
          WHERE (((ams_reg_epaymenttransdetails.applicationnumber)::text = (app.applicationnumber)::text) AND (ams_reg_epaymenttransdetails.isdelete IS NULL))
          ORDER BY ams_reg_epaymenttransdetails.inserteddatetime DESC
         LIMIT 1) AS deptreferencecode
   FROM (((kaverimrg.applicantapplicationdetails app
     JOIN kaverimrg.servicesmaster ser ON ((app.applicationtypeid = ser.serviceid)))
     JOIN kaverimrg.wrkflowmaster wrk ON (((app.currentstatus)::text = (wrk.wrkflowstatusid)::text)))
     LEFT JOIN kaverimrg.sromaster sr ON ((sr.srocode = COALESCE(app.regsrocode, app.srocode))))
  WHERE (app.isdeleted = false)
  ORDER BY app.applicationstartdate DESC;


ALTER TABLE kaverimrg.vw_citizen_dashbaord OWNER TO postgres;

