--
-- Name: vw_cnt_totalapplication; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_cnt_totalapplication AS
 SELECT DISTINCT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    d.bookid,
    bm.booknameenglish AS bookname,
    sum(
        CASE
            WHEN (d.finalregistrationnumber IS NOT NULL) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.applicationtypeid, d.bookid) AS cnt_totalapplication
   FROM (((kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
     JOIN kaverimrg.documentmaster d ON (((d.applicationnumber)::text = (ad.applicationnumber)::text)))
     JOIN kaverimrg.booktypemaster bm ON ((d.bookid = bm.bookid)))
  WHERE (((ad.currentstatus)::text = 'CD120'::text) AND (bm.bookid IS NOT NULL))
UNION ALL
 SELECT DISTINCT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    NULL::integer AS bookid,
    NULL::character varying(150) AS bookname,
    sum(
        CASE
            WHEN ((ad.currentstatus)::text = ANY (ARRAY[('CE110'::character varying)::text, ('CC109'::character varying)::text])) THEN 1
            ELSE 0
        END) OVER (PARTITION BY ad.applicationtypeid, ad.bookid) AS cnt_totalapplication
   FROM (kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
  WHERE ((ad.currentstatus)::text = ANY (ARRAY[('CE110'::character varying)::text, ('CC109'::character varying)::text]))
  ORDER BY 1;


ALTER TABLE kaverimrg.vw_cnt_totalapplication OWNER TO postgres;

--
-- Name: vw_construction_types; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_construction_types AS
 SELECT ct.constructiontypeid,
    ((max(DISTINCT (ct.description)::text) || '; '::text) || string_agg((((ct.floordesc)::text || ' : '::text) || COALESCE(cr.rate, (ct.rate)::numeric)), ' ; '::text ORDER BY ct.floorid)) AS constructiontypedesc,
    max(
        CASE
            WHEN (ct.floorid = 1) THEN COALESCE(cr.rate, (ct.rate)::numeric)
            ELSE NULL::numeric
        END) AS groundfloorrate,
    max(
        CASE
            WHEN (ct.floorid = 1) THEN NULL::numeric
            ELSE COALESCE(cr.rate, (ct.rate)::numeric)
        END) AS abovefloorrate,
    ct.villagecode
   FROM (( SELECT v.villagecode,
            v.villagenamee AS villagename,
            ct_1.description,
            ct_1.constructiontypeid,
                CASE
                    WHEN (b.floorid = 1) THEN ct_1.groundfloorrate
                    ELSE ct_1.abovefloorrate
                END AS rate,
            b.floorid,
            b.description AS floordesc
           FROM kaverimrg.mas_val_constructiontypes ct_1,
            kaverimrg.mas_val_buildingfloors b,
            kaverimrg.villagemaster_bck_12062023 v
          WHERE (b.floorid = ANY (ARRAY[1, 2]))) ct
     LEFT JOIN kaverimrg.mas_val_constructionrates cr ON (((cr.constructiontypeid = ct.constructiontypeid) AND (cr.floorid = ct.floorid) AND (ct.villagecode = cr.villageid))))
  GROUP BY ct.constructiontypeid, ct.villagecode;


ALTER TABLE kaverimrg.vw_construction_types OWNER TO postgres;

--
-- Name: vw_court_order_non_agri; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_court_order_non_agri AS
 SELECT DISTINCT x.propertyid,
    x.sro,
    x.court_order_number,
    x.injuction_or_stay_flag,
    x.survey_no,
    x.currentnumber,
    x.oldnumber,
    x.eastboundary,
    x.westboundary,
    x.northboundary,
    x.southboundary,
    x.area,
    x.description,
    x.applicationnumber,
    x.currentpropertytypeid,
    x.propertynotype,
    x.oldpropertytypeid,
    x.hissa_no
   FROM ( SELECT bpn.id,
            bpn.srocode AS sro,
            bpn.propertyid,
            bpn.injuction_or_stay_flag,
            bpn.orderid,
            bpn.currentpropertytypeid,
            bnt.typenameenglish AS propertynotype,
            bpn.currentnumber,
            bpn.oldpropertytypeid,
            bpn.oldnumber,
            bpn.description AS description1,
            bpn.survey_no,
            bpn.surnoc,
            bpn.hissa_no,
            bp.propertydescription,
            bp.isagriculturalproperty,
            bp.eastboundary,
            bp.northboundary,
            bp.westboundary,
            bp.southboundary,
            bp.area,
            bp.measurementunit,
            mum.descriptionenglish,
            co.ordernumber AS court_order_number,
            co.description,
            co.orderentrydatetime,
            co.iscancelled,
            co.reasonofcancellation,
            pm.applicationnumber
           FROM (((((kaverimrg.bannedpropertynumbers bpn
             JOIN kaverimrg.bannedproperties bp ON ((bpn.propertyid = bp.propertyid)))
             JOIN kaverimrg.propertymaster pm ON (((pm.propertyid = bp.propertyid) AND (bpn.srocode = bp.srocode))))
             JOIN kaverimrg.courtorders co ON (((bp.srocode = co.srocode) AND (bp.orderid = co.orderid))))
             JOIN kaverimrg.measunitmaster mum ON ((mum.unitid = bp.measurementunit)))
             JOIN kaverimrg.propertynotypemaster bnt ON ((bnt.propertytypeid = bpn.currentpropertytypeid)))) x;


ALTER TABLE kaverimrg.vw_court_order_non_agri OWNER TO postgres;

--
-- Name: vw_dailyregister; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_dailyregister AS
 SELECT d.documentid,
