--
-- Name: vw_doc_for_approval_movable; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_doc_for_approval_movable AS
 SELECT a.applicationnumber,
    a.propertyid,
    a.movablepropertydesc,
    a.stamparticlecode,
    b.articlenamee AS stamparticleselected,
    a.stampruleid,
    c.descriptione AS stampsubarticleselected,
    a.regarticlecode,
    d.articlenamee AS registrationfeearticleselected,
    d.bookid,
    e.booknameenglish AS booknumber,
    a.consideration AS totalconsiderationamount,
    a.govtduty,
    ((a.noofscanpages)::numeric * 2.5) AS scanningfees,
    0 AS denotationofstampduty,
    string_agg(
        CASE
            WHEN (f.ispresenter = true) THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS presenter,
    string_agg(
        CASE
            WHEN (f.isexecutor = false) THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS claimant,
    string_agg(
        CASE
            WHEN ((f.isorganization = true) AND (f.isexecutor = true)) THEN concat(f.firstname, f.middlename, f.lastname)
            ELSE NULL::text
        END, ', '::text) AS executant,
    f.age,
    f.sex,
    f.address,
    f.pan,
    f.profession,
    h.name,
    h.age AS witnessage,
    h.sex AS witnesssex,
    h.address AS witnessaddress,
    a.srocode,
    i.sronamee
   FROM ((((((((kaverimrg.propertymaster a
     JOIN kaverimrg.stamparticles b ON (((a.stamparticlecode = b.stamparticlecode) AND (b.stamparticlecode = 5))))
     JOIN kaverimrg.stamprules c ON (((c.stamparticlecode = b.stamparticlecode) AND (c.stampruleid = 19) AND (c.stamparticlecode = 5))))
     JOIN kaverimrg.registrationarticles d ON (((d.regarticlecode = a.regarticlecode) AND (d.regarticlecode = 72))))
     JOIN kaverimrg.booktypemaster e ON ((e.bookid = d.bookid)))
     JOIN kaverimrg.partyinfo f ON ((f.propertyid = a.propertyid)))
     JOIN kaverimrg.partywitness g ON ((g.partyid = f.partyid)))
     JOIN kaverimrg.witnessinfo h ON ((h.witnessid = g.witnessid)))
     JOIN kaverimrg.sromaster i ON ((i.srocode = a.srocode)))
  GROUP BY a.propertyid, a.movablepropertydesc, a.stamparticlecode, b.articlenamee, a.stampruleid, c.descriptione, a.regarticlecode, d.articlenamee, d.bookid, e.booknameenglish, a.consideration, a.govtduty, a.noofscanpages, f.age, f.sex, f.address, f.pan, f.profession, f.partyid, h.name, h.age, h.sex, h.address, h.profession, a.srocode, i.sronamee, a.applicationnumber;


ALTER TABLE kaverimrg.vw_doc_for_approval_movable OWNER TO postgres;

