ALTER TABLE kaverimrg.vw_fee_calculation_amount_details_dept_dummy OWNER TO postgres;

--
-- Name: vw_fee_calculation_amount_details_dept_v2; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fee_calculation_amount_details_dept_v2 AS
(
         SELECT 'Old Payment Details'::text AS usertype,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN ff.propertyid
                    ELSE (0)::bigint
                END AS propertyid,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN (ff.applicationnumber)::text
                    ELSE NULL::text
                END AS applicationnumber,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN ff.isexempted
                    ELSE NULL::boolean
                END AS isexempted,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN (ff.exemptdescription)::text
                    ELSE NULL::text
                END AS exemptdescription,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN (ff.exemtype)::text
                    ELSE NULL::text
                END AS exemtype,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN ff.exemamount
                    ELSE 0
                END AS exemamount,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN (ff.exemdocpath)::text
                    ELSE NULL::text
                END AS exemdocpath,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN (ff.denodocpath)::text
                    ELSE NULL::text
                END AS denodocpath,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.cess)
                    ELSE (0)::numeric
                END AS cess,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.deficit_stamp_duty)
                    ELSE (0)::numeric
                END AS deficitstampduty,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.mutation_fee)
                    ELSE (0)::numeric
                END AS mutationfee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.registration_fee)
                    ELSE (0)::numeric
                END AS registrationfee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.service_charge)
                    ELSE (0)::numeric
                END AS servicecharge,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.stamp_duty)
                    ELSE (0)::numeric
                END AS stampduty,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.surcharge)
                    ELSE (0)::numeric
                END AS surcharge,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.duplicate_stamp_duty)
                    ELSE (0)::numeric
                END AS duplicatestampduty,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.duplicate_registration_fee)
                    ELSE (0)::numeric
                END AS duplicateregistrationfee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.private_attendance_fee)
                    ELSE (0)::numeric
                END AS privateattandancefee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.consenting_fee)
                    ELSE (0)::numeric
                END AS consentingfee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.memo_fees)
                    ELSE (0)::numeric
                END AS memofee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.adjudication_fee)
                    ELSE (0)::numeric
                END AS adjudicationfee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.e_stamp_fee)
                    ELSE (0)::numeric
                END AS estampfee,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN sum(ff.govt_duty_before_exemption)
                    ELSE (0)::numeric
                END AS govtdutybeforeexem,
                CASE
                    WHEN (count(ff.applicationo) > 0) THEN ( SELECT sum(fss.sro_amountrequired) AS sum
                       FROM ( SELECT
                                    CASE
WHEN (frm.ismanualfee = true) THEN (sum(COALESCE(fr.sroamountrequired, (0)::numeric)) - sum(COALESCE(fr.amountpaid, (0)::numeric)))
ELSE '0'::numeric
                                    END AS sro_amountrequired
                               FROM (kaverimrg.feesrequired fr
                                 JOIN kaverimrg.feesrulemaster frm ON ((fr.feerulecode = frm.feerulecode)))
                              WHERE ((fr.receiptid IS NULL) AND ((fr.applicationnumber)::text = (ff.applicationnumber)::text))
                              GROUP BY fr.applicationnumber, frm.ismanualfee) fss)
                    ELSE (0)::numeric
                END AS otherfee
           FROM ( SELECT ss.propertyid,
                    ss.applicationnumber,
                    ss.applicationo,
                    ss.isexempted,
                    ss.exemptdescription,
                    ss.exemtype,
                    ss.exemamount,
                    ss.exemdocpath,
                    ss.denodocpath,
                        CASE
                            WHEN (ss.feerulecode = 1) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS registration_fee,
                        CASE
                            WHEN (ss.feerulecode = 35) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS deficit_stamp_duty,
                        CASE
                            WHEN (ss.feerulecode = 58) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS surcharge,
                        CASE
                            WHEN (ss.feerulecode = 2) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS service_charge,
                        CASE
                            WHEN (ss.feerulecode = 6) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS mutation_fee,
                        CASE
                            WHEN (ss.feerulecode = 7) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS private_attendance_fee,
                        CASE
                            WHEN (ss.feerulecode = 34) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS consenting_fee,
                        CASE
                            WHEN (ss.feerulecode = 36) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS stamp_duty,
                        CASE
                            WHEN (ss.feerulecode = 59) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS cess,
                        CASE
                            WHEN (ss.feerulecode = 64) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS duplicate_stamp_duty,
                        CASE
                            WHEN (ss.feerulecode = 65) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS duplicate_registration_fee,
                        CASE
                            WHEN (ss.feerulecode = 88) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS adjudication_fee,
                        CASE
                            WHEN (ss.feerulecode = 89) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS e_stamp_fee,
                        CASE
                            WHEN (ss.feerulecode = 90) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS memo_fees,
                        CASE
                            WHEN (ss.feerulecode = 104) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS denotation_of_stamp_duty,
                        CASE
                            WHEN (ss.feerulecode = 105) THEN (sum(ss.sroamountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
                        END AS govt_duty_before_exemption
                   FROM ( SELECT b.feerulecode,
                            b.applicationnumber,
                            b.propertyid,
                            b.isexempted,
                            b.exemptdescription,
                            b.exemtype,
                            b.exemamount,
                            b.sroamountrequired,
                            b.exemdocpath,
                            b.denodocpath,
                            f.descriptione,
                            b.amountpaid,
                            fk.applicationnumber AS applicationo
                           FROM ((kaverimrg.feesrequired b
                             JOIN kaverimrg.feesrequired_paymentchk fk ON (((b.applicationnumber)::text = (fk.applicationnumber)::text)))
                             LEFT JOIN kaverimrg.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                          WHERE (b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 35, 36, 58, 59, 64, 65, 88, 89, 90, 104, 105]))
                          GROUP BY b.feerulecode, fk.applicationnumber, b.amountpaid, b.applicationnumber, b.propertyid, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.sroamountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
                  GROUP BY ss.propertyid, ss.applicationo, ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.sroamountrequired) ff
          GROUP BY ff.propertyid, ff.applicationnumber, ff.isexempted, ff.exemptdescription, ff.exemtype, ff.exemamount, ff.exemdocpath, ff.denodocpath
        UNION
         SELECT 'citizen'::text AS usertype,
            ff.propertyid,
            (ff.applicationnumber)::text AS applicationnumber,
            ff.isexempted,
            (ff.exemptdescription)::text AS exemptdescription,
            (ff.exemtype)::text AS exemtype,
            ff.exemamount,
            (ff.exemdocpath)::text AS exemdocpath,
            (ff.denodocpath)::text AS denodocpath,
            sum(ff.cess) AS cess,
