                  WHERE ((b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 35, 36, 58, 59, 64, 65, 88, 89, 90, 104, 105])) AND (b.receiptid IS NULL))
                  GROUP BY b.feerulecode, b.applicationnumber, b.propertyid, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.sfdaamountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
