          GROUP BY ss.propertyid, ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.sroamountrequired) ff
