--
-- Name: vw_fee_calculation_amount_details_dept_v2_testing; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fee_calculation_amount_details_dept_v2_testing AS
 SELECT 'citizen'::text AS usertype,
    ff.propertyid,
    (ff.applicationnumber)::text AS applicationnumber,
    ff.isexempted,
    (ff.exemptdescription)::text AS exemptdescription,
    (ff.exemtype)::text AS exemtype,
    ff.exemamount,
    (ff.exemdocpath)::text AS exemdocpath,
    (ff.denodocpath)::text AS denodocpath,
    sum(ff.cess) AS cess,
    sum(ff.deficit_stamp_duty) AS deficitstampduty,
    sum(ff.mutation_fee) AS mutationfee,
    sum(ff.registration_fee) AS registrationfee,
    sum(ff.service_charge) AS servicecharge,
    sum(ff.stamp_duty) AS stampduty,
    sum(ff.surcharge) AS surcharge,
    sum(ff.duplicate_stamp_duty) AS duplicatestampduty,
    sum(ff.duplicate_registration_fee) AS duplicateregistrationfee,
    sum(ff.private_attendance_fee) AS privateattandancefee,
    sum(ff.consenting_fee) AS consentingfee,
    sum(ff.memo_fees) AS memofee,
    sum(ff.adjudication_fee) AS adjudicationfee,
    sum(ff.e_stamp_fee) AS estampfee,
    sum(ff.govt_duty_before_exemption) AS govtdutybeforeexem,
    ( SELECT sum(fss.sro_amountrequired) AS sum
           FROM ( SELECT
                        CASE
                            WHEN (frm.ismanualfee = true) THEN (sum(COALESCE(fr.amountrequired, (0)::numeric)) - sum(COALESCE(fr.amountpaid, (0)::numeric)))
                            ELSE '0'::numeric
