                  WHERE ((fr.receiptid IS NULL) AND ((fr.applicationnumber)::text = (ff.applicationnumber)::text))
                  GROUP BY fr.applicationnumber, frm.ismanualfee) fss) AS otherfee
   FROM ( SELECT ss.propertyid,
            ss.applicationnumber,
            ss.isexempted,
            ss.exemptdescription,
            ss.exemtype,
            ss.exemamount,
            ss.exemdocpath,
            ss.denodocpath,
                CASE
                    WHEN (ss.feerulecode = 1) THEN (sum(ss.amountrequired) - sum(COALESCE(ss.amountpaid, (0)::numeric)))
