                    ELSE '0'::numeric
                END AS govt_duty_before_exemption
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.propertyid,
                    b.isexempted,
                    b.exemptdescription,
                    b.exemtype,
                    b.exemamount,
                    b.amountrequired,
                    b.exemdocpath,
                    b.denodocpath,
                    f.descriptione,
