                        END AS private_attendance_fee,
                        CASE
                            WHEN (ss.feerulecode = 34) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS consenting_fee,
                        CASE
                            WHEN (ss.feerulecode = 36) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS stamp_duty,
                        CASE
                            WHEN (ss.feerulecode = 59) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS cess,
                        CASE
                            WHEN (ss.feerulecode = 64) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS duplicate_stamp_duty,
                        CASE
                            WHEN (ss.feerulecode = 65) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS duplicate_registration_fee,
                        CASE
                            WHEN (ss.feerulecode = 88) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
                        END AS adjudication_fee,
                        CASE
                            WHEN (ss.feerulecode = 89) THEN sum(COALESCE(ss.amountrequired, (0)::numeric))
                            ELSE '0'::numeric
