    sum(ff.e_stamp_fee) AS estampfee,
    sum(ff.denotation_of_stamp_duty) AS denotationofstampduty,
    sum(ff.govt_duty_before_exemption) AS govtdutybeforeexem
   FROM ( SELECT ss.propertyid,
            ss.applicationnumber,
            ss.isexempted,
            ss.exemptdescription,
            ss.exemtype,
            ss.exemamount,
            ss.exemdocpath,
            ss.denodocpath,
                CASE
                    WHEN (ss.feerulecode = 1) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS registration_fee,
                CASE
                    WHEN (ss.feerulecode = 35) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS deficit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 58) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS surcharge,
                CASE
                    WHEN (ss.feerulecode = 2) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS service_charge,
                CASE
                    WHEN (ss.feerulecode = 6) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS mutation_fee,
                CASE
                    WHEN (ss.feerulecode = 7) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS private_attendance_fee,
                CASE
                    WHEN (ss.feerulecode = 34) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS consenting_fee,
                CASE
                    WHEN (ss.feerulecode = 36) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 59) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS cess,
                CASE
                    WHEN (ss.feerulecode = 64) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS duplicate_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 65) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS duplicate_registration_fee,
                CASE
                    WHEN (ss.feerulecode = 88) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS adjudication_fee,
                CASE
                    WHEN (ss.feerulecode = 89) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS e_stamp_fee,
                CASE
                    WHEN (ss.feerulecode = 90) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS memo_fees,
                CASE
                    WHEN (ss.feerulecode = 104) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS denotation_of_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 105) THEN sum(ss.sroamountrequired)
                    ELSE '0'::numeric
                END AS govt_duty_before_exemption
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.propertyid,
                    b.isexempted,
                    b.exemptdescription,
                    b.exemtype,
                    b.exemamount,
                    b.sroamountrequired,
                    b.exemdocpath,
                    b.denodocpath,
                    f.descriptione
                   FROM (kaverimrg.feesrequired b
                     LEFT JOIN kaverimrg.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE (b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 35, 36, 58, 59, 64, 65, 88, 89, 90, 104, 105]))
                  GROUP BY b.feerulecode, b.applicationnumber, b.propertyid, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.sroamountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
          GROUP BY ss.propertyid, ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.sroamountrequired) ff
  GROUP BY ff.propertyid, ff.applicationnumber, ff.isexempted, ff.exemptdescription, ff.exemtype, ff.exemamount, ff.exemdocpath, ff.denodocpath;


