--
-- Name: vw_fee_calculation_and_amount_details_dept_bck_10042023; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fee_calculation_and_amount_details_dept_bck_10042023 AS
 SELECT v.usertype,
    v.propertyid,
    v.applicationnumber,
    v.isexempted,
    v.exemptdescription,
    v.exemtype,
    v.exemamount,
    v.exemdocpath,
    v.denodocpath,
    v.cess,
    v.deficitstampduty,
    v.mutationfee,
    v.registrationfee,
    v.servicecharge,
    v.stampduty,
    v.surcharge,
    v.duplicatestampduty,
    v.duplicateregistrationfee,
    v.privateattandancefee,
    v.consentingfee,
    v.memofee,
    v.adjudicationfee,
    v.estampfee,
        CASE
            WHEN (v.usertype = 'citizen'::text) THEN sub.citizen_amountrequired
            WHEN (v.usertype = 'sfda'::text) THEN sub.sfda_amountrequired
            WHEN (v.usertype = 'sro'::text) THEN sub.sro_amountrequired
            ELSE NULL::numeric
        END AS othersfee,
    v.denotationofstampduty,
    v.govtdutybeforeexem,
    (v.govtdutybeforeexem - v.stampduty) AS finalexemamt
   FROM (kaverimrg.vw_fee_calculation_amount_details_dept_v3_saurabh v
     LEFT JOIN ( SELECT ss.applicationnumber,
            sum(ss.citizen_amountrequired) AS citizen_amountrequired,
            sum(ss.sfda_amountrequired) AS sfda_amountrequired,
            sum(ss.sro_amountrequired) AS sro_amountrequired
           FROM ( SELECT fr.applicationnumber,
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(fr.amountrequired)
                            ELSE (0)::numeric
                        END AS citizen_amountrequired,
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(fr.sfdaamountrequired)
                            ELSE (0)::numeric
                        END AS sfda_amountrequired,
                        CASE
                            WHEN (frm.ismanualfee = true) THEN sum(fr.sroamountrequired)
                            ELSE (0)::numeric
                        END AS sro_amountrequired
                   FROM (kaverimrg.feesrequired fr
                     JOIN kaverimrg.feesrulemaster frm ON ((fr.feerulecode = frm.feerulecode)))
                  GROUP BY fr.applicationnumber, frm.ismanualfee) ss
          GROUP BY ss.applicationnumber) sub ON ((v.applicationnumber = (sub.applicationnumber)::text)))
  ORDER BY v.usertype;


