                  WHERE ((b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 36, 58, 59, 64, 65, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 104, 105])) AND (b.exemamount IS NOT NULL))
                  GROUP BY b.feerulecode, b.regexemtype, b.regexemamount, b.undervaluationamount, b.applicationnumber, b.propertyid, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.amountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
          GROUP BY ss.propertyid, ss.regexemtype, ss.regexemamount, ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.amountrequired) ff
  GROUP BY ff.propertyid, ff.applicationnumber, ff.regexemtype, ff.regexemamount, ff.isexempted, ff.exemptdescription, ff.exemtype, ff.exemamount, ff.exemdocpath, ff.denodocpath;


ALTER TABLE kaverimrg.vw_fee_calculation_details_underval_v2 OWNER TO postgres;

--
-- Name: vw_fee_calculation_details_v2; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fee_calculation_details_v2 AS
 SELECT DISTINCT (ff.applicationnumber)::text AS applicationnumber,
    ff.isexempted,
    (ff.exemptdescription)::text AS exemptdescription,
    (ff.exemtype)::text AS exemtype,
    ff.exemamount,
    ff.regexemtype,
    ff.regexemamount,
    (ff.exemdocpath)::text AS exemdocpath,
    (ff.denodocpath)::text AS denodocpath,
    sum(ff.cess) AS cess,
    sum(ff.deficit_stamp_duty) AS deficitstampduty,
    sum(ff.mutation_fee) AS mutationfee,
    sum(ff.registration_fee) AS registrationfee,
    sum(ff.service_charge) AS servicecharge,
    sum(ff.stamp_duty) AS stampduty,
    sum(ff.surcharge) AS surcharge,
    sum(ff.duplicate_stamp_duty) AS duplicatestampduty,
    sum(ff.duplicate_registration_fee) AS duplicateregistrationfee,
    sum(ff.private_attendance_fee) AS privateattandancefee,
    sum(ff.consenting_fee) AS consentingfee,
    sum(ff.memo_fees) AS memofees,
    sum(ff.adjudication_fee) AS adjudicationfee,
    sum(ff.e_stamp_fee) AS estampfee,
    sum(ff.denotation_of_stamp_duty) AS denotationofstampduty,
    sum(ff.affidavit_stamp_duty) AS affidavitstampduty,
    sum(ff.preamption_stamp_duty) AS preamptionstampduty,
    sum(ff.appeal_fee) AS appealfee,
    sum(ff.document_with_drawal_fee) AS documentwithdrawalfee,
    sum(ff.holiday_fee) AS holidayfee,
    sum(ff.will_deposit_fee) AS willdepositfee,
    sum(ff.filing_of_trasnlation_fee) AS filingoftrasnlationfee,
    sum(ff.safe_custody_fee) AS safecustodyfee,
    sum(ff.govt_duty_before_exemption) AS govtdutybeforeexem
   FROM ( SELECT ss.propertyid,
            ss.applicationnumber,
            ss.isexempted,
            ss.exemptdescription,
            ss.exemtype,
            ss.exemamount,
            ss.regexemtype,
            ss.regexemamount,
            ss.exemdocpath,
            ss.denodocpath,
                CASE
                    WHEN (ss.feerulecode = 1) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS registration_fee,
                CASE
                    WHEN (ss.feerulecode = 35) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS deficit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 58) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS surcharge,
                CASE
                    WHEN (ss.feerulecode = 2) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS service_charge,
                CASE
                    WHEN (ss.feerulecode = 6) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS mutation_fee,
                CASE
                    WHEN (ss.feerulecode = 7) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS private_attendance_fee,
                CASE
                    WHEN (ss.feerulecode = 34) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS consenting_fee,
                CASE
                    WHEN (ss.feerulecode = 36) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 59) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS cess,
                CASE
                    WHEN (ss.feerulecode = 64) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS duplicate_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 65) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS duplicate_registration_fee,
                CASE
                    WHEN (ss.feerulecode = 88) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS adjudication_fee,
                CASE
                    WHEN (ss.feerulecode = 89) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS e_stamp_fee,
                CASE
                    WHEN (ss.feerulecode = 90) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS memo_fees,
                CASE
                    WHEN (ss.feerulecode = 91) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS affidavit_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 92) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS preamption_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 93) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS appeal_fee,
                CASE
                    WHEN (ss.feerulecode = 94) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS document_with_drawal_fee,
                CASE
                    WHEN (ss.feerulecode = 95) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS holiday_fee,
                CASE
                    WHEN (ss.feerulecode = 96) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS will_deposit_fee,
                CASE
                    WHEN (ss.feerulecode = 97) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS filing_of_trasnlation_fee,
                CASE
                    WHEN (ss.feerulecode = 98) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS safe_custody_fee,
                CASE
                    WHEN (ss.feerulecode = 104) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS denotation_of_stamp_duty,
                CASE
                    WHEN (ss.feerulecode = 105) THEN sum(ss.amountrequired)
                    ELSE '0'::numeric
                END AS govt_duty_before_exemption
           FROM ( SELECT b.feerulecode,
                    b.applicationnumber,
                    b.propertyid,
                    b.isexempted,
                    b.exemptdescription,
                    b.exemtype,
                    b.exemamount,
                    b.regexemtype,
                    b.regexemamount,
                    b.amountrequired,
                    b.exemdocpath,
                    b.denodocpath,
                    f.descriptione
                   FROM (kaverimrg.feesrequired b
                     LEFT JOIN kaverimrg.feesrulemaster f ON ((b.feerulecode = f.feerulecode)))
                  WHERE ((b.feerulecode = ANY (ARRAY[1, 2, 6, 7, 34, 36, 58, 59, 64, 65, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 104, 105])) AND (b.exemamount IS NOT NULL))
                  GROUP BY b.feerulecode, b.regexemtype, b.regexemamount, b.applicationnumber, b.propertyid, b.isexempted, b.exemptdescription, b.exemtype, b.exemamount, b.amountrequired, b.exemdocpath, b.denodocpath, f.descriptione) ss
          GROUP BY ss.propertyid, ss.regexemtype, ss.regexemamount, ss.applicationnumber, ss.isexempted, ss.exemptdescription, ss.exemtype, ss.exemamount, ss.exemdocpath, ss.denodocpath, ss.feerulecode, ss.amountrequired) ff
  GROUP BY ff.propertyid, ff.applicationnumber, ff.regexemtype, ff.regexemamount, ff.isexempted, ff.exemptdescription, ff.exemtype, ff.exemamount, ff.exemdocpath, ff.denodocpath;


ALTER TABLE kaverimrg.vw_fee_calculation_details_v2 OWNER TO postgres;

--
-- Name: vw_feecalculation_movable; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_feecalculation_movable AS
 SELECT a.documentid,
    a.feerulecode,
    b.descriptione,
    a.isexempted,
    a.exemptdescription,
    a.feecalculationstring,
    a.amountrequired,
    c.govtduty AS governmentduty,
    c.noofscanpages AS numberofpages,
    f.isinpercentage,
    c.consideration AS considerationamount,
    a.applicationnumber
   FROM (((kaverimrg.feesrequired a
     JOIN kaverimrg.feesrulemaster b ON ((a.feerulecode = b.feerulecode)))
     JOIN kaverimrg.propertymaster c ON (((c.propertyid = a.propertyid) AND ((a.applicationnumber)::text = (c.applicationnumber)::text))))
     JOIN kaverimrg.stamprules f ON (((f.stampruleid = c.stampruleid) AND (c.ismovableproperty = true) AND ((a.applicationnumber)::text = 'PRP-12012022-02236'::text))))
  ORDER BY a.feerulecode;


