-- Name: vw_fees_landingpage; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fees_landingpage AS
 SELECT DISTINCT sum(rd.amountpaid) OVER (PARTITION BY rd.feerulecode) AS feesamount,
    sum(rd.amountpaid) OVER () AS totalamount,
    rd.feerulecode,
    fm.descriptione AS feesname
   FROM (kaverimrg.receiptdetails rd
     JOIN kaverimrg.feesrulemaster fm ON ((rd.feerulecode = fm.feerulecode)))
  WHERE (rd.feerulecode = ANY (ARRAY[1, 36]));


