--
-- Name: vw_feesrule_mapping; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_feesrule_mapping AS
 SELECT frm.feerulecode,
    frm.descriptione AS feerulename,
    ah.deptpurposeid,
    ah.name AS accntheadname,
    ah.headofaccount AS prpsname,
    ah.treasurynumber AS trsrycode,
    substr((ah.headofaccount)::text, 1, 4) AS prpsnamehead,
    ah.isactive,
    ah.issubpurposeexist,
    sm.servicename,
    sm.nomenclature,
    frm.subrefcode
   FROM (((kaverimrg.feesrulemaster frm
     LEFT JOIN kaverimrg.mas_ams_accountheadsfeetypesmapping ahmap ON (((frm.feerulecode = ahmap.feeruleid) AND (ahmap.isactive = true))))
     LEFT JOIN kaverimrg.mas_ams_accountheads ah ON (((ah.deptpurposeid = ahmap.deptpurposeid) AND (ah.serviceid = ahmap.serviceid))))
     LEFT JOIN kaverimrg.servicesmaster sm ON ((sm.serviceid = ah.serviceid)));


ALTER TABLE kaverimrg.vw_feesrule_mapping OWNER TO postgres;

--
-- Name: vw_fetch_add_order_details; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_add_order_details AS
 SELECT a.orderid,
    to_char(a.orderdate, 'YYYY/MM/DD'::text) AS orderdate,
    a.relativepath,
    a.absolutefilepath,
    d.districtnamee,
    a.documentid,
    a.statuscode,
    a.correctionnote,
    a.documentrescan,
    b.note_enteredpart,
    a.rescandocument
   FROM ((kaverimrg.dec_drordermaster a
     LEFT JOIN kaverimrg.dec_drpndnote b ON ((a.orderid = b.orderid)))
     LEFT JOIN kaverimrg.districtmaster d ON ((a.districtcode = d.districtcode)))
  ORDER BY a.orderid DESC;


ALTER TABLE kaverimrg.vw_fetch_add_order_details OWNER TO postgres;

--
-- Name: vw_fetch_cc; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_cc AS
 SELECT dm.documentid,
    s.districtcode,
    d.districtnamee,
    s.srocode,
    s.sronamee,
    dm.regarticlecode,
    dm.documentnumber,
    (
        CASE
            WHEN ((to_char(dm.registrationdatetime, 'MM'::text))::bigint > 3) THEN (((to_char(dm.registrationdatetime, 'YYYY'::text))::bigint || '-'::text) || to_char((dm.registrationdatetime + '1 year'::interval), 'YY'::text))
            ELSE ((((to_char(dm.registrationdatetime, 'YYYY'::text))::bigint - 1) || '-'::text) || to_char(dm.registrationdatetime, 'YY'::text))
        END)::character varying AS yearofregistration,
    dm.bookid,
    dm.pagecount,
    dm.uploaddocdeedpath,
    r.referencetext,
    r.documenttypeid,
    doc.documenttypedesc AS documenttype
   FROM ((((kaverimrg.documentmaster dm
     JOIN kaverimrg.sromaster s ON ((s.srocode = dm.srocode)))
     JOIN kaverimrg.districtmaster_bck_12062023 d ON ((d.districtcode = s.districtcode)))
     LEFT JOIN kaverimrg.referencemaster r ON ((r.documentid = dm.documentid)))
     LEFT JOIN kaverimrg.documenttypemaster doc ON ((r.documenttypeid = doc.documenttypeid)))
  WHERE (dm.isregistrationcompleted = true);


ALTER TABLE kaverimrg.vw_fetch_cc OWNER TO postgres;

--
-- Name: vw_fetch_court_order_details; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_court_order_details AS
 SELECT DISTINCT x.applicationnumber,
    x.propertyid,
    x.sro,
    x.court_order_number,
    x.injuction_or_stay_flag,
    x.survey_no,
    x.currentnumber,
    x.oldnumber,
    x.eastboundary,
    x.westboundary,
    x.northboundary,
    x.southboundary,
    x.area,
    x.description AS court_order_details,
    x.propertydescription AS description,
    x.currentpropertytypeid,
    x.oldpropertytypeid,
    x.hissa_no,
    x.propertytypename,
    x.issuingauthority,
    x.issueddate,
    x.villagecode
   FROM ( SELECT bpn.id,
            sm.sronamee AS sro,
            bpn.injuction_or_stay_flag,
            bpn.orderid,
            bpn.currentpropertytypeid,
            bpn.currentnumber,
            bpn.oldpropertytypeid,
            bpn.oldnumber,
            bpn.description AS description1,
            bpn.survey_no,
            bpn.surnoc,
            bpn.hissa_no,
            bp.propertydescription,
            bp.isagriculturalproperty,
            bp.eastboundary,
            bp.northboundary,
            bp.westboundary,
            bp.southboundary,
            bp.area,
            bp.measurementunit,
            mum.descriptionenglish,
            co.ordernumber AS court_order_number,
            co.description,
            co.orderentrydatetime,
            co.iscancelled,
            co.reasonofcancellation,
            pm.applicationnumber,
            pm.propertyid,
            pt.typenameenglish AS propertytypename,
            co.issuingauthority,
            co.issueddate,
            bp.villagecode
           FROM (((((((kaverimrg.courtorders co
             JOIN kaverimrg.bannedpropertynumbers bpn ON (((co.courtorderid = bpn.orderid) AND (co.srocode = bpn.srocode))))
             JOIN kaverimrg.bannedproperties bp ON (((bpn.orderid = bp.orderid) AND (bpn.srocode = bp.srocode) AND (bp.courtpropertyid = bpn.propertyid))))
             JOIN kaverimrg.propertynumberdetails pnd ON (((pnd.currentpropertytypeid = bpn.currentpropertytypeid) AND (bpn.srocode = pnd.srocode) AND
                CASE
                    WHEN (bpn.currentpropertytypeid <> 1) THEN ((pnd.currentnumber)::text = (bpn.currentnumber)::text)
                    ELSE ((bpn.currentnumber)::text = (pnd.currentnumber)::text)
                END)))
             JOIN kaverimrg.propertymaster pm ON (((pm.propertyid = pnd.propertyid) AND (pm.srocode = co.srocode))))
             JOIN kaverimrg.propertynotypemaster pt ON ((pnd.currentpropertytypeid = pt.propertytypeid)))
             JOIN kaverimrg.measunitmaster mum ON ((mum.unitid = bp.measurementunit)))
             JOIN kaverimrg.sromaster sm ON ((sm.srocode = co.srocode)))
          WHERE ((co.isinforce = true) AND (co.iscancelled = false) AND (pnd.currentnumber IS NOT NULL) AND ((pnd.currentnumber)::text <> '0'::text))) x;


ALTER TABLE kaverimrg.vw_fetch_court_order_details OWNER TO postgres;

--
-- Name: vw_fetch_court_order_details_backup_14032023; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_court_order_details_backup_14032023 AS
 SELECT DISTINCT x.applicationnumber,
    x.propertyid,
    x.sro,
    x.court_order_number,
    x.injuction_or_stay_flag,
    x.survey_no,
    x.currentnumber,
    x.oldnumber,
    x.eastboundary,
    x.westboundary,
