    x.propertydescription AS description,
    x.currentpropertytypeid,
    x.oldpropertytypeid,
    x.hissa_no,
    x.propertytypename,
    x.issuingauthority,
    x.issueddate
   FROM ( SELECT bpn.id,
            sm.sronamee AS sro,
            bpn.injuction_or_stay_flag,
            bpn.orderid,
            bpn.currentpropertytypeid,
            bpn.currentnumber,
            bpn.oldpropertytypeid,
            bpn.oldnumber,
            bpn.description AS description1,
            bpn.survey_no,
            bpn.surnoc,
            bpn.hissa_no,
            bp.propertydescription,
            bp.isagriculturalproperty,
            bp.eastboundary,
            bp.northboundary,
            bp.westboundary,
            bp.southboundary,
            bp.area,
            bp.measurementunit,
            mum.descriptionenglish,
            co.ordernumber AS court_order_number,
            co.description,
            co.orderentrydatetime,
            co.iscancelled,
            co.reasonofcancellation,
            pm.applicationnumber,
            pm.propertyid,
            pt.typenameenglish AS propertytypename,
            co.issuingauthority,
            co.issueddate
           FROM (((((((kaverimrg.courtorders co
             LEFT JOIN kaverimrg.bannedpropertynumbers bpn ON ((co.courtorderid = bpn.orderid)))
             JOIN kaverimrg.bannedproperties bp ON ((co.courtorderid = bp.orderid)))
             JOIN kaverimrg.propertynumberdetails pnd ON ((((pnd.currentpropertytypeid = bpn.currentpropertytypeid) AND ((pnd.currentnumber)::text = (bpn.currentnumber)::text) AND (bpn.srocode = pnd.srocode)) OR (((pnd.hissa_no)::text = (bpn.hissa_no)::text) AND (pnd.survey_no = bpn.survey_no) AND (bpn.srocode = pnd.srocode)))))
             JOIN kaverimrg.propertymaster pm ON (((pm.propertyid = pnd.propertyid) AND (pm.srocode = co.srocode))))
             LEFT JOIN kaverimrg.propertynotypemaster pt ON ((bpn.currentpropertytypeid = pt.propertytypeid)))
             LEFT JOIN kaverimrg.measunitmaster mum ON ((mum.unitid = bp.measurementunit)))
             LEFT JOIN kaverimrg.sromaster sm ON ((sm.srocode = co.srocode)))
          WHERE ((co.isinforce = true) AND (pnd.currentnumber IS NOT NULL) AND ((pnd.currentnumber)::text <> '0'::text))) x;


ALTER TABLE kaverimrg.vw_fetch_court_order_details_backup_14032023 OWNER TO postgres;

--
-- Name: vw_fetch_court_order_fruit; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_court_order_fruit AS
 SELECT co.ordernumber,
    bpn.srocode,
    co.issuingauthority,
    co.issueddate,
    co.description AS orderdescription,
    bp.propertydescription,
    bp.villagecode,
    ((bpn.survey_no || '/'::text) || (bpn.hissa_no)::text) AS currentnumber,
    bpn.survey_no,
    bpn.hissa_no
   FROM ((kaverimrg.bannedpropertynumbers bpn
     JOIN kaverimrg.bannedproperties bp ON ((bp.courtpropertyid = bpn.propertyid)))
     JOIN kaverimrg.courtorders co ON (((bpn.srocode = co.srocode) AND (bpn.orderid = co.courtorderid) AND (co.isinforce = true))))
  WHERE (bpn.currentpropertytypeid = 1);


ALTER TABLE kaverimrg.vw_fetch_court_order_fruit OWNER TO postgres;

--
-- Name: vw_fetch_crossref_dashboard; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_crossref_dashboard AS
 SELECT dm.documentid,
    dm.srocode,
    dm.regarticlecode,
    ra.articlenamee AS natureofdocument,
    dm.finalregistrationnumber,
    (dm.registrationdatetime)::date AS registrationdatetime,
    dm.bookid,
    bm.booknameenglish AS bookname,
    dm.documentnumber,
    "right"((dm.finalregistrationnumber)::text, 7) AS finyear,
    dm.olddocreference
   FROM ((kaverimrg.documentmaster dm
     JOIN kaverimrg.registrationarticles ra ON ((dm.regarticlecode = ra.regarticlecode)))
     JOIN kaverimrg.booktypemaster bm ON ((bm.bookid = dm.bookid)))
  WHERE ((dm.regarticlecode = ANY (ARRAY[32, 33, 48, 83, 98, 104, 105])) AND (NOT ((COALESCE(dm.documentid, (0)::bigint), COALESCE(dm.srocode, 0), COALESCE(dm.bookid, 0)) IN ( SELECT COALESCE(referencemaster.documentid, (0)::bigint) AS "coalesce",
            COALESCE(referencemaster.srocode, (0)::bigint) AS "coalesce",
            COALESCE(referencemaster.bookid, 0) AS "coalesce"
           FROM kaverimrg.referencemaster))));


ALTER TABLE kaverimrg.vw_fetch_crossref_dashboard OWNER TO postgres;

--
-- Name: vw_fetch_dept_doc_details; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_dept_doc_details AS
 SELECT DISTINCT dm.applicationnumber,
    ad.srocode,
    ad.applicationtypeid,
    dm.finalregistrationnumber,
    dm.executiondatetime,
    dm.pendingdocumentnumber,
    bm.printablename AS book,
    dm.registrationdatetime,
    pm.sronoofscanpages AS noofscnpages,
    svm.servicename AS applicationtype,
    sm.sronamee AS sroname,
    pm.propertyid,
    dm.presentdatetime,
    dm.documentid,
    sm.sronamek,
    md.isbefore2003
   FROM ((((((kaverimrg.documentmaster dm
     JOIN kaverimrg.sromaster sm ON ((sm.srocode = dm.srocode)))
     JOIN kaverimrg.applicantapplicationdetails ad ON (((ad.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN kaverimrg.minutebook_data md ON (((md.applicationnumber)::text = (ad.applicationnumber)::text)))
     JOIN kaverimrg.propertymaster pm ON ((pm.documentid = dm.documentid)))
     JOIN kaverimrg.servicesmaster svm ON ((svm.serviceid = ad.applicationtypeid)))
     LEFT JOIN kaverimrg.booktypemaster bm ON ((bm.bookid = dm.bookid)));


ALTER TABLE kaverimrg.vw_fetch_dept_doc_details OWNER TO postgres;

--
-- Name: vw_fetch_dept_group; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_dept_group AS
 SELECT dug.groupid,
    dug.groupname,
    dug.groupdesc,
    dug.isactive,
    ( SELECT array_to_json(array_agg(row_to_json(tmp.*))) AS array_to_json
           FROM ( SELECT grm.rollid,
                    d.designame
                   FROM (kaverimrg.group_roll_mapping grm
                     JOIN kaverimrg.desigmaster d ON ((grm.rollid = d.designationid)))
                  WHERE (grm.groupid = dug.groupid)) tmp) AS roleinfo
   FROM kaverimrg.deptmentusergroup dug;


ALTER TABLE kaverimrg.vw_fetch_dept_group OWNER TO postgres;

--
-- Name: vw_fetch_document_search_parameters; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_document_search_parameters AS
 SELECT a.propertyid,
    a.srocode,
    a.sronoofscanpages AS noofscanpages,
    c.sronamee,
    b.documentid,
    b.documentnumber,
    b.bookid,
    d.booknameenglish AS booktype,
        CASE
            WHEN (date_part('month'::text, CURRENT_DATE) <= (3)::double precision) THEN ((to_char((CURRENT_DATE + '-1 years'::interval), 'YYYY'::text) || '-'::text) || to_char((CURRENT_DATE)::timestamp with time zone, 'YY'::text))
            ELSE ((to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text) || '-'::text) || to_char((CURRENT_DATE + '1 year'::interval), 'YY'::text))
        END AS financial_year
   FROM (((kaverimrg.documentmaster b
     JOIN kaverimrg.propertymaster a ON (((a.documentid = b.documentid) AND (a.srocode = b.srocode))))
     JOIN kaverimrg.sromaster c ON ((b.srocode = c.srocode)))
     JOIN kaverimrg.booktypemaster d ON ((b.bookid = d.bookid)));


ALTER TABLE kaverimrg.vw_fetch_document_search_parameters OWNER TO postgres;

