--
-- Name: vw_fetch_ec; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_ec AS
 SELECT DISTINCT pi.partyid,
    pm.propertyid,
    dm.documentid,
    dm.srocode,
    dm.stamp5datetime AS executiondate,
    ra.articlenamee,
    pm.marketvalue,
    pm.consideration,
    string_agg(
        CASE
            WHEN (pi.partytypeid = 1) THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END, ', '::text) AS claimant,
    string_agg(
        CASE
            WHEN (pi.partytypeid = 2) THEN concat(pi.firstname, pi.middlename, pi.lastname)
            ELSE NULL::text
        END, ', '::text) AS executant,
    dm.cdnumber,
    dm.pagecount,
    dm.finalregistrationnumber AS documentreference,
    ps.description,
    pn.currentpropertytypeid,
    pn.currentnumber,
    pm.applicationnumber,
    pm.eastboundary AS east,
    pm.westboundary AS west,
    pm.northboundary AS north,
    pm.southboundary AS south,
    ps.easttowest,
    ps.northtosouth,
    pn.currentnumber AS aptno_new,
    pn.oldnumber AS oldno,
    pm.totalarea AS area,
    pm.villagecode,
    v.villagenamee,
    v.hoblicode,
    h.hoblinamee,
    pi.address,
    r.referencetext
   FROM ((((((((kaverimrg.propertymaster pm
     JOIN kaverimrg.documentmaster dm ON (((pm.regsrocode = dm.srocode) AND (pm.documentid = dm.documentid))))
     JOIN kaverimrg.propertyschedules ps ON (((ps.srocode = pm.regsrocode) AND (ps.propertyid = pm.propertyid))))
     JOIN kaverimrg.registrationarticles ra ON ((ra.regarticlecode = dm.regarticlecode)))
     JOIN kaverimrg.partyinfo pi ON (((pi.srocode = dm.srocode) AND (pi.documentid = dm.documentid))))
     JOIN kaverimrg.propertynumberdetails pn ON (((pn.propertyid = pm.propertyid) AND (pn.srocode = pm.regsrocode))))
     JOIN kaverimrg.villagemaster_bck_12062023 v ON ((v.villagecode = pm.villagecode)))
     JOIN kaverimrg.hoblimaster_bck_12062023 h ON ((h.hoblicode = v.hoblicode)))
     LEFT JOIN kaverimrg.referencemaster r ON ((r.documentid = dm.documentid)))
  GROUP BY pi.partyid, pm.propertyid, dm.documentid, dm.srocode, dm.stamp5datetime, ra.articlenamee, pm.marketvalue, pm.consideration, dm.cdnumber, dm.pagecount, dm.finalregistrationnumber, ps.description, pm.villagecode, pn.currentpropertytypeid, pn.currentnumber, pm.applicationnumber, pm.eastboundary, pm.westboundary, pm.northboundary, pm.southboundary, ps.easttowest, ps.northtosouth, pn.oldnumber, pm.totalarea, v.villagenamee, v.hoblicode, h.hoblinamee, pi.address, r.referencetext;


ALTER TABLE kaverimrg.vw_fetch_ec OWNER TO postgres;

