   FROM ((((((((((kaverimrg.partyinfo a
     JOIN kaverimrg.partytypemaster c ON ((a.partytypeid = c.partytypeid)))
     JOIN kaverimrg.sromaster b ON ((a.srocode = b.srocode)))
     LEFT JOIN kaverimrg.salutationmaster d ON ((a.salutationid = d.salutationid)))
     LEFT JOIN kaverimrg.districtmaster_bck_12062023 e ON ((a.districtcode = e.districtcode)))
     LEFT JOIN kaverimrg.talukmaster_bck_12062023 f ON ((a.talukcode = f.talukcode)))
     LEFT JOIN kaverimrg.hoblimaster_bck_12062023 g ON ((a.hoblicode = g.hoblicode)))
     LEFT JOIN kaverimrg.villagemaster_bck_12062023 h ON ((a.villagecode = h.villagecode)))
     LEFT JOIN kaverimrg.propertynumberdetails j ON ((a.propertyid = j.propertyid)))
     LEFT JOIN kaverimrg.mas_idprooftypes k ON ((a.idprooftypeid = k.idprooftypeid)))
     LEFT JOIN kaverimrg.applicantapplicationdetails ap ON ((((a.applicationnumber)::text = (ap.applicationnumber)::text) AND (a.srocode = ap.srocode))))
  WHERE (a.applicationnumber IS NOT NULL)
  ORDER BY a.partyid, a.propertyid;


