    a.thumbpath,
    a.totalextacre,
    a.totalextgunta,
    a.totalextfgunta,
    a.transactextacre,
    a.transactextgunta,
    a.transactextfgunta,
    a.volumename,
    a.hasgpa,
    a.isaua,
    a.importedpartyparentid,
    a.salutationid,
    ( SELECT s3.descriptione
           FROM kaverimrg.salutationmaster s3
          WHERE (s3.salutationid = a.salutationid)) AS descriptione,
    a.isorganization,
    a.organizationid,
    a.applicationnumber,
    a.verified,
    a.issroapproved,
    a.tanno,
    a.yearofincorp,
    a.orgpoaauthsignfname,
    a.orgpoaauthsignmname,
    a.orgpoaauthsignlname,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
    a.propertynumber,
    a.idprooftypeid,
    a.isconsentwitness,
    a.isprivateattendance,
    ( SELECT m2.description
           FROM kaverimrg.mas_idprooftypes m2
          WHERE (m2.idprooftypeid = a.idprooftypeid)) AS idprooftypename,
    a.coveringletterno,
    a.section88file,
    a.isduplicate,
    a.duplicatepartyid
   FROM (((kaverimrg.partyinfo a
     LEFT JOIN kaverimrg.lgd_districtmaster e ON ((a.districtcode = e.districtcode)))
     LEFT JOIN kaverimrg.lgd_statemaster s ON ((e.lgdstatecode = s.statecode)))
     LEFT JOIN ( SELECT propertynumberdetails.propertyid,
            row_number() OVER (PARTITION BY propertynumberdetails.propertyid) AS rnk
           FROM kaverimrg.propertynumberdetails) j ON (((j.rnk = 1) AND (a.propertyid = j.propertyid))))
  WHERE (((a.applicationnumber)::text ~ '^[0-9]+$'::text) = false);


