    f.presentertypeid,
    f.linkfirmpersonid
   FROM ((kaverimrg.firmparty f
     JOIN kaverimrg.firmmaster f2 ON (((f.applicationnumber)::text = (f2.applicationnumber)::text)))
     JOIN kaverimrg.firmprotestentry fa ON ((((f2.finalregistrationnumber)::text = (fa.finalregistrationnumber)::text) AND (f.presentertypeid = ANY (ARRAY[1, 6])) AND (f.age >= 18))));


ALTER TABLE kaverimrg.vw_fetch_getfirmpartyinfo OWNER TO postgres;

--
-- Name: vw_fetch_getfirmpartylistinfo; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_getfirmpartylistinfo AS
 SELECT DISTINCT f.firmpersonid,
    f.applicationnumber AS firmnumber,
    f.registrationid,
    f.salutation,
    f.firstname,
    f.middlename,
    f.lastname,
    f.relationship,
    f.relativename,
    f.dob,
    f.age,
    f.gender,
    f.occupation,
    f.phoneno,
    f.mailaddress,
    f.dateofjoin,
    f.datetime,
    f.prehousebuildname,
    f.prestreetname,
    f.prestatecode,
    f.predistrictcode,
    f.pretalukacode,
    f.precityvillagecode,
    f.prepincode,
    f.ispresentaddresssameaspermanent,
    f.perhousebuildname,
    f.permanentaddress,
    f.perstreetname,
    f.perstatecode,
    f.perdistrictcode,
    f.pertalukacode,
    f.perhoblicode,
    f.percityvillagecode,
    f.perpincode,
    fm.finalregistrationnumber,
    f.prehoblicode,
    f.presentertypeid,
    f.linkfirmpersonid,
    am.applicationnumber,
        CASE
            WHEN (f.firmpersonid = ap.firmpersonid) THEN ap.amendmentpersonid
            ELSE NULL::integer
        END AS amendmentpersonid,
    ap.amendmentid,
    (((((((((((((((f.perhousebuildname)::text || ' '::text) || (f.perstreetname)::text) || ' '::text) || (di.districtnamee)::text) || ' '::text) || (ta.taluknamee)::text) || ' '::text) || (ho.hoblinamee)::text) || ' '::text) || (vill.villagenamee)::text) || ' '::text) || (stat.statenamee)::text) || '-'::text) || f.perpincode) AS peraddress,
    ap.salutation AS amendsalutation,
    ap.firstname AS amendfirstname,
    ap.middlename AS amendmiddlename,
    ap.lastname AS amendlastname,
    ap.amendhousebuildingname,
    ap.amendstreetaddress,
    ap.amendstatecode,
    ap.amenddistrictcode,
    ap.amendtalukacode,
    ap.amendhoblicode,
    ap.amendcityvillagecode,
    ap.amendpincode
   FROM (((((((((((((kaverimrg.firmamendment am
     JOIN kaverimrg.firmmaster fm ON (((am.finalregistrationnumber)::text = (fm.finalregistrationnumber)::text)))
     LEFT JOIN kaverimrg.firmparty f ON (((fm.applicationnumber)::text = (f.applicationnumber)::text)))
     LEFT JOIN kaverimrg.amendmentfirmparty ap ON (((am.amendmentid = ap.amendmentid) AND (f.firmpersonid = ap.firmpersonid) AND (ap.presentertypeid = 6))))
     LEFT JOIN kaverimrg.districtmaster di ON ((f.perdistrictcode = di.districtcode)))
     LEFT JOIN kaverimrg.talukmaster ta ON ((f.pertalukacode = ta.talukcode)))
     LEFT JOIN kaverimrg.hoblimaster ho ON ((f.perhoblicode = ho.hoblicode)))
     LEFT JOIN kaverimrg.villagemaster vill ON ((f.percityvillagecode = vill.villagecode)))
     LEFT JOIN kaverimrg.statemaster stat ON ((f.perstatecode = stat.statecode)))
     LEFT JOIN kaverimrg.districtmaster dii ON ((ap.amenddistrictcode = dii.districtcode)))
     LEFT JOIN kaverimrg.talukmaster taa ON ((ap.amendtalukacode = taa.talukcode)))
     LEFT JOIN kaverimrg.hoblimaster hoo ON ((ap.amendhoblicode = hoo.hoblicode)))
     LEFT JOIN kaverimrg.villagemaster villa ON ((ap.amendcityvillagecode = villa.villagecode)))
     LEFT JOIN kaverimrg.statemaster stata ON ((ap.amendstatecode = stata.statecode)))
  WHERE ((f.presentertypeid <> 8) AND (f.presentertypeid <> 2));


ALTER TABLE kaverimrg.vw_fetch_getfirmpartylistinfo OWNER TO postgres;

