--
-- Name: vw_fetch_marriage_srooffice; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_marriage_srooffice AS
 SELECT DISTINCT a.applicationnumber,
    a.srocode,
    a.sronamee,
    a.drcode,
    a.drname,
    a.sro_option
   FROM ( SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'BrideGroom_SRO'::text AS sro_option
           FROM (((kaverimrg.persondetails pd
             JOIN kaverimrg.villagemaster v ON ((v.villagecode = pd.percityvillagecode)))
             JOIN kaverimrg.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaverimrg.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'M%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'BrideGroom_SRO_pre'::text AS sro_option
           FROM (((kaverimrg.persondetails pd
             JOIN kaverimrg.villagemaster v ON ((v.villagecode = pd.precityvillagecode)))
             JOIN kaverimrg.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaverimrg.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'M%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'Bride_SRO'::text AS sro_option
           FROM (((kaverimrg.persondetails pd
             JOIN kaverimrg.villagemaster v ON ((v.villagecode = pd.percityvillagecode)))
             JOIN kaverimrg.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaverimrg.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'F%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'Bride_SRO_pre'::text AS sro_option
           FROM (((kaverimrg.persondetails pd
             JOIN kaverimrg.villagemaster v ON ((v.villagecode = pd.precityvillagecode)))
             JOIN kaverimrg.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaverimrg.districtmaster d ON ((d.districtcode = sm.districtcode)))
          WHERE ((pd.sex)::text ~~ 'F%'::text)
        UNION ALL
         SELECT pd.applicationnumber,
            sm.srocode,
            sm.sronamee,
            sm.districtcode AS drcode,
            d.districtnamee AS drname,
            'Marriage_Place_SRO'::text AS sro_option
           FROM (((kaverimrg.marriageregistration pd
             JOIN kaverimrg.villagemaster v ON ((v.villagecode = pd.cityvillagecode)))
             JOIN kaverimrg.sromaster sm ON ((v.srocode = sm.srocode)))
             JOIN kaverimrg.districtmaster d ON ((d.districtcode = sm.districtcode)))) a;


ALTER TABLE kaverimrg.vw_fetch_marriage_srooffice OWNER TO postgres;

