-- Name: vw_fetch_module_submodule_info; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_module_submodule_info AS
 SELECT m.moduleid,
    s.submoduleid,
    f.functionid
   FROM ((kaverimrg.modulemaster m
     LEFT JOIN kaverimrg.submodulemaster s ON ((m.moduleid = s.moduleid)))
     LEFT JOIN kaverimrg.functionmaster f ON (((s.moduleid = f.moduleid) AND (s.submoduleid = f.submoduleid) AND (m.moduleid = f.moduleid))))
  ORDER BY m.moduleid, s.submoduleid, f.functionid;


ALTER TABLE kaverimrg.vw_fetch_module_submodule_info OWNER TO postgres;

--
-- Name: vw_fetch_movable_property; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_movable_property AS
 SELECT a.propertyid,
    a.documentid,
    a.stamparticlecode,
    e.articlenamee AS stamparticle,
    a.stampruleid,
    f.descriptione AS stampsubarticalcode,
    d.bookid,
    c.booknameenglish AS booknumber,
    a.regarticlecode,
    d.articlenamee AS registrationfeearticle,
    a.movablepropertydesc AS propertywithdescription,
    a.applicationnumber,
    f.sameasarticleid,
    f.parentrefid,
    f.haschild,
    f.isslabs,
    f.unitisamount,
    f.unitdescriptione,
    f.unit,
    f.value,
    f.minlimit,
    f.maxlimit,
    f.multipliedby,
    f.sdcalcon,
    f.isinpercentage,
    f.isfixduty,
    f.isexempted,
    f.isruleactive,
    f.regvalue,
    f.regispercent,
    f.regmaxlimit,
    f.regminlimit,
    f.regcalconconsideration,
    f.othercalcrule,
    f.othercalcon,
    f.isaddonvalue,
    f.addoncaptione,
    f.activefrom,
    f.activeto,
    f.issurcharge,
    f.urbanvalue,
    f.ruralvalue,
    f.issurchargepercentage,
    f.iscess,
    f.cessvalue,
    f.iscesspercentage
   FROM ((((kaverimrg.propertymaster a
     JOIN kaverimrg.registrationarticles d ON ((d.regarticlecode = a.regarticlecode)))
     JOIN kaverimrg.booktypemaster c ON ((c.bookid = d.bookid)))
     JOIN kaverimrg.stamparticles e ON ((e.stamparticlecode = a.stamparticlecode)))
     JOIN kaverimrg.stamprules f ON (((f.stampruleid = a.stampruleid) AND (a.ismovableproperty = true))));


ALTER TABLE kaverimrg.vw_fetch_movable_property OWNER TO postgres;

--
-- Name: vw_fetch_new_property_no_search_parameters; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_new_property_no_search_parameters AS
 SELECT a.srocode,
    a.orderid,
    a.ordernumber AS drordernumber,
    a.orderdate,
    b.documentid,
    b.villagecode,
    v.villagenamee,
    b.propertyid,
    p.currentpropertytypeid,
    c.typenameenglish AS currentpropertytype,
    p.currentnumber,
    p.oldpropertytypeid,
    f.typenameenglish AS oldpropertytype,
    p.oldnumber,
    p.survey_no,
    p.surnoc,
    p.hissa_no,
    d.note_preparedpart AS ordernote
   FROM ((((((kaverimrg.dec_drordermaster a
     JOIN kaverimrg.propertymaster b ON ((a.documentid = b.documentid)))
     JOIN kaverimrg.propertynumberdetails p ON ((b.propertyid = p.propertyid)))
     LEFT JOIN kaverimrg.propertynotypemaster c ON ((p.currentpropertytypeid = c.propertytypeid)))
     LEFT JOIN kaverimrg.propertynotypemaster f ON ((p.oldpropertytypeid = f.propertytypeid)))
     JOIN kaverimrg.dec_drpndnote d ON ((a.orderid = d.orderid)))
     LEFT JOIN kaverimrg.villagemaster_bck_12062023 v ON ((b.villagecode = v.villagecode)));


ALTER TABLE kaverimrg.vw_fetch_new_property_no_search_parameters OWNER TO postgres;

