     LEFT JOIN kaverimrg.partytypemaster au_type ON ((au.partytypeid = au_type.partytypeid)))
     LEFT JOIN kaverimrg.partytypemaster poa_type ON ((poa.partytypeid = poa_type.partytypeid)))
     LEFT JOIN kaverimrg.salutationmaster e ON ((a.salutationid = e.salutationid)))
     LEFT JOIN kaverimrg.salutationmaster sal_au ON ((au.salutationid = sal_au.salutationid)))
     LEFT JOIN kaverimrg.salutationmaster sal_poa ON ((sal_poa.salutationid = poa.salutationid)))
     LEFT JOIN kaverimrg.mas_idprooftypes id ON ((id.idprooftypeid = a.idprooftypeid)))
     LEFT JOIN kaverimrg.mas_idprooftypes id_au ON ((id_au.idprooftypeid = au.idprooftypeid)))
     LEFT JOIN kaverimrg.mas_idprooftypes id_poa ON ((id_poa.idprooftypeid = poa.idprooftypeid)))
     LEFT JOIN kaverimrg.relationshipmasters r ON (((r.id)::text = (a.relationship)::text)))
     LEFT JOIN kaverimrg.relationshipmasters r_au ON (((r_au.id)::text = (au.relationship)::text)))
     LEFT JOIN kaverimrg.relationshipmasters r_poa ON (((r_poa.id)::text = (poa.relationship)::text)))
  WHERE (a.applicationnumber IS NOT NULL);


