--
-- Name: vw_fetch_party_witness; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_party_witness AS
 SELECT 0 AS partyid,
    ''::text AS partyname,
    b.name,
    b.middlename,
    b.lastname,
    b.age,
    b.address,
    b.sex,
    b.profession,
    b.witnessid,
    b.registrationid,
    b.dateofbirth,
    b.status,
    b.phoneno,
    b.relation,
    b.mothername,
    b.fathersname,
    b.srocode,
    b.applicationnumber,
    b.verified,
    b.issroapproved,
    b.statecode,
    b.districtcode,
    b.talukcode,
    b.hoblicode,
    b.villagecode,
    b.relativename,
    b.pincode,
    b.houseno,
    b.iscliment,
    b.isexicutent,
    ( SELECT array_to_json(array_agg(row_to_json(schd.*))) AS array_to_json
           FROM ( SELECT pi.partyid,
                    concat_ws(' '::text, pi.firstname, pi.middlename, pi.lastname) AS partyname,
                        CASE
                            WHEN (COALESCE(pwi.witnessid, (0)::bigint) = 0) THEN 'false'::text
                            ELSE 'true'::text
                        END AS ispartywitness
                   FROM (kaverimrg.partyinfo pi
                     JOIN kaverimrg.partywitness pwi ON (((pi.partyid = pwi.partyid) AND (pwi.witnessid = b.witnessid))))
                  WHERE ((pi.applicationnumber)::text = (b.applicationnumber)::text)) schd) AS partyidentifier
   FROM kaverimrg.witnessinfo b;


