    a.isaua,
    a.importedpartyparentid,
    a.salutationid,
    d.descriptione,
    a.isorganization,
    a.organizationid,
    a.applicationnumber,
    a.verified,
    a.issroapproved,
    a.tanno,
    a.yearofincorp,
    a.orgpoaauthsignfname,
    a.orgpoaauthsignmname,
    a.orgpoaauthsignlname,
    a.linkpartyid,
    a.housenumber,
    a.pin,
    a.propertyid,
    a.propertynumber,
    a.idprooftypeid,
    k.description AS idprooftypename
   FROM (((((((((kaverimrg.partyinfo a
     JOIN kaverimrg.sromaster b ON ((a.srocode = b.srocode)))
     JOIN kaverimrg.partytypemaster c ON ((a.partytypeid = c.partytypeid)))
     LEFT JOIN kaverimrg.salutationmaster d ON ((a.salutationid = d.salutationid)))
     LEFT JOIN kaverimrg.lgd_districtmaster e ON ((a.districtcode = e.districtcode)))
     LEFT JOIN kaverimrg.lgd_talukmaster f ON (((f.lgd_districtcode = e.districtcode) AND (a.talukcode = f.talukcode))))
     LEFT JOIN kaverimrg.lgd_statemaster s ON ((e.lgdstatecode = s.statecode)))
     LEFT JOIN kaverimrg.partyinfo i ON ((a.partyid = i.partyid)))
     LEFT JOIN kaverimrg.partyinfo j ON ((a.partyid = j.linkpartyid)))
     LEFT JOIN kaverimrg.mas_idprooftypes k ON ((a.idprooftypeid = k.idprooftypeid)))
  WHERE ((COALESCE(a.ispresenter, false) = true) AND (a.applicationnumber IS NOT NULL))
  ORDER BY a.partyid;


