--
-- Name: vw_fetch_presenter_for_schedule; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_presenter_for_schedule AS
 SELECT p.partyid AS linkpartyid,
    p.partytypeid AS linked_partytypeid,
    p.firstname AS linked_firstname,
    a.partyid,
    a.partytypeid,
    a.firstname,
    p.isorganization,
        CASE
            WHEN (a.partytypeid = 4) THEN concat(p.firstname, ' is rep. by MG ', a.firstname)
            WHEN ((a.partytypeid = 5) AND (p.isorganization = true)) THEN concat(p.firstname, ' POA by ', a.firstname, ' is Rep. by ', a.orgpoaauthsignfname)
            WHEN ((a.partytypeid = 5) AND (p.isorganization = false)) THEN concat(a.firstname, ' is GPA of ', p.firstname)
            WHEN ((a.partytypeid = 9) AND (p.isorganization = true)) THEN concat(p.firstname, ' is Rep. by ', a.firstname)
            WHEN ((a.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN (p.firstname)::text
            WHEN ((a.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN (p.firstname)::text
            ELSE NULL::text
        END AS fullname,
    p.applicationnumber
   FROM (kaverimrg.partyinfo p
     LEFT JOIN kaverimrg.partyinfo a ON ((p.partyid = a.linkpartyid)))
  WHERE ((p.partytypeid = ANY (ARRAY[1, 2])) AND (p.isduplicate IS NOT TRUE));


ALTER TABLE kaverimrg.vw_fetch_presenter_for_schedule OWNER TO postgres;

--
-- Name: vw_fetch_presenter_info; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_presenter_info AS
 SELECT p.partyid AS linkpartyid,
    p.partytypeid AS linked_partytypeid,
    p.firstname AS linked_firstname,
    p1.partyid,
    p1.partytypeid,
    p1.firstname,
    p.isorganization,
        CASE
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 4) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is rep. by minor guardian ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = true)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' POA by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname, ' is Rep. by ', p1.orgpoaauthsignfname, ' ', p1.orgpoaauthsignlname)
            WHEN ((p1.partytypeid = 5) AND (p.isorganization = false)) THEN concat(s1.descriptione, p1.firstname, ' is GPA of ', s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid = 9) AND (p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname, ' is Rep. by ', s1.descriptione, p1.firstname, ' ', p1.middlename, ' ', p1.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 1)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            WHEN ((p1.partytypeid IS NULL) AND (p.partytypeid = 2)) THEN concat(s.descriptione, p.firstname, ' ', p.middlename, ' ', p.lastname)
            ELSE NULL::text
        END AS fullname,
    p.applicationnumber,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.age
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.age
            WHEN ((p.age)::text < '18'::text) THEN p1.age
            ELSE p.age
        END AS age,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.sex
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.sex
            WHEN ((p.age)::text < '18'::text) THEN p1.sex
            ELSE p.sex
        END AS sex,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p1.housenumber IS NULL) THEN ''::text
                ELSE p1.housenumber
            END || ', '::text) || (p1.address)::text) || ', '::text) || kaverimrg.fn_fetch_address_village((p1.talukcode)::bigint)) || ' - '::text) || p1.pin))
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p2.housenumber IS NULL) THEN ''::text
                ELSE p2.housenumber
            END || ', '::text) || (p2.address)::text) || ', '::text) || kaverimrg.fn_fetch_address_village((p2.talukcode)::bigint)) || ' - '::text) || p2.pin))
            WHEN ((p.age)::text < '18'::text) THEN concat_ws(' '::text, ((((((
            CASE
                WHEN (p.housenumber IS NULL) THEN ''::text
                ELSE p.housenumber
            END || ', '::text) || (p.address)::text) || ', '::text) || kaverimrg.fn_fetch_address_village((p.talukcode)::bigint)) || ' - '::text) || p.pin))
            ELSE concat_ws(' '::text, ((((((
            CASE
                WHEN (p.housenumber IS NULL) THEN ''::text
                ELSE p.housenumber
            END || ', '::text) || (p.address)::text) || ', '::text) || kaverimrg.fn_fetch_address_village((p.talukcode)::bigint)) || ' - '::text) || p.pin))
        END AS address,
        CASE
            WHEN (p.idprooftypeid IS NOT NULL) THEN m1.description
            WHEN (p1.idprooftypeid IS NOT NULL) THEN m2.description
            WHEN (p2.idprooftypeid IS NOT NULL) THEN m3.description
            WHEN (p.partyid IS NOT NULL) THEN m1.description
            WHEN (p1.partyid IS NOT NULL) THEN m2.description
            WHEN (p2.partyid IS NOT NULL) THEN m3.description
            ELSE NULL::character varying
        END AS descr,
        CASE
            WHEN ((p.isorganization = true) AND (p.firstname IS NULL)) THEN p.pan
            WHEN ((p.isorganization = true) AND (p.firstname IS NOT NULL)) THEN p.pan
            WHEN (((p.age)::text < '18'::text) AND (p.pan IS NULL)) THEN p1.pan
            WHEN (((p.age)::text < '18'::text) AND (p1.pan IS NULL)) THEN p2.pan
            ELSE p.pan
        END AS pan,
        CASE
            WHEN ((p.isorganization = true) AND (p2.firstname IS NULL)) THEN p1.profession
            WHEN ((p.isorganization = true) AND (p2.firstname IS NOT NULL)) THEN p2.profession
            WHEN ((p.age)::text < '18'::text) THEN p1.profession
            ELSE p.profession
        END AS profession,
    p.isexecutor,
    p.ispresenter
   FROM ((((((((kaverimrg.partyinfo p
     LEFT JOIN kaverimrg.partyinfo p1 ON ((p.partyid = p1.linkpartyid)))
     LEFT JOIN kaverimrg.partyinfo p2 ON ((p1.linkpartyid = p2.partyid)))
     LEFT JOIN kaverimrg.salutationmaster s ON ((p.salutationid = s.salutationid)))
     LEFT JOIN kaverimrg.salutationmaster s1 ON ((p1.salutationid = s1.salutationid)))
     LEFT JOIN kaverimrg.salutationmaster s2 ON ((p2.salutationid = s2.salutationid)))
     LEFT JOIN kaverimrg.mas_idprooftypes m1 ON ((p.idprooftypeid = m1.idprooftypeid)))
     LEFT JOIN kaverimrg.mas_idprooftypes m2 ON ((p1.idprooftypeid = m2.idprooftypeid)))
     LEFT JOIN kaverimrg.mas_idprooftypes m3 ON ((p2.idprooftypeid = m3.idprooftypeid)))
  WHERE ((p.partytypeid = ANY (ARRAY[1, 2])) AND ((p.section88exemption IS NULL) OR (p.section88exemption = false)) AND (p.isprivateattendance = false));


ALTER TABLE kaverimrg.vw_fetch_presenter_info OWNER TO postgres;

