            f_1.iscess,
            f_1.cessvalue,
            f_1.iscesspercentage,
            a.propertytypeid,
            a.noofscanpages,
            a.roadcode,
            r.roadnamee,
            f_1.isparttransactallowed,
            a.ownedarea,
            a.sfdastamparticlecode,
            a.sfdastampruleid,
            a.sfdanoofscanpages,
            a.sfdamarketvalue,
            a.srostamparticlecode,
            a.srostampruleid,
            a.sronoofscanpages,
            a.sromarketvalue,
            a.denodescription,
            a.estampdescription,
            a.adjudescription,
            a.sroconsideration,
            a.sfdaconsideration,
            a.isbefore2004,
            a.sfdastampduty,
            a.srostampduty,
            a.sfdacessduty,
            a.srocessduty,
            a.sfdasurcharge,
            a.srosurcharge,
            a.surcharge,
            a.valuationtypeid
           FROM ((((((((((((((kaverimrg.propertymaster a
             LEFT JOIN kaverimrg.sromaster c ON ((a.srocode = c.srocode)))
             LEFT JOIN kaverimrg.stamparticles b ON ((a.stamparticlecode = b.stamparticlecode)))
             LEFT JOIN LATERAL ( SELECT pn.propertyid,
                    pn.srocode,
                    pn.currentpropertytypeid,
                    pn.currentnumber,
                    pn.oldpropertytypeid,
                    pn.oldnumber,
                    pn.description,
                    pn.survey_no,
                    pn.surnoc,
                    pn.hissa_no
                   FROM kaverimrg.propertynumberdetails pn
                  WHERE (pn.propertyid = a.propertyid)
                 LIMIT 1) l ON ((a.propertyid = l.propertyid)))
             LEFT JOIN ( SELECT pn2.currentpropertytypeid,
                    pn2.propertyid
                   FROM kaverimrg.propertynumberdetails pn2
                  WHERE (pn2.currentpropertytypeid = ANY (ARRAY[65, 60]))) pnn ON ((a.propertyid = pnn.propertyid)))
             LEFT JOIN kaverimrg.propertynotypemaster pt ON ((pt.propertytypeid = l.currentpropertytypeid)))
             LEFT JOIN kaverimrg.propertytypemaster py ON ((a.propertytypeid = py.propertytypeid)))
             LEFT JOIN kaverimrg.villagemaster_bck_12062023 d ON ((a.villagecode = d.villagecode)))
             LEFT JOIN kaverimrg.sromaster ss ON ((d.srocode = ss.srocode)))
             LEFT JOIN kaverimrg.measunitmaster e_1 ON ((a.unitid = e_1.unitid)))
             LEFT JOIN kaverimrg.stamprules f_1 ON ((a.stampruleid = f_1.stampruleid)))
             LEFT JOIN kaverimrg.talukmaster_bck_12062023 i ON ((i.talukcode = d.talukcode)))
             LEFT JOIN kaverimrg.districtmaster_bck_12062023 g ON ((ss.districtcode = g.districtcode)))
             LEFT JOIN kaverimrg.hoblimaster_bck_12062023 h ON ((d.hoblicode = h.hoblicode)))
             LEFT JOIN kaverimrg.roadmaster r ON ((a.roadcode = r.roadcode)))
          WHERE ((a.ismovableproperty = false) AND (py.isagri = false))) e,
    ( SELECT
                CASE
                    WHEN (( SELECT sum(1) AS count1
                       FROM kaverimrg.mojanixml m
                      WHERE (m.propertyid = a.propertyid)) >= 1) THEN true
                    ELSE false
                END AS isesketchused,
            a.sroroadcode,
            ( SELECT DISTINCT r1.roadnamee
                   FROM kaverimrg.roadmaster r1
                  WHERE (r1.roadcode = a.sroroadcode)) AS sroroadnamee,
            a.sfdaroadcode,
            ( SELECT DISTINCT r2.roadnamee
                   FROM kaverimrg.roadmaster r2
                  WHERE (r2.roadcode = a.sfdaroadcode)) AS sfdaroadnamee,
            i.unit AS unittype,
                CASE
                    WHEN (pnn.currentpropertytypeid = 65) THEN true
                    ELSE false
                END AS easthiproperty,
                CASE
                    WHEN (pnn.currentpropertytypeid = 60) THEN true
                    ELSE false
                END AS eswathuproperty,
                CASE
                    WHEN (pnn.currentpropertytypeid = 1) THEN true
                    ELSE false
                END AS isbhoomiproperty
           FROM ((((((((((((((kaverimrg.propertymaster a
             LEFT JOIN kaverimrg.sromaster c ON ((a.srocode = c.srocode)))
             LEFT JOIN kaverimrg.stamparticles b ON ((a.stamparticlecode = b.stamparticlecode)))
             LEFT JOIN LATERAL ( SELECT pn.propertyid,
                    pn.srocode,
                    pn.currentpropertytypeid,
                    pn.currentnumber,
                    pn.oldpropertytypeid,
                    pn.oldnumber,
                    pn.description,
                    pn.survey_no,
                    pn.surnoc,
                    pn.hissa_no
                   FROM kaverimrg.propertynumberdetails pn
                  WHERE (pn.propertyid = a.propertyid)
                 LIMIT 1) l ON ((a.propertyid = l.propertyid)))
             LEFT JOIN ( SELECT pn2.currentpropertytypeid,
                    pn2.propertyid
                   FROM kaverimrg.propertynumberdetails pn2
                  WHERE (pn2.currentpropertytypeid = ANY (ARRAY[65, 60]))) pnn ON ((a.propertyid = pnn.propertyid)))
             LEFT JOIN kaverimrg.propertynotypemaster pt ON ((pt.propertytypeid = l.currentpropertytypeid)))
             LEFT JOIN kaverimrg.propertytypemaster py ON ((a.propertytypeid = py.propertytypeid)))
             LEFT JOIN kaverimrg.villagemaster_bck_12062023 d ON ((a.villagecode = d.villagecode)))
             LEFT JOIN kaverimrg.sromaster ss ON ((d.srocode = ss.srocode)))
             LEFT JOIN kaverimrg.measunitmaster e_1 ON ((a.unitid = e_1.unitid)))
             LEFT JOIN kaverimrg.stamprules f_1 ON ((a.stampruleid = f_1.stampruleid)))
             LEFT JOIN kaverimrg.talukmaster_bck_12062023 i ON ((i.talukcode = d.talukcode)))
             LEFT JOIN kaverimrg.districtmaster_bck_12062023 g ON ((ss.districtcode = g.districtcode)))
             LEFT JOIN kaverimrg.hoblimaster_bck_12062023 h ON ((d.hoblicode = h.hoblicode)))
             LEFT JOIN kaverimrg.roadmaster r ON ((a.roadcode = r.roadcode)))
          WHERE ((a.ismovableproperty = false) AND (py.isagri = false))) f
  ORDER BY 1;


