--
-- Name: vw_fetch_property_schedules; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_property_schedules AS
 SELECT a.scheduleid,
    a.propertyid,
    b.srocode,
    c.sronamee,
    b.villagecode,
    g.villagenamee,
    a.partyid,
    a.scheduletype,
    a.totalarea,
    a.unitid,
    f.descriptionenglish,
    a.description,
    a.partyids,
    a.aileniatedauthorityid,
    a.alieniatedorder,
    a.bhoomisellerpartyids,
    a.govtrestricorder,
    a.govtrestrictionid,
    a.landcode,
    a.propertygroup,
    a.giftshare,
    a.giftsharedetails,
    a.easttowest,
    a.northtosouth,
    a.northboundary,
    a.southboundary,
    a.eastboundary,
    a.westboundary,
    a.blockchainpropertyid,
    a.assignedblockchainpid,
    a.applicationnumber,
    a.verified,
    b.issroapproved,
    b.propertytypeid,
    b.ismovableproperty,
    ( SELECT p.transactextacre
           FROM kaverimrg.partyinfo p
          WHERE ((p.propertyid = b.propertyid) AND (p.partytypeid =
                CASE
                    WHEN (sf.isownertobeclaimant = true) THEN 1
                    ELSE 2
                END))
         LIMIT 1) AS transactextacre,
    ( SELECT p.transactextgunta
           FROM kaverimrg.partyinfo p
          WHERE ((p.propertyid = b.propertyid) AND (p.partytypeid =
                CASE
                    WHEN (sf.isownertobeclaimant = true) THEN 1
                    ELSE 2
                END))
         LIMIT 1) AS transactextgunta,
    ( SELECT p.transactextfgunta
           FROM kaverimrg.partyinfo p
          WHERE ((p.propertyid = b.propertyid) AND (p.partytypeid =
                CASE
                    WHEN (sf.isownertobeclaimant = true) THEN 1
                    ELSE 2
                END))
         LIMIT 1) AS transactextfgunta
   FROM (((((kaverimrg.propertyschedules a
     JOIN kaverimrg.propertymaster b ON ((a.propertyid = b.propertyid)))
     JOIN kaverimrg.sromaster c ON ((b.regsrocode = c.srocode)))
     JOIN kaverimrg.measunitmaster f ON ((a.unitid = f.unitid)))
     JOIN kaverimrg.villagemaster g ON ((b.villagecode = g.villagecode)))
     LEFT JOIN kaverimrg.stamprulesflag sf ON ((sf.stampruleid = b.stampruleid)))
  WHERE (a.propertyid = b.propertyid)
  ORDER BY a.scheduleid;


ALTER TABLE kaverimrg.vw_fetch_property_schedules OWNER TO postgres;

--
-- Name: vw_fetch_reuploadjslip; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_reuploadjslip AS
 SELECT sub.documentid,
    sub.srocode,
    sub.bookid,
    sub.regarticlecode,
    sub.applicationnumber,
    sub.finalregistrationnumber,
    sub.registrationdatetime,
    sub.acknowledgeno,
    sub.remarks,
    sub.jslipsuccess,
    sub.createddate AS uploaddate
   FROM ( SELECT DISTINCT dm.documentid,
            dm.srocode,
            dm.bookid,
            dm.regarticlecode,
            dm.applicationnumber,
            dm.finalregistrationnumber,
            dm.registrationdatetime,
            COALESCE(bf.acknowledgeno, '0'::character varying(8000)) AS acknowledgeno,
            bf.remarks,
            bf.createddate,
                CASE
                    WHEN ((bf.remarks)::text = ANY (ARRAY[('Already Saved'::character varying)::text, ('Saved'::character varying)::text])) THEN true
                    ELSE false
                END AS jslipsuccess,
            dense_rank() OVER (PARTITION BY bf.finalregistrationnumber ORDER BY bf.acknowledgeno DESC NULLS LAST, bf.createddate DESC NULLS LAST) AS rank1
           FROM (((kaverimrg.documentmaster dm
             LEFT JOIN kaverimrg.bhoomifileuploaddetails bf ON (((dm.finalregistrationnumber)::text = (bf.finalregistrationnumber)::text)))
             LEFT JOIN kaverimrg.propertymaster pm ON ((dm.documentid = pm.documentid)))
             LEFT JOIN kaverimrg.stamprulesflag s ON ((pm.stampruleid = s.stampruleid)))
          WHERE ((dm.isregistrationcompleted = true) AND (pm.propertytypeid = 17) AND (s.isjslipagri IS TRUE))) sub
  WHERE (sub.rank1 = 1);


ALTER TABLE kaverimrg.vw_fetch_reuploadjslip OWNER TO postgres;

