   FROM ((((kaverimrg.roadmaster rm
     JOIN kaverimrg.villagemaster_bck_12062023 v ON ((rm.villagecode = v.villagecode)))
     JOIN kaverimrg.hoblimaster_bck_12062023 h ON ((v.hoblicode = h.hoblicode)))
     JOIN kaverimrg.talukmaster_bck_12062023 t ON ((v.talukcode = t.talukcode)))
     JOIN kaverimrg.districtmaster_bck_12062023 d ON ((t.districtcode = d.districtcode)));


