--
-- Name: vw_fetch_section68_property_return_string; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_section68_property_return_string AS
 SELECT tab1.propertyid,
    (tab1.col1 || tab2.col1) AS propertydescription,
    tab3.col1 AS footnotefordesc
   FROM ( SELECT a.propertyid,
            (((((((((((((((((((('(Village)'::text || (COALESCE(b.villagenamee, ''::character varying))::text) || ', '::text) || COALESCE(tab3_1.typenameenglish, ''::text)) || '. '::text) || COALESCE(tab3_1.currentnumber, ''::text)) || ', '::text) || (COALESCE(c.hoblinamee, ''::character varying))::text) || ', '::text) || (COALESCE(d.taluknamee, ''::character varying))::text) || ', '::text) || (COALESCE(e.districtnamee, ''::character varying))::text) || ',(North)'::text) || (COALESCE(a.northboundary, ''::character varying))::text) || ',(South)'::text) || (COALESCE(a.southboundary, ''::character varying))::text) || ',(East)'::text) || (COALESCE(a.eastboundary, ''::character varying))::text) || ',(West)'::text) || (COALESCE(a.westboundary, ''::character varying))::text) || ', '::text) AS col1
           FROM (((((kaverimrg.propertymaster a
             JOIN kaverimrg.villagemaster_bck_12062023 b ON ((a.villagecode = b.villagecode)))
             JOIN kaverimrg.hoblimaster_bck_12062023 c ON ((b.hoblicode = c.hoblicode)))
             JOIN kaverimrg.talukmaster_bck_12062023 d ON ((c.talukcode = d.talukcode)))
             JOIN kaverimrg.districtmaster_bck_12062023 e ON ((d.districtcode = e.districtcode)))
             JOIN ( SELECT g.propertyid,
                    array_to_string(array_agg(h.typenameenglish), ','::text) AS typenameenglish,
                    array_to_string(array_agg(g.currentnumber), ','::text) AS currentnumber
                   FROM (kaverimrg.propertynotypemaster h
                     JOIN kaverimrg.propertynumberdetails g ON ((h.propertytypeid = g.currentpropertytypeid)))
                  GROUP BY g.propertyid) tab3_1 ON ((a.propertyid = tab3_1.propertyid)))) tab1,
    ( SELECT f.propertyid,
            ('Private Property Note :'::text || array_to_string(array_agg(((('(Schedule '::text || (COALESCE(f.scheduletype, ((''::character varying)::text)::character varying))::text) || ') '::text) || (COALESCE(f.description, ''::character varying))::text)), ','::text)) AS col1
           FROM kaverimrg.propertyschedules f
          GROUP BY f.propertyid) tab2,
    ( SELECT pm.propertyid,
            ((((('as per the order number '::text || (o.ordernumber)::text) || ' dated '::text) || to_char(o.orderdate, 'dd-mm-yyyy'::text)) || ' by District Registrar '::text) || (d.districtnamee)::text) AS col1
           FROM (((kaverimrg.propertymaster pm
             LEFT JOIN kaverimrg.documentmaster dm ON ((pm.documentid = dm.documentid)))
             LEFT JOIN kaverimrg.dec_drordermaster o ON ((dm.documentid = o.documentid)))
             LEFT JOIN kaverimrg.districtmaster_bck_12062023 d ON ((o.districtcode = d.districtcode)))) tab3
  WHERE ((tab1.propertyid = tab2.propertyid) AND (tab3.propertyid = tab1.propertyid));


ALTER TABLE kaverimrg.vw_fetch_section68_property_return_string OWNER TO postgres;

