    c.partytypeid,
    c.descriptioninenglish AS partytype,
    d.partyid,
    d.firstname,
    d.middlename,
    d.lastname,
    e.note_preparedpart AS ordernote
   FROM ((((kaverimrg.dec_drordermaster a
     JOIN kaverimrg.documentmaster b ON ((a.documentid = b.documentid)))
     JOIN kaverimrg.partyinfo d ON ((((b.applicationnumber)::text = (d.applicationnumber)::text) AND (d.partytypeid = ANY (ARRAY[1, 2])))))
     JOIN kaverimrg.partytypemaster c ON ((d.partytypeid = c.partytypeid)))
     JOIN kaverimrg.dec_drpndnote e ON ((a.orderid = e.orderid)));


