--
-- Name: vw_fetch_sr_correction_requests; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_sr_correction_requests AS
 SELECT a.orderid,
    a.districtcode,
    a.srocode,
    b.sronamee,
    b.sronamee AS orderrequestedbysr,
    a.documentid,
    c.finalregistrationnumber AS registrationno,
    a.orderdate AS requestdate,
    d1.note AS "Note",
    a.relativepath AS deedattachpath,
        CASE
            WHEN (a.statuscode = 0) THEN 'Pending'::text
            WHEN (a.statuscode = 1) THEN 'Drorder'::text
            WHEN (a.statuscode = 2) THEN 'Deorescan'::text
            WHEN (a.statuscode = 3) THEN 'Rescandone'::text
            WHEN (a.statuscode = 4) THEN 'Finalized'::text
            ELSE 'Finalized'::text
        END AS status
   FROM ((((kaverimrg.dec_drordermaster a
     JOIN kaverimrg.sromaster b ON ((a.srocode = b.srocode)))
     LEFT JOIN kaverimrg.documentmaster c ON ((a.documentid = c.documentid)))
     JOIN ( SELECT d.orderid,
            array_to_string(array_agg(d.note_enteredpart), ', '::text) AS note
           FROM kaverimrg.dec_drpndnote d
          GROUP BY d.orderid) d1 ON ((a.orderid = d1.orderid)))
     LEFT JOIN kaverimrg.ecpropertysearchkeyvalues e ON ((a.orderid = e.orderid)))
  ORDER BY a.orderid DESC;


ALTER TABLE kaverimrg.vw_fetch_sr_correction_requests OWNER TO postgres;

