--
-- Name: vw_fetch_witness; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_fetch_witness AS
 SELECT (0)::bigint AS partyid,
    pw.partyname,
    a.witnessid,
    (((((a.name)::text || ' '::text) || a.middlename) || ' '::text) || a.lastname) AS witnessname,
    3 AS partytypeid,
    'Consenting Witness'::text AS partytypename,
    a.applicationnumber,
    a.name,
    a.sex,
    a.age,
    a.relation,
    ( SELECT rel.relatione
           FROM kaverimrg.relationshipmasters rel
          WHERE ((rel.id)::text = (a.relation)::text)) AS relationtype,
    a.relativename,
    a.profession,
    a.districtcode,
    a.talukcode,
    0 AS hoblicode,
    0 AS villagecode,
    ((((((a.address)::text || ', '::text) || ((g.taluknamee)::text || ', '::text)) || ((d.districtnamee)::text || ', '::text)) || ((s.statenamee)::text || ' '::text)) || ' '::text) AS address,
    a.pincode,
    a.houseno
   FROM ((((kaverimrg.witnessinfo a
     LEFT JOIN ( SELECT b.witnessid,
            pi.applicationnumber,
            string_agg(concat_ws(' '::text, pi.firstname, pi.middlename, pi.lastname), ','::text ORDER BY pi.partyid) AS partyname
           FROM (kaverimrg.partywitness b
             LEFT JOIN kaverimrg.partyinfo pi ON ((pi.partyid = b.partyid)))
          GROUP BY b.witnessid, pi.applicationnumber) pw ON (((a.witnessid = pw.witnessid) AND ((pw.applicationnumber)::text = (a.applicationnumber)::text))))
     JOIN kaverimrg.lgd_districtmaster d ON ((d.districtcode = a.districtcode)))
     JOIN kaverimrg.lgd_statemaster s ON ((d.lgdstatecode = s.statecode)))
     JOIN kaverimrg.lgd_talukmaster g ON ((g.talukcode = a.talukcode)));


ALTER TABLE kaverimrg.vw_fetch_witness OWNER TO postgres;

