--
-- Name: vw_jslip_applicationdata; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_jslip_applicationdata AS
 SELECT DISTINCT dm.documentid,
    dm.applicationnumber,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    dm.srocode,
    (dm.registrationdatetime)::date AS registrationdate,
    dm.regarticlecode,
    dmref.regarticlecode AS previousarticlecode,
    dmref.finalregistrationnumber AS previousfinalregistrationnumber,
    (dmref.registrationdatetime)::date AS previousregistrationdate,
    pm.jslipnumber,
    pm.villagecode,
    NULL::text AS correctedcolumncodes,
        CASE
            WHEN (frts.applicationnumber IS NOT NULL) THEN dm.considerationamount
            ELSE ( SELECT sum(pmm.consideration) AS sum
               FROM kaverimrg.propertymaster pmm
              WHERE ((pmm.applicationnumber)::text = (dm.applicationnumber)::text))
        END AS cost,
    fr1.receiptid AS receiptnumber
   FROM ((((kaverimrg.documentmaster dm
     JOIN ( SELECT propertymaster.applicationnumber,
            propertymaster.documentid,
            propertymaster.villagecode,
            dense_rank() OVER (PARTITION BY propertymaster.documentid ORDER BY propertymaster.villagecode) AS jslipnumber
           FROM kaverimrg.propertymaster
          WHERE (propertymaster.propertytypeid = 17)) pm ON (((pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN ( SELECT fr.documentid,
            fr.srocode,
            array_to_string(array_agg(DISTINCT fr.receiptid), ', '::text) AS receiptid
           FROM kaverimrg.feesrequired fr
          WHERE (fr.receiptid IS NOT NULL)
          GROUP BY fr.documentid, fr.srocode) fr1 ON (((fr1.documentid = dm.documentid) AND (fr1.srocode = dm.srocode) AND (fr1.receiptid IS NOT NULL))))
     LEFT JOIN kaverimrg.documentmaster dmref ON ((dmref.documentid = dm.correctionreference)))
     LEFT JOIN kaverimrg.fruits_data_recv_details frts ON (((frts.applicationnumber)::text = (dm.applicationnumber)::text)));


ALTER TABLE kaverimrg.vw_jslip_applicationdata OWNER TO postgres;

--
-- Name: vw_jslip_applicationdetails; Type: VIEW; Schema: kaverimrg; Owner: postgres
