    p.currentnumber,
    pm.villagecode,
    v2.villagenamee,
    pm.sdcalculationstring,
    dm.finalregistrationnumber,
    pm.totalarea,
    pm.northboundary,
    pm.southboundary,
    pm.eastboundary,
    pm.westboundary,
    flt.floorid,
    lg.xml
   FROM ((((((((kaverimrg.propertymaster pm
     JOIN kaverimrg.documentmaster dm ON (((dm.documentid = pm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaverimrg.valuationdetails v ON ((v.propertyid = pm.propertyid)))
     LEFT JOIN kaverimrg.val_flatratedetails flt ON ((flt.valuationid = v.valid)))
     LEFT JOIN kaverimrg.eaasti_eswatuxmllog lg ON ((pm.propertyid = lg.propertyid)))
     JOIN kaverimrg.sromaster sm ON ((dm.srocode = sm.srocode)))
     JOIN kaverimrg.districtmaster d ON ((d.districtcode = sm.districtcode)))
     LEFT JOIN kaverimrg.villagemaster v2 ON (((dm.srocode = v2.srocode) AND (pm.villagecode = v2.villagecode))))
     JOIN kaverimrg.propertynumberdetails p ON ((pm.propertyid = p.propertyid)))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (p.currentpropertytypeid = 60));


ALTER TABLE kaverimrg.vw_jslip_easthi_finalproperty OWNER TO postgres;

--
-- Name: vw_jslip_surveynumberdata; Type: VIEW; Schema: kaverimrg; Owner: postgres
