CREATE VIEW kaverimrg.vw_jslip_surveynumberdetails AS
 SELECT dm.documentid,
    dm.applicationnumber,
    pm.propertyid,
    dm.finalregistrationnumber,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    v.kaverimrgvillagecode,
