    NULL::text AS govtrestrictionorder,
    ( SELECT DISTINCT p.landcode
           FROM kaverimrg.partyinfo p
          WHERE (p.propertyid = pm.propertyid)) AS landcode
   FROM (((((((kaverimrg.documentmaster dm
     LEFT JOIN kaverimrg.propertymaster pm ON (((pm.propertytypeid = 17) AND (pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     LEFT JOIN kaverimrg.propertynumberdetails pnd ON ((pm.propertyid = pnd.propertyid)))
     JOIN kaverimrg.bhoomimappingdetails_bck_12062023 v ON ((v.kaverimrgvillagecode = pm.villagecode)))
     JOIN kaverimrg.bhoomidistrictmaster bdm ON ((v.bhoomidistrictcode = bdm.districtcode)))
     JOIN kaverimrg.bhoomitalukmaster btm ON (((v.bhoomitalukcode = btm.talukcode) AND (v.bhoomidistrictcode = btm.districtcode))))
     JOIN kaverimrg.bhoomihoblimaster bhm ON (((v.bhoomihobicode = bhm.hoblicode) AND (v.bhoomitalukcode = bhm.talukcode) AND (v.bhoomidistrictcode = bhm.districtcode))))
     JOIN kaverimrg.bhoomivillagemaster bhv ON (((v.bhoomivillagecode = bhv.villagecode) AND (v.bhoomihobicode = bhv.hoblicode) AND (v.bhoomitalukcode = bhv.talukcode) AND (v.bhoomidistrictcode = bhv.districtcode))))
