--
-- Name: vw_jslip_surveynumberdetails_for_old_method; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_jslip_surveynumberdetails_for_old_method AS
 SELECT dm.documentid,
    dm.applicationnumber,
    pm.propertyid,
    dm.finalregistrationnumber,
    rga.articlenamee,
        CASE
            WHEN (((btm.unit)::text = 'G'::text) AND (pm.unitid = 1)) THEN (pm.totalarea * (40)::numeric)
            WHEN (((btm.unit)::text = 'C'::text) AND (pm.unitid = 1)) THEN (pm.totalarea * (100)::numeric)
            WHEN (((btm.unit)::text = 'G'::text) AND (pm.unitid = 2)) THEN (pm.totalarea * (40)::numeric)
            WHEN (((btm.unit)::text = 'C'::text) AND (pm.unitid = 6)) THEN (pm.totalarea * (100)::numeric)
            ELSE pm.totalarea
        END AS totalarea,
    btm.unit,
    mm.measurementnamee,
    (dm.documentid || to_char(dm.registrationdatetime, 'ddMMYYYY'::text)) AS regid,
    v.kaverimrgvillagecode,
    v.bhoomivillagecode AS villagecode,
    pnd.survey_no,
    pnd.hissa_no,
    pnd.currentnumber,
    bhv.villagenamee AS village,
    v.bhoomihobicode AS hoblicode,
    bhm.hoblinamee AS hobli,
    btm.talukcode,
    btm.taluknamee AS taluk,
    v.bhoomidistrictcode AS districtcode,
    bdm.districtnamee AS district,
    NULL::text AS govtrestrictioncleared,
    NULL::text AS govtrestrictionid,
    NULL::text AS govtrestrictionorder,
    sf.isownertobeclaimant
   FROM (((((((((((kaverimrg.documentmaster dm
     JOIN kaverimrg.propertymaster pm ON (((pm.propertytypeid = 17) AND (pm.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (pm.applicationnumber)::text))))
     JOIN kaverimrg.propertynumberdetails pnd ON ((pm.propertyid = pnd.propertyid)))
     LEFT JOIN kaverimrg.stamprules stm ON ((pm.stampruleid = stm.stampruleid)))
     JOIN kaverimrg.stamprulesflag sf ON ((stm.stampruleid = sf.stampruleid)))
     JOIN kaverimrg.registrationarticles rga ON ((rga.regarticlecode = pm.regarticlecode)))
     JOIN kaverimrg.measurementmaster mm ON ((mm.measurementcode = pm.unitid)))
     JOIN kaverimrg.bhoomimappingdetails v ON ((v.kaverimrgvillagecode = pm.villagecode)))
     JOIN kaverimrg.bhoomidistrictmaster bdm ON ((v.bhoomidistrictcode = bdm.districtcode)))
     JOIN kaverimrg.bhoomitalukmaster btm ON (((v.bhoomitalukcode = btm.talukcode) AND (v.bhoomidistrictcode = btm.districtcode))))
     JOIN kaverimrg.bhoomihoblimaster bhm ON (((v.bhoomihobicode = bhm.hoblicode) AND (v.bhoomitalukcode = bhm.talukcode) AND (v.bhoomidistrictcode = bhm.districtcode))))
     JOIN kaverimrg.bhoomivillagemaster bhv ON (((v.bhoomivillagecode = bhv.villagecode) AND (v.bhoomihobicode = bhv.hoblicode) AND (v.bhoomitalukcode = bhv.talukcode) AND (v.bhoomidistrictcode = bhv.districtcode))))
  WHERE ((dm.finalregistrationnumber IS NOT NULL) AND (dm.registrationdatetime IS NOT NULL));


ALTER TABLE kaverimrg.vw_jslip_surveynumberdetails_for_old_method OWNER TO postgres;

