--
-- Name: vw_srch_courtorders; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_srch_courtorders AS
 SELECT app_json.orderid,
    app_json.srocode,
    app_json.ordernumber,
    app_json.issuingauthority,
    app_json.issuedate,
    app_json.description AS courtdescription,
    app_json.casetype,
    app_json.iscancelled,
    app_json.isinforce,
    row_to_json(app_json.*) AS court_json
   FROM ( SELECT co.courtorderid AS orderid,
            co.ordernumber,
            co.srocode,
            co.issuingauthority,
            (co.issueddate)::date AS issuedate,
            co.description,
            co.isinforce,
            co.iscancelled,
            co.casetype,
            co.cancellationdate,
            co.cancellationremarks,
            co.username,
            co.dateofcancellation,
            ( SELECT array_to_json(array_agg(row_to_json(prpty.*))) AS array_to_json
                   FROM ( SELECT bp.courtpropertyid AS propertyid,
                            bp.isagriculturalproperty,
                            tm.districtcode,
                            bp.srocode,
                            bp.villagecode,
                            bp.jurisdictionsrcode,
                            vm.hoblicode,
                            bp.northboundary,
                            bp.southboundary,
                            bp.eastboundary,
                            bp.westboundary,
                            vm.talukcode AS talukacode,
                            bp.propertydescription,
                            bp.area,
                            bp.measurementunit,
                            bp.extentinformation AS extentdescription,
                            bp.isdelete,
                            ( SELECT array_to_json(array_agg(row_to_json(prptyno.*))) AS array_to_json
                                   FROM ( SELECT bpn.propertyid,
    bpn.srocode,
    bpn.currentpropertytypeid,
    bpn.currentnumber,
    bpn.oldnumber,
    bpn.hissa_no AS hissanumber,
    bpn.survey_no AS surveynumber,
    bpn.isdelete,
    bpn.courtpropertynumberid AS propertynumberid
   FROM (kaverimrg.bannedpropertynumbers bpn
     LEFT JOIN kaverimrg.propertynotypemaster pntm ON ((pntm.propertytypeid = bpn.currentpropertytypeid)))
  WHERE ((bpn.propertyid = bp.courtpropertyid) AND (bpn.srocode = bp.srocode) AND (COALESCE(bpn.isdelete, false) = false) AND (co.courtorderid = bpn.orderid) AND (co.srocode = bpn.srocode))) prptyno) AS propertynumbers
                           FROM ((kaverimrg.bannedproperties bp
                             LEFT JOIN kaverimrg.villagemaster_bck_12062023 vm ON ((bp.villagecode = vm.villagecode)))
                             LEFT JOIN kaverimrg.talukmaster_bck_12062023 tm ON ((vm.talukcode = tm.talukcode)))
                          WHERE ((COALESCE(bp.isdelete, false) = false) AND (co.courtorderid = bp.orderid) AND (co.srocode = bp.srocode))) prpty) AS orderproperties,
            ( SELECT array_to_json(array_agg(row_to_json(prty.*))) AS array_to_json
                   FROM ( SELECT party.courtpartyid AS partyid,
                            party.srocode,
                            party.salutation,
                            party.firstname,
                            party.middlename,
                            party.lastname,
                            party.age,
                            party.house_building_name AS housebuildingname,
                            vm.talukcode AS talukacode,
                            vm.hoblicode,
                            party.villagecode,
                            party.districtcode,
                            party.statecode,
                            party.address,
                            party.pincode,
                            party.isdelete
                           FROM ((kaverimrg.bannedparties party
                             LEFT JOIN kaverimrg.villagemaster_bck_12062023 vm ON ((party.villagecode = vm.villagecode)))
                             LEFT JOIN kaverimrg.talukmaster_bck_12062023 tm ON ((vm.talukcode = tm.talukcode)))
                          WHERE ((COALESCE(party.isdelete, false) = false) AND (co.courtorderid = party.orderid) AND (co.srocode = party.srocode))) prty) AS parties
           FROM kaverimrg.courtorders co
          WHERE (COALESCE(co.iscancelled, false) = false)) app_json;


ALTER TABLE kaverimrg.vw_srch_courtorders OWNER TO postgres;

--
-- Name: vw_srch_courtorders_backup_160223; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_srch_courtorders_backup_160223 AS
 SELECT app_json.orderid,
    app_json.srocode,
    app_json.ordernumber,
    app_json.issuingauthority,
    app_json.issuedate,
    app_json.description AS courtdescription,
    app_json.casetype,
    app_json.iscancelled,
    app_json.isinforce,
    row_to_json(app_json.*) AS court_json
   FROM ( SELECT co.courtorderid AS orderid,
            co.ordernumber,
            co.srocode,
            co.issuingauthority,
            (co.issueddate)::date AS issuedate,
            co.description,
            co.isinforce,
            co.iscancelled,
            co.casetype,
            co.cancellationdate,
            co.cancellationremarks,
            co.username,
            co.dateofcancellation,
            ( SELECT array_to_json(array_agg(row_to_json(prpty.*))) AS array_to_json
                   FROM ( SELECT bp.courtpropertyid AS propertyid,
                            bp.isagriculturalproperty,
                            tm.districtcode,
                            bp.srocode,
                            bp.villagecode,
                            bp.jurisdictionsrcode,
                            vm.hoblicode,
                            bp.northboundary,
                            bp.southboundary,
                            bp.eastboundary,
                            bp.westboundary,
                            vm.talukcode AS talukacode,
                            bp.propertydescription,
                            bp.area,
                            bp.measurementunit,
                            bp.extentinformation AS extentdescription,
                            bp.isdelete,
                            ( SELECT array_to_json(array_agg(row_to_json(prptyno.*))) AS array_to_json
                                   FROM ( SELECT bpn.propertyid,
    bpn.srocode,
    bpn.currentpropertytypeid,
    bpn.currentnumber,
    bpn.oldnumber,
    bpn.hissa_no AS hissanumber,
    bpn.survey_no AS surveynumber,
    bpn.isdelete,
    bpn.courtpropertynumberid AS propertynumberid
   FROM (kaverimrg.bannedpropertynumbers bpn
     LEFT JOIN kaverimrg.propertynotypemaster pntm ON ((pntm.propertytypeid = bpn.currentpropertytypeid)))
  WHERE ((bpn.propertyid = bp.courtpropertyid) AND (COALESCE(bpn.isdelete, false) = false) AND (co.courtorderid = bpn.orderid))) prptyno) AS propertynumbers
                           FROM ((kaverimrg.bannedproperties bp
                             LEFT JOIN kaverimrg.villagemaster_bck_12062023 vm ON ((bp.villagecode = vm.villagecode)))
                             LEFT JOIN kaverimrg.talukmaster_bck_12062023 tm ON ((vm.talukcode = tm.talukcode)))
                          WHERE ((COALESCE(bp.isdelete, false) = false) AND (co.courtorderid = bp.orderid))) prpty) AS orderproperties,
            ( SELECT array_to_json(array_agg(row_to_json(prty.*))) AS array_to_json
                   FROM ( SELECT party.courtpartyid AS partyid,
                            party.srocode,
                            party.salutation,
                            party.firstname,
                            party.middlename,
                            party.lastname,
                            party.age,
                            party.house_building_name AS housebuildingname,
                            vm.talukcode AS talukacode,
                            vm.hoblicode,
                            party.villagecode,
                            party.districtcode,
                            party.statecode,
                            party.address,
                            party.pincode,
                            party.isdelete
                           FROM ((kaverimrg.bannedparties party
                             LEFT JOIN kaverimrg.villagemaster_bck_12062023 vm ON ((party.villagecode = vm.villagecode)))
                             LEFT JOIN kaverimrg.talukmaster_bck_12062023 tm ON ((vm.talukcode = tm.talukcode)))
                          WHERE ((COALESCE(party.isdelete, false) = false) AND (co.courtorderid = party.orderid))) prty) AS parties
           FROM kaverimrg.courtorders co
          WHERE (COALESCE(co.iscancelled, false) = false)) app_json;


ALTER TABLE kaverimrg.vw_srch_courtorders_backup_160223 OWNER TO postgres;

--
-- Name: vw_sro_graphcnt; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_sro_graphcnt AS
 SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    ad.applicationnumber,
    ad.srocode,
    ad.bookid,
    bm.booknameenglish AS bookname,
    ad.applicationenddate
   FROM ((kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
     JOIN kaverimrg.booktypemaster bm ON ((ad.bookid = bm.bookid)))
  WHERE ((ad.currentstatus)::text = 'CD120'::text)
UNION ALL
 SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    ad.applicationnumber,
    ea.kaverimrgsrocode AS srocode,
    ea.booktype AS bookid,
    NULL::character varying(150) AS bookname,
    ad.applicationenddate
   FROM ((kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.cc_applicationdetails ea ON (((ad.applicationnumber)::text = (ea.applicationnumber)::text)))
     JOIN kaverimrg.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
  WHERE ((ad.currentstatus)::text = 'CC109'::text)
UNION ALL
 SELECT ad.applicationtypeid,
    sm.servicename AS applicationtypename,
    ad.applicationnumber,
    ea.kaverimrgsrocode AS srocode,
    ad.bookid,
    NULL::character varying(150) AS bookname,
    ad.applicationenddate
   FROM ((kaverimrg.applicantapplicationdetails ad
     JOIN kaverimrg.ec_applicationdetails ea ON (((ad.applicationnumber)::text = (ea.applicationnumber)::text)))
     JOIN kaverimrg.servicesmaster sm ON ((sm.serviceid = ad.applicationtypeid)))
  WHERE ((ad.currentstatus)::text = 'CE110'::text);


ALTER TABLE kaverimrg.vw_sro_graphcnt OWNER TO postgres;

