--
-- Name: vw_verifychallan; Type: VIEW; Schema: kaverimrg; Owner: postgres
--

CREATE VIEW kaverimrg.vw_verifychallan AS
 SELECT epay.officeid,
    epay.remittername AS nameoftheperson,
    ddo.ddocode,
    epay.deptreferencecode AS challannumber,
    mo.officename AS ddoofficename,
    epay.totalamount,
    epay.transactionid,
    CURRENT_TIMESTAMP AS transactiondate,
    '33029493274'::bigint AS ktc25reconcilationno
   FROM (((kaverimrg.ams_reg_khajaneresponselog khj
     JOIN ( SELECT ams_reg_epaymenttransdetails.transactionid,
            ams_reg_epaymenttransdetails.transactiondatetime,
            ams_reg_epaymenttransdetails.officeid,
            ams_reg_epaymenttransdetails.deptreferencecode,
            ams_reg_epaymenttransdetails.remittername,
            ams_reg_epaymenttransdetails.treasurycode,
            sum(ams_reg_epaymenttransdetails.totalamount) AS totalamount
           FROM kaverimrg.ams_reg_epaymenttransdetails
          GROUP BY ams_reg_epaymenttransdetails.transactionid, ams_reg_epaymenttransdetails.transactiondatetime, ams_reg_epaymenttransdetails.officeid, ams_reg_epaymenttransdetails.deptreferencecode, ams_reg_epaymenttransdetails.remittername, ams_reg_epaymenttransdetails.treasurycode) epay ON (((epay.deptreferencecode)::text = (khj.deptreferencecode)::text)))
     LEFT JOIN kaverimrg.mas_officemaster mo ON ((mo.officeid = epay.officeid)))
     LEFT JOIN kaverimrg.mas_ams_khajaneddocodemapping ddo ON ((ddo.srocode = epay.officeid)));


ALTER TABLE kaverimrg.vw_verifychallan OWNER TO postgres;

